    // compute their picks' weighted sums, and member m adds helper h's (h % nm == m) into its partial before the MoE
    // all-reduce.  One tensor-parallel group, HIP, local helpers only (pfh_setup says why not otherwise).
    int pfh_rows = 0;
    bool pfh_live = false;
    std::atomic<uint64_t> pfh_key{0};               // (the lead's: (chunk seq << 8 | layer) of the last layer issued)
    int* pfh_ids = nullptr;                         // pinned [rows][kPicks]: the lead's routing, read back
    float* pfh_w = nullptr;
    std::vector<cudaStream_t> pfh_cs;               // by device index: the x read-back's stream
    std::vector<cudaEvent_t> pfh_ev_r, pfh_ev_x;    // (routing done; x read back)
    std::vector<std::vector<const float*>> pfh_out_dev;   // [device][helper]: the helper's out rows as the device sees them
    std::vector<std::vector<const int*>> pfh_map_dev;
    std::vector<double> pfh_wait_ms;                // by device index: the host's waits for its helpers (the run's)
    int64_t pfh_layers_run = 0, pfh_layers_streamed = 0;   // (the lead's thread: layers of PF chunks on the helpers / streamed)
    int64_t pfh_layers_mixed = 0, pfh_exp_streamed = 0;    // (the lead's: helper layers that also streamed experts no helper holds)
    double pfh_xwait_ms = 0;                                // (the lead's host waits for the x read-back, the run's)
    // DS4_PF_HELPER_MIX (default on with the flag; =0: pf1's rule, a layer with one unheld CPU-lane expert streams whole): a
    // layer goes to the helpers when the helpers hold at least one of its CPU-lane experts; the ones they do not hold (the
    // expert cache moved them out of VRAM since load) are streamed to the members as before, in runs of host_list positions
    bool pfh_mix() const {
        static const bool on = std::getenv("DS4_PF_HELPER_MIX") == nullptr || std::atoi(std::getenv("DS4_PF_HELPER_MIX")) != 0;
        return on;
    }
    bool pfh_held(const Layer& L0, int e) const { return hlp.pf_owner(L0.il, e) >= 0; }
    bool pfh_layer_ok(const Layer& L0) const {
        if (!pfh_live || L0.mtp || L0.vs_pin == nullptr || L0.host_list.empty()) return false;
        bool any = false, all = true;
        for (int e : L0.host_list) {
            const bool h = pfh_held(L0, e);
            any = any || h;
            all = all && h;
        }
        return pfh_mix() ? any : all;
    }
    // DS4_PF_HELPER_MAXP=<tokens> (default unset / 0: off - every read as above).  A prompt read of more than <tokens> new
    // tokens goes the DS4_PF_HELPER=0 way for the whole read: no chunk of it on the helpers (pfh_chunk false: the planner
    // streams every CPU-lane expert, wp.pfh false) and the flag-off chunk_min for its path choice (pf3 lowers chunk_min only
    // with the helper).  Decided once a read: the server declares the read's new tokens before its feeds (set_prompt_total:
    // a read the pin splits in two keeps one decision), any other caller's feed is a read of its own (its n).  Reads of
    // <tokens> or fewer are untouched.  The served A/B behind it: PF-13 srvhelp-20261113T223615Z (helper slower from 16K)
    int pfh_maxp = 0;
    int pfh_chunk_min_off = 0;   // (chunk_min as a DS4_PF_HELPER=0 load leaves it; set by pfh_setup before pf3 lowers it)
    int pfh_read = -1;           // (the declared read: -1 none, 0 with the helper, 1 without it)
    bool pfh_skip = false;       // (the feed in progress bypasses the helper: set by Model::feed / feed_mark around the run)
    bool pfh_bypass(int64_t n) const { return pfh_live && pfh_maxp > 0 && n > (int64_t) pfh_maxp; }
    void pfh_bypass_line(int64_t n, const char* how) const {
        std::fprintf(stderr, "ds4: DS4_PF_HELPER_MAXP=%d: a prompt read of %lld new tokens (%s) without the prompt helper "
                             "(the DS4_PF_HELPER=0 path)\n", pfh_maxp, (long long) n, how);
    }
    // a feed of n tokens: whether it bypasses the helper (the declared read's decision, else its own length's)
    bool pfh_feed_skip(int n) const {
        if (!pfh_live || pfh_maxp <= 0) return false;
        if (pfh_read >= 0) return pfh_read == 1;
        const bool sk = pfh_bypass(n);
        if (sk) pfh_bypass_line(n, "one feed");
        return sk;
    }
    int feed_chunk_min(bool skip) const { return skip && pfh_chunk_min_off > 0 ? pfh_chunk_min_off : chunk_min; }
    // the one rule the planner (no batches) and the layer (the helpers) apply
    bool pfh_chunk(int T) const { return pfh_live && !pfh_skip && T >= 1 && T <= pfh_rows; }
    // the one rule the lane (arms li + 1 after li; skips the helpers on a DD request) and the lead (joins on the device) apply
    bool dd_at(int il, int T) const {
        return dd_live && il >= 1 && il < g.nl && il < (int) L.size() && !L[(size_t) il].mtp && T >= 1 && T <= dd_maxt;
    }
    // DS4_DD_AUDIT: the counters as one line (the compute thread's: l.slot is its own between windows)
    std::string dd_audit_line() const {
        long long now = 0;   // (VRAM experts still in a helper's owner table: the promotions DD never heard of)
        std::string lay;
        for (size_t li = 0; li < L.size(); ++li) {
            for (int e = 0; e < L[li].n_exp && e < dd_aud_nexp; ++e)
                now += dd_aud_own[li * (size_t) dd_aud_nexp + (size_t) e] >= 0 && L[li].slot[(size_t) e] >= 0;
            const long long n = dd_aud_layer ? dd_aud_layer[li].load(std::memory_order_relaxed) : 0;
            if (n > 0) lay += (lay.empty() ? "" : " ") + std::to_string(li) + ":" + std::to_string(n);
        }
        std::string ecl;   // DS4_ECOWN
        if (ecown) {
            unsigned long long ck = 0, bad = 0, tmo = 0;
            for (size_t di = 0; ec_chk != nullptr && di < ec_tmo.size(); ++di) {
                ck += ((const volatile unsigned long long*) ec_chk)[di * 4];
                bad += ((const volatile unsigned long long*) ec_chk)[di * 4 + 1];
                tmo += ((const volatile unsigned long long*) ec_chk)[di * 4 + 2];
            }
            char e[384];
            std::snprintf(e, sizeof e, "; DS4_ECOWN: %lld picks handed to the lead (in its VRAM), %lld zero-copy staged, %lld lane/lead table "
                          "differences; device checks %llu, mismatched picks %llu, timeouts %llu",
                          ec_handed.load(), ec_zc.load(), ec_disagree.load(), ck, bad, tmo);
            ecl = e;
        }
        char b[512];
        std::snprintf(b, sizeof b, "%lld device-direct requests, %lld picks; %lld picks computed twice (VRAM + a helper's table) in %lld requests, "
                      "%lld of them on a token with no CPU-lane pick (stale x), route weight %.3f in all; %lld skipped (helper not armed); "
                      "VRAM experts in a helper's table now %lld; swaps %lld; by layer [",
                      dd_aud_req.load(), dd_aud_picks.load(), dd_aud_dbl.load(), dd_aud_dreq.load(), dd_aud_stale.load(),
                      (double) dd_aud_wq.load() / 1e6, dd_aud_unarmed.load(), now, (long long) st.swaps);
        return std::string(b) + lay + "]" + ecl;
    }
    // the one rule the lane (which defers request li) and the device (which adds layer il - 1's rows at il) both apply
    bool defer_at(int il, int T) const {
        return helper_defer && dresps != nullptr && hlp.enabled() && il >= 0 && il < g.nl - 1 && il < (int) L.size() &&
               !L[(size_t) il].mtp && T >= 1 && T <= defer_maxt;
    }
    // lookahead: while layer L runs, the device guesses the next layer's picks (its gate on L's FFN input, the same
    // choice) and publishes them with L's routing; the CPU lane asks for the guessed experts it will read from the files
    // at once (a thread of its own, os::prefetch), so the SSD reads them while L computes instead of on the next
    // layer's critical path.  Only the page cache sees it - the outputs are the same.  DS4_AHEAD=0: off, 2: also the
    // layer after (from L's input too); DS4_AHEAD_EXTRA: guesses past the next layer's top k (< 0: fewer - the guess's
    // picks by rank on Sun: 97 91 81 70 57 41 %, past the top 6 29 20 %: reads wasted on an SSD-bound PC).
    int ahead_mode = std::getenv("DS4_AHEAD") ? std::atoi(std::getenv("DS4_AHEAD")) : 1;
    // ---- decode fusions ported from Project Maya (docs/dsv41/cards/FG-02.md; each default off, each independent, each checked
    // byte for byte at load against the launches it replaces - a difference fails the load).  A flag set to 0 allocates its
    // buffers and keeps the old path: an identity test's off arm then has the same VRAM, so the same expert placement.
    // DS4_HC_FUSE=1 (Maya #511, MAYA_DS4_HC_FUSE): a decoded token's (T 1) HC mix + split and pre-norm in one launch
    // (hc_mix_split_norm), its x rounded to int8 there for the Q8_0 / low-bit GEMVs that read it (the attention's input
    // GEMVs; the shared expert's w1 / w3), and the FFN split writing the layer's copy of its pre slots (no end-of-layer
    // copy) - 4 launches fewer a layer on every member.  =2: a window's rows too (a DSpark verify window, a
    // DS4_BATCH_DECODE window: T up to kWin).  Not the drafter's blocks.  Checked at load (hc_fuse_check) on 1 row (=2:
    // and kWin rows).  (Maya's =1 rounds only the attention's input; ours both - the check covers both)
    int hc_fuse = 0;
    bool hc_fuse_set = false;
    // FG-07 (docs/dsv41/cards/FG-07.md; each default off, checked at load like the flags here).
    // DS4_AR_POST=<bits>: a window's tensor-parallel all-reduce (both of a layer's: the attention's and the MoE's) on the
    // one-phase host path, with bit 1 the hc_post after it folded into the sum kernel, bit 2 the put (xfer_put) folded in
    // too (per-block flags; three members or more) - 1 or 2 launches fewer an all-reduce on every member.  Trunk layers,
    // T <= kWin.  The same sums (the member-order __fadd_rn chain) and hc_post's per-element code: the same bits.
    int ar_post = 0;
    // DS4_ATTN_MERGE=1: a decoded token's (T 1; =2: T <= kWin) independent attention launches as one launch each -
    // {q's low-rank norm, the ring's rows into ext, the KV row's finish} after the input GEMVs, then {q's RoPE finish, the
    // KV row into the ring} after wq_b - 5 launches become 2 on every member.  Each block runs its op's kernel body: the
    // same bits.  Trunk layers, no DS4_DUMP_*.  =3 (FG-16 item 3): =2, and sparse_attn's
    // unpack of each query's selected compressed rows (unpack_sel_kernel) as blocks of the second launch where its inputs are
    // final there - a layer without its own indexer (ix_src: its top-k comes later) and not a window that completes one of
    // its own compressed rows (kv_src with a group done: that row is written later).  The same code a block: the same bits
    int attn_merge = 0;
    std::atomic<bool> am3_warned{false};   // (DS4_ATTN_MERGE=3: the "arguments differ" line, once)
    // DS4_BT_FUSE=1 (fusion plan F2 "bt parity", docs/dsv41/cards/FG-16.md item 2; default off: the batch path as before).
    // A batch window's attention (attn_batch: DS4_BATCH_DECODE's steps, the server's PAR >= 2) takes the solo path's launch
    // fusions that are set: DS4_AR_POST's all-reduce with hc_post folded (ar_then_post); DS4_ATTN_MERGE's two merged launches
    // over DS4_MULTI_ATTN's runs - {q's norm [+ int8], the runs' rings into the shared buffer, the KV rows' finish} after the
    // input GEMVs, {q's RoPE at each row's position, the runs' new rows into their rings [+ backups]} after wq_b, and with =3
    // the rows' unpack of their selected compressed rows in the second where it is final there (no indexer of the layer's
    // own, no run completing a compressed row of its own); DS4_XK_QO's o finish rounding wo_a's int8 input for the T rows
    // (bt_fin_kernel's int8 rows in mv's layout, gguf PreQ8 rows > 1).  The per-run path (DS4_MULTI_ATTN refused) keeps its
    // launches but the all-reduce's.  Every block runs its kernel's code: each row's bytes the unfused batch path's (load
    // check bt_fuse_check at 2 and kWin rows).  HIP gfx1100 layer devices
    int bt_fuse = 0;
    std::atomic<bool> btf_warned{false};   // (the "arguments differ" line, once)
    std::atomic<unsigned> btf_seen{0};     // (bits: the parts that have engaged - a line the first time each does)
    // DS4_ROUTE_FUSE=1 (Maya #511, MAYA_DS4_ROUTE_FUSE): a decoded token's (T 1) router stage on a group's lead, with one
    // layer of lookahead (DS4_AHEAD 1, the default) and a next layer to guess: this layer's gate and the next layer's
    // lookahead gate in one launch (gemv_f32_pair), the routing and the guesses in another (route_pair), the publish as
    // before - 4 launches become 2, on the lead only (the members' routing and plan as before).  =2: a window's rows too.
    // Every other case (no guess, the members, the drafter, DS4_AHEAD 0) keeps the old launches; DS4_AHEAD=2 is refused.
    // The request record (Req) the CPU lane and the MI50 helpers read is written with the same bytes, then published as
    // before.  Checked at load (route_fuse_check) on 1 row (=2: and 3 and kWin rows)
    int route_fuse = 0;
    // leadpath (docs/dsv41/cards/HX-21.md; each default off, each exact by construction): DS4_LP_ROUTE=1 the routing's top
    // k per warp then merged (route_publish_lp: the old picks in the old order, the old rounds when a score is NaN or the
    // picks reach -FLT_MAX), DS4_LP_PUBFUSE=1 a one-row request published by the routing's launch (no publish_kernel launch) -
    // both on route_publish's calls (every member; the lead's DS4_ROUTE_FUSE pair path is left as it is, so on the lead they
    // need DS4_AHEAD=0), checked at load (lp_route_check); DS4_LP_JOINCOMB=1 the lead's DD join and combine in one launch
    bool lp_route = false, lp_pubfuse = false, lp_joincomb = false;
    // helperwin (docs/dsv41/cards/HX-22.md; default off; exact by construction, checked at load): DS4_HW_PUBT=1 (with
    // DS4_LP_PUBFUSE=1) - a window of T > 1 rows is published by its routing launch's last block too (a device word a layer
    // device, allocated after every buffer and expert is placed, so the VRAM placement is the flag-off one's), not by a
    // publish_kernel launch after it.  lp_route_check's 3- and kWin-row runs then cover it
    bool hw_pubt = false;
    std::vector<unsigned*> hw_pub_cnt;   // by device index (empty: off)
    unsigned* pub_cnt_of(int dev) const { return hw_pub_cnt.empty() ? nullptr : hw_pub_cnt[(size_t) dev]; }
    bool hw_pubt_setup(std::string& err) {
        const char* v = std::getenv("DS4_HW_PUBT");
        hw_pubt = v != nullptr && std::atoi(v) == 1;
        if (!hw_pubt) return true;
        if (!lp_pubfuse) {
            std::fprintf(stderr, "ds4: helperwin: DS4_HW_PUBT=1 needs DS4_LP_PUBFUSE=1: off\n");
            hw_pubt = false;
            return true;
        }
        hw_pub_cnt.assign(devs.size(), nullptr);
        for (size_t di = 0; di < devs.size(); ++di) {
            cudaSetDevice(devs[di].id);
            if (cudaMalloc((void**) &hw_pub_cnt[di], sizeof(unsigned)) != cudaSuccess ||
                cudaMemset(hw_pub_cnt[di], 0, sizeof(unsigned)) != cudaSuccess || cudaDeviceSynchronize() != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_HW_PUBT: the counter on CUDA" + std::to_string(devs[di].id);
                return false;
            }
        }
        std::fprintf(stderr, "ds4: helperwin: DS4_HW_PUBT=1: a window of up to %d rows published by its routing launch's last block "
                             "(checked at load with DS4_LP_PUBFUSE)\n", kWin);
        return true;
    }
    // DS4_ROUTER_BF16=1 (Maya #745, MAYA_DS4_ROUTER_BF16 - Maya's AMD default; ours off by default): a BF16 router (the
    // pack-2.25 GGUF holds every trunk router in BF16; the drafter's are F32 and stay so) stays BF16 on the device -
    // 3.9 MB a read instead of 7.9, ~150 MiB of VRAM a tp3 member freed for experts.  The logits are the F32 copy's bits
    // (router_check at load, on unless DS4_ROUTER_CHECK=0); the freed VRAM moves the expert placement, so a decode's tokens
    // can differ through the experts that moved (the CPU lane's and the GPU's sums differ) - DS4_ROUTER_BF16_PAD=1 keeps
    // the placement (identity tests).  Every gemv_f32 on the router: decode, windows, the prompt's chunks
    int router_bf16 = 0, router_bf16_n = 0;
    bool router_pad = false, router_chk = true;
    // DS4_DECODE_TRIM=<bits> (Maya #512, MAYA_DS4_DECODE_TRIM; unset / 0: as before) - small exact trims of a decoded
    // window, each checked at load: 1 the shared expert's swiglu rounds its output to int8 for its down GEMV s2
    // (swiglu_q8 + PreQ8); 2 q's low-rank norm rounds it for wq_b (Finish::q8 + PreQ8) - one int8 rounding launch fewer a
    // layer each, on every member, at any T up to kWin; 4 a ratio-1 layer's latent copy and a verify window's compressor
    // snapshot (4 copies) one kernel each (copy_regions).  Maya's bit 8 (the drafter's hand-offs between its cards) is not
    // ported: our drafter's blocks share one card.  Not the drafter's blocks (bits 1 / 2: trunk layers only)
    int decode_trim = 0;
    bool decode_trim_set = false;
    // DS4_EG_SPLIT=1 (SV-09; unset / 0: as before): a decoded token's (T = 1) Engram GEMV (engram.wkv,
    // 25600 x 6144 Q5_K, ~108 MB a layer, read whole by every tensor-parallel member: ~129 us on each XTX) split by its
    // output rows over the group - member m computes rows [m N / nm, (m + 1) N / nm) into a vector of -0.0, then the
    // group's decode all-reduce (in member order) gathers the rows.  Bit-identical by construction: ds4_iq's mv_kernel
    // computes each row in one warp whatever the job's row count (gg::view only moves the base), and -0.0 is the exact
    // identity of IEEE addition (x + -0 = -0 + x = x for every x, the zeros' signs too).  Windows of T > 1 (verify,
    // prompts) as before.  Set (=0 too): eg_nz allocated, so an identity test's off arm has the same VRAM
    int eg_split = 0;
    bool eg_split_set = false;
    // DS4_EG_AHEAD=1 (FG-09, docs/dsv41/cards/FG-09.md; unset / 0: as before): an Engram layer's chain (the rows' H2D,
    // dequant, q8 + GEMV), whose inputs are token ids only, enqueued on a per-device side stream one Engram trigger earlier
    // - the first Engram layer's at the previous layer's FFN start (after its attention is enqueued), each later one's at
    // the previous Engram layer's FFN start - into its own buffers; the main stream waits on its event right before
    // engram_gate.  The same kernels on the same inputs, so bit-identical by construction.  With DS4_EG_SPLIT active
    // (T = 1, nm > 1) the side stream computes the member's slice into its -0.0 rows and the all-gather stays on the
    // main stream, at the same place in the all-reduce sequence (two streams must not interleave a group's ARs).  A
    // layer the device holds without its trigger layer, or a window that did not prefetch it: the old path.  Set (=0
    // too): the side stream, its gguf scratch and the buffers made, so an identity test's off arm has the same VRAM
    int eg_ahead = 0;
    bool eg_ahead_set = false;
    std::vector<int> eg_ah_trig;          // [engram index]: the layer whose FFN start enqueues it (-1: none)
    uint64_t eg_ah_win = 0;               // the window being enqueued (forward_par / forward_serial: +1 each)
    std::atomic<int> eg_ah_said{0};       // (the one-time "engaged" line)
    std::atomic<long long> eg_ah_used{0}, eg_ah_old{0};   // Engram layers that took the prefetch / the old path
    // DS4_TOPK_MB=1 (FG-10; unset / 0: as before): the decode path's indexer top-k (topk, and cand_blocks' top-k
    // of the blocks) over a widest row of n >= DS4_TOPK_MB_MIN scores (default 8192, ~32K tokens at ratio 4) runs on up
    // to 64 workgroups a row (topk_mb: three histogram levels, the k-th key, the picks in index order) instead of one;
    // the same selection rule - the k-th largest key, every key above it, the ties kept the lowest positions, written in
    // index order - so the same out bits (checked at load against the one-workgroup kernel).  Prompt chunks (device-made
    // sizes) as before.  Set (=0 too): each layer device's d.tmb allocated, so an identity test's off arm has the same VRAM
    int topk_mb = 0;
    bool topk_mb_set = false;
    int topk_mb_min = 8192;
    // xtxkern (docs/dsv41/cards/FG-08.md; default off, bit-identical by construction, gfx1100 layer devices only;
    // build 14 takes DS4_XK_QO alone of xtxkern's seven flags):
    // (item 4, the 120-a-token roundings; each exact by construction: q8_quant's ops on the same stored values)
    // DS4_XK_QO=1 the o finish also rounds the heads to int8, wo_a's groups read it (needs DS4_HC_FUSE set: its int8 rows);
    int xk_qo = 0;
    // (FG-16) DS4_XK_QA=1 wo_a's GEMV (Q5_K) rounds its outputs to int8 as it stores them, wo_b reads it (as QO; T 1 only;
    // FG-08's QA's fmaf-fixed form, exact in its bench; needs DS4_HC_FUSE set)
    int xk_qa = 0;
    // DS4_TOPK_MB_BATCH=1 (FG-11; unset / 0: as before): with DS4_TOPK_MB=1, the batch windows' indexer
    // top-k (bt_run_sel: a bank's run of rows, its topk and cand_blocks' top-k) takes DS4_TOPK_MB's multi-block path too, by the
    // same rule (n >= DS4_TOPK_MB_MIN, r.gen == 0, rows <= kWin): the same k-th key, ties to the lowest positions, picks in
    // index order - the same bits as the one-workgroup kernel.  A run's rows use d.tmb's rows 0 .. n-1 on d.st, a run at a
    // time (as the solo window); the scratch is left zero, so runs and solo windows can follow each other.  Needs DS4_TOPK_MB=1.
    int topk_mb_batch = 0;
    bool topk_mb_batch_set = false;
    std::atomic<int> tmb_bt_said{0};   // (the one-time "engaged" line)
    int ahead_extra = std::getenv("DS4_AHEAD_EXTRA") ? std::atoi(std::getenv("DS4_AHEAD_EXTRA")) : 0;
    // (DS4_AHEAD_ORDER=0: the CPU lane computes a layer's experts in expert order, not the ones asked for early first)
    bool ahead_order = std::getenv("DS4_AHEAD_ORDER") == nullptr || std::atoi(std::getenv("DS4_AHEAD_ORDER")) != 0;
    std::vector<uint8_t> ahead_fl;     // [layer][1024]: 1 the top-k guess, 2 any guess, a layer before; 4 two layers before;
                                       // 8 asked for (prefetch)
    std::vector<uint8_t> ahead_rank;   // [layer][1024]: 1 + the expert's rank in the guess a layer before (0: not guessed)
    std::vector<unsigned> ahead_for;   // [layer]: the request (seq) its flags are for
    std::thread pf_th;
    std::mutex pf_mu;
    std::condition_variable pf_cv;
    std::vector<std::pair<const void*, size_t>> pf_q;
    // the expert cache: swaps prepared on threads of their own (DS4_CACHE_THREADS, 1 by default - 4 measured no faster
    // on one V100 - more for a PC to try: each its staging buffers and
    // copy streams), switched between windows
    struct Swap {
        int layer = 0, in = -1, out = -1;
        int ram = -1;   // (copy_mode, `in` held in RAM) the spare slot `out` is copied into from VRAM
    };
    static constexpr int kMaxSwaps = 8;
    // the swap rule: a CPU-lane expert in when its heat passes the coldest VRAM one's x margin + bonus; heat x decay
    // every 256 tokens; at most `inflight` swaps under way (DS4_CACHE_MARGIN / _BONUS / _DECAY / _INFLIGHT)
    static float env_f(const char* k, float d) { return std::getenv(k) ? (float) std::atof(std::getenv(k)) : d; }
    const float c_margin = env_f("DS4_CACHE_MARGIN", 1.25f), c_bonus = env_f("DS4_CACHE_BONUS", 1.0f),
                c_decay = env_f("DS4_CACHE_DECAY", 0.9f);
    const int c_inflight = std::max(1, (int) env_f("DS4_CACHE_INFLIGHT", (float) kMaxSwaps));
    // DS4_EC_FIX=1 (default unset / 0: off - every swap as before): the expert cache never picks a helper-held expert to
    // swap into VRAM (cache_tick_swaps leaves them out of `best` and of the RAM tier's `rb`), whoever filled cpu_hits.  The
    // windows' lane and the settle rounds already leave them out of cpu_hits; the chunked prompt path does not (it adds every
    // non-VRAM pick), so with it off each prompt read swaps up to c_inflight (8) of the hottest helper-held experts into VRAM and
    // evicts that many cold VRAM experts no helper holds: those stream from host RAM in every later prompt chunk (HX-26
    // cleak-20261114T005644Z: +8 "unheld" a prompt, +13.9 % 2K TTFT after 50 prompts), and the helpers' device-direct owner
    // tables (fixed at load) still list the promoted ones (see helper_dd's note: "it never swaps in a helper's expert")
    const bool ec_fix = std::getenv("DS4_EC_FIX") != nullptr && std::atoi(std::getenv("DS4_EC_FIX")) == 1;
    int64_t ec_left = 0;   // (DS4_EC_FIX: helper-held cache hits left out of the swaps, the process's)
    // DS4_ECOWN=1 (default unset / 0: off - build 16 as it was): the swaps as before (a helper-held expert may be promoted
    // into VRAM), and each such pick is computed exactly once - by the lead.  The routing that publishes a request also
    // publishes, per token, which of its picks the publishing device holds in VRAM (Req::vmask, from the same vram_tab read
    // as its plan); the helpers' device-direct heads leave a marked pick out of their plan, and the lead's join does not wait
    // for a helper whose picks are all marked.  Refused with DS4_EC_FIX=1 (two answers to one question).
    const bool ecown = std::getenv("DS4_ECOWN") != nullptr && std::atoi(std::getenv("DS4_ECOWN")) == 1;
    std::atomic<long long> ec_handed{0}, ec_disagree{0}, ec_zc{0};   // (DS4_DD_AUDIT under ECOWN: the lane's counts)
    // DS4_CACHE_DET=1 / DS4_CACHE_FREEZE=<n> (TEST ONLY, default unset / 0: off - the cache as it was; for ECOWN's batch-vs-
    // solo gate, where a placement that lands on a timer could differ between two runs for that reason alone).  DET: each tick
    // first waits until every queued move has finished and lands them all (not just the ones ready), and the prompt's settle
    // runs rounds (up to 64) instead of DS4_SETTLE_MS; the idle settle is off.  FREEZE=n: after the n-th prompt read's settle
    // every queued move is waited for and landed, then no move is queued again (the placement fixed for the process's rest).
    const bool c_det = std::getenv("DS4_CACHE_DET") != nullptr && std::atoi(std::getenv("DS4_CACHE_DET")) == 1;
    const int c_freeze = std::getenv("DS4_CACHE_FREEZE") != nullptr ? std::max(0, std::atoi(std::getenv("DS4_CACHE_FREEZE"))) : 0;
    int c_reads = 0;          // (prompt reads settled so far)
    bool c_frozen = false;
    // (DET / FREEZE: block until the movers have finished every queued move - each always reports back, failed or not)
    void cache_drain() {
        const double t0 = now_ms();
        for (;;) {
            {
                std::lock_guard<std::mutex> lk(sw_mu);
                if ((int) sw_ready.size() >= sw_inflight && (int) ram_ready.size() >= ram_inflight) return;
            }
            if (now_ms() - t0 > 120000.0) {
                std::fprintf(stderr, "ds4: DS4_CACHE_DET: moves still in flight after 120 s (%d VRAM, %d RAM): landing what is ready\n",
                             sw_inflight, ram_inflight);
                return;
            }
            std::this_thread::sleep_for(std::chrono::microseconds(200));
        }
    }
    unsigned long long* ec_chk = nullptr;     // (DS4_DD_AUDIT under ECOWN: host-mapped [devices x 4], ecown_chk_k's counters)
    std::vector<unsigned long long> ec_tmo;   // (by device index: ecown_chk_k's timeout, wall-clock ticks)
    // the RAM tier (a GGUF's in-place experts, as GLM's: the hottest in VRAM, the next hottest here, the coldest in the
    // files): RAM slots of one expert blob each, filled at load with the hottest experts VRAM does not hold, so the
    // CPU lane reads them from RAM; between windows (cache_tick) a hotter expert from the files takes the place of the
    // layer's coldest held one - read into a free slot by ram_th, switched while nothing reads them.  Opt-in
    // (STRATA_DS4_RAM_TIER=1): on a V100 with 64 GB of RAM it was slower than the page cache alone (1.4 against 2.2-2.4
    // tokens/s sampled) - the cache follows a conversation's experts at once, the tier's moves lag behind.
    struct RamSwap {
        int layer = 0, in = -1, out = -1, slot = -1;
    };
    std::vector<uint8_t*> ram_slots, ram_chunks;
    std::vector<size_t> ram_chunk_bytes;
    bool ram_pinned = false;   // the slots are pinned memory (the prompt path DMAs them from where they lie)
    // DS4_TP_DIRECT: the pinned copy's ranges (sorted by base) and each one's device address by device id (0: not yet
    // looked up), [range * 16 + id]
    std::vector<std::pair<uintptr_t, size_t>> pin_ranges;
    mutable std::unique_ptr<std::atomic<uintptr_t>[]> pin_dev;
    size_t flow_part[3] = {0, 0, 0};   // the flow's staging room for each part: its largest over the trunk's layers
    std::vector<int> ram_free;
    std::deque<RamSwap> ram_queue;
    std::vector<RamSwap> ram_ready;
    std::condition_variable ram_cv;
    std::thread ram_th;
    int ram_inflight = 0, ram_held = 0;
    bool ram_tier = std::getenv("STRATA_DS4_RAM_TIER") != nullptr && std::atoi(std::getenv("STRATA_DS4_RAM_TIER")) != 0;
    // STRATA_DS4_DISK_SKIP_W (experimental opt-in, CHANGES THE ANSWERS; 0 = off): on the small windows (decode, a
    // draft's check - never the prompt path) the CPU lane leaves out a routed expert whose share of its token's route
    // weights is below this and whose pages are not in RAM now (the page cache or the RAM tier; os::in_ram - Linux every
    // page, Windows sampled pages of the working set), so a token waits on the SSD only for the experts that weigh; the
    // weight it carried is lost (no renormalisation).  On layers from STRATA_DS4_DISK_SKIP_FROM (0) on.  An expert left
    // out still counts as used (the expert cache, the profile).
    const float disk_skip_w = [] {
        const char* v = std::getenv("STRATA_DS4_DISK_SKIP_W");
        return v != nullptr ? std::max(0.0f, (float) std::atof(v)) : 0.0f;
    }();
    const int disk_skip_from = [] {
        const char* v = std::getenv("STRATA_DS4_DISK_SKIP_FROM");
        return v != nullptr ? std::max(0, std::atoi(v)) : 0;
    }();
    // the RAM store (--ssd-cache): the CPU lane's experts in slots a policy owns, read unbuffered (null: off)
    std::unique_ptr<ExpertStore> store;
    uint8_t* zc_stage_buf = nullptr;   // device: k staging slots for the store's experts of a decode token
    size_t zc_stride = 0;
    bool zc_copy = true;               // DS4_STORE_STAGE=0: the expert kernels read the arena over PCIe themselves
    bool in_ram(const Layer& l, int e) const {   // (DISK_SKIP_W) expert e's pages in RAM now
        if (!l.ram.empty() && l.ram[(size_t) e] >= 0) return true;
        if (l.lay.fmt == gg::kFmtMXFP4) {
            for (int r = 0; r < 3; ++r)
                if (!os::in_ram(mx_mat(l, e, r), mx_part_bytes(l, r))) return false;
            return true;
        }
        return !file_experts || os::in_ram(file_part(l, e), l.blob);
    }
    // a GGUF's CPU-lane experts copied into RAM (copy_experts, after VRAM took its share: --mmap-experts off - auto reads
    // them in place; DS4_COPY_GB=<n>: the hottest n GB, the rest in place - static, no moves between
    // them): RAM slots (l.ram, as the tier's) of NH parts, part X on NUMA node X with rows [X n / NH, (X + 1) n / NH) of
    // each matrix at cp_lay[layer][r] - whole rows, so the split never cuts a GGUF block (MXFP4's 32, the IQ / K types'
    // 256 values: blocks run along a row); one spare slot a layer for the cache's swaps (the expert VRAM gives back takes
    // the RAM place of the one it takes in)
    // Windows' commit on an integrated GPU: its allocations are charged to the commit (RAM + page file) like any private
    // memory - measured on a Radeon 8065S with 160 GiB of its own: the system's free commit fell by each one, whatever
    // its size (one above ~3 GiB also counts as the process's private bytes, a smaller one does not, the commit the
    // same), so a page file at least the GPU's share is what lets it hold experts at all.  The experts it holds
    // (place_experts) and the copies stay within what Windows can still commit, less max(8 GB, 10% of the RAM) for the
    // other programs - commit_kept: the experts that kept off the GPU, pagefile_hint: the page file (GB) that would hold
    // them (the log's WARNING, a NOTE and INFO for the server)
    double commit_kept = 0, pagefile_hint = 0;
    double commit_margin() const {
        const os::Commit c = os::commit();
        return std::max(8.0 * (double) (1ull << 30), c.ram == ~uint64_t{0} ? 0.0 : 0.1 * (double) c.ram);
    }
    // what may still be committed beside the margin (~inf: nothing limits it; DS4_COMMIT_CAP_GB: at most that, tests)
    double commit_room() const {
        const os::Commit c = os::commit();
        double avail = c.avail == ~uint64_t{0} ? 1e300 : (double) c.avail;
        if (const char* v = std::getenv("DS4_COMMIT_CAP_GB")) avail = std::min(avail, std::atof(v) * 1e9);
        return avail >= 1e300 ? 1e300 : std::max(0.0, avail - commit_margin());
    }
    // a device whose allocations Windows charges to the commit: an integrated GPU (DS4_COMMIT_CAP_GB: any, tests)
    bool commit_charged(const Dev& d) const {
        if (std::getenv("DS4_COMMIT_CAP_GB") != nullptr) return true;
#if defined(_WIN32)
        int v = 0;
        if (cudaDeviceGetAttribute(&v, cudaDevAttrIntegrated, d.id) != cudaSuccess) {
            (void) cudaGetLastError();
            return false;
        }
        return v != 0;
#else
        (void) d;
        return false;
#endif
    }
    bool copy_mode = false;
    std::vector<std::array<uint8_t*, 2>> ram_part;   // slot -> its parts
    std::vector<std::array<size_t, 4>> cp_lay;       // layer -> part offsets of gate, up, down rows; a part's bytes
    std::vector<int> copy_spare;                      // layer -> its spare slot (-1: none)
    // STRATA_DS4_SHARED_STORE: copy_mode's slots are views into one read-only mapping shared with the other engines (ram_part[
    // shared_slot0[il] + e] is expert e of layer il, every expert has its slot); no spare slot, nothing is ever written
    std::unique_ptr<strata::ds4::SharedStore> shared_store;
    std::vector<int> shared_slot0;                    // layer -> its first slot in ram_part (-1: the layer is not in the store)
    // the expert cache's spare host parts made resident at load (default), not by the first swap mid-decode (DS4_PREFAULT_SPARE=0)
    static bool prefault_spares() {
        const char* v = std::getenv("DS4_PREFAULT_SPARE");
        return !(v != nullptr && std::atoi(v) == 0);
    }
    std::mutex sw_mu;
    std::condition_variable sw_cv;
    std::deque<Swap> sw_queue;
    std::vector<Swap> sw_ready;
    struct SwapBufs {
        uint8_t *a = nullptr, *b = nullptr, *h = nullptr;
        std::vector<cudaStream_t> st;   // a copy stream a device
    };
    std::vector<SwapBufs> sw_bufs;
    std::vector<std::thread> cache_ths;
    int sw_inflight = 0;
    int64_t decay_tokens = 0;
    bool check_swaps = std::getenv("DS4_CHECK_SWAPS") != nullptr;
    std::vector<float> host_logits;
    std::vector<void*> host_allocs;
    std::FILE* dump_h = std::getenv("DS4_DUMP_H") ? std::fopen(std::getenv("DS4_DUMP_H"), "wb") : nullptr;
    // DS4_DUMP_L: (threads) every layer's residual streams as records [layer, p0, T, T x hc x dim floats], window or
    // chunk path (tests: where the two part)
    std::FILE* dump_l = std::getenv("DS4_DUMP_L") ? std::fopen(std::getenv("DS4_DUMP_L"), "wb") : nullptr;
    // DS4_DUMP_S: the sub-steps inside the layers named by DS4_DUMP_S_LAYERS (default 0,1,2,3), records
    // [char name[16], int64 il, p0, T, nbytes][nbytes raw bytes] (window path, the same on CUDA and Metal)
    std::FILE* dump_s = std::getenv("DS4_DUMP_S") ? std::fopen(std::getenv("DS4_DUMP_S"), "wb") : nullptr;
    std::vector<int> dump_s_layers = [] {
        std::vector<int> v;
        const char* e = std::getenv("DS4_DUMP_S_LAYERS");
        std::string str = e ? e : "0,1,2,3";
        size_t a = 0;
        while (a < str.size()) {
            size_t b = str.find(',', a);
            if (b == std::string::npos) b = str.size();
            if (b > a) v.push_back(std::atoi(str.substr(a, b - a).c_str()));
            a = b + 1;
        }
        return v;
    }();
    // DS4_DUMP_R: the chunk path's routing, a record a layer [layer, p0, T, k, n_exp, n_vs, n_slots, kPicks] (int64),
    // then the picks' experts [T kPicks] (the first k of each token's), each expert's virtual slot [n_exp], the
    // slots' row bounds [n_vs + 1], the sorted rows' tokens [T k] (int32), the gate's logits [T n_exp] and its bias
    // [n_exp] (F32)
    std::FILE* dump_r = std::getenv("DS4_DUMP_R") ? std::fopen(std::getenv("DS4_DUMP_R"), "wb") : nullptr;
    // DS4_DUMP_Y=<layer>:<file> (layer -1: every layer): its expert sets on the chunk path, a record a piece [layer,
    // row0, rows, n_exp, wbase kind (0 VRAM, 1 ring), max_rows] (int64), its bounds [n_exp + 1], its h rows [rows ff]
    // (F16) and y rows [rows dim] (F32)
    int dump_y_layer = std::getenv("DS4_DUMP_Y") ? std::atoi(std::getenv("DS4_DUMP_Y")) : -1;
    std::FILE* dump_y = [] {
        const char* v = std::getenv("DS4_DUMP_Y");
        const char* f = v != nullptr ? std::strchr(v, ':') : nullptr;
        return f != nullptr ? std::fopen(f + 1, "wb") : nullptr;
    }();
    std::mutex dump_mu;
    // DS4_PROF: the GPU's time a decoded token by stage - events in stream order at a layer's start, after its
    // attention, after the routing and the shared expert, after the experts' gate / up, after the wait for the CPU
    // lane, after the down pass and the post - read after the token's sync, each the time since the mark before it
    bool prof_on = std::getenv("DS4_PROF") != nullptr;
    // DS4_PRED_DUMP=file (predictor data, the chunked prompt path): per layer and chunk u8 layer, u16 T, T x 384 fp16 router
    // logits, T x 256 fp16 projection of the router input.  DS4_XIN_DUMP=file (expert similarity inputs): u8 layer, u16 T,
    // T x D fp32 router inputs, the first DS4_XIN_N (1024) tokens of each layer.
    std::FILE* pred_f = std::getenv("DS4_PRED_DUMP") != nullptr ? std::fopen(std::getenv("DS4_PRED_DUMP"), "wb") : nullptr;
    std::FILE* xin_f = std::getenv("DS4_XIN_DUMP") != nullptr ? std::fopen(std::getenv("DS4_XIN_DUMP"), "wb") : nullptr;
    int xin_n = std::getenv("DS4_XIN_N") ? std::atoi(std::getenv("DS4_XIN_N")) : 1024;
    std::array<int, 64> xin_got{};
    std::FILE* trace_f = std::getenv("DS4_TRACE") != nullptr ? std::fopen(std::getenv("DS4_TRACE"), "wb") : nullptr;
    struct ProfMark {
        const Dev* d;
        cudaEvent_t ev;
        int stage;
    };
    std::mutex prof_mu;
    std::vector<ProfMark> prof_marks;
    std::map<int, std::vector<cudaEvent_t>> prof_pool;   // by device: an event belongs to the device it was made on
    bool prof_window = false;   // (decode windows only: T == 1)
    const bool prof_sync_on = std::getenv("DS4_PROF_SYNC") != nullptr;
    double prof_sync_t = 0;     // DS4_PROF_SYNC: the host clock at the last mark
    // ... and a run of chunks' (prof_chunk): a layer's start, after its attention, after the routing and the shared
    // expert, after its experts (the streamed ones' waits for their reads in it); printed after the run
    bool prof_chunk = false;
    // DS4_PROF stages of the chunked prompt (finer ones than the decode's 0..5): 0 between layers, 1 attention rest (wq_b, wo,
    // hc_post), 2 router-side tail (shared expert), 3 experts (+ waits), 4 Engram, 5 attn mHC (mix, split, norm), 6 attention
    // projections (wq_a, wkv, compressor), 7 compressor + indexer, 8 q_b + rope, 9 sparse attention, 10 ffn mHC + router + sort
    // (tensor parallel: 11 the attention's all-reduce, 12 the MoE's, both with the wait for the slowest member; 13 the
    // streamed experts' batches with the waits for their copies, 3 then the VRAM experts alone; 14 the GPU idle while the
    // host read the bounds back)
    double cprof_ms[16] = {};
    double cprof_dev[16][16] = {};   // (the same by device id)
    // DS4_PROF: the experts' kernels alone, by type (events around the gate/up and down calls of run_set)
    struct EkMark {
        cudaEvent_t e0, e1, e2;
        int tg, td, nrows, nexp, maxrows, dev, ff;
    };
    std::vector<EkMark> ek_marks;
    std::map<int, std::vector<cudaEvent_t>> ek_pool;   // by device
    cudaEvent_t ek_ev() {
        int cur = 0;
        cudaGetDevice(&cur);
        std::vector<cudaEvent_t>& pl = ek_pool[cur];
        if (!pl.empty()) {
            cudaEvent_t e = pl.back();
            pl.pop_back();
            return e;
        }
        cudaEvent_t e = nullptr;
        cudaEventCreate(&e);
        return e;
    }
    void prof_mark(const Dev& d, int stage) {
        if (ds4_dbg("DS4_TLOG")) {   // the host's own phase times (what the GPU meters do not see)
            static double t_last = 0, acc[5] = {0, 0, 0, 0, 0}; static long n = 0; static bool reg = false;
            if (!reg) {
                reg = true;
                std::atexit([] {
                    std::fprintf(stderr,
                                 "tlog: %ld layers | host ms: attn %.0f  moe_pre %.0f  gate_up %.0f  cpu_wait %.0f  down+post %.0f\n",
                                 n, acc[0], acc[1], acc[2], acc[3], acc[4]);
                });
            }
            const double t = now_ms();
            if (t_last > 0) {
                const int b = stage == 0 ? 4 : stage - 1;
                acc[b >= 0 && b < 5 ? b : 4] += t - t_last;
            }
            t_last = t;
            if (stage == 3) ++n;
        }
        if (!prof_window && !prof_chunk) return;
        if (prof_window && !prof_chunk && prof_sync_on) {   // decode: the stream drained at each mark, host clock (events hang the driver on gfx1151 Windows)
            std::lock_guard<std::mutex> lk(prof_mu);
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
            const double t = now_ms();
            if (prof_sync_t > 0 && stage >= 0 && stage < 6) st.prof_ms[stage] += t - prof_sync_t;
            prof_sync_t = now_ms();
            return;
        }
        std::lock_guard<std::mutex> lk(prof_mu);
        int cur = 0;
        cudaGetDevice(&cur);
        cudaSetDevice(d.id);   // (events of another device are an "invalid resource handle")
        cudaEvent_t e = nullptr;
        std::vector<cudaEvent_t>& pool = prof_pool[d.id];
        if (pool.empty()) cudaEventCreate(&e);
        else {
            e = pool.back();
            pool.pop_back();
        }
        cudaEventRecord(e, d.st);
        cudaSetDevice(cur);
        prof_marks.push_back({&d, e, stage});
    }
    void prof_collect() {
        if (!prof_window && !prof_chunk) return;
        if (prof_window && !prof_chunk && prof_sync_on) {
            std::lock_guard<std::mutex> lk(prof_mu);
            prof_sync_t = 0;
            ++st.prof_tokens;
            return;
        }
        std::lock_guard<std::mutex> lk(prof_mu);
        std::vector<std::pair<const Dev*, cudaEvent_t>> last;
        for (const ProfMark& m : prof_marks) {
            auto it = std::find_if(last.begin(), last.end(), [&](const auto& x) { return x.first == m.d; });
            if (it != last.end()) {
                float ms = 0.0f;
                cudaSetDevice(m.d->id);
                if (cudaEventElapsedTime(&ms, it->second, m.ev) == cudaSuccess) {
                    (prof_chunk ? cprof_ms : st.prof_ms)[m.stage] += ms;
                    if (prof_chunk && m.d->id >= 0 && m.d->id < 16) cprof_dev[m.d->id][m.stage] += ms;
                }
                it->second = m.ev;
            } else {
                last.push_back({m.d, m.ev});
            }
        }
        for (const ProfMark& m : prof_marks) prof_pool[m.d->id].push_back(m.ev);
        prof_marks.clear();
        if (!prof_chunk) ++st.prof_tokens;
    }
    void dump_layer(Dev& d, const float* h, int il, int64_t p0, int T) {
        std::vector<float> v((size_t) T * g.hc * g.dim);
        cudaSetDevice(d.id);
#if defined(STRATA_METAL)
        ds4_metal_flush();   // (the residual stream is read back here: commit the batched dispatches first)
        cudaDeviceSynchronize();
#endif
        cudaMemcpyAsync(v.data(), h, v.size() * 4, cudaMemcpyDeviceToHost, d.st);
        cudaStreamSynchronize(d.st);
        std::lock_guard<std::mutex> lk(dump_mu);
        const int64_t hdr[3] = {il, p0, T};
        std::fwrite(hdr, 8, 3, dump_l);
        std::fwrite(v.data(), 4, v.size(), dump_l);
        std::fflush(dump_l);
    }

    bool dump_s_on(int il) const {
        if (dump_s == nullptr) return false;
        for (int x : dump_s_layers)
            if (x == il) return true;
        return false;
    }
    bool dump_s_name(const char* name) const {   // DS4_DUMP_S_NAMES=a,b,c: only these points (default all)
        static const std::string names = [] { const char* e = std::getenv("DS4_DUMP_S_NAMES"); return std::string(e ? "," : "") + (e ? e : "") + (e ? "," : ""); }();
        return names.empty() || names.find(std::string(",") + name + ",") != std::string::npos;
    }
    void dump_sub(Dev& d, const char* name, int il, int64_t p0, int T, const void* dev, size_t nbytes) {
        if (!dump_s_on(il) || !dump_s_name(name)) return;
        std::vector<uint8_t> v(nbytes);
        cudaSetDevice(d.id);
#if defined(STRATA_METAL)
        ds4_metal_flush();
        cudaDeviceSynchronize();   // (the batched dispatches have finished before the read)
#endif
        cudaMemcpyAsync(v.data(), dev, nbytes, cudaMemcpyDeviceToHost, d.st);
        cudaStreamSynchronize(d.st);
        dump_sub_host(name, il, p0, T, v.data(), nbytes);
    }
    void dump_sub_host(const char* name, int il, int64_t p0, int T, const void* host, size_t nbytes) {
        if (!dump_s_on(il) || !dump_s_name(name)) return;
        std::lock_guard<std::mutex> lk(dump_mu);
        char nm[16] = {};
        std::strncpy(nm, name, 15);
        const int64_t hdr[4] = {il, p0, T, (int64_t) nbytes};
        std::fwrite(nm, 1, 16, dump_s);
        std::fwrite(hdr, 8, 4, dump_s);
        std::fwrite(host, 1, nbytes, dump_s);
        std::fflush(dump_s);
    }

    ~Impl() {
        draft_report();   // (DS4_DRAFT_*: before anything stops)
        quit.store(true);
        if (warm_bg.joinable()) warm_bg.join();   // (the warm-up uses the BLAS handles destroyed below)
        eg_io.stop();   // (its threads write into h_eg)
        for (auto& w : workers) w->stop();
        for (size_t i = 0; i < chunks.size(); ++i)
            if (chunks[i] && chunks[i]->blas) {
                cudaSetDevice(devs[i].id);
                cublasDestroy(chunks[i]->blas);
#if defined(DS4_MIX_ROCBLAS)
                if (chunks[i]->mix_rb) {
                    if (std::getenv("STRATA_ROCBLAS_VERBOSE"))
                        std::fprintf(stderr, "ds4: mHC mix rocBLAS CUDA%d: %llu tuned launches, %llu fallbacks\n", devs[i].id,
                                     (unsigned long long) chunks[i]->mix_tuned, (unsigned long long) chunks[i]->mix_fallbacks);
                    rocblas_destroy_handle(chunks[i]->mix_rb);
                    chunks[i]->mix_rb = nullptr;
                }
#endif
            }
        quit.store(true);
        if (service.joinable()) service.join();
        if (store_bg.joinable()) store_bg.join();   // (the store's background fill: it checks quit between its pieces)
        {
            std::lock_guard<std::mutex> lk(pf_mu);
        }
        pf_cv.notify_all();
        if (pf_th.joinable()) pf_th.join();
        {
            std::lock_guard<std::mutex> lk(sw_mu);
        }
        sw_cv.notify_all();
        ram_cv.notify_all();
        for (std::thread& t : cache_ths)
            if (t.joinable()) t.join();
        if (ram_th.joinable()) ram_th.join();
        for (size_t i = 0; i < ram_chunks.size(); ++i) {
            if (ram_pinned) (void) cudaHostUnregister(ram_chunks[i]);
            os::anon_free(ram_chunks[i], ram_chunk_bytes[i]);
        }
        shared_store.reset();   // (unmaps; STRATA_DS4_SHARED_STORE_DROP=1: the last engine out removes the file)
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            for (void* p : d.allocs) cudaFree(p);
            if (d.st) cudaStreamDestroy(d.st);
            if (d.ev) cudaEventDestroy(d.ev);
            if (d.eg_st) cudaStreamDestroy(d.eg_st);   // (DS4_EG_AHEAD)
        }
        if (eg_ahead > 0)
            std::fprintf(stderr, "ds4: DS4_EG_AHEAD: %lld Engram layer passes took the prefetch, %lld the old path\n",
                         eg_ah_used.load(), eg_ah_old.load());
        for (void* p : host_allocs) cudaFreeHost(p);
        for (Layer& l : L)
            for (uint8_t* b : l.host)
                if (b != nullptr) {
                    (void) b;   // host blobs live in one mapping per layer, unmapped below
                }
        for (auto& m : host_maps) {
            if (chunk > 0 && lane_pinned) cudaHostUnregister(m.first);
            os::anon_free(m.first, m.second);
        }
    }
    std::vector<std::pair<void*, size_t>> host_maps;
    bool lane_pinned = false;   // (host_maps registered with the runtime: chunk > 0 and not DS4_PIN_LANE=0)

    template <class T>
    bool dalloc(Dev& d, T*& p, size_t n, std::string& err, size_t* acct = nullptr) {
        void* v = nullptr;
        cudaSetDevice(d.id);
        const size_t b = align256(n * sizeof(T));
        if (cudaMalloc(&v, b) != cudaSuccess) {
            err = "cudaMalloc " + std::to_string(b >> 20) + " MiB on CUDA" + std::to_string(d.id) + " failed";
            return false;
        }
        // zeroed before anything lands in it: the loads copy in on the default stream, which the non-blocking d.st
        // does not order against - a zeroing still queued there could wipe the weights just copied
        if (cudaMemsetAsync(v, 0, b, d.st) != cudaSuccess || cudaStreamSynchronize(d.st) != cudaSuccess) {
            cudaFree(v);
            err = "zeroing " + std::to_string(b >> 20) + " MiB on CUDA" + std::to_string(d.id) + " failed";
            return false;
        }
        d.allocs.push_back(v);
        if (acct) *acct += b;
        else d.scratch += b;
        p = (T*) v;
        return true;
    }
    static Layer& member(Layer& l, int m) { return m == 0 ? l : l.mates[(size_t) m - 1]; }
    static const Layer& member(const Layer& l, int m) { return m == 0 ? l : l.mates[(size_t) m - 1]; }
    // bytes of a VRAM slot of l's experts (a member's part of each, in a group)
    static size_t unit(const Layer& l) { return l.nm > 1 ? l.hblob : l.blob; }
    // the members of a group of nm that take heads: the most the heads and the wo_a groups split among evenly (64
    // heads and 8 groups: 9 -> 8, 7 or 6 -> 4, 5 -> 4, 3 -> 2); the first members the rest, only their FFN share
    int head_members(int nm) const {
        int na = nm;
        while (na > 1 && (g.heads % na != 0 || g.o_groups % na != 0)) --na;
        return na;
    }
    // DS4_ATTN_SPLIT3=1 (default off): Layer::a3 for l's group - where head_members leaves members out, the wo_a groups
    // split in nm + 1 equal parts (8 over 3: 2 groups), and wq_b / wo_b are a GGUF's row-major types (BF16, Q8_0, a K-quant)
    static bool a3_env() {
        static const bool on = [] { const char* v = std::getenv("DS4_ATTN_SPLIT3"); return v != nullptr && std::atoi(v) == 1; }();
        return on;
    }
    bool a3_eligible(const Layer& l) {
        if (!a3_env() || l.nm < 2 || l.mtp || head_members(l.nm) == l.nm || g.o_groups > 16 || g.heads % g.o_groups != 0 ||
            g.o_groups % (l.nm + 1) != 0 || g.o_lora % 256 != 0)
            return false;
        for (const char* n : {"attn.wq_b", "attn.wo_b"}) {
            const Tensor* t = pk.get(l.name + n + ".weight");
            if (t == nullptr || t->shape.size() != 2) return false;
            if (t->dtype != "BF16" && t->dtype != "Q8_0" && gg_type_of(t->dtype) <= 0) return false;
            if (t->dtype == "Q8_0" || t->dtype == "BF16") continue;
            if (t->shape[1] % 256 != 0) return false;
        }
        return true;
    }
    // the most heads a member of a group of nm works on at once in the chunked prompt (its scratch): head_members' share,
    // or with a3 its own and shared groups
    int chunk_heads(int nm) const {
        int h = g.heads / head_members(nm);
        if (a3_env() && nm > 1 && head_members(nm) != nm && g.o_groups % (nm + 1) == 0)
            h = std::max(h, 2 * (g.o_groups / (nm + 1)) * (g.heads / std::max(1, g.o_groups)));
        return h;
    }
    // a3: a standalone [n][k] matrix of the given output (cols) or input ranges of a GGUF's BF16 / Q8_0 / K-quant one,
    // concatenated in that order (the inputs in whole blocks)
    bool mat_concat(Dev& d, const std::string& pre, x3::Mat& m, std::string& err, size_t* acct,
                    const std::vector<std::pair<int, int>>& ranges, bool cols) {
        const Tensor* tp = pk.get(pre + ".weight");
        if (tp == nullptr || tp->shape.size() != 2) {
            err = pre + ": not a matrix in the pack (DS4_ATTN_SPLIT3)";
            return false;
        }
        const Tensor& t = *tp;
        const bool q8 = t.dtype == "Q8_0", bf = t.dtype == "BF16";
        const int ggt = (q8 || bf) ? -1 : gg_type_of(t.dtype);
        if (!q8 && !bf && ggt <= 0) {
            err = pre + ": type " + t.dtype + " not covered by DS4_ATTN_SPLIT3";
            return false;
        }
        const int n = (int) t.shape[0], k = (int) t.shape[1];
        const int bv = bf ? 1 : q8 ? 32 : 256;   // values a block, and its bytes
        const size_t bb = bf ? 2 : q8 ? (size_t) gg::kQ8Bytes : gg::type_row_bytes(ggt, 256);
        const size_t rb = (size_t) (k / bv) * bb;
        std::vector<uint8_t> w((size_t) n * rb);
        if (k % bv != 0 || t.bytes != w.size() || !pk.read(t, w.data())) {
            err = pre + ": read failed";
            return false;
        }
        int tot = 0;
        for (const auto& r : ranges) {
            if (r.first < 0 || r.second <= 0 || r.first + r.second > (cols ? n : k) || (!cols && (r.first % bv || r.second % bv))) {
                err = pre + ": a range outside the matrix or its blocks (DS4_ATTN_SPLIT3)";
                return false;
            }
            tot += r.second;
        }
        std::vector<uint8_t> p;
        int on = n, ok = k;
        if (cols) {
            p.reserve((size_t) tot * rb);
            for (const auto& r : ranges)
                p.insert(p.end(), w.begin() + (long) ((size_t) r.first * rb), w.begin() + (long) ((size_t) (r.first + r.second) * rb));
            on = tot;
        } else {
            const size_t pb = (size_t) (tot / bv) * bb;
            p.resize((size_t) n * pb);
            for (size_t row = 0; row < (size_t) n; ++row) {
                size_t at = 0;
                for (const auto& r : ranges) {
                    const size_t nb = (size_t) (r.second / bv) * bb;
                    std::memcpy(p.data() + row * pb + at, w.data() + row * rb + (size_t) (r.first / bv) * bb, nb);
                    at += nb;
                }
            }
            ok = tot;
        }
        uint8_t* dp = nullptr;
        if (!dalloc(d, dp, p.size(), err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(dp, p.data(), p.size(), cudaMemcpyHostToDevice));
        m = x3::Mat{};
        m.fmt = bf ? gg::kFmtBF16 : q8 ? gg::kFmtQ8_0 : gg::kFmtGG;
        if (ggt > 0) m.K = ggt;
        m.raw = dp;
        m.k = ok;
        m.n = on;
        m.ld = bf ? ok : (int) ((size_t) (ok / bv) * bb);
        return true;
    }
    // a3: inputs [k0, k0 + kn) of a row-major matrix (whole blocks) - the same rows, the stride kept
    static x3::Mat kview(const x3::Mat& m, int k0, int kn) {
        x3::Mat v = m;
        size_t off = 0;
        if (m.fmt == gg::kFmtBF16) off = (size_t) k0 * 2;
        else if (m.fmt == gg::kFmtQ8_0) off = (size_t) (k0 / 32) * gg::kQ8Bytes;
        else off = (size_t) (k0 / 256) * gg::type_row_bytes(m.K, 256);
        v.raw = (const uint8_t*) m.raw + off;
        v.k = kn;
        return v;
    }
    // host-mapped memory (the same address on the host and every device), zeroed
    template <class T>
    bool hmap(T*& p, size_t n, std::string& err) {
        void* v = nullptr;
        if (cudaHostAlloc(&v, n * sizeof(T) + 64, cudaHostAllocMapped | cudaHostAllocPortable) != cudaSuccess) {
            err = "host-mapped memory (" + std::to_string((n * sizeof(T)) >> 20) + " MiB)";
            return false;
        }
        std::memset(v, 0, n * sizeof(T) + 64);
        host_allocs.push_back(v);
        p = (T*) v;
        return true;
    }
    // DS4_AR_P2PK (build 9: on by default; DS4_AR_P2PK=0 = the host-mapped path): a prompt chunk's all-reduce (ArGroup arb of a group of three members or more) as ar_p2pk_kernel's
    // reduce-scatter + all-gather of kernel stores straight into the peers' VRAM.  Peer access enabled between every pair,
    // each member's receive slots, flags and error words hipDeviceMallocUncached in its own VRAM, then the self-test below;
    // anything short of a pass: a stderr line and the host-mapped path (a.p2pk 0).  The decode windows' group is not touched.
    //   DS4_AR_P2PK_SPLIT=w0,w1,..  chunk weights in member order (default equal; a smaller share for a member with slow links)
    //   DS4_AR_P2PK_TILE=KiB  (1024; was 64)   DS4_AR_P2PK_BLOCKS=n (192)   DS4_AR_P2PK_ORDER=0 (tile-major sends; default 1 peer-major)   DS4_AR_P2PK_SEED=n (the self-test's data; default random)
    //   DS4_AR_P2PK_DRY=1: buffers allocated and self-tested, the host path used (A/B on the same VRAM placement)
    // The self-test: ten all-reduces, F16 and F32 interleaved, of random partials (p2pk_fill: full mantissas, |v| 2^-44 ..
    // 2^17, so FP16 subnormals, zeros and saturation), sizes one token, 5 tokens, the F16 threshold (n4 = 65536), a large
    // one off the tile grid and the largest the slots take (F16: the whole chunk row, the 16K window's at --max-context
    // 16896), in an order that mixes long and short calls and both parities.  Each is checked bit for bit on every member
    // against the host path's own reduce-scatter (ar_rs_kernel / ar_rs16_kernel through this group's host rows) on the
    // same data, and every wait is bounded (a timeout sets the error word, the kernel gives up instead of hanging)
    bool ar_p2pk_setup(Group& G, ArGroup& a) {
#if defined(STRATA_USE_HIP)
        if (env_tri("DS4_AR_P2PK") == 0) return false;   // (build 9: unset = on)
        const int nm = a.nm;
        std::string ids;
        for (int m : G.mem) ids += (ids.empty() ? "CUDA" : ",") + std::to_string(devs[(size_t) m].id);
        const auto no = [&](const std::string& why) {
            std::fprintf(stderr, "ds4: DS4_AR_P2PK: group %s keeps the host-mapped prompt-chunk all-reduce: %s\n", ids.c_str(),
                         why.c_str());
            (void) hipGetLastError();
            a.p2pk = 0;
            a.pk_cap = 0;
            return false;
        };
        if (nm < 3) return no("fewer than 3 members");
        if (nm > ArGroup::kPkMax) return no("more than " + std::to_string(ArGroup::kPkMax) + " members");
        if (a.stride == 0 || a.stride % 8 != 0 || a.sums == nullptr || a.bflags == nullptr)
            return no("no reduce-scatter rows of a chunk (or a row stride not a multiple of 8)");
        // the chunk weights
        int wmax = 0;
        long long wsum = 0;
        std::string split;
        {
            for (int m = 0; m < nm; ++m) a.pk_w[m] = 1;
            const char* e = std::getenv("DS4_AR_P2PK_SPLIT");
            if (e != nullptr && *e) {
                std::vector<int> w;
                for (const char* q = e; *q;) {
                    char* end = nullptr;
                    const long v = std::strtol(q, &end, 10);
                    if (end == q) break;
                    w.push_back((int) v);
                    if (*end != ',') break;
                    q = end + 1;
                }
                bool ok = (int) w.size() == nm;
                for (int v : w) ok = ok && v >= 1 && v <= 1000;
                if (!ok) return no(std::string("DS4_AR_P2PK_SPLIT=") + e + " is not " + std::to_string(nm) + " weights of 1..1000");
                for (int m = 0; m < nm; ++m) a.pk_w[m] = w[(size_t) m];
            }
            for (int m = 0; m < nm; ++m) {
                wmax = std::max(wmax, a.pk_w[m]);
                wsum += a.pk_w[m];
                split += (m ? "," : "") + std::to_string(a.pk_w[m]);
            }
        }
        // the slots: the most units a call can take in the precision the host path would use (allreduce): F32 below the
        // F16 threshold, F16 at and past it unless DS4_AR_F16=0
        const long long n4max = (long long) (a.stride / 4);
        const long long numax = env_tri("DS4_AR_F16") == 0 ? n4max : std::max(n4max / 2, std::min(n4max, (long long) 65535));
        const int tu = p2pk_tile_units();
        a.pk_tu = tu;
        a.pk_cap = (numax * wmax + wsum - 1) / wsum + 1;
        a.pk_maxt = (int) ((a.pk_cap + tu - 1) / tu);
        int prev = 0;
        (void) hipGetDevice(&prev);
        struct Restore {
            int d;
            ~Restore() { (void) hipSetDevice(d); }
        } restore{prev};
        for (int x : G.mem)
            for (int y : G.mem) {
                if (x == y) continue;
                const int ix = devs[(size_t) x].id, iy = devs[(size_t) y].id;
                int can = 0;
                if (hipDeviceCanAccessPeer(&can, ix, iy) != hipSuccess || !can)
                    return no("hipDeviceCanAccessPeer " + std::to_string(ix) + " -> " + std::to_string(iy) + " says no");
                (void) hipSetDevice(ix);
                const hipError_t e = hipDeviceEnablePeerAccess(iy, 0);
                if (e != hipSuccess && e != hipErrorPeerAccessAlreadyEnabled)
                    return no("hipDeviceEnablePeerAccess " + std::to_string(ix) + " -> " + std::to_string(iy) + ": " +
                              hipGetErrorString(e));
                (void) hipGetLastError();
            }
        const size_t rb = (size_t) 2 * (nm - 1) * (size_t) a.pk_cap * 16,
                     fb = (size_t) 2 * 3 * nm * (size_t) a.pk_maxt * 8 * sizeof(unsigned), eb = 256;
        for (int m = 0; m < nm; ++m) {
            Dev& d = devs[(size_t) G.mem[(size_t) m]];
            (void) hipSetDevice(d.id);
            void *r = nullptr, *f = nullptr, *w = nullptr;
            if (hipExtMallocWithFlags(&r, rb, hipDeviceMallocUncached) != hipSuccess ||
                hipExtMallocWithFlags(&f, fb, hipDeviceMallocUncached) != hipSuccess ||
                hipExtMallocWithFlags(&w, eb, hipDeviceMallocUncached) != hipSuccess) {
                for (void* q : {r, f, w})
                    if (q) (void) hipFree(q);
                return no("hipExtMallocWithFlags(hipDeviceMallocUncached) failed on CUDA" + std::to_string(d.id));
            }
            for (void* q : {r, f, w}) d.allocs.push_back(q);
            d.scratch += rb + fb + eb;
            if (hipMemset(r, 0, rb) != hipSuccess || hipMemset(f, 0, fb) != hipSuccess || hipMemset(w, 0, eb) != hipSuccess)
                return no("zeroing the receive buffers failed");
            a.pk_buf[m] = r;
            a.pk_flags[m] = (unsigned*) f;
            a.pk_err[m] = (unsigned*) w;
        }
        for (int m = 0; m < nm; ++m) {
            (void) hipSetDevice(devs[(size_t) G.mem[(size_t) m]].id);
            if (hipDeviceSynchronize() != hipSuccess) return no("hipDeviceSynchronize after the allocations failed");
        }
        // the self-test's cases: (precision, floats), F16 and F32 interleaved, long after short and short after long
        unsigned seed = (unsigned) std::chrono::high_resolution_clock::now().time_since_epoch().count() ^
                        (unsigned) (uintptr_t) &a * 2654435761u;
        if (const char* e = std::getenv("DS4_AR_P2PK_SEED")) seed = (unsigned) std::strtoul(e, nullptr, 10);
        const size_t D = (size_t) g.dim;
        const auto fit = [&](bool f16) {   // (the largest call the slots take, a multiple of 8 floats, at most a chunk row)
            const long long units = (a.pk_cap - 1) * wsum / wmax;
            return (size_t) std::min<long long>((long long) a.stride, units * (f16 ? 8 : 4)) / 8 * 8;
        };
        const size_t big16 = fit(true), big32 = fit(false), thr = (size_t) 4 << 16;
        const auto odd = [](size_t n) { return std::max<size_t>(8, (n * 5 / 7) / 8 * 8 - 8); };   // (off the tile grid)
        struct Case {
            bool f16;
            size_t n;
        };
        std::vector<Case> cases = {{true, big16}, {false, D}, {true, 5 * D}, {false, big32}, {true, odd(big16)},
                                   {false, std::min(thr, big32)}, {true, std::min(thr, big16)}, {false, 5 * D},
                                   {true, D}, {false, odd(big32)}};
        size_t nbuf = 0;
        for (Case& c : cases) {
            c.n = std::min(c.n, (size_t) a.stride) / 8 * 8;
            nbuf = std::max(nbuf, c.n);
        }
        std::vector<float*> xr((size_t) nm, nullptr), xp((size_t) nm, nullptr);
        std::vector<unsigned*> cw((size_t) nm, nullptr);
        bool ok = true;
        std::string why;
        for (int m = 0; m < nm && ok; ++m) {
            (void) hipSetDevice(devs[(size_t) G.mem[(size_t) m]].id);
            if (hipMalloc((void**) &xr[(size_t) m], nbuf * 4) != hipSuccess || hipMalloc((void**) &xp[(size_t) m], nbuf * 4) != hipSuccess ||
                hipMalloc((void**) &cw[(size_t) m], 8) != hipSuccess) {
                ok = false;
                why = "hipMalloc of the self-test's rows (" + std::to_string(nbuf * 8 >> 20) + " MiB a member) failed";
            }
        }
        std::string done;
        for (size_t k = 0; k < cases.size() && ok; ++k) {
            const Case& c = cases[k];
            const unsigned seq = (unsigned) k + 1;
            for (int m = 0; m < nm; ++m) {
                Dev& d = devs[(size_t) G.mem[(size_t) m]];
                (void) hipSetDevice(d.id);
                (void) hipMemsetAsync(cw[(size_t) m], 0xff, 8, d.st);   // ({0, ~0}: the count, the first index)
                (void) hipMemsetAsync(cw[(size_t) m], 0, 4, d.st);
                p2pk_fill(xr[(size_t) m], xp[(size_t) m], c.n, seed + (unsigned) k * 7919u, m, d.st);
            }
            for (int m = 0; m < nm; ++m) {   // (the reference: every member's launch queued before any is waited on)
                Dev& d = devs[(size_t) G.mem[(size_t) m]];
                (void) hipSetDevice(d.id);
                allreduce_rs_ref(xr[(size_t) m], (int) c.n, a, m, seq, c.f16, d.st);
            }
            for (int m = 0; m < nm && ok; ++m) {
                Dev& d = devs[(size_t) G.mem[(size_t) m]];
                (void) hipSetDevice(d.id);
                if (!allreduce_p2pk_test(xp[(size_t) m], (int) c.n, a, m, seq, c.f16, d.st)) {
                    ok = false;   // (decided on the host, the same for every member: none of them launched)
                    why = "case " + std::to_string(k) + " (" + std::to_string(c.n) + " floats) does not fit the slots";
                }
            }
            for (int m = 0; m < nm; ++m) {
                Dev& d = devs[(size_t) G.mem[(size_t) m]];
                (void) hipSetDevice(d.id);
                p2pk_cmp(xr[(size_t) m], xp[(size_t) m], c.n, cw[(size_t) m], d.st);
            }
            for (int m = 0; m < nm && ok; ++m) {
                Dev& d = devs[(size_t) G.mem[(size_t) m]];
                (void) hipSetDevice(d.id);
                unsigned res[2] = {0, 0}, e3[3] = {0, 0, 0};
                if (hipStreamSynchronize(d.st) != hipSuccess || hipMemcpy(res, cw[(size_t) m], 8, hipMemcpyDeviceToHost) != hipSuccess ||
                    hipMemcpy(e3, a.pk_err[m], 12, hipMemcpyDeviceToHost) != hipSuccess) {
                    ok = false;
                    why = std::string("the self-test failed to run: ") + hipGetErrorString(hipGetLastError());
                    break;
                }
                const std::string at = "case " + std::to_string(k) + " (" + (c.f16 ? "F16" : "F32") + ", " + std::to_string(c.n) +
                                       " floats) member " + std::to_string(m) + " (CUDA" + std::to_string(d.id) + ")";
                if (e3[0] != 0) {
                    ok = false;
                    char t[96];
                    std::snprintf(t, sizeof t, ": timed out at seq %u (kind %u, peer %u, tile %u; flag %u)", e3[0], (e3[1] >> 28) - 1,
                                  (e3[1] >> 24) & 15u, e3[1] & 0xffffffu, e3[2]);
                    why = at + t;
                } else if (res[0] != 0) {
                    ok = false;
                    why = at + ": " + std::to_string(res[0]) + " sums differ from the host path's, the first at " + std::to_string(res[1]);
                }
            }
            if (ok) done += (done.empty() ? "" : " ") + std::string(c.f16 ? "F16:" : "F32:") + std::to_string(c.n);
        }
        // (a run's all-reduces count seq from 1 again: the peer flags and error words, and the host rows' flags, to zero)
        for (int m = 0; m < nm; ++m) {
            Dev& d = devs[(size_t) G.mem[(size_t) m]];
            (void) hipSetDevice(d.id);
            (void) hipDeviceSynchronize();
            for (void* q : {(void*) xr[(size_t) m], (void*) xp[(size_t) m], (void*) cw[(size_t) m]})
                if (q) (void) hipFree(q);
            if (hipMemset(a.pk_flags[m], 0, fb) != hipSuccess || hipMemset(a.pk_err[m], 0, eb) != hipSuccess ||
                hipMemset(a.pk_buf[m], 0, rb) != hipSuccess || hipDeviceSynchronize() != hipSuccess) {
                ok = false;
                if (why.empty()) why = "resetting the flags failed";
            }
        }
        std::memset(a.bflags, 0, (size_t) 2 * a.nm * a.slots * kArBlocks * 8 * sizeof(unsigned));
        if (!ok) return no("self-test (seed " + std::to_string(seed) + "): " + why);
        const double mib = (double) (rb + fb + eb) / 1048576.0;
        if (env_tri("DS4_AR_P2PK_DRY") == 1) {
            std::fprintf(stderr, "ds4: DS4_AR_P2PK_DRY: group %s prompt-chunk all-reduce buffers allocated (%.1f MiB a member) and "
                                 "self-tested, the host-mapped path used\n", ids.c_str(), mib);
            a.p2pk = 0;
            return false;
        }
        a.p2pk = 1;
        std::fprintf(stderr, "ds4: DS4_AR_P2PK: group %s prompt-chunk all-reduces peer to peer (tiled reduce-scatter + all-gather, "
                             "kernel stores into the peers' uncached VRAM; %.1f MiB a member, tile %d KiB, %d blocks, %s sends, split %s); "
                             "self-test bit-identical to the host path on every member (seed %u: %s)\n",
                     ids.c_str(), mib, tu / 64, p2pk_blocks(), p2pk_order() == 1 ? "peer-major" : "tile-major", split.c_str(), seed, done.c_str());
        return true;
#else
        (void) G;
        (void) a;
        return false;
#endif
    }
    template <class T>
    bool halloc(T*& p, size_t n, std::string& err) {
        void* v = nullptr;
        if (cudaHostAlloc(&v, n * sizeof(T) + 64, cudaHostAllocPortable) != cudaSuccess) {
            err = "cudaHostAlloc " + std::to_string((n * sizeof(T)) >> 20) + " MiB failed";
            return false;
        }
        host_allocs.push_back(v);
        p = (T*) v;
        return true;
    }

    // ---- weights
    bool upload(Dev& d, const Tensor& t, void* dst, std::string& err) {
        std::vector<uint8_t> tmp(t.bytes);
        if (!pk.read(t, tmp.data())) {
            err = "read failed";
            return false;
        }
        cudaSetDevice(d.id);
        CK(cudaMemcpy(dst, tmp.data(), t.bytes, cudaMemcpyHostToDevice));
        return true;
    }
    // a dense matrix in a ggml block type (x3::Mat fmt kFmtGG, row = k / 256 blocks): whole, or part of its rows / inputs
    // tp4 (after Project Maya e3f2475's mat_bf16): r0 >= 0 - the range [r0, r0 + rn) of its outputs (cols) or of its
    // inputs (whole 256-blocks) instead of an even part: the shared expert at its member's own FFN range
    bool mat_gg(Dev& d, const std::string& pre, const Tensor& t, int ggt, x3::Mat& m, std::string& err, size_t* acct, int part,
                int np, bool cols, int r0 = -1, int rn = 0) {
        if (t.shape.size() != 2 || t.shape[1] % 256 != 0) {
            err = pre + ": a " + t.dtype + " tensor that is not a matrix of whole blocks";
            return false;
        }
        int n = (int) t.shape[0], k = (int) t.shape[1];
        const size_t rb = gg::type_row_bytes(ggt, k), bb = rb / ((size_t) k / 256);
        std::vector<uint8_t> w((size_t) n * rb);
        if (t.bytes != w.size() || !pk.read(t, w.data())) {
            err = pre + ": read failed";
            return false;
        }
        if (np > 1 && r0 >= 0) {   // (an explicit range)
            const int whole = cols ? n : k;
            if (rn <= 0 || r0 + rn > whole || (!cols && (r0 % 256 != 0 || rn % 256 != 0))) {
                err = pre + ": " + std::to_string(whole) + (cols ? " outputs" : " inputs") + " have no range [" +
                      std::to_string(r0) + ", " + std::to_string(r0 + rn) + ")" + (cols ? "" : " of whole 256-blocks");
                return false;
            }
            std::vector<uint8_t> p;
            if (cols) {
                p.assign(w.begin() + (long) ((size_t) r0 * rb), w.begin() + (long) ((size_t) (r0 + rn) * rb));
                n = rn;
            } else {
                const size_t pb = (size_t) (rn / 256) * bb, off = (size_t) (r0 / 256) * bb;
                p.resize((size_t) n * pb);
                for (size_t r = 0; r < (size_t) n; ++r) std::memcpy(p.data() + r * pb, w.data() + r * rb + off, pb);
                k = rn;
            }
            w.swap(p);
        } else if (np > 1) {
            const int whole = cols ? n : k, wd = whole / np;
            // (TP-01): outputs that do not split evenly (the head's 129,280 over 3) in 128-column blocks as
            // split128 shares them - head_cols' shares for a K-quant head, which head_share and its gather already use
            const bool uneven128 = cols && whole % np != 0 && whole % 128 == 0 && whole / 128 >= np;
            if (!uneven128 && (whole % np != 0 || wd % (cols ? 1 : 256) != 0)) {
                err = pre + ": " + std::to_string(whole) + (cols ? " outputs" : " inputs") + " do not split in " + std::to_string(np) + " parts";
                return false;
            }
            std::vector<uint8_t> p;
            if (uneven128) {
                int c0 = 0, cn = 0;
                split128(whole, np, part, c0, cn);
                p.assign(w.begin() + (long) ((size_t) c0 * rb), w.begin() + (long) ((size_t) (c0 + cn) * rb));
                n = cn;
            } else if (cols) {
                p.assign(w.begin() + (long) ((size_t) part * wd * rb), w.begin() + (long) ((size_t) (part + 1) * wd * rb));
                n = wd;
            } else {
                const size_t pb = (size_t) (wd / 256) * bb, off = (size_t) (part * wd / 256) * bb;
                p.resize((size_t) n * pb);
                for (size_t r = 0; r < (size_t) n; ++r) std::memcpy(p.data() + r * pb, w.data() + r * rb + off, pb);
                k = wd;
            }
            w.swap(p);
        }
        uint8_t* dp = nullptr;
        if (!dalloc(d, dp, w.size(), err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(dp, w.data(), w.size(), cudaMemcpyHostToDevice));
        m = x3::Mat{};
        m.fmt = gg::kFmtGG;
        m.K = ggt;
        m.raw = dp;
        m.k = k;
        m.n = n;
        m.ld = (int) gg::type_row_bytes(ggt, k);
        return true;
    }
    // a GGUF's BF16 or Q8_0 matrix ([out][in]) onto the device, as mat() takes an EXL3 one: whole, or part `part` of its
    // columns (outputs: a range of its rows) or of its rows (inputs: a range of each row, whole Q8_0 blocks) - a
    // standalone [n][k] matrix
    // (r0 >= 0: the range [r0, r0 + rn) instead of an even part - tp4's shared expert, its member's FFN range)
    bool mat_bf16(Dev& d, const std::string& pre, const Tensor& t, x3::Mat& m, std::string& err, size_t* acct, int part,
                  int np, bool cols, int r0 = -1, int rn = 0) {
        const bool q8 = t.dtype == "Q8_0";
        // a ggml K-quant dense matrix (Q4_K / Q5_K / Q6_K: 256 values a block; the GEMV path of ds4_iq)
        const int ggt = (t.dtype == "Q4_K" || t.dtype == "Q5_K" || t.dtype == "Q6_K") ? gg_type_of(t.dtype) : -1;
        if (ggt > 0) return mat_gg(d, pre, t, ggt, m, err, acct, part, np, cols, r0, rn);
        if (t.shape.size() != 2 || (q8 && t.shape[1] % 32 != 0)) {
            err = pre + ": a " + t.dtype + " tensor that is not a matrix";
            return false;
        }
        int n = (int) t.shape[0], k = (int) t.shape[1];
        // a row's bytes, and the bytes of v of its values (BF16: 2 each; Q8_0: 34 every 32)
        auto bytes_of = [&](size_t v) { return q8 ? v / 32 * gg::kQ8Bytes : v * 2; };
        std::vector<uint8_t> w((size_t) n * bytes_of((size_t) k));
        if (t.bytes != w.size() || !pk.read(t, w.data())) {
            err = pre + ": read failed";
            return false;
        }
        if (np > 1) {
            const int whole = cols ? n : k, wd = r0 >= 0 ? rn : whole / np, w0 = r0 >= 0 ? r0 : part * wd;
            const int q = q8 ? 32 : 8;
            if ((r0 < 0 && whole % np != 0) || wd <= 0 || wd % q != 0 || w0 % q != 0 || w0 + wd > whole) {
                err = pre + ": " + std::to_string(whole) + (cols ? " outputs" : " inputs") + " do not split in " +
                      (r0 >= 0 ? "[" + std::to_string(w0) + ", " + std::to_string(w0 + wd) + ")" : std::to_string(np) + " parts");
                return false;
            }
            const size_t rb = bytes_of((size_t) k);
            std::vector<uint8_t> p;
            if (cols) {
                p.assign(w.begin() + (long) ((size_t) w0 * rb), w.begin() + (long) ((size_t) (w0 + wd) * rb));
                n = wd;
            } else {
                const size_t pb = bytes_of((size_t) wd);
                p.resize((size_t) n * pb);
                for (size_t r = 0; r < (size_t) n; ++r)
                    std::memcpy(p.data() + r * pb, w.data() + r * rb + bytes_of((size_t) w0), pb);
                k = wd;
            }
            w.swap(p);
        }
        uint8_t* dp = nullptr;
        if (!dalloc(d, dp, w.size(), err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(dp, w.data(), w.size(), cudaMemcpyHostToDevice));
        m = x3::Mat{};
        m.fmt = q8 ? gg::kFmtQ8_0 : gg::kFmtBF16;
        m.raw = dp;
        m.k = k;
        m.n = n;
        m.ld = q8 ? (int) bytes_of((size_t) k) : k;
        return true;
    }
    // a Q8_0 tensor's values as F32 (host)
    static std::vector<float> q8_values(const uint8_t* q, size_t n) {
        std::vector<float> v(n);
        for (size_t b = 0; b < n / 32; ++b) {
            const uint8_t* p = q + b * gg::kQ8Bytes;
            const float d = f16_to_f32((uint16_t) (p[0] | p[1] << 8));
            for (int j = 0; j < 32; ++j) v[b * 32 + j] = d * (float) (int8_t) p[2 + j];
        }
        return v;
    }
    // an EXL3 matrix onto the device: whole, or (np > 1) part `part` of its columns (cols) or of its rows - a standalone
    // matrix of its own (the rotations' 128-blocks stay whole)
    // (rot: split128's - an EXL3 matrix's uneven 128-block shares going round the members; a GGUF's BF16 / Q8_0 matrix
    // splits evenly, its groups only as wide as that goes)
    bool mat(Dev& d, const std::string& pre, x3::Mat& m, std::string& err, size_t* acct, int part = 0, int np = 1,
             bool cols = true, int rot = 0, int r0 = -1, int rn = 0) {
        if (const Tensor* tw = pk.get(pre + ".weight"); tw != nullptr && (tw->dtype == "BF16" || tw->dtype == "Q8_0" || tw->dtype == "Q4_K" || tw->dtype == "Q5_K" || tw->dtype == "Q6_K"))
            return mat_bf16(d, pre, *tw, m, err, acct, part, np, cols, r0, rn);
        if (r0 >= 0) {   // (tp4: an explicit range is a GGUF dense matrix's only - an EXL3 one splits by split128's rot)
            err = pre + ": an explicit range of a matrix that is not BF16, Q8_0 or a K-quant";
            return false;
        }
        const Tensor* tr = pk.get(pre + ".trellis");
        const Tensor* su = pk.get(pre + ".suh");
        const Tensor* sv = pk.get(pre + ".svh");
        if (tr == nullptr || su == nullptr || sv == nullptr || tr->shape.size() != 3) {
            err = pre + ": not an EXL3 matrix in the pack";
            return false;
        }
        if (pk.get(pre + ".mul1") == nullptr) {
            err = pre + ": only the mul1 codebook is covered";
            return false;
        }
        m.k = (int) tr->shape[0] * 16;
        m.n = (int) tr->shape[1] * 16;
        m.K = (int) tr->shape[2] / 16;
        m.cb = 2;
        m.ld = 0;
        if (np > 1) {
            const int whole = cols ? m.n : m.k;
            int at = 0, w = 0;
            if (whole % 128 != 0 || whole / 128 < np) {
                err = pre + ": " + std::to_string(whole) + (cols ? " columns" : " rows") + " do not split in " +
                      std::to_string(np) + " parts of 128-blocks";
                return false;
            }
            split128(whole, np, part, at, w, rot);
            std::vector<uint8_t> t0(tr->bytes), u0(su->bytes), v0(sv->bytes);
            if (!pk.read(*tr, t0.data()) || !pk.read(*su, u0.data()) || !pk.read(*sv, v0.data())) {
                err = pre + ": read failed";
                return false;
            }
            const size_t tile = tr->bytes / ((size_t) (m.k / 16) * (m.n / 16));
            std::vector<uint8_t> t1, u1, v1;
            if (cols) {   // the tiles [c0 / 16, (c0 + w) / 16) of each 16-row slice, svh [c0, c0 + w)
                const size_t c0 = (size_t) at, nt = (size_t) m.n / 16, nth = (size_t) w / 16;
                t1.resize((size_t) (m.k / 16) * nth * tile);
                for (size_t sl = 0; sl < (size_t) m.k / 16; ++sl)
                    std::memcpy(t1.data() + sl * nth * tile, t0.data() + (sl * nt + c0 / 16) * tile, nth * tile);
                u1 = u0;
                v1.assign(v0.begin() + (long) (c0 * 2), v0.begin() + (long) ((c0 + w) * 2));
                m.n = w;
            } else {      // the 16-row slices [r0 / 16, (r0 + w) / 16), suh [r0, r0 + w)
                const size_t r0 = (size_t) at, row = (size_t) (m.n / 16) * tile;
                t1.assign(t0.begin() + (long) (r0 / 16 * row), t0.begin() + (long) ((r0 + w) / 16 * row));
                u1.assign(u0.begin() + (long) (r0 * 2), u0.begin() + (long) ((r0 + w) * 2));
                v1 = v0;
                m.k = w;
            }
            uint32_t* dt = nullptr;
            uint16_t *ds = nullptr, *dv = nullptr;
            if (!dalloc(d, dt, t1.size() / 4, err, acct) || !dalloc(d, ds, u1.size() / 2, err, acct) ||
                !dalloc(d, dv, v1.size() / 2, err, acct))
                return false;
            cudaSetDevice(d.id);
            CK(cudaMemcpy(dt, t1.data(), t1.size(), cudaMemcpyHostToDevice));
            CK(cudaMemcpy(ds, u1.data(), u1.size(), cudaMemcpyHostToDevice));
            CK(cudaMemcpy(dv, v1.data(), v1.size(), cudaMemcpyHostToDevice));
            m.trellis = dt;
            m.suh = ds;
            m.svh = dv;
            return x3::supported(m) || (err = pre + ": a part not covered by the EXL3 kernels", false);
        }
        uint32_t* dt = nullptr;
        uint16_t *ds = nullptr, *dv = nullptr;
        if (!dalloc(d, dt, tr->bytes / 4, err, acct) || !dalloc(d, ds, su->bytes / 2, err, acct) ||
            !dalloc(d, dv, sv->bytes / 2, err, acct))
            return false;
        if (!upload(d, *tr, dt, err) || !upload(d, *su, ds, err) || !upload(d, *sv, dv, err)) return false;
        m.trellis = dt;
        m.suh = ds;
        m.svh = dv;
        if (!x3::supported(m)) {
            err = pre + ": k " + std::to_string(m.k) + " n " + std::to_string(m.n) + " K " + std::to_string(m.K) +
                  " not covered by the EXL3 kernels";
            return false;
        }
        return true;
    }
    // a float tensor (F32 / F16 / BF16) as F32 on the device
    bool f32(Dev& d, const std::string& name, float*& p, std::string& err, size_t* acct, size_t want = 0) {
        const Tensor* t = pk.get(name);
        if (t == nullptr) {
            err = name + ": not in the pack";
            return false;
        }
        std::vector<uint8_t> raw(t->bytes);
        if (!pk.read(*t, raw.data())) {
            err = name + ": read failed";
            return false;
        }
        size_t n = 0;
        std::vector<float> v;
        if (t->dtype == "F32") {
            n = t->bytes / 4;
            v.resize(n);
            std::memcpy(v.data(), raw.data(), t->bytes);
        } else if (t->dtype == "F16" || t->dtype == "BF16") {
            n = t->bytes / 2;
            v.resize(n);
            const uint16_t* s = (const uint16_t*) raw.data();
            for (size_t i = 0; i < n; ++i) v[i] = t->dtype == "F16" ? f16_to_f32(s[i]) : bf16_to_f32(s[i]);
        } else if (t->dtype == "Q8_0") {   // (a GGUF's router may come so)
            n = t->bytes / gg::kQ8Bytes * 32;
            v = q8_values(raw.data(), n);
        } else {
            err = name + ": dtype " + t->dtype + " is not a float";
            return false;
        }
        if (want != 0 && n != want) {
            err = name + ": " + std::to_string(n) + " values, expected " + std::to_string(want);
            return false;
        }
        if (!dalloc(d, p, n, err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(p, v.data(), n * 4, cudaMemcpyHostToDevice));
        return true;
    }
    // the router's weights (DS4_ROUTER_BF16, Project Maya #745's gate()): with the flag on, a BF16 tensor's rows go to
    // the device as they are - half an F32 copy's bytes, read twice a decoded token a layer (the gate and the next layer's
    // guesses), the same bits (the kernels widen each value exactly; router_check compares them at load); any other dtype,
    // or the flag off, the F32 copy as before (f32()).  DS4_ROUTER_BF16_PAD=1 (identity tests only): the bytes saved held
    // in an unused allocation, so the VRAM the experts are placed in, and so the placement, is the F32 copy's
    bool gate(Dev& d, const std::string& name, GateW& gw, std::string& err, size_t* acct, size_t want) {
        const Tensor* t = pk.get(name);
        if (router_bf16 == 0 || t == nullptr || t->dtype != "BF16") {
            float* p = nullptr;
            if (!f32(d, name, p, err, acct, want)) return false;
            gw.f = p;
            return true;
        }
        if (t->bytes != want * 2) {
            err = name + ": " + std::to_string(t->bytes / 2) + " values, expected " + std::to_string(want);
            return false;
        }
        std::vector<uint8_t> raw(t->bytes);
        if (!pk.read(*t, raw.data())) {
            err = name + ": read failed";
            return false;
        }
        uint16_t* p = nullptr;
        if (!dalloc(d, p, want, err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(p, raw.data(), t->bytes, cudaMemcpyHostToDevice));
        gw.h = p;
        ++router_bf16_n;
        if (router_pad) {   // (the F32 copy's other half, never read)
            uint16_t* pad = nullptr;
            if (!dalloc(d, pad, want, err, acct)) return false;
        }
        return true;
    }
    bool f16raw(Dev& d, const std::string& name, uint16_t*& p, std::string& err, size_t* acct) {
        const Tensor* t = pk.get(name);
        if (t != nullptr && (t->dtype == "F32" || t->dtype == "BF16" || t->dtype == "Q8_0")) {   // (a GGUF's)
            const size_t n = t->dtype == "Q8_0" ? t->bytes / gg::kQ8Bytes * 32 : t->bytes / (t->dtype == "F32" ? 4 : 2);
            std::vector<uint8_t> raw(t->bytes);
            if (!pk.read(*t, raw.data())) {
                err = name + ": read failed";
                return false;
            }
            const std::vector<float> q = t->dtype == "Q8_0" ? q8_values(raw.data(), n) : std::vector<float>();
            std::vector<uint16_t> h(n);
            for (size_t i = 0; i < n; ++i) {
                float v;
                if (t->dtype == "F32") std::memcpy(&v, raw.data() + i * 4, 4);
                else if (t->dtype == "Q8_0") v = q[i];
                else v = bf16_to_f32(((const uint16_t*) raw.data())[i]);
                h[i] = strata::kernels::f16_from_f32(v);
            }
            if (!dalloc(d, p, n, err, acct)) return false;
            cudaSetDevice(d.id);
            CK(cudaMemcpy(p, h.data(), n * 2, cudaMemcpyHostToDevice));
            return true;
        }
        if (t == nullptr || t->dtype != "F16") {
            err = name + ": not an F16 tensor in the pack";
            return false;
        }
        if (!dalloc(d, p, t->bytes / 2, err, acct)) return false;
        return upload(d, *t, p, err);
    }

    // The markov bias's head as Q8_0 blocks of 32 (34 B: F16 d + 32 int8) instead of F16 values: the same bias sums with the
    // quantisation's error, half the bytes the drafter's five markov steps read (66 MB -> 33 MB) and half the memory.  The
    // pack is untouched: the F32 / F16 / BF16 tensor is quantised as it is loaded.
    bool mk_head_q8(Dev& d, const std::string& name, uint8_t*& p, std::string& err, size_t* acct) {
        const Tensor* t = pk.get(name);
        if (t == nullptr || (t->dtype != "F32" && t->dtype != "F16" && t->dtype != "BF16")) {
            err = name + ": not an F32 / F16 / BF16 tensor";
            return false;
        }
        const size_t n = t->bytes / (t->dtype == "F32" ? 4 : 2);
        if (n == 0 || n % 32 != 0) {
            err = name + ": not a whole number of 32-value blocks";
            return false;
        }
        std::vector<uint8_t> raw(t->bytes);
        if (!pk.read(*t, raw.data())) {
            err = name + ": read failed";
            return false;
        }
        std::vector<float> v(n);
        for (size_t i = 0; i < n; ++i) {
            if (t->dtype == "F32") std::memcpy(&v[i], raw.data() + i * 4, 4);
            else v[i] = t->dtype == "F16" ? f16_to_f32(((const uint16_t*) raw.data())[i])
                                          : bf16_to_f32(((const uint16_t*) raw.data())[i]);
        }
        const size_t nb = n / 32;
        std::vector<uint8_t> q(nb * 34);
        for (size_t b = 0; b < nb; ++b) {
            const float* s = v.data() + b * 32;
            float amax = 0.0f;
            for (int i = 0; i < 32; ++i) amax = std::max(amax, std::fabs(s[i]));
            const float dd = amax > 0.0f ? amax / 127.0f : 0.0f;
            const uint16_t dh = strata::kernels::f16_from_f32(dd);
            std::memcpy(q.data() + b * 34, &dh, 2);
            int8_t* o = (int8_t*) (q.data() + b * 34 + 2);
            for (int i = 0; i < 32; ++i) {
                const float x = dd > 0.0f ? s[i] / dd : 0.0f;
                o[i] = (int8_t) std::max(-127.0f, std::min(127.0f, std::round(x)));
            }
        }
        if (!dalloc(d, p, nb * 34, err, acct)) return false;
        cudaSetDevice(d.id);
        CK(cudaMemcpy(p, q.data(), nb * 34, cudaMemcpyHostToDevice));
        return true;
    }

    size_t mat_bytes(const std::string& pre) const {
        if (const Tensor* t = pk.get(pre + ".weight")) return align256(t->bytes);
        size_t b = 0;
        for (const char* s : {".trellis", ".suh", ".svh"})
            if (const Tensor* t = pk.get(pre + s)) b += align256(t->bytes);
        return b;
    }    size_t tensor_bytes(const std::string& name) const {
        const Tensor* t = pk.get(name);
        return t ? align256(t->bytes * (t->dtype == "F32" ? 1 : 2)) : 0;
    }

    // ---- expert regions and blob layout
    // a GGUF's MXFP4 experts: the blob is gate | up | down ([out][in / 32] blocks each, as the file holds them), every
    // expert's matrix r at the same stride from expert 0's in one file (the GGUF's [n_exp][out][in] tensor)
    // (the other block types: lay.fmt stays kFmtMXFP4 - read in place as these - and lay.K[r] is role r's ggml type)
    static int gg_type_of(const std::string& dtype) {
        for (int t : {gg::kTypeMXFP4, 10, 11, 12, 13, 14, 16, 17, 18, 19, 20, 21, 22, 23, 29, 145, 146, 224, 225, 226, 227})
            if (dtype == gg::type_name(t)) return t;
        return -1;
    }
    bool expert_layout_mx(Layer& l, std::string& err) {
        const std::string P = l.name + "ffn.experts.";
        const char* parts[3] = {"w1", "w3", "w2"};   // gate, up, down
        size_t off = 0;
        for (int r = 0; r < 3; ++r) {
            const int n = r < 2 ? g.ff : g.dim, k = r < 2 ? g.dim : g.ff;
            const Tensor* t0 = pk.get(P + "0." + parts[r] + ".weight");
            const Tensor* t1 = l.n_exp > 1 ? pk.get(P + "1." + parts[r] + ".weight") : t0;
            const int ty = t0 != nullptr ? gg_type_of(t0->dtype) : -1;
            const size_t bytes = ty > 0 ? (size_t) n * gg::type_row_bytes(ty, k) : 0;
            if (t0 == nullptr || t1 == nullptr || bytes == 0 || t0->bytes != bytes) {
                err = P + "0." + parts[r] + ": not an MXFP4 or low-bit [" + std::to_string(n) + "][" + std::to_string(k) +
                      "] matrix the engine reads (" + (t0 != nullptr ? t0->dtype : std::string("missing")) + ")";
                return false;
            }
            l.mx_file[r] = t0->file;
            l.mx_off[r] = t0->off;
            l.mx_stride[r] = l.n_exp > 1 ? t1->off - t0->off : bytes;
            for (int e = 0; e < l.n_exp; ++e) {
                const Tensor* t = pk.get(P + std::to_string(e) + "." + parts[r] + ".weight");
                if (t == nullptr || t->dtype != t0->dtype || t->bytes != bytes || t->file != l.mx_file[r] ||
                    t->off != l.mx_off[r] + (uint64_t) e * l.mx_stride[r]) {
                    err = P + std::to_string(e) + "." + parts[r] + ": missing, or not where the layer's others are";
                    return false;
                }
            }
            l.lay.trellis[r] = off;
            l.lay.suh[r] = l.lay.svh[r] = off;
            l.lay.K[r] = ty;
            off += align256(bytes) + (store_gb() > 0 ? ExpertStore::kSlack : 0);   // (the store's aligned reads spill into the gaps)
        }
        l.lay.fmt = gg::kFmtMXFP4;
        if (!gg::mx_experts(l.lay) && (gg::expert_type(l.lay, 0) != gg::expert_type(l.lay, 1) ||
                                       gg::expert_type(l.lay, 0) == gg::kTypeMXFP4 ||
                                       gg::expert_type(l.lay, 2) == gg::kTypeMXFP4)) {
            err = P + ": gate / up / down of types " + gg::type_name(l.lay.K[0]) + " / " + gg::type_name(l.lay.K[1]) +
                  " / " + gg::type_name(l.lay.K[2]) + " (gate and up must match; MXFP4 does not mix with the others)";
            return false;
        }
        std::string why;   // (a layer the CPU lane cannot compute used to answer zeros for every pick it got there; Maya #620)
        if (!lane_fmt_ok(l, why)) {
            err = P + ": the CPU lane cannot compute experts of types " + gg::type_name(gg::expert_type(l.lay, 0)) + " / " +
                  gg::type_name(gg::expert_type(l.lay, 2)) + ": " + why;
            return false;
        }
        l.blob = off;
        // a type the device kernels do not take (none of the i-quants now: gg::type_on_device lists them): the layer stays on the CPU lane, where
        // ggml-cpu's row dots read it - one warning, then the placement code keeps it out of VRAM
        for (int r = 0; r < 3; ++r)
            if (!gg::type_on_device(l.lay.K[r])) {
                l.cpu_only = true;
#if defined(STRATA_METAL)
                static bool said = false;   // (a mixed pack has many such layers: one line, not one a layer)
                if (!said) {
                    said = true;
                    std::fprintf(stderr,
                                 "ds4: this pack has %s experts: no GPU kernel for that type, every such layer's "
                                 "experts stay on the CPU lane (ggml-cpu's rows; VRAM tier: none)\n",
                                 gg::type_name(l.lay.K[r]));
                }
#else
                std::fprintf(stderr,
                             "ds4: layer %d %s is %s: no GPU kernel for it, its experts stay on the CPU lane "
                             "(ggml-cpu's rows; VRAM tier: none)\n", l.il, r == 2 ? "down" : "gate/up",
                             gg::type_name(l.lay.K[r]));
#endif
                break;
            }
        return true;
    }
    // cpu_experts_mx / cpu_experts_iq take this layer's experts (the checks cpu_experts_iq makes before computing); `why`
    // if not.  (Project Maya e598716, #620.  expert_layout_mx already refuses MXFP4 mixed with another type, so a layer
    // here is all MXFP4 - cpu_experts_mx's own kernels - or low-bit gate / up / down through iq_cpu_fmt)
    bool lane_fmt_ok(const Layer& l, std::string& why) const {
        if (gg::mx_experts(l.lay)) return true;
        const int E = g.dim, FF = g.ff;
        gg::IqCpu fm;
        if (!gg::iq_cpu_fmt(gg::expert_type(l.lay, 0), gg::expert_type(l.lay, 2), E, FF, fm, why)) return false;
        if (fm.act_bytes > (size_t) E * 4 || fm.h_bytes > (size_t) E * 4) {
            why = "activation rows too large";
            return false;
        }
        return true;
    }
    const uint8_t* mx_mat(const Layer& l, int e, int r) const {   // expert e's matrix r: its RAM-tier slot, else the file's
        if (store) {
            const int s = store->find(l.il, e);
            if (s >= 0) return store->mat(s, r);
        }
        if (!l.ram.empty() && l.ram[(size_t) e] >= 0)   // (a copy with NH > 1: part 0's rows only - whole: read_mx)
            return copy_mode ? ram_part[(size_t) l.ram[(size_t) e]][0] + cp_lay[(size_t) l.il][(size_t) r]
                             : ram_slots[(size_t) l.ram[(size_t) e]] + l.lay.trellis[r];
        return pk.at(l.mx_file[r], l.mx_off[r] + (uint64_t) e * l.mx_stride[r]);
    }
    size_t mx_part_bytes(const Layer& l, int r) const {   // (its type's)
        return r < 2 ? (size_t) g.ff * gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim)
                     : (size_t) g.dim * gg::type_row_bytes(gg::expert_type(l.lay, 2), g.ff);
    }
    // (copy_mode) matrix r's rows, and the rows of one NUMA part of it
    int mx_n(int r) const { return r < 2 ? g.ff : g.dim; }
    size_t mx_row_b(const Layer& l, int r) const { return mx_part_bytes(l, r) / (size_t) mx_n(r); }
    // part X's rows [X n / NH, ..) of expert e's matrix r: its copy's part on node X, else where the file has them
    const uint8_t* mx_part_ptr(const Layer& l, int e, int r, int X) const {
        if (copy_mode && l.ram[(size_t) e] >= 0)
            return ram_part[(size_t) l.ram[(size_t) e]][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r];
        return mx_mat(l, e, r) + (size_t) X * (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
    }
    // a copy's NH parts -> the blob, and back (each matrix's rows of part X at X n / NH rows into the blob's matrix)
    void ram_to_blob(const Layer& l, int s, uint8_t* blob) const {
        for (int r = 0; r < 3; ++r) {
            const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
            for (int X = 0; X < NH; ++X)
                std::memcpy(blob + l.lay.trellis[r] + (size_t) X * nb, ram_part[(size_t) s][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r], nb);
        }
    }
    void blob_to_ram(const Layer& l, const uint8_t* blob, int s) const {
        for (int r = 0; r < 3; ++r) {
            const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
            for (int X = 0; X < NH; ++X)
                std::memcpy(ram_part[(size_t) s][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r], blob + l.lay.trellis[r] + (size_t) X * nb, nb);
        }
    }
    // expert e (from the file) -> its blob; and member m of nm's part of a blob (gate / up rows [m n_ff / nm, ..), down
    // inputs of the same range: in each row the blocks [m n_ff / nm / 32, ..)) and back
    bool read_mx(const Layer& l, int e, uint8_t* blob) const {   // (from its RAM-tier slot or copy when it has one)
        if (!l.ram.empty() && l.ram[(size_t) e] >= 0) {
            if (copy_mode) ram_to_blob(l, l.ram[(size_t) e], blob);
            else std::memcpy(blob, ram_slots[(size_t) l.ram[(size_t) e]], l.blob);
            return true;
        }
        return read_mx_file(l, e, blob);
    }
    bool read_mx_file(const Layer& l, int e, uint8_t* blob) const {   // (the movers: never a slot that may change)
        for (int r = 0; r < 3; ++r)
            if (!pk.read_at(l.mx_file[r], l.mx_off[r] + (uint64_t) e * l.mx_stride[r], mx_part_bytes(l, r),
                            blob + l.lay.trellis[r]))
                return false;
        return true;
    }
    // member m's part of expert e straight into dst in the member layout (l.hlay, as mx_blob_to_half writes it):
    // from its RAM copy / store / RAM-tier slot row by row (a third of the bytes read_mx copies), else the file's blob
    // through a scratch buffer.  The prompt path DMAs the result in 3 copies; the down's cudaMemcpy2DAsync out of the
    // whole blob was g.dim row copies of dh bytes each (HIP: one SDMA command a row, ~4,100 an expert) - the ~380 s
    // fixed cost of a --tp 3 prompt
    bool read_mx_member(const Layer& l, int e, int m, uint8_t* dst) const {
        const bool in_ram = (store && store->find(l.il, e) >= 0) || (!l.ram.empty() && l.ram[(size_t) e] >= 0);
        if (!in_ram) {
            thread_local std::vector<uint8_t> tmp;
            if (tmp.size() < l.blob) tmp.resize(l.blob);
            if (!read_mx_file(l, e, tmp.data())) return false;
            mx_blob_to_half(l, tmp.data(), m, dst);
            return true;
        }
        // (tp4: member m's own range [ff0, ff0 + ffn) and layout - an even split's are m n_ff / nm, n_ff / nm and
        //  member 0's hlay, as before)
        const Layer& x = member(l, m);
        auto row = [&](int r, size_t i) {   // (matrix r's row i, whichever NUMA part of a copy holds it)
            const size_t per = (size_t) (mx_n(r) / NH), X = std::min<size_t>(i / per, (size_t) NH - 1);
            return mx_part_ptr(l, e, r, (int) X) + (i - X * per) * mx_row_b(l, r);
        };
        const size_t dh = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ffn),
                     d0 = gg::type_row_bytes(gg::expert_type(l.lay, 2), x.ff0);
        for (int r = 0; r < 2; ++r) {
            const size_t gr = gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim);
            for (size_t i = 0; i < (size_t) x.ffn; ++i)
                std::memcpy(dst + x.hlay.trellis[r] + i * gr, row(r, (size_t) x.ff0 + i), gr);
        }
        for (size_t i = 0; i < (size_t) g.dim; ++i)
            std::memcpy(dst + x.hlay.trellis[2] + i * dh, row(2, i) + d0, dh);
        return true;
    }
    // (tp4) member m's part of matrix r of an expert, as the members' range math sees it: gate / up rows
    // [ff0, ff0 + ffn) - offset and length in the matrix; the down's d0 / dh bytes of each row (dr bytes a row)
    struct MxCut { size_t gr[2], d0, dh, dr; int ff0, ffn; };
    MxCut mx_cut(const Layer& l, int m) const {
        const Layer& x = member(l, m);
        const int t2 = gg::expert_type(l.lay, 2);
        MxCut c{};
        for (int r = 0; r < 2; ++r) c.gr[r] = gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim);
        c.d0 = gg::type_row_bytes(t2, x.ff0);
        c.dh = gg::type_row_bytes(t2, x.ffn);
        c.dr = gg::type_row_bytes(t2, g.ff);
        c.ff0 = x.ff0;
        c.ffn = x.ffn;
        return c;
    }
    // DS4_TP_DIRECT: the prompt's tensor-parallel stream without the readers' host copy.  The copied experts are pinned
    // (and mapped) at load when a layer is tensor parallel (load_experts_mx); a member's part of an expert in that copy is
    // then sent from where it lies: gate and up are its ff / nm contiguous rows of each, one DMA each; the down's part is
    // dh bytes of each of g.dim rows of dr, which as a 2D DMA is one SDMA command a row (the ~380 s bug of 9f072683), so
    // a kernel gathers it from the mapped copy (mode 2, the default) or it goes through the staging alone (mode 1).
    // The bytes that reach the ring slot are read_mx_member's.  DS4_TP_DIRECT=0: the staging path for every expert.
    static int tp_direct_env() {
        static const int v = std::getenv("DS4_TP_DIRECT") ? std::atoi(std::getenv("DS4_TP_DIRECT")) : -1;
        return v;
    }
    int tp_direct_mode() const {
        if (!ram_pinned || pin_ranges.empty()) return 0;
        const int v = tp_direct_env();
        return v < 0 ? 2 : std::max(0, std::min(v, 2));
    }
    // the pinned range [base, base + n) holding p .. p + len (-1: none)
    int pin_range(const void* p, size_t len) const {
        const uintptr_t a = (uintptr_t) p;
        auto it = std::upper_bound(pin_ranges.begin(), pin_ranges.end(), a,
                                   [](uintptr_t v, const std::pair<uintptr_t, size_t>& r) { return v < r.first; });
        if (it == pin_ranges.begin()) return -1;
        --it;
        return a + len <= it->first + it->second ? (int) (it - pin_ranges.begin()) : -1;
    }
    bool tp_direct_ok(const Layer& l, int e) const {
        if (!copy_mode || NH != 1 || shared_store || l.nm < 2 || l.ram.empty() || l.ram[(size_t) e] < 0) return false;
        if (store && store->find(l.il, e) >= 0) return false;   // (read_mx_member's order: the store first)
        if (mx_row_b(l, 0) != mx_row_b(l, 1)) return false;    // (gate and up rows of one size, as read_mx_member copies)
        const uint8_t* p = ram_part[(size_t) l.ram[(size_t) e]][0];
        return pin_range(p, cp_lay[(size_t) l.il][3]) >= 0;
    }
    // mode 1: the down's part of member m into dst at l.hlay.trellis[2], as read_mx_member writes it
    void read_mx_member_down(const Layer& l, int e, int m, uint8_t* dst) const {
        const MxCut k = mx_cut(l, m);   // (tp4: the member's own range and layout)
        const size_t dr = mx_row_b(l, 2);
        const uint8_t* d0 = mx_part_ptr(l, e, 2, 0);
        for (size_t i = 0; i < (size_t) g.dim; ++i)
            std::memcpy(dst + member(l, m).hlay.trellis[2] + i * k.dh, d0 + i * dr + k.d0, k.dh);
    }
    // the device's address of pinned host p (the range's mapping on the current device, looked up once)
    const uint8_t* pin_dev_ptr(const uint8_t* p, int dev_id) const {
        const int r = pin_range(p, 1);
        if (r < 0 || dev_id < 0 || dev_id >= 16) return nullptr;
        std::atomic<uintptr_t>& slot = pin_dev[(size_t) r * 16 + (size_t) dev_id];
        uintptr_t b = slot.load(std::memory_order_relaxed);
        if (b == 0) {
            void* dp = nullptr;
            if (cudaHostGetDevicePointer(&dp, (void*) pin_ranges[(size_t) r].first, 0) != cudaSuccess || dp == nullptr) {
                (void) cudaGetLastError();
                return nullptr;
            }
            b = (uintptr_t) dp;
            slot.store(b, std::memory_order_relaxed);
        }
        return (const uint8_t*) (b + ((uintptr_t) p - pin_ranges[(size_t) r].first));
    }
    // member m's part of expert e (tp_direct_ok) -> its ring slot dst on copy stream cs; `sb`: its staging slot (mode 1)
    bool stream_member_direct(const Layer& l, int m, int e, uint8_t* dst, cudaStream_t cs, int mode, const uint8_t* sb,
                              std::string& err) {
        // (tp4: the member's own range [ff0, ff0 + ffn) and layout; tp_direct_ok holds gate / up rows of one size)
        const MxCut k = mx_cut(l, m);
        const x3::ExpertLayout& hl = member(l, m).hlay;
        const size_t gr = mx_row_b(l, 0), dh = k.dh, dr = mx_row_b(l, 2);
        bool ok = true;
        for (int r = 0; r < 2; ++r)
            ok = ok && cudaMemcpyAsync(dst + hl.trellis[r], mx_part_ptr(l, e, r, 0) + (size_t) k.ff0 * gr, (size_t) k.ffn * gr,
                                       cudaMemcpyHostToDevice, cs) == cudaSuccess;
        if (ok && mode == 1)
            ok = sb != nullptr && cudaMemcpyAsync(dst + hl.trellis[2], sb + hl.trellis[2], (size_t) g.dim * dh,
                                                  cudaMemcpyHostToDevice, cs) == cudaSuccess;
        else if (ok) {
            int dev = 0;
            cudaGetDevice(&dev);
            const uint8_t* src = pin_dev_ptr(mx_part_ptr(l, e, 2, 0), dev);
            ok = src != nullptr;
            if (ok) tp_strided_rows(dst + hl.trellis[2], dh, src + k.d0, dr, dh, g.dim, cs);
            ok = ok && cudaPeekAtLastError() == cudaSuccess;
        }
        if (!ok) err = "streaming layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " (direct) failed";
        return ok;
    }
    // (l the group's first member: member m's own range [ff0, ff0 + ffn) and its own layout - whole blocks of the down's
    //  inputs, even or not; tp4 after Project Maya e3f2475)
    void mx_blob_to_half(const Layer& l, const uint8_t* blob, int m, uint8_t* dst) const {
        const MxCut k = mx_cut(l, m);
        const x3::ExpertLayout& hl = member(l, m).hlay;
        for (int r = 0; r < 2; ++r)
            std::memcpy(dst + hl.trellis[r], blob + l.lay.trellis[r] + (size_t) k.ff0 * k.gr[r], (size_t) k.ffn * k.gr[r]);
        for (size_t row = 0; row < (size_t) g.dim; ++row)
            std::memcpy(dst + hl.trellis[2] + row * k.dh, blob + l.lay.trellis[2] + row * k.dr + k.d0, k.dh);
    }
    void mx_half_to_blob(const Layer& l, const uint8_t* src, int m, uint8_t* blob) const {
        const MxCut k = mx_cut(l, m);
        const x3::ExpertLayout& hl = member(l, m).hlay;
        for (int r = 0; r < 2; ++r)
            std::memcpy(blob + l.lay.trellis[r] + (size_t) k.ff0 * k.gr[r], src + hl.trellis[r], (size_t) k.ffn * k.gr[r]);
        for (size_t row = 0; row < (size_t) g.dim; ++row)
            std::memcpy(blob + l.lay.trellis[2] + row * k.dr + k.d0, src + hl.trellis[2] + row * k.dh, k.dh);
    }

    bool expert_layout(Layer& l, std::string& err) {
        if (const Tensor* t = pk.get(l.name + "ffn.experts.0.w1.weight"); t != nullptr && gg_type_of(t->dtype) > 0)
            return expert_layout_mx(l, err);
        const std::string P = l.name + "ffn.experts.";
        const char* parts[3] = {"w1", "w3", "w2"};   // gate, up, down
        const char* pieces[3] = {".trellis", ".suh", ".svh"};
        l.region_off.resize((size_t) l.n_exp);
        l.region_bytes.resize((size_t) l.n_exp);
        l.region_file.resize((size_t) l.n_exp);
        size_t off = 0;
        for (int r = 0; r < 3; ++r) {
            const Tensor* tr = pk.get(P + "0." + parts[r] + ".trellis");
            if (tr == nullptr || pk.get(P + "0." + parts[r] + ".mul1") == nullptr) {
                err = P + "0." + parts[r] + ": not an EXL3 (mul1) matrix";
                return false;
            }
            l.lay.K[r] = (int) tr->shape[2] / 16;
            l.lay.trellis[r] = off;
            off += align256(tr->bytes);
            l.lay.suh[r] = off;
            off += align256(pk.get(P + "0." + parts[r] + ".suh")->bytes);
            l.lay.svh[r] = off;
            off += align256(pk.get(P + "0." + parts[r] + ".svh")->bytes);
        }
        l.lay.cb = 2;
        l.blob = off;
        for (int e = 0; e < l.n_exp; ++e) {
            const std::string E = P + std::to_string(e) + ".";
            uint64_t lo = UINT64_MAX, hi = 0;
            int file = -1;
            for (int r = 0; r < 3; ++r)
                for (int q = 0; q < 3; ++q) {
                    const Tensor* t = pk.get(E + parts[r] + pieces[q]);
                    if (t == nullptr) {
                        err = E + parts[r] + pieces[q] + ": missing";
                        return false;
                    }
                    if (file < 0) file = t->file;
                    if (t->file != file) {
                        err = E + ": split across files";
                        return false;
                    }
                    lo = std::min(lo, t->off);
                    hi = std::max(hi, t->off + t->bytes);
                    if (e == 0) l.piece_bytes[r][q] = t->bytes;
                    else if (t->bytes != l.piece_bytes[r][q]) {
                        err = E + parts[r] + ": not the shape of expert 0's";
                        return false;
                    }
                }
            l.region_off[(size_t) e] = lo;
            l.region_bytes[(size_t) e] = hi - lo;
            l.region_file[(size_t) e] = file;
            for (int r = 0; r < 3; ++r)
                for (int q = 0; q < 3; ++q) {
                    const size_t src = pk.get(E + parts[r] + pieces[q])->off - lo;
                    if (e == 0) l.piece_src[r][q] = src;
                    else if (src != l.piece_src[r][q]) {
                        err = E + ": the pieces lie differently from expert 0's";
                        return false;
                    }
                }
        }
        return true;
    }
    // the region of expert e (read from the file) -> its blob
    void repack(const Layer& l, const uint8_t* region, uint8_t* blob) const {
        for (int r = 0; r < 3; ++r) {
            const size_t dst[3] = {l.lay.trellis[r], l.lay.suh[r], l.lay.svh[r]};
            for (int q = 0; q < 3; ++q) std::memcpy(blob + dst[q], region + l.piece_src[r][q], l.piece_bytes[r][q]);
        }
    }

    // the region of expert e -> its CPU-lane part X (columns [X n / NH, (X + 1) n / NH) of each matrix)
    void repack_part(const Layer& l, const uint8_t* region, int X, uint8_t* dst) const {
        for (int r = 0; r < 3; ++r) {
            const size_t tile = (size_t) 32 * l.lay.K[r];
            const int k = l.hl.k[r], nt = l.hl.n[r] * NH / 16, nth = l.hl.n[r] / 16;
            const uint8_t* tr = region + l.piece_src[r][0];
            for (int sl = 0; sl < k / 16; ++sl)
                std::memcpy(dst + l.hl.trellis[r] + (size_t) sl * nth * tile, tr + ((size_t) sl * nt + (size_t) X * nth) * tile,
                            (size_t) nth * tile);
            std::memcpy(dst + l.hl.suh[r], region + l.piece_src[r][1], (size_t) k * 2);
            std::memcpy(dst + l.hl.svh[r], region + l.piece_src[r][2] + (size_t) X * l.hl.n[r] * 2, (size_t) l.hl.n[r] * 2);
        }
    }

    // ---- loading
    // ---- the decode fusions' flags (see hc_fuse).  An integer 0 .. maxv, or unset; -1 and err for anything else
    static int fuse_env(const char* name, int maxv, bool& set, std::string& err) {
        const char* v = std::getenv(name);
        set = v != nullptr;
        if (v == nullptr) return 0;
        char* end = nullptr;
        const long b = std::strtol(v, &end, 10);
        if (*v == 0 || end == nullptr || *end != 0 || b < 0 || b > maxv) {
            err = std::string(name) + "=" + v + ": an integer 0 .. " + std::to_string(maxv);
            return -1;
        }
        return (int) b;
    }
    bool fuse_flags(std::string& err) {
        bool wave32 = true;   // (the fused kernels' warp roundings and reductions are a 32-lane warp's: every layer device)
        for (const Dev& d : devs) {
            cudaDeviceProp p{};
            if (cudaGetDeviceProperties(&p, d.id) != cudaSuccess || p.warpSize != 32) wave32 = false;
        }
        (void) cudaGetLastError();
#if defined(STRATA_METAL)
        wave32 = false;   // (no Metal kernels for them)
#endif
        hc_fuse = fuse_env("DS4_HC_FUSE", 2, hc_fuse_set, err);
        if (hc_fuse < 0) return false;
        if (hc_fuse > 0 && (!wave32 || !pk.gguf || g.dim < 32 || g.dim % 32 != 0 || g.dim > 8 * 1024 || g.hc < 1 || g.hc > 8 ||
                            (2 + g.hc) * g.hc > 32)) {
            err = "DS4_HC_FUSE=" + std::to_string(hc_fuse) +
                  ": not this build / model (wave32 layer devices, a GGUF pack, dim a multiple of 32 up to 8192, hc <= 4)";
            return false;
        }
        if (hc_fuse > 0)
            std::fprintf(stderr, "ds4: DS4_HC_FUSE=%d: a decoded token's HC mix, split and norm in one launch, its x rounded to "
                                 "int8 there for the attention's and the shared expert's GEMVs, the pre copy by the FFN split%s "
                                 "(Project Maya #511; checked at load)\n",
                         hc_fuse, hc_fuse > 1 ? "; a window's rows too" : "");
        else if (hc_fuse_set)
            std::fprintf(stderr, "ds4: DS4_HC_FUSE=0: its buffers allocated, the old launches\n");
        bool rf_set = false;
        route_fuse = fuse_env("DS4_ROUTE_FUSE", 2, rf_set, err);
        if (route_fuse < 0) return false;
        if (route_fuse > 0 && !wave32) {
            err = "DS4_ROUTE_FUSE=" + std::to_string(route_fuse) + ": not on this build's devices (wave32 layer devices)";
            return false;
        }
        if (route_fuse > 0 && ahead_mode > 1) {   // (Maya's fuse pairs one layer of guesses; depth 2 is another shape)
            err = "DS4_ROUTE_FUSE=" + std::to_string(route_fuse) + " takes one layer of lookahead (DS4_AHEAD 1), not " +
                  std::to_string(ahead_mode);
            return false;
        }
        if (route_fuse > 0)
            std::fprintf(stderr, "ds4: DS4_ROUTE_FUSE=%d: a decoded token's router stage on the lead in two launches - its gate and "
                                 "the next layer's, then the routing and the guesses%s (Project Maya #511; checked at load)%s\n",
                         route_fuse, route_fuse > 1 ? "; a window's rows too" : "",
                         ahead_mode == 1 ? "" : " - inactive while DS4_AHEAD is 0 (no guesses to pair)");
        bool rb_set = false, pad_set = false, chk_set = false;
        router_bf16 = fuse_env("DS4_ROUTER_BF16", 1, rb_set, err);
        if (router_bf16 < 0) return false;
        const int pad = fuse_env("DS4_ROUTER_BF16_PAD", 1, pad_set, err);
        if (pad < 0) return false;
        const int chk = fuse_env("DS4_ROUTER_CHECK", 1, chk_set, err);
        if (chk < 0) return false;
        router_pad = pad == 1;
        router_chk = !chk_set || chk == 1;
#if defined(STRATA_METAL)
        if (router_bf16 > 0) {
            err = "DS4_ROUTER_BF16=1: no Metal kernel for a BF16 router";
            return false;
        }
#endif
        if (router_bf16 > 0)
            std::fprintf(stderr, "ds4: DS4_ROUTER_BF16=1: a BF16 router stays BF16 on the GPUs (half its bytes a read, the same "
                                 "bits%s)%s (Project Maya #745)\n",
                         router_chk ? ": checked at load" : "; DS4_ROUTER_CHECK=0: not checked",
                         router_pad ? "; DS4_ROUTER_BF16_PAD=1: the bytes saved held unused, the F32 copy's expert placement" : "");
        decode_trim = fuse_env("DS4_DECODE_TRIM", 15, decode_trim_set, err);
        if (decode_trim < 0) return false;
        if (decode_trim & 8) {
            err = "DS4_DECODE_TRIM=" + std::to_string(decode_trim) +
                  ": bit 8 (Maya's drafter hand-offs between cards) is not ported - our drafter's blocks share one card; bits 1 2 4";
            return false;
        }
        if ((decode_trim & 3) && (!wave32 || !pk.gguf || g.ff % 32 != 0 || g.q_lora % 32 != 0)) {
            err = "DS4_DECODE_TRIM=" + std::to_string(decode_trim) +
                  ": bits 1 / 2 not on this build / model (wave32 layer devices, a GGUF pack, ff and q_lora multiples of 32)";
            return false;
        }
        if ((decode_trim & 4) && !wave32) {
            err = "DS4_DECODE_TRIM=" + std::to_string(decode_trim) + ": bit 4 not on this build (no kernel)";
            return false;
        }
        if (decode_trim != 0)
            std::fprintf(stderr, "ds4: DS4_DECODE_TRIM=%d:%s%s%s (Project Maya #512; checked at load)\n", decode_trim,
                         decode_trim & 1 ? " the shared expert's swiglu rounds s2's int8 input;" : "",
                         decode_trim & 2 ? " q's norm rounds wq_b's int8 input;" : "",
                         decode_trim & 4 ? " the latent / snapshot copies one kernel each;" : "");
        else if (decode_trim_set)
            std::fprintf(stderr, "ds4: DS4_DECODE_TRIM=0: its buffers allocated, the old launches\n");
        // leadpath (docs/dsv41/cards/HX-21.md; each default off, each exact by construction)
        bool lps = false;
        lp_route = fuse_env("DS4_LP_ROUTE", 1, lps, err) == 1;
        if (!err.empty()) return false;
        lp_pubfuse = fuse_env("DS4_LP_PUBFUSE", 1, lps, err) == 1;
        if (!err.empty()) return false;
        lp_joincomb = fuse_env("DS4_LP_JOINCOMB", 1, lps, err) == 1;
        if (!err.empty()) return false;
        if ((lp_route || lp_pubfuse) && !wave32) {
            err = "DS4_LP_ROUTE / DS4_LP_PUBFUSE: not on this build's devices (wave32 layer devices)";
            return false;
        }
        if (lp_route || lp_pubfuse)
            std::fprintf(stderr, "ds4: leadpath:%s%s (checked at load)%s\n",
                         lp_route ? " DS4_LP_ROUTE=1: the routing's top k per warp, merged by one warp;" : "",
                         lp_pubfuse ? " DS4_LP_PUBFUSE=1: a one-row request published by the routing's own launch;" : "",
                         route_fuse > 0 && ahead_mode == 1 ? " - the lead's DS4_ROUTE_FUSE pair path keeps its launches (DS4_AHEAD=0 "
                                                             "puts the lead on the routing these change)" : "");
        if (lp_joincomb)
            std::fprintf(stderr, "ds4: leadpath: DS4_LP_JOINCOMB=1: the lead's device-direct join and its combine in one launch "
                                 "(with DS4_HELPER_DD; exact by construction)\n");
        bool ap_set = false, am_set = false;   // (FG-07)
        ar_post = fuse_env("DS4_AR_POST", 3, ap_set, err);
        if (ar_post < 0) return false;
        if (ar_post > 0 && (!wave32 || g.dim % 4 != 0 || g.hc < 1 || g.hc > 8)) {
            err = "DS4_AR_POST=" + std::to_string(ar_post) + ": not this build / model (wave32 layer devices, dim % 4, hc <= 8)";
            return false;
        }
        if (ar_post > 0)
            std::fprintf(stderr, "ds4: DS4_AR_POST=%d: a window's all-reduce on the one-phase host path with%s%s folded into the "
                                 "sum kernel (checked at load)\n",
                         ar_post, ar_post & 1 ? " hc_post" : "", ar_post & 2 ? (ar_post & 1 ? " and the put" : " the put") : "");
        attn_merge = fuse_env("DS4_ATTN_MERGE", 3, am_set, err);
        if (attn_merge < 0) return false;
        if (attn_merge > 0 && !wave32) {
            err = "DS4_ATTN_MERGE=" + std::to_string(attn_merge) + ": not on this build's devices (wave32 layer devices)";
            return false;
        }
        if (attn_merge > 0)
            std::fprintf(stderr, "ds4: DS4_ATTN_MERGE=%d: a decoded token's q norm + ring rows + KV finish in one launch, q RoPE + "
                                 "the ring's new row in another%s (checked at load)\n",
                         attn_merge, attn_merge > 1 ? "; a window's rows too" : "");
        if (attn_merge > 2)   // (DS4_ATTN_MERGE=3, FG-16 item 3)
            std::fprintf(stderr, "ds4: DS4_ATTN_MERGE=3: sparse_attn's unpack of the selected rows in the second merged launch "
                                 "(layers whose selection and compressed rows are final there; checked at load)\n");
        eg_split = fuse_env("DS4_EG_SPLIT", 1, eg_split_set, err);
        if (eg_split < 0) return false;
        if (eg_split_set)
            std::fprintf(stderr, "ds4: DS4_EG_SPLIT=%d: %s (prep-loose-ends)\n", eg_split,
                         eg_split ? "a decoded token's Engram GEMV split by rows over the tensor-parallel group, gathered by its "
                                    "all-reduce (the same bits)"
                                  : "its buffer allocated, the old launches");
        eg_ahead = fuse_env("DS4_EG_AHEAD", 1, eg_ahead_set, err);
        if (eg_ahead < 0) return false;
        if (eg_ahead_set) {
            if (pk.eg_layers > Dev::kEgAh || g.eg_layers.size() > (size_t) Dev::kEgAh) {
                err = "DS4_EG_AHEAD: " + std::to_string(g.eg_layers.size()) + " Engram layers, at most " + std::to_string(Dev::kEgAh);
                return false;
            }
            eg_ah_trig.assign(g.eg_layers.size(), -1);   // (the first: the layer before it; each later: the Engram layer before it)
            for (size_t e = 0; e < g.eg_layers.size(); ++e)
                eg_ah_trig[e] = e == 0 ? g.eg_layers[0] - 1 : g.eg_layers[e - 1];
            for (size_t e = 0; e < g.eg_layers.size(); ++e)   // (ids not ascending: that layer keeps the old path)
                if (eg_ah_trig[e] >= g.eg_layers[e]) eg_ah_trig[e] = -1;
            std::fprintf(stderr, "ds4: DS4_EG_AHEAD=%d: %s (prep-l8egahead)\n", eg_ahead,
                         eg_ahead ? "each Engram layer's chain (H2D, dequant, GEMV) on a side stream one Engram trigger ahead, "
                                    "the gate waiting on its event (the same bits; with DS4_EG_SPLIT the slice ahead, the "
                                    "all-gather in place)"
                                  : "its side stream and buffers made, the old launches");
        }
        topk_mb = fuse_env("DS4_TOPK_MB", 1, topk_mb_set, err);
        if (topk_mb < 0) return false;
        if (const char* v = std::getenv("DS4_TOPK_MB_MIN")) {
            char* end = nullptr;
            const long b = std::strtol(v, &end, 10);
            if (*v == 0 || end == nullptr || *end != 0 || b < 1 || b > (1L << 30)) {
                err = std::string("DS4_TOPK_MB_MIN=") + v + ": an integer 1 .. 2^30";
                return false;
            }
            topk_mb_min = (int) b;
        }
        if (topk_mb > 0 && !wave32) {
            err = "DS4_TOPK_MB=1: not this build (wave32 layer devices: its scan is a 32-lane warp's, as topk_kernel's)";
            return false;
        }
        if (topk_mb > 0)
            std::fprintf(stderr, "ds4: DS4_TOPK_MB=1: the decode path's indexer top-k over n >= %d scores on up to %d workgroups "
                                 "a row (the same k-th key, ties to the lowest positions, picks in index order: the same bits; "
                                 "checked at load) (prep-topkmb)\n",
                         topk_mb_min, kTopkMbMaxG);
        else if (topk_mb_set)
            std::fprintf(stderr, "ds4: DS4_TOPK_MB=0: its scratch allocated, the old launches (prep-topkmb)\n");
        {   // xtxkern (build 14: DS4_XK_QO only)
            bool s6 = false, s7 = false;
            xk_qo = fuse_env("DS4_XK_QO", 1, s6, err);
            if (xk_qo < 0) return false;
            xk_qa = fuse_env("DS4_XK_QA", 1, s7, err);   // (FG-16)
            if (xk_qa < 0) return false;
            if (xk_qo || xk_qa) {
                bool gfx1100 = wave32;   // (the kernels exist only in the gfx1100 code object)
#if defined(STRATA_USE_HIP)
                for (const Dev& d : devs) {
                    cudaDeviceProp p{};
                    if (cudaGetDeviceProperties(&p, d.id) != cudaSuccess || std::strncmp(p.gcnArchName, "gfx1100", 7) != 0)
                        gfx1100 = false;
                }
                (void) cudaGetLastError();
#else
                gfx1100 = false;
#endif
                if (!gfx1100) {
                    err = "DS4_XK_*: not on this build's devices (gfx1100 layer devices only)";
                    return false;
                }
                if (xk_qo && !hc_fuse_set) {
                    err = "DS4_XK_QO needs DS4_HC_FUSE set (=0 too: its int8 rows hold the roundings)";
                    return false;
                }
                if (xk_qa && !hc_fuse_set) {
                    err = "DS4_XK_QA needs DS4_HC_FUSE set (=0 too: its int8 rows hold the roundings)";
                    return false;
                }
                xk_set(xk_qa ? kXkQa : 0);   // (FG-16: xk_mv_q5k_q8 launches only with kXkQa set)
                std::fprintf(stderr, "ds4: xtxkern roundings:%s%s (bit-identical by construction; the id phase and the bench compare)\n",
                             xk_qo ? " DS4_XK_QO=1: the o finish rounds wo_a's input;" : "",
                             xk_qa ? " DS4_XK_QA=1: wo_a's GEMV rounds wo_b's input;" : "");
            }
        }
        {   // DS4_BT_FUSE (fusion plan F2; after DS4_AR_POST / DS4_ATTN_MERGE / DS4_XK_QO, which it applies to the batch path)
            bool bfs = false;
            bt_fuse = fuse_env("DS4_BT_FUSE", 1, bfs, err);
            if (bt_fuse < 0) return false;
            if (bt_fuse > 0) {
                bool gfx1100 = wave32;   // (bt_fin_kernel exists only in the gfx1100 code object)
#if defined(STRATA_USE_HIP)
                for (const Dev& d : devs) {
                    cudaDeviceProp p{};
                    if (cudaGetDeviceProperties(&p, d.id) != cudaSuccess || std::strncmp(p.gcnArchName, "gfx1100", 7) != 0)
                        gfx1100 = false;
                }
                (void) cudaGetLastError();
#else
                gfx1100 = false;
#endif
                if (!gfx1100) {
                    err = "DS4_BT_FUSE: not on this build's devices (gfx1100 layer devices only)";
                    return false;
                }
                std::fprintf(stderr, "ds4: DS4_BT_FUSE=1: a batch window's attention takes the solo fusions that are set:%s%s%s%s "
                                     "(batch windows only - DS4_BATCH_DECODE; checked at load)\n",
                             ar_post > 0 ? " DS4_AR_POST's folded all-reduce;" : "",
                             attn_merge > 0 ? " DS4_ATTN_MERGE's two merged launches over the DS4_MULTI_ATTN runs;" : "",
                             attn_merge > 2 ? " =3's unpack in the second;" : "",
                             xk_qo ? " DS4_XK_QO's o finish rounding wo_a's input;" : "");
                if (ar_post <= 0 && attn_merge <= 0 && !xk_qo)
                    std::fprintf(stderr, "ds4: DS4_BT_FUSE=1: none of DS4_AR_POST / DS4_ATTN_MERGE / DS4_XK_QO is set - nothing "
                                         "to apply, the batch path as before\n");
            }
        }
        topk_mb_batch = fuse_env("DS4_TOPK_MB_BATCH", 1, topk_mb_batch_set, err);   // (FG-11)
        if (topk_mb_batch < 0) return false;
        if (topk_mb_batch > 0 && topk_mb <= 0) {
            err = "DS4_TOPK_MB_BATCH=1 needs DS4_TOPK_MB=1 (its scratch and its load check)";
            return false;
        }
        if (topk_mb_batch > 0)
            std::fprintf(stderr, "ds4: DS4_TOPK_MB_BATCH=1: the batch windows' indexer top-k (a bank's run) over n >= %d scores on "
                                 "the multi-block path too (the same bits) (prep-leads2 topkbatch)\n", topk_mb_min);
        else if (topk_mb_batch_set)
            std::fprintf(stderr, "ds4: DS4_TOPK_MB_BATCH=0: the batch windows keep the one-workgroup top-k (prep-leads2 topkbatch)\n");
        return true;
    }
    // the flags' load-time checks, at the end of load (every buffer and expert placed; no request yet).  Each compares the
    // new launches with the old ones byte for byte on the real weights and devices; any difference fails the load
    bool fuse_checks(std::string& err) {
        bool ran = false;
        if (hc_fuse > 0) {
            ran = true;
            if (!hc_fuse_check(err, 1) || (hc_fuse > 1 && !hc_fuse_check(err, kWin))) return false;
        }
        if (route_fuse > 0) {
            ran = true;
            if (!route_fuse_check(err, 1) || (route_fuse > 1 && !(route_fuse_check(err, 3) && route_fuse_check(err, kWin))))
                return false;
        }
        if (lp_route || lp_pubfuse) {   // leadpath
            ran = true;
            if (!lp_route_check(err, 1) || !lp_route_check(err, 3) || !lp_route_check(err, kWin)) return false;
        }
        if (router_bf16 > 0) {
            std::fprintf(stderr, "ds4: DS4_ROUTER_BF16: %d routers (every member's) kept BF16\n", router_bf16_n);
            if (router_chk && router_bf16_n > 0) {
                ran = true;
                if (!router_check(err)) return false;
            }
        }
        if (decode_trim & 3) {
            ran = true;
            if (!trim_q8_check(err)) return false;
        }
        if (decode_trim & 4) {
            ran = true;
            if (!trim_copy_check(err)) return false;
        }
        if (ar_post > 0) {   // (FG-07)
            ran = true;
            if (!ar_post_check(err, 1) || !ar_post_check(err, kWin)) return false;
        }
        if (attn_merge > 0) {
            ran = true;
            if (!attn_merge_check(err, 1) || (attn_merge > 1 && !attn_merge_check(err, kWin))) return false;
            if (attn_merge > 2 && (!attn_merge3_check(err, 1) || !attn_merge3_check(err, kAttnScratchT))) return false;
        }
        if (bt_fuse > 0 && (attn_merge > 0 || xk_qo)) {   // (DS4_BT_FUSE; its AR_POST part is ar_post_check's, above)
            ran = true;
            if (!bt_fuse_check(err, 2) || !bt_fuse_check(err, kWin)) return false;
        }
        if (topk_mb > 0) {   // (FG-10)
            ran = true;
            if (!topk_mb_check(err)) return false;
        }
        if (!ran) return true;   // (every flag off: nothing enqueued, as before)
        for (Dev& d : devs) {   // (the checks ran on each device's stream; their buffers are freed)
            cudaSetDevice(d.id);
            CK(cudaStreamSynchronize(d.st));
        }
        return true;
    }

    bool load(const Options& opt, std::string& err) {
        o = opt;
        // STRATA_DS4_DIAG_RESERVE_MIB=N leaves N MiB more free on each GPU (added to --reserve-mib, which sizes the experts' slots
        // everywhere) - a lazy module load after the experts filled the memory then has room (H2)
        if (diag_enabled() && std::getenv("STRATA_DS4_DIAG_RESERVE_MIB") != nullptr) {
            o.reserve_mib += std::atoll(std::getenv("STRATA_DS4_DIAG_RESERVE_MIB"));
            std::fprintf(stderr, "DIAG: reserve %lld MiB per GPU (--reserve-mib + STRATA_DS4_DIAG_RESERVE_MIB)\n", (long long) o.reserve_mib);
        }
        const double t0 = now_ms();
        if (!pk.load(o.pack, err)) return false;
        g.from(pk);
        if (g.dim == 0 || g.nl == 0 || (int) g.ratios.size() < g.nl) {
            err = o.pack + "/ds4.txt: incomplete geometry";
            return false;
        }
        if (g.hd != 512 || g.ix_hd != 128 || g.k_exp > 8 || g.hc > 8) {
            err = "geometry not covered (head_dim " + std::to_string(g.hd) + ", index_head_dim " +
                  std::to_string(g.ix_hd) + ", experts per token " + std::to_string(g.k_exp) + ")";
            return false;
        }
        freqs_win = rope_freqs(g.rd, 0, g.rope_theta, g.factor, g.beta_fast, g.beta_slow);
        freqs_comp = rope_freqs(g.rd, g.orig_ctx, g.comp_theta, g.factor, g.beta_fast, g.beta_slow);

        // devices
        int ndev = 0;
        if (cudaGetDeviceCount(&ndev) != cudaSuccess || ndev == 0) {
            err = "no CUDA device";
            return false;
        }
        std::vector<int> ids = o.gpus;
        if (ids.empty())
            for (int i = 0; i < ndev; ++i) ids.push_back(i);
        // helper (ds4_helper.hpp): its device owns no layers - out of the list that becomes devs[]; a wave64 card is
        // accepted only in that role (with the helper off, every listed device is checked as a layer host, as before:
        // a device the binary has no code for would fail at its first launch anyway)
        if (!o.helper_devices.empty()) {
            for (int hd : o.helper_devices) {
                if (hd < 0 || (hd >= ndev && helper::pool_client_dirs() == nullptr)) {   // (a pool client never opens the device)
                    err = "--helper-device " + std::to_string(hd) + ": only " + std::to_string(ndev) + " devices";
                    return false;
                }
                ids.erase(std::remove(ids.begin(), ids.end(), hd), ids.end());
            }
            if (ids.empty()) {
                err = "--helper-device " + (o.helper_devices.size() == 1 ? std::to_string(o.helper_devices[0]) : std::string("list")) +
                      " leaves no device to hold the layers";
                return false;
            }
            // (tensor parallel is fine: the helper computes WHOLE experts the members' VRAM slices leave out and its answer joins the
            // lead's CPU-lane part before the all-reduce - docs/dsv41/cards/TP-03.md)
            if (!pk.gguf) {
                err = "the helper expert cache takes GGUF packs only (IST-DAS / UD), not EXL3";
                return false;
            }
        }
#if defined(STRATA_USE_HIP)
        if (diag_enabled()) {   // the devices, then the kernels' attributes on each layer device before any big allocation
            diag_startup(ids, ndev);
            diag_probe_all("start", ids);
        }
#endif
        for (int id : ids) {
            const std::string why = helper::accept_device(id, false);
            if (!why.empty()) {
                err = why;
                return false;
            }
        }
        devs.resize(ids.size());
        for (size_t i = 0; i < ids.size(); ++i) {
            Dev& d = devs[i];
            d.id = ids[i];
            CK(cudaSetDevice(d.id));
            CK(cudaStreamCreateWithFlags(&d.st, cudaStreamNonBlocking));
            CK(cudaEventCreateWithFlags(&d.ev, cudaEventDisableTiming));
            CK(cudaEventCreateWithFlags(&d.ev2, cudaEventDisableTiming));
            if (!x3::prepare(d.st) || (pk.gguf && !gg::prepare(d.st))) {
                err = "exl3 scratch on CUDA" + std::to_string(d.id);
                return false;
            }
            CK(cudaMemGetInfo(&d.free0, &d.total));
            d.free0 = uma_free(d.id, d.free0);
            if (!preflight_kernels(d, err)) return false;
        }
        if (!fuse_flags(err)) return false;   // (the decode fusions' flags, before their buffers)
        // the groups' width: o.tp, less while the experts' blocks do not split in it (a member takes n_ff / tp of each
        // expert: the down's inputs in whole blocks - a GGUF's 256-value types split n_ff 2304 in 1, 3 or 9 parts)
        int tp = o.tp;
        if (pk.gguf && tp > 1) {
            int blk = 32;
            for (const auto& kv : pk.t) {
                const std::string& n = kv.first;
                if (n.find(".ffn.experts.") == std::string::npos || n.size() < 9 ||
                    n.compare(n.size() - 9, 9, "w2.weight") != 0)
                    continue;
                const int ty = gg_type_of(kv.second.dtype);
                if (ty >= 0) blk = std::max(blk, gg::type_block(ty));
            }
            // (TP-01): the heads and the wo_a groups no longer lower tp - a group of nm whose heads do not split
            // nm ways gives them to head_members(nm) of its members (64 heads / 8 groups at nm 3: 0 / 32 / 32, the first
            // member FFN only), the path the layer setup already has.  Only the experts' FFN split lowers it now.
            const int align = std::getenv("DS4_TP_ALIGN") ? std::atoi(std::getenv("DS4_TP_ALIGN")) : 128;
            auto even = [&](int t) { return g.ff % t == 0 && (g.ff / t) % blk == 0 && (g.ff / t) % align == 0; };
            // (TP-05; Project Maya e3f2475 #408): where o.tp does not split the blocks evenly, whole blocks
            // of u values (the experts' block and the alignment both) as even as they go - only there, so a width that
            // splits evenly (tp3 on n_ff 2304) is untouched.  DS4_TP_UNEVEN=0: the old fallback.  DS4_TP_SHARES=a,b,..
            // (tests): o.tp members' blocks of u, summing to n_ff / u - any width, even one that splits evenly
            const int u = std::max(blk, align);
            const char* tue = std::getenv("DS4_TP_UNEVEN");
            const bool uneven_ok = !(tue != nullptr && std::strcmp(tue, "0") == 0) && u % blk == 0 && u % align == 0 &&
                                   g.ff % u == 0 && g.ff / u >= tp;
            if (const char* v = std::getenv("DS4_TP_SHARES"); v != nullptr && *v != '\0' && tp > 1) {
                std::vector<int> sh;
                int sum = 0;
                bool ok = uneven_ok;
                for (const char* p = v; ok && *p != '\0';) {
                    char* e = nullptr;
                    const long x = std::strtol(p, &e, 10);
                    ok = e != p && x >= 1 && x <= 4096 && (*e == ',' || *e == '\0');
                    if (ok) sh.push_back((int) x), sum += (int) x;
                    p = *e == ',' ? e + 1 : e;
                }
                if (!ok || (int) sh.size() != tp || sum != g.ff / std::max(1, u)) {
                    err = std::string("DS4_TP_SHARES=") + v + ": " + std::to_string(tp) + " block counts of 1 or more, " +
                          "summing to n_ff " + std::to_string(g.ff) + " / " + std::to_string(u) + " (and DS4_TP_UNEVEN not 0)";
                    return false;
                }
                tp_shares = sh;
                tp_uneven = true;
            } else if (!even(tp) && uneven_ok)
                tp_uneven = true;
            if (tp_uneven) {
                tp_blk = u;
                std::string s;
                for (int m = 0; m < tp; ++m) {
                    int f0 = 0, fn = 0;
                    tp_range(0, tp, m, f0, fn);
                    s += (m ? "/" : "") + std::to_string(fn / u);
                }
                std::fprintf(stderr, "ds4: tensor parallel %d: the experts' n_ff %d in %d-value blocks, %s a member at layer 0 "
                                     "(uneven: the odd blocks going round the members layer by layer%s; DS4_TP_UNEVEN=0 "
                                     "lowers tp instead)\n", tp, g.ff, u, s.c_str(), tp_shares.empty() ? "" : ", DS4_TP_SHARES");
            }
            while (!tp_uneven && tp > 1 && !even(tp)) --tp;
            if (tp != o.tp)
                std::fprintf(stderr, "ds4: tensor parallel %d -> %d: n_ff %d does not split %d ways in the experts' %d-value blocks "
                                     "(or DS4_TP_ALIGN %d) (each GPU its own layers)\n", o.tp, tp, g.ff, o.tp, blk, align);
            else if (tp > 1 && head_members(tp) != tp)
                std::fprintf(stderr, "ds4: tensor parallel %d: %d heads / %d output groups split over %d of the %d members (%d heads "
                                     "each); the other %d take only their FFN share\n", tp, g.heads, g.o_groups, head_members(tp), tp,
                             g.heads / head_members(tp), tp - head_members(tp));
            if (tp > 1 && head_members(tp) != tp && a3_env())
                std::fprintf(stderr, "ds4: DS4_ATTN_SPLIT3: where the output groups split in %d parts, each of the %d members takes "
                                     "%d groups and its %d-th of a prompt chunk's rows of the last %d; a decode step %s\n",
                             tp + 1, tp, g.o_groups % (tp + 1) == 0 ? g.o_groups / (tp + 1) : 0, tp,
                             g.o_groups % (tp + 1) == 0 ? g.o_groups / (tp + 1) : 0,
                             g.o_groups % (tp + 1) == 0 ? "those one each on the last members" : "(not this model: off)");
        }
        // the groups: runs of tp devices of one kind (their memory), a device unlike the next alone
        // - or, tp the number of GPUs, one group of all of them whatever their kind (its tightest member sets the
        // experts' room); threads mode for the windows (decode) where a group is 2 wide or more or --threads on, the
        // prompt path (its own thread a GPU) as asked for - also where the experts' blocks took the groups' width down
        // to 1 (a 256-value type's: Maya's quants), which left every prompt in windows of 16
        par = o.threads || tp > 1;
        // the chunked (layer-major) prompt path: with --tp / --threads as before; --prefill-chunk N (N > 0) or
        // kChunkedPromptDefault bring it to a single card's default run too (a host thread a GPU for the prompt only;
        // decode stays as asked).  --prefill-chunk 0 keeps the windows of 16 (DS4_WINDOWS=1 the same).  Off by default
        // until a prompt costs the decode nothing: its buffers hold VRAM the windowed path gives to experts
        prompt_par = par || o.tp > 1 ||
                     ((o.prefill_chunk > 0 || (o.prefill_chunk < 0 && kChunkedPromptDefault)) &&
                      std::getenv("DS4_WINDOWS") == nullptr);
#if defined(STRATA_METAL)
        if (std::getenv("DS4_NO_CHUNKS") == nullptr) prompt_par = true;   // the chunked prompt path on one device, the decode steps stay on the host-routed path
#endif
        const bool tp_all = tp > 1 && tp == (int) devs.size();
        for (size_t i = 0; i < devs.size();) {
            Group G;
            G.mem.push_back((int) i);
            size_t j = i + 1;
            while ((int) G.mem.size() < tp && j < devs.size() && (tp_all || devs[j].total == devs[i].total))
                G.mem.push_back((int) j++);
            if ((int) G.mem.size() < tp && G.mem.size() > 1) {   // a short run at the end: devices of their own
                for (int m : G.mem) {
                    Group one;
                    one.mem.push_back(m);
                    groups.push_back(one);
                }
            } else groups.push_back(G);
            i = j;
        }
        {   // (docs/dsv41/cards/PF-02.md): the matrix-core prompt attention's default - on (mode f32) for gfx1100 in a tp group
            bool tp_groups = false;
            for (const Group& G : groups) tp_groups = tp_groups || G.mem.size() > 1;
            set_fast_attn_tp(tp_groups);
            gg::iq::set_hipk_tp(tp_groups);   // (the gfx1100 tp default of the matrix-core expert tiles, STRATA_DS4_HIPK=0 off)
        }
        for (size_t gi = 0; gi < groups.size(); ++gi)
            for (size_t m = 0; m < groups[gi].mem.size(); ++m) {
                devs[(size_t) groups[gi].mem[m]].grp = (int) gi;
                devs[(size_t) groups[gi].mem[m]].mi = (int) m;
            }
        // whether the CPU lane's experts are read in place (--mmap-experts; auto: the pack's expert bytes beyond what the
        // GPUs can take - their free memory less the other weights and the prompt path's buffers - do not fit the RAM
        // this process can get beside kRamMargin), decided here because it sets the prompt chunk's default: in place
        // every chunk streams every expert VRAM does not hold from the files, so the larger the chunk the fewer times
        if (pk.gguf) file_experts = true;   // (a GGUF's: the files stay their source - copy_experts copies them into RAM
                                            // after VRAM's are in, by --mmap-experts)
        else if (o.mmap_experts >= 0) file_experts = o.mmap_experts > 0;
        else {
            double exp_b = 0, other_b = 0, room = 0;
            for (const auto& kt : pk.t) {
                const std::string& n = kt.first;
                if (n.find(".engram.embed.") != std::string::npos || n.rfind("vision.", 0) == 0 || n == "embed.weight" ||
                    (!o.dspark && n.rfind("mtp.", 0) == 0))
                    continue;
                (n.find(".ffn.experts.") != std::string::npos ? exp_b : other_b) += (double) kt.second.bytes;
            }
            for (const Dev& d : devs)
                room += std::max(0.0, (double) d.free0 - (double) ((size_t) o.reserve_mib << 20) -
                                          (prompt_par ? 1.5 : 0.4) * (1 << 30)) *
                        o.vram_experts;
            file_experts = exp_b - std::max(0.0, room - other_b) + (double) kRamMargin > (double) ram_avail();
        }
        // The default prompt chunk, one rule (ds4_experts_rule.hpp: prefill_chunk_default).  Measured: the chunked pass streams the experts the GPUs
        // do not hold once per chunk, so where they hold less than half of them a larger chunk is fewer passes (1 x R9700 + 251 GB, 8K prompt:
        // 1024 200, 2048 277, 4096 353, 8192 431 tok/s; RTX 5070 / 3060 12 GB in place: 8192 244 / 228 against 1024 186 / 175); where they hold
        // most (4 x R9700: 8192 214, 1024 370) the small one wins; with the experts copied into RAM (--mmap-experts off) 4096 beats 8192 by 7-9%
        // (H100 32 GiB: 2048 502, 4096 538, 8192 495).  A GGUF pack always has file_experts set (copied only by --mmap-experts off).
        const bool own_default = !(par || o.tp > 1);   // (a run with tp 1 and no --threads: `strata launch` writes --tp 1 for 4+ AMD cards, --tp 2 for 2-3 and nothing for one card = the engine's tp 2)
        const bool multi_tp = rdna4() && !own_default && !o.threads && devs.size() >= 2;   // (the 4-card default-tp run the 1024 chunk was also measured on; an explicit --prefill-chunk below wins over the rule)
        const bool gguf_copy = pk.gguf && (o.mmap_experts == 0 || (store_gb() <= 0.0 && auto_copy_all));
        uint64_t vmin_bytes = ~0ull;
        for (const Dev& dv : devs) vmin_bytes = std::min<uint64_t>(vmin_bytes, (uint64_t) dv.total);
        if (devs.empty()) vmin_bytes = 0;
#if defined(__HIP_PLATFORM_AMD__) || defined(__HIPCC__)
        const bool hip_build = true;
#else
        const bool hip_build = false;
#endif
        const int rule_chunk = prefill_chunk_default(own_default, gpu_expert_share(), gguf_copy, file_experts, hip_build, vmin_bytes, kVlRows, multi_tp, defaults_026());
        chunk = prompt_par ? (o.prefill_chunk >= 0 ? o.prefill_chunk : rule_chunk) : 0;
        if (prompt_par && o.prefill_chunk < 0 && rule_chunk == 4096 && gguf_copy)
            std::fprintf(stderr, "ds4: prompts in chunks of 4096 tokens (the experts are copied into RAM, %.0f GiB of graphics memory; --prefill-chunk N changes it)\n",
                         (double) vmin_bytes / (double) (1ull << 30));
        const char* dc = std::getenv("DS4_CHUNK");   // (tests: down to 16, a short prompt in several chunks)
        if (dc != nullptr) chunk = prompt_par ? std::atoi(dc) : 0;
        if (const char* v = std::getenv("DS4_CHUNK_MIN")) chunk_min = std::max(1, std::atoi(v));
        if (chunk > 0) {
            chunk = std::min(kMaxChunk, std::max(dc != nullptr ? 16 : 256, chunk / 16 * 16));
            eg_cap = (size_t) chunk;
            tap_cap = std::max(kWin, 128);
        } else   // (only as asked for: --prefill-chunk 0, or --tp 1 with --threads off)
            std::fprintf(stderr,
                         "ds4: prompts run in windows of %d tokens (%s): long prompts prefill far slower than in\n"
                         "     chunks (a 7-GPU RTX 3090 rig, Maya-S read in place: 8K / 32K tokens 115 / 99 tokens/s,\n"
                         "     461 / 1010 in chunks of %d) - %s\n",
                         kWin, o.prefill_chunk == 0 ? "--prefill-chunk 0" : "--tp 1 with --threads off", kVlRows,
                         o.prefill_chunk == 0 ? "leave --prefill-chunk out for chunks"
                                              : "leave --tp 1 out, or pass --threads on, for chunks");
        // the vision tower on the first GPU, before the split: the layers get what it leaves
        if (o.vision && !load_vision(err)) {   // (a tower that cannot load leaves the model reading text: said loudly,
            if (o.vision_only) return false;   // and the server is told pictures are off - info_lines)
            std::fprintf(stderr, "ds4: WARNING: the vision tower did not load (%s): pictures are OFF, the model reads "
                                 "text only\n", err.c_str());
            vision_err = err.empty() ? "unknown reason" : err;
            err.clear();
            vt.release();
            img_tok = -1;
        }
        if (o.vision_only) return true;

        // layers: roles and the sources they read
#if defined(STRATA_METAL)
        // On a Mac the drafter is off unless it is asked for outright: it gave the same answers and no speed-up there, and the head of its
        // quantised Markov bias has no Metal kernel (the engine stopped with "kernel launch with no Metal dispatch" on the setup test).
        if (o.dspark && g.n_mtp > 0) {
            if (o.dspark_auto) {
                o.dspark = false;
                std::fprintf(stderr, "ds4: the DSpark drafter is not supported on a Mac yet, so it is not loaded\n");
            } else {   // --dspark on / off: loaded as asked
                std::fprintf(stderr, "ds4: WARNING: the DSpark drafter is not supported on a Mac yet; --dspark on will probably stop at the Markov bias step (kernel launch with no Metal dispatch)\n");
            }
        }
#endif
        if (o.dspark_auto && o.dspark && g.n_mtp > 0) {   // (see Options::dspark_auto)
            double exp_b = 0, room_b = 0;
            for (const auto& kt : pk.t)
                if (kt.first.rfind("layers.", 0) == 0 && kt.first.find(".ffn.experts.") != std::string::npos) exp_b += (double) kt.second.bytes;
            for (const Dev& d : devs) room_b += std::max(0.0, (double) d.free0 - (double) ((size_t) o.reserve_mib << 20));
            if (exp_b > 1.5 * room_b) {
                o.dspark = false;
                std::fprintf(stderr, "ds4: DSpark not loaded: the routed experts (%.0f GB) are far more than the GPU holds (%.0f GB), where its verify "
                                     "rounds read 3.3x a token's bytes and gain nothing (--dspark on loads it anyway)\n", exp_b / 1e9, room_b / 1e9);
            }
        }
        if (!o.dspark) g.n_mtp = 0;
        if (o.dspark_block > 0 && std::getenv("DS4_DSPARK_MAX") == nullptr) max_drafts = o.dspark_block;   // (--dspark-block N: at most N drafts a round)
        L.resize((size_t) (g.nl + g.n_mtp));
        int last_src = -1;
        int experts_used = 1 << 20;
        for (int il = 0; il < g.nl + g.n_mtp; ++il) {
            Layer& l = L[(size_t) il];
            l.il = il;
            l.mtp = il >= g.nl;
            l.name = l.mtp ? "mtp." + std::to_string(il - g.nl) + "." : "layers." + std::to_string(il) + ".";
            l.n_exp = l.mtp ? g.d_n_exp : g.n_exp;
            l.k_exp = l.mtp ? g.d_k : g.k_exp;
            if (!l.mtp) {   // experts a word takes: --experts N / the faster-mode rule (ds4_experts_rule.hpp), DS4_TOPK=N over both (a test)
                if (il == 0) {
                    uint64_t vram_all = 0;
                    bool integrated = false;   // (a GPU that shares the PC's RAM: Strix Halo)
                    for (const Dev& dv : devs) {
                        vram_all += (uint64_t) dv.total;
                        cudaDeviceProp ip{};
                        if (cudaGetDeviceProperties(&ip, dv.id) == cudaSuccess && ip.integrated) integrated = true;
                    }
                    // two or more RDNA4 cards holding at least half of the experts (the 4 x R9700 class): Faster by default too
                    const bool multi_rdna4 = rdna4() && devs.size() >= 2 && gpu_expert_share() >= 0.5;
                    const int n = experts_test_override(experts_per_word(o.experts, vram_all, l.k_exp, integrated, multi_rdna4, defaults_026()), l.k_exp);
                    experts_used = n;
                    if (n < l.k_exp)
                        std::fprintf(stderr, "ds4: experts per word: %d (%s; full quality: --experts %d)\n", n,
                                     o.experts >= 1 ? "as asked" : multi_rdna4 ? "faster mode: the cards hold most of the experts" : "faster mode", l.k_exp);
                    else if (o.experts >= 1)
                        std::fprintf(stderr, "ds4: experts per word: %d (full quality)\n", n);
                }
                l.k_exp = std::min(l.k_exp, experts_used);
            }
            l.ratio = g.ratios[(size_t) il];
            if (l.mtp) {   // window attention only: no compressor, indexer or Engram
                if (l.ratio != 0 || l.n_exp <= 0 || l.k_exp <= 0 || l.k_exp > kPicks) {
                    err = l.name + ": a DSpark block of compress ratio " + std::to_string(l.ratio) + ", " +
                          std::to_string(l.n_exp) + " experts / " + std::to_string(l.k_exp) + " is not covered";
                    return false;
                }
                if (!expert_layout(l, err)) return false;
                continue;
            }
            l.kv_src = std::find(g.kv_src.begin(), g.kv_src.end(), il) != g.kv_src.end();
            l.ix_src = std::find(g.ix_src.begin(), g.ix_src.end(), il) != g.ix_src.end();
            l.owns_k = l.kv_src;
            l.cand_src = il == g.cand_src;
            l.uses_cand = g.cand_src >= 0 && g.cand_src < il && l.ix_src;
            if (l.kv_src) {
                Src s;
                s.layer = il;
                s.ratio = l.ratio;
                s.cap = (o.max_context + l.ratio - 1) / l.ratio + 1;
                srcs.push_back(s);
                last_src = (int) srcs.size() - 1;
            }
            if (l.ratio > 0) {
                if (last_src < 0 || srcs[(size_t) last_src].ratio != l.ratio) {
                    err = "layer " + std::to_string(il) + ": compress ratio " + std::to_string(l.ratio) +
                          " without a KV source of that ratio before it";
                    return false;
                }
                l.src = last_src;
                l.ik_src = last_src;
            }
            auto eg = std::find(g.eg_layers.begin(), g.eg_layers.end(), il);
            if (eg != g.eg_layers.end()) l.eg = (int) (eg - g.eg_layers.begin());
            if (!expert_layout(l, err)) return false;
        }

        // A layer whose experts the chunk path's tile GEMM cannot take (IQ1_M on Metal today) would be streamed to the
        // GPU for every prompt and stop in "kernel launch with no Metal dispatch".  Prompts then run in windows of 16,
        // which is slower but correct; say so instead of failing at the first prompt.
        {
            bool chunk_unsupported = false;
            const char* why = "";
            for (const Layer& l : L) {
                for (int r = 0; r < 3; ++r)
                    if (!gg::type_on_chunk(gg::expert_type(l.lay, r))) { chunk_unsupported = true; why = gg::type_name(gg::expert_type(l.lay, r)); break; }
                if (chunk_unsupported) break;
            }
            if (chunk > 0 && chunk_unsupported) {
                chunk = 0;
                std::fprintf(stderr,
                             "ds4: the prompt chunk path has no GPU kernel for %s: prompts run in windows of %d instead "
                             "of chunks - slower prompts, and the only correct path on this build\n",
                             why, kWin);
            }
        }

        // the split: each layer's dense weights + its experts, the head on the last GPU
        for (Layer& l : L) {
            const std::string& P = l.name;
            size_t b = 0;
            if (l.mtp && l.il == g.nl) b += mat_bytes("mtp.0.main_proj");
            for (const char* m : {"attn.wq_a", "attn.wq_b", "attn.wkv", "attn.wo_b", "ffn.shared_experts.w1",
                                  "ffn.shared_experts.w2", "ffn.shared_experts.w3", "attn.compressor.wkv",
                                  "attn.compressor.wgate", "attn.indexer.wq_b", "attn.indexer.wk", "engram.wkv"})
                b += mat_bytes(P + m);
            for (int gi = 0; gi < g.o_groups; ++gi) b += mat_bytes(P + "attn.wo_a.slice." + std::to_string(gi));
            b += tensor_bytes(P + "hc_attn_fn") + tensor_bytes(P + "hc_ffn_fn") + tensor_bytes(P + "ffn.gate.weight");
            b += (size_t) g.win * win_rb() + (2u << 20);
            l.dense_bytes = b;
        }
        const size_t head_b = mat_bytes("head") + (size_t) g.vocab * 4 + (16u << 20);
        const size_t per_dev_fixed = (size_t) o.reserve_mib << 20;
        const size_t kv_per_src_dev = 0;   // counted after the split
        (void) kv_per_src_dev;
        std::vector<double> avail(groups.size(), 0.0);
        double avail_sum = 0;
        for (size_t gi = 0; gi < groups.size(); ++gi) {
            for (int m : groups[gi].mem)
                avail[gi] += std::max(0.0, (double) devs[(size_t) m].free0 - (double) per_dev_fixed - 400.0 * (1 << 20));
            avail_sum += avail[gi];
        }
        double need_sum = (double) head_b;
        for (const Layer& l : L) need_sum += (double) l.dense_bytes + (double) l.blob * l.n_exp;
        {
            // contiguous layer ranges, each group's share of the total by its free memory
            size_t d = 0;
            double cum = 0, target = avail[0] / avail_sum * need_sum;
            std::vector<Layer*> order;   // the drafter's blocks first (the first GPU), then the trunk's layers
            for (Layer& l : L)
                if (l.mtp) order.push_back(&l);
            for (Layer& l : L)
                if (!l.mtp) order.push_back(&l);
            for (Layer* lp : order) {
                Layer& l = *lp;
                const double lb = (double) l.dense_bytes + (double) l.blob * l.n_exp;
                if (cum + lb / 2 > target && d + 1 < groups.size()) {
                    ++d;
                    target += avail[d] / avail_sum * need_sum;
                }
                l.grp = (int) d;
                cum += lb;
            }
            // with the chunked prompt path: the contiguous split that streams the least into its busiest member (its
            // VRAM short of its layers' experts, per member) - a chunk's groups run as a pipeline, its slowest stage
            // sets the pace; a token's decode passes every layer either way, the experts in VRAM the same in all
            if (chunk > 0 && groups.size() > 1 && groups.size() <= 6 && std::getenv("DS4_SPLIT") == nullptr) {
                const int G = (int) groups.size(), NL = g.nl;
                std::vector<double> cap(groups.size());
                for (int gi = 0; gi < G; ++gi) {
                    const int nm = (int) groups[(size_t) gi].mem.size();
                    double mn = 1e300;
                    for (int m : groups[(size_t) gi].mem)
                        mn = std::min(mn, std::max(0.0, (double) devs[(size_t) m].free0 - (double) per_dev_fixed -
                                                            400.0 * (1 << 20) - 1.1 * (1 << 30)));   // (the chunk's buffers)
                    cap[(size_t) gi] = mn * nm;
                }
                for (const Layer& l : L)
                    if (l.mtp) cap[0] -= (double) l.dense_bytes + (double) l.blob * l.n_exp;
                cap[(size_t) G - 1] -= (double) head_b;
                std::vector<double> pe(NL + 1, 0.0), pd(NL + 1, 0.0);   // prefix sums: experts, dense
                for (int il = 0; il < NL; ++il) {
                    pe[(size_t) il + 1] = pe[(size_t) il] + (double) L[(size_t) il].blob * L[(size_t) il].n_exp;
                    pd[(size_t) il + 1] = pd[(size_t) il] + (double) L[(size_t) il].dense_bytes;
                }
                auto cost = [&](int gi, int a, int b) {   // per-member streaming of layers [a, b) on group gi
                    const int nm = (int) groups[(size_t) gi].mem.size();
                    const double dense = (pd[(size_t) b] - pd[(size_t) a]) * (nm > 1 ? 1.3 : 1.0);
                    return std::max(0.0, pe[(size_t) b] - pe[(size_t) a] - (cap[(size_t) gi] - dense)) / nm;
                };
                // best[gi][b]: the least max cost of layers [0, b) over groups 0..gi (each at least one layer)
                std::vector<std::vector<double>> best((size_t) G, std::vector<double>((size_t) NL + 1, 1e300));
                std::vector<std::vector<int>> cut((size_t) G, std::vector<int>((size_t) NL + 1, 0));
                for (int b = 1; b <= NL; ++b) best[0][(size_t) b] = cost(0, 0, b);
                for (int gi = 1; gi < G; ++gi)
                    for (int b = gi + 1; b <= NL; ++b)
                        for (int a = gi; a < b; ++a) {
                            const double v = std::max(best[(size_t) gi - 1][(size_t) a], cost(gi, a, b));
                            if (v < best[(size_t) gi][(size_t) b]) {
                                best[(size_t) gi][(size_t) b] = v;
                                cut[(size_t) gi][(size_t) b] = a;
                            }
                        }
                int b = NL;
                for (int gi = G - 1; gi >= 0; --gi) {
                    const int a = gi > 0 ? cut[(size_t) gi][(size_t) b] : 0;
                    for (int il = a; il < b; ++il) L[(size_t) il].grp = gi;
                    b = a;
                }
            }
            // DS4_SPLIT=a,b,..: the trunk layers each group takes (the drafter stays with the first)
            if (const char* sp = std::getenv("DS4_SPLIT")) {
                std::vector<int> n;
                for (const char* q = sp; *q;) {
                    n.push_back(std::atoi(q));
                    while (*q && *q != ',') ++q;
                    if (*q == ',') ++q;
                }
                int il = 0;
                for (size_t gi = 0; gi < n.size() && gi < groups.size(); ++gi)
                    for (int j = 0; j < n[gi] && il < g.nl; ++j) L[(size_t) il++].grp = (int) gi;
                for (; il < g.nl; ++il) L[(size_t) il].grp = (int) groups.size() - 1;
            }
            // (the drafter's blocks: tensor parallel over their group as the trunk's layers, DS4_DRAFT_TP=0: on the
            // lead alone; a group of one, or no threads mode to run the members at once: the lead alone too)
            {
                const char* v = std::getenv("DS4_DRAFT_TP");
                draft_tp = g.n_mtp > 0 && par && !(v != nullptr && *v != '\0' && std::atoi(v) == 0) &&
                           groups[(size_t) L[(size_t) g.nl].grp].mem.size() > 1;
            }
            for (Layer& l : L) {
                l.dev = groups[(size_t) l.grp].mem[0];
                l.nm = l.mtp && !draft_tp ? 1 : (int) groups[(size_t) l.grp].mem.size();
            }
            if (g.n_mtp > 0)
                std::fprintf(stderr, "ds4: the drafter's %d blocks %s (DS4_DRAFT_TP=%s)\n", g.n_mtp,
                             draft_tp ? "tensor parallel over the lead's group, as the trunk's layers"
                                      : "on the lead alone", draft_tp ? "0: on the lead alone" : "1: tensor parallel");
            head_dev = L[(size_t) g.nl - 1].dev;
            d_dev = g.n_mtp > 0 ? L[(size_t) g.nl].dev : 0;
            if (!draft_small_setup(err)) return false;   // DS4_DRAFT_* (before the members copy the blocks)
        }
        // the groups' members: copies of each layer's device state, a member's part of an expert
        for (Layer& l : L) {
            l.ff0 = 0;
            l.ffn = g.ff;
            l.ah0 = l.og0 = 0;
            l.ahn = g.heads;
            l.ogn = g.o_groups;
            if (l.nm == 1) continue;
            const int na = head_members(l.nm);
            if (g.heads % na != 0 || g.o_groups % na != 0 || g.ff % 128 != 0 || g.ff / 128 < l.nm) {
                err = "tensor parallel " + std::to_string(l.nm) + ": the heads, output groups or FFN do not split";
                return false;
            }
            for (int m = 1; m < l.nm; ++m) {
                Layer c = l;
                c.mates.clear();
                c.mi = m;
                c.dev = groups[(size_t) l.grp].mem[(size_t) m];
                l.mates.push_back(std::move(c));
            }
            // each member's FFN columns and its part of an expert's layout: an EXL3 expert's in whole 128-blocks, as even
            // as they go (split128, the odd blocks going round the members layer by layer); a GGUF's in even shares, or
            // (tp4, tp_uneven) in whole tp_blk blocks as even as they go - each member its own ff0 / ffn / hlay /
            // hblob, which every GGUF member path (mx_blob_to_half, the streams, the swaps) takes
            const bool gguf_x = l.lay.fmt == gg::kFmtMXFP4;
            for (int m = 0; m < l.nm; ++m) {
                Layer& x = member(l, m);
                const int ha = m - (l.nm - na);   // (its place among the members with heads)
                x.ahn = ha < 0 ? 0 : g.heads / na;
                x.ah0 = ha < 0 ? 0 : ha * x.ahn;
                x.ogn = ha < 0 ? 0 : g.o_groups / na;
                x.og0 = ha < 0 ? 0 : ha * x.ogn;
                if (a3_eligible(l)) {   // DS4_ATTN_SPLIT3 (see Layer::a3)
                    const int nm = l.nm, G = g.o_groups, base = G / (nm + 1), hpg = g.heads / G;
                    x.a3 = true;
                    x.a3_own = x.a3_sh = base * hpg;
                    x.a3_ng = 0;
                    for (int gi = 0; gi < base; ++gi) x.a3_ord[x.a3_ng++] = m * base + gi;
                    int ndec = 0;
                    for (int j = 0; j < base; ++j)   // (shared group j decodes on member nm - 1 - j % nm)
                        if (nm - 1 - j % nm == m) { x.a3_ord[x.a3_ng++] = nm * base + j; ++ndec; }
                    for (int j = 0; j < base; ++j)
                        if (nm - 1 - j % nm != m) x.a3_ord[x.a3_ng++] = nm * base + j;
                    x.ahn = (base + ndec) * hpg;   // (the decode's heads and groups: a prefix of a3_ord)
                    x.ah0 = 0;
                    x.ogn = base + ndec;
                    x.og0 = 0;
                }
                if (gguf_x && tp_uneven)   // (tp4: whole blocks, the odd ones going round the members)
                    tp_range(l.il, l.nm, m, x.ff0, x.ffn);
                else if (gguf_x) {
                    x.ffn = g.ff / l.nm;
                    x.ff0 = m * x.ffn;
                } else
                    split128(g.ff, l.nm, m, x.ff0, x.ffn, l.il % l.nm);   // (rot: the odd blocks go round the members)
                size_t off = 0;
                for (int r = 0; r < 3; ++r) {
                    const int k = r < 2 ? g.dim : x.ffn, n = r < 2 ? x.ffn : g.dim;
                    x.hlay.K[r] = l.lay.K[r];
                    x.hlay.trellis[r] = off;
                    if (gguf_x) {   // gate / up rows, down inputs: [n][k / block] blocks
                        const int ty = gg::expert_type(l.lay, r);
                        if (k % gg::type_block(ty) != 0) {
                            err = "tensor parallel " + std::to_string(l.nm) + ": the experts' " + gg::type_name(ty) +
                                  " blocks do not split";
                            return false;
                        }
                        x.hlay.suh[r] = x.hlay.svh[r] = off;
                        off += align256((size_t) n * gg::type_row_bytes(ty, k));
                        continue;
                    }
                    off += align256(x3::trellis_bytes(k, n, l.lay.K[r]));
                    x.hlay.suh[r] = off;
                    off += align256((size_t) k * 2);
                    x.hlay.svh[r] = off;
                    off += align256((size_t) n * 2);
                }
                x.hlay.cb = l.lay.cb;
                x.hlay.fmt = l.lay.fmt;
                x.hblob = off;
            }
        }
        // which devices hold each source's compressed KV / index keys
        for (Src& s : srcs) {
            s.ckv.assign(devs.size(), nullptr);
            s.ik.assign(devs.size(), nullptr);
        }
        for (const Layer& l0 : L)
            for (int m = 0; m < l0.nm; ++m) {
                const Layer& l = member(l0, m);
                if (l.src >= 0) {
                    srcs[(size_t) l.src].ckv[(size_t) l.dev] = (uint8_t*) 1;
                    if (l0.grp != L[(size_t) srcs[(size_t) l.src].layer].grp) srcs[(size_t) l.src].remote = true;
                }
                if (l.ix_src && l.ik_src >= 0) {
                    srcs[(size_t) l.ik_src].ik[(size_t) l.dev] = (uint8_t*) 1;
                    if (l0.grp != L[(size_t) srcs[(size_t) l.ik_src].layer].grp) srcs[(size_t) l.ik_src].remote = true;
                }
            }

        // per device: the scratch, the caches, the dense weights
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            const int D = g.dim, H = g.hc;
            const size_t W = kWin, P = (size_t) kWin * kPicks, cap = (size_t) o.max_context + 64;
            bool ok = dalloc(d, d.h, W * H * D, err) && dalloc(d, d.h2, W * H * D, err) && dalloc(d, d.x, W * D, err) &&
                      dalloc(d, d.qr, W * g.q_lora, err) && dalloc(d, d.q, W * g.heads * g.hd, err) &&
                      dalloc(d, d.kvr, W * g.hd, err) && dalloc(d, d.ckr, W * g.hd, err) &&
                      dalloc(d, d.cgr, W * g.hd, err) && dalloc(d, d.latent, W * g.hd, err) &&
                      dalloc(d, d.ikr, W * g.ix_hd, err) && dalloc(d, d.iq, W * g.ix_heads * g.ix_hd, err) &&
                      dalloc(d, d.iw, W * 64, err) && dalloc(d, d.scores, W * cap, err) &&
                      dalloc(d, d.bm, W * bm_stride(), err) && dalloc(d, d.o, W * g.heads * g.hd, err) &&
                      dalloc(d, d.oa, W * g.o_groups * g.o_lora, err) && dalloc(d, d.ao, W * D, err) &&
                      dalloc(d, d.mix, W * 32, err) && dalloc(d, d.a_pre, W * 8, err) && dalloc(d, d.a_post, W * 8, err) &&
                      dalloc(d, d.a_comb, W * 64, err) && dalloc(d, d.f_pre, W * 8, err) &&
                      dalloc(d, d.f_post, W * 8, err) && dalloc(d, d.f_comb, W * 64, err) && dalloc(d, d.pre, W * 8, err) &&
                      dalloc(d, d.glog, W * 1024, err) && dalloc(d, d.glog_a, 2 * W * 1024, err) &&
                      dalloc(d, d.rw, W * kPicks, err) &&
                      dalloc(d, d.ridx, W * kPicks, err) && dalloc(d, d.ridx_a, 2 * kPicks, err) && dalloc(d, d.rw_a, 2 * kPicks, err) &&
                      dalloc(d, d.moe_out, W * D, err) &&
                      dalloc(d, d.sg, W * g.ff, err) && dalloc(d, d.su, W * g.ff, err) && dalloc(d, d.sh, W * g.ff, err) &&
                      dalloc(d, d.sh_out, W * D, err) && dalloc(d, d.cpu_part, W * D, err) &&
                      dalloc(d, d.freqs_win, 64, err) && dalloc(d, d.freqs_comp, 64, err) &&
                      dalloc(d, d.topk, W * topk_stride(), err) && dalloc(d, d.cand, W * cand_stride(), err) &&
                      dalloc(d, d.tok, 16, err) && dalloc(d, d.emb_rows, W * D, err) &&
                      dalloc(d, d.ext, ((size_t) g.win + W) * g.hd, err) && dalloc(d, d.xe, P * D, err) &&
                      dalloc(d, d.xg, P * g.ff, err) && dalloc(d, d.xu, P * g.ff, err) && dalloc(d, d.xhh, P * g.ff, err) &&
                      dalloc(d, d.ed, P * D, err) && dalloc(d, d.plan_ptr, P, err);
        if (ok && ds4_dbg("DS4_DBG_DEVH"))
            std::fprintf(stderr, "DBG devh: id=%d h=%p h2=%p\n", d.id, (void*) d.h, (void*) d.h2);
            if (!ok) return false;
            d.attn_scr.max_t = kAttnScratchT;
            d.attn_scr.cap = (int) topk_stride();
            if (!dalloc(d, d.attn_scr.rows, (size_t) kAttnScratchT * topk_stride() * g.hd, err)) return false;
            // (DS4_TOPK_MB set - =0 too, so an identity test's off arm has the same VRAM, the same expert placement)
            if (topk_mb_set && !dalloc(d, d.tmb, (size_t) kWin * kTopkMbRow, err)) return false;
            // (DS4_HC_FUSE set - =0 too, so an identity test's off arm has the same VRAM, the same expert placement)
            if (hc_fuse_set && !(dalloc(d, d.xq8, W * D, err) && dalloc(d, d.xd8, W * D / 32, err))) return false;
            // (DS4_DECODE_TRIM set - =0 too, as above)
            if (decode_trim_set && !(dalloc(d, d.shq8, W * g.ff, err) && dalloc(d, d.shd8, W * g.ff / 32, err) &&
                                     dalloc(d, d.qrq8, W * g.q_lora, err) && dalloc(d, d.qrd8, W * g.q_lora / 32, err)))
                return false;
            if (!g.eg_layers.empty()) {
                const int cols = (pk.eg_ngram - 1) * pk.eg_heads;
                ok = dalloc(d, d.eg_rows, W * cols * (pk.eg_hd + pk.eg_hd / 32), err) &&
                     dalloc(d, d.eg_x, W * cols * pk.eg_hd, err) && dalloc(d, d.eg_kv, W * (g.hc + 1) * D, err);
                if (!ok) return false;
                if (eg_split_set) {   // (DS4_EG_SPLIT: the -0.0 rows, filled once)
                    const size_t nz = (size_t) (g.hc + 1) * D;
                    if (!dalloc(d, d.eg_nz, nz, err)) return false;
                    const std::vector<uint32_t> mz(nz, 0x80000000u);   // (-0.0f as bits: no fast-math folding)
                    CK(cudaMemcpy(d.eg_nz, mz.data(), nz * 4, cudaMemcpyHostToDevice));
                }
                if (eg_ahead_set) {   // (DS4_EG_AHEAD: the side stream, its gguf scratch made now, each layer's buffers)
                    CK(cudaStreamCreateWithFlags(&d.eg_st, cudaStreamNonBlocking));
                    CK(cudaEventCreateWithFlags(&d.eg_ev_main, cudaEventDisableTiming));
                    if (pk.gguf && !gg::prepare(d.eg_st)) {
                        err = "DS4_EG_AHEAD: the side stream's gguf scratch on CUDA" + std::to_string(d.id);
                        return false;
                    }
                    for (size_t e = 0; e < g.eg_layers.size() && e < (size_t) Dev::kEgAh; ++e) {
                        CK(cudaEventCreateWithFlags(&d.eg_ev[e], cudaEventDisableTiming));
                        if (!(dalloc(d, d.eg_ah_rows[e], W * cols * (pk.eg_hd + pk.eg_hd / 32), err) &&
                              dalloc(d, d.eg_ah_x[e], W * cols * pk.eg_hd, err) && dalloc(d, d.eg_ah_kv[e], W * (g.hc + 1) * D, err)))
                            return false;
                    }
                }
            }
            if ((int) di == head_dev && !dalloc(d, d.logits, (size_t) kWin * g.vocab, err)) return false;
            if (!halloc(d.bounce, bounce_bytes(), err)) return false;
            if (!dalloc(d, d.xcnt, 4, err) || !dalloc(d, d.hccnt, kWin, err) || !hmap(d.hand, bounce_bytes(), err) || !hmap(d.hand_flag, 32, err) ||
                !dalloc(d, d.grp_ptr, P, err) || !dalloc(d, d.grp_start, P + 1, err) || !dalloc(d, d.grp_ent, P, err) ||
                !dalloc(d, d.n_groups, 4, err))
                return false;
            if (g.n_mtp > 0 && !dalloc(d, d.tap, (size_t) tap_cap * D, err)) return false;
            if (g.n_mtp > 0 && (int) di == head_dev &&
                (!dalloc(d, d_confv, kWin, err) || !dalloc(d, d_ints, 64, err) || !dalloc(d, d_specq, kWin, err)))
                return false;
            CK(cudaEventCreateWithFlags(&d.ev_out, cudaEventDisableTiming));
            cudaSetDevice(d.id);
            CK(cudaMemcpy(d.freqs_win, freqs_win.data(), freqs_win.size() * 4, cudaMemcpyHostToDevice));
            CK(cudaMemcpy(d.freqs_comp, freqs_comp.data(), freqs_comp.size() * 4, cudaMemcpyHostToDevice));
            for (Src& s : srcs) {
                if (s.h_ckv == nullptr) {   // (its events belong to the source layer's device: it records them)
                    if (!halloc(s.h_ckv, (size_t) kWin * ckv_rb(), err) || !halloc(s.h_ik, (size_t) kWin * ik_rb(), err))
                        return false;
                    CK(cudaSetDevice(devs[(size_t) L[(size_t) s.layer].dev].id));
                    CK(cudaEventCreateWithFlags(&s.ev_ckv, cudaEventDisableTiming));
                    CK(cudaEventCreateWithFlags(&s.ev_ik, cudaEventDisableTiming));
                    CK(cudaSetDevice(d.id));
                }
                if (s.ckv[di] != nullptr && !dalloc(d, s.ckv[di], (size_t) s.cap * ckv_rb(), err, &d.caches))
                    return false;
                if (s.ik[di] != nullptr && !dalloc(d, s.ik[di], (size_t) s.cap * ik_rb(), err, &d.caches))
                    return false;
            }
        }
        for (Src& sr : srcs) {
            if (sr.remote && (!hmap(sr.x_stage, x_cap() * (ckv_rb() + ik_rb()), err) || !hmap(sr.x_flag, 32, err)))
                return false;
            if (sr.remote && chunk > 0 &&
                (!hmap(sr.x_stage1, x_cap() * (ckv_rb() + ik_rb()), err) || !hmap(sr.x_flag1, 32, err) ||
                 !hmap(sr.x_ack, (size_t) 2 * devs.size() * 32, err)))
                return false;
            const int sg = L[(size_t) sr.layer].grp;
            for (size_t di = 0; di < devs.size(); ++di)
                if ((sr.ckv[di] != nullptr || sr.ik[di] != nullptr) && devs[di].grp != sg) sr.readers.push_back((int) di);
        }
        for (Group& G : groups) {
            G.ar.nm = (int) G.mem.size();
            G.ar.slots = 4;
            G.ar.stride = (size_t) kWin * g.dim;
            if (G.ar.nm > 1 && (!hmap(G.ar.data, (size_t) G.ar.nm * G.ar.slots * G.ar.stride, err) ||
                                !hmap(G.ar.flags, (size_t) G.ar.nm * G.ar.slots * 32, err)))
                return false;
            // three members or more: the reduce-scatter's sums and its per-block flags (allreduce)
            if (G.ar.nm > 2 && (!hmap(G.ar.sums, (size_t) G.ar.slots * G.ar.stride, err) ||
                                !hmap(G.ar.bflags, (size_t) 2 * G.ar.nm * G.ar.slots * kArBlocks * 8, err)))
                return false;
            if (G.ar.nm > 1 && &G == &groups[(size_t) devs[(size_t) head_dev].grp] &&
                (!hmap(G.lg_stage, (size_t) 2 * (G.ar.nm - 1) * kWin * ((g.vocab / 128 + G.ar.nm - 1) / G.ar.nm * 128), err) ||
                 !hmap(G.lg_flag, (size_t) 2 * (G.ar.nm - 1) * 32, err) || !hmap(G.lg_ack, (size_t) 2 * 32, err)))
                return false;
            G.arb = G.ar;   // (a chunk's: two slots of chunk rows)
            G.arb.slots = 2;
            G.arb.stride = (size_t) chunk * g.dim;
            if (chunk > 0 && G.arb.nm > 1 && (!hmap(G.arb.data, (size_t) G.arb.nm * G.arb.slots * G.arb.stride, err) ||
                                              !hmap(G.arb.flags, (size_t) G.arb.nm * G.arb.slots * 32, err)))
                return false;
            if (chunk > 0 && G.arb.nm > 2 &&
                (!hmap(G.arb.sums, (size_t) G.arb.slots * G.arb.stride, err) ||
                 !hmap(G.arb.bflags, (size_t) 2 * G.arb.nm * G.arb.slots * kArBlocks * 8, err)))
                return false;
            if (chunk > 0) ar_p2pk_setup(G, G.arb);   // DS4_AR_P2PK (build 9: on unless =0)
        }
        if (g.n_mtp > 0) {
            if (!halloc(h_taps, (size_t) tap_cap * g.d_targets.size() * g.dim, err)) return false;
            CK(cudaSetDevice(devs[(size_t) d_dev].id));
            CK(cudaEventCreateWithFlags(&ev_seed, cudaEventDisableTiming));
            CK(cudaEventRecord(ev_seed, devs[(size_t) d_dev].st));
            if (draft_tp) {   // (the rings' way from the lead to the members, and each member's done-with-it event)
                const Layer& l0 = L[(size_t) g.nl];
                if (!halloc(h_dring, (size_t) g.n_mtp * g.win * win_rb(), err)) return false;
                CK(cudaEventCreateWithFlags(&ev_dring, cudaEventDisableTiming));
                ev_dring_in.assign((size_t) l0.nm, nullptr);
                for (int m = 1; m < l0.nm; ++m) {
                    const Dev& e = devs[(size_t) groups[(size_t) l0.grp].mem[(size_t) m]];
                    CK(cudaSetDevice(e.id));
                    CK(cudaEventCreateWithFlags(&ev_dring_in[(size_t) m], cudaEventDisableTiming));
                    CK(cudaEventRecord(ev_dring_in[(size_t) m], e.st));
                }
                CK(cudaSetDevice(devs[(size_t) d_dev].id));
            }
        }
        // the dense weights, each device's layers by a thread of its own
        {
            std::vector<std::string> errs(devs.size());
            std::vector<std::thread> th;
            for (size_t di = 0; di < devs.size(); ++di)
                th.emplace_back([this, di, &errs] {
                    std::string e;
                    if (!load_dense((int) di, e)) errs[di] = e;
                });
            for (auto& t : th) t.join();
            for (auto& e : errs)
                if (!e.empty()) {
                    err = e;
                    return false;
                }
        }
        if (o.verbose)
            std::fprintf(stderr, "ds4: dense weights loaded in %.1f s\n", (now_ms() - t0) / 1000.0);
        // the markov steps over a head group of two or more (DS4_MK_SPLIT=0: the lead's whole rows, as before): E
        // host-mapped, the steps' slots
        // (only where every member holds its rows of the markov head: a type load_dense does not take keeps the lead's)
        bool mk_rows = g.n_mtp > 0 && head_nm() > 1;
        for (int m : groups[(size_t) devs[(size_t) head_dev].grp].mem) mk_rows = mk_rows && devs[(size_t) m].mk_share != nullptr;
        if (mk_rows && !(std::getenv("DS4_MK_SPLIT") != nullptr && std::atoi(std::getenv("DS4_MK_SPLIT")) == 0)) {
            const Tensor* te = pk.get("mtp." + std::to_string(g.n_mtp - 1) + ".markov_head.embed.weight");
            if (te == nullptr || te->dtype != "BF16" || te->bytes != (uint64_t) g.vocab * g.d_rank * 2) {
                err = "the markov embed: not a BF16 [vocab][rank] table";
                return false;
            }
            if (!hmap(h_mk_embed, (size_t) g.vocab * g.d_rank, err) || !pk.read(*te, h_mk_embed) ||
                !hmap(mk_slots, (size_t) kWin * head_nm() * 4, err)) {
                if (err.empty()) err = "the markov embed: read failed";
                return false;
            }
            devs[(size_t) head_dev].mk_ints = d_ints;   // (the lead's drafted tokens: where the confidence head reads them)
            mk_split = true;
        }

        // the embedding table, pinned on the host
        {
            const Tensor* t = pk.get("embed.weight");
            const size_t nv = (size_t) g.vocab * g.dim;
            const bool q8 = t != nullptr && t->dtype == "Q8_0" && t->bytes == nv / 32 * gg::kQ8Bytes;
            // other block types (a GGUF whose dense tensors are Q4_K / Q5_K / Q6_K: the IST-DAS sets' Q5_K embed.weight):
            // each row through ggml's to_float, to the same BF16 the host table holds
            const int ety = t != nullptr ? gg_type_of(t->dtype) : -1;
            const size_t erb = ety > 0 ? gg::type_row_bytes(ety, g.dim) : 0;
            const bool qrow = t != nullptr && !(t->dtype == "BF16") && erb > 0 && t->bytes == (size_t) g.vocab * erb;
            if (t == nullptr || (!q8 && !qrow && (t->dtype != "BF16" || t->bytes != nv * 2))) {
                err = "embed.weight: not a BF16 (or Q8_0 / a ggml block type) [vocab][dim] table";
                return false;
            }
            if (!halloc(embed_pinned, nv, err)) return false;
            if (qrow) {   // (ggml's decode of each row, rounded to BF16 as the Q8_0 path rounds)
                std::vector<uint8_t> row(erb);
                for (size_t r = 0; r < (size_t) g.vocab; ++r) {
                    if (!pk.read_at(t->file, t->off + r * erb, erb, row.data())) {
                        err = "embed.weight: read failed";
                        return false;
                    }
                    if (!gg::gg_row_to_bf16(ety, row.data(), g.dim, embed_pinned + r * g.dim)) {
                        err = "embed.weight: ggml has no decode for " + t->dtype;
                        return false;
                    }
                }
            } else if (q8) {   // (a GGUF's: each value rounded to BF16, a row at a time)
                std::vector<uint8_t> row((size_t) g.dim / 32 * gg::kQ8Bytes);
                for (size_t r = 0; r < (size_t) g.vocab; ++r) {
                    if (!pk.read_at(t->file, t->off + r * row.size(), row.size(), row.data())) {
                        err = "embed.weight: read failed";
                        return false;
                    }
                    const std::vector<float> v = q8_values(row.data(), (size_t) g.dim);
                    for (size_t c = 0; c < (size_t) g.dim; ++c) {
                        uint32_t u;
                        std::memcpy(&u, &v[c], 4);
                        u += 0x7fffu + ((u >> 16) & 1u);   // round to nearest even
                        embed_pinned[r * g.dim + c] = (uint16_t) (u >> 16);
                    }
                }
            } else if (!pk.read(*t, embed_pinned)) {
                err = "embed.weight: read failed";
                return false;
            }
            if (ds4_dbg("DS4_DBG_EMB")) std::fprintf(stderr,
                    "DBG emb pinned: %04x %04x %04x %04x  (row1: %04x %04x)\n",
                    (unsigned) embed_pinned[0], (unsigned) embed_pinned[1],
                    (unsigned) embed_pinned[2], (unsigned) embed_pinned[3],
                    (unsigned) embed_pinned[(size_t) g.dim], (unsigned) embed_pinned[(size_t) g.dim + 1]);

        }
        // the host side of the CPU lane and the Engram rows
        const int cols = (pk.eg_ngram - 1) * pk.eg_heads;
        if (!halloc(h_x, (size_t) kWin * g.dim, err) || !halloc(h_w, (size_t) kWin * kPicks, err) ||
            !halloc(h_part, (size_t) kWin * g.dim, err) || !halloc(h_idx, (size_t) kWin * kPicks, err) || !halloc(h_idx_a, (size_t) 2 * kPicks, err) ||
            !halloc(h_emb, (size_t) std::max(kWin, chunk) * g.dim, err) ||
            !halloc(h_eg, (size_t) std::max(1, pk.eg_layers) * eg_cap * cols * (pk.eg_hd + pk.eg_hd / 32) + 64, err))
            return false;
        if (pk.eg_layers > 0) {
            // the Engram rows' reader: threads enough to keep an SSD's queue busy (reads from the page cache need few);
            // the row cache a small share of the RAM free (DS4_ENGRAM_CACHE_MB: its size, 0 off; DS4_ENGRAM_THREADS)
            const size_t row = (size_t) pk.eg_hd + pk.eg_hd / 32;
#if defined(_WIN32)
            // (Windows: each thread's ReadFile is synchronous, so the threads are the queue depth - Project Maya: a 28K-token
            //  prompt in one chunk, 10 threads 17.1 s, 64 13.4 s on a 20-core PC.  Here (6 cores, shipped profile) 64 readers
            //  gave +4.5% on a 4K prompt but no decode gain in every pair: DS4_ENGRAM_THREADS=64 turns them on)
#endif
            const unsigned hw = std::max(1u, std::thread::hardware_concurrency());
            int nth = (int) std::min(16u, std::max(4u, hw / 2));
#if defined(STRATA_METAL)
            // A Mac reads the Engram rows with two threads: with more, a decode of the same prompt gave slightly different words run to run
            // (3 to 9 runs of 16 differed from the serial reference, against none of 24 with one or two threads; the cause is not found yet).  DS4_ENGRAM_THREADS=N sets another number.
            nth = 2;
            if (std::getenv("DS4_ENGRAM_THREADS") == nullptr) std::fprintf(stderr, "ds4: Engram rows are read with 2 threads (DS4_ENGRAM_THREADS=N sets another number)\n");
#endif
            if (const char* e = std::getenv("DS4_ENGRAM_THREADS")) nth = std::max(1, std::atoi(e));
            const uint64_t avail = ram_avail();
            uint64_t mb = avail == ~uint64_t{0} ? 64 : std::min<uint64_t>(256, std::max<uint64_t>(16, (avail >> 20) / 64));
            if (const char* e = std::getenv("DS4_ENGRAM_CACHE_MB")) mb = std::strtoull(e, nullptr, 10);
            eg_cache.init((size_t) ((mb << 20) / row), row);
            std::vector<std::string> paths;
            for (const std::string& fn : pk.files) paths.push_back(pk.model_dir + "/" + fn);
            // Windows: the Engram tables' files that hold nothing else are unmapped and read unbuffered - an SSD's
            // queue kept by the reader threads instead of the page cache's (whose reads of one file from many threads
            // went ~255K rows a second here); unbuffered reads of a mapped file take a slow path, so only unmapped
            // ones (off by default: -8% on a 4K prompt here; DS4_EG_DIRECT=1 turns it on)
            std::vector<char> eg_direct(pk.files.size(), 0);
#if defined(_WIN32)
            if (pk.gguf && std::getenv("DS4_EG_DIRECT") != nullptr && std::atoi(std::getenv("DS4_EG_DIRECT")) != 0) {
                std::vector<char> eg_file(pk.files.size(), 0), other(pk.files.size(), 0);
                for (const auto& kt : pk.t)
                    if (kt.second.file >= 0 && (size_t) kt.second.file < pk.files.size())
                        (kt.first.find(".engram.embed.") != std::string::npos ? eg_file : other)[(size_t) kt.second.file] = 1;
                for (size_t i = 0; i < pk.files.size(); ++i)
                    if (eg_file[i] && !other[i]) {
                        if (i < pk.maps.size() && pk.maps[i].first != nullptr) {
                            os::unmap(pk.maps[i].first, pk.maps[i].second);
                            pk.maps[i] = {nullptr, 0};
                        }
                        eg_direct[i] = 1;
                        if (o.verbose) std::fprintf(stderr, "ds4: %s unmapped, its Engram rows read unbuffered\n",
                                                    pk.files[i].c_str());
                    }
            }
#endif
            eg_io.start(paths, nth, eg_direct);
            for (int li = 0; li < pk.eg_layers; ++li) {
                eg_win.emplace_back(new EgBatch());
                const std::string id = std::to_string(g.eg_layers[(size_t) li]);
                const Tensor* tw = pk.get("layers." + id + ".engram.embed.weight");
                // The row layout the reader and the dequant take.  A type not here (or no tensor at all) would be read
                // as some other format's bytes - the old code then read the scale tensor of a pack that has none and
                // crashed in eg_issue - so refuse the pack once, with the type's name, before any token is read.
                int fmt;
                if (tw == nullptr) {
                    std::fprintf(stderr, "ds4: Engram layer %s: engram.embed.weight is missing from the pack\n", id.c_str());
                    std::exit(2);
                } else if (tw->dtype == "MXFP8") {
                    fmt = 0;
                } else if (tw->dtype == "Q6_K") {
                    fmt = 1;
                } else if (tw->dtype == "IQ4_NL") {
                    fmt = 2;
                } else if (pk.get("layers." + id + ".engram.embed.scale") != nullptr) {
                    fmt = 3;   // (an old pack: FP8 codes in one tensor, their E8M0 scales in another)
                } else {
                    std::fprintf(stderr,
                                 "ds4: Engram layer %s: engram.embed.weight type %s is not one the Engram reader handles "
                                 "(MXFP8, Q6_K, IQ4_NL)\n",
                                 id.c_str(), tw->dtype.c_str());
                    std::exit(2);
                }
                if (fmt == 1 && pk.eg_hd % 256 != 0) {
                    err = "Engram layer " + id + ": Q6_K rows of " + std::to_string(pk.eg_hd) +
                          " values (not whole superblocks of 256)";
                    return false;
                }
                if (fmt == 2 && pk.eg_hd % 32 != 0) {
                    err = "Engram layer " + id + ": IQ4_NL rows of " + std::to_string(pk.eg_hd) +
                          " values (not whole blocks of 32)";
                    return false;
                }
                eg_fmt.push_back((uint8_t) fmt);
                eg_tw.push_back(tw);
                eg_ts.push_back(pk.get("layers." + id + ".engram.embed.scale"));
            }
            if (o.verbose)
                std::fprintf(stderr, "ds4: Engram rows read on %d threads, issued with the tokens, collected before "
                                     "their layer; row cache %llu MB (%zu rows)\n",
                             nth, (unsigned long long) mb, eg_cache.capacity());
        }
        prof.assign((size_t) (g.nl + g.n_mtp) * g.n_exp, 0u);
        if (!o.profile.empty()) {
            std::FILE* f = std::fopen(o.profile.c_str(), "rb");
            if (f != nullptr) {
                std::vector<uint32_t> p(prof.size());
                const size_t n = std::fread(p.data(), 4, p.size(), f);
                if (n == p.size() || n == (size_t) g.nl * g.n_exp) std::copy(p.begin(), p.begin() + (long) n, prof.begin());
                std::fclose(f);
            }
        }

        // the chunked prompt path's buffers (before the experts: they take what is left)
        if (chunk > 0) {
            // recommend, never force: a chunk the cards cannot hold in buffers is halved (down to 256 rows) and then the
            // prompt runs in windows of 16, said in one line - the load only fails for a reason that is not this
            std::vector<size_t> na0, sc0;
            for (Dev& d : devs) {
                na0.push_back(d.allocs.size());
                sc0.push_back(d.scratch);
            }
            const size_t nh = host_allocs.size();
            std::string aerr;
            while (chunk > 0 && !alloc_chunks(aerr)) {
                for (size_t di = 0; di < devs.size(); ++di) {
                    Dev& d = devs[di];
                    cudaSetDevice(d.id);
                    cudaDeviceSynchronize();
                    if (di < chunks.size() && chunks[di]) {
                        if (chunks[di]->blas) cublasDestroy(chunks[di]->blas);
#if defined(DS4_MIX_ROCBLAS)
                        if (chunks[di]->mix_rb) rocblas_destroy_handle(chunks[di]->mix_rb);
#endif
                        if (chunks[di]->cs) cudaStreamDestroy(chunks[di]->cs);
                    }
                    while (d.allocs.size() > na0[di]) {
                        cudaFree(d.allocs.back());
                        d.allocs.pop_back();
                    }
                    d.scratch = sc0[di];
                }
                while (host_allocs.size() > nh) {
                    cudaFreeHost(host_allocs.back());
                    host_allocs.pop_back();
                }
                chunks.clear();
                if (slab_auto_grew_) {   // the automatic slab did not fit: the 0.2.6 slab first, the chunk only if that does not fit either
                    slab_auto_grew_ = false;
                    slab_force_base_ = true;
                    std::fprintf(stderr, "ds4: the automatic attention slab did not fit (%s): trying the 256-row slab\n", aerr.c_str());
                    aerr.clear();
                    continue;
                }
                const int was = chunk;
                chunk = chunk > 512 ? chunk / 2 / 16 * 16 : 0;
                if (chunk > 0) {
                    eg_cap = (size_t) chunk;
                    std::fprintf(stderr, "ds4: the prompt path's buffers for chunks of %d rows did not fit (%s): trying %d\n",
                                 was, aerr.c_str(), chunk);
                } else {
                    prompt_par = false;
                    eg_cap = (size_t) kWin;
                    tap_cap = kWin;
                    std::fprintf(stderr, "ds4: the prompt path's buffers did not fit (%s): prompts run in windows of %d "
                                         "tokens (slower on long prompts; more free GPU memory or a lower --reserve-mib "
                                         "brings the chunks back)\n", aerr.c_str(), kWin);
                }
                aerr.clear();
            }
            if (chunk > 0 && aerr.empty()) err.clear();
        }
        // the CPU lane's experts read in place (decided above): how much of them the load reads ahead, from what VRAM
        // now leaves over
        if (file_experts) {
            double room = 0, all = 0;   // the VRAM place_experts will find for experts; every expert's bytes
            for (Dev& d : devs) {
                cudaSetDevice(d.id);
                size_t fr = 0, tot = 0;
                CK(cudaMemGetInfo(&fr, &tot));
                fr = uma_free(d.id, fr);
                room += std::max(0.0, (double) fr - (double) ((size_t) o.reserve_mib << 20)) * o.vram_experts;
            }
            for (const Layer& l : L) all += (double) l.blob * l.n_exp;
            const double need = std::max(0.0, all - room);
            const uint64_t avail = ram_avail();
            warm_bytes = avail > kRamMargin ? std::min<uint64_t>(avail - kRamMargin, (uint64_t) need) : 0;
            if (avail == ~uint64_t{0}) warm_bytes = (uint64_t) need;
            if (store_gb() > 0) warm_bytes = 0;   // (the store is the RAM tier: nothing to warm in the OS cache)
            std::fprintf(stderr,
                         "ds4: the experts VRAM leaves over (~%.1f GB) are read in place from the model's files%s "
                         "(%.1f GB of RAM free to keep them: the most-routed %.1f GB read ahead; prompts in chunks of %d)\n",
                         need / 1e9, o.mmap_experts > 0 ? " (--mmap-experts on)"
                                     : pk.gguf ? " (--mmap-experts off copies them into RAM)" : ", not copied into RAM",
                         avail == ~uint64_t{0} ? 0.0 : avail / 1e9, warm_bytes / 1e9, chunk);
        }
        // the CPU lane: one pool of workers per NUMA node, each expert split in NH column parts (part X on node X); in
        // place, one part (the files' layout) and one pool over every node's cores (the pages lie where the cache put them)
        cores = node_cores();
        NH = file_experts ? 1 : (int) std::min<size_t>(2, cores.size());
        if (NH > 1 && ((g.ff / NH) % 128 != 0 || (g.dim / NH) % 128 != 0)) NH = 1;
        if (!pk.gguf) make_pools();   // (a GGUF's after its experts: copy_experts decides NH)
        {
            const size_t E = (size_t) g.dim, FF = (size_t) g.ff, GQ = E / 256, DQ = FF / 128, S = kSlots;
            c_xh.resize((size_t) NH * S * 2 * E);
            c_xsb.resize((size_t) NH * S * 2 * (E / 128));
            c_acc.resize((size_t) NH * S * 2 * GQ * (FF / NH));
            c_xhd.resize(S * FF);
            c_xsd.resize(S * (FF / 128));
            c_accd.resize((size_t) NH * S * DQ * (E / NH));
            c_yd.resize(S * E);
        }
        // DS4_BATCH_DECODE=N: the sequence banks first, out of what the experts would have had (off: nothing)
        if (!bank_alloc(err)) return false;
        // the experts: VRAM slots in what each device has left, the rest on the host
        if (!place_experts(err)) return false;
        if (!load_experts(err)) return false;
        if (!helper_fill(err)) return false;   // the helper's share of the experts VRAM left out (no-op with it off)
#if defined(STRATA_USE_HIP)
        if (diag_enabled()) diag_after_experts();
#endif
        if (pk.gguf) make_pools();
        if (chunk > 0) {
            // the CPU lane's parts pinned (the chunks stream them to the GPUs by DMA), each layer's virtual slots
            const double tr = now_ms();
            // DS4_PIN_LANE=0 (A/B, default 1 = pinned as before): leave the CPU lane's parts pageable.  A pinned
            // (userptr) range on Linux is not long-term pinned: khugepaged / compaction moving one of its pages fires the
            // MMU notifier, and amdgpu then evicts every queue of the process and revalidates all its userptr BOs.
            lane_pinned = !(std::getenv("DS4_PIN_LANE") && std::atoi(std::getenv("DS4_PIN_LANE")) == 0);
            if (lane_pinned)
                for (auto& m : host_maps)
                    if (cudaHostRegister(m.first, m.second, cudaHostRegisterPortable) != cudaSuccess) {
                        err = "pinning the CPU lane's experts (" + std::to_string(m.second >> 20) + " MiB) failed";
                        return false;
                    }
            if (!host_maps.empty())
                std::fprintf(stderr, "ds4: CPU lane's experts %s in %.1f s\n", lane_pinned ? "pinned" : "left pageable (DS4_PIN_LANE=0)",
                             (now_ms() - tr) / 1000.0);
            if (file_experts) {   // in place: each device's staging for its ring, and its readers (DS4_READERS, 8)
                size_t mr = 0;
                for (const Layer& l : L)
                    if (!l.mtp) {
                        for (uint64_t r : l.region_bytes) mr = std::max<size_t>(mr, r);
                        if (l.lay.fmt == gg::kFmtMXFP4) {   // (a GGUF's: read as its blob)
                            mr = std::max(mr, l.blob);
                            for (int r = 0; r < 3; ++r) flow_part[r] = std::max(flow_part[r], mx_part_bytes(l, r));
                        }
                    }
                const char* nr = std::getenv("DS4_READERS");
                const int n_readers = std::max(1, nr != nullptr ? std::atoi(nr) : 8);
                const bool flow_on = std::getenv("DS4_FLOW") == nullptr || std::atoi(std::getenv("DS4_FLOW")) != 0;
                // (a tensor-parallel group's members on the flow only with DS4_FLOW_TP=1 for now: each reads the
                // whole down of every expert it streams, 25 MB an expert for a pair, 18.8 alone - 3x V100, the
                // 17-token prompt from the page cache: 2.5-2.7 s on the flow, 1.3-1.6 s in the group's windows)
                const bool flow_tp = std::getenv("DS4_FLOW_TP") != nullptr && std::atoi(std::getenv("DS4_FLOW_TP")) != 0;
                for (size_t di = 0; di < chunks.size(); ++di) {
                    auto& cp = chunks[di];
                    if (cp == nullptr || cp->ring == nullptr) continue;
                    cp->stage_stride = (mr + 4095) & ~(size_t) 4095;
                    // the flow: every trunk layer of the device a GGUF's (alone or a tensor-parallel group's member)
                    bool fl = flow_on;
                    int n_exp_max = 0;
                    for (const Layer& l : L)
                        if (!l.mtp)
                            for (int m = 0; m < l.nm; ++m)
                                if (member(l, m).dev == (int) di) {
                                    // (a group's members: each its share of the down's blocks in every row.  tp4:
                                    //  not an uneven split's - the flow's reads, copies and run_set take even shares
                                    //  (Maya's flow port, e3f2475's second half / 0fd1370, is not in this branch))
                                    fl = fl && l.lay.fmt == gg::kFmtMXFP4 &&
                                         (l.nm == 1 || (flow_tp && !tp_uneven && (g.ff / l.nm) %
                                                        std::max(1, gg::type_block(gg::expert_type(l.lay, 2))) == 0));
                                    n_exp_max = std::max(n_exp_max, l.n_exp);
                                }
                    if (fl)   // (each part read unbuffered from its offset rounded down: a page more each)
                        cp->stage_stride = std::max(cp->stage_stride, flow_stride());
                    cp->S = cp->ring_n;
                    if (!halloc(cp->stage, (size_t) cp->S * cp->stage_stride, err)) return false;
                    cp->readers = std::make_unique<Pool>(n_readers - 1, std::vector<int>{}, 50);
                    if (!fl) continue;
                    cudaSetDevice(devs[di].id);
                    cp->flow = true;
#if defined(STRATA_METAL)
                    cp->direct = std::getenv("DS4_FLOW_DIRECT") == nullptr || std::atoi(std::getenv("DS4_FLOW_DIRECT")) != 0;
#endif
                    cp->dev = (int) di;
                    cp->io = std::make_unique<IoQueue>(n_readers);
                    cp->stage_item.assign((size_t) cp->S, -1);
                    cp->stage_ev.resize((size_t) cp->S);
                    cp->ring_fill.resize((size_t) cp->ring_n);
                    cp->ring_free.resize((size_t) cp->ring_n);
                    for (auto* v : {&cp->stage_ev, &cp->ring_fill, &cp->ring_free})
                        for (cudaEvent_t& e : *v) CK(cudaEventCreateWithFlags(&e, cudaEventDisableTiming));
                    // (a region is written again only bc_n batches later - more than a layer's items, so after that
                    // layer's bounds wait, which every copy from it precedes)
                    cp->bc_n = n_exp_max + 2;
                    cp->bc_w = cp->ring_n + 1;
                    if (!halloc(cp->bc_pin, (size_t) cp->bc_n * cp->bc_w, err) ||
                        !dalloc(devs[di], cp->bc_dev, (size_t) cp->bc_n * cp->bc_w, err))
                        return false;
                }
                // every device with layers on the flow: a prompt reads only the experts it picks, once, so a short one
                // takes the chunked path too (one pass, where windows of 16 read the CPU lane's picks again for each
                // window, a page fault at a time) - DS4_CHUNK_MIN still overrides
                bool all_flow = true;
                for (const auto& cp : chunks) all_flow = all_flow && (cp == nullptr || cp->ring == nullptr || cp->flow);
                if (all_flow && std::getenv("DS4_CHUNK_MIN") == nullptr) chunk_min = kFlowChunkMin;
            }
            for (Layer& l : L) {
                if (l.mtp) continue;
                for (int m = 0; m < l.nm; ++m) {   // (each member its own: the flow's members decide them each)
                    Layer& x = member(l, m);
                    if (!halloc(x.vs_pin, (size_t) l.n_exp, err)) return false;
                    if (!dalloc(devs[(size_t) x.dev], x.vs_dev, (size_t) l.n_exp, err)) return false;
                }
            }
        }
        {
            void* m = nullptr;
#if defined(STRATA_USE_HIP)
            if (helper_dd && hlp.enabled()) {   // DS4_HELPER_DD: the helpers' heads read the ring: fine-grained (coherent)
                if (hipHostMalloc(&m, sizeof(Req) * kRing, hipHostMallocCoherent | hipHostMallocMapped | hipHostMallocPortable) != hipSuccess) {
                    err = "fine-grained host memory for the decode path's requests (DS4_HELPER_DD)";
                    return false;
                }
            } else
#endif
            if (cudaHostAlloc(&m, sizeof(Req) * kRing, cudaHostAllocMapped | cudaHostAllocPortable) != cudaSuccess) {
                err = "host-mapped memory for the decode path's requests";
                return false;
            }
            host_allocs.push_back(m);
            reqs = (Req*) m;
            if (cudaHostAlloc(&m, sizeof(Resp) * kRing, cudaHostAllocMapped | cudaHostAllocPortable) != cudaSuccess) {
                err = "host-mapped memory for the decode path's answers";
                return false;
            }
            host_allocs.push_back(m);
            resps = (Resp*) m;
            if (helper_defer) {   // DS4_HELPER_DEFER: the deferred ring
                if (cudaHostAlloc(&m, sizeof(Resp) * kRing, cudaHostAllocMapped | cudaHostAllocPortable) != cudaSuccess) {
                    err = "host-mapped memory for the deferred helper rows (DS4_HELPER_DEFER)";
                    return false;
                }
                host_allocs.push_back(m);
                dresps = (Resp*) m;
                std::memset((void*) dresps, 0, sizeof(Resp) * kRing);
            }
            std::memset((void*) reqs, 0, sizeof(Req) * kRing);
            std::memset((void*) resps, 0, sizeof(Resp) * kRing);
            for (auto& x : layer_of) x.store(-1);
            ahead_fl.assign(L.size() * 1024, 0);
            ahead_rank.assign(L.size() * 1024, 0);
            ahead_for.assign(L.size(), 0);
            if (const char* v = std::getenv("DS4_TP_CHECK"); v != nullptr && std::strcmp(v, "1") == 0 && !tp_check(err))
                return false;   // (tp4: DS4_TP_CHECK=1, at load - no request yet)
            if (ecown && ec_fix) {   // DS4_ECOWN
                err = "DS4_ECOWN=1 and DS4_EC_FIX=1 together: one of them (ECOWN lets the cache promote helper-held experts, EC_FIX forbids it)";
                return false;
            }
            if (helper_dd && hlp.enabled() && !dd_setup(err)) return false;   // DS4_HELPER_DD (before the lane starts)
            if (helper::pf_helper_rows() > 0 && !pfh_setup(err)) return false;   // DS4_PF_HELPER (before the lane starts)
            const int core = !cores.empty() && !cores[0].empty() ? cores[0][0] : -1;
            service = std::thread([this, core] {
                if (core >= 0) pin_self(core);
                serve_lane();
            });
            if (ahead_mode > 0) pf_th = std::thread([this] { prefetch_loop(); });
        }
        if (o.expert_cache) {
            size_t maxb = 0;
            for (const Layer& l : L) maxb = std::max(maxb, l.blob);
            const int nt = std::max(1, std::min(c_inflight, std::getenv("DS4_CACHE_THREADS") ? std::atoi(std::getenv("DS4_CACHE_THREADS")) : 1));
            sw_bufs.resize((size_t) nt);
            for (SwapBufs& B : sw_bufs) {
                if (!halloc(B.a, maxb, err) || !halloc(B.b, maxb, err) || !halloc(B.h, maxb, err)) return false;
                for (Dev& d : devs) {
                    cudaSetDevice(d.id);
                    cudaStream_t cs = nullptr;
                    CK(cudaStreamCreateWithFlags(&cs, cudaStreamNonBlocking));
                    B.st.push_back(cs);
                }
            }
            for (SwapBufs& B : sw_bufs) cache_ths.emplace_back([this, &B] { cache_loop(B); });
        }
        if (ec_fix)   // DS4_EC_FIX (see ec_fix)
            std::fprintf(stderr, "ds4: DS4_EC_FIX=1: the expert cache never swaps a helper-held expert into VRAM (%zu helpers%s)\n",
                         (size_t) hlp.size(), o.expert_cache ? "" : "; no expert cache here: nothing to do");
        else if (std::getenv("DS4_EC_FIX") != nullptr && std::atoi(std::getenv("DS4_EC_FIX")) != 0)
            std::fprintf(stderr, "ds4: DS4_EC_FIX=%s is not 1: off (the swaps as before)\n", std::getenv("DS4_EC_FIX"));
        if (ecown)   // DS4_ECOWN (see ecown)
            std::fprintf(stderr, "ds4: DS4_ECOWN=1: a helper-held expert the cache swaps into VRAM is computed by the lead only (the request's "
                                 "in-VRAM marks; %s%s)\n", dd_live ? "device-direct helpers live" : "no device-direct helpers here: nothing to do",
                         o.expert_cache ? "" : "; no expert cache here");
        else if (std::getenv("DS4_ECOWN") != nullptr && std::atoi(std::getenv("DS4_ECOWN")) != 0)
            std::fprintf(stderr, "ds4: DS4_ECOWN=%s is not 1: off (build 16 as it was)\n", std::getenv("DS4_ECOWN"));
        if (c_det || c_freeze > 0)   // DS4_CACHE_DET / DS4_CACHE_FREEZE (test only)
            std::fprintf(stderr, "ds4: TEST MODE%s%s%s\n", c_det ? " DS4_CACHE_DET=1 (every queued move landed at each tick; settle by rounds)" : "",
                         c_freeze > 0 ? " DS4_CACHE_FREEZE (placement fixed after prompt read " : "",
                         c_freeze > 0 ? (std::to_string(c_freeze) + ")").c_str() : "");
        if (!dd_audit && std::getenv("DS4_DD_AUDIT") != nullptr && std::atoi(std::getenv("DS4_DD_AUDIT")) != 0)   // DS4_DD_AUDIT
            std::fprintf(stderr, "ds4: DS4_DD_AUDIT=%s is off (it needs =1 and device-direct helpers live)\n", std::getenv("DS4_DD_AUDIT"));
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            CK(cudaStreamSynchronize(d.st));
        }
        if (par || chunk > 0)   // (the windows' threads; the prompt path's, whatever mode the windows take)
            for (size_t di = 0; di < devs.size(); ++di) {
                workers.push_back(std::make_unique<Worker>());
                workers.back()->start();
            }
        if (!hw_pubt_setup(err)) return false;   // (helperwin DS4_HW_PUBT: after every placement; before the checks)
        if (!fuse_checks(err)) return false;   // (the decode fusions' load-time checks; no request yet)
        calibrate_paths();
        init_store();      // (last: the store's arena is registered with the driver - page-locked memory the other pinned allocations must come before)
        preload_store();
        // On by default for a Windows HIP build on an APU (Strix Halo: measured +7.5% decode, no change in the prompt); DS4_NO_VIEW=1 forces it
        // on anywhere, DS4_NO_VIEW=0 turns it off
        bool no_view = std::getenv("DS4_NO_VIEW") != nullptr && std::atoi(std::getenv("DS4_NO_VIEW")) != 0;
#if defined(_WIN32) && defined(STRATA_USE_HIP)
        if (std::getenv("DS4_NO_VIEW") == nullptr && !devs.empty()) {
            cudaDeviceProp vp{};
            no_view = cudaGetDeviceProperties(&vp, devs[0].id) == cudaSuccess && vp.integrated != 0;
        }
#endif
        if (no_view && store && pk.gguf) {
            pk.drop_views();
            store->set_pfds(pk.pfds);
            views = false;
            std::fprintf(stderr, "ds4: no view of the model's files after the load: unbuffered reads at the drive's rate\n");
        }
        if (o.verbose) std::fprintf(stderr, "ds4: loaded in %.1f s\n%s", (now_ms() - t0) / 1000.0, describe().c_str());
        if (chunk > 0) (void) pick_flow_min();   // (the startup line)
        // the decode's per-window lists sized now, so a decode token never grows one (a heap grown in the decode waits
        // for the mm lock: docs/dsv41/cards/EB-05.md, mechanism 2)
        for (Layer& l : L) l.cpu_hits.reserve(2 * (size_t) kSlots);   // (a window's picks; the lane adds, cache_tick empties)
        {
            std::lock_guard<std::mutex> lk(sw_mu);
            sw_ready.reserve(64);
            ram_ready.reserve(64);
        }
        sw_ready_tick.reserve(64);
        ram_ready_tick.reserve(64);
        rb_scratch.reserve(devs.size());
        reset();
        start_warm();
        // (FG-04): load waits for the warm-up, a load cost like the pinning - the first prompt never waits
        // on warm_mu, so its time is the prompt's alone and this line is the load-time price (with a tuned mix table: the
        // per-solution code-object loads too).  DS4_WARM_WAIT=0: in the background, as before.
        if (warm_bg.joinable() && !(std::getenv("DS4_WARM_WAIT") && std::atoi(std::getenv("DS4_WARM_WAIT")) == 0)) {
            const double tw = now_ms();
            warm_bg.join();
            std::fprintf(stderr, "ds4: load waited %.0f ms for the prompt path's warm-up (DS4_WARM_WAIT=0: in the background)\n",
                         now_ms() - tw);
        }
        return true;
    }


    // the caches' row bytes, packed as DeepSeek keeps them (ds4_kernels.cuh): the window ring's (FP8), the compressed
    // KV's (FP4 + E4M3 scales), the index keys' (FP4 + power-of-two scales)
    size_t win_rb() const { return kv_row_bytes(kKvFp8, g.hd); }
    size_t ckv_rb() const { return kv_row_bytes(kKvFp4, g.hd); }
    size_t ik_rb() const { return kv_row_bytes(kKvFp4p, g.ix_hd); }

    // The chunked prompt's first GEMM of each kind pays the BLAS library's start (its handle's heuristics, the code objects of its
    // kernels loaded on first use): ~1 s of hipModuleLoad plus ~2.5 s of library time on the R9700 (rocprofv3), 1-2 s on CUDA, once a
    // process - 3.6 s on the first prompt that went through the flow, measured as 4.9 s for a 25-token pass against 1.0 s for the
    // next one.  Paid here instead, at load, on a thread beside the store's read: the chunk GEMMs on tiny inputs into the chunk's own
    // scratch buffers (the mHC mix GEMM in F32, the FP16 GEMM the projections and the indexer weights use) - no engine state is
    // touched (heat, profile, stats, positions, KV), so the answers are what they were.  DS4_WARM=0 turns it off.
    void warm_flow() {
        const int T = 16, D = g.dim, hcd = g.hc * g.dim, n_mix = (2 + g.hc) * g.hc;
        const float one = 1.0f, zero = 0.0f;
        for (size_t di = 0; di < chunks.size(); ++di) {
            if (!chunks[di] || chunks[di]->blas == nullptr) continue;
            Chunk& c = *chunks[di];
            if (c.C < T) continue;
            cudaSetDevice(devs[di].id);
            (void) cublasSgemm(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, n_mix, T, hcd, &one, c.h, hcd, c.h, hcd, &zero, c.mix, 32);
#if defined(DS4_MIX_ROCBLAS)
            // the mix's rocBLAS handle too (with a tuned table), opened by its first product on the same scratch
            if (rocblas_handle rb = mix_handle(devs[di], c); rb && !c.mix_rb_open &&
                rocblas_gemm_ex(rb, rocblas_operation_transpose, rocblas_operation_none, n_mix, T, hcd, &one, c.h,
                                rocblas_datatype_f32_r, hcd, c.h, rocblas_datatype_f32_r, hcd, &zero, c.mix,
                                rocblas_datatype_f32_r, 32, c.mix, rocblas_datatype_f32_r, 32, rocblas_datatype_f32_r,
                                rocblas_gemm_algo_standard, 0, 0) == rocblas_status_success)
                c.mix_rb_open = true;
            // then each distinct tuned solution once - rocBLAS loads a solution's code object at its first launch, which
            // otherwise lands inside the first prompt (fresh process, 2K: +3.7 s then +1.0 s, H9pf28-20261109T041047Z) - at T
            // = its row's bucket (at most the chunk's rows), on the same scratch; a refusal is retried once (rocBLAS can refuse
            // the first launch while it sets up: gemm.cu try_rocblas_f16o).  Timed and printed.
            if (c.mix_rb && c.mix_rb_open && c.mix_tab) {
                const double tw = now_ms();
                std::vector<int> done;
                int warmed = 0, refused = 0;
                for (const auto& r : c.mix_tab->rows()) {
                    if (!r.f32 || !r.tuned || r.n != n_mix || r.k != hcd || r.ldy != 32) continue;
                    if (std::find(done.begin(), done.end(), r.solution) != done.end()) continue;
                    done.push_back(r.solution);
                    const int tr = std::min(r.t_bucket, c.C);
                    auto launch = [&] {
                        return rocblas_gemm_ex(c.mix_rb, rocblas_operation_transpose, rocblas_operation_none, n_mix, tr, hcd, &one,
                                               c.h, rocblas_datatype_f32_r, hcd, c.h, rocblas_datatype_f32_r, hcd, &zero, c.mix,
                                               rocblas_datatype_f32_r, 32, c.mix, rocblas_datatype_f32_r, 32,
                                               rocblas_datatype_f32_r, rocblas_gemm_algo_solution_index, r.solution, 0);
                    };
                    if (launch() == rocblas_status_success || launch() == rocblas_status_success) ++warmed;
                    else ++refused;
                }
                (void) cudaStreamSynchronize(devs[di].st);
                std::fprintf(stderr, "ds4: mHC mix rocBLAS warm-up CUDA%d: %d tuned solutions in %.0f ms (%d refused)\n",
                             devs[di].id, warmed, now_ms() - tw, refused);
            }
#endif
            const int ns[2] = {256, 32};
            for (int n : ns)
                (void) cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, n, T, D, &one, c.w16, CUDA_R_16F, D, c.x16, CUDA_R_16F, D, &zero,
                                    c.y, CUDA_R_32F, n, CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
            (void) cudaStreamSynchronize(devs[di].st);
            (void) cudaGetLastError();
        }
    }
    // The warm-up runs once the model is loaded, on a thread of its own: HIP serialises the BLAS start with the store's page-locked
    // arena (measured: beside the store's read it finished only when the read did, 21 s, and load still grew by its 3.5 s), so
    // it cannot hide inside the load; after it, a person typing gives it the seconds it needs.  A chunked pass that starts first
    // waits for it (warm_mu) - never later than that pass would have been without it - and a warm-up that finds the flow already
    // used does nothing.  DS4_WARM=0 turns it off.
    std::mutex warm_mu;
    std::atomic<bool> flow_used{false};
    std::thread warm_bg;
    void start_warm() {
        if (chunk <= 0 || (std::getenv("DS4_WARM") && std::atoi(std::getenv("DS4_WARM")) == 0)) return;
        warm_bg = std::thread([this] {
            std::lock_guard<std::mutex> lk(warm_mu);
            if (flow_used.load() || quit.load()) return;
            const double tw = now_ms();
            warm_flow();
            if (o.verbose) std::fprintf(stderr, "ds4: prompt path warmed up in %.0f ms\n", now_ms() - tw);
        });
    }
    // ---- the chunked prompt path
    size_t x_cap() const { return (size_t) std::max<int>(kWin, chunk + 2); }   // a window's / chunk's new source rows
    size_t chunk_hand_bytes() const {
        return (size_t) chunk * ((size_t) g.hc * g.dim * 4 + 8 * 4 + topk_stride() * 4 + cand_stride() * 4);
    }

    // the staging ring's size (MB) for the experts a chunk streams from the CPU lane: 400 where a good part of them are
    // streamed; 16 where the cards hold most of the experts (they are within 30% of fitting) (a 4-card box) - the ring's VRAM is then worth more
    // as expert slots, and the decode after a prompt keeps the windowed path's speed (R9700 x4: 29.6 -> 31.7 tok/s)
    // The share of the routed experts the GPUs can hold, from what is known at layout (their free memory less the reserve, the
    // prompt path's buffers and the dense weights; the trunk's experts only when no drafter is loaded): 1 = all of them.
    double gpu_expert_share(double* exp_out = nullptr, double* room_out = nullptr, double* other_out = nullptr) const {
        double exp_b = 0, other_b = 0, room = 0;
        for (const auto& kt : pk.t) {
            const std::string& n = kt.first;
            if (n.find(".engram.embed.") != std::string::npos || n.rfind("vision.", 0) == 0 || n == "embed.weight" ||
                (!o.dspark && n.rfind("mtp.", 0) == 0))
                continue;
            (n.find(".ffn.experts.") != std::string::npos ? exp_b : other_b) += (double) kt.second.bytes;
        }
        for (const Dev& d : devs)
            room += std::max(0.0, (double) d.free0 - (double) ((size_t) o.reserve_mib << 20) - 1.5 * (1 << 30)) * o.vram_experts;
        if (exp_out) *exp_out = exp_b;
        if (room_out) *room_out = room;
        if (other_out) *other_out = other_b;
        return exp_b > 0 ? std::min(1.0, std::max(0.0, room - other_b) / exp_b) : 1.0;
    }
    size_t ring_mb_auto() const {
        double exp_b = 0, other_b = 0, room = 0;
        const double share = gpu_expert_share(&exp_b, &room, &other_b);
        // One rule for the staging ring (ds4_experts_rule.hpp: staging_ring_mb): 16 MB where the cards hold the experts, a small
        // ring from each device's room where they hold most of them (4 x R9700), the larger streamed ring from the summed room on a
        // unified-memory GPU (Strix Halo: 400 -> 1200 MB) and where the cards hold under half.  DS4_RING_MB overrides.
        bool unified = false;
        for (const Dev& d : devs) {
            cudaDeviceProp ip{};
            if (cudaGetDeviceProperties(&ip, d.id) == cudaSuccess && ip.integrated != 0) unified = true;
        }
        const size_t mb = (size_t) strata::ds4::staging_ring_mb(exp_b > 0 ? share : 0.0, room, (int) devs.size(), unified, rdna4(), defaults_026());
        if (o.verbose)
            std::fprintf(stderr, "ds4: staging ring: experts %.1f GB, VRAM room %.1f GB, dense %.1f GB -> %d MB\n", exp_b / 1e9,
                         room / 1e9, other_b / 1e9, (int) mb);
        return mb;
    }
    bool slab_auto_grew_ = false, slab_force_base_ = false;   // the automatic attention slab: grew this try / must not grow (it did not fit)
#if defined(STRATA_USE_HIP)
    // STRATA_DS4_DIAG - the experts have filled the layer devices (~--reserve-mib free): the kernels' attributes again, then the
    // preflight launches once more on every layer device, concurrently from one thread per device (the prompt path's pattern), or one
    // device at a time with a device sync between (STRATA_DS4_DIAG_SERIAL_PREFLIGHT=1).  Never fatal: it only reports.
    //   probes passed at "start" and fail here -> the code object is loaded lazily and the memory is gone (H2);
    //   fail at "start" on ordinals 2/3 -> no code object for them (H1/H4); concurrent fails and serial passes -> a race (H3).
    void diag_after_experts() {
        std::vector<int> ids;
        for (const Dev& d : devs) ids.push_back(d.id);
        diag_probe_all("after-experts", ids);
        const bool serial = diag_env_on("STRATA_DS4_DIAG_SERIAL_PREFLIGHT");
        int prev = 0;
        (void) hipGetDevice(&prev);
        std::vector<std::string> res(devs.size());
        std::vector<char> ok(devs.size(), 0);
        const auto one = [&](size_t i) {
            (void) hipSetDevice(devs[i].id);
            ok[i] = preflight_kernels(devs[i], res[i]) ? 1 : 0;
        };
        std::fprintf(stderr, "DIAG late preflight (%s) starts, t=%.3f s\n", serial ? "serial, a device sync between" : "concurrent, one thread per device",
                     ds4_diag_s());
        if (serial) {
            for (size_t i = 0; i < devs.size(); ++i) {
                one(i);
                (void) hipSetDevice(devs[i].id);
                (void) hipDeviceSynchronize();
            }
        } else {
            std::atomic<size_t> ready{0};
            std::vector<std::thread> th;
            for (size_t i = 0; i < devs.size(); ++i)
                th.emplace_back([&, i] {
                    ready.fetch_add(1);
                    while (ready.load() < devs.size()) std::this_thread::yield();
                    one(i);
                });
            for (std::thread& t : th) t.join();
        }
        for (size_t i = 0; i < devs.size(); ++i)
            std::fprintf(stderr, "DIAG late preflight CUDA%d: %s%s%s\n", devs[i].id, ok[i] ? "ok" : "FAILED: ", ok[i] ? "" : res[i].c_str(),
                         "");
        (void) hipSetDevice(prev);
    }
#endif
    // one tiny launch of a kernel from each of the two TUs the prompt path starts with (exl3.cu rows_f16, ds4_iq.cu
    // dequant_rows), on every layer device, before the weights fill its memory.  A device the binary has no usable code
    // object for ("invalid kernel file") then stops the load with a message naming it, instead of failing launch by launch
    // in the prompt path.  The current device is d.id.
    bool preflight_kernels(const Dev& d, std::string& err) {
        cudaDeviceProp prop{};
        cudaGetDeviceProperties(&prop, d.id);
        float* x = nullptr;
        uint16_t* out = nullptr;
        uint8_t* raw = nullptr;
        bool ok = cudaMalloc((void**) &x, 256 * sizeof(float)) == cudaSuccess &&
                  cudaMalloc((void**) &out, 256 * sizeof(uint16_t)) == cudaSuccess && cudaMalloc((void**) &raw, 512) == cudaSuccess;
        std::string what, why = "launch error";
        if (ok) {
            cudaMemset(x, 0, 256 * sizeof(float));
            cudaMemset(raw, 0, 512);
            (void) cudaGetLastError();
            const int e0 = x3::launch_errors() + gg::launch_errors();
            x3::rows_f16(x, 256, nullptr, 1, 256, out, d.st);
            cudaError_t e = cudaStreamSynchronize(d.st);
            if (e != cudaSuccess || x3::launch_errors() + gg::launch_errors() != e0) {
                what = "exl3 rows_f16";
                if (e != cudaSuccess) why = diag_err(e);
#if defined(STRATA_USE_HIP)
                if (e != cudaSuccess) (void) ds4_diag_launch_error("preflight", "exl3 rows_f16 (stream sync)", (int) e);
#endif
            }
            if (what.empty()) {
                if (!gg::iq::dequant_rows(gg::iq::kQ5_K, raw, 176, 256, 1, out, false, d.st) ||
                    cudaStreamSynchronize(d.st) != cudaSuccess)
                    what = "i-quant dequant_rows", why = diag_err(cudaGetLastError());
            }
        }
        if (x) cudaFree(x);
        if (out) cudaFree(out);
        if (raw) cudaFree(raw);
        (void) cudaGetLastError();
        if (!ok) {
            err = "preflight on CUDA" + std::to_string(d.id) + ": scratch allocation failed";
            return false;
        }
        if (!what.empty()) {
            err = "CUDA" + std::to_string(d.id) + " (" + prop.gcnArchName + "): the " + what + " kernel does not launch on this device (" +
                  why + "; the line above, if any, names the call) - this binary has no usable code object for it";
            return false;
        }
        return true;
    }

    bool alloc_chunks(std::string& err) {
        slab_auto_grew_ = false;
        chunks.resize(devs.size());
        const int D = g.dim, H = g.hc, HD = g.hd;
        const int cols = (pk.eg_ngram - 1) * pk.eg_heads, ehd = pk.eg_hd;
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            cudaSetDevice(d.id);
            chunks[di] = std::make_unique<Chunk>();
            Chunk& c = *chunks[di];
            const int nm = (int) groups[(size_t) d.grp].mem.size();
            const int NHL = chunk_heads(nm), HQ = NHL * HD, OG = NHL / std::max(1, g.heads / std::max(1, g.o_groups));   // (a3: its own + shared groups)
            int FF = 0, ff0_ = 0;
            split128(g.ff, nm, 0, ff0_, FF);   // (the widest member's share: member 0 takes the odd blocks)
            if (tp_uneven && nm > 1)   // (tp4: the uneven split's widest member, any layer's rotation)
                for (int m = 0; m < nm; ++m) {
                    int f0 = 0, fn = 0;
                    tp_range(0, nm, m, f0, fn);
                    FF = std::max(FF, fn);
                }
            const size_t C = (size_t) chunk;
            c.C = chunk;
            // the base slab: STRATA_DS4_A_MB megabytes of q.  Every dense GEMM of a layer is issued once a slab, so the slab width divides
            // the prompt's dense weight traffic.  A unified-memory GPU (Strix Halo, main 3133160ed) takes 32 MB: measured 8 -> 32 MB took
            // its 32K prompt 325.89 -> 357.78 tok/s, 16K 315.01 -> 328.04, 8K +1.6%, 4K flat, decode unmoved.  A discrete card keeps 8 MB
            // (the 0.2.6 slab): its VRAM is the expert tier's, and on the RTX 5070 a bigger slab bought +2% prompt for -3% decode.
            // STRATA_DS4_A_MB overrides the base on any GPU (8 restores the old slab).
            bool unified = false;
            {
                cudaDeviceProp ip{};
                unified = cudaGetDeviceProperties(&ip, d.id) == cudaSuccess && ip.integrated != 0;
            }
            static const size_t a_mb_env = [] {
                const char* v = std::getenv("STRATA_DS4_A_MB");
                return (size_t) (v != nullptr ? std::max(1, std::atoi(v)) : 0);
            }();
            const size_t a_mb = strata::ds4::attn_slab_base_mb(unified, a_mb_env, defaults_026());
            c.A = std::max(64, (int) ((a_mb << 20) / (size_t) HQ) / 64 * 64);
            // DS4_ATTN_SLAB=N: the attention slab's rows.  The dense projections (q_b, wo_a/b) are dequantized and GEMM'd
            // once a slab, so a slab of 256 rows dequantizes the same weights 32 times for an 8K prompt (measured: the
            // dense dequant 916 ms of the 8K prompt, rocBLAS 867 ms); a larger slab costs VRAM for c.q/c.o and the oa
            // buffers (A * HQ x 4 bytes each).  0.2.7: unset = automatic (attn_slab_rows: up to 2048 rows where the buffers
            // take VRAM no expert would have used), 0 = the 0.2.6 rule above, N = that many rows.
            {
                int env = -1;
                if (const char* v = std::getenv("DS4_ATTN_SLAB")) env = std::max(0, std::atoi(v));
                bool tp_slab = false;   // (the rule below asked; a failed allocation falls back as the automatic slab does)
#if defined(STRATA_USE_HIP)
                // a tensor-parallel group on gfx1100 (RX 7900 XTX) asks for a 2048-row slab: q_b + rope 2.0 -> 1.07 s a card
                // on the test machine's tp3 16K prompt (23.4 against 24.1 s with HIPK), for 87 fewer VRAM experts a card
                // (docs/dsv41/FEATURES.md section 2.9).  DS4_ATTN_SLAB=N still wins (0: the base rule).
                if (env < 0 && nm >= 2 && !unified && !slab_force_base_ && a_mb_env == 0) {
                    cudaDeviceProp sp{};
                    if (cudaGetDeviceProperties(&sp, d.id) == cudaSuccess && std::strncmp(sp.gcnArchName, "gfx1100", 7) == 0) env = 2048, tp_slab = true;
                }
#endif
                if ((slab_force_base_ || unified || a_mb_env != 0) && env < 0) env = 0;   // (no automatic growth on a unified-memory GPU, or when STRATA_DS4_A_MB chose the base)
                // per row: c.q + c.o (float), c.o16 (half), c.oa (float), c.oa16 (half)
                const double bpr = (double) HQ * 10.0 + (double) OG * (double) g.o_lora * 6.0;
                double spare = 1e18;   // the expert tier off (--vram-experts 0): the buffers cost no expert
                double share = 0.0;    // the share of the routed experts the cards hold (0 with the tier off)
                if (o.vram_experts > 0.0) {
                    double exp_b = 0, room = 0, other_b = 0;
                    share = gpu_expert_share(&exp_b, &room, &other_b);
                    spare = (room - other_b - exp_b) / (double) std::max<size_t>(1, devs.size());
                }
                const int base = c.A;
                // one rule (ds4_experts_rule.hpp: attn_slab_rows): the chunk's whole slab (<= 1024 rows) where the cards hold half the
                // experts or more (4 x R9700, +9% prompt), up to 2048 rows where the VRAM is spare, the base otherwise
                c.A = strata::ds4::attn_slab_rows(env, chunk, base, spare, bpr, rdna4() ? share : 0.0, defaults_026());
                if (tp_slab && c.A > base) {
                    slab_auto_grew_ = true;
                    if (di == 0 && o.verbose)
                        std::fprintf(stderr, "ds4: attention slab %d rows (tensor parallel on gfx1100; DS4_ATTN_SLAB=0 keeps %d)\n", c.A, base);
                }
                if (env < 0 && c.A > base) {
                    slab_auto_grew_ = true;
                    if (di == 0 && o.verbose) {
                        if (rdna4() && share >= 0.5)
                            std::fprintf(stderr, "ds4: attention slab %d rows (automatic: the cards hold %.0f%% of the experts; DS4_ATTN_SLAB=0 keeps %d)\n",
                                         c.A, share * 100.0, base);
                        else
                            std::fprintf(stderr, "ds4: attention slab %d rows (automatic: %.1f GB of VRAM to spare beyond the experts; DS4_ATTN_SLAB=0 keeps %d)\n",
                                         c.A, spare / 1e9, base);
                    }
                }
            }
            // (the indexer's slab: its scores rows are the context wide - about 64 MB of them)
            c.AI = std::max(32, std::min(128, (int) (((size_t) 64 << 20) / (((size_t) o.max_context + 64) * 4)) / 32 * 32));
            c.w16_elems = (size_t) 8 << 20;
            bool has_eg = false, has_first = false;
            size_t stride = 0;
            for (const Layer& l : L)
                for (int m = 0; m < l.nm; ++m)
                    if (member(l, m).dev == (int) di && !l.mtp) {
                        has_eg = has_eg || l.eg >= 0;
                        has_first = has_first || l.il == 0;
                        stride = std::max(stride, align256(unit(member(l, m))));
                    }
            const size_t A = (size_t) c.A, AI = (size_t) c.AI, ss = (size_t) o.max_context + 64;
            bool ok = dalloc(d, c.h, C * H * D, err) && dalloc(d, c.x, C * D, err) && dalloc(d, c.acc, C * D, err) &&
                      dalloc(d, c.x16, C * D, err) && dalloc(d, c.qr, C * g.q_lora, err) &&
                      dalloc(d, c.qr16, C * g.q_lora, err) && dalloc(d, c.kvr, C * HD, err) &&
                      dalloc(d, c.ckr, C * HD, err) && dalloc(d, c.cgr, C * HD, err) &&
                      dalloc(d, c.latent, (C + 2) * HD, err) && dalloc(d, c.lat16, (C + 2) * HD, err) &&
                      dalloc(d, c.ikr, (C + 2) * g.ix_hd, err) && dalloc(d, c.ext, ((size_t) g.win + C) * HD, err) &&
                      dalloc(d, c.q, A * HQ, err) && dalloc(d, c.o, A * HQ, err) && dalloc(d, c.o16, A * HQ, err) &&
                      dalloc(d, c.oa, A * OG * g.o_lora, err) && dalloc(d, c.oa16, A * OG * g.o_lora, err) &&
                      dalloc(d, c.iq, AI * g.ix_heads * g.ix_hd, err) && dalloc(d, c.iw, C * 64, err) &&
                      dalloc(d, c.scores, AI * ss, err) && dalloc(d, c.bm, AI * bm_stride(), err) &&
                      dalloc(d, c.topk, C * topk_stride(), err) && dalloc(d, c.cand, C * cand_stride(), err) &&
                      dalloc(d, c.mix, C * 32, err) && dalloc(d, c.a_pre, C * 8, err) && dalloc(d, c.a_post, C * 8, err) &&
                      dalloc(d, c.a_comb, C * 64, err) && dalloc(d, c.f_pre, C * 8, err) &&
                      dalloc(d, c.f_post, C * 8, err) && dalloc(d, c.f_comb, C * 64, err) && dalloc(d, c.pre, C * 8, err) &&
                      dalloc(d, c.glog, C * 1024, err) && dalloc(d, c.ridx, C * kPicks, err) &&
                      dalloc(d, c.rw, C * kPicks, err) && dalloc(d, c.bounds, 2048, err) &&
                      dalloc(d, c.row_tok, C * kPicks, err) && dalloc(d, c.pos, C * kPicks, err) &&
                      dalloc(d, c.sg, C * FF, err) && dalloc(d, c.su, C * FF, err) && dalloc(d, c.sh16, C * FF, err) &&
                      dalloc(d, c.h16, (C + kH16Pad) * FF, err) && dalloc(d, c.y, C * D, err) && dalloc(d, c.w16, c.w16_elems, err) &&
                      halloc(c.bounds_pin, 2048, err);
            if (!ok) return false;
            if (has_first && !dalloc(d, c.emb, C * D, err)) return false;
            if (has_eg) {
                const size_t ES = 256, per = (size_t) cols * (ehd + ehd / 32);
                if (!dalloc(d, c.eg_x, ES * cols * ehd, err) || !dalloc(d, c.eg_x16, ES * cols * ehd, err) ||
                    !dalloc(d, c.eg_kv, ES * (H + 1) * D, err) || !dalloc(d, c.eg_rows, C * per, err))
                    return false;
            }
            if (stride > 0) {   // DS4_RING_MB (400) of slots in kParts batches
                const size_t mb = std::getenv("DS4_RING_MB") ? (size_t) std::atoi(std::getenv("DS4_RING_MB")) : ring_mb_auto();
                c.ring_stride = stride;
                c.ring_n = std::max(Chunk::kParts, (int) ((mb << 20) / stride) / Chunk::kParts * Chunk::kParts);
                if (!dalloc(d, c.ring, (size_t) c.ring_n * stride, err)) return false;
            }
            CK(cudaStreamCreateWithFlags(&c.cs, cudaStreamNonBlocking));
            for (int i = 0; i < Chunk::kParts; ++i) {
                CK(cudaEventCreateWithFlags(&c.filled[i], cudaEventDisableTiming));
                CK(cudaEventCreateWithFlags(&c.freed[i], cudaEventDisableTiming));
            }
            if (cublasCreate(&c.blas) != CUBLAS_STATUS_SUCCESS || cublasSetStream(c.blas, d.st) != CUBLAS_STATUS_SUCCESS) {
                err = "cuBLAS on CUDA" + std::to_string(d.id);
                return false;
            }
            for (int sl = 0; sl < 2; ++sl) {
                if (d.mi == 0 && (!hmap(c.hand[sl], chunk_hand_bytes(), err) || !hmap(c.hand_flag[sl], 32, err))) return false;
                if (has_first && !halloc(c.emb_host[sl], C * D, err)) return false;
                if (has_eg && !halloc(c.eg_host[sl], C * pk.eg_layers * (size_t) cols * (ehd + ehd / 32), err)) return false;
                CK(cudaEventCreateWithFlags(&c.emb_ev[sl], cudaEventDisableTiming));
                CK(cudaEventCreateWithFlags(&c.eg_ev[sl], cudaEventDisableTiming));
            }
            if (d.mi == 0 && !hmap(c.hand_ack, (size_t) 2 * 8 * 32, err)) return false;
        }
        return true;
    }

    // y[r][c] = x16[r] . W[:, c] (+ beta y) for r < rows: W reconstructed to FP16 in whole 128-column blocks, then the product.
    // The product prefers the engine's own RDNA3 WMMA kernel (src/prefill/wmma_gemm.cu) over hipBLAS: on gfx1151 hipBLAS
    // measures 4.97 TFLOPS at this call convention while that kernel measures 20-40 (BM 128 x BN 256, grouped tile order), and
    // the chunked prompt's dense GEMM is 11.1 s of a 4K prompt at the library's rate.  Same operands and the same values (the
    // k order differs, so it is rounding-level: the quality gate and the acceptance gate cover it); STRATA_DENSE_PFGEMM=0 keeps
    // hipBLAS for an A/B.
    bool gemm(Dev& d, Chunk& c, const x3::Mat& m, const uint16_t* x16, int ldx, int rows, float* y, int ldy, float beta,
              std::string& err) {
        if (rows <= 0) return true;
#if defined(STRATA_USE_HIP)   // (wmma_gemm.cu is part of the AMD builds only: a CUDA build has no such kernel and keeps cuBLAS)
        static const bool pf = strata::ds4::dense_pfgemm_default(env_tri("STRATA_DENSE_PFGEMM"), defaults_026());
#endif
        const int cols = std::max(128, (int) std::min<size_t>((size_t) m.n, c.w16_elems / (size_t) m.k) / 128 * 128);
        for (int c0 = 0; c0 < m.n; c0 += cols) {
            const int nc = std::min(cols, m.n - c0);
            if (m.fmt != 0) gg::rows(nc == m.n ? m : gg::view(m, c0, nc), c.w16, false, d.st);   // (a GGUF's)
            else x3::reconstruct_rows(nc == m.n ? m : x3::view(m, c0, nc), c.w16, false, d.st);
#if defined(STRATA_USE_HIP)
            if (pf && rows >= 64 && ((uintptr_t) x16 & 15u) == 0 &&
                strata_pf_gemm_f16_ld(x16, ldx, c.w16, m.k, y + c0, rows, nc, m.k, ldy, beta, d.st))
                continue;
#endif
            const float one = 1.0f;
            const cublasStatus_t st = cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, nc, rows, m.k, &one, c.w16, CUDA_R_16F,
                                                   m.k, x16, CUDA_R_16F, ldx, &beta, y + c0, CUDA_R_32F, ldy,
                                                   CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP);
            if (st != CUBLAS_STATUS_SUCCESS) {
                err = "cublasGemmEx: status " + std::to_string((int) st);
                return false;
            }
        }
        return true;
    }
    // ---- the busy experts (run_set): an expert of many rows as FP16 GEMMs.  The tiles decode its weights again for
    // every 64 of its rows (a prompt's chunk gives a popular expert hundreds); decoded once, to the FP16 values the tiles
    // multiply (iq::f16_rows), the library's GEMM takes them at its own speed.  DS4_FAT_ROWS=N (default 0, off; N:
    // the experts of N rows or more) takes the experts of N rows or more; the same products, only the sums' order differ
    // (3x V100, Maya-XS: 64 rows +6-8% on 8K / 32K prompts; KL vs the reference 0.276, the stock path 0.285 - the same;
    //  RTX 5090, IST-DAS 2.25 bpw: a 13K-token prompt 1,400 -> 1,625 tok/s at 64 rows, decode unchanged)
    static int fat_rows() {
        static const int n = [] {
            const int v = std::getenv("DS4_FAT_ROWS") ? std::max(0, std::atoi(std::getenv("DS4_FAT_ROWS"))) : 0;
            return v > 0 ? std::max(v, 17) : 0;   // (the light kernels take the experts of 16 rows or fewer)
        }();
        return n;
    }
    bool fat_ready(Dev& d, Chunk& c, int D, int FF) {
#if defined(STRATA_USE_HIP) || defined(STRATA_METAL)   // (CUDA only: the Mac has no dispatch for these kernels, HIP is unmeasured)
        (void) d, (void) c, (void) D, (void) FF;
        return false;
#else
        if (fat_rows() <= 0 || c.fat_off) return false;
        if (tp_uneven) return false;   // (tp4: its buffers take the first layer's FF - an uneven split's members vary)
        if (c.fat_w != nullptr) return true;
        static const int R = std::getenv("DS4_FAT_PIECE") ? std::max(64, std::atoi(std::getenv("DS4_FAT_PIECE"))) : 1024;
        if (cudaSetDevice(d.id) != cudaSuccess || cudaMalloc(&c.fat_w, (size_t) 2 * FF * D * 2) != cudaSuccess ||
            cudaMalloc(&c.fat_x, (size_t) R * D * 2) != cudaSuccess ||
            cudaMalloc(&c.fat_gu, (size_t) R * 2 * FF * 4) != cudaSuccess) {
            cudaGetLastError();
            std::fprintf(stderr, "ds4: CUDA%d: no VRAM for the busy experts' path (%.0f MB): the tiles take them\n", d.id,
                         ((double) 2 * FF * D * 2 + (double) R * D * 2 + (double) R * 2 * FF * 4) / 1e6);
            c.fat_off = true;
            return false;
        }
        c.fat_r = R;
        std::fprintf(stderr, "ds4: CUDA%d busy experts (%d rows or more) as FP16 GEMMs, %d rows a piece (%.0f MB)\n", d.id,
                     fat_rows(), R, ((double) 2 * FF * D * 2 + (double) R * D * 2 + (double) R * 2 * FF * 4) / 1e6);
        return true;
#endif
    }
    // h16[lr0 + r] = FP16 clamped SwiGLU of the expert's gate and up over x16[row_tok[row + r]], r < n
    bool fat_gate_up(Chunk& c, const x3::SetArgs& sa, const uint8_t* blob, int row, int n, int a, int D, int FF,
                     cudaStream_t s, std::string& err) {
        const int tg = gg::expert_type(sa.lay, 0);
        if (!gg::iq::f16_rows(tg, blob + sa.lay.trellis[0], D, FF, c.fat_w, D, s) ||
            !gg::iq::f16_rows(tg, blob + sa.lay.trellis[1], D, FF, c.fat_w + (size_t) FF * D, D, s)) {
            err = "the busy experts' path: gate / up not decoded";
            return false;
        }
        const float one = 1.0f, zero = 0.0f;
        for (int p0 = 0; p0 < n; p0 += c.fat_r) {
            const int np = std::min(c.fat_r, n - p0);
            gg::iq::gather_f16(c.x16, D, c.row_tok + row + p0, np, D, c.fat_x, s);
            if (cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, 2 * FF, np, D, &one, c.fat_w, CUDA_R_16F, D, c.fat_x,
                             CUDA_R_16F, D, &zero, c.fat_gu, CUDA_R_32F, 2 * FF, CUBLAS_COMPUTE_32F,
                             CUBLAS_GEMM_DEFAULT_TENSOR_OP) != CUBLAS_STATUS_SUCCESS) {
                err = "the busy experts' path: cublasGemmEx (gate / up) failed";
                return false;
            }
            gg::iq::swiglu_f16(c.fat_gu, 2 * FF, np, FF, sa.limit, c.h16 + (size_t) (row - a + p0) * FF, FF, s);
        }
        return true;
    }
    // y[lr0 + r] = down(h16[lr0 + r]), r < n
    bool fat_down(Chunk& c, const x3::SetArgs& sa, const uint8_t* blob, int lr0, int n, int D, int FF, cudaStream_t s,
                  std::string& err) {
        if (!gg::iq::f16_rows(gg::expert_type(sa.lay, 2), blob + sa.lay.trellis[2], FF, D, c.fat_w, FF, s)) {
            err = "the busy experts' path: down not decoded";
            return false;
        }
        const float one = 1.0f, zero = 0.0f;
        if (cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, D, n, FF, &one, c.fat_w, CUDA_R_16F, FF,
                         c.h16 + (size_t) lr0 * FF, CUDA_R_16F, FF, &zero, c.y + (size_t) lr0 * D, CUDA_R_32F, D,
                         CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT_TENSOR_OP) != CUBLAS_STATUS_SUCCESS) {
            err = "the busy experts' path: cublasGemmEx (down) failed";
            return false;
        }
        return true;
    }
    // y[r][c] = alpha x16[r] . W[c] for F16 weights W [n][k] (the indexer's weights_proj)
    bool gemm_f16w(Chunk& c, const uint16_t* W, int n, int k, const uint16_t* x16, int ldx, int rows, float alpha,
                   float* y, int ldy, std::string& err) {
        const float zero = 0.0f;
        const cublasStatus_t st = cublasGemmEx(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, n, rows, k, &alpha, W, CUDA_R_16F, k,
                                               x16, CUDA_R_16F, ldx, &zero, y, CUDA_R_32F, ldy, CUBLAS_COMPUTE_32F,
                                               CUBLAS_GEMM_DEFAULT_TENSOR_OP);
        if (st != CUBLAS_STATUS_SUCCESS) {
            err = "cublasGemmEx (F16 weights): status " + std::to_string((int) st);
            return false;
        }
        return true;
    }
#if defined(DS4_MIX_ROCBLAS)
    // (FG-04): the mHC mix GEMM's rocBLAS solution table - the f32 rows of STRATA_ROCBLAS_TUNING (a table
    // file, or a directory holding <arch>-rocblas-<version>.txt: the variable Gemm::f16_inplace reads for its f16o rows),
    // made by tools/hip/tune_rocblas --dsv41-mix.  On gfx1100 rocBLAS's own pick for this shape (N = 24, K = 20480, T
    // rows) is MT128x128 without split-K: T / 128 workgroups, 1.9 ms a call at T = 2048 where the h read is ~0.2 ms
    // (rocprofv3, pf/runs/trace-Itr-20261108T125655Z: 80 calls, 152 ms of a 2K prompt on CUDA0).  A solution index
    // changes the order of the K sums only (rounding).  DS4_MIX_TUNED=0 ignores the table here; no table, another card or
    // another rocBLAS build: cublasSgemm, as before.
    static const strata::prefill::rocblas_tuning::Table* mix_table(const std::string& arch) {
        static std::mutex mu;
        static bool tried = false, ok = false;
        static strata::prefill::rocblas_tuning::Table table;
        std::lock_guard<std::mutex> lk(mu);
        if (!tried) {
            tried = true;
            const char* path = std::getenv("STRATA_ROCBLAS_TUNING");
            const char* off = std::getenv("DS4_MIX_TUNED");
            char version[128] = {0};
            if (!path || !*path || (off && off[0] == '0')) {
            } else if (rocblas_get_version_string(version, sizeof version) != rocblas_status_success) {
                std::fprintf(stderr, "ds4: mHC mix rocBLAS table: rocBLAS version query failed; cublasSgemm runs\n");
            } else {
                std::filesystem::path file(path);
                std::error_code ec;
                if (std::filesystem::is_directory(file, ec)) {
                    std::string tag(version);
                    while (!tag.empty() && tag.back() == '.') tag.pop_back();
                    file /= arch + "-rocblas-" + tag + ".txt";
                }
                std::string e;
                if (table.load(file.string(), arch, version, e)) ok = true;
                else std::fprintf(stderr, "ds4: mHC mix rocBLAS table: %s (%s); cublasSgemm runs\n", e.c_str(), file.string().c_str());
            }
        }
        return ok && table.arch() == arch ? &table : nullptr;
    }
    // the chunk's rocBLAS handle for the mix, on the device's stream; null (once and for all): no tuned f32 row for the
    // mix's shape on this card
    rocblas_handle mix_handle(Dev& d, Chunk& c) {
        if (c.mix_rb_tried) return c.mix_rb;
        c.mix_rb_tried = true;
        hipDeviceProp_t p{};
        if (hipGetDeviceProperties(&p, d.id) != hipSuccess) return nullptr;
        std::string arch(p.gcnArchName);
        if (const auto colon = arch.find(':'); colon != std::string::npos) arch.resize(colon);
        const auto* t = mix_table(arch);
        if (!t) return nullptr;
        const int hcd = g.hc * g.dim, n_mix = (2 + g.hc) * g.hc;
        size_t rows = 0, tuned = 0;
        for (const auto& r : t->rows())
            if (r.f32 && r.n == n_mix && r.k == hcd && r.ldy == 32) { ++rows; tuned += r.tuned ? 1 : 0; }
        if (tuned == 0) return nullptr;
        if (rocblas_create_handle(&c.mix_rb) != rocblas_status_success) {
            c.mix_rb = nullptr;
            std::fprintf(stderr, "ds4: mHC mix rocBLAS handle on CUDA%d failed; cublasSgemm runs\n", d.id);
            return nullptr;
        }
        rocblas_set_stream(c.mix_rb, d.st);
        c.mix_tab = t;
        static std::atomic<bool> said{false};
        if (!said.exchange(true))
            std::fprintf(stderr, "ds4: mHC mix through rocBLAS solutions (STRATA_ROCBLAS_TUNING: %zu f32 rows for %d x %d, %zu with "
                                 "a solution; %s, rocBLAS %s; DS4_MIX_TUNED=0 off)\n", rows, n_mix, hcd, tuned, arch.c_str(),
                         t->version().c_str());
        return c.mix_rb;
    }
    // mixes = fn^T . h through the table's solution for T rows; false (nothing written): no tuned row for T, or the
    // launch was refused - cublasSgemm runs (and for that T from now on after three refusals)
    bool mix_rocblas(Dev& d, Chunk& c, const float* h, const float* fn, int T, float* mixes) {
        rocblas_handle rb = mix_handle(d, c);
        if (!rb) return false;
        const int hcd = g.hc * g.dim, n_mix = (2 + g.hc) * g.hc;
        auto it = c.mix_picks.find(T);
        if (it == c.mix_picks.end()) {
            Chunk::MixPick pick;
            if (const auto* row = c.mix_tab->closest(n_mix, hcd, 32, T, true); row && row->tuned) {
                pick.tuned = true;
                pick.solution = row->solution;
            }
            if (std::getenv("STRATA_ROCBLAS_VERBOSE"))
                std::fprintf(stderr, "ds4: mHC mix CUDA%d T=%d: %s %d\n", d.id, T, pick.tuned ? "rocBLAS solution" : "cublasSgemm",
                             pick.solution);
            it = c.mix_picks.emplace(T, pick).first;
        }
        if (!it->second.tuned) return false;
        const float one = 1.0f, zero = 0.0f;
        auto run = [&](rocblas_gemm_algo algo, int sol) {
            return rocblas_gemm_ex(rb, rocblas_operation_transpose, rocblas_operation_none, n_mix, T, hcd, &one, fn,
                                   rocblas_datatype_f32_r, hcd, h, rocblas_datatype_f32_r, hcd, &zero, mixes,
                                   rocblas_datatype_f32_r, 32, mixes, rocblas_datatype_f32_r, 32, rocblas_datatype_f32_r, algo,
                                   sol, 0);
        };
        if (!c.mix_rb_open) {   // (no warm-up, DS4_WARM=0: the handle's first product is the default kernel's)
            if (run(rocblas_gemm_algo_standard, 0) != rocblas_status_success) return false;
            c.mix_rb_open = true;
            return true;
        }
        const rocblas_status st = run(rocblas_gemm_algo_solution_index, it->second.solution);
        if (st == rocblas_status_success) {
            ++c.mix_tuned;
            return true;
        }
        ++c.mix_fallbacks;
        if (++it->second.refusals >= 3) {
            std::fprintf(stderr, "ds4: mHC mix rocBLAS solution %d refused (status %d) for T=%d three times on CUDA%d; "
                                 "cublasSgemm for it\n", it->second.solution, (int) st, T, d.id);
            it->second.tuned = false;
        }
        return false;
    }
#endif
    // hc_mix over a chunk: the dots by an F32 GEMM, then the rms scale
    bool hc_mix_chunk(Dev& d, Chunk& c, const float* h, const float* fn, int T, float* mixes, std::string& err) {
        const int hcd = g.hc * g.dim, n_mix = (2 + g.hc) * g.hc;
#if defined(STRATA_METAL)
        if (!std::getenv("DS4_CHUNK_SGEMM")) {   // the window path's fused kernel: no F32 GEMM, no second pass
            hc_mix(h, fn, hcd, n_mix, T, g.eps, mixes, d.st);
            return true;
        }
#endif
#if defined(DS4_MIX_ROCBLAS)
        if (mix_rocblas(d, c, h, fn, T, mixes)) {   // a tuned rocBLAS solution (STRATA_ROCBLAS_TUNING f32 rows)
            hc_mix_scale(h, hcd, n_mix, T, g.eps, mixes, d.st);
            return true;
        }
#endif
        const float one = 1.0f, zero = 0.0f;
        if (cublasSgemm(c.blas, CUBLAS_OP_T, CUBLAS_OP_N, n_mix, T, hcd, &one, fn, hcd, h, hcd, &zero, mixes, 32) !=
            CUBLAS_STATUS_SUCCESS) {
            err = "cublasSgemm (mHC mixes)";
            return false;
        }
        hc_mix_scale(h, hcd, n_mix, T, g.eps, mixes, d.st);
        return true;
    }

    // expert e of l (on the CPU lane: its NH column parts) -> member m's VRAM copy at dst, in the GPU layout (the full
    // blob, or a group member's part), by DMA from the pinned parts on the copy stream (in place: from `src`, its file
    // region read into pinned staging)
    // (src_half: src is already member m's part in l.hlay's layout, read_mx_member's)
    bool stream_expert(const Layer& l, int m, int e, uint8_t* dst, cudaStream_t cs, std::string& err,
                       const uint8_t* src = nullptr, bool src_half = false) {
        if (l.lay.fmt == gg::kFmtMXFP4) {   // the blob, or member m's rows / blocks: from `src` (the expert read into
            // pinned staging as its blob) or from the file's mapping
            // A copied expert (copy_mode) holds whole matrix rows of each NUMA part on its node; mx_mat() is part 0
            // only then, and a whole matrix read from it corrupted its second half (NH > 1).  copy_rows reads rows
            // [first, first + rows) of matrix r, columns [col, col + width) bytes, from whichever part holds each row.
            // (Project Maya 0444b76, #533, by tctiger.  NH == 1: one part, the same single copies as before)
            const bool copied = src == nullptr && copy_mode && !l.ram.empty() && l.ram[(size_t) e] >= 0 &&
                                !(store && store->find(l.il, e) >= 0);   // (mx_mat's order: the store first)
            auto copy_rows = [&](int r, uint8_t* out, size_t out_pitch, int first, int rows, size_t col, size_t width) {
                const size_t pitch = mx_row_b(l, r);
                const int parts = copied ? NH : 1, per = mx_n(r) / parts;
                for (int X = 0; X < parts; ++X) {
                    const int lo = std::max(first, X * per), hi = std::min(first + rows, (X + 1) * per);
                    if (lo >= hi) continue;
                    const uint8_t* base = copied ? mx_part_ptr(l, e, r, X)
                                                 : src != nullptr ? src + l.lay.trellis[r] : mx_mat(l, e, r);
                    const uint8_t* from = base + (size_t) (lo - X * per) * pitch + col;
                    uint8_t* to = out + (size_t) (lo - first) * out_pitch;
                    const cudaError_t status =
                        width == pitch && width == out_pitch
                            ? cudaMemcpyAsync(to, from, (size_t) (hi - lo) * width, cudaMemcpyHostToDevice, cs)
                            : cudaMemcpy2DAsync(to, out_pitch, from, pitch, width, (size_t) (hi - lo), cudaMemcpyHostToDevice, cs);
                    if (status != cudaSuccess) return false;
                }
                return true;
            };
            bool ok = true;
            if (l.nm == 1) {
                if (src != nullptr)
                    ok = cudaMemcpyAsync(dst, src, l.blob, cudaMemcpyHostToDevice, cs) == cudaSuccess;
                else
                    for (int r = 0; r < 3; ++r)
                        ok = ok && copy_rows(r, dst + l.lay.trellis[r], mx_row_b(l, r), 0, mx_n(r), 0, mx_row_b(l, r));
            } else {
                // (tp4: member m's own range and layout - Project Maya e3f2475)
                const MxCut k = mx_cut(l, m);
                const x3::ExpertLayout& hl = member(l, m).hlay;
                if (src_half && src != nullptr) {   // (three contiguous copies, no per-row DMA)
                    for (int r = 0; r < 3; ++r)
                        ok = ok && cudaMemcpyAsync(dst + hl.trellis[r], src + hl.trellis[r],
                                                   r < 2 ? (size_t) k.ffn * k.gr[r] : (size_t) g.dim * k.dh,
                                                   cudaMemcpyHostToDevice, cs) == cudaSuccess;
                    if (!ok) err = "streaming layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
                    return ok;
                }
                // gate / up: member m's rows [ff0, ff0 + ffn); down: its columns [d0, d0 + dh) across every NUMA row part
                // (build 10: tp4's uneven cut through EB-07 4/4's copy_rows)
                for (int r = 0; r < 2; ++r) ok = ok && copy_rows(r, dst + hl.trellis[r], k.gr[r], k.ff0, k.ffn, 0, k.gr[r]);
                ok = ok && copy_rows(2, dst + hl.trellis[2], k.dh, 0, g.dim, k.d0, k.dh);
            }
            if (!ok) err = "streaming layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
            return ok;
        }
        const auto& parts = l.hh[(size_t) e];
        const int D = g.dim, FF = g.ff;
        auto cp2 = [&](uint8_t* d0, size_t dp, const uint8_t* s0, size_t sp, size_t w, size_t h) {
            return cudaMemcpy2DAsync(d0, dp, s0, sp, w, h, cudaMemcpyHostToDevice, cs) == cudaSuccess;
        };
        auto cp = [&](uint8_t* d0, const uint8_t* s0, size_t n) {
            return cudaMemcpyAsync(d0, s0, n, cudaMemcpyHostToDevice, cs) == cudaSuccess;
        };
        bool ok = true;
        if (NH == 1) {   // one part: the whole expert in exllamav3's layout, its pieces at hl's offsets
            const uint8_t* p = src != nullptr ? src : parts[0];
            if (l.nm == 1) {
                for (int r = 0; r < 3; ++r)
                    ok = ok && cp(dst + l.lay.trellis[r], p + l.hl.trellis[r], l.piece_bytes[r][0]) &&
                         cp(dst + l.lay.suh[r], p + l.hl.suh[r], (size_t) l.hl.k[r] * 2) &&
                         cp(dst + l.lay.svh[r], p + l.hl.svh[r], (size_t) l.hl.n[r] * 2);
            } else {   // member m's part (its FFN columns [f0, f0 + fn)), cut as blob_to_half cuts a blob
                const Layer& x = member(l, m);
                const int f0 = x.ff0, fn = x.ffn;
                for (int r = 0; r < 2; ++r) {
                    const size_t tile = (size_t) 32 * l.lay.K[r], nt = (size_t) FF / 16, nth = (size_t) fn / 16;
                    ok = ok && cp2(dst + x.hlay.trellis[r], nth * tile, p + l.hl.trellis[r] + (size_t) (f0 / 16) * tile,
                                   nt * tile, nth * tile, (size_t) D / 16) &&
                         cp(dst + x.hlay.suh[r], p + l.hl.suh[r], (size_t) D * 2) &&
                         cp(dst + x.hlay.svh[r], p + l.hl.svh[r] + (size_t) f0 * 2, (size_t) fn * 2);
                }
                const size_t row = (size_t) (D / 16) * 32 * l.lay.K[2];
                ok = ok && cp(dst + x.hlay.trellis[2], p + l.hl.trellis[2] + (size_t) (f0 / 16) * row,
                              (size_t) (fn / 16) * row) &&
                     cp(dst + x.hlay.suh[2], p + l.hl.suh[2] + (size_t) f0 * 2, (size_t) fn * 2) &&
                     cp(dst + x.hlay.svh[2], p + l.hl.svh[2], (size_t) D * 2);
            }
        } else if (l.nm == 1) {   // the full blob: each matrix's columns from the two parts side by side
            for (int r = 0; r < 3; ++r) {
                const size_t tile = (size_t) 32 * l.lay.K[r];
                const int k = l.hl.k[r], nh = l.hl.n[r];   // part: k x nh
                for (int X = 0; X < 2; ++X) {
                    ok = ok && cp2(dst + l.lay.trellis[r] + (size_t) X * (nh / 16) * tile, (size_t) (2 * nh / 16) * tile,
                                   parts[(size_t) X] + l.hl.trellis[r], (size_t) (nh / 16) * tile, (size_t) (nh / 16) * tile,
                                   (size_t) (k / 16));
                    ok = ok && cp(dst + l.lay.svh[r] + (size_t) X * nh * 2, parts[(size_t) X] + l.hl.svh[r], (size_t) nh * 2);
                }
                ok = ok && cp(dst + l.lay.suh[r], parts[0] + l.hl.suh[r], (size_t) k * 2);
            }
        } else {   // member m (FFN columns [f0, f0 + fn)): gate / up from the parts holding them; down rows [f0, ..) of
                   // both parts' columns
            const Layer& x = member(l, m);
            const int f0 = x.ff0, fn = x.ffn;
            for (int r = 0; r < 2; ++r) {
                const size_t tile = (size_t) 32 * l.lay.K[r];
                const int hn = l.hl.n[r];   // part X: columns [X hn, (X + 1) hn)
                for (int X = 0; X < 2; ++X) {
                    const int a = std::max(f0, X * hn), b = std::min(f0 + fn, (X + 1) * hn);
                    if (a >= b) continue;
                    ok = ok && cp2(dst + x.hlay.trellis[r] + (size_t) ((a - f0) / 16) * tile, (size_t) (fn / 16) * tile,
                                   parts[(size_t) X] + l.hl.trellis[r] + (size_t) ((a - X * hn) / 16) * tile,
                                   (size_t) (hn / 16) * tile, (size_t) ((b - a) / 16) * tile, (size_t) (D / 16)) &&
                         cp(dst + x.hlay.svh[r] + (size_t) (a - f0) * 2, parts[(size_t) X] + l.hl.svh[r] + (size_t) (a - X * hn) * 2,
                            (size_t) (b - a) * 2);
                }
                ok = ok && cp(dst + x.hlay.suh[r], parts[0] + l.hl.suh[r], (size_t) D * 2);
            }
            const size_t tile = (size_t) 32 * l.lay.K[2];
            const int nh = D / 2;
            for (int X = 0; X < 2; ++X) {
                ok = ok && cp2(dst + x.hlay.trellis[2] + (size_t) X * (nh / 16) * tile, (size_t) (D / 16) * tile,
                               parts[(size_t) X] + l.hl.trellis[2] + (size_t) (f0 / 16) * (nh / 16) * tile,
                               (size_t) (nh / 16) * tile, (size_t) (nh / 16) * tile, (size_t) (fn / 16));
                ok = ok && cp(dst + x.hlay.svh[2] + (size_t) X * nh * 2, parts[(size_t) X] + l.hl.svh[2], (size_t) nh * 2);
            }
            ok = ok && cp(dst + x.hlay.suh[2], parts[0] + l.hl.suh[2] + (size_t) f0 * 2, (size_t) fn * 2);
        }
        if (!ok) err = "streaming layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
        return ok;
    }

    // a device's streamed experts: batches of ring_n / kParts of each of its layers' CPU-lane experts, chunk by chunk
    // in layer order; the copies run at most kParts batches ahead of the compute
    struct Batch {
        int k = 0, il = 0, j0 = 0, n = 0;   // chunk, layer, its host_list range
    };
    struct Streamer {
        std::vector<Batch> b;
        size_t cp = 0, kp = 0;        // the next batch to copy, to compute
        std::atomic<size_t> done{0};  // cp, for read_ahead's thread
    };
    // in place (file_experts): the batches' file regions read ahead of their copies - POSIX_FADV_WILLNEED, the kernel
    // reading them in the background in large requests, where the copies alone fault the pages in a few at a time -
    // at most DS4_READAHEAD_MB (2048) beyond the batch being copied; each region by its layer's first member alone
    void read_ahead(const Streamer& S, int di, const std::atomic<bool>& stop) const {
        static const double cap = (std::getenv("DS4_READAHEAD_MB") ? std::atof(std::getenv("DS4_READAHEAD_MB")) : 2048.0) *
                                  1048576.0;
        std::deque<std::pair<size_t, double>> issued;   // (batch, bytes) not yet copied
        double ahead = 0;
        for (size_t q = 0; q < S.b.size() && !stop.load(std::memory_order_relaxed);) {
            const size_t done = S.done.load(std::memory_order_relaxed);
            while (!issued.empty() && issued.front().first < done) {
                ahead -= issued.front().second;
                issued.pop_front();
            }
            if (ahead > cap) {
                std::this_thread::sleep_for(std::chrono::microseconds(500));
                continue;
            }
            const Batch& bt = S.b[q];
            const Layer& l0 = L[(size_t) bt.il];
            double nb = 0;
            if (l0.dev == di)
                for (int i = 0; i < bt.n; ++i) {
                    const int e = l0.host_list[(size_t) (bt.j0 + i)];
                    if (l0.lay.fmt == gg::kFmtMXFP4) {
                        if (copy_mode && l0.ram[(size_t) e] >= 0) continue;   // (in RAM: nothing to read)
                        for (int r = 0; r < 3; ++r)
                            os::advise(pk.fds[(size_t) l0.mx_file[r]], (l0.mx_off[r] + (uint64_t) e * l0.mx_stride[r]), mx_part_bytes(l0, r), true);
                        nb += (double) l0.blob;
                        continue;
                    }
                    os::advise(pk.fds[(size_t) l0.region_file[(size_t) e]], l0.region_off[(size_t) e], l0.region_bytes[(size_t) e], true);
                    nb += (double) l0.region_bytes[(size_t) e];
                }
            issued.push_back({q++, nb});
            ahead += nb;
        }
    }
    bool copy_ahead(Dev& d, Chunk& c, Streamer& S, int di, std::string& err) {
        const int P = Chunk::kParts;
        while (S.cp < S.b.size() && S.cp < S.kp + P) {
            const Batch& bt = S.b[S.cp];
            const int half = (int) (S.cp % P);
            const Layer& l0 = L[(size_t) bt.il];
            int mi = 0;
            for (int m = 0; m < l0.nm; ++m)
                if (member(l0, m).dev == di) mi = m;
            if (S.cp >= (size_t) P) CK(cudaStreamWaitEvent(c.cs, c.freed[half], 0));
            const bool half_mx = c.stage != nullptr && l0.nm > 1 && l0.lay.fmt == gg::kFmtMXFP4 &&
                                 std::getenv("DS4_TP_ROWDMA") == nullptr;   // (DS4_TP_ROWDMA: the old per-row 2D DMA, A/B)
            // DS4_TP_DIRECT (tp_direct_mode): a member's part of an expert in the pinned RAM copy goes out from where it
            // lies - gate / up rows by DMA, the down's part (dh bytes of each of its g.dim rows) by a gather kernel from the
            // mapped copy (2) or through the staging (1) - not through the readers' host copy into the staging (0)
            const int tpd = half_mx ? tp_direct_mode() : 0;
            int n_direct = 0;
            std::vector<char> dir((size_t) bt.n, 0);
            for (int i = 0; i < bt.n && tpd > 0; ++i)
                if (tp_direct_ok(l0, l0.host_list[(size_t) (bt.j0 + i)])) dir[(size_t) i] = 1, ++n_direct;
            uint8_t* sb = nullptr;   // in place: the batch's regions in the part's staging slots
            if (c.stage != nullptr && !(tpd == 2 && n_direct == bt.n)) {
                const double t_evt = now_ms();
                if (S.cp >= (size_t) P) CK(cudaEventSynchronize(c.filled[half]));   // (its last batch's copies out)
                c.dbg_evt_ms += now_ms() - t_evt;
                sb = c.stage + (size_t) half * (c.ring_n / P) * c.stage_stride;
                std::atomic<bool> bad{false};
                const double t_st = now_ms();
                c.readers->run(bt.n, [&](int i) {
                    const int e = l0.host_list[(size_t) (bt.j0 + i)];
                    if (dir[(size_t) i]) {   // (direct: the down's part alone in mode 1, nothing in mode 2)
                        if (tpd == 1) read_mx_member_down(l0, e, mi, sb + (size_t) i * c.stage_stride);
                    } else if (half_mx)   // (a tensor-parallel member: only its part, contiguous - read_mx_member)
                        bad.store(bad.load() || !read_mx_member(l0, e, mi, sb + (size_t) i * c.stage_stride));
                    else if (l0.lay.fmt == gg::kFmtMXFP4 ? !read_mx(l0, e, sb + (size_t) i * c.stage_stride)
                                                    : !pk.read_at(l0.region_file[(size_t) e], l0.region_off[(size_t) e],
                                                                  l0.region_bytes[(size_t) e],
                                                                  sb + (size_t) i * c.stage_stride))
                        bad.store(true);
                });
                c.dbg_stage_ms += now_ms() - t_st;
                if (bad.load()) {
                    err = "reading layer " + std::to_string(l0.il) + "'s experts from the model's files failed";
                    return false;
                }
            }
            const double t_dma = now_ms();
            for (int i = 0; i < bt.n; ++i) {
                uint8_t* dst = c.ring + ((size_t) half * (c.ring_n / P) + i) * c.ring_stride;
                const int e = l0.host_list[(size_t) (bt.j0 + i)];
                if (dir[(size_t) i]) {
                    if (!stream_member_direct(l0, mi, e, dst, c.cs, tpd, sb != nullptr ? sb + (size_t) i * c.stage_stride : nullptr,
                                              err))
                        return false;
                    ++c.run_direct;
                } else {
                    if (!stream_expert(l0, mi, e, dst, c.cs, err, sb != nullptr ? sb + (size_t) i * c.stage_stride : nullptr,
                                       half_mx))
                        return false;
                    ++c.run_staged;
                }
                c.stream_bytes += (double) unit(member(l0, mi));
                c.run_bytes += (double) unit(member(l0, mi));
            }
            c.dbg_dma_ms += now_ms() - t_dma;
            CK(cudaEventRecord(c.filled[half], c.cs));
            ++S.cp;
            S.done.store(S.cp, std::memory_order_relaxed);
        }
        return true;
    }

    // ---- the flow (see Chunk)
    // Windows (WDDM: HIP's runtime and CUDA's driver alike) submits queued work only when the host waits on the GPU:
    // the flow's copies and the compute it queued between its waits are submitted at once (win_submit); elsewhere
    // nothing.  (CUDA too since #303: two RTX 3080s hung before the first layer, one GPU spinning on the other's flow)
    static void kick(cudaStream_t s) { win_submit(s); }
    size_t flow_region(int r) const {   // a part's room in a staging slot (read from its offset rounded down)
        return ((flow_part[r] + os::kDirectAlign - 1) & ~(size_t) (os::kDirectAlign - 1)) + os::kDirectAlign;
    }
    size_t flow_stride() const { return flow_region(0) + flow_region(1) + flow_region(2); }
    static Chunk::Item& fit(Chunk& c, size_t i) { return c.items[i - c.base]; }
    // what member m of l's group reads of matrix r of an expert: gate / up its rows [m n_ff / nm, ..) - one run, from
    // this offset in the matrix, this long; the down the whole matrix (its part, the blocks [m n_ff / nm / 32, ..) of
    // every row, is DMA'd out of it row by row); alone (nm 1) every matrix whole
    size_t mx_read_off(const Layer& l, int m, int r) const {
        return r < 2 && l.nm > 1 ? (size_t) m * (size_t) (g.ff / l.nm) * gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim)
                                 : 0;
    }
    size_t mx_read_len(const Layer& l, int r) const {
        return r < 2 && l.nm > 1 ? (size_t) (g.ff / l.nm) * gg::type_row_bytes(gg::expert_type(l.lay, r), g.dim)
                                 : mx_part_bytes(l, r);
    }
    // the device's member index in L0's group (0 alone)
    int flow_mi(const Chunk& c, const Layer& L0) const {
        for (int m = 0; m < L0.nm; ++m)
            if (member(L0, m).dev == c.dev) return m;
        return 0;
    }
    void flow_push(Chunk& c, const Layer& l, int mi, int k, int e, int v) {
        c.items.emplace_back();
        Chunk::Item& it = c.items.back();
        it.il = l.il;
        it.mi = mi;
        it.k = k;
        it.e = e;
        it.v = v;
        bool in_ram = !l.ram.empty() && l.ram[(size_t) e] >= 0;
        const uint8_t* store_blob = nullptr;   // (the RAM store holds it: copied into staging like a RAM-tier slot, no read)
        if (!in_ram && store && l.nm == 1) {
            const int ss = store->find(l.il, e);
            if (ss >= 0) {
                store_blob = store->blob(ss);
                in_ram = true;
            }
        }
        // (DMA'd from where it lies.  A copy split over NUMA parts (copy_mode, NH > 1) holds each part's rows on its node:
        // part 0 alone is not the whole matrix, so such a copy takes the staging below, which reads all NH parts
        // (flow_pump) - the gate Project Maya's equivalent branch has (`... && NH == 1`, main 7bf15ac; cf. #533))
        if (in_ram && ram_pinned && store_blob == nullptr && (!copy_mode || NH == 1)) {
            const uint8_t* p = copy_mode ? ram_part[(size_t) l.ram[(size_t) e]][0]
                                         : ram_slots[(size_t) l.ram[(size_t) e]];
            for (int r = 0; r < 3; ++r)
                it.src[r] = p + (copy_mode ? cp_lay[(size_t) l.il][(size_t) r] : l.lay.trellis[r]) + mx_read_off(l, mi, r);
            ++c.it_ram;
            return;
        }
        if (in_ram)   // (copied into staging by io, then DMA'd; copy_mode: from its NH parts, flow_pump)
            it.ram = store_blob != nullptr ? store_blob
                     : copy_mode ? ram_part[(size_t) l.ram[(size_t) e]][0] : ram_slots[(size_t) l.ram[(size_t) e]];
        bool hit = false;
        if (!in_ram && c.lc != nullptr && l.nm == 1) {   // layer-major: from the layer cache, or kept for the chunks after
            const size_t i = c.base + c.items.size() - 1, stride = (l.blob + 63) & ~(size_t) 63;
            if (c.lc_il != l.il) {   // (a layer's first item: the slots the layer before used are its own again
                c.lc_il = l.il;      // once that layer's items are all read - `after` below)
                c.lc_used = 0;
                c.lc_n = (int) std::min<size_t>(c.lc_of.size(), c.lc_bytes / stride);
                c.lc_first = i;
                std::fill(c.lc_of.begin(), c.lc_of.end(), -1);
            }
            const int j = c.lc_of[(size_t) e];
            if (j >= 0) {   // (copied into staging by io once its reader is done, then DMA'd)
                it.ram = c.lc + (size_t) j * stride;
                it.after = c.lc_writer[(size_t) j];
                hit = true;
            } else if (k + 1 < (int) c.fl_T.size() && c.lc_used < c.lc_n) {   // (a later chunk may pick it)
                const int jn = c.lc_used++;
                c.lc_of[(size_t) e] = jn;
                c.lc_writer[(size_t) jn] = (int64_t) i;
                it.keep = c.lc + (size_t) jn * stride;
                it.after = (int64_t) c.lc_first - 1;
            }
        }
        if (c.direct && l.nm == 1 && !(in_ram && copy_mode)) {   // (the ring slot is the destination: filled by flow_pump when its turn comes)
            it.direct = true;
            it.stage = -1;
            it.left.store(3, std::memory_order_relaxed);
            ++(in_ram ? c.it_ram : hit ? c.it_lc : c.it_file);
            return;
        }
        it.stage = (int) (c.n_file++ % (uint64_t) c.S);
        uint8_t* sb = c.stage + (size_t) it.stage * c.stage_stride;
        for (int r = 0; r < 3; ++r) {
            const uint64_t off = l.mx_off[r] + (uint64_t) e * l.mx_stride[r] + mx_read_off(l, mi, r);
            it.src[r] = sb + (in_ram || hit ? 0 : off % os::kDirectAlign);
            sb += flow_region(r);
        }
        it.left.store(in_ram && copy_mode && store_blob == nullptr ? 3 * NH : 3, std::memory_order_relaxed);
        ++(in_ram ? c.it_ram : hit ? c.it_lc : c.it_file);
    }
    // the likely experts of (chunk k, layer il) for T tokens, first in its stream: the CPU lane's experts whose chance
    // to be picked at least once, 1 - (1 - share)^(picks), is at least DS4_SPEC_Q (0.9: the reads are what takes the
    // time, an unpicked one costs a whole read, and the routing is known a few ms after the layer before is done -
    // early reads pay where a chunk's long attention keeps the disk otherwise idle, and there nearly every expert is
    // that likely), likeliest first, at most what the staging and the ring hold (no more can be read before the layer
    // routes); the layer's virtual slots put them first, then its other CPU-lane experts in index order (the order the
    // rest of its picks are streamed in)
    // (a tensor-parallel group's members each decide their own stream and virtual slots - the same, from the same
    // profile and the same routing - and each reads only its part of every expert)
    void flow_spec(Chunk& c, int k, int il, int T) {
        static const double spec_q = std::getenv("DS4_SPEC_Q") ? std::atof(std::getenv("DS4_SPEC_Q")) : 0.9;
        Layer& l = L[(size_t) il];
        const int mi = flow_mi(c, l);
        int* vs = member(l, mi).vs_pin;
        c.spec_k = k;
        c.spec_il = il;
        c.spec_begin = c.base + c.items.size();
        const uint32_t* pr = prof.data() + (size_t) il * g.n_exp;
        double sum = 0;
        for (int e = 0; e < l.n_exp; ++e) sum += pr[e];
        std::vector<std::pair<double, int>> cand;
        const double picks = (double) l.k_exp * T;
        // (early reads only while they hit: once a run's likely ones went unpicked more often than DS4_SPEC_WASTE
        // (0.2) of the time, the rest of the run reads only what the routing picked - an unpicked one costs a whole
        // read, and how well the profile guesses depends on the PC's history and the prompt: V100, 64 tokens - 376
        // of 921 likely ones unpicked, 7 GB of 84 read for nothing; Radeon 8065S, 128 and 512 tokens - 44 of 945 and
        // 21 of 1568, the early reads 9-12% faster there)
        static const double waste = std::getenv("DS4_SPEC_WASTE") ? std::atof(std::getenv("DS4_SPEC_WASTE")) : 0.2;
        const bool early = c.it_spec < 2u * (uint64_t) c.ring_n || (double) c.it_spec_unused <= waste * (double) c.it_spec;
        for (int e : l.host_list) {
            if (!early) break;
            const double p = sum > 0 ? pr[e] / sum : 0.0;
            const double q = p >= 1.0 ? 1.0 : 1.0 - std::exp(picks * std::log1p(-p));
            if (q >= spec_q && spec_q <= 1.0) cand.push_back({q, e});
        }
        std::stable_sort(cand.begin(), cand.end(), [](const std::pair<double, int>& a, const std::pair<double, int>& b) {
            return a.first > b.first;
        });
        if (cand.size() > (size_t) (c.S + c.ring_n)) cand.resize((size_t) (c.S + c.ring_n));
        std::vector<char> is((size_t) l.n_exp, 0);
        int j = 0;
        for (const auto& x : cand) {
            vs[x.second] = l.n_slots + j++;
            is[(size_t) x.second] = 1;
        }
        for (int e : l.host_list)
            if (!is[(size_t) e]) vs[e] = l.n_slots + j++;
        for (const auto& x : cand) flow_push(c, l, mi, k, x.second, vs[x.second]);
        c.n_spec = (int) cand.size();
        c.it_spec += cand.size();
    }
    // (chunk k, layer il) routed (bounds b by virtual slot): the rest of its picks after its likely ones
    void flow_rest(Chunk& c, int k, int il, const std::vector<int>& b) {
        const Layer& l = L[(size_t) il];
        const int mi = flow_mi(c, l);
        const int* vs = member(l, mi).vs_pin;
        for (size_t i = c.spec_begin; i < c.spec_begin + (size_t) c.n_spec; ++i) {
            const int v = fit(c, i).v;
            if (b[(size_t) v + 1] == b[(size_t) v]) ++c.it_spec_unused;
        }
        for (int e : l.host_list) {   // (index order: their virtual slots ascending)
            const int v = vs[e];
            if (v >= l.n_slots + c.n_spec && b[(size_t) v + 1] > b[(size_t) v]) flow_push(c, l, mi, k, e, v);
        }
    }
    // the next (chunk, layer) of the device after (k, il) in the run's order that streams experts (false: none) - a
    // long prompt's skip leaves out its early chunks' layers from Run::yoco on (kv_only there: no experts)
    bool flow_next(const Chunk& c, int k, int il, int& k2, int& il2) const {
        while (flow_next1(c, k, il, k2, il2)) {
            if (c.fl_yoco < 0 || k2 >= c.fl_cut_k || il2 < c.fl_yoco) return true;
            k = k2;
            il = il2;
        }
        return false;
    }
    // the rows chunk k runs layer il on (a long prompt's skip: the cut chunk's from cut_r on, from the yoco layer on)
    static int fl_rows(const Chunk& c, int k, int il) {
        const int T = c.fl_T[(size_t) k];
        return c.fl_yoco >= 0 && k == c.fl_cut_k && il >= c.fl_yoco ? T - c.fl_cut_r : T;
    }
    bool flow_next1(const Chunk& c, int k, int il, int& k2, int& il2) const {
        const auto it = std::find(c.fl_layers.begin(), c.fl_layers.end(), il);
        const size_t i = (size_t) (it - c.fl_layers.begin());
        if (c.lm) {   // (layer-major: the layer's next chunk, then the next layer's first)
            if (k + 1 < (int) c.fl_T.size()) {
                k2 = k + 1;
                il2 = il;
                return true;
            }
            if (i + 1 >= c.fl_layers.size()) return false;
            k2 = 0;
            il2 = c.fl_layers[i + 1];
            return true;
        }
        if (i + 1 < c.fl_layers.size()) {
            k2 = k;
            il2 = c.fl_layers[i + 1];
            return true;
        }
        if (k + 1 < (int) c.fl_T.size() && !c.fl_layers.empty()) {
            k2 = k + 1;
            il2 = c.fl_layers[0];
            return true;
        }
        return false;
    }
    // the reads (in order, each into its staging slot once that slot's last DMA is done) and the DMAs (in order, each
    // into its ring slot once that slot's last use is queued: the copy stream waits for it) as far as they can go now
    bool flow_pump(Chunk& c, std::string& err) {
        const size_t end = c.base + c.items.size();
        IoQueue::Job jobs[6];
        while (c.n_read < end) {
            Chunk::Item& it = fit(c, c.n_read);
            if (it.after >= 0) {   // layer-major: a slot's expert copied out of it once its reader is done; a slot
                // written again once the layer before's items are all read (none still copies out of it)
                bool wait = false;
                if (it.keep == nullptr)
                    wait = (size_t) it.after >= c.base && fit(c, (size_t) it.after).left.load(std::memory_order_acquire) != 0;
                else {
                    while (c.lc_chk < c.n_read &&
                           (c.lc_chk < c.base || fit(c, c.lc_chk).left.load(std::memory_order_acquire) == 0))
                        ++c.lc_chk;
                    wait = c.lc_chk <= (size_t) it.after;
                }
                if (wait) break;
            }
            if (it.direct) {
                const size_t R = (size_t) c.ring_n, r = c.n_read % R;
                if (c.n_read >= R) {   // the slot's last use has to be computed - and finished: the CPU writes it
                    if (c.n_comp <= c.n_read - R) break;
                    CK(cudaEventSynchronize(c.ring_free[r]));
                }
                const Layer& l = L[(size_t) it.il];
#if defined(STRATA_METAL)
                uint8_t* dst = (uint8_t*) strata::gpu::host_view(c.ring + r * c.ring_stride);   // (device addresses are the GPU's: the CPU writes through the host view)
#else
                uint8_t* dst = c.ring + r * c.ring_stride;
#endif
                const x3::ExpertLayout& lay = l.lay;
                int nj = 0;
                for (int q = 0; q < 3; ++q) {
                    IoQueue::Job& j = jobs[nj++];
                    j = IoQueue::Job{};
                    const os::fd_t pf = pk.pfds.empty() ? os::kBadFd : pk.pfds[(size_t) l.mx_file[q]];
                    j.fd = pf != os::kBadFd ? pf : pk.fds[(size_t) l.mx_file[q]];
                    j.dfd = pk.dfds.empty() ? os::kBadFd : pk.dfds[(size_t) l.mx_file[q]];
                    j.off = l.mx_off[q] + (uint64_t) it.e * l.mx_stride[q];
                    j.len = mx_part_bytes(l, q);
                    j.dst = dst + lay.trellis[q];
                    j.exact = true;
                    j.left = &it.left;
                    j.bad = &it.bad;
                    j.mem = it.ram != nullptr ? it.ram + lay.trellis[q] : nullptr;
                    j.map = pk.at(l.mx_file[q], j.off);
                    j.keep = it.keep != nullptr ? it.keep + lay.trellis[q] : nullptr;
                }
                c.io->push(jobs, nj);
            } else if (it.stage >= 0) {
                const int64_t prev = c.stage_item[(size_t) it.stage];
                if (prev >= 0) {
                    if ((size_t) prev >= c.n_dma) break;
                    const cudaError_t q = cudaEventQuery(c.stage_ev[(size_t) it.stage]);
                    if (q == cudaErrorNotReady) break;
                    CK(q);
                }
                c.stage_item[(size_t) it.stage] = (int64_t) c.n_read;
                const Layer& l = L[(size_t) it.il];
                uint8_t* sb = c.stage + (size_t) it.stage * c.stage_stride;
                const int cs = copy_mode && it.ram != nullptr ? l.ram[(size_t) it.e] : -1;   // (a copy's slot)
                int nj = 0;
                for (int r = 0; r < 3; ++r) {
                    if (cs >= 0) {   // a copy: each matrix's NH parts of rows, side by side into staging
                        const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
                        for (int X = 0; X < NH; ++X) {
                            IoQueue::Job& j = jobs[nj++];
                            j = IoQueue::Job{};
                            j.len = nb;
                            j.dst = sb + (size_t) X * nb;
                            j.left = &it.left;
                            j.bad = &it.bad;
                            j.mem = ram_part[(size_t) cs][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r];
                        }
                        sb += flow_region(r);
                        continue;
                    }
                    IoQueue::Job& j = jobs[nj++];
                    const os::fd_t pf = pk.pfds.empty() ? os::kBadFd : pk.pfds[(size_t) l.mx_file[r]];
                    j.fd = pf != os::kBadFd ? pf : pk.fds[(size_t) l.mx_file[r]];
                    j.dfd = pk.dfds.empty() ? os::kBadFd : pk.dfds[(size_t) l.mx_file[r]];
                    j.off = l.mx_off[r] + (uint64_t) it.e * l.mx_stride[r] + mx_read_off(l, it.mi, r);
                    j.len = mx_read_len(l, r);
                    j.dst = sb;
                    j.left = &it.left;
                    j.bad = &it.bad;
                    j.mem = it.ram != nullptr ? it.ram + l.lay.trellis[r] + mx_read_off(l, it.mi, r) : nullptr;
                    j.map = pk.at(l.mx_file[r], j.off);
                    j.keep = it.keep != nullptr ? it.keep + l.lay.trellis[r] : nullptr;
                    sb += flow_region(r);
                }
                c.io->push(jobs, nj);
            }
            ++c.n_read;
        }
        const size_t R = (size_t) c.ring_n, dma0 = c.n_dma;
        struct Kick {   // (every way out: what was queued is submitted)
            cudaStream_t s;
            const size_t &a, b;
            ~Kick() {
                if (a != b) kick(s);
            }
        } kq{c.cs, c.n_dma, dma0};
        while (c.n_dma < c.n_read && c.n_dma < c.n_comp + R) {
            Chunk::Item& it = fit(c, c.n_dma);
            if (it.left.load(std::memory_order_acquire) != 0) break;
            if (it.bad.load(std::memory_order_acquire)) {
                err = "reading layer " + std::to_string(it.il) + " expert " + std::to_string(it.e) +
                      " from the model's files failed";
                return false;
            }
            const size_t r = c.n_dma % R;
            if (c.n_dma >= R) CK(cudaStreamWaitEvent(c.cs, c.ring_free[r], 0));
            const Layer& l = L[(size_t) it.il];
            uint8_t* dst = c.ring + r * c.ring_stride;
            const x3::ExpertLayout& lay = l.nm > 1 ? l.hlay : l.lay;
            if (it.direct) {   // (already in the slot)
                CK(cudaEventRecord(c.ring_fill[r], c.cs));
                c.stream_bytes += (double) unit(l);
                ++c.n_dma;
                continue;
            }
            for (int p = 0; p < 2; ++p)
                CK(cudaMemcpyAsync(dst + lay.trellis[p], it.src[p], mx_read_len(l, p), cudaMemcpyHostToDevice, c.cs));
            if (l.nm > 1) {   // (the down's part: in each of its rows the member's blocks)
                const int t2 = gg::expert_type(l.lay, 2);
                const size_t dr = gg::type_row_bytes(t2, g.ff), dh = gg::type_row_bytes(t2, g.ff / l.nm);
                CK(cudaMemcpy2DAsync(dst + lay.trellis[2], dh, it.src[2] + (size_t) it.mi * dh, dr, dh, (size_t) g.dim,
                                     cudaMemcpyHostToDevice, c.cs));
            } else
                CK(cudaMemcpyAsync(dst + lay.trellis[2], it.src[2], mx_part_bytes(l, 2), cudaMemcpyHostToDevice, c.cs));
            CK(cudaEventRecord(c.ring_fill[r], c.cs));
            if (it.stage >= 0) CK(cudaEventRecord(c.stage_ev[(size_t) it.stage], c.cs));
            c.stream_bytes += (double) unit(l);
            ++c.n_dma;
        }
        return true;
    }
    // layer L0 of chunk k routed (bounds b, the device's copy d_bounds): its streamed experts as they land, the VRAM
    // ones in shares between them (the device works while the reads run)
    bool flow_layer(Dev& d, Chunk& c, Layer& L0, int mi, int k, int T, const std::vector<int>& b, std::string& err) {
        cudaStream_t s = d.st;
        const uint8_t* vbase = member(L0, mi).vram_base;   // (a member's: its part of each VRAM expert, L0's slots)
        if (c.spec_k != k || c.spec_il != L0.il) {
            err = "the prompt path's expert stream is out of step (layer " + std::to_string(L0.il) + ")";
            return false;
        }
        flow_rest(c, k, L0.il, b);
        const size_t lb = c.spec_begin, le = c.base + c.items.size(), n_lay = le - lb;
        int k2 = 0, il2 = 0;
        if (flow_next(c, k, L0.il, k2, il2)) flow_spec(c, k2, il2, fl_rows(c, k2, il2));
        const size_t R = (size_t) c.ring_n, bmax = std::max<size_t>(1, R / 2);
        int v_done = 0;
        while (c.n_comp < le) {
            // a batch's bounds are fixed by the stream alone (bmax items, never across the ring's end), never by what
            // has landed: the experts' outputs are summed batch after batch (the VRAM ones' shares between them), so
            // the sums come out the same on every run whatever the reads' timing
            const size_t i0 = c.n_comp, i1 = std::min({le, i0 + bmax, (i0 / R + 1) * R});
            if (!flow_pump(c, err)) return false;
            if (c.n_dma < i1) {   // not all of the batch landed: wait for a read, or for a staging slot's copy
                const double tw = now_ms();
                kick(s);
                if (c.n_read > c.n_dma) c.io->wait_any(500);
                else {
                    const Chunk::Item& it = fit(c, c.n_read);
                    if (it.stage >= 0) CK(cudaEventSynchronize(c.stage_ev[(size_t) it.stage]));
                }
                c.wait_ms += now_ms() - tw;
                continue;
            }
            const int n = (int) (i1 - i0);
            int* bc = c.bc_pin + (size_t) (c.n_batch % (uint64_t) c.bc_n) * c.bc_w;
            int* bcd = c.bc_dev + (size_t) (c.n_batch % (uint64_t) c.bc_n) * c.bc_w;
            ++c.n_batch;
            // (the items' virtual slots ascend and the slots between them have no rows: their bounds side by side)
            for (int m = 0; m < n; ++m) bc[m] = b[(size_t) fit(c, i0 + (size_t) m).v];
            bc[n] = b[(size_t) fit(c, i1 - 1).v + 1];
            if (bc[n] > bc[0]) {
                CK(cudaStreamWaitEvent(s, c.ring_fill[(i1 - 1) % R], 0));
                CK(cudaMemcpyAsync(bcd, bc, (size_t) (n + 1) * 4, cudaMemcpyHostToDevice, s));
                if (!run_set(d, c, L0, c.ring + (i0 % R) * c.ring_stride, 0, c.ring_stride, bcd, bc, 0, n, T, err))
                    return false;
            }
            for (size_t i = i0; i < i1; ++i) CK(cudaEventRecord(c.ring_free[i % R], s));
            kick(s);
            c.n_comp = i1;
            if (!flow_pump(c, err)) return false;
            const int v_to = (int) ((int64_t) L0.n_slots * (int64_t) (c.n_comp - lb) / (int64_t) std::max<size_t>(1, n_lay));
            if (!run_set(d, c, L0, vbase, 0, unit(L0), c.bounds, b.data(), v_done, v_to, T, err)) return false;
            v_done = v_to;
        }
        if (!run_set(d, c, L0, vbase, 0, unit(L0), c.bounds, b.data(), v_done, L0.n_slots, T, err)) return false;
        while (c.base < c.n_comp && c.items.size() > 4096) {   // (done with: read, copied and used)
            c.items.pop_front();
            ++c.base;
        }
        return true;
    }

    // the experts [i0, i1) of a sorted set (blobs at wbase + i * stride; bounds b on the host, d_bounds on the device)
    // over the chunk's rows, in pieces of at most C rows, each added into acc in pick order
    bool run_set(Dev& d, Chunk& c, const Layer& l, const uint8_t* wbase, int wb0, size_t stride, const int* d_bounds,
                 const int* b, int i0, int i1, int T, std::string& err) {
        const int D = g.dim, FF = l.ffn;
        while (i0 < i1) {
            int j = i0 + 1;
            while (j < i1 && b[j + 1] - b[i0] <= c.C) ++j;
            const int a = b[i0], nrows = b[j] - a;
            int max_rows = 0;
            for (int i = i0; i < j; ++i) max_rows = std::max(max_rows, b[i + 1] - b[i]);
            if (nrows > 0) {
                x3::SetArgs sa;
                sa.wbase = wbase + (size_t) (i0 - wb0) * stride;   // (wbase: set member wb0's blob)
                sa.stride = stride;
                sa.lay = l.nm > 1 ? l.hlay : l.lay;
                sa.n_exp = j - i0;
                sa.bounds = d_bounds + i0;
                sa.row0 = a;
                sa.max_rows = max_rows;
#if defined(STRATA_METAL)
                sa.hbounds = b + i0;
                sa.total_rows = nrows;
#endif
                sa.n_embd = D;
                sa.n_ff = FF;
                sa.limit = g.lim;
                // gate / up read the layer's F16 copy of the activations (the same rounding the tiles make for their
                // shared tile): with 18-36 column blocks an expert the F32 rows were read that many times
                sa.x16 = strata::ds4::gate_up_x16_default(defaults_026()) ? c.x16 : nullptr;
                // the busy experts (DS4_FAT_ROWS=N: those of N rows or more): their weights decoded to FP16 once and
                // multiplied by the library's GEMM - the tiles decode an expert's weights again for every 64 of its rows
                std::vector<int> fat;
                if (sa.lay.fmt == gg::kFmtMXFP4 && !gg::mx_experts(sa.lay) && D % 256 == 0 && FF % 256 == 0 &&
                    gg::expert_type(sa.lay, 1) == gg::expert_type(sa.lay, 0) &&
                    gg::iq::f16_rows_ok(gg::expert_type(sa.lay, 0)) && gg::iq::f16_rows_ok(gg::expert_type(sa.lay, 2)) &&
                    fat_ready(d, c, D, FF)) {
                    int rest = 0;
                    for (int i = i0; i < j; ++i) {
                        const int r = b[i + 1] - b[i];
                        if (r >= fat_rows()) fat.push_back(i);
                        else rest = std::max(rest, r);
                    }
                    if (!fat.empty()) {
                        sa.skip_ge = fat_rows();
                        sa.max_rows = rest;
                    }
                }
                EkMark ek{};
                const bool ekp = prof_chunk;
                if (ekp) {
                    std::lock_guard<std::mutex> lk(prof_mu);
                    ek.e0 = ek_ev();
                    ek.e1 = ek_ev();
                    ek.e2 = ek_ev();
                    ek.tg = gg::expert_type(sa.lay, 0);
                    ek.td = gg::expert_type(sa.lay, 2);
                    ek.nrows = nrows;
                    ek.nexp = j - i0;
                    ek.maxrows = max_rows;
                    ek.ff = FF;
                    cudaGetDevice(&ek.dev);
                    cudaEventRecord(ek.e0, d.st);
                }
                if (sa.lay.fmt == gg::kFmtMXFP4) {
                    gg::set_gate_up(sa, c.x, D, c.row_tok + a, c.h16, FF, d.st);
                    for (const int i : fat)
                        if (!fat_gate_up(c, sa, sa.wbase + (size_t) (i - i0) * stride, b[i], b[i + 1] - b[i], a, D, FF,
                                         d.st, err))
                            return false;
                    if (ekp) cudaEventRecord(ek.e1, d.st);
                    gg::set_down(sa, c.h16, FF, c.y, D, d.st);
                    for (const int i : fat)
                        if (!fat_down(c, sa, sa.wbase + (size_t) (i - i0) * stride, b[i] - a, b[i + 1] - b[i], D, FF,
                                      d.st, err))
                            return false;
                } else {
                    x3::set_gate_up(sa, c.x, D, c.row_tok + a, c.h16, FF, d.st);
                    if (ekp) cudaEventRecord(ek.e1, d.st);
                    x3::set_down(sa, c.h16, FF, c.y, D, d.st);
                }
                if (ekp) {
                    cudaEventRecord(ek.e2, d.st);
                    std::lock_guard<std::mutex> lk(prof_mu);
                    ek_marks.push_back(ek);
                }
                if (dump_y != nullptr && (dump_y_layer < 0 || l.il == dump_y_layer)) {
                    std::vector<int> bb(b + i0, b + j + 1);
                    std::vector<uint16_t> hv((size_t) nrows * FF);
                    std::vector<float> yv((size_t) nrows * D);
                    CK(cudaStreamSynchronize(d.st));
                    CK(cudaMemcpy(hv.data(), c.h16, hv.size() * 2, cudaMemcpyDeviceToHost));
                    CK(cudaMemcpy(yv.data(), c.y, yv.size() * 4, cudaMemcpyDeviceToHost));
                    std::lock_guard<std::mutex> lk(dump_mu);
                    const int64_t hdr[6] = {l.il, a, nrows, j - i0, wbase == c.ring || (wbase > c.ring &&
                                            wbase < c.ring + (size_t) c.ring_n * c.ring_stride) ? 1 : 0, max_rows};
                    std::fwrite(hdr, 8, 6, dump_y);
                    std::fwrite(bb.data(), 4, bb.size(), dump_y);
                    std::fwrite(hv.data(), 2, hv.size(), dump_y);
                    std::fwrite(yv.data(), 4, yv.size(), dump_y);
                    std::fflush(dump_y);
                }
                moe_combine(c.acc, c.y, c.pos, c.rw, T, l.k_exp, a, a + nrows, D, d.st);
            }
            i0 = j;
        }
        (void) err;
        return true;
    }

    bool load_dense(int di, std::string& err) {
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        size_t* acct = &d.weights;
        for (Layer& l0 : L)
          for (int mi = 0; mi < l0.nm; ++mi) {
            Layer& l = member(l0, mi);
            if (l.dev != di) continue;
            // (a group's member: its share of the heads (wq_b columns, the sinks), of wo_a's groups and wo_b's rows,
            // of the shared expert's FFN; the rest whole)
            const int nm = l0.nm, na = g.heads / std::max(1, l.ahn), ha = l.ah0 / std::max(1, l.ahn);
            const std::string& P = l.name;
            // tp4 (Project Maya e3f2475 #408): an uneven split's shared expert at the member's own FFN range, as its
            // routed experts - decode runs it with FF = l.ffn - which needs it as wide as theirs
            const int sr0 = nm > 1 && tp_uneven && l0.lay.fmt == gg::kFmtMXFP4 ? l.ff0 : -1;
            if (sr0 >= 0) {
                const Tensor* sw = pk.get(P + "ffn.shared_experts.w1.weight");
                if (sw == nullptr || sw->shape.size() != 2 || (int) sw->shape[0] != g.ff) {
                    err = "layer " + std::to_string(l.il) + ": the uneven tensor-parallel split needs the shared expert as "
                          "wide as the routed ones (" + std::to_string(g.ff) + ")";
                    return false;
                }
            }
            const std::string A = P + "attn.";
            bool ok = mat(d, A + "wq_a", l.wq_a, err, acct) &&
                      (l.a3 || l.ahn == 0 || mat(d, A + "wq_b", l.wq_b, err, acct, ha, na, true)) &&
                      mat(d, A + "wkv", l.wkv, err, acct) &&
                      (l.a3 || l.ahn == 0 || mat(d, A + "wo_b", l.wo_b, err, acct, ha, na, false)) &&
                      f32(d, A + "q_norm.weight", l.q_norm, err, acct, (size_t) g.q_lora) &&
                      f32(d, A + "kv_norm.weight", l.kv_norm, err, acct, (size_t) g.hd) &&
                      f32(d, A + "attn_sink", l.sink, err, acct, (size_t) g.heads) &&
                      f32(d, P + "attn_norm.weight", l.attn_norm, err, acct, (size_t) g.dim) &&
                      f32(d, P + "ffn_norm.weight", l.ffn_norm, err, acct, (size_t) g.dim) &&
                      f32(d, P + "hc_attn_fn", l.hca_fn, err, acct) && f32(d, P + "hc_attn_scale", l.hca_scale, err, acct) &&
                      f32(d, P + "hc_attn_base", l.hca_base, err, acct) && f32(d, P + "hc_ffn_fn", l.hcf_fn, err, acct) &&
                      f32(d, P + "hc_ffn_scale", l.hcf_scale, err, acct) &&
                      f32(d, P + "hc_ffn_base", l.hcf_base, err, acct) &&
                      gate(d, P + "ffn.gate.weight", l.gate_w, err, acct, (size_t) l.n_exp * g.dim) &&
                      f32(d, P + "ffn.gate.bias", l.gate_bias, err, acct, (size_t) l.n_exp) &&
                      (l.mtp || img_tok < 0 || pk.get(P + "ffn.gate.bias_vl") == nullptr ||
                       f32(d, P + "ffn.gate.bias_vl", l.gate_bias_vl, err, acct, (size_t) l.n_exp)) &&
                      mat(d, P + "ffn.shared_experts.w1", l.s1, err, acct, mi, nm, true, l.il % nm, sr0, l.ffn) &&
                      mat(d, P + "ffn.shared_experts.w2", l.s2, err, acct, mi, nm, false, l.il % nm, sr0, l.ffn) &&
                      mat(d, P + "ffn.shared_experts.w3", l.s3, err, acct, mi, nm, true, l.il % nm, sr0, l.ffn);
            if (!ok) return false;
            if (sr0 >= 0 && (l.s1.n != l.ffn || l.s3.n != l.ffn || l.s2.k != l.ffn)) {   // (tp4)
                err = "layer " + std::to_string(l.il) + ": the shared expert's part (" + std::to_string(l.s1.n) +
                      ") is not the member's FFN range (" + std::to_string(l.ffn) + ")";
                return false;
            }
            if (l0.mtp && !l0.dkeep.empty() && !draft_mask_bias(d, l.gate_bias, l0, err)) return false;   // DS4_DRAFT_KEEP
            if (l.a3) {   // DS4_ATTN_SPLIT3: its groups in a3_ord's order (see Layer::a3)
                const int hpg = g.heads / g.o_groups, ql = hpg * g.hd;
                std::vector<std::pair<int, int>> qr, br;
                for (int i = 0; i < l.a3_ng; ++i) {
                    qr.push_back({l.a3_ord[i] * ql, ql});
                    br.push_back({l.a3_ord[i] * g.o_lora, g.o_lora});
                }
                if (!mat_concat(d, A + "wq_b", l.wq_b, err, acct, qr, true) ||
                    !mat_concat(d, A + "wo_b", l.wo_b, err, acct, br, false))
                    return false;
                for (int i = 0; i < l.a3_ng; ++i)
                    if (!mat(d, A + "wo_a.slice." + std::to_string(l.a3_ord[i]), l.wo_a[i], err, acct)) return false;
                const int HO = l.a3_own * g.hd, HS = l.a3_sh * g.hd, KO = l.a3_own / hpg * g.o_lora,
                          KS = l.a3_sh / hpg * g.o_lora;
                l.a3_qo = gg::view(l.wq_b, 0, HO);
                l.a3_qs = gg::view(l.wq_b, HO, HS);
                l.a3_qd = gg::view(l.wq_b, 0, l.ahn * g.hd);
                l.a3_bo = kview(l.wo_b, 0, KO);
                l.a3_bs = kview(l.wo_b, KO, KS);
                l.a3_bd = kview(l.wo_b, 0, l.ogn * g.o_lora);
                // the sinks in the same order: a3_ord's heads first
                std::vector<float> sk((size_t) g.heads), so;
                cudaSetDevice(d.id);
                CK(cudaMemcpy(sk.data(), l.sink, sk.size() * 4, cudaMemcpyDeviceToHost));
                std::vector<char> used((size_t) g.heads, 0);
                for (int i = 0; i < l.a3_ng; ++i)
                    for (int h = 0; h < hpg; ++h) {
                        so.push_back(sk[(size_t) (l.a3_ord[i] * hpg + h)]);
                        used[(size_t) (l.a3_ord[i] * hpg + h)] = 1;
                    }
                for (int h = 0; h < g.heads; ++h)
                    if (!used[(size_t) h]) so.push_back(sk[(size_t) h]);
                CK(cudaMemcpy(l.sink, so.data(), so.size() * 4, cudaMemcpyHostToDevice));
                if (o.verbose && l.il == 0)
                    std::fprintf(stderr, "ds4: DS4_ATTN_SPLIT3: CUDA%d (part %d) groups %d own + %d shared, decode %d heads\n", d.id, l.mi,
                                 l.a3_own / hpg, l.a3_sh / hpg, l.ahn);
            } else {
                l.sink += (size_t) l.ah0;
                for (int gi = 0; gi < l.ogn; ++gi)
                    if (!mat(d, A + "wo_a.slice." + std::to_string(l.og0 + gi), l.wo_a[gi], err, acct)) return false;
            }
            if (l.kv_src) {
                const std::string C = A + "compressor.";
                if (!mat(d, C + "wkv", l.c_wkv, err, acct) || !f32(d, C + "norm.weight", l.c_norm, err, acct)) return false;
                if (l.ratio > 1 && !mat(d, C + "wgate", l.c_wgate, err, acct)) return false;
                if (l.ratio > 1 && (!dalloc(d, l.c_kv, (size_t) l.ratio * g.hd, err) ||
                                    !dalloc(d, l.c_score, (size_t) l.ratio * g.hd, err)))
                    return false;
            }
            if (l.ix_src) {
                const std::string I = A + "indexer.";
                if (!mat(d, I + "wq_b", l.i_wq_b, err, acct) || !f16raw(d, I + "weights_proj.weight", l.i_wproj, err, acct))
                    return false;
                if (l.owns_k && (!mat(d, I + "wk", l.i_wk, err, acct) || !f32(d, I + "k_norm.weight", l.ik_norm, err, acct)))
                    return false;
            }
            if (l.eg >= 0) {
                if (!mat(d, P + "engram.wkv", l.eg_wkv, err, acct)) return false;
                if (pk.get(P + "engram.gate.weight") != nullptr) {   // a GGUF: q_weight * k_weight, folded already
                    if (!f32(d, P + "engram.gate.weight", l.eg_w, err, acct, (size_t) g.hc * g.dim)) return false;
                } else {
                    float *qw = nullptr, *kw = nullptr;
                    if (!f32(d, P + "engram.q_weight", qw, err, acct) || !f32(d, P + "engram.k_weight", kw, err, acct))
                        return false;
                    std::vector<float> a((size_t) g.hc * g.dim), b(a.size());
                    CK(cudaMemcpy(a.data(), qw, a.size() * 4, cudaMemcpyDeviceToHost));
                    CK(cudaMemcpy(b.data(), kw, b.size() * 4, cudaMemcpyDeviceToHost));
                    for (size_t i = 0; i < a.size(); ++i) a[i] *= b[i];   // only ever used as a product
                    CK(cudaMemcpy(qw, a.data(), a.size() * 4, cudaMemcpyHostToDevice));
                    l.eg_w = qw;
                }
            }
            if (!dalloc(d, l.win, (size_t) g.win * win_rb(), err, &d.caches)) return false;
            if (g.n_mtp > 0 && !l.mtp) {
                if (!dalloc(d, l.ring_bak, (size_t) kWin * win_rb(), err)) return false;
                if (l.kv_src && l.ratio > 1 && (!dalloc(d, l.c_snap, (size_t) 2 * l.ratio * g.hd, err) ||
                                                !dalloc(d, l.c_rows, (size_t) 2 * kWin * g.hd, err)))
                    return false;
            }
            if (!dalloc(d, l.vram_tab, (size_t) l.n_exp, err, acct)) return false;
          }
        if (d.grp == devs[(size_t) head_dev].grp) {   // the head: each member of its group a share of the columns
            const int hn = head_nm();
            // tp4 fix: the member's columns exactly as head_cols gives them (head_share, its gather and the markov
            // rows use head_cols).  mat_gg split a K-quant head in 128-column blocks only where the vocabulary does not
            // divide by the members: 129,280 / 4 = 32,320 divides, so at tp4 it loaded even 32,320-column shares while
            // head_cols' split128 gathers 32,384 / 32,384 / 32,256 / 32,256 - every logit past the first boundary taken
            // from the wrong column (q4 top-1 87 %, KL > 1 at 12.8 % of positions).  tp3 (split128 there too) and tp2
            // (64,640 = 505 blocks either way) load the same columns as before
            // (a GGUF dense head only - an EXL3 one takes split128's rot 0 in mat, head_cols' split already)
            const Tensor* thw = pk.get("head.weight");
            const bool hgg = thw != nullptr && (thw->dtype == "BF16" || thw->dtype == "Q8_0" || thw->dtype == "Q4_K" ||
                                                thw->dtype == "Q5_K" || thw->dtype == "Q6_K");
            int hv0 = 0, hvn = g.vocab;
            if (hn > 1) head_cols(hn, d.mi, hv0, hvn);
            if (!mat(d, "head", d.head, err, acct, d.mi, hn, true, 0, hn > 1 && hgg ? hv0 : -1, hvn) ||
                !f32(d, "norm.weight", d.norm_w, err, acct, (size_t) g.dim))
                return false;
            if (hn > 1 && d.head.n != hvn) {
                err = "the head's columns on CUDA" + std::to_string(d.id) + ": " + std::to_string(d.head.n) + " loaded, " +
                      std::to_string(hvn) + " in head_cols' share [" + std::to_string(hv0) + ", " + std::to_string(hv0 + hvn) + ")";
                return false;
            }
            if (g.n_mtp > 0 && !f32(d, "mtp." + std::to_string(g.n_mtp - 1) + ".norm.weight", d.d_norm, err, acct, (size_t) g.dim))
                return false;
            if (!dalloc(d, d.logits_part, (size_t) kWin * ((g.vocab / 128 + hn - 1) / hn * 128), err)) return false;
            if (g.n_mtp > 0 && hn > 1) {   // the markov steps over the group (mk_split): this member's rows of the head
                const Tensor* th = pk.get("mtp." + std::to_string(g.n_mtp - 1) + ".markov_head.head.weight");
                const int R = g.d_rank;
                head_cols(hn, d.mi, d.mk_v0, d.mk_vn);   // (its share of the head's columns: the same rows)
                // F16 as the pack holds it, or a GGUF drafter's BF16 rounded to F16 as f16raw rounds d_mk_head (the same
                // values as the lead's whole rows); another type: no mk_split (the lead's whole rows)
                if (th != nullptr && (th->dtype == "F16" || th->dtype == "BF16") && th->bytes == (uint64_t) g.vocab * R * 2) {
                    std::vector<uint16_t> rows((size_t) d.mk_vn * R);
                    if (!pk.read_at(th->file, th->off + (uint64_t) d.mk_v0 * R * 2, rows.size() * 2, rows.data())) {
                        err = "the markov head: read failed";
                        return false;
                    }
                    if (th->dtype == "BF16")
                        for (uint16_t& h : rows) h = strata::kernels::f16_from_f32(bf16_to_f32(h));
                    if (!dalloc(d, d.mk_share, rows.size(), err, acct) || !dalloc(d, d.mk_erow, (size_t) R, err) ||
                        !dalloc(d, d.mk_ints, (size_t) kWin + 2, err))
                        return false;
                    CK(cudaMemcpy(d.mk_share, rows.data(), rows.size() * 2, cudaMemcpyHostToDevice));
                }
            }
        }
        if (di == head_dev) {
            head = d.head;
            norm_w = d.norm_w;
            d_norm = d.d_norm;
            if (g.n_mtp > 0) {
                const std::string Z = "mtp." + std::to_string(g.n_mtp - 1) + ".";
                if (!f32(d, Z + "confidence_head.proj.weight", d_conf, err, acct, (size_t) (g.dim + g.d_rank)))
                    return false;
                const Tensor* te = pk.get(Z + "markov_head.embed.weight");
                const Tensor* th = pk.get(Z + "markov_head.head.weight");
                if (te == nullptr || th == nullptr || te->dtype != "BF16" || (th->dtype != "F16" && th->dtype != "BF16")) {
                    err = Z + "markov_head: not the BF16 embed and F16 / BF16 head expected";
                    return false;
                }
                if (!dalloc(d, d_mk_embed, te->bytes / 2, err, acct) || !upload(d, *te, d_mk_embed, err) ||
                    (strata::ds4::markov_head_q8_default(defaults_026())
                         ? !mk_head_q8(d, Z + "markov_head.head.weight", d_mk_head_q8, err, acct)
                         : !f16raw(d, Z + "markov_head.head.weight", d_mk_head, err, acct)))   // (0.2.6: the head as F16)
                    return false;
            }
        }
        if (g.n_mtp > 0 && di == d_dev) {
            if (!mat(d, "mtp.0.main_proj", d_main_proj, err, acct) ||
                !f32(d, "mtp.0.main_norm.weight", d_main_norm, err, acct, (size_t) g.dim))
                return false;
        }
        return true;
    }

#if defined(STRATA_METAL)
    // The most the VRAM experts may add on a Mac: the engine's anonymous memory (Metal buffers + host memory, all counted) stays
    // under the cap metal/src/engine/arena_budget.h derived from the freezes of the 128 GB M5 Max (macOS keeps a file-cache floor and
    // compresses / swaps anonymous memory past it): max(15% of the RAM, 40% of the RAM, the floor + 12 GB) left to macOS, at most
    // the GPU working set; what the process holds now (task_info phys_footprint) is already inside it.
    double metal_expert_cap() const {
        uint64_t phys = 0;
        size_t len = sizeof phys;
        sysctlbyname("hw.memsize", &phys, &len, nullptr, 0);
        unsigned long long pages = 0;
        size_t pl = sizeof pages;
        double floor_b = 0;
        if (sysctlbyname("vm.vm_page_filecache_min", &pages, &pl, nullptr, 0) == 0) floor_b = (double) pages * (double) vm_page_size;
        size_t fr = 0, tot = 0;
        cudaMemGetInfo(&fr, &tot);
        const double gb = 1e9, P = (double) phys;
        double keep = std::max(7.0 * gb, 0.15 * P);
        if (const char* e = std::getenv("STRATA_METAL_KEEP_FREE_GB")) keep = std::atof(e) * gb;
        double share = 0.40;
        if (const char* e = std::getenv("STRATA_METAL_LEAVE_SHARE")) share = std::atof(e);
        double leave = keep;
        if (P >= 64.0 * gb) leave = std::max({leave, share * P, floor_b > 0 ? floor_b + 12.0 * gb : 0.0});
        const double cap = std::min((double) tot, P - leave);
        task_vm_info_data_t ti;
        mach_msg_type_number_t cnt = TASK_VM_INFO_COUNT;
        double foot = 0;
        if (task_info(mach_task_self(), TASK_VM_INFO, (task_info_t) &ti, &cnt) == KERN_SUCCESS) foot = (double) ti.phys_footprint;
        // Other programs' anonymous memory (a browser, another model's server).  The cap above was measured with a small server beside
        // the engine (NEIGHBOUR_ALLOWANCE); with more anonymous memory held elsewhere the same share leaves macOS too little and the Mac
        // pages (a 128 GB M5 Max froze twice with a 60 GB Qwen server running next to this engine).  The rest comes off the experts, so
        // they stream from the SSD a little more.  STRATA_METAL_NEIGHBOURS=0 turns it off.
        double neighbours = 0;
        const char* ne = std::getenv("STRATA_METAL_NEIGHBOURS");
        if (ne == nullptr || std::atoi(ne) != 0) {
            vm_statistics64_data_t vs;
            mach_msg_type_number_t vc = HOST_VM_INFO64_COUNT;
            if (host_statistics64(mach_host_self(), HOST_VM_INFO64, (host_info64_t) &vs, &vc) == KERN_SUCCESS) {
                const double anon = ((double) vs.internal_page_count + (double) vs.total_uncompressed_pages_in_compressor) * (double) vm_page_size;
                constexpr double NEIGHBOUR_ALLOWANCE = 8.0e9;
                neighbours = std::max(0.0, anon - foot - NEIGHBOUR_ALLOWANCE);
                if (neighbours > 0.5e9)
                    std::fprintf(stderr, "ds4: other programs hold %.1f GB of anonymous memory: %.1f GB less for the experts\n", anon / gb, neighbours / gb);
            }
        }
        return std::max(4.0 * gb, cap - foot - 1.0 * gb - neighbours);
    }
#endif
#if defined(STRATA_METAL)
    // Metal (unified memory): a CPU-lane expert's matrices through no-copy buffers over the model's own pages, so the GPU computes it
    // like a VRAM one (no CPU lane, no second pass).  false: not mappable / the cap is reached (the CPU lane has it).
    bool zc_try(Layer& l, int e) {
        static const bool on = std::getenv("DS4_ZC") != nullptr;   // (measured: no faster than the CPU lane - cold pages come from the SSD either way)
        if (!on || l.lay.fmt != gg::kFmtMXFP4 || l.nm != 1 || l.vm.empty()) return false;
        if (l.vm[(size_t) e][0].raw != nullptr) return true;
        uint64_t a[3];
        for (int r = 0; r < 3; ++r) {
            a[r] = ::strata::dsv41::metal_host::zc_map(mx_mat(l, e, r), mx_part_bytes(l, r));
            if (a[r] == 0) return false;
        }
        for (int r = 0; r < 3; ++r) {
            x3::Mat& m = l.vm[(size_t) e][(size_t) r];
            m = x3::Mat{};
            m.K = gg::expert_type(l.lay, r);
            m.fmt = m.K == gg::kTypeMXFP4 ? gg::kFmtMXFP4 : gg::kFmtGG;
            m.raw = (const void*) a[r];
            m.k = r < 2 ? g.dim : g.ff;
            m.n = r < 2 ? g.ff : g.dim;
        }
        return true;
    }
#endif
    void set_vm(Layer& l, int e, int slot) {
        uint8_t* b = l.vram_base + (size_t) slot * l.blob;
        if (l.lay.fmt == gg::kFmtMXFP4) {
            for (int r = 0; r < 3; ++r) {
                x3::Mat& m = l.vm[(size_t) e][(size_t) r];
                m = x3::Mat{};
                m.K = gg::expert_type(l.lay, r);   // (a low-bit type: its GEMV, ds4_iq's)
                m.fmt = m.K == gg::kTypeMXFP4 ? gg::kFmtMXFP4 : gg::kFmtGG;
                m.raw = b + l.lay.trellis[r];
                m.k = r < 2 ? g.dim : g.ff;
                m.n = r < 2 ? g.ff : g.dim;
            }
            return;
        }
        for (int r = 0; r < 3; ++r) {
            x3::Mat& m = l.vm[(size_t) e][(size_t) r];
            m.trellis = (const uint32_t*) (b + l.lay.trellis[r]);
            m.suh = (const uint16_t*) (b + l.lay.suh[r]);
            m.svh = (const uint16_t*) (b + l.lay.svh[r]);
            m.k = r < 2 ? g.dim : g.ff;
            m.n = r < 2 ? g.ff : g.dim;
            m.K = l.lay.K[r];
            m.cb = 2;
            m.ld = 0;
        }
    }
    // an expert's VRAM blob -> its CPU-lane part X, and its NH parts -> the blob (the cache's swaps)
    void blob_to_part(const Layer& l, const uint8_t* blob, int X, uint8_t* dst) const {
        for (int r = 0; r < 3; ++r) {
            const size_t tile = (size_t) 32 * l.lay.K[r];
            const int k = l.hl.k[r], nt = l.hl.n[r] * NH / 16, nth = l.hl.n[r] / 16;
            const uint8_t* tr = blob + l.lay.trellis[r];
            for (int sl = 0; sl < k / 16; ++sl)
                std::memcpy(dst + l.hl.trellis[r] + (size_t) sl * nth * tile, tr + ((size_t) sl * nt + (size_t) X * nth) * tile,
                            (size_t) nth * tile);
            std::memcpy(dst + l.hl.suh[r], blob + l.lay.suh[r], (size_t) k * 2);
            std::memcpy(dst + l.hl.svh[r], blob + l.lay.svh[r] + (size_t) X * l.hl.n[r] * 2, (size_t) l.hl.n[r] * 2);
        }
    }
    void parts_to_blob(const Layer& l, const std::array<uint8_t*, 4>& parts, uint8_t* blob) const {
        for (int r = 0; r < 3; ++r) {
            const size_t tile = (size_t) 32 * l.lay.K[r];
            const int k = l.hl.k[r], nt = l.hl.n[r] * NH / 16, nth = l.hl.n[r] / 16;
            uint8_t* tr = blob + l.lay.trellis[r];
            for (int X = 0; X < NH; ++X)
                for (int sl = 0; sl < k / 16; ++sl)
                    std::memcpy(tr + ((size_t) sl * nt + (size_t) X * nth) * tile,
                                parts[(size_t) X] + l.hl.trellis[r] + (size_t) sl * nth * tile, (size_t) nth * tile);
            std::memcpy(blob + l.lay.suh[r], parts[0] + l.hl.suh[r], (size_t) k * 2);
            for (int X = 0; X < NH; ++X)
                std::memcpy(blob + l.lay.svh[r] + (size_t) X * l.hl.n[r] * 2, parts[(size_t) X] + l.hl.svh[r],
                            (size_t) l.hl.n[r] * 2);
        }
    }

    // an expert's blob -> member m's part (gate / up columns [ff0, ff0 + ffn), down rows of the same), and back
    void blob_to_half(const Layer& l, const uint8_t* blob, int m, uint8_t* dst) const {
        if (l.lay.fmt == gg::kFmtMXFP4) return mx_blob_to_half(l, blob, m, dst);
        const Layer& x = member(l, m);
        const int f0 = x.ff0, fn = x.ffn;
        for (int r = 0; r < 2; ++r) {
            const size_t tile = (size_t) 32 * l.lay.K[r], nt = (size_t) g.ff / 16, nth = (size_t) fn / 16;
            for (size_t sl = 0; sl < (size_t) g.dim / 16; ++sl)
                std::memcpy(dst + x.hlay.trellis[r] + sl * nth * tile,
                            blob + l.lay.trellis[r] + (sl * nt + (size_t) f0 / 16) * tile, nth * tile);
            std::memcpy(dst + x.hlay.suh[r], blob + l.lay.suh[r], (size_t) g.dim * 2);
            std::memcpy(dst + x.hlay.svh[r], blob + l.lay.svh[r] + (size_t) f0 * 2, (size_t) fn * 2);
        }
        const size_t row = (size_t) (g.dim / 16) * 32 * l.lay.K[2];
        std::memcpy(dst + x.hlay.trellis[2], blob + l.lay.trellis[2] + (size_t) (f0 / 16) * row, (size_t) (fn / 16) * row);
        std::memcpy(dst + x.hlay.suh[2], blob + l.lay.suh[2] + (size_t) f0 * 2, (size_t) fn * 2);
        std::memcpy(dst + x.hlay.svh[2], blob + l.lay.svh[2], (size_t) g.dim * 2);
    }
    void half_to_blob(const Layer& l, const uint8_t* src, int m, uint8_t* blob) const {
        if (l.lay.fmt == gg::kFmtMXFP4) return mx_half_to_blob(l, src, m, blob);
        const Layer& x = member(l, m);
        const int f0 = x.ff0, fn = x.ffn;
        for (int r = 0; r < 2; ++r) {
            const size_t tile = (size_t) 32 * l.lay.K[r], nt = (size_t) g.ff / 16, nth = (size_t) fn / 16;
            for (size_t sl = 0; sl < (size_t) g.dim / 16; ++sl)
                std::memcpy(blob + l.lay.trellis[r] + (sl * nt + (size_t) f0 / 16) * tile,
                            src + x.hlay.trellis[r] + sl * nth * tile, nth * tile);
            if (m == 0) std::memcpy(blob + l.lay.suh[r], src + x.hlay.suh[r], (size_t) g.dim * 2);
            std::memcpy(blob + l.lay.svh[r] + (size_t) f0 * 2, src + x.hlay.svh[r], (size_t) fn * 2);
        }
        const size_t row = (size_t) (g.dim / 16) * 32 * l.lay.K[2];
        std::memcpy(blob + l.lay.trellis[2] + (size_t) (f0 / 16) * row, src + x.hlay.trellis[2], (size_t) (fn / 16) * row);
        std::memcpy(blob + l.lay.suh[2] + (size_t) f0 * 2, src + x.hlay.suh[2], (size_t) fn * 2);
        if (m == 0) std::memcpy(blob + l.lay.svh[2], src + x.hlay.svh[2], (size_t) g.dim * 2);
    }

    // tp4 (Project Maya's trim_to_fit, e3f2475 #408, MIT): a group's members' exact expert bytes against each one's
    // own room: a member holds its own part (unit(member)) of each slot of the group's split layers and the whole slots
    // of the group's one-device layers it holds (the drafter's, on the lead); trimmed a slot at a time - a split
    // layer's, the one with the most; the drafter's only when none is left - until each fits; false (err) when one cannot
    bool trim_to_fit(int gi, const std::vector<double>& own, std::string& err) {
        const size_t nm = groups[(size_t) gi].mem.size();
        for (size_t mi = 0; mi < nm; ++mi) {
            const int dv = groups[(size_t) gi].mem[mi];
            auto bytes_of = [&](const Layer& l) -> double {   // (this member's bytes a slot of l: 0 if it holds none)
                if (l.grp != gi) return 0.0;
                if ((size_t) l.nm == nm) return (double) unit(member(l, (int) mi));
                return l.nm == 1 && l.dev == dv ? (double) l.blob : 0.0;
            };
            double b = 0;
            for (const Layer& l : L) b += bytes_of(l) * l.n_vram;
            int trimmed = 0;
            while (b > own[mi]) {
                Layer* pick = nullptr;
                for (Layer& l : L)
                    if (bytes_of(l) > 0 && l.n_vram > 0 &&
                        (pick == nullptr || ((size_t) pick->nm != nm && (size_t) l.nm == nm) ||
                         (((size_t) pick->nm == nm) == ((size_t) l.nm == nm) && l.n_vram > pick->n_vram)))
                        pick = &l;
                if (pick == nullptr) {
                    err = "the experts' VRAM: member " + std::to_string(mi) + " of group " + std::to_string(gi) +
                          " (CUDA" + std::to_string(devs[(size_t) dv].id) + ") has no room for its parts";
                    return false;
                }
                --pick->n_vram;   // (every member gives up its part of that slot: the ones before only fit better)
                b -= bytes_of(*pick);
                ++trimmed;
            }
            if (trimmed > 0)
                std::fprintf(stderr, "ds4: CUDA%d: %d expert slots fewer, its own parts' bytes (%.2f GB) in its room "
                                     "(%.2f GB) (uneven tensor-parallel split)\n", devs[(size_t) dv].id, trimmed, b / 1e9,
                             own[mi] / 1e9);
        }
        return true;
    }

    // tp4: DS4_TP_CHECK=1 - at load, before any request, every split GGUF layer's member parts byte for byte (after
    // Project Maya's MAYA_DS4_TP_CHECK, e3f2475 #408, MIT; Maya's also runs a token through the parts - that numeric half
    // is the quality gate's here, docs/dsv41/cards/TP-05.md):
    //  - the members' ranges tile [0, n_ff) in member order, in whole blocks (tp_blk where uneven), each member's
    //    layout holds its part, and (uneven) its shared expert's part is its range;
    //  - for a layer's first VRAM expert and its first CPU-lane one: each member's part (mx_blob_to_half) put back
    //    (mx_half_to_blob) is the file's blob; read_mx_member's part is the same bytes; the VRAM expert's slot on every
    //    member holds them; stream_expert's copy from a whole blob and (where the layer takes it) stream_member_direct's
    //    copy put the same bytes in a device buffer.
    // Any difference, a failed read or a CUDA error fails the start.  Only the matrices' bytes are compared (a slot's
    // alignment padding is not the model's)
    bool tp_check(std::string& err) {
        const double t0 = now_ms();
        size_t n_parts = 0, n_vram = 0, n_stream = 0, n_direct = 0;
        const int tpd = tp_direct_mode();
        for (const Layer& l : L) {
            if (l.nm < 2 || l.lay.fmt != gg::kFmtMXFP4) continue;
            const std::string at = "DS4_TP_CHECK: layer " + std::to_string(l.il) + ": ";
            const int t2 = gg::expert_type(l.lay, 2), bk = std::max(1, gg::type_block(t2));
            int f = 0;
            for (int m = 0; m < l.nm; ++m) {
                const Layer& x = member(l, m);
                const MxCut k = mx_cut(l, m);
                const bool rng = x.ff0 == f && x.ffn > 0 && x.ffn % bk == 0 && (!tp_uneven || x.ffn % tp_blk == 0);
                const bool lay = x.hlay.trellis[1] >= x.hlay.trellis[0] + (size_t) x.ffn * k.gr[0] &&
                                 x.hlay.trellis[2] >= x.hlay.trellis[1] + (size_t) x.ffn * k.gr[1] &&
                                 x.hblob >= x.hlay.trellis[2] + (size_t) g.dim * k.dh;
                const bool shr = !tp_uneven || (x.s1.n == x.ffn && x.s3.n == x.ffn && x.s2.k == x.ffn);
                if (!rng || !lay || !shr) {
                    err = at + "member " + std::to_string(m) + " [" + std::to_string(x.ff0) + ", " +
                          std::to_string(x.ff0 + x.ffn) + "): " + (!rng ? "not the next whole blocks of n_ff" :
                          !lay ? "its layout does not hold its part" : "its shared expert's part is not its range");
                    return false;
                }
                f += x.ffn;
            }
            if (f != g.ff) {
                err = at + "the members' ranges end at " + std::to_string(f) + ", not n_ff " + std::to_string(g.ff);
                return false;
            }
            std::vector<int> es;   // (the first VRAM expert, the first CPU-lane one)
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] >= 0) { es.push_back(e); break; }
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] < 0) { es.push_back(e); break; }
            std::vector<uint8_t> blob(l.blob), back(l.blob, 0), want(l.blob), got(l.blob), stg(l.blob);
            uint8_t* hb = nullptr;   // (the whole blob in pinned memory: stream_expert's source)
            if (cudaHostAlloc((void**) &hb, l.blob, cudaHostAllocPortable) != cudaSuccess) {
                err = at + "cudaHostAlloc of a blob failed";
                return false;
            }
            struct HostFree { uint8_t* p; ~HostFree() { cudaFreeHost(p); } } hf{hb};
            for (int e : es) {
                const std::string ate = at + "expert " + std::to_string(e) + ": ";
                if (!read_mx_file(l, e, blob.data())) {
                    err = ate + "the file's read failed";
                    return false;
                }
                std::memcpy(hb, blob.data(), l.blob);
                std::fill(back.begin(), back.end(), 0);
                for (int m = 0; m < l.nm; ++m) {
                    const Layer& x = member(l, m);
                    const MxCut k = mx_cut(l, m);
                    const size_t u = unit(x);
                    auto same = [&](const uint8_t* a, const uint8_t* b) {   // (the part's three matrices)
                        for (int r = 0; r < 3; ++r) {
                            const size_t n = r < 2 ? (size_t) k.ffn * k.gr[r] : (size_t) g.dim * k.dh;
                            if (std::memcmp(a + x.hlay.trellis[r], b + x.hlay.trellis[r], n) != 0) return false;
                        }
                        return true;
                    };
                    const std::string atm = ate + "member " + std::to_string(m) + ": ";
                    std::fill(want.begin(), want.end(), 0);
                    mx_blob_to_half(l, blob.data(), m, want.data());
                    mx_half_to_blob(l, want.data(), m, back.data());
                    std::fill(got.begin(), got.end(), 0);
                    if (!read_mx_member(l, e, m, got.data()) || !same(want.data(), got.data())) {
                        err = atm + "read_mx_member's part differs from the blob's";
                        return false;
                    }
                    ++n_parts;
                    cudaSetDevice(devs[(size_t) x.dev].id);
                    if (l.slot[(size_t) e] >= 0) {   // (its VRAM slot)
                        if (cudaMemcpy(got.data(), x.vram_base + (size_t) l.slot[(size_t) e] * u, u,
                                       cudaMemcpyDeviceToHost) != cudaSuccess || !same(want.data(), got.data())) {
                            err = atm + "its VRAM slot differs from the blob's part";
                            return false;
                        }
                        ++n_vram;
                    }
                    uint8_t* db = nullptr;
                    cudaStream_t st = nullptr;
                    if (cudaMalloc((void**) &db, u) != cudaSuccess ||
                        cudaStreamCreateWithFlags(&st, cudaStreamNonBlocking) != cudaSuccess) {
                        if (db != nullptr) cudaFree(db);
                        err = atm + "a device buffer of " + std::to_string(u) + " bytes";
                        return false;
                    }
                    bool ok = stream_expert(l, m, e, db, st, err, hb, false) && cudaStreamSynchronize(st) == cudaSuccess &&
                              cudaMemcpy(got.data(), db, u, cudaMemcpyDeviceToHost) == cudaSuccess && same(want.data(), got.data());
                    if (ok) ++n_stream;
                    else if (err.empty()) err = atm + "stream_expert's copy differs from the blob's part";
                    if (ok && tpd > 0 && tp_direct_ok(l, e)) {   // (the prompt path's DS4_TP_DIRECT copy)
                        if (tpd == 1) {
                            std::fill(stg.begin(), stg.end(), 0);
                            read_mx_member_down(l, e, m, stg.data());
                        }
                        ok = cudaMemsetAsync(db, 0, u, st) == cudaSuccess &&
                             stream_member_direct(l, m, e, db, st, tpd, tpd == 1 ? stg.data() : nullptr, err) &&
                             cudaStreamSynchronize(st) == cudaSuccess &&
                             cudaMemcpy(got.data(), db, u, cudaMemcpyDeviceToHost) == cudaSuccess && same(want.data(), got.data());
                        if (ok) ++n_direct;
                        else if (err.empty()) err = atm + "stream_member_direct's copy (DS4_TP_DIRECT " + std::to_string(tpd) +
                                                    ") differs from the blob's part";
                    }
                    cudaStreamDestroy(st);
                    cudaFree(db);
                    if (!ok) {
                        const cudaError_t ce = cudaGetLastError();
                        if (ce != cudaSuccess) err += std::string(" (") + cudaGetErrorString(ce) + ")";
                        return false;
                    }
                }
                for (int r = 0; r < 3; ++r)
                    if (std::memcmp(back.data() + l.lay.trellis[r], blob.data() + l.lay.trellis[r], mx_part_bytes(l, r)) != 0) {
                        err = ate + "the members' parts put back are not the blob (matrix " + std::to_string(r) + ")";
                        return false;
                    }
            }
        }
        std::fprintf(stderr, "ds4: DS4_TP_CHECK: %zu member parts, %zu VRAM slots, %zu streamed and %zu direct copies the "
                             "file's bytes (%s split, %.1f s)\n", n_parts, n_vram, n_stream, n_direct,
                     tp_uneven ? "uneven" : "even", (now_ms() - t0) / 1000.0);
        return true;
    }

    bool place_experts(std::string& err) {
        // (Windows, an integrated GPU: what its experts may commit - commit_room - and what that kept off the GPU)
        double room = 1e300, kept = 0;
        for (const Dev& d : devs)
            if (commit_charged(d)) room = commit_room();
        const double room0 = room;
        // per group: what its tightest member has left (each member holds its part of every VRAM expert of the
        // group's layers, its unit bytes a slot - counted at the members' mean: an uneven split's odd blocks go round
        // the members layer by layer, so each member's total comes to about the mean's)
        auto ucount = [](const Layer& l) {
            double s = 0;
            for (int m = 0; m < l.nm; ++m) s += (double) unit(member(l, m));
            return s / l.nm;
        };
        // The drafter's blocks live on their group's lead alone (nm 1), so their experts are charged to that card only:
        // each member keeps its own budget, the drafter takes the lead's, and the trunk (whose every VRAM expert is
        // split over all members) gets the tightest member's remainder.  DS4_DRAFT_BUDGET_SHARED=1: the old charge, the
        // drafter's bytes taken from the group's one shared per-member budget (every member gives them up).
        static const bool draft_shared = [] {
            const char* v = std::getenv("DS4_DRAFT_BUDGET_SHARED");
            return v != nullptr && *v != '\0' && *v != '0';
        }();
        for (size_t gi = 0; gi < groups.size(); ++gi) {
            double budget = 1e300;
            bool charged = false;
            std::vector<double> bm;   // (each member's own budget, in groups[gi].mem order)
            for (int m : groups[gi].mem) {
                cudaSetDevice(devs[(size_t) m].id);
                size_t fr = 0, tot = 0;
                CK(cudaMemGetInfo(&fr, &tot));
                fr = uma_free(devs[(size_t) m].id, fr);
                // (an integrated GPU, Windows: its memory is the system's.  What it allocates after the experts - the long
                // prompt's buffers, the GEMM workspaces - spills into RAM when the experts took every byte of the GPU's
                // address space, and on a 32K prompt that ran the machine out of RAM.  So the experts leave room for them,
                // growing with the context.  DS4_UMA_GPU_RESERVE_GB: that room, tests)
                double uma_extra = 0.0;
                if (commit_charged(devs[(size_t) m])) {
                    uma_extra = (4.0 + 2.0e-4 * std::max(0.0, (double) o.max_context - 16384.0)) * (double) (1ull << 30);
                    if (const char* v = std::getenv("DS4_UMA_GPU_RESERVE_GB")) uma_extra = std::atof(v) * (double) (1ull << 30);
                }
                double b_m = std::max(0.0, ((double) fr - (double) ((size_t) o.reserve_mib << 20) - uma_extra)) * o.vram_experts;
#if defined(STRATA_METAL)
                if (o.vram_experts_auto && std::getenv("DS4_NO_AUTO_VX") == nullptr) {
                    const double cap = metal_expert_cap();
                    if (cap < b_m) {
                        std::fprintf(stderr, "ds4: expert share: %.1f GB of VRAM experts (the RAM cap leaves %.1f GB; --vram-experts sets it)\n",
                                     cap / 1e9, cap / 1e9);
                        b_m = cap;
                    }
                }
#endif
                bm.push_back(b_m);
                budget = std::min(budget, b_m);
                charged = charged || commit_charged(devs[(size_t) m]);
            }
            if (charged && room < 1e300) {   // (each member's slots charged: the group's share of the room)
                double all = 0;
                for (const Layer& l : L)
                    if (l.grp == (int) gi) all += (double) unit(l) * l.n_exp;
                const double nm = (double) groups[gi].mem.size(), capped = std::min(budget, room / nm);
                kept += std::max(0.0, std::min(budget, all) - std::min(capped, all)) * nm;
                budget = capped;
                room = std::max(0.0, room - std::min(budget, all) * nm);
            }
            // (tp4: each member's own room, this snapshot, before the drafter's charge - trim_to_fit's)
            std::vector<double> own = bm;
            if (charged && room0 < 1e300)
                for (double& v : own) v = std::min(v, budget);
            double budget_t = budget;   // the drafter's experts first, all of them (every draft uses its blocks)
            bool per_card = false;
            bool dr_split = false;   // (DS4_DRAFT_TP: the drafter's blocks over the group - every member holds its part
                                     // of each of their experts, so the one per-member budget is the right charge)
            for (const Layer& l : L) dr_split = dr_split || (l.grp == (int) gi && l.mtp && l.nm > 1);
            if (draft_shared || groups[gi].mem.size() < 2 || dr_split) {
                double dr = 0;
                for (Layer& l : L)
                    if (l.grp == (int) gi && l.mtp) {
                        l.n_vram = std::min(dcap(l), (int) std::floor(budget_t / (double) ucount(l)));   // (dcap: DS4_DRAFT_KEEP / _EXPERTS)
                        budget_t -= (double) l.n_vram * ucount(l);
                        dr += (double) l.n_vram * ucount(l);
                    }
                if (dr_split)
                    std::fprintf(stderr, "ds4: drafter experts split over the group's %zu members (DS4_DRAFT_TP=0: on the "
                                         "lead alone): %.2f GB a member; trunk room per member %.2f GB\n",
                                 groups[gi].mem.size(), dr / 1e9, std::max(0.0, budget_t) / 1e9);
            } else {   // per card: a drafter block's experts from the budget of the member that holds them (its l.dev)
                if (charged)   // (the commit's cap above applies to every member; otherwise each keeps its own room)
                    for (double& b : bm) b = std::min(b, budget);
                double dr = 0;
                int ddev = groups[gi].mem[0];
                for (Layer& l : L)
                    if (l.grp == (int) gi && l.mtp) {
                        ddev = l.dev;
                        size_t k = 0;
                        while (k < groups[gi].mem.size() && groups[gi].mem[k] != l.dev) ++k;
                        if (k == groups[gi].mem.size()) k = 0;
                        l.n_vram = std::min(dcap(l), (int) std::floor(bm[k] / (double) ucount(l)));   // (dcap)
                        bm[k] -= (double) l.n_vram * ucount(l);
                        dr += (double) l.n_vram * ucount(l);
                    }
                if (dr > 0) {
                    per_card = true;
                    budget_t = *std::min_element(bm.begin(), bm.end());
                    std::string s;
                    for (size_t k = 0; k < bm.size(); ++k)
                        s += (k ? " / " : "") + std::to_string((int) std::lround(bm[k] / 1e6)) + " MB";
                    std::fprintf(stderr, "ds4: drafter experts (%.2f GB) charged to CUDA%d alone (per-card budget; "
                                         "DS4_DRAFT_BUDGET_SHARED=1: the old shared charge): trunk room per member %s, the "
                                         "tightest %.2f GB (shared charge: %.2f GB)\n",
                                 dr / 1e9, devs[(size_t) ddev].id, s.c_str(), budget_t / 1e9,
                                 std::max(0.0, budget - dr) / 1e9);
                    budget = budget_t;   // (the trunk's ceiling below: what its tightest member has left)
                }
            }
            double want = 0;
            for (const Layer& l : L)
                if (l.grp == (int) gi && !l.mtp && !l.cpu_only) want += (double) ucount(l) * l.n_exp;
            const double frac = want > 0 ? std::min(1.0, std::max(0.0, budget_t) / want) : 0.0;
            for (Layer& l : L) {
                if (l.grp != (int) gi || l.mtp) continue;
                if (l.cpu_only) {   // (its type has no device kernel: the CPU lane reads every expert of it)
                    l.n_vram = 0;
                    continue;
                }
                l.n_vram = std::min(l.n_exp, (int) std::floor(frac * l.n_exp));
                // never more than fits: the floor of each layer's share can still round up the total
                while (l.n_vram > 0 && (double) ucount(l) * l.n_vram > budget) --l.n_vram;
            }
            double used = 0;   // (per card: the trunk's own, against the trunk's ceiling; the drafter's are on the lead's)
            for (Layer& l : L)
                if (l.grp == (int) gi && !(per_card && l.mtp)) used += (double) ucount(l) * l.n_vram;
            // what the floors left: whole experts, layer by layer
            for (Layer& l : L) {
                if (l.grp != (int) gi || l.cpu_only || (per_card && l.mtp)) continue;
                while (l.n_vram < dcap(l) && used + (double) ucount(l) <= budget) {   // (dcap: n_exp for the trunk)
                    ++l.n_vram;
                    used += (double) ucount(l);
                }
            }
            // (tp4: the mean above only proposed - with an uneven split each member's exact bytes, its own part of
            //  every slot, against its own room from the same snapshot; over it, a slot fewer at a time till it fits)
            if (tp_uneven && groups[gi].mem.size() > 1 && !trim_to_fit((int) gi, own, err)) return false;
        }
        if (kept > 0) {   // the commit kept experts off the GPU: say so, and the page file that keeps them on it
            const os::Commit c = os::commit();
            const double gib = (double) (1ull << 30);
            const double pf = c.limit != ~uint64_t{0} && c.ram != ~uint64_t{0} && c.limit > c.ram ? (double) (c.limit - c.ram) : 0.0;
            commit_kept = kept;
            pagefile_hint = std::ceil((pf + kept) / gib);
            std::fprintf(stderr,
                         "ds4: WARNING: %.1f GB of experts stay off the GPU - Windows charges the GPU's memory to its "
                         "commit (RAM + page file) and can commit only %.1f GB more for them (%.0f GB kept for the "
                         "other programs). A page file of %.0f GB (%.0f MB; now %.0f GB) keeps them on the GPU: System "
                         "> About > Advanced system settings > Performance > Advanced > Virtual memory, then restart\n",
                         kept / 1e9, room0 / 1e9, commit_margin() / 1e9, pagefile_hint, pagefile_hint * 1024.0, pf / gib);
        } else if (room0 < 1e300 && o.verbose) {
            std::fprintf(stderr, "ds4: Windows' commit has room for the GPU's experts (%.1f GB beside %.0f GB for the other "
                                 "programs)\n", room0 / 1e9, commit_margin() / 1e9);
        }
        for (Layer& l : L) {
            // the hottest experts of the profile first, then by index
            std::vector<int> order((size_t) l.n_exp);
            std::iota(order.begin(), order.end(), 0);
            const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
            std::stable_sort(order.begin(), order.end(), [&](int a, int b) { return p[a] > p[b]; });
            if (l.mtp && !l.dkeep.empty())   // DS4_DRAFT_KEEP: the kept experts take the slots, most picked first
                std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
                    if (l.dkeep[(size_t) a] != l.dkeep[(size_t) b]) return l.dkeep[(size_t) a] > l.dkeep[(size_t) b];
                    return l.dcnt[(size_t) a] > l.dcnt[(size_t) b];
                });
            l.slot.assign((size_t) l.n_exp, -1);
            l.host.assign((size_t) l.n_exp, nullptr);
            // a layer with experts on both sides keeps one VRAM slot free for the cache's swaps
            l.n_slots = std::min(l.n_vram, l.n_exp);
            if (o.expert_cache && l.n_slots >= 2 && l.n_slots < l.n_exp && !(l.mtp && draft_mod())) {   // (the cache skips the drafter: no spare for it)   // (every expert fits: nothing to swap)
                l.n_vram = l.n_slots - 1;
                l.spare_vram = l.n_slots - 1;
            } else {
                l.n_vram = l.n_slots;
                l.spare_vram = -1;
            }
            for (int i = 0; i < l.n_vram; ++i) l.slot[(size_t) order[(size_t) i]] = i;
            for (int m = 0; m < l.nm && l.n_slots > 0; ++m) {
                Layer& x = member(l, m);
                Dev& d = devs[(size_t) x.dev];
                cudaSetDevice(d.id);
                void* v = nullptr;
                if (cudaMalloc(&v, (size_t) l.n_slots * unit(x)) != cudaSuccess) {
                    err = "cudaMalloc of layer " + std::to_string(l.il) + "'s " + std::to_string(l.n_slots) +
                          " experts on CUDA" + std::to_string(d.id) + " failed";
                    return false;
                }
                d.allocs.push_back(v);
                d.experts += (size_t) l.n_slots * unit(x);
                x.vram_base = (uint8_t*) v;
            }
            l.heat.assign((size_t) l.n_exp, 0.0f);
            {   // the profile as the starting heat: its counts scaled to ~512 hits a layer
                double sum = 0;
                for (int e = 0; e < l.n_exp; ++e) sum += p[e];
                const double sc = sum > 0 ? 512.0 / sum : 0.0;
                for (int e = 0; e < l.n_exp; ++e) l.heat[(size_t) e] = (float) (p[e] * sc);
            }
            const int n_host = l.n_exp - l.n_vram;
            {   // the CPU lane's parts of an expert (in place: the whole expert, its pieces where the file has them)
                size_t off = 0;
                for (int r = 0; r < 3; ++r) {
                    const int k = r < 2 ? g.dim : g.ff, nf = r < 2 ? g.ff : g.dim, n = nf / NH;
                    l.hl.k[r] = k;
                    l.hl.n[r] = n;
                    l.hl.trellis[r] = file_experts ? l.piece_src[r][0] : off;
                    off += align256((size_t) (k / 16) * (n / 16) * 32 * l.lay.K[r]);
                    l.hl.suh[r] = file_experts ? l.piece_src[r][1] : off;
                    off += align256((size_t) k * 2);
                    l.hl.svh[r] = file_experts ? l.piece_src[r][2] : off;
                    off += align256((size_t) n * 2);
                }
                l.hl.bytes = off;
            }
            l.hh.assign((size_t) l.n_exp, {nullptr, nullptr, nullptr, nullptr});
            if (l.lay.fmt == gg::kFmtMXFP4) {   // a GGUF's: read in place from the file's mapping
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) l.host[(size_t) e] = (uint8_t*) mx_mat(l, e, 0);
            } else if (file_experts) {   // every expert's file mapped (the cache's swaps hand VRAM experts back to the files)
                for (int e = 0; e < l.n_exp; ++e)
                    if (pk.map(l.region_file[(size_t) e]) == nullptr) {
                        err = "mapping " + pk.files[(size_t) l.region_file[(size_t) e]] + " failed";
                        return false;
                    }
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) {
                        l.hh[(size_t) e][0] = file_part(l, e);
                        l.host[(size_t) e] = l.hh[(size_t) e][0];
                    }
            } else if (n_host > 0) {
                const int n_parts = n_host + (l.spare_vram >= 0 ? 1 : 0);   // (+ the cache's spare)
                const size_t bytes = (size_t) n_parts * l.hl.bytes;
                for (int X = 0; X < NH; ++X) {
                    void* m = node_map(bytes, X, NH);
                    if (m == nullptr) {
                        err = "host memory for layer " + std::to_string(l.il) + "'s " + std::to_string(n_host) +
                              " CPU experts (" + std::to_string(bytes >> 20) + " MiB on node " + std::to_string(X) + ")";
                        return false;
                    }
                    host_maps.emplace_back(m, bytes);
                    int hi = 0;
                    for (int e = 0; e < l.n_exp; ++e)
                        if (l.slot[(size_t) e] < 0) l.hh[(size_t) e][(size_t) X] = (uint8_t*) m + (size_t) (hi++) * l.hl.bytes;
                    if (l.spare_vram >= 0) {
                        l.spare_host[(size_t) X] = (uint8_t*) m + (size_t) hi * l.hl.bytes;
                        if (prefault_spares()) os::prefault_write(l.spare_host[(size_t) X], l.hl.bytes);   // (see copy_experts)
                    }
                }
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) l.host[(size_t) e] = l.hh[(size_t) e][0];
            }
            l.vm.assign((size_t) l.n_exp, {});
            if (l.nm == 1)   // (the host-routed window path's views: a group's members take the device-routed path)
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] >= 0) set_vm(l, e, l.slot[(size_t) e]);
            if (!halloc(l.tab_pin, (size_t) 2 * l.nm, err)) return false;
            for (int m = 0; m < l.nm; ++m) {
                Layer& x = member(l, m);
                std::vector<unsigned long long> tab((size_t) l.n_exp, 0ull);
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] >= 0)
                        tab[(size_t) e] = (unsigned long long) (x.vram_base + (size_t) l.slot[(size_t) e] * unit(x));
                cudaSetDevice(devs[(size_t) x.dev].id);
                CK(cudaMemcpy(x.vram_tab, tab.data(), tab.size() * 8, cudaMemcpyHostToDevice));
            }
        }
        return true;
    }

    // DS4_HELPER_DD: refuse the modes it does not combine with, open the helpers' device-direct windows, and give every
    // device its join's views (the helpers' fine-grained host blocks as that device sees them) and its own part / flag
    // DS4_LP_JOINCOMB: dd_join_k's launch arguments (ffn()'s) as gguf's join + combine takes them
    gg::DdJoinArgs lp_join_args(const Layer& l, int slot, unsigned sq, int T) const {
        static_assert(kDdMaxH == 8 && kPicks == 8, "gg::DdJoinArgs mirrors DdJoin (8 helpers) and plans 8 picks a row");
        const DdJoin& dj = dd_j[(size_t) l.dev];
        const Dev& d = devs[(size_t) l.dev];
        gg::DdJoinArgs a;
        for (int k = 0; k < kDdMaxH; ++k) {
            a.seq[k] = dj.seq[k];
            a.has[k] = dj.has[k];
            a.out[k] = dj.out[k];
        }
        a.nh = dj.nh;
        a.own = dj.own;
        a.nexp = dj.nexp;
        a.cnt = dj.cnt;
        a.rseq = (const unsigned*) &resps[slot].seq;
        a.want = sq;
        a.lane_part = (const float*) &resps[slot].part[0][0];
        a.lane_stride = (size_t) kMaxDim;
        a.lane_flag = (const int*) resps[slot].cpu;
        a.ridx = (const int*) d.ridx;
        a.il = l.il;
        a.kexp = l.k_exp;
        a.part = dd_part[(size_t) l.dev];
        a.flag = dd_flag[(size_t) l.dev];
        a.vmask = ecown ? (const unsigned*) reqs[slot].vmask : nullptr;   // DS4_ECOWN (the lead's request)
        (void) T;
        return a;
    }
    bool dd_setup(std::string& err) {
        const char* why = hlp.pool_client() ? "a pool client" : std::getenv("STRATA_POOL_SERVE") ? "STRATA_POOL_SERVE" : helper_defer ? "DS4_HELPER_DEFER"
                          : hlp.armed_on() ? "DS4_HELPER_ARMED" : hlp.size() > (size_t) kDdMaxH ? "more than 8 helpers"
                          : nullptr;
#if !defined(STRATA_USE_HIP)
        why = "a non-HIP build";
#endif
        if (why != nullptr) {
            std::fprintf(stderr, "helper: DS4_HELPER_DD=1 is off: not with %s\n", why);
            return true;
        }
        std::string e2;
        if (!hlp.dd_open(reqs, [&](int li, int e) {
                const Layer& x = L[(size_t) li];
                return x.slot[(size_t) e] >= 0 || (!x.dkeep.empty() && !x.dkeep[(size_t) e]);
            }, e2)) {
            err = "DS4_HELPER_DD: " + e2;
            return false;
        }
#if defined(STRATA_USE_HIP)
        const std::vector<helper::Helper::DdView> v = hlp.dd_views();
        dd_j.assign(devs.size(), DdJoin{});
        dd_part.assign(devs.size(), nullptr);
        dd_flag.assign(devs.size(), nullptr);
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            cudaSetDevice(d.id);
            DdJoin& j = dd_j[di];
            j.nh = (int) v.size();
            for (size_t k = 0; k < v.size(); ++k)
                if (hipHostGetDevicePointer((void**) &j.seq[k], (void*) v[k].seq, 0) != hipSuccess ||
                    hipHostGetDevicePointer((void**) &j.has[k], (void*) v[k].has, 0) != hipSuccess ||
                    hipHostGetDevicePointer((void**) &j.out[k], (void*) v[k].out, 0) != hipSuccess) {
                    err = "DS4_HELPER_DD: the helpers' host blocks on device " + std::to_string(d.id);
                    return false;
                }
            if (!dalloc(d, dd_part[di], (size_t) kWin * g.dim, err) || !dalloc(d, dd_flag[di], (size_t) kWin, err)) return false;
        }
        // DS4_HELPER_DD_SKIP=1: the heads' owner table on every device (the lead's join reads its own), and the counters
        dd_skip = std::getenv("DS4_HELPER_DD_SKIP") != nullptr && std::atoi(std::getenv("DS4_HELPER_DD_SKIP")) == 1;
        if (dd_skip) {
            int nexp = 0;
            for (const Layer& x : L) nexp = std::max(nexp, x.n_exp);
            const std::vector<int8_t> ot = hlp.dd_owner_table((int) L.size(), nexp);
            int64_t owned = 0;
            for (int8_t o : ot) owned += o >= 0;
            dd_own.assign(devs.size(), nullptr);
            dd_cnt.assign(devs.size(), nullptr);
            for (size_t di = 0; di < devs.size(); ++di) {
                Dev& d = devs[di];
                cudaSetDevice(d.id);
                if (cudaMalloc((void**) &dd_own[di], ot.size()) != cudaSuccess ||
                    cudaMemcpy(dd_own[di], ot.data(), ot.size(), cudaMemcpyHostToDevice) != cudaSuccess ||
                    cudaMalloc((void**) &dd_cnt[di], 2 * sizeof(unsigned long long)) != cudaSuccess ||
                    cudaMemset(dd_cnt[di], 0, 2 * sizeof(unsigned long long)) != cudaSuccess) {
                    cudaGetLastError();
                    err = "DS4_HELPER_DD_SKIP: the owner table on device " + std::to_string(d.id);
                    return false;
                }
                dd_j[di].own = dd_own[di];
                dd_j[di].nexp = nexp;
                dd_j[di].cnt = dd_cnt[di];
            }
            std::fprintf(stderr, "helper: DS4_HELPER_DD_SKIP: the lead waits only for the helpers with a pick in the request (%lld experts in the "
                                 "owner table, %d layers x %d)\n", (long long) owned, (int) L.size(), nexp);
        }
        dd_live = true;
        std::fprintf(stderr, "helper: DS4_HELPER_DD: trunk layers 1 .. %d device-direct on %zu helpers (windows of up to %d rows)\n", g.nl - 1,
                     hlp.size(), dd_maxt);
        if (std::getenv("DS4_DD_AUDIT") != nullptr && std::atoi(std::getenv("DS4_DD_AUDIT")) == 1) {   // DS4_DD_AUDIT (see dd_audit)
            int nexp = 0;
            for (const Layer& x : L) nexp = std::max(nexp, x.n_exp);
            dd_aud_own = hlp.dd_owner_table((int) L.size(), nexp);
            dd_aud_nexp = nexp;
            dd_aud_layer.reset(new std::atomic<long long>[L.size()]);
            for (size_t li = 0; li < L.size(); ++li) dd_aud_layer[li].store(0);
            int64_t owned = 0, both = 0;
            for (size_t li = 0; li < L.size(); ++li)
                for (int e = 0; e < L[li].n_exp; ++e) {
                    const int8_t o = dd_aud_own[li * (size_t) nexp + (size_t) e];
                    owned += o >= 0;
                    both += o >= 0 && L[li].slot[(size_t) e] >= 0;
                }
            dd_audit = true;
            std::fprintf(stderr, "ds4: DS4_DD_AUDIT=1: counting device-direct picks computed twice (VRAM and a helper's owner table): %lld "
                                 "experts in the tables, %lld of them in VRAM at load\n", (long long) owned, (long long) both);
            if (ecown) {   // DS4_ECOWN: every device's plan checked against the lead's marks (ecown_chk_k), 2 s a wait at most
                void* m = nullptr;
                if (hipHostMalloc(&m, devs.size() * 4 * sizeof(unsigned long long),
                                  hipHostMallocCoherent | hipHostMallocMapped | hipHostMallocPortable) != hipSuccess) {
                    (void) cudaGetLastError();
                    err = "DS4_ECOWN + DS4_DD_AUDIT: host-mapped check counters";
                    return false;
                }
                std::memset(m, 0, devs.size() * 4 * sizeof(unsigned long long));
                ec_tmo.assign(devs.size(), 0ull);
                for (size_t di = 0; di < devs.size(); ++di) {
                    int khz = 0;
                    if (hipDeviceGetAttribute(&khz, hipDeviceAttributeWallClockRate, devs[di].id) != hipSuccess || khz <= 0) {
                        (void) cudaGetLastError();
                        (void) hipHostFree(m);
                        err = "DS4_ECOWN + DS4_DD_AUDIT: the wall clock rate of device " + std::to_string(devs[di].id);
                        return false;
                    }
                    ec_tmo[di] = (unsigned long long) khz * 2000ull;
                }
                ec_chk = (unsigned long long*) m;
                std::fprintf(stderr, "ds4: DS4_ECOWN + DS4_DD_AUDIT=1: every device's plan checked against the lead's in-VRAM marks on each "
                                     "device-direct layer (%zu devices)\n", devs.size());
            }
        }
#endif
        return true;
    }

    // DS4_PF_HELPER: the helpers' prompt buffers, every device's views of their answers, and a check on every helper
    // against the CPU lane's arithmetic.  Anything it cannot take turns the flag off (printed), never fails the load.
    bool pfh_setup(std::string& err) {
        (void) err;
        pfh_rows = helper::pf_helper_rows();
        const char* why = nullptr;
        int grp = -1;
        bool one_group = true, any_nm = false;
        for (const Layer& l : L) {
            if (l.mtp) continue;
            if (grp < 0) grp = l.grp;
            one_group = one_group && l.grp == grp;
            any_nm = any_nm || l.nm > 1;
        }
#if !defined(STRATA_USE_HIP)
        why = "a non-HIP build";
#else
        if (!hlp.enabled()) why = "no --helper-device";
        else if (hlp.pool_client()) why = "a pool client";
        else if (chunk <= 0) why = "no chunked prompt path";
        else if (!one_group) why = "more than one layer group (the helpers' buffers are one chunk's, the key one sequence)";
#endif
        if (why == nullptr) {
            const int maxt = std::min(pfh_rows, chunk);
            std::string e2;
            if (!hlp.pf_open(maxt, e2)) {
                std::fprintf(stderr, "helper: DS4_PF_HELPER=%d is off: %s\n", pfh_rows, e2.c_str());
                return true;
            }
            pfh_rows = maxt;
        }
        if (why != nullptr) {
            std::fprintf(stderr, "helper: DS4_PF_HELPER=%d is off: not with %s\n", pfh_rows, why);
            return true;
        }
#if defined(STRATA_USE_HIP)
        if (!halloc(pfh_ids, (size_t) pfh_rows * kPicks, err) || !halloc(pfh_w, (size_t) pfh_rows * kPicks, err)) return false;
        pfh_cs.assign(devs.size(), nullptr);
        pfh_ev_r.assign(devs.size(), nullptr);
        pfh_ev_x.assign(devs.size(), nullptr);
        pfh_out_dev.assign(devs.size(), std::vector<const float*>(hlp.size(), nullptr));
        pfh_map_dev.assign(devs.size(), std::vector<const int*>(hlp.size(), nullptr));
        pfh_wait_ms.assign(devs.size(), 0.0);
        for (size_t di = 0; di < devs.size(); ++di) {
            cudaSetDevice(devs[di].id);
            CK(cudaStreamCreateWithFlags(&pfh_cs[di], cudaStreamNonBlocking));
            CK(cudaEventCreateWithFlags(&pfh_ev_r[di], cudaEventDisableTiming));
            CK(cudaEventCreateWithFlags(&pfh_ev_x[di], cudaEventDisableTiming));
            for (size_t h = 0; h < hlp.size(); ++h) {
                void* o = nullptr;
                void* m = nullptr;
                if (hipHostGetDevicePointer(&o, (void*) hlp.pf_out(h), 0) != hipSuccess ||
                    hipHostGetDevicePointer(&m, (void*) hlp.pf_map(h), 0) != hipSuccess) {
                    cudaGetLastError();
                    std::fprintf(stderr, "helper: DS4_PF_HELPER=%d is off: helper %zu's answers are not visible to CUDA%d\n", pfh_rows, h, devs[di].id);
                    return true;
                }
                pfh_out_dev[di][h] = (const float*) o;
                pfh_map_dev[di][h] = (const int*) m;
            }
        }
        // the layers it can take now (every CPU-lane expert held by a helper; the expert cache may move some later: those stream)
        plan_streams();
        int nl_ok = 0, nl_all = 0;
        for (const Layer& l : L) {
            if (l.mtp || l.vs_pin == nullptr) continue;
            ++nl_all;
            nl_ok += [&] {
                if (l.host_list.empty()) return 0;
                for (int e : l.host_list)
                    if (hlp.pf_owner(l.il, e) < 0) return 0;
                return 1;
            }();
        }
        pfh_live = true;
        std::string ce;
        if (!pfh_check(ce)) {
            pfh_live = false;
            std::fprintf(stderr, "helper: DS4_PF_HELPER=%d is off: the load check failed: %s\n", pfh_rows, ce.c_str());
            return true;
        }
        std::fprintf(stderr, "helper: DS4_PF_HELPER: prompt chunks of up to %d rows compute the helper-held experts on the %zu helpers "
                             "(%d of %d layers: every CPU-lane expert held; member m adds helper h %% %d == m before the MoE all-reduce%s); "
                             "load check: %s\n",
                     pfh_rows, hlp.size(), nl_ok, nl_all, L[0].nm, any_nm ? "" : ", one member", ce.c_str());
        // pf3: prompts of 128 .. chunk_min - 1 tokens take the chunked path too (DS4_PF_HELPER_CHUNK_MIN=<n>, default 128; 0
        // leaves chunk_min alone; DS4_CHUNK_MIN, when set, wins).  Below chunk_min a prompt goes through windows of 16, which
        // the flag does not touch: run pfh2-20261111T091302Z, 448-480 tokens 1.89-1.96 s ON and OFF alike, 0.68-0.74 s with
        // DS4_CHUNK_MIN=128; 222 tokens 0.93 s vs 0.48 s
        pfh_chunk_min_off = chunk_min;   // (DS4_PF_HELPER_MAXP: a bypassed read's path choice, as with the flag off)
        {
            const char* v = std::getenv("DS4_PF_HELPER_CHUNK_MIN");
            const int pcm = v != nullptr ? std::atoi(v) : 128;
            if (pcm > 0 && std::getenv("DS4_CHUNK_MIN") == nullptr && chunk > 0 && pcm < chunk_min) {
                std::fprintf(stderr, "helper: DS4_PF_HELPER: chunk_min %d -> %d (DS4_PF_HELPER_CHUNK_MIN; DS4_CHUNK_MIN wins)\n", chunk_min, pcm);
                chunk_min = std::max(kWin + 1, pcm);
            }
        }
        {   // DS4_PF_HELPER_MAXP (see pfh_maxp)
            const char* v = std::getenv("DS4_PF_HELPER_MAXP");
            if (v != nullptr && *v != 0) {
                char* end = nullptr;
                const long mp = std::strtol(v, &end, 10);
                if (end == nullptr || *end != 0 || mp < 0 || mp > (1L << 30))
                    std::fprintf(stderr, "helper: DS4_PF_HELPER_MAXP=%s ignored (a token count >= 0): every prompt read with the helper\n", v);
                else
                    pfh_maxp = (int) mp;
            }
            if (pfh_maxp > 0)
                std::fprintf(stderr, "helper: DS4_PF_HELPER_MAXP=%d: a prompt read of more than %d new tokens without the prompt "
                                     "helper (the DS4_PF_HELPER=0 path for the whole read, chunk_min %d); %d or fewer with it "
                                     "(chunk_min %d)\n", pfh_maxp, pfh_maxp, pfh_chunk_min_off, pfh_maxp, chunk_min);
        }
#endif
        return true;
    }
    // every helper: the PF path's answer for synthetic rows of two of its experts (21 rows of one - two rounds, 16 + 5 - and
    // 5 of another; then 3 rows: the <= 4-row kernel) against the CPU lane's arithmetic on the same blobs (read_mx, as the
    // fill read them).  Not the same rounding (the CPU's activations are Q8_K, a scale a 256), so a relative tolerance:
    // a wave64 / layout bug gives O(1).  out: the worst relative L2 error, or the failure.
    bool pfh_check(std::string& out) {
        const double tol = std::getenv("DS4_PF_HELPER_TOL") ? std::atof(std::getenv("DS4_PF_HELPER_TOL")) : 0.03;
        double worst = 0.0;
        int checked = 0;
        const int D = g.dim, FF = g.ff;
        for (size_t h = 0; h < hlp.size(); ++h) {
            int li = -1, e0 = -1, e1 = -1;
            for (const Layer& l : L) {
                if (l.mtp || l.vs_pin == nullptr || l.lay.fmt != gg::kFmtMXFP4 || gg::mx_experts(l.lay)) continue;
                e0 = e1 = -1;
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0 && hlp.pf_owner(l.il, e) == (int) h) {
                        if (e0 < 0) e0 = e;
                        else if (e1 < 0) e1 = e;
                    }
                if (e1 >= 0) {
                    li = l.il;
                    break;
                }
            }
            if (li < 0) continue;
            const Layer& l = L[(size_t) li];
            gg::IqCpu fm;
            std::string ferr;
            if (!gg::iq_cpu_fmt(gg::expert_type(l.lay, 0), gg::expert_type(l.lay, 2), D, FF, fm, ferr)) {
                out = "no CPU reference for layer " + std::to_string(li) + ": " + ferr;
                return false;
            }
            std::vector<uint8_t> b0(l.blob), b1(l.blob);
            if (!read_mx(l, e0, b0.data()) || !read_mx(l, e1, b1.data())) {
                out = "reading layer " + std::to_string(li) + "'s experts";
                return false;
            }
            for (int T : {21, 3}) {
                if (T > pfh_rows) continue;
                uint32_t s = 12345u + (uint32_t) h * 977u + (uint32_t) T;
                float* x = hlp.pf_x();
                for (size_t q = 0; q < (size_t) T * D; ++q) {
                    s = s * 1664525u + 1013904223u;
                    x[q] = ((float) (s >> 8) / 16777216.0f - 0.5f) * 2.0f;
                }
                std::vector<int> ids((size_t) T * kPicks, -1);
                std::vector<float> w((size_t) T * kPicks, 0.0f);
                for (int t = 0; t < T; ++t) {
                    ids[(size_t) t * kPicks] = e0;
                    w[(size_t) t * kPicks] = 0.6f;
                    if (t < 5) {
                        ids[(size_t) t * kPicks + 1] = e1;
                        w[(size_t) t * kPicks + 1] = 0.3f;
                    }
                }
                std::string e2;
                if (!hlp.pf_issue(li, T, 2, ids.data(), w.data(), [&](int e) { return l.slot[(size_t) e] < 0; }, e2) || !hlp.pf_wait(h)) {
                    out = "helper " + std::to_string(h) + ": " + (e2.empty() ? "the wait failed" : e2);
                    return false;
                }
                if (hlp.pf_tokens(h) != T) {
                    out = "helper " + std::to_string(h) + ": " + std::to_string(hlp.pf_tokens(h)) + " tokens answered of " + std::to_string(T);
                    return false;
                }
                const float* po = hlp.pf_out(h);
                const int* pm = hlp.pf_map(h);
                std::vector<uint8_t> act((size_t) fm.act_bytes), hq((size_t) fm.h_bytes);
                std::vector<float> hh((size_t) FF), y((size_t) D);
                double num = 0.0, den = 0.0;
                for (int t = 0; t < T; ++t) {
                    std::vector<double> ref((size_t) D, 0.0);
                    for (int i = 0; i < 2; ++i) {
                        const int e = ids[(size_t) t * kPicks + i];
                        if (e < 0) continue;
                        const uint8_t* bl = (e == e0 ? b0 : b1).data();
                        gg::iq_cpu_quant(fm.gu_act, x + (size_t) t * D, D, act.data());
                        const void* ap[1] = {act.data()};
                        float* hp[1] = {hh.data()};
                        gg::iq_cpu_gate_up(fm, bl + l.lay.trellis[0], bl + l.lay.trellis[1], ap, 1, hp, 0, FF, g.lim);
                        gg::iq_cpu_quant(fm.d_act, hh.data(), FF, hq.data());
                        const void* hqp[1] = {hq.data()};
                        float* yp[1] = {y.data()};
                        gg::iq_cpu_down(fm, bl + l.lay.trellis[2], hqp, 1, yp, 0, D);
                        for (int c = 0; c < D; ++c) ref[(size_t) c] += (double) w[(size_t) t * kPicks + i] * (double) y[(size_t) c];
                    }
                    const int j = pm[t];
                    if (j < 0) {
                        out = "helper " + std::to_string(h) + ": token " + std::to_string(t) + " not answered";
                        return false;
                    }
                    for (int c = 0; c < D; ++c) {
                        const double v = (double) po[(size_t) j * D + c];
                        if (!std::isfinite(v)) {
                            out = "helper " + std::to_string(h) + ": a non-finite answer";
                            return false;
                        }
                        num += (v - ref[(size_t) c]) * (v - ref[(size_t) c]);
                        den += ref[(size_t) c] * ref[(size_t) c];
                    }
                }
                const double rel = std::sqrt(num / std::max(den, 1e-30));
                worst = std::max(worst, rel);
                ++checked;
                if (!(rel <= tol)) {
                    char b[200];
                    std::snprintf(b, sizeof b, "helper %zu (layer %d experts %d, %d), %d rows: relative L2 error %.3g > %.3g (DS4_PF_HELPER_TOL)", h, li, e0, e1, T, rel, tol);
                    out = b;
                    return false;
                }
            }
        }
        if (checked == 0) {
            out = "no helper has two experts of a layer to check";
            return false;
        }
        char b[160];
        std::snprintf(b, sizeof b, "%d cases on %zu helpers, worst relative L2 error %.2g (tolerance %.2g)", checked, hlp.size(), worst, tol);
        out = b;
        return true;
    }

    // (ds4_helper.hpp): open the helper and fill it with the hottest experts the primary's slots left out.  Trunk
    // layers of GGUF experts (a tensor-parallel group's too: l is its member 0, whose blob / lay / slot are the whole expert's
    // and the primary-resident test, the members' hlay slices being separate); the drafter's blocks and anything the device kernels do not
    // take stay the CPU lane's.  The helper's copy of an expert takes nothing away: file / RAM tiers are unchanged.
    bool helper_fill(std::string& err) {
        if (o.helper_devices.empty()) return true;
        helper::Config hc;
        hc.slots = o.helper_slots;   // (per helper)
        hc.reserve_mib = 512;
        hc.verbose = true;
        if (!hlp.open(o.helper_devices, hc, err)) return false;
        {   // build 8: stripe the helpers by default under a tensor-parallel group of 3+ (DS4_HELPER_PLACE=layer: as before)
            size_t gmax = 0;
            for (const Group& G : groups) gmax = std::max(gmax, G.mem.size());
            hlp.stripe_default = gmax >= 3 && o.helper_devices.size() >= 2;
        }
        std::vector<helper::LayerGeo> geo;
        for (size_t li = 0; li < L.size(); ++li) {
            const Layer& l = L[li];
            helper::LayerGeo gl;
            gl.li = (int) li;
            gl.n_exp = l.n_exp;
            gl.k_exp = l.k_exp;
            gl.blob = l.blob;
            gl.lay = l.lay;
            gl.n_embd = g.dim;
            gl.n_ff = g.ff;
            gl.limit = g.lim;
            gl.eligible = (!l.mtp || dhelper) && !l.cpu_only && l.n_exp > 0 && l.lay.fmt == gg::kFmtMXFP4 &&
                          (int) l.slot.size() == l.n_exp && l.blob > 0 &&
                          (gg::mx_experts(l.lay) || (gg::iq::supported(gg::expert_type(l.lay, 0)) && gg::iq::supported(gg::expert_type(l.lay, 2))));
            gl.prio = l.mtp && dhelper ? 1 : 0;   // DS4_DRAFT_EXPERTS=helper: the drafter's ranked before any trunk expert
            geo.push_back(gl);
        }
        const bool ok = hlp.fill(geo, prof.empty() ? nullptr : prof.data(), (size_t) g.n_exp,
                                 [&](int li, int e) {   // (DS4_DRAFT_KEEP: a dropped drafter expert is never picked - no helper holds it)
                                     const Layer& x = L[(size_t) li];
                                     return x.slot[(size_t) e] >= 0 || (!x.dkeep.empty() && !x.dkeep[(size_t) e]);
                                 },
                                 [&](int li, int e, uint8_t* dst) { return read_mx(L[(size_t) li], e, dst); }, err);
        if (ok) std::fprintf(stderr, "%s", hlp.describe().c_str());
        if (ok && helper_defer && defer_2w && !hlp.pool_client()) {   // DS4_HELPER_DEFER: the second lanes
            std::string e2;
            defer_lanes = hlp.open_deferred(e2);
            std::fprintf(stderr, "helper: DS4_HELPER_DEFER: %s\n", defer_lanes ? "a second lane a helper for the deferred picks (DS4_HELPER_DEFER_2W)"
                                                                            : ("no second lanes (" + e2 + "): deferred picks queue behind the kept ones").c_str());
        }
        // the helper warmed at load (DS4_HELPER_WARM=0: off) - one round a layer, one expert it holds, x = 0 into a
        // scratch answer, so every expert-type kernel's code object, its stream and buffers are first used here and not on
        // the decode's first token (measured: token 1 of every helper run 86-89 ms against a 31-32 ms median).  Nothing the
        // model computes is touched; the helper's own counters see these rounds.
        if (ok && !hlp.pool_client() && !(std::getenv("DS4_HELPER_WARM") && std::atoi(std::getenv("DS4_HELPER_WARM")) == 0)) {
            const double tw = now_ms();
            std::unique_ptr<Req> rq(new Req());
            std::unique_ptr<Resp> rs(new Resp());
            std::memset((void*) rq.get(), 0, sizeof(Req));
            int warmed = 0;
            // (every helper on every layer it holds experts of: with several helpers the first owned expert of a
            // layer is only on one of them)
            for (size_t li = 0; li < L.size(); ++li)
                for (size_t k = 0; k < hlp.size(); ++k)
                for (int e = 0; e < L[li].n_exp; ++e) {
                    if (!hlp.at(k).owns((int) li, e)) continue;
                    std::memset((void*) rs.get(), 0, sizeof(Resp));
                    rq->T = 1;
                    rq->ids[0][0] = e;
                    rq->w[0][0] = 1.0f;
                    helper::Pick pk1;
                    pk1.t = 0;
                    pk1.i = 0;
                    pk1.e = e;
                    std::vector<helper::Pick> rej, fail;
                    if (hlp.begin((int) li, *rq, 1, &pk1, 1, rej)) {
                        hlp.finish(*rs, 1, fail);
                        ++warmed;
                    }
                    if (defer_lanes && hlp.begin_deferred((int) li, *rq, 1, &pk1, 1, rej)) {   // (the deferred lanes too)
                        hlp.finish_deferred(*rs, 1);
                        ++warmed;
                    }
                    break;
                }
            std::fprintf(stderr, "helper: warmed %d (layer, helper) rounds in %.0f ms (DS4_HELPER_WARM=0: off)\n", warmed, now_ms() - tw);
            hlp.reset_stats();   // the run's counters (the end-of-run line) leave the warm-up out
        }
        return ok;
    }

    // a GGUF's VRAM experts, in file order, by a few threads through pinned staging blobs (the CPU lane's stay in the
    // file: the mapping reads them on first use)
    bool load_experts_mx(std::string& err) {
        struct Job {
            int layer, e;
        };
        std::vector<Job> jobs;
        size_t maxb = 0;
        for (const Layer& l : L) {
            maxb = std::max(maxb, l.blob);
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] >= 0) jobs.push_back({l.il, e});
        }
        std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {
            const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
            if (la.mx_file[0] != lb.mx_file[0]) return la.mx_file[0] < lb.mx_file[0];
            return la.mx_off[0] + (uint64_t) a.e * la.mx_stride[0] < lb.mx_off[0] + (uint64_t) b.e * lb.mx_stride[0];
        });
        std::atomic<size_t> next{0};
        std::atomic<bool> failed{false};
        std::mutex emu;
        std::string ferr;
        std::atomic<int64_t> done_bytes{0};
        const double t0 = now_ms();
        std::vector<std::thread> th;
        for (int t = 0; t < 12; ++t)
            th.emplace_back([&] {
                uint8_t *stage = nullptr, *stage2 = nullptr;
                cudaHostAlloc((void**) &stage, maxb, cudaHostAllocPortable);
                cudaHostAlloc((void**) &stage2, maxb, cudaHostAllocPortable);
                for (;;) {
                    const size_t i = next.fetch_add(1);
                    if (i >= jobs.size() || failed.load()) break;
                    const Layer& l = L[(size_t) jobs[i].layer];
                    const int e = jobs[i].e;
                    bool ok = stage != nullptr && stage2 != nullptr && read_mx(l, e, stage);
                    for (int m = 0; m < l.nm && ok; ++m) {   // (a group: each member its part)
                        const Layer& x = member(l, m);
                        cudaSetDevice(devs[(size_t) x.dev].id);
                        if (l.nm > 1) blob_to_half(l, stage, m, stage2);
                        // (tp4: the member's own slot size - unit(l) is member 0's)
                        ok = cudaMemcpy(x.vram_base + (size_t) l.slot[(size_t) e] * unit(x), l.nm > 1 ? stage2 : stage,
                                        unit(x), cudaMemcpyHostToDevice) == cudaSuccess;
                    }
                    if (!ok) {
                        std::lock_guard<std::mutex> lk(emu);
                        ferr = "loading layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
                        failed.store(true);
                        break;
                    }
                    const int64_t db = done_bytes.fetch_add((int64_t) l.blob) + (int64_t) l.blob;
                    if (o.verbose && (i % 1024) == 0)
                        std::fprintf(stderr, "ds4: experts %zu / %zu (%.1f GB, %.2f GB/s)\n", i, jobs.size(), db / 1e9,
                                     db / 1e6 / std::max(1.0, now_ms() - t0));
                }
                if (stage) cudaFreeHost(stage);
                if (stage2) cudaFreeHost(stage2);
            });
        for (auto& t : th) t.join();
        if (failed.load()) {
            err = ferr;
            return false;
        }
        // as load_experts in place: the VRAM experts' pages leave the cache, the most-routed of the others (the
        // profile's share of their layer, then by index) are read once, up to warm_bytes, so the cache starts with them
        struct Warm {
            int layer, e;
            double share;
        };
        std::vector<Warm> warm;
        for (const Layer& l : L) {
            const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
            double sum = 0;
            for (int e = 0; e < l.n_exp; ++e) sum += p[e];
            for (int e = 0; e < l.n_exp; ++e) {
                if (l.slot[(size_t) e] >= 0) {
                    for (int r = 0; r < 3; ++r)
                        os::advise(pk.fds[(size_t) l.mx_file[r]], (l.mx_off[r] + (uint64_t) e * l.mx_stride[r]), mx_part_bytes(l, r), false);
                } else {
                    warm.push_back({l.il, e, sum > 0 ? p[e] / sum : 0.0});
                }
            }
        }
        std::stable_sort(warm.begin(), warm.end(), [](const Warm& a, const Warm& b) { return a.share > b.share; });
        if (!ram_tier && !warm.empty()) {   // copied into RAM (copy_experts decides), the rest read ahead into what is left
            std::vector<std::pair<int, int>> hot;
            for (const Warm& w : warm) hot.push_back({w.layer, w.e});
            if (!copy_experts(hot, err)) return false;
            if (copy_mode) {
                warm.erase(std::remove_if(warm.begin(), warm.end(),
                                          [&](const Warm& w) { return L[(size_t) w.layer].ram[(size_t) w.e] >= 0; }),
                           warm.end());
                const uint64_t av = ram_avail();
                if (av != ~uint64_t{0}) warm_bytes = av > kRamMargin ? std::min<uint64_t>(warm_bytes, av - kRamMargin) : 0;
            }
        }
        if (ram_tier && warm_bytes > 0 && !warm.empty()) {
            // chunks of 32 slots up to warm_bytes (all the RAM the rest leaves, kRamMargin kept), one slot kept free for
            // a move in; the hottest experts read in, their pages then dropped from the page cache.  Plain memory, not
            // pinned: only the CPU reads it (what goes to a GPU passes the pinned staging), and pinned memory is capped on
            // Windows - the engine's own pinned buffers come after this
            const size_t want = std::min(warm.size(), (size_t) (warm_bytes / maxb));
            while (ram_slots.size() < want + 1) {
                const size_t n = std::min<size_t>(32, want + 1 - ram_slots.size());
                uint8_t* c = (uint8_t*) os::anon_alloc(n * maxb, -1, 1);
                if (c == nullptr) break;
                ram_chunks.push_back(c);
                ram_chunk_bytes.push_back(n * maxb);
                for (size_t i = 0; i < n; ++i) ram_slots.push_back(c + i * maxb);
            }
            ram_held = ram_slots.empty() ? 0 : (int) ram_slots.size() - 1;
            for (Layer& l : L)
                if (l.lay.fmt == gg::kFmtMXFP4) l.ram.assign((size_t) l.n_exp, -1);
            std::atomic<size_t> ri{0};
            std::atomic<bool> rfail{false};
            std::vector<std::thread> rt;
            for (int t = 0; t < 12 && ram_held > 0; ++t)
                rt.emplace_back([&] {
                    for (size_t i; (i = ri.fetch_add(1)) < (size_t) ram_held;) {
                        const Layer& l = L[(size_t) warm[i].layer];
                        if (!read_mx_file(l, warm[i].e, ram_slots[i])) rfail.store(true);
                        for (int r = 0; r < 3; ++r)
                            os::advise(pk.fds[(size_t) l.mx_file[r]], l.mx_off[r] + (uint64_t) warm[i].e * l.mx_stride[r],
                                       mx_part_bytes(l, r), false);
                    }
                });
            for (auto& t : rt) t.join();
            if (rfail.load()) {
                err = "reading the RAM tier's experts from the model's files failed";
                return false;
            }
            for (int i = 0; i < ram_held; ++i) L[(size_t) warm[(size_t) i].layer].ram[(size_t) warm[(size_t) i].e] = i;
            if (ram_held > 0) ram_free.push_back(ram_held);
            if (o.expert_cache && ram_held > 0) ram_th = std::thread([this] { ram_loop(); });
            if (o.verbose)
                std::fprintf(stderr, "ds4: RAM tier: %d experts (%.1f GB of RAM), the hottest after VRAM's; the other %zu "
                                     "read from the model's files (%.1f s)\n",
                             ram_held, ram_slots.size() * (double) maxb / 1e9, warm.size() - (size_t) ram_held,
                             (now_ms() - t0) / 1000.0);
            return true;
        }
        size_t nw = 0;
        for (double b = 0; nw < warm.size() && b + (double) L[(size_t) warm[nw].layer].blob <= (double) warm_bytes; ++nw)
            b += (double) L[(size_t) warm[nw].layer].blob;
        std::atomic<size_t> wi{0};
        std::vector<std::thread> wt;
        for (int t = 0; t < 12 && nw > 0; ++t)
            wt.emplace_back([&] {
                std::vector<uint8_t> buf(maxb);
                for (size_t i; (i = wi.fetch_add(1)) < nw;) read_mx(L[(size_t) warm[i].layer], warm[i].e, buf.data());
            });
        for (auto& t : wt) t.join();
        if (o.verbose && nw > 0)
            std::fprintf(stderr, "ds4: %zu CPU-lane experts read ahead (%.1f GB) in %.1f s\n", nw,
                         nw * (double) L[0].blob / 1e9, (now_ms() - t0) / 1000.0);
        return true;
    }

    // STRATA_DS4_SHARED_STORE: copy_experts' result - the CPU lane's experts in RAM, in copy_mode's layout (one NUMA part, matrix r at
    // cp_lay[il][r], an expert's block cp_lay[il][3] bytes) - but in ONE file-backed mapping shared by every engine on the box.  The
    // segment holds EVERY routed expert of every layer in L (not only this engine's CPU-lane set: each engine's GPUs hold a different
    // set, and a swap moves an expert between lane and VRAM), expert e of layer il at lay_off[il] + e * cp_lay[il][3].  The first
    // engine to find the segment missing fills it from the GGUF files, the others map it read-only (SharedStore, ds4_shared_store.hpp).
    // ram_part gets one entry per (layer, expert) -> slot shared_slot0[il] + e; l.ram[e] is set for this engine's lane experts only.
    // Pinning for the prompt path is skipped (a read-only shared mapping; the prompt stages the experts as an unpinned copy does).
    bool copy_experts_shared(const std::vector<std::pair<int, int>>& hot, std::string& err) {
#if !defined(__linux__)
        (void) hot;
        err = "STRATA_DS4_SHARED_STORE: the shared expert store is Linux only";
        return false;
#else
        const double t0 = now_ms();
        NH = 1;   // (a single part: the segment is not split by NUMA node; see docs/dsv41/cards/HX-03.md)
        cp_lay.assign(L.size(), {0, 0, 0, 0});
        shared_slot0.assign(L.size(), -1);
        std::vector<uint64_t> lay_off(L.size(), 0);
        uint64_t data = 0;
        int nslot = 0;
        uint64_t ident = 1469598103934665603ull;   // FNV-1a over everything the layout and the bytes' source depend on
        auto mix = [&](uint64_t v) {
            for (int i = 0; i < 8; ++i) {
                ident ^= (v >> (8 * i)) & 0xff;
                ident *= 1099511628211ull;
            }
        };
        mix(strata::ds4::SharedStore::kVersion);
        mix((uint64_t) g.nl), mix((uint64_t) g.n_exp), mix((uint64_t) g.ff), mix((uint64_t) g.dim);
        for (size_t i = 0; i < pk.files.size(); ++i) {
            for (char c : pk.files[i]) mix((uint64_t) (unsigned char) c);
            mix(os::file_size(pk.fds[i]));
        }
        for (const Layer& l : L) {
            size_t off = 0;
            for (int r = 0; r < 3; ++r) {
                cp_lay[(size_t) l.il][(size_t) r] = off;
                off += align256((size_t) mx_n(r) * mx_row_b(l, r));
            }
            cp_lay[(size_t) l.il][3] = off;
            if (l.mx_file[0] < 0 || l.mx_file[1] < 0 || l.mx_file[2] < 0 || l.n_exp <= 0) continue;   // (not a file-backed MXFP4 layer: none of it here)
            shared_slot0[(size_t) l.il] = nslot;
            lay_off[(size_t) l.il] = data;
            nslot += l.n_exp;
            data += (uint64_t) l.n_exp * off;
            mix((uint64_t) l.il), mix((uint64_t) l.n_exp), mix((uint64_t) l.blob), mix((uint64_t) off);
            for (int r = 0; r < 3; ++r) mix((uint64_t) l.mx_file[r]), mix(l.mx_off[r]), mix(l.mx_stride[r]), mix((uint64_t) cp_lay[(size_t) l.il][(size_t) r]);
        }
        if (nslot == 0) {
            err = "STRATA_DS4_SHARED_STORE: no layer of this pack has file-backed experts";
            return false;
        }
        const std::string path = strata::ds4::SharedStore::resolve(shared_store_spec(), ident);
        double wait_s = 1800.0;
        if (const char* v = std::getenv("STRATA_DS4_SHARED_STORE_WAIT")) wait_s = std::max(1.0, std::atof(v));
        auto ss = std::make_unique<strata::ds4::SharedStore>();
        std::string serr;
        const strata::ds4::SharedStore::Role role = ss->open(path, ident, data, wait_s, serr);
        if (role == strata::ds4::SharedStore::Role::kNone) {
            err = "STRATA_DS4_SHARED_STORE: " + serr;
            return false;
        }
        if (role == strata::ds4::SharedStore::Role::kFill) {
            struct Job {
                int layer, e;
            };
            std::vector<Job> jobs;
            jobs.reserve((size_t) nslot);
            for (const Layer& l : L)
                if (shared_slot0[(size_t) l.il] >= 0)
                    for (int e = 0; e < l.n_exp; ++e) jobs.push_back({l.il, e});
            std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {   // (file order: the disk reads ahead)
                const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
                if (la.mx_file[0] != lb.mx_file[0]) return la.mx_file[0] < lb.mx_file[0];
                return la.mx_off[0] + (uint64_t) a.e * la.mx_stride[0] < lb.mx_off[0] + (uint64_t) b.e * lb.mx_stride[0];
            });
            uint8_t* const base = ss->data();
            std::atomic<size_t> ji{0};
            std::atomic<bool> bad{false};
            std::atomic<int64_t> done_b{0};
            std::vector<std::thread> th;
            for (int t = 0; t < 12; ++t)
                th.emplace_back([&] {
                    for (size_t i; (i = ji.fetch_add(1)) < jobs.size() && !bad.load();) {
                        const Job& j = jobs[i];
                        const Layer& l = L[(size_t) j.layer];
                        uint8_t* dst = base + lay_off[(size_t) l.il] + (uint64_t) j.e * cp_lay[(size_t) l.il][3];
                        for (int r = 0; r < 3; ++r)
                            if (!pk.read_at(l.mx_file[r], l.mx_off[r] + (uint64_t) j.e * l.mx_stride[r], mx_part_bytes(l, r),
                                            dst + cp_lay[(size_t) l.il][(size_t) r]))
                                bad.store(true);
                        const int64_t db = done_b.fetch_add((int64_t) l.blob) + (int64_t) l.blob;
                        if (o.verbose && i % 2048 == 0)
                            std::fprintf(stderr, "ds4: shared store: filling %zu / %zu (%.1f GB, %.2f GB/s)\n", i, jobs.size(), db / 1e9,
                                         db / 1e6 / std::max(1.0, now_ms() - t0));
                    }
                });
            for (auto& t : th) t.join();
            if (bad.load()) {
                ss->abort();
                err = "STRATA_DS4_SHARED_STORE: reading the experts from the model's files failed";
                return false;
            }
            std::string perr;
            if (!ss->publish((now_ms() - t0) / 1000.0, perr)) {
                ss->abort();
                err = "STRATA_DS4_SHARED_STORE: " + perr;
                return false;
            }
            for (size_t i = 0; i < pk.fds.size(); ++i)   // (the fill's reads left a second copy in the page cache: let it go)
                (void) ::posix_fadvise((int) pk.fds[i], 0, 0, POSIX_FADV_DONTNEED);
        }
        if (const char* v = std::getenv("STRATA_DS4_SHARED_STORE_DROP")) ss->set_drop(std::atoi(v) != 0);
        // slots: expert e of layer il at the segment's fixed place; this engine's lane experts get l.ram
        const uint8_t* const base = ss->data();
        ram_part.assign((size_t) nslot, {nullptr, nullptr});
        for (const Layer& l : L) {
            if (shared_slot0[(size_t) l.il] < 0) continue;
            for (int e = 0; e < l.n_exp; ++e)
                ram_part[(size_t) shared_slot0[(size_t) l.il] + (size_t) e][0] =
                    const_cast<uint8_t*>(base + lay_off[(size_t) l.il] + (uint64_t) e * cp_lay[(size_t) l.il][3]);
        }
        copy_spare.assign(L.size(), -1);
        for (Layer& l : L) l.ram.assign((size_t) l.n_exp, -1);
        int held = 0;
        for (const auto& h : hot) {
            Layer& l = L[(size_t) h.first];
            if (shared_slot0[(size_t) l.il] < 0) continue;   // (stays in place)
            l.ram[(size_t) h.second] = shared_slot0[(size_t) l.il] + h.second;
            ++held;
        }
        copy_mode = true;
        ram_held = held;
        double hb = 0;
        for (const auto& h : hot)
            if (L[(size_t) h.first].ram[(size_t) h.second] >= 0) hb += (double) L[(size_t) h.first].blob;
        std::fprintf(stderr, "ds4: shared store %s: %s %.1f GB of experts in %.1f s%s; this engine's CPU lane reads %d of %zu experts (%.1f GB) from it\n",
                     ss->path().c_str(), role == strata::ds4::SharedStore::Role::kFill ? "filled" : "attached",
                     (double) ss->data_bytes() / 1e9, (now_ms() - t0) / 1000.0,
                     role == strata::ds4::SharedStore::Role::kFill ? "" : (" (filled by pid " + std::to_string(ss->filler_pid()) + " in " +
                                                                              std::to_string((int) ss->filler_seconds()) + " s)").c_str(),
                     held, hot.size(), hb / 1e9);
        shared_store = std::move(ss);
        return true;
#endif
    }

    // a GGUF's CPU-lane experts copied into RAM (copy_mode), decided once VRAM's are in - on a unified-memory APU the GPU
    // has taken its share of the RAM by then, so the copies only get what it leaves.  `hot`: the CPU lane's experts, the
    // most-routed first.  --mmap-experts off: all that fit beside kRamMargin (a warning if not all do); on and auto:
    // none - read in place: the page cache follows a conversation's experts where a static set (the profile's
    // hottest) does not (the RAM tier's lesson), and copies that all fit were no faster; DS4_COPY_GB=<n>: the
    // hottest n GB (the static hybrid, for tests).  Each copy in NH parts on the NUMA nodes (DS4_COPY_NUMA=1: one), read from the files in file
    // order by a few threads, anonymous memory on huge pages (Windows: plain), not pinned (only the CPU reads it; what
    // goes to a GPU passes the pinned staging) - a layer that cannot get its memory keeps its experts in place
    bool copy_experts(const std::vector<std::pair<int, int>>& hot, std::string& err) {
        if (o.mmap_experts > 0 || hot.empty()) return true;
        if (!shared_store_spec().empty()) return copy_experts_shared(hot, err);
        const double t0 = now_ms();
        auto spare_of = [&](const Layer& l) { return o.expert_cache && l.spare_vram >= 0 ? 1 : 0; };
        double all = 0;
        {
            std::vector<char> seen(L.size(), 0);
            for (const auto& h : hot) {
                const Layer& l = L[(size_t) h.first];
                all += (double) l.blob * (1 + (seen[(size_t) l.il]++ == 0 ? spare_of(l) : 0));
            }
        }
        const uint64_t avail = ram_avail();
        // (Windows: the copies are committed memory, within what its commit still has beside the other programs' margin)
        // DS4_COPY_HUGETLB: the arena comes from the kernel's huge-page pool, which MemAvailable does not count: add
        // its free bytes so the full copy is taken when the pool holds it.
        // 0.2.7: DS4_COPY_HUGETLB unset = ON when the reserved pool already holds the whole copy (HugePages_Free), else the
        // ordinary arena exactly as before; =0 is the off switch, =1 asks for it anyway (a smaller pool is used, the rest warns).
        const uint64_t pool_free = os::huge_free_bytes();
        const bool huge_arena = strata::ds4::copy_hugetlb_default(env_tri("DS4_COPY_HUGETLB"), (double) pool_free, all, defaults_026());
        if (huge_arena && std::getenv("DS4_COPY_HUGETLB") == nullptr)
            std::fprintf(stderr, "ds4: the reserved huge-page pool (%.1f GB free) holds the whole copy (%.1f GB): the arena on 2 MB pages "
                                 "(DS4_COPY_HUGETLB=0 keeps the ordinary arena)\n", (double) pool_free / 1e9, all / 1e9);
        bool arena_all_huge = huge_arena;   // (every chunk really from the pool: the pin below needs that)
        const double pool = huge_arena ? (double) pool_free : 0.0;
        const double can = std::min(avail == ~uint64_t{0} ? 1e300 : std::max(0.0, (double) avail - (double) kRamMargin) + pool,
                                    commit_room());
        // (auto: none - copies that all fit were measured no faster than the page cache: the CPU lane's rows are
        // compute-bound, ~46 GB/s from either on 2 Xeon sockets, NUMA parts included; a part copied cost decode speed
        // on 64 GB and on 32 GB of RAM)
        double budget = o.mmap_experts == 0 ? std::min(all, can) : auto_copy_all && all <= can ? all : 0.0;   // (auto: all or none)
        if (const char* v = std::getenv("DS4_COPY_GB")) budget = std::atof(v) * 1e9;
        if (o.mmap_experts < 0 && auto_copy_all && all > can)
            std::fprintf(stderr, "ds4: the CPU lane's experts (%.1f GB) do not all fit the RAM this process can get now (%.1f GB beside %.0f GB for "
                                 "the rest): read in place from the model's files (--mmap-experts off copies what fits)\n", all / 1e9, can / 1e9, kRamMargin / 1e9);
        if (o.mmap_experts == 0 && all > can)
            std::fprintf(stderr, "ds4: --mmap-experts off: the CPU lane's experts (%.1f GB) do not all fit the RAM this "
                                 "process can get (%.1f GB beside %.0f GB for the rest) - the most-routed copied, the "
                                 "others read in place\n", all / 1e9, can / 1e9, kRamMargin / 1e9);
        if (auto_copy_all && budget > 0)
            std::fprintf(stderr, "ds4: --mmap-experts auto: the CPU lane's experts (%.1f GB) fit the RAM this process can get (%.1f GB beside %.0f GB for "
                                 "the rest): copied in at load, no demand store (--mmap-experts on keeps them in place)\n", all / 1e9, can / 1e9, kRamMargin / 1e9);
        if (budget <= 0) {
            if (o.verbose)
                std::fprintf(stderr, "ds4: the CPU lane's experts (%.1f GB) stay in place: the RAM this process can get "
                                     "(%.1f GB beside %.0f GB for the rest) does not hold them all\n",
                             all / 1e9, can / 1e9, kRamMargin / 1e9);
            return true;
        }
        // NUMA parts: whole rows of each matrix, so any row count the nodes divide
        int nh = (int) std::min<size_t>(2, std::max<size_t>(1, cores.size()));
        if (const char* v = std::getenv("DS4_COPY_NUMA"))   // (0 / 1: one part; 2: two, even on one node - a test)
            nh = std::atoi(v) >= 2 ? 2 : 1;
        if (g.ff % nh != 0 || g.dim % nh != 0) nh = 1;
        NH = nh;
        cp_lay.assign(L.size(), {0, 0, 0, 0});
        for (const Layer& l : L) {
            size_t off = 0;
            for (int r = 0; r < 3; ++r) {
                cp_lay[(size_t) l.il][(size_t) r] = off;
                off += align256((size_t) (mx_n(r) / NH) * mx_row_b(l, r));
            }
            cp_lay[(size_t) l.il][3] = off;
        }
        // the hottest that fit the budget (a layer's first one brings its spare)
        std::vector<int> n_copy(L.size(), 0);
        double used = 0;
        size_t take = 0;
        for (; take < hot.size(); ++take) {
            const Layer& l = L[(size_t) hot[take].first];
            const double add = (double) l.blob * (1 + (n_copy[(size_t) l.il] == 0 ? spare_of(l) : 0));
            if (used + add > budget) break;
            used += add;
            ++n_copy[(size_t) l.il];
        }
        // each layer's slots: one block per node of (copies + spare) parts
        std::vector<int> first(L.size(), -1);
        copy_spare.assign(L.size(), -1);
        for (Layer& l : L) {
            l.ram.assign((size_t) l.n_exp, -1);
            const int ns = n_copy[(size_t) l.il] + (n_copy[(size_t) l.il] > 0 ? spare_of(l) : 0);
            if (ns == 0) continue;
            const size_t part = cp_lay[(size_t) l.il][3], bytes = (size_t) ns * part;
            std::array<uint8_t*, 2> base = {nullptr, nullptr};
            // DS4_COPY_HUGETLB=1: the arena on explicit 2 MB pages (the pool must be reserved), so a pin of it keeps
            // 2 MB pages and the prompt's DMA reads stay stable (a THP arena pinned by cudaHostRegister runs in 4 KB
            // pages: measured 11.9 s one prompt, 30.4 s the next for the same 140 GB)
            const bool huge = huge_arena;
            bool ok = true;
            for (int X = 0; X < NH && ok; ++X) {
                size_t got = bytes;
                base[(size_t) X] = (uint8_t*) (huge ? os::huge_alloc(bytes, &got) : node_map(bytes, X, NH));
                if (huge && base[(size_t) X] == nullptr) {   // no pool on this machine: the ordinary arena instead
                    static bool warned = false;
                    if (!warned) {
                        std::fprintf(stderr, "ds4: the 2 MB huge-page arena was asked for but the pool ran out (reserve more: sysctl "
                                             "vm.nr_hugepages=N); using the ordinary arena\n");
                        warned = true;
                    }
                    arena_all_huge = false;
                    got = bytes;
                    base[(size_t) X] = (uint8_t*) node_map(bytes, X, NH);
                }
                ok = base[(size_t) X] != nullptr;
                if (ok) {
                    ram_chunks.push_back(base[(size_t) X]);
                    ram_chunk_bytes.push_back(got);
                }
            }
            if (!ok) {
                std::fprintf(stderr, "ds4: no RAM for layer %d's %d copied experts (%.1f GB): they stay in place\n", l.il,
                             ns, (double) bytes * NH / 1e9);
                n_copy[(size_t) l.il] = 0;
                continue;
            }
            first[(size_t) l.il] = (int) ram_part.size();
            for (int i = 0; i < ns; ++i)
                ram_part.push_back({base[0] + (size_t) i * part, NH > 1 ? base[1] + (size_t) i * part : nullptr});
            if (spare_of(l)) copy_spare[(size_t) l.il] = first[(size_t) l.il] + ns - 1;
        }
        struct Job {
            int layer, e, slot;
        };
        std::vector<Job> jobs;
        {
            std::vector<int> next = first;
            for (size_t i = 0; i < take; ++i) {
                const int il = hot[i].first;
                if (n_copy[(size_t) il] == 0) continue;
                jobs.push_back({il, hot[i].second, next[(size_t) il]++});
            }
        }
        std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {   // (file order: the disk reads ahead)
            const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
            if (la.mx_file[0] != lb.mx_file[0]) return la.mx_file[0] < lb.mx_file[0];
            return la.mx_off[0] + (uint64_t) a.e * la.mx_stride[0] < lb.mx_off[0] + (uint64_t) b.e * lb.mx_stride[0];
        });
        std::atomic<size_t> ji{0};
        std::atomic<bool> bad{false};
        std::atomic<int64_t> done_b{0};
        std::vector<std::thread> th;
        for (int t = 0; t < 12 && !jobs.empty(); ++t)
            th.emplace_back([&] {
                for (size_t i; (i = ji.fetch_add(1)) < jobs.size() && !bad.load();) {
                    const Job& j = jobs[i];
                    const Layer& l = L[(size_t) j.layer];
                    for (int r = 0; r < 3; ++r) {
                        const size_t nb = (size_t) (mx_n(r) / NH) * mx_row_b(l, r);
                        for (int X = 0; X < NH; ++X)
                            if (!pk.read_at(l.mx_file[r], l.mx_off[r] + (uint64_t) j.e * l.mx_stride[r] + (uint64_t) X * nb, nb,
                                            ram_part[(size_t) j.slot][(size_t) X] + cp_lay[(size_t) l.il][(size_t) r]))
                                bad.store(true);
                    }
                    const int64_t db = done_b.fetch_add((int64_t) l.blob) + (int64_t) l.blob;
                    if (o.verbose && i % 2048 == 0)
                        std::fprintf(stderr, "ds4: copying experts %zu / %zu (%.1f GB, %.2f GB/s)\n", i, jobs.size(), db / 1e9,
                                     db / 1e6 / std::max(1.0, now_ms() - t0));
                }
            });
        for (auto& t : th) t.join();
        if (bad.load()) {
            err = "copying the CPU lane's experts from the model's files failed";
            return false;
        }
        for (const Job& j : jobs) L[(size_t) j.layer].ram[(size_t) j.e] = j.slot;
        // each layer's spare RAM part is first written by the expert cache's first swap of that layer, i.e. during the
        // decode: ~40 x 10 MB of fresh anonymous huge pages taken while the page cache has the RAM full.  Each such fault
        // compacts (direct, and wakes kcompactd), the migrations move pages of the process's GPU-mapped host buffers, and every
        // one fires amdgpu's userptr MMU notifier, which quiesces all of the process's GPU queues until the restore worker
        // revalidates them: single tokens of 0.2-4 s.  So the spares are made resident here, at load.
        // DS4_PREFAULT_SPARE=0: the old behaviour (left to the first swap).
        if (prefault_spares()) {
            const double tp = now_ms();
            size_t nb = 0;
            for (const Layer& l : L) {
                const int s = copy_spare[(size_t) l.il];
                if (s < 0) continue;
                for (int X = 0; X < NH; ++X) {
                    os::prefault_write(ram_part[(size_t) s][(size_t) X], cp_lay[(size_t) l.il][3]);
                    nb += cp_lay[(size_t) l.il][3];
                }
            }
            if (nb > 0)
                std::fprintf(stderr, "ds4: the expert cache's spare RAM parts made resident at load (%.0f MB in %.0f ms; DS4_PREFAULT_SPARE=0: off)\n",
                             nb / 1e6, now_ms() - tp);
        }
        copy_mode = true;
        ram_held = (int) jobs.size();
        double cb = 0;
        for (const Job& j : jobs) cb += (double) L[(size_t) j.layer].blob;
        std::fprintf(stderr, "ds4: %zu of the CPU lane's %zu experts copied into RAM (%.1f GB, %d NUMA part%s) in %.1f s%s\n",
                     jobs.size(), hot.size(), cb / 1e9, NH, NH > 1 ? "s" : "", (now_ms() - t0) / 1000.0,
                     jobs.size() < hot.size() ? "; the others read in place" : "");
        // DS4_COPY_PIN: pin the copies, so the prompt path DMAs each expert from where it lies instead of copying it to
        // the pinned staging first (the pass streams 122 GB at 6.8 GB/s through the staging, where the RAM-to-staging
        // and DMA probes are 24 and 28 GB/s).  The CPU lane reads the same memory, and pinned 4 KB pages can cost its
        // TLB (an earlier registration measured -15% decode on a 12 GB card, where the CPU lane does nearly all of the
        // decode) - so AUTO (unset) pins when the cards hold at least half the routed experts: the CPU lane is then a
        // minority of the decode and the prompt stream is what hurts.  Measured on 4x R9700, 2.25 bpw (share 0.72),
        // three interleaved pairs: the second 8K prompt of a process 12.0/11.9/11.9 s against 28.8/13.8/12.3 s unpinned,
        // decode 35.42/35.50/34.9-36.0 against 35.43/35.45/34.9-36.0 tok/s (no cost).  DS4_COPY_PIN=0/1 forces it.
        // DS4_COPY_PIN_RO=1: cudaHostRegisterReadOnly (the GPU only reads it).
        // 0.2.7: DS4_COPY_PIN unset = ON when EITHER condition measured reliable holds: (a) the whole arena is on explicit 2 MB pages (a pin of a
        // THP arena registers 4 KB pages and the DMA rate was erratic on the 12 GB cell: 11.9 s one prompt, 30.4 s the next), or (b) the
        // cards hold at least half the routed experts on RDNA4 (4 x R9700: the pin was reliable in 4/4 runs there, see above).  =0 is the off
        // switch, =1 pins any arena.
        const int pin_env = env_tri("DS4_COPY_PIN");
        bool pin_copies = strata::ds4::copy_pin_default(pin_env, arena_all_huge, rdna4(), gpu_expert_share(),
                                                        !ram_chunks.empty(), defaults_026());
        // DS4_TP_DIRECT (tp_direct_mode): a tensor-parallel layer's prompt stream sends each member's part from the
        // copy as it lies, which needs the copy pinned and mapped - so unless DS4_COPY_PIN=0 or DS4_TP_DIRECT=0 the copy
        // is pinned whenever a layer is tensor parallel.  (The staging it replaces moved 32 GB a chunk a member on
        // the test machine's tp3 through 8 reader threads; see docs/dsv41/FEATURES.md section 2.9)
        bool any_tp = false;
        for (const Layer& l : L) any_tp = any_tp || (!l.mtp && l.nm > 1);
        const bool tp_pin = any_tp && pin_env != 0 && tp_direct_env() != 0 && !ram_chunks.empty() && !shared_store;
        pin_copies = pin_copies || tp_pin;
        if (pin_copies) {
            const bool ro = std::getenv("DS4_COPY_PIN_RO") != nullptr && std::atoi(std::getenv("DS4_COPY_PIN_RO")) != 0;
            const unsigned flags = (ro ? cudaHostRegisterReadOnly : cudaHostRegisterPortable) |
                                   (tp_pin ? cudaHostRegisterMapped | cudaHostRegisterPortable : 0u);
            const double tr = now_ms();
            bool ok = true;
            size_t done = 0;
            for (size_t i = 0; i < ram_chunks.size() && ok; ++i) {
                ok = cudaHostRegister(ram_chunks[i], ram_chunk_bytes[i], flags) == cudaSuccess;
                if (ok) ++done;
            }
            if (ok) {
                ram_pinned = true;
                for (size_t i = 0; i < ram_chunks.size(); ++i)
                    pin_ranges.push_back({(uintptr_t) ram_chunks[i], ram_chunk_bytes[i]});
                std::sort(pin_ranges.begin(), pin_ranges.end());
                pin_dev.reset(new std::atomic<uintptr_t>[pin_ranges.size() * 16]);
                for (size_t i = 0; i < pin_ranges.size() * 16; ++i) pin_dev[i].store(0);
                std::fprintf(stderr, "ds4: the copied experts pinned in %.1f s (%s%s, %zu ranges): the prompt path DMAs them in place%s\n",
                             (now_ms() - tr) / 1000.0, ro ? "read-only" : "read-write", tp_pin ? ", mapped" : "",
                             ram_chunks.size(), tp_pin ? " (tensor parallel: DS4_TP_DIRECT, =0 the staging)" : "");
            } else {
                (void) cudaGetLastError();
                for (size_t i = 0; i < done; ++i) (void) cudaHostUnregister(ram_chunks[i]);   // (none left half pinned)
                std::fprintf(stderr, "ds4: pinning the copied experts failed: the prompt path stages them\n");
            }
        }
        return true;
    }

    bool load_experts(std::string& err) {
        if (!L.empty() && L[0].lay.fmt == gg::kFmtMXFP4) return load_experts_mx(err);
        // every expert's region, in file order, by a few threads; VRAM ones through a pinned staging blob.  In place
        // (file_experts) the CPU lane's experts are not copied: the most-routed of them (the profile's share of their
        // layer) are read once, up to warm_bytes, so the page cache starts with them, and the VRAM ones' pages are
        // dropped from it again
        struct Job {
            int layer, e;
        };
        std::vector<Job> jobs;
        for (const Layer& l : L)
            for (int e = 0; e < l.n_exp; ++e)
                if (!file_experts || l.slot[(size_t) e] >= 0) jobs.push_back({l.il, e});
        uint64_t warm = 0;
        if (file_experts) {
            std::vector<std::pair<double, Job>> cand;
            for (const Layer& l : L) {
                const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
                double sum = 0;
                for (int e = 0; e < l.n_exp; ++e) sum += p[e];
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0) cand.push_back({sum > 0 ? p[e] / sum : 0.0, Job{l.il, e}});
            }
            std::stable_sort(cand.begin(), cand.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
            for (const auto& c : cand) {
                const uint64_t b = L[(size_t) c.second.layer].region_bytes[(size_t) c.second.e];
                if (warm + b > warm_bytes) break;
                warm += b;
                jobs.push_back(c.second);
            }
        }
        std::sort(jobs.begin(), jobs.end(), [&](const Job& a, const Job& b) {
            const Layer &la = L[(size_t) a.layer], &lb = L[(size_t) b.layer];
            if (la.region_file[(size_t) a.e] != lb.region_file[(size_t) b.e])
                return la.region_file[(size_t) a.e] < lb.region_file[(size_t) b.e];
            return la.region_off[(size_t) a.e] < lb.region_off[(size_t) b.e];
        });
        std::atomic<size_t> next{0};
        std::atomic<bool> failed{false};
        std::mutex emu;
        std::string ferr;
        const int nth = 12;
        size_t maxr = 0, maxb = 0;
        for (const Layer& l : L) {
            maxb = std::max(maxb, l.blob);
            for (uint64_t r : l.region_bytes) maxr = std::max<size_t>(maxr, r);
        }
        std::atomic<int64_t> done_bytes{0};
        const double t0 = now_ms();
        std::vector<std::thread> th;
        for (int t = 0; t < nth; ++t)
            th.emplace_back([&] {
                std::vector<uint8_t> region(maxr);
                uint8_t *stage = nullptr, *stage2 = nullptr;
                cudaHostAlloc((void**) &stage, maxb, cudaHostAllocPortable);
                cudaHostAlloc((void**) &stage2, maxb, cudaHostAllocPortable);
                int cur_dev = -1;
                for (;;) {
                    const size_t i = next.fetch_add(1);
                    if (i >= jobs.size() || failed.load()) break;
                    const Layer& l = L[(size_t) jobs[i].layer];
                    const int e = jobs[i].e;
                    if (!pk.read_at(l.region_file[(size_t) e], l.region_off[(size_t) e], l.region_bytes[(size_t) e],
                                    region.data())) {
                        std::lock_guard<std::mutex> lk(emu);
                        ferr = "reading layer " + std::to_string(l.il) + " expert " + std::to_string(e) + " failed";
                        failed.store(true);
                        break;
                    }
                    if (l.slot[(size_t) e] >= 0) {
                        repack(l, region.data(), stage);
                        bool up = true;
                        for (int m = 0; m < l.nm && up; ++m) {   // (a group: each member its part)
                            const Layer& x = member(l, m);
                            const Dev& d = devs[(size_t) x.dev];
                            if (cur_dev != d.id) {
                                cudaSetDevice(d.id);
                                cur_dev = d.id;
                            }
                            if (l.nm > 1) blob_to_half(l, stage, m, stage2);
                            up = cudaMemcpy(x.vram_base + (size_t) l.slot[(size_t) e] * unit(x), l.nm > 1 ? stage2 : stage,
                                            unit(x), cudaMemcpyHostToDevice) == cudaSuccess;
                        }
                        if (!up) {
                            std::lock_guard<std::mutex> lk(emu);
                            ferr = "uploading layer " + std::to_string(l.il) + " expert " + std::to_string(e);
                            failed.store(true);
                            break;
                        }
                        if (file_experts)
                            os::advise(pk.fds[(size_t) l.region_file[(size_t) e]], l.region_off[(size_t) e], l.region_bytes[(size_t) e], false);
                    } else if (!file_experts) {
                        for (int X = 0; X < NH; ++X) repack_part(l, region.data(), X, l.hh[(size_t) e][(size_t) X]);
                    }
                    const int64_t db = done_bytes.fetch_add((int64_t) l.region_bytes[(size_t) e]) +
                                       (int64_t) l.region_bytes[(size_t) e];
                    if (o.verbose && (i % 1024) == 0)
                        std::fprintf(stderr, "ds4: experts %zu / %zu (%.1f GB, %.2f GB/s)\n", i, jobs.size(),
                                     db / 1e9, db / 1e6 / std::max(1.0, now_ms() - t0));
                }
                if (stage) cudaFreeHost(stage);
                if (stage2) cudaFreeHost(stage2);
            });
        for (auto& t : th) t.join();
        if (failed.load()) {
            err = ferr;
            return false;
        }
        if (file_experts)
            std::fprintf(stderr, "ds4: experts loaded in %.1f s (%.1f GB of the CPU lane's read ahead)\n",
                         (now_ms() - t0) / 1000.0, warm / 1e9);
        return true;
    }

    std::string describe() const {
        std::ostringstream s;
        if (hlp.enabled()) s << hlp.describe();   // the helper expert cache's line (device, slots, GiB, layers)
        for (size_t di = 0; di < devs.size(); ++di) {
            const Dev& d = devs[di];
            int a = -1, b = -1, ev = 0, et = 0;
            for (const Layer& l : L)
                for (int m = 0; m < l.nm; ++m)
                    if (member(l, m).dev == (int) di) {
                        if (a < 0) a = l.il;
                        b = l.il;
                        ev += l.n_vram;
                        et += l.n_exp;
                    }
            size_t fr = 0, tot = 0;
            cudaSetDevice(d.id);
            cudaMemGetInfo(&fr, &tot);
            const size_t gsz = groups.empty() ? 1 : groups[(size_t) d.grp].mem.size();
            char tp[64] = "";
            if (gsz > 1) std::snprintf(tp, sizeof tp, " (tensor parallel %zu, part %d)", gsz, d.mi);
            char line[384];
            std::snprintf(line, sizeof line,
                          "ds4: CUDA%d layers [%d, %d]%s%s: weights %.2f GB, experts %.2f GB (%d of %d in VRAM), caches "
                          "%.2f GB, %.0f MiB free\n",
                          d.id, a, b, tp, (int) di == head_dev ? " + head" : "", d.weights / 1e9, d.experts / 1e9, ev, et,
                          d.caches / 1e9, fr / 1048576.0);
            s << line;
        }
        int nh = 0;
        size_t hb_ = 0;
        for (const Layer& l : L) {
            nh += l.n_exp - l.n_vram;
            hb_ += (size_t) (l.n_exp - l.n_vram) * l.blob;
        }
        if (std::getenv("DS4_PLACE_HASH")) {   // debugging: which experts hold a VRAM slot, as one hash (is the placement the same from run to run?)
            uint64_t h = 1469598103934665603ull;
            for (const Layer& l : L)
                for (int e = 0; e < l.n_exp; ++e) { h ^= (uint64_t) (l.slot[(size_t) e] >= 0 ? 1 + l.il * 1000 + e : 0); h *= 1099511628211ull; }
            char hl[96];
            std::snprintf(hl, sizeof hl, "ds4: placement hash %016llx\n", (unsigned long long) h);
            s << hl;
        }
        char line[200];
        if (copy_mode)
            std::snprintf(line, sizeof line, "ds4: %d routed experts on the CPU lane (%.1f GB): %d copied into RAM (%d NUMA "
                                             "parts), the rest in place in the model's files; %d threads\n",
                          nh, hb_ / 1e9, ram_held, NH, cpu_threads());
        else if (file_experts)
            std::snprintf(line, sizeof line,
                          "ds4: %d routed experts on the CPU lane (%.1f GB, in place in the model's files), %d threads\n",
                          nh, hb_ / 1e9, cpu_threads());
        else
            std::snprintf(line, sizeof line, "ds4: %d routed experts on the CPU lane (%.1f GB of RAM, %d NUMA parts), %d threads\n", nh,
                          hb_ / 1e9, NH, cpu_threads());
        s << line;
        return s.str();
    }

    // The most the automatic store may take: all of the trunk's routed experts (the CPU lane's are a part of them; a store larger
    // than they are is never filled), never less than the old 48 GB.  A PC whose free RAM holds them all (the 251 GB R9700 box:
    // 115 GB of CPU-lane experts, 1 card, 2.00 set: 12.6 -> 21.4 tokens/s with the whole set resident, misses 15.4 -> 1.5 a token)
    // gets every one; the RAM that the room below leaves (free - 12 GB) is what bounds it elsewhere.
    // Whether the experts the GPUs will not hold (the CPU lane's: the pack's less the GPUs' share) all fit the RAM this process can get beside
    // kRamMargin, so that --mmap-experts auto copies them in (a copied expert is the CPU lane's own memory: no page cache to lose to the
    // Engram tables and the files' churn, no store indirection or miss path).  Measured, 1 x R9700 + 251 GB, 2.00 pack, warm: decode +10-15%.
    // --mmap-experts on/off and --ssd-cache N stand as given.
    bool cpu_lane_fits_ram() const {
        if (!pk.gguf || o.mmap_experts >= 0 || o.ssd_cache_gb >= 0.0 || std::getenv("DS4_STORE_GB") || std::getenv("DS4_COPY_GB")) return false;
        if (const char* v = std::getenv("DS4_COPY_ALL")) return std::atoi(v) != 0 && ram_avail() != ~uint64_t{0};
        // An integrated GPU's experts are already in this same RAM (and, above the RAM, in the page file it commits): copying
        // the CPU lane's in beside them takes the pages the GPU's experts live on.  Measured on Strix Halo (64 GB, 2.00 set):
        // 82 GB of experts on the GPU, then 53 GB copied in, and an 8K prompt did not finish in 11 minutes (the in-place path is
        // what the 8-hour soak ran).  DS4_COPY_ALL=1 still forces it; DS4_COPY_ALL=0 leaves it off everywhere.
        for (const Dev& d : devs)
            if (commit_charged(d)) return false;
        const uint64_t avail = ram_avail();
        if (avail == ~uint64_t{0}) return false;
        double exp_b = 0, room = 0, other_b = 0;
        const double share = gpu_expert_share(&exp_b, &room, &other_b);
        if (exp_b <= 0) return false;
        const double lane = exp_b * (1.0 - std::min(1.0, share));
        return copy_all_fits(lane, avail, (double) kRamMargin, commit_room());   // (Windows: the commit room too, not only the free RAM)
    }
    // STRATA_DS4_SHARED_STORE=<name | dir | path | 1>; "" when off (unset, 0, off), not a GGUF pack, or --mmap-experts on (in place)
    std::string shared_store_spec() const {
        const char* v = std::getenv("STRATA_DS4_SHARED_STORE");
        if (v == nullptr || !*v || !std::strcmp(v, "0") || !std::strcmp(v, "off")) return std::string();
        if (!pk.gguf) return std::string();
        if (o.mmap_experts > 0) {
            static bool said = false;
            if (!said) std::fprintf(stderr, "ds4: STRATA_DS4_SHARED_STORE ignored: --mmap-experts on reads the experts in place\n");
            said = true;
            return std::string();
        }
        return std::string(v);
    }
    mutable bool auto_copy_all = false;   // (set by store_gb(): the auto size is the CPU lane's experts copied in, no demand store)
    double store_cap_gb() const {
        double b = 0;
        for (const auto& kt : pk.t)
            if (kt.first.find(".ffn.experts.") != std::string::npos && kt.first.rfind("mtp.", 0) != 0) b += (double) kt.second.bytes;
        return std::max(48.0, b / 1e9);
    }
    double store_gb() const {
        static double cached = -2.0;   // (decided once: the layout of the blobs depends on it)
        if (cached > -1.5) return cached;
        double gb = o.ssd_cache_gb;
        if (const char* v = std::getenv("DS4_STORE_GB")) gb = std::atof(v);
        if (!pk.gguf) gb = 0.0;
        else if (!shared_store_spec().empty()) {   // the shared store is the CPU lane's RAM copy; no private demand store beside it
            if (gb > 0.0) std::fprintf(stderr, "ds4: STRATA_DS4_SHARED_STORE is set: --ssd-cache / DS4_STORE_GB ignored (no private RAM store)\n");
            auto_copy_all = true;
            gb = 0.0;
        } else if (gb < 0.0 && cpu_lane_fits_ram()) {   // auto, and the RAM holds every CPU-lane expert beside kRamMargin: they are copied in at load
            auto_copy_all = true;                       // (copy_experts), the demand store would only be a second, smaller copy of them
            gb = 0.0;
        } else if (gb < 0.0) {   // auto: the RAM free now less 12 GB for the system and the owner's programs, all the experts at most
            const uint64_t avail = ram_avail();
            avail0_ = avail;
            const double room = avail == ~uint64_t{0} ? 0.0 : (double) avail / 1e9 - 12.0;
            gb = room >= 4.0 ? std::min(store_cap_gb(), room) : 0.0;
        }
        return cached = gb;
    }
    // The auto size is decided again here, after the weights are on the GPU: on a unified-memory machine (Strix Halo) the GPU's
    // allocations come out of the same RAM the store would use, and the first estimate (made at the layout, before any upload)
    // saw all of it free.  The explicit sizes (--ssd-cache, DS4_STORE_GB) stand.
    mutable uint64_t avail0_ = ~uint64_t{0};   // (free RAM when the first estimate was made, before the weights went to the GPU)
    double store_gb_now() const {
        const double gb = store_gb();
        if (gb <= 0.0 || o.ssd_cache_gb >= 0.0 || std::getenv("DS4_STORE_GB")) return gb;
        const uint64_t avail = ram_avail();
        if (avail == ~uint64_t{0}) return gb;
        // (the prompt buffers and the context's caches are touched after this point and, on such a machine, take RAM too: measured on
        // Strix Halo about 0.11 MB a token of context beyond 16384, a 40960 context ending 2.5 GB lower than a 16384 one)
        bool any_integrated = false;   // (only a device the driver calls integrated can share the RAM: a discrete card's pinned buffers also lower the free RAM, #4147)
        for (const Dev& d : devs) {
            int v = 0;
            if (cudaDeviceGetAttribute(&v, cudaDevAttrIntegrated, d.id) == cudaSuccess) any_integrated = any_integrated || v != 0;
            else (void) cudaGetLastError();
        }
        const bool uma = strata::ds4::store_gpu_shares_ram(any_integrated, avail0_, avail);
        const double ctx_gb = uma ? 1.1e-4 * std::max(0.0, (double) o.max_context - 16384.0) : 0.0;
        const double room = (double) avail / 1e9 - 12.0 - ctx_gb;
        const double now = room >= 4.0 ? std::min(store_cap_gb(), room) : 0.0;
        if (now < gb)
            std::fprintf(stderr, "ds4: RAM store: %.1f GB of RAM free after the GPU's weights: store sized %.1f GB, not %.1f\n",
                         (double) avail / 1e9, now, gb);
        return std::min(gb, now);
    }
    void init_store() {
        const double gb = store_gb_now();
        if (gb <= 0.0 || L.empty() || L[0].lay.fmt != gg::kFmtMXFP4 || !file_experts) return;
        if (o.ssd_cache_gb < 0.0 && !std::getenv("DS4_STORE_GB")) {   // (the auto size: say when it holds less than the CPU lane's experts)
            double exp_b = 0;
            const double share = gpu_expert_share(&exp_b), lane_gb = exp_b * (1.0 - std::min(1.0, share)) / 1e9;
            if (lane_gb > gb + 1.0 && o.verbose)
                std::fprintf(stderr, "ds4: RAM store: the auto size (%.1f GB) holds less than the CPU lane's experts (%.1f GB): the hottest are kept, the "
                                     "rest is read from the SSD as the prompt picks it (--ssd-cache N sets the size)\n", gb, lane_gb);
        }
        std::vector<ExpertStore::LayerGeo> geo((size_t) g.nl);   // (the trunk's layers: the drafter's bigger experts stay in place)
        for (const Layer& l : L) {
            if (l.il >= g.nl) continue;
            ExpertStore::LayerGeo& gl = geo[(size_t) l.il];
            gl.n_exp = l.n_exp;
            for (int r = 0; r < 3; ++r) {
                gl.file[r] = l.mx_file[r];
                gl.off[r] = l.mx_off[r];
                gl.stride[r] = l.mx_stride[r];
                gl.bytes[r] = mx_part_bytes(l, r);
                gl.tr[r] = l.lay.trellis[r];
            }
            gl.blob = l.blob;
        }
        ExpertStore::Cfg cfg;
        cfg.budget_bytes = (size_t) (gb * 1e9);
        cfg.threads = std::getenv("DS4_STORE_THREADS") ? std::atoi(std::getenv("DS4_STORE_THREADS")) : 8;
        cfg.floor_bytes = (size_t) (std::getenv("DS4_STORE_FLOOR_GB") ? std::atof(std::getenv("DS4_STORE_FLOOR_GB")) : 8.0) << 30;
        cfg.policy = (ExpertStore::Policy) (std::getenv("DS4_STORE_POLICY") ? std::atoi(std::getenv("DS4_STORE_POLICY")) : o.ssd_policy);
        cfg.ram_avail = [] { return ram_avail(); };
        cfg.reserve = (size_t) (std::getenv("DS4_STORE_RESERVE") ? std::atoi(std::getenv("DS4_STORE_RESERVE")) : 192);
        cfg.vis_percent = std::getenv("DS4_STORE_ZC_FRAC") ? std::atoi(std::getenv("DS4_STORE_ZC_FRAC")) : 50;
        // (the GPU computing the store's experts over PCIe is opt-in, DS4_STORE_ZC=1: measured slower than the CPU lane alone on a
        // 5070 / PCIe 5.0 - the staging copy sits in the layer's critical path - and its answers depend on the timing of which lane
        // took which expert, the CPU lane's are the mmap path's byte for byte)
        const bool want_zc = std::getenv("DS4_STORE_ZC") && std::atoi(std::getenv("DS4_STORE_ZC")) != 0 && devs.size() == 1 &&
                             L[0].nm == 1;
        if (want_zc) {   // the arena's chunks registered for the GPU to read in place (zero-copy over PCIe)
            const int dev0 = devs[0].id;
            {   // (a unified-memory GPU whose budget the weights already fill: the registered store is the same RAM, past the budget the GPU faults)
                cudaDeviceProp zp{};
                size_t zfree = 0, ztotal = 0;
                cudaSetDevice(dev0);
                if (cudaGetDeviceProperties(&zp, dev0) == cudaSuccess && zp.integrated && cudaMemGetInfo(&zfree, &ztotal) == cudaSuccess &&
                    (double) zfree < gb * 1e9)
                    std::fprintf(stderr,
                                 "ds4: DS4_STORE_ZC=1 on a GPU that shares the PC's RAM: the weights already fill its memory budget (%.1f GB left, the store would "
                                 "register up to %.1f GB more), so this will likely fail with a GPU fault. The store is the same RAM either way, zero-copy gains nothing here; "
                                 "leave DS4_STORE_ZC off.\n", (double) zfree / 1e9, gb);
            }
            cfg.map_chunk = [dev0](void* h, size_t n) -> void* {
                cudaSetDevice(dev0);
                unsigned reg_flags = cudaHostRegisterMapped | cudaHostRegisterPortable;
#if defined(STRATA_USE_HIP)
                // (test arm: DS4_ZC_COARSE=1, hipExtHostRegisterCoarseGrained, which ROCm Core SDK 10.1 honors on Windows; the store is read-only to the GPU)
                if (std::getenv("DS4_ZC_COARSE") && std::atoi(std::getenv("DS4_ZC_COARSE")) != 0) reg_flags |= 0x8u;
#endif
                if (cudaHostRegister(h, n, reg_flags) != cudaSuccess) {
                    (void) cudaGetLastError();
                    return nullptr;
                }
                void* d = nullptr;
                if (cudaHostGetDevicePointer(&d, h, 0) != cudaSuccess) {
                    (void) cudaGetLastError();
                    cudaHostUnregister(h);
                    return nullptr;
                }
                if (d != h) std::fprintf(stderr, "ds4: RAM store: chunk host %p -> device %p (not the identity)\n", h, d);
                return d;
            };
            cfg.unmap_chunk = [dev0](void* h) {
                cudaSetDevice(dev0);
                cudaHostUnregister(h);
            };
        }
        bool direct = true;
        for (os::fd_t f : pk.dfds) direct = direct && f != os::kBadFd;
        auto st = std::make_unique<ExpertStore>();
        if (!st->init(cfg, geo, pk.dfds, pk.pfds)) {
            std::fprintf(stderr, "ds4: --ssd-cache: the store could not start\n");
            return;
        }
        store = std::move(st);
        // (the router lookahead's guesses are not read ahead with the store: measured 4.5 against 4.7 tok/s, 62% of the guesses are right and
        // the SSD is the narrow part; DS4_AHEAD=1 turns them on)
        if (std::getenv("DS4_AHEAD") == nullptr) ahead_mode = 0;
        for (Layer& l : L)
            if (l.il < g.nl && want_zc) l.zc.assign((size_t) l.n_exp, 0);
        std::fprintf(stderr, "ds4: RAM store: up to %zu slots of %.1f MB (%.1f GB), policy %d, %d reader threads, %s reads\n",
                     store->slots_max(), store->slot_bytes() / 1e6, store->slots_max() * (double) store->slot_bytes() / 1e9,
                     (int) cfg.policy, cfg.threads, direct ? "unbuffered" : "BUFFERED (no direct handle)");
        if (want_zc) {
            if (!store->gpu_mapped()) {
                std::fprintf(stderr, "ds4: RAM store: the arena could not be mapped for the GPU: zero-copy off\n");
                for (Layer& l : L) l.zc.clear();
            } else {
                zc_stride = (store->max_blob() + 4095) & ~(size_t) 4095;
                cudaSetDevice(devs[0].id);
                if (cudaMalloc((void**) &zc_stage_buf, zc_stride * kPicks) != cudaSuccess) {
                    (void) cudaGetLastError();
                    zc_stage_buf = nullptr;
                    for (Layer& l : L) l.zc.clear();
                } else {
                    for (Layer& l : L)
                        if (!l.zc.empty() && cudaMalloc((void**) &l.zc_tab, (size_t) l.n_exp * 8) == cudaSuccess) cudaMemset(l.zc_tab, 0, (size_t) l.n_exp * 8);
                        else if (!l.zc.empty()) {
                            (void) cudaGetLastError();
                            l.zc.clear();
                        }
                }
            }
            std::fprintf(stderr, "ds4: RAM store: the GPU takes its slots over PCIe (%s), %zu slots kept evictable\n",
                         zc_stage_buf != nullptr ? "copied into a staging area at the PCIe rate first" : "off", cfg.reserve);
        }
    }
    // the profile's hottest experts (VRAM's left out) read into the store before the first token (DS4_STORE_PRELOAD=0: not)
    void preload_store() {
        if (!store) return;
        if (std::getenv("DS4_STORE_PRELOAD") && std::atoi(std::getenv("DS4_STORE_PRELOAD")) == 0) return;
        std::vector<std::pair<double, std::pair<int, int>>> cand;
        double tot = 0;
        for (const Layer& l : L) {
            if (l.il >= g.nl) continue;
            const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
            for (int e = 0; e < l.n_exp; ++e) tot += p[e];
        }
        if (tot <= 0) return;   // (no profile yet: the first tokens fill it)
        for (const Layer& l : L) {
            if (l.il >= g.nl) continue;
            const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] < 0 && p[e] > 0) cand.push_back({(double) p[e] / (double) l.blob, {l.il, e}});
        }
        std::stable_sort(cand.begin(), cand.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
        std::vector<std::pair<int, int>> list;
        list.reserve(cand.size());
        for (const auto& c : cand) list.push_back(c.second);
        // The slots the CPU lane's experts leave over: the experts the VRAM cache holds that the profile counts least (the cache gives
        // up its coldest to the CPU lane, and a store without them reads each from the SSD while the CPU lane waits - 1.8 misses a
        // token on the 251 GB R9700 box, 2.9 ms of a 49 ms token), then the lane's experts the profile never saw.  Last in the list: they
        // take only the slots the likely ones left.  DS4_STORE_SPARE=0: off.
        if (strata::ds4::store_feature_default(env_tri("DS4_STORE_SPARE"), defaults_026())) {
            std::vector<std::pair<double, std::pair<int, int>>> vr, zero;
            for (const Layer& l : L) {
                if (l.il >= g.nl) continue;
                const uint32_t* p = prof.data() + (size_t) l.il * g.n_exp;
                for (int e = 0; e < l.n_exp; ++e) {
                    if (l.slot[(size_t) e] >= 0) vr.push_back({(double) p[e] / (double) l.blob, {l.il, e}});
                    else if (p[e] == 0) zero.push_back({0.0, {l.il, e}});
                }
            }
            std::stable_sort(vr.begin(), vr.end(), [](const auto& a, const auto& b) { return a.first < b.first; });
            for (const auto& c : vr) list.push_back(c.second);
            for (const auto& c : zero) list.push_back(c.second);
        }
        const double t0 = now_ms();
        // (with the spare experts in the list the reserve is theirs: last in the list, so the oldest ticks, so the first a demand read replaces)
        const bool spare_on = strata::ds4::store_feature_default(env_tri("DS4_STORE_SPARE"), defaults_026());
        const size_t leave = spare_on ? 0 : (size_t) (std::getenv("DS4_STORE_RESERVE") ? std::atoi(std::getenv("DS4_STORE_RESERVE")) : 192) + 64;
        // The first 48 GB (what a store held before it could take every expert) are read before the first token; the rest of the
        // hottest-first list is read after it, in pieces of 128 experts on a thread of its own, behind the model's own reads (a
        // guess's priority) - the same bytes.  Opt-in (DS4_STORE_BG=1): "ready" comes 9 s sooner on the 251 GB R9700 box (24 s against 34), but a prompt sent at
        // once then waits for the same SSD (200 tokens: 18.7 s against 9.0), so the first answer starts no sooner and decode after
        // it measured 3.7% lower; it only pays when the first prompt comes more than ~10 s after ready.
        const size_t first = !(std::getenv("DS4_STORE_BG") && std::atoi(std::getenv("DS4_STORE_BG")) == 1)
                                 ? list.size()
                                 : std::min(list.size(), (size_t) (48e9 / (double) std::max<size_t>(1, L[0].blob)));
        const std::vector<std::pair<int, int>> head(list.begin(), list.begin() + (long) first), tail(list.begin() + (long) first, list.end());
        const size_t n = store->preload(head, leave);
        std::fprintf(stderr, "ds4: RAM store: %zu of the profile's hottest experts read in (%.1f GB) in %.1f s%s\n", n,
                     (double) n * (double) L[0].blob / 1e9, (now_ms() - t0) / 1000.0,
                     tail.empty() ? "" : "; the rest is read in the background");
        if (tail.empty()) return;
        store_bg = std::thread([this, tail, leave] {
            const double tb = now_ms();
            size_t got = 0;
            std::vector<std::pair<int, int>> piece;
            for (size_t i = 0; i < tail.size() && !quit.load(std::memory_order_relaxed); i += 128) {
                piece.assign(tail.begin() + (long) i, tail.begin() + (long) std::min(tail.size(), i + 128));
                got += store->preload(piece, leave);
            }
            std::fprintf(stderr, "ds4: RAM store: %zu more experts (%.1f GB) read in the background in %.1f s\n", got,
                         (double) got * (double) L[0].blob / 1e9, (now_ms() - tb) / 1000.0);
        });
    }
    // at a window boundary: the store's ready slots become the device's (zero-copy) experts, taken back when it needs the room;
    // each touched layer's whole table is written again (VRAM slots, the store's, 0), in stream order before the next window
    std::vector<ExpertStore::Vis> sync_ev;   // store_sync's lists, kept (a window's)
    std::vector<char> sync_dirty;
    std::vector<unsigned long long> sync_tab;
    void store_sync() {
        if (!store || !store->gpu_mapped()) return;
        std::vector<ExpertStore::Vis>& ev = sync_ev;
        ev.clear();
        store->sync(ev, [&](int layer, int e) { return L[(size_t) layer].slot[(size_t) e] < 0; });
        if (ev.empty()) return;
        std::vector<char>& dirty = sync_dirty;
        dirty.assign(L.size(), 0);
        for (const auto& v : ev) {
            Layer& l = L[(size_t) v.layer];
            if (l.zc.empty()) continue;
            l.zc[(size_t) v.e] = v.dev != 0 ? 1 : 0;
            dirty[(size_t) v.layer] = 1;
        }
        for (Layer& l : L) {
            if (!dirty[(size_t) l.il]) continue;
            if (l.zc_tab == nullptr) continue;
            std::vector<unsigned long long>& tab = sync_tab;   // (pageable: the copy has it staged when the call returns,
            tab.assign((size_t) l.n_exp, 0ull);                //  as with the local vector this was)
            for (int e = 0; e < l.n_exp; ++e)
                if (l.zc[(size_t) e]) {
                    const int s = l.slot[(size_t) e] < 0 ? store->find(l.il, e) : -1;
                    tab[(size_t) e] = s >= 0 ? store->dev_blob(s) : 0ull;
                    if (s < 0) l.zc[(size_t) e] = 0;
                }
            cudaSetDevice(devs[0].id);
            cudaMemcpyAsync(l.zc_tab, tab.data(), tab.size() * 8, cudaMemcpyHostToDevice, devs[0].st);
        }
    }

    int cpu_threads() const {
        int n = 0;
        for (const auto& pl : pools) n += pl->size() - 1;
        return n + 1;
    }
    // the CPU lane's workers: a pool per NUMA node (NH of them) on its cores; in place with one part, one pool over
    // every node's cores (the pages lie where the cache put them)
    void make_pools() {
        std::vector<std::vector<int>> cs = cores;
        if ((int) cs.size() < NH && !cs.empty()) {   // (DS4_COPY_NUMA=2 on one node, a test: its cores split in NH)
            std::vector<int> all = cs[0];
            cs.assign((size_t) NH, {});
            for (size_t i = 0; i < all.size(); ++i) cs[i * (size_t) NH / all.size()].push_back(all[i]);
        }
        static const int lane_free = [] {
            const char* v = std::getenv("STRATA_DS4_LANE_FREE");
            return v != nullptr ? std::max(0, std::atoi(v)) : 2;
        }();
        size_t lane_cpus = 0;
        for (const auto& v : cs) lane_cpus += v.size();
        const bool lane_takes_all = lane_cpus >= (size_t) std::max(1u, std::thread::hardware_concurrency());
        for (int X = 0; X < (int) cs.size() && X < std::max(NH, 1); ++X) {
            std::vector<int> c = cs[(size_t) X];
            if (file_experts && NH == 1)
                for (size_t Y = 1; Y < cs.size(); ++Y) c.insert(c.end(), cs[Y].begin(), cs[Y].end());
            if (X == 0 && !c.empty()) c.erase(c.begin());   // the host thread's core (it helps node 0's pool)
            // cores of the first pool left free beside the host thread's, for the thread that launches the decode's kernels
            // (and waits on the device) and whatever else the PC runs: with a worker spinning on every other logical CPU
            // that thread waits for a core (Project Maya #359, a 20-core Windows 11 PC: decode 28.3 -> 55.5 tok/s).  Only
            // when the lane would take every logical CPU and --cpu-threads is not given.
            // STRATA_DS4_LANE_FREE: the cores left free (2 by default, 0: as before)
            if (X == 0 && o.cpu_threads <= 0 && lane_free > 0 && (int) c.size() > lane_free + 1 && lane_takes_all)
                c.resize(c.size() - (size_t) lane_free);
            int nw = (int) c.size();
            if (o.cpu_threads > 0) nw = std::max(X == 0 ? 0 : 1, std::min(nw, o.cpu_threads / NH - (X == 0 ? 1 : 0)));
            pools.push_back(std::make_unique<Pool>(nw, c, 20000));   // spin through a token's layers (20 ms)
        }
        (void) gg::mx_tier();   // (measured here, not on the first token)
        if (o.verbose) {
            int nthr = 0;
            for (auto& p : pools) nthr += p->size();
            std::fprintf(stderr, "ds4: CPU lane: %d threads, MXFP4 rows %s (%s)\n", nthr, gg::mx_tier_name(gg::mx_tier()),
                         gg::mx_tier_report());
        }
    }

    void reset() {
        pos = 0;
        toks.clear();
        ctoks.clear();
        toks.reserve((size_t) o.max_context);   // the whole context now - a decode's push_back never grows the heap
        ctoks.reserve((size_t) o.max_context);
        slot_held = false;
        for (Check& c0 : ck) c0.pos = -1;
        for (Layer& l0 : L)
            for (int m = 0; m < l0.nm; ++m) {
                Layer& l = member(l0, m);
                Dev& d = devs[(size_t) l.dev];
                cudaSetDevice(d.id);
                cudaMemsetAsync(l.win, 0, (size_t) g.win * win_rb(), d.st);
                if (l.c_kv) cudaMemsetAsync(l.c_kv, 0, (size_t) l.ratio * g.hd * 4, d.st);
                if (l.c_score) cudaMemsetAsync(l.c_score, 0, (size_t) l.ratio * g.hd * 4, d.st);
            }
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
    }

    // the state at pos into checkpoint `slot` (the window rings and the compressors' partial groups: the rest of the
    // state is indexed by position, and what lies past a restored position is written again)
    void checkpoint(int slot) {
        Check& c = ck[slot & (kChecks - 1)];
        c.pos = pos;
        c.win.resize(L.size());
        c.comp.resize(L.size() * 2);
        for (size_t i = 0; i < L.size(); ++i) {
            Layer& l = L[i];
            Dev& d = devs[(size_t) l.dev];
            cudaSetDevice(d.id);
            c.win[i].resize((size_t) g.win * win_rb());
            cudaMemcpyAsync(c.win[i].data(), l.win, c.win[i].size(), cudaMemcpyDeviceToHost, d.st);
            if (l.c_kv) {
                c.comp[2 * i].resize((size_t) l.ratio * g.hd);
                c.comp[2 * i + 1].resize((size_t) l.ratio * g.hd);
                cudaMemcpyAsync(c.comp[2 * i].data(), l.c_kv, c.comp[2 * i].size() * 4, cudaMemcpyDeviceToHost, d.st);
                cudaMemcpyAsync(c.comp[2 * i + 1].data(), l.c_score, c.comp[2 * i + 1].size() * 4,
                                cudaMemcpyDeviceToHost, d.st);
            }
        }
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
    }

    // the checkpoint at or before position limit (the state's tokens agree with a new prompt up to there), or -1
    int best_check(int64_t limit) const {
        int b = -1;
        for (int i = 0; i < kChecks; ++i)
            if (ck[i].pos >= 0 && ck[i].pos <= limit && ck[i].pos <= pos && (b < 0 || ck[i].pos > ck[b].pos)) b = i;
        return b;
    }
    int64_t restorable(int64_t limit) const {
        const int b = best_check(limit);
        return b < 0 ? -1 : ck[b].pos;
    }

    // checkpoint 1 (the position before the last prompt's end) becomes the anchor too
    void pin() {
        if (ck[1].pos > 0) ck[2] = ck[1];
    }
    // the checkpoints the state can go back to (what a slot of it keeps), latest first
    std::vector<int64_t> check_positions() const {
        std::vector<int64_t> v;
        for (const Check& c : ck)
            if (c.pos > 0 && c.pos <= pos && c.win.size() == L.size() &&
                std::find(v.begin(), v.end(), c.pos) == v.end())
                v.push_back(c.pos);
        std::sort(v.rbegin(), v.rend());
        return v;
    }
    // the checkpoints a slot keeps (each with its role: 0, 1 or the anchor)
    std::vector<int> slot_checks() const {
        std::vector<int> v;
        for (int i = 0; i < kChecks; ++i)
            if (ck[i].pos > 0 && ck[i].pos <= pos && ck[i].win.size() == L.size()) v.push_back(i);
        return v;
    }
    size_t check_bytes() const {
        size_t n = 16;
        for (const Layer& l : L) n += (size_t) g.win * win_rb() + (l.c_kv ? 2 * (size_t) l.ratio * g.hd * 4 : 0);
        return n;
    }

    bool restore(int64_t limit) {
        const int b = best_check(limit);
        if (b < 0) return false;
        const Check& c = ck[b];
        for (size_t i = 0; i < L.size(); ++i)
            for (int m = 0; m < L[i].nm; ++m) {   // (a group's members hold the same state: the lead's copy)
                Layer& l = member(L[i], m);
                Dev& d = devs[(size_t) l.dev];
                cudaSetDevice(d.id);
                cudaMemcpyAsync(l.win, c.win[i].data(), c.win[i].size(), cudaMemcpyHostToDevice, d.st);
                if (l.c_kv) {
                    cudaMemcpyAsync(l.c_kv, c.comp[2 * i].data(), c.comp[2 * i].size() * 4, cudaMemcpyHostToDevice, d.st);
                    cudaMemcpyAsync(l.c_score, c.comp[2 * i + 1].data(), c.comp[2 * i + 1].size() * 4,
                                    cudaMemcpyHostToDevice, d.st);
                }
            }
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
        pos = c.pos;
        toks.resize((size_t) pos);
        ctoks.resize((size_t) pos);
        slot_held = false;
        for (Check& o2 : ck)   // a later checkpoint saw tokens the state no longer has
            if (o2.pos > pos) o2.pos = -1;
        return true;
    }

    // ---- the kept conversations (a slot): the state out of the model and back, through a file or a host buffer.
    // A prompt that continues the state is reused in place (checkpoint / restore, the compressed KV left where it is);
    // a conversation that leaves the model for another one is a slot - the whole state: the position, its tokens,
    // every window ring (the DSpark blocks' included), the compressors' partial groups and each KV source's compressed
    // KV and index keys up to it (rows 0 .. pos / ratio, the groups its position completed; one the prompt has not
    // completed yet lives in the compressor's partial group).  A tensor parallel group's members hold the same state,
    // so one member's ring is saved and written back into all of them.  Text only: a conversation that holds pictures
    // is not a slot (the Engram history's rows are the tokens' again, no -1 among them).
    static constexpr uint64_t kSlotMagic = 0x31544f4c53345344ull;   // "DS4SLOT1" (little endian)

    int64_t src_rows(const Src& s) const { return pos / std::max(1, s.ratio); }

    // the slot's bytes: the header, the tokens, every layer's ring and partial group, every source's rows, the end
    size_t slot_bytes() const {
        size_t n = 8 + 8 + slot_identity().size() + 8 + (size_t) pos * 4;
        for (const Layer& l : L) n += 8 + (size_t) g.win * win_rb() + 8 + (l.c_kv ? 2 * (size_t) l.ratio * g.hd * 4 : 0);
        for (const Src& s : srcs) n += 8 + (size_t) src_rows(s) * (ckv_rb() + ik_rb());
        n += 8 + slot_checks().size() * check_bytes();   // (the checkpoints: what the slot can be taken back at)
        return n + 8;
    }

    uint64_t slot_save(std::vector<uint8_t>& out, std::string& err) {
        if (slot_held) {
            err = "it is already set aside";
            return 0;
        }
        if (pos <= 0) {
            err = "there is no conversation";
            return 0;
        }
        if ((int64_t) toks.size() != pos) {
            err = "the state's tokens do not match its position";
            return 0;
        }
        if (!imgs.empty()) {
            err = "it holds pictures";
            return 0;
        }
        const std::string id = slot_identity();
        out.assign(slot_bytes(), 0);
        uint8_t* p = out.data();
        size_t off = 0;
        const auto put = [&](const void* s, size_t b) {
            std::memcpy(p + off, s, b);
            off += b;
        };
        const uint64_t il = id.size(), n = (uint64_t) pos;
        put(&kSlotMagic, 8);
        put(&il, 8);
        put(id.data(), (size_t) il);
        put(&n, 8);
        put(toks.data(), (size_t) n * 4);
        for (Dev& d : devs) {   // (the devices' work ends before their state is read)
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
        for (size_t i = 0; i < L.size(); ++i) {
            const Layer& l = L[i];
            const Dev& d = devs[(size_t) l.dev];
            cudaSetDevice(d.id);
            const uint64_t wb = (uint64_t) g.win * win_rb();
            put(&wb, 8);
            if (cudaMemcpy(p + off, l.win, (size_t) wb, cudaMemcpyDeviceToHost) != cudaSuccess) {
                err = l.name + "window ring: " + cudaGetErrorString(cudaGetLastError());
                return 0;
            }
            off += (size_t) wb;
            const uint64_t cn = l.c_kv ? (uint64_t) l.ratio * (uint64_t) g.hd : 0;
            put(&cn, 8);
            if (cn > 0) {
                const size_t cb = (size_t) cn * 4;
                if (cudaMemcpy(p + off, l.c_kv, cb, cudaMemcpyDeviceToHost) != cudaSuccess ||
                    cudaMemcpy(p + off + cb, l.c_score, cb, cudaMemcpyDeviceToHost) != cudaSuccess) {
                    err = l.name + "compressor's group: " + cudaGetErrorString(cudaGetLastError());
                    return 0;
                }
                off += 2 * cb;
            }
        }
        for (const Src& s : srcs) {
            const uint64_t rows = (uint64_t) src_rows(s);
            put(&rows, 8);
            if (rows == 0) continue;
            const int di = L[(size_t) s.layer].dev;
            const uint8_t* ckv = s.ckv[(size_t) di];
            const uint8_t* ik = s.ik[(size_t) di];   // (a pack whose sources are not index sources: none, zeros)
            if (ckv == nullptr) {
                err = "source layer " + std::to_string(s.layer) + "'s rows are not on its device";
                return 0;
            }
            const size_t cb = (size_t) rows * ckv_rb(), ib = (size_t) rows * ik_rb();
            cudaSetDevice(devs[(size_t) di].id);
            if (cudaMemcpy(p + off, ckv, cb, cudaMemcpyDeviceToHost) != cudaSuccess ||
                (ik != nullptr && cudaMemcpy(p + off + cb, ik, ib, cudaMemcpyDeviceToHost) != cudaSuccess)) {
                err = "source layer " + std::to_string(s.layer) + "'s compressed KV: " + cudaGetErrorString(cudaGetLastError());
                return 0;
            }
            off += cb + ib;
        }
        {
            const std::vector<int> cs = slot_checks();
            const uint64_t nc = cs.size();
            put(&nc, 8);
            for (int k : cs) {
                const Check& c = ck[k];
                const uint64_t role = (uint64_t) k, cp = (uint64_t) c.pos;
                put(&role, 8);
                put(&cp, 8);
                for (size_t i = 0; i < L.size(); ++i) {
                    put(c.win[i].data(), (size_t) g.win * win_rb());
                    if (L[i].c_kv) {
                        put(c.comp[2 * i].data(), (size_t) L[i].ratio * g.hd * 4);
                        put(c.comp[2 * i + 1].data(), (size_t) L[i].ratio * g.hd * 4);
                    }
                }
            }
        }
        if (off + 8 != out.size()) {
            err = "the state's size does not add up";
            return 0;
        }
        put(&kSlotMagic, 8);
        slot_held = true;
        return (uint64_t) off;
    }

    bool slot_load(const uint8_t* data, size_t bytes, int64_t n_pos, std::string& err) {
        size_t off = 0;
        bool wrote = false, ok = false;
        // a load that stops after some of another conversation's state went into the layers leaves a state no
        // checkpoint can repair: it is reset (the prompt is read from token 0), never served from the mix
        struct FailClosed {
            Impl& p;
            const bool& wrote;
            const bool& ok;
            ~FailClosed() {
                if (!ok && wrote) p.reset();
            }
        } guard{*this, wrote, ok};
        const auto room = [&](size_t b) { return b <= bytes && off <= bytes - b; };
        uint64_t magic = 0, il = 0, n = 0;
        if (!room(16)) {
            err = "the slot is cut short";
            return false;
        }
        std::memcpy(&magic, data + off, 8);
        std::memcpy(&il, data + off + 8, 8);
        off += 16;
        if (magic != kSlotMagic || il == 0 || il > (1u << 20)) {
            err = "not a saved conversation";
            return false;
        }
        if (!room((size_t) il + 8)) {
            err = "the slot is cut short";
            return false;
        }
        {
            std::string id((size_t) il, '\0');
            std::memcpy(id.data(), data + off, (size_t) il);
            off += (size_t) il;
            std::memcpy(&n, data + off, 8);
            off += 8;
            if (id != slot_identity()) {
                err = "another model's, or another engine version's, conversation";
                return false;
            }
        }
        if (n != (uint64_t) n_pos || n_pos <= 0 || n_pos > o.max_context || !room((size_t) n * 4)) {
            err = "the conversation's position is not this prompt's";
            return false;
        }
        std::vector<int32_t> toks_in((size_t) n);
        std::memcpy(toks_in.data(), data + off, (size_t) n * 4);
        off += (size_t) n * 4;
        for (Dev& d : devs) {   // (their work ends before the state is written over)
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
        for (size_t i = 0; i < L.size(); ++i) {
            Layer& l = L[i];
            const Dev& d = devs[(size_t) l.dev];
            cudaSetDevice(d.id);
            uint64_t wb = 0, cn = 0;
            if (!room(8)) {
                err = "the slot is cut short";
                return false;
            }
            std::memcpy(&wb, data + off, 8);
            off += 8;
            if (wb != (uint64_t) g.win * win_rb() || !room((size_t) wb + 8)) {
                err = l.name + "window ring of another size";
                return false;
            }
            wrote = true;
            for (int m = 0; m < l.nm; ++m) {
                Layer& lm = member(l, m);
                cudaSetDevice(devs[(size_t) lm.dev].id);   // (a tensor-parallel group's members sit on different GPUs: #4350)
                if (cudaMemcpy(lm.win, data + off, (size_t) wb, cudaMemcpyHostToDevice) != cudaSuccess) {
                    err = l.name + "window ring: " + cudaGetErrorString(cudaGetLastError());
                    return false;
                }
            }
            off += (size_t) wb;
            std::memcpy(&cn, data + off, 8);
            off += 8;
            if (cn != (l.c_kv ? (uint64_t) l.ratio * (uint64_t) g.hd : 0)) {
                err = l.name + "compressor's group of another size";
                return false;
            }
            if (cn > 0) {
                const size_t cb = (size_t) cn * 4;
                if (!room(2 * cb)) {
                    err = "the slot is cut short";
                    return false;
                }
                for (int m = 0; m < l.nm; ++m) {
                    Layer& lm = member(l, m);
                    cudaSetDevice(devs[(size_t) lm.dev].id);
                    if (cudaMemcpy(lm.c_kv, data + off, cb, cudaMemcpyHostToDevice) != cudaSuccess ||
                        cudaMemcpy(lm.c_score, data + off + cb, cb, cudaMemcpyHostToDevice) != cudaSuccess) {
                        err = l.name + "compressor's group: " + cudaGetErrorString(cudaGetLastError());
                        return false;
                    }
                }
                off += 2 * cb;
            }
        }
        for (const Src& s : srcs) {
            uint64_t rows = 0;
            if (!room(8)) {
                err = "the slot is cut short";
                return false;
            }
            std::memcpy(&rows, data + off, 8);
            off += 8;
            if (rows != (uint64_t) (n_pos / std::max(1, s.ratio))) {
                err = "source layer " + std::to_string(s.layer) + "'s rows are not this conversation's";
                return false;
            }
            if (rows == 0) continue;
            const size_t cb = (size_t) rows * ckv_rb(), ib = (size_t) rows * ik_rb();
            if (!room(cb + ib)) {
                err = "the slot is cut short";
                return false;
            }
            for (size_t di = 0; di < devs.size(); ++di) {
                if (s.ckv[di] == nullptr && s.ik[di] == nullptr) continue;
                cudaSetDevice(devs[di].id);
                if (s.ckv[di] != nullptr && cudaMemcpy(s.ckv[di], data + off, cb, cudaMemcpyHostToDevice) != cudaSuccess) {
                    err = "source layer " + std::to_string(s.layer) + "'s compressed KV: " + cudaGetErrorString(cudaGetLastError());
                    return false;
                }
                if (s.ik[di] != nullptr &&
                    cudaMemcpy(s.ik[di], data + off + cb, ib, cudaMemcpyHostToDevice) != cudaSuccess) {
                    err = "source layer " + std::to_string(s.layer) + "'s index keys: " + cudaGetErrorString(cudaGetLastError());
                    return false;
                }
            }
            off += cb + ib;
        }
        Check got[kChecks];   // the slot's checkpoints: the positions it can be taken back at
        {
            uint64_t nc = 0;
            if (!room(8)) {
                err = "the slot is cut short";
                return false;
            }
            std::memcpy(&nc, data + off, 8);
            off += 8;
            if (nc > (uint64_t) kChecks) {
                err = "the slot's checkpoints are damaged";
                return false;
            }
            for (uint64_t k = 0; k < nc; ++k) {
                uint64_t role = 0, cp = 0;
                if (!room(16)) {
                    err = "the slot is cut short";
                    return false;
                }
                std::memcpy(&role, data + off, 8);
                std::memcpy(&cp, data + off + 8, 8);
                off += 16;
                if (role >= (uint64_t) kChecks || got[role].pos >= 0 || cp == 0 || cp > (uint64_t) n_pos) {
                    err = "the slot's checkpoints are damaged";
                    return false;
                }
                Check& c = got[role];
                c.pos = (int64_t) cp;
                c.win.resize(L.size());
                c.comp.resize(L.size() * 2);
                for (size_t i = 0; i < L.size(); ++i) {
                    const size_t wb = (size_t) g.win * win_rb(), cb = L[i].c_kv ? (size_t) L[i].ratio * g.hd * 4 : 0;
                    if (!room(wb + 2 * cb)) {
                        err = "the slot is cut short";
                        return false;
                    }
                    c.win[i].assign(data + off, data + off + wb);
                    off += wb;
                    if (cb > 0) {
                        c.comp[2 * i].resize(cb / 4);
                        c.comp[2 * i + 1].resize(cb / 4);
                        std::memcpy(c.comp[2 * i].data(), data + off, cb);
                        std::memcpy(c.comp[2 * i + 1].data(), data + off + cb, cb);
                        off += 2 * cb;
                    }
                }
            }
        }
        uint64_t end = 0;
        if (!room(8)) {
            err = "the slot is cut short";
            return false;
        }
        std::memcpy(&end, data + off, 8);
        off += 8;
        if (end != kSlotMagic) {
            err = "the slot does not end where it should";
            return false;
        }
        pos = n_pos;
        toks.swap(toks_in);
        ctoks.resize((size_t) pos);
        for (size_t i = 0; i < (size_t) pos; ++i)
            ctoks[i] = toks[i] < pk.eg_vocab ? pk.eg_map[(size_t) toks[i]] : 0;
        for (int k = 0; k < kChecks; ++k) ck[k] = std::move(got[k]);   // (the slot's own; the old ones held the state
                                                               // this one replaced)
        slot_held = false;
        ok = true;
        return true;
    }

    std::string slot_identity() const {
        const auto size_of = [](const std::string& p) {
            std::error_code ec;
            const auto s = std::filesystem::file_size(p, ec);
            return ec ? 0ull : (unsigned long long) s;
        };
        std::ostringstream id;
        id << "strata-ds4-session-3 engine=" << STRATA_VERSION << " mtp=" << g.n_mtp << " dim=" << g.dim << " hd=" << g.hd
           << " win=" << g.win << " ratios=";
        for (int r : g.ratios) id << r << ",";
        id << " kv=";
        for (int v : g.kv_src) id << v << ",";
        id << " ix=";
        for (int v : g.ix_src) id << v << ",";
        id << " ds4.txt:" << size_of(pk.dir + "/ds4.txt") << " engram.bin:" << size_of(pk.dir + "/engram.bin")
           << " tensors.txt:" << size_of(pk.dir + "/tensors.txt");
        for (size_t i = 0; i < pk.files.size(); ++i)
            id << " " << pk.files[i] << ":" << os::file_size(pk.fds[i]);
        return id.str();
    }

    size_t bounce_bytes() const {
        return (size_t) kWin * ((size_t) g.hc * g.dim * 4 + 8 * 4 + topk_stride() * 4 + cand_stride() * 4);
    }
    size_t topk_stride() const { return (size_t) std::max(g.ix_topk, 32); }
    unsigned* tmb_of(const Dev& d) const { return topk_mb > 0 ? d.tmb : nullptr; }   // (DS4_TOPK_MB=1: its scratch)
    // (DS4_TOPK_MB_BATCH=1) a batch run's scratch: DS4_TOPK_MB's d.tmb, or null (the one-workgroup kernel, as before)
    unsigned* tmb_bt(const Dev& d) const { return topk_mb > 0 && topk_mb_batch > 0 ? d.tmb : nullptr; }
    // (DS4_TOPK_MB_BATCH=1) the one-time line once a batch run's widest top-k row reaches DS4_TOPK_MB_MIN
    void tmb_bt_note(const Dev& d, const Rows& r, int n) {
        if (tmb_bt(d) == nullptr || n < 1 || n > kWin) return;
        int w = 0;
        for (int t = 0; t < n; ++t) w = std::max(w, r.n[t]);
        if (w >= topk_mb_min && tmb_bt_said.exchange(1) == 0)
            std::fprintf(stderr, "ds4: DS4_TOPK_MB_BATCH engaged: a batch run of %d rows, a top-k over %d scores, took the "
                                 "multi-block path\n", n, w);
    }
    size_t cand_stride() const { return (size_t) std::max(g.cand_topk, 32); }
    size_t bm_stride() const { return (size_t) (o.max_context + 64) / std::max(1, g.cand_blk) + 64; }
    static constexpr int kSlots = kWin * kPicks;   // the CPU lane's (token, expert) rows a window can need

    // ---- the vision tower (the checkpoint's vision.* / aligner.*) on the first GPU, its weights streamed from the
    // host; a prompt's pictures as their spans' rows (set_images)
    VisionTower vt;
    VisionGeo vg;
    int img_tok = -1;
    std::string vision_err;              // why the tower did not load (pictures off), or empty
    std::vector<uint16_t> img_mark[3];   // image_start, image_newline, image_end: BF16 [dim]
    std::vector<Image> imgs;             // the pictures of the prompt being fed, by start
    // a BF16 (or, rounded to nearest even, F32) tensor of n values into dst
    bool read_bf16(const Tensor& t, size_t n, void* dst) {
        if (t.dtype == "BF16") return t.bytes == n * 2 && pk.read(t, dst);
        if (t.dtype != "F32" || t.bytes != n * 4) return false;
        std::vector<float> f(n);
        if (!pk.read(t, f.data())) return false;
        uint16_t* o = (uint16_t*) dst;
        for (size_t i = 0; i < n; ++i) {
            uint32_t u;
            std::memcpy(&u, &f[i], 4);
            o[i] = (uint16_t) ((u + 0x7FFFu + ((u >> 16) & 1u)) >> 16);
        }
        return true;
    }
    bool load_vision(std::string& err) {
        vg.layers = (int) pk.num("vision.num_hidden_layers", 0);
        const int tok = (int) pk.num("image_token_id", -1);
        if (vg.layers <= 0 || tok < 0 || pk.get("vision.patch_embed.proj.weight") == nullptr) return true;   // none
        vg.dim = (int) pk.num("vision.hidden_size", 1024), vg.heads = (int) pk.num("vision.num_attention_heads", 16);
        vg.inter = (int) pk.num("vision.intermediate_size", 2816), vg.patch = (int) pk.num("vision.patch_size", 14);
        vg.merge = (int) pk.num("vision.downsample_ratio", 3), vg.theta = (float) pk.num("vision.rope_theta", 1e4);
        vg.max_tokens = (int) pk.num("vision.max_image_tokens", 1024), vg.out = g.dim;
        const char* mark[3] = {"image_start", "image_newline", "image_end"};
        for (int i = 0; i < 3; ++i) {
            const Tensor* t = pk.get(mark[i]);
            img_mark[i].resize((size_t) g.dim);
            if (t == nullptr || !read_bf16(*t, (size_t) g.dim, img_mark[i].data())) {
                err = std::string(mark[i]) + ": not a BF16 (or F32) row of the model's width";
                return false;
            }
        }
        const double t0 = now_ms();
        Dev& d = devs[0];
        // the tower's tensors as BF16: the checkpoint's own, or a GGUF's mmproj (F32 norms / biases / marker rows, which
        // came from BF16, converted back exactly; mlp.w1 as the two files' gate and up, the halves of its rows)
        auto read = [this](const std::string& n, std::vector<int64_t>& shape, void* dst) {
            const Tensor* t = pk.get(n);
            if (t == nullptr && n.size() > 13 && n.compare(n.size() - 13, 13, "mlp.w1.weight") == 0) {
                const std::string pre = n.substr(0, n.size() - 13);
                const Tensor* tg = pk.get(pre + "mlp.gate.weight");
                const Tensor* tu = pk.get(pre + "mlp.up.weight");
                if (tg == nullptr || tu == nullptr || tg->shape.size() != 2 || tg->shape != tu->shape) return false;
                shape = {tg->shape[0] * 2, tg->shape[1]};
                const size_t half = (size_t) tg->shape[0] * (size_t) tg->shape[1];
                return dst == nullptr || (read_bf16(*tg, half, dst) && read_bf16(*tu, half, (uint16_t*) dst + half));
            }
            if (t == nullptr) return false;
            shape = t->shape;
            size_t n_el = 1;
            for (int64_t x : t->shape) n_el *= (size_t) x;
            return dst == nullptr || read_bf16(*t, n_el, dst);
        };
        if (!vt.load(vg, d.id, read, err)) return false;
        img_tok = tok;
        CK(cudaSetDevice(d.id));
        CK(cudaMemGetInfo(&d.free0, &d.total));   // (the split sees what the tower left)
        d.free0 = uma_free(d.id, d.free0);
        if (o.verbose)
            std::fprintf(stderr, "ds4: vision tower (%d blocks) on CUDA%d: %.0f MiB, up to %d patches, %.1f s\n",
                         vg.layers, d.id, (double) vt.device_bytes() / (1 << 20), vt.max_patches(),
                         (now_ms() - t0) / 1000.0);
        return true;
    }
    bool encode_image(const uint8_t* rgb, int w, int h, std::vector<uint16_t>& span, std::string& err) {
        if (img_tok < 0) {
            err = "this model has no vision tower (or it is off)";
            return false;
        }
        std::vector<uint16_t> rows;
        int nh = 0, nw = 0;
        if (!vt.encode(rgb, w, h, rows, nh, nw, err)) return false;
        const size_t D = (size_t) g.dim;
        span.resize(((size_t) nh * (nw + 1) + 2) * D);
        uint16_t* o = span.data();
        auto put = [&](const uint16_t* r) {
            std::memcpy(o, r, D * 2);
            o += D;
        };
        put(img_mark[0].data());
        for (int i = 0; i < nh; ++i) {
            for (int j = 0; j < nw; ++j) put(rows.data() + ((size_t) i * nw + j) * D);
            put(img_mark[1].data());
        }
        put(img_mark[2].data());
        return true;
    }
    // the row of a picture's span at position p (null: p is in none)
    const uint16_t* image_row(int64_t p) const {
        if (imgs.empty()) return nullptr;
        auto it = std::upper_bound(imgs.begin(), imgs.end(), p, [](int64_t v, const Image& im) { return v < im.start; });
        if (it == imgs.begin()) return nullptr;
        const Image& im = *(it - 1);
        const int64_t r = p - im.start;
        if (!im.rows || r >= (int64_t) (im.rows->size() / (size_t) g.dim)) return nullptr;
        return im.rows->data() + (size_t) r * g.dim;
    }
    // token tk's embedding row at position p: inside a picture's span, the picture's
    const uint16_t* emb_row(int64_t p, int tk) const {
        const uint16_t* r = tk == img_tok ? image_row(p) : nullptr;
        return r != nullptr ? r : embed_pinned + (size_t) tk * g.dim;
    }
    bool in_image(int64_t p) const { return img_tok >= 0 && toks[(size_t) p] == img_tok && image_row(p) != nullptr; }
    // the Engram's compressed id of token tk at p (-1: a picture's, which no n-gram spans)
    int32_t ctok(int64_t p, int tk) const {
        if (tk == img_tok && image_row(p) != nullptr) return -1;
        return tk < pk.eg_vocab ? pk.eg_map[(size_t) tk] : 0;
    }
    // a chunk's image rows (route()'s bits); false: none
    bool vl_bits(int64_t p0, int T, VlBits& b) const {
        if (imgs.empty()) return false;
        std::memset(&b, 0, sizeof b);
        bool any = false;
        for (int t = 0; t < T && t < kVlRows; ++t)
            if (in_image(p0 + t)) {
                b.w[t >> 5] |= 1u << (t & 31);
                any = true;
            }
        return any;
    }

    // ---- Engram: a window's rows of one table (Engram layer li), tokens p0 .. p0 + T - 1 into dst ([token] of [cols]
    // [hd] codes then the scales; nullptr: h_eg).  eg_issue serves the rows already fetched from the row cache (and a
    // row the window needs twice from one read) and hands the rest to the reader's threads; eg_finish waits for them,
    // copies the repeats and keeps the new rows in the cache.  The rows are the file's bytes either way.
    // (DS4_BATCH_DECODE: rpos / rtoks give each row its own position and its own sequence's Engram ids - a batch
    // window's rows are B sequences, one token each; null: positions p0 .., this state's ctoks)
    void eg_issue(int64_t p0, int T, int li, uint8_t* dst, EgBatch& b, const int64_t* rpos = nullptr,
                  const std::vector<int32_t>* const* rtoks = nullptr) {
        const int cols = (pk.eg_ngram - 1) * pk.eg_heads, hd = pk.eg_hd;
        const size_t per = (size_t) cols * (hd + hd / 32);
        b.clear();
        b.reads.reserve((size_t) T * cols);
        b.dups.reserve((size_t) T * cols);
        b.ok.reserve((size_t) T * cols);
        // the tensors from load (no name strings a call), and the batch's "row read already" set in a table this thread
        // keeps (open addressing; a decode window clears only its own few slots) - a decode token allocates nothing here
        const Tensor* tw = eg_tw[(size_t) li];
        const Tensor* ts = eg_ts[(size_t) li];
        const int fmt = eg_fmt[(size_t) li];
        const bool mx8 = fmt == 0;   // (a GGUF: the scales between the codes, one per 32)
        const bool q6k = fmt == 1;   // (a GGUF: one Q6_K superblock a 256 values, its scales inside)
        const bool iq4 = fmt == 2;   // (a GGUF: 18-byte blocks a 32 values, d and 16 nibble bytes, no scales)
        struct Seen {   // a row this batch reads already -> its read
            std::vector<uint64_t> key;   // ~0: empty
            std::vector<int> val;
            size_t mask = 0;
            void reset(size_t n) {
                size_t cap = 64;
                while (cap < 2 * n) cap <<= 1;
                if (key.size() < cap) {
                    key.assign(cap, ~uint64_t{0});
                    val.assign(cap, 0);
                } else {
                    std::fill(key.begin(), key.begin() + (ptrdiff_t) cap, ~uint64_t{0});
                }
                mask = cap - 1;
            }
            static size_t h(uint64_t k) { return (size_t) ((k * 0x9E3779B97F4A7C15ull) >> 17); }
            int find(uint64_t k) const {
                for (size_t i = h(k) & mask;; i = (i + 1) & mask) {
                    if (key[i] == ~uint64_t{0}) return -1;
                    if (key[i] == k) return val[i];
                }
            }
            void put(uint64_t k, int v) {
                size_t i = h(k) & mask;
                while (key[i] != ~uint64_t{0}) i = (i + 1) & mask;
                key[i] = k;
                val[i] = v;
            }
        };
        thread_local Seen first;
        first.reset((size_t) T * (size_t) cols);
        int64_t hits = 0;
        {
            std::lock_guard<std::mutex> lk(eg_cache_mu);
            for (int t = 0; t < T; ++t) {
                const int64_t p = rpos != nullptr ? rpos[t] : p0 + t;
                const std::vector<int32_t>& ctoks = rtoks != nullptr ? *rtoks[t] : this->ctoks;
                uint8_t* rows = dst != nullptr ? dst + (size_t) t * per : h_eg + ((size_t) li * eg_cap + t) * per;
                uint8_t* scales = rows + (size_t) cols * hd;
                if (ctoks[(size_t) p] < 0) {   // a picture's token: no rows (zeros: its gate adds nothing)
                    std::memset(rows, 0, per);
                    continue;
                }
                int64_t prod[8];
                bool blocked = false;
                for (int s = 0; s < pk.eg_ngram; ++s) {   // (the look-back stops at the start and at a picture)
                    blocked = blocked || p < s || ctoks[(size_t) (p - s)] < 0;
                    const int64_t tk = blocked ? pk.eg_pad : ctoks[(size_t) (p - s)];
                    prod[s] = tk * pk.eg_mult[(size_t) li * pk.eg_ngram + s];
                }
                int64_t rolling = prod[0];
                for (int n = 1; n < pk.eg_ngram; ++n) {
                    rolling ^= prod[n];
                    for (int h = 0; h < pk.eg_heads; ++h) {
                        const int c = (n - 1) * pk.eg_heads + h;
                        const int64_t id = rolling % pk.eg_primes[(size_t) li * cols + c] + pk.eg_off[(size_t) li * cols + c];
                        uint8_t* rd = rows + (size_t) c * hd;
                        uint8_t* sd = scales + (size_t) c * (hd / 32);
                        const uint64_t key = (uint64_t) id * 8 + (uint64_t) li;
                        if (const uint8_t* hit = eg_cache.find(key)) {
                            std::memcpy(rd, hit, (size_t) hd);
                            std::memcpy(sd, hit + hd, (size_t) hd / 32);
                            ++hits;
                            continue;
                        }
                        const int fi = first.find(key);
                        if (fi >= 0) {
                            b.dups.push_back({fi, {rd, sd}});
                            continue;
                        }
                        first.put(key, (int) b.reads.size());
                        EgRead r;
                        r.file = tw->file;
                        r.dst = rd;
                        r.scales = sd;
                        r.key = key;
                        if (mx8) {
                            r.mx8 = true;
                            r.n = (uint32_t) (hd / 32 * 33);
                            r.off = tw->off + (uint64_t) id * r.n;
                        } else if (q6k || iq4) {   // (into the row's code bytes; its scale bytes unused)
                            r.n = (uint32_t) (q6k ? hd / 256 * 210 : hd / 32 * 18);
                            r.off = tw->off + (uint64_t) id * r.n;
                        } else {
                            r.n = (uint32_t) hd;
                            r.off = tw->off + (uint64_t) id * hd;
                            r.file2 = ts->file;
                            r.n2 = (uint32_t) (hd / 32);
                            r.off2 = ts->off + (uint64_t) id * (hd / 32);
                        }
                        b.reads.push_back(r);
                    }
                }
            }
        }
        eg_rows_n += hits + (int64_t) b.reads.size() + (int64_t) b.dups.size();
        eg_hits_n += hits + (int64_t) b.dups.size();
        eg_reads_n += (int64_t) b.reads.size();
        eg_io.submit(b);
    }
    // b's rows all in place (any thread; a group's members may ask at once: one finishes, the others wait for it)
    void eg_finish(EgBatch& b) {
        if (b.post.load(std::memory_order_acquire) == 2) return;
        const int64_t t0 = now_ns();
        eg_io.wait(b);
        int want = 0;
        if (b.post.compare_exchange_strong(want, 1, std::memory_order_acq_rel)) {
            const int hd = pk.eg_hd;
            for (const auto& d : b.dups) {
                const EgRead& r = b.reads[(size_t) d.first];
                std::memcpy(d.second.first, r.dst, (size_t) hd);
                std::memcpy(d.second.second, r.scales, (size_t) hd / 32);
            }
            if (ds4_dbg("DS4_DBG_EG") && pk.eg_hd >= 32) {   // DBG: a row whose IQ4_NL block scale is not finite
                for (size_t i = 0; i < b.reads.size(); ++i) {
                    const EgRead& r = b.reads[i];
                    for (int k = 0; k < hd / 32; ++k) {
                        uint16_t hb;
                        std::memcpy(&hb, r.dst + (size_t) k * 18, 2);
                        if ((hb & 0x7c00) == 0x7c00)
                            std::fprintf(stderr, "DBG eg bad scale: read %zu/%zu file=%d off=%llu n=%u block=%d half=%04x ok=%d\n", i, b.reads.size(),
                                         r.file, (unsigned long long) r.off, r.n, k, hb, (int) b.ok[i]);
                    }
                }
            }
            {
                std::lock_guard<std::mutex> lk(eg_cache_mu);
                for (size_t i = 0; i < b.reads.size(); ++i) {
                    const EgRead& r = b.reads[i];
                    if (!b.ok[i]) {   // (a failed read: zeros, its gate adds nothing; not kept)
#if defined(STRATA_METAL)
                        std::fprintf(stderr, "ds4: WARNING: an Engram row could not be read (file %d, offset %llu, %u bytes): it counts as zeros\n", r.file,
                                     (unsigned long long) r.off, r.n);
#endif
                        std::memset(r.dst, 0, (size_t) hd);
                        std::memset(r.scales, 0, (size_t) hd / 32);
                        continue;
                    }
                    if (uint8_t* c = eg_cache.put(r.key)) {
                        std::memcpy(c, r.dst, (size_t) hd);
                        std::memcpy(c + hd, r.scales, (size_t) hd / 32);
                    }
                }
            }
            eg_io_ns += b.t1.load() - b.t0;
            b.live = false;
            b.post.store(2, std::memory_order_release);
        } else {
            while (b.post.load(std::memory_order_acquire) != 2) std::this_thread::yield();
        }
        eg_wait_ns += now_ns() - t0;
    }
    void eg_stats() {
        st.eg_rows = eg_rows_n.load();
        st.eg_hits = eg_hits_n.load();
        st.eg_reads = eg_reads_n.load();
        st.eg_io_ms = (double) eg_io_ns.load() / 1e6;
        std::lock_guard<std::mutex> lk(eg_cache_mu);
        st.eg_cached = (int64_t) eg_cache.size();
        st.eg_cache_cap = (int64_t) eg_cache.capacity();
    }
    // the chunked prompt path: rows of Engram layer `only` into dst, now (a helper thread, a chunk ahead)
    void engram_rows(int64_t p0, int T, int only, uint8_t* dst) {
        EgBatch b;
        eg_issue(p0, T, only, dst, b);
        eg_finish(b);
    }

    // ---- the CPU lane: a window's routed experts that live on the host, as entries (an expert and up to 8 of its
    // tokens, in rows slot0 ..) computed together: each node its column part of every matrix, from memory on that node,
    // in four rounds (the gate / up split-K pieces, each preparing its two input blocks of every token; each band's
    // sums / codebook / Hadamard / swiglu and that block of the down input, which both nodes then read whole; the down
    // pieces; the down bands).  yd[slot] gets each row's expert output.
    static constexpr int kEntMax = kWin > kc::kExl3CpuMaxN ? kWin : kc::kExl3CpuMaxN;
    struct Ent {
        int e = 0, n = 0, slot0 = 0;
        int tok[kEntMax] = {};
    };
    // tokens an entry holds: the i-quant GGUF experts take a whole window's tokens of an expert in one call (the CPU
    // lane's exact multi-token rows, 7+ tokens an expert: decoded once for all), the others (MXFP4, EXL3) up to 8
    static int ent_cap(const Layer& l) {
        return l.lay.fmt == gg::kFmtMXFP4 && !gg::mx_experts(l.lay) ? kEntMax : kc::kExl3CpuMaxN;
    }
    // node X's job as a std::function without a heap block: the job's lambda (X, j) by address plus X - 16 trivially
    // copyable bytes, which std::function keeps in place (a [&, X] lambda capturing a dozen references is ~100 bytes and was
    // a malloc each assignment: 4-8 a CPU-lane call, on the lane's thread, every layer of every token)
    template <class F>
    struct NodeJob {
        const F* f;
        int X;
        void operator()(int j) const { (*f)(X, j); }
    };
    template <class F>
    void node_jobs(std::function<void(int)>* f, const F& fn) {
        for (int X = 0; X < NH; ++X) f[X] = NodeJob<F>{&fn, X};
    }
    void run_nodes(int n, const std::function<void(int)>* f) {
        for (int X = 0; X < NH; ++X) pools[(size_t) X]->start(n, f[X]);
        pools[0]->help();
        for (int X = 0; X < NH; ++X) pools[(size_t) X]->wait();
    }

    // a GGUF's MXFP4 experts on the CPU lane, read from the file's mapping or their copy in RAM (mx_part_ptr): each
    // node its rows of every matrix - the gate / up rows [X n_ff / NH, ..) of each entry (the swiglu into its h row),
    // then (h whole) the down rows [X dim / NH, ..) into yd.  A row's sum is the same whatever the split: the same bits
    // in a copy as in place.  The device's arithmetic (gg::mx_rows: int8 activations rounded as the device rounds
    // them, exact integer sums a block; every CPU tier the same bits): each token's input quantized once, whatever
    // number of entries take it, and each job its band of h straight into the down's int8 input.
    // (ord: the order the entries are computed in - their slots, so the sums, stay the same; null: as they are)
    void cpu_experts_mx(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx, const int* ord) {
        if (!gg::mx_experts(l.lay)) return cpu_experts_iq(l, x, ents, ldx, ord);
        constexpr int RB = 64;   // rows a job (whole blocks of h: RB % 32 == 0)
        const int E = g.dim, FF = g.ff, FFh = FF / NH, Eh = E / NH;
        const int GB = (FFh + RB - 1) / RB, DB = (Eh + RB - 1) / RB, ne = (int) ents.size();
        const size_t gr = gg::mx_row_bytes(E), dr = gg::mx_row_bytes(FF);
        const size_t xa = gg::mx_act_bytes(E), ha = gg::mx_act_bytes(FF);
        const bool band_q = FFh % 32 == 0;   // (each job's rows whole blocks of h)
        const float lim = g.lim;
        static_assert(kc::kExl3CpuMaxN <= gg::kMxCpuMaxN, "a CPU-lane entry's tokens in one call");
        {   // the experts read from the files (not in the RAM tier) that are not resident: all their pages asked for at
            // once, so the SSD reads them with large requests side by side while the first entries compute
            // (os::prefetch_cold: the resident ones are left alone - the hint walks every page of a range, which cost
            // more than computing a warm expert, 0.34 ms a 6.3 MB matrix on Windows)
            thread_local std::vector<std::pair<const void*, size_t>> want;   // kept (the lane's thread)
            want.clear();
            for (const Ent& en : ents)
                if (!store && (l.ram.empty() || l.ram[(size_t) en.e] < 0))
                    for (int r = 0; r < 3; ++r) want.push_back({mx_mat(l, en.e, r), mx_part_bytes(l, r)});
            os::prefetch_cold(want);
        }
        // the int8 inputs in c_xh's bytes: token t's (t < kWin) at t xa, then the slots' h at (kWin + slot) ha; a token
        // index past the window (none on the decode or chunk paths) gets a row of its own after them
        uint8_t* xq = (uint8_t*) c_xh.data();
        uint8_t* hq = xq + (size_t) kWin * xa;
        uint8_t* xq_extra = hq + (size_t) kSlots * ha;
        auto x_act = [&](const Ent& en, int i) -> const void* {
            const int t = en.tok[i];
            return t < kWin ? xq + (size_t) t * xa : xq_extra + (size_t) (en.slot0 + i) * xa;
        };
        {
            bool done[kWin] = {};
            for (const Ent& en : ents)
                for (int i = 0; i < en.n; ++i) {
                    const int t = en.tok[i];
                    if (t < kWin && done[t]) continue;
                    if (t < kWin) done[t] = true;
                    gg::mx_quant(x + (size_t) t * ldx, E, (void*) x_act(en, i));
                }
        }
        std::function<void(int)> f[4];
        const auto mx_gu = [&](int X, int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / GB] : j / GB)];
                const int r0 = X * FFh + (j % GB) * RB, r1 = std::min(X * FFh + FFh, r0 + RB);
                const void* ap[gg::kMxCpuMaxN];
                float yg[gg::kMxCpuMaxN][RB], yu[gg::kMxCpuMaxN][RB];
                float *gp[gg::kMxCpuMaxN], *up[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    ap[i] = x_act(en, i);
                    gp[i] = yg[i];
                    up[i] = yu[i];
                }
                // (part X's rows, from where they are: a copy's part on node X, or the file's)
                gg::mx_rows(mx_part_ptr(l, en.e, 0, X), gr, E, r0 - X * FFh, r1 - X * FFh, ap, en.n, gp);
                gg::mx_rows(mx_part_ptr(l, en.e, 1, X), gr, E, r0 - X * FFh, r1 - X * FFh, ap, en.n, up);
                for (int i = 0; i < en.n; ++i) {
                    float* h = band_q ? yg[i] : c_xhd.data() + (size_t) (en.slot0 + i) * FF + r0;
                    for (int r = r0; r < r1; ++r) {
                        float gv = yg[i][r - r0], uv = yu[i][r - r0];
                        if (lim > 0.0f) {
                            gv = std::min(gv, lim);
                            uv = std::min(std::max(uv, -lim), lim);
                        }
                        h[r - r0] = gv / (1.0f + std::exp(-gv)) * uv;
                    }
                    if (band_q) gg::mx_quant_blocks(h, r0 / 32, r1 / 32, hq + (size_t) (en.slot0 + i) * ha, FF);
                }
            };
        node_jobs(f, mx_gu);
        run_nodes(ne * GB, f);
        if (!band_q)
            for (const Ent& en : ents)
                for (int i = 0; i < en.n; ++i)
                    gg::mx_quant(c_xhd.data() + (size_t) (en.slot0 + i) * FF, FF, hq + (size_t) (en.slot0 + i) * ha);
        const auto mx_down = [&](int X, int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / DB] : j / DB)];
                const int r0 = X * Eh + (j % DB) * RB, r1 = std::min(X * Eh + Eh, r0 + RB);
                const void* ap[gg::kMxCpuMaxN];
                float* yp[gg::kMxCpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    ap[i] = hq + (size_t) (en.slot0 + i) * ha;
                    yp[i] = c_yd.data() + (size_t) (en.slot0 + i) * E + r0;
                }
                gg::mx_rows(mx_part_ptr(l, en.e, 2, X), dr, FF, r0 - X * Eh, r1 - X * Eh, ap, en.n, yp);
            };
        node_jobs(f, mx_down);
        run_nodes(ne * DB, f);
    }
    // ... the low-bit ones (ds4_iq's types): as above, through ggml-cpu's dots (gg::iq_cpu_*) - each token's input
    // quantized once to the weight type's activation (Q8_K) in its c_xh row's bytes, then (h whole) its h the same
#if defined(STRATA_METAL)
    // The CPU lane's cold reads were 78% of its time (a madvise(WILLNEED) of a range that is not in the page cache blocks while the SSD
    // reads it).  Stale-router lookahead (no training): the GPU applies layer L+a's gate (+ bias, the router's own rule) to layer L's FFN
    // input (a gemv and a route a layer, queued behind the shared expert) and the host reads the guessed picks with the real ones; the
    // guessed CPU-lane experts whose pages are not in the page cache are read in on helper threads while this layer computes.  Bytes per
    // layer capped (DS4_LA_MAX experts, default 4); DS4_LOOKAHEAD layers ahead (default 2; 0 off).
    static bool la_enabled() { return la_depth() > 0; }
    static int la_depth() {
        static const int d = std::getenv("DS4_LOOKAHEAD") ? std::atoi(std::getenv("DS4_LOOKAHEAD")) : 0;   // (off by default until it is measured faster)
        return std::min(d, 2);
    }
    struct LaPool {
        std::mutex m;
        std::condition_variable cv;
        std::deque<std::pair<const void*, size_t>> q;
        LaPool() {
            const int nth = std::getenv("DS4_LA_THREADS") ? std::atoi(std::getenv("DS4_LA_THREADS")) : 3;
            for (int i = 0; i < nth; ++i)
                std::thread([this] {
                    for (;;) {
                        std::pair<const void*, size_t> r;
                        {
                            std::unique_lock<std::mutex> lk(m);
                            cv.wait(lk, [&] { return !q.empty(); });
                            r = q.front();
                            q.pop_front();
                            while (q.size() > 64) q.pop_front();   // (stale reads are worth nothing)
                        }
                        const uintptr_t a = (uintptr_t) r.first & ~(uintptr_t) 16383;
                        const size_t len = r.second + ((uintptr_t) r.first - a);
                        std::vector<unsigned char> vec((len + 16383) / 16384);
                        bool cold = true;
                        if (mincore((void*) a, len, (char*) vec.data()) == 0) {
                            cold = false;
                            for (unsigned char c : vec) if (!(c & 1)) { cold = true; break; }
                        }
                        if (cold) os::prefetch({r});
                    }
                }).detach();
        }
        void push(const void* p, size_t n) {
            { std::lock_guard<std::mutex> lk(m); q.push_back({p, n}); }
            cv.notify_one();
        }
    };
    std::mutex la_mu;
    std::vector<std::vector<int>> la_guess;   // per layer: the CPU-lane experts its last lookahead guessed
    long la_hit = 0, la_all = 0, la_issued = 0;
    void lookahead_prefetch(Layer& l, cudaEvent_t ev2, int la_n, const std::vector<Ent>& ents) {
        if (l.nm != 1) return;
        static LaPool* pool = nullptr;
        static bool reg = false;
        if (pool == nullptr) {
            la_guess.assign(L.size(), {});
            pool = new LaPool();
        }
        if (ds4_dbg("DS4_CPU_LOG") && !reg) {
            reg = true;
            static Impl* self = this;
            std::atexit([] { std::fprintf(stderr, "lookahead: %ld of %ld CPU-lane experts were guessed; %ld matrices queued\n", self->la_hit, self->la_all, self->la_issued); });
        }
        for (const Ent& en : ents) {
            ++la_all;
            const auto& gs = la_guess[(size_t) l.il];
            if (std::find(gs.begin(), gs.end(), en.e) != gs.end()) ++la_hit;
        }
        if (la_n <= 0) return;
        cudaEventSynchronize(ev2);
        static const int cap = std::getenv("DS4_LA_MAX") ? std::atoi(std::getenv("DS4_LA_MAX")) : 4;
        for (int a = 1; a <= la_n; ++a) {
            Layer& nx = L[(size_t) (l.il + a)];
            std::vector<int> cpu;
            for (int r = 0; r < nx.k_exp; ++r) {
                const int e = h_idx_a[(a - 1) * kPicks + r];
                if (e >= 0 && e < nx.n_exp && nx.slot[(size_t) e] < 0 && (int) cpu.size() < cap) cpu.push_back(e);
            }
            la_guess[nx.il] = cpu;
            for (int e : cpu)
                for (int r = 0; r < 3; ++r) { pool->push(mx_mat(nx, e, r), mx_part_bytes(nx, r)); ++la_issued; }
        }
    }
#endif
    void cpu_experts_iq(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx, const int* ord) {
        constexpr int RB = 64;   // rows a job
        const int E = g.dim, FF = g.ff, FFh = FF / NH, Eh = E / NH;
        const int GB = (FFh + RB - 1) / RB, DB = (Eh + RB - 1) / RB, ne = (int) ents.size();
        gg::IqCpu fm;
        std::string ferr;
        if (!gg::iq_cpu_fmt(gg::expert_type(l.lay, 0), gg::expert_type(l.lay, 2), E, FF, fm, ferr) ||
            fm.act_bytes > (size_t) E * 4 || fm.h_bytes > (size_t) E * 4) {
            // (expert_layout_mx refuses such a layer at load: if one gets here anyway, stop rather than answer zeros -
            // the old path wrote zeros for every pick with one log line.  Project Maya e598716, #620)
            std::fprintf(stderr, "ds4: layer %d's CPU-lane experts: %s (cannot compute them; aborting)\n", l.il,
                         ferr.empty() ? "activation rows too large" : ferr.c_str());
            std::fflush(stderr);
            std::abort();
        }
        static double t_pre = 0, t_q1 = 0, t_r1 = 0, t_q2 = 0, t_r2 = 0; static long n_calls = 0; static bool reg = false;
        if (ds4_dbg("DS4_CPU_LOG") && !reg) { reg = true; std::atexit([] { std::fprintf(stderr, "cpu_experts_iq phases (ms over %ld calls): prefetch %.1f, quant1 %.1f, gate_up %.1f, quant2 %.1f, down %.1f\n", n_calls, t_pre, t_q1, t_r1, t_q2, t_r2); }); }
        const bool cpulog = ds4_dbg("DS4_CPU_LOG");   // (the Mac engine's counters; false elsewhere)
        if (cpulog) ++n_calls;
        double tp0 = now_ms();
        const float lim = g.lim;
        {   // (os::prefetch_cold, as above: the resident ones are left alone - on Windows the hint walks every page of a
            // range, ~0.13 ms an IQ2_XXS expert, on the lane's critical path before the first entry computes.
            // off by default (the mmap path, owner PC: not faster in every pair); DS4_IQ_PF_COLD=1 turns it on)
            thread_local std::vector<std::pair<const void*, size_t>> want;   // kept (the lane's thread)
            want.clear();
            for (const Ent& en : ents)
                if (!store && (l.ram.empty() || l.ram[(size_t) en.e] < 0))
                    for (int r = 0; r < 3; ++r) want.push_back({mx_mat(l, en.e, r), mx_part_bytes(l, r)});
            static const bool pf_all = std::getenv("DS4_IQ_PF_COLD") == nullptr || std::atoi(std::getenv("DS4_IQ_PF_COLD")) == 0;
#if defined(__APPLE__)   // (macOS: the cold reads of a call's matrices in parallel, and a page-cache census under DS4_CPU_LOG)
            if (pf_all && ds4_dbg("DS4_CPU_LOG")) {   // how many of the experts' matrices are in the page cache (mincore, the first 64 pages)
                static long cold_n = 0, warm_n = 0; static double cold_ms = 0, warm_ms = 0; static bool reg2 = false;
                if (!reg2) { reg2 = true; std::atexit([] { std::fprintf(stderr, "prefetch: %ld matrices cold (%.1f ms), %ld warm (%.1f ms)\n", cold_n, cold_ms, warm_n, warm_ms); }); }
                for (const auto& w : want) {
                    const uintptr_t a = (uintptr_t) w.first & ~(uintptr_t) 16383;
                    unsigned char vec[64];
                    const size_t len = std::min<size_t>(w.second, 64 * 16384);
                    bool cold = false;
                    if (mincore((void*) a, len, (char*) vec) == 0) for (size_t i = 0; i < (len + 16383) / 16384; ++i) if (!(vec[i] & 1)) cold = true;
                    const double t0 = now_ms();
                    os::prefetch({w});
                    (cold ? cold_ms : warm_ms) += now_ms() - t0;
                    (cold ? cold_n : warm_n)++;
                }
            } else if (pf_all && want.size() > 1 && std::getenv("DS4_SERIAL_PREFETCH") == nullptr) {
                // (a madvise(WILLNEED) of a cold range blocks while the SSD reads it: queue depth 1 reads 3.9 GB/s; the matrices of
                // all the call's experts at once keep the SSD busy)
                std::function<void(int)> pf[4];
                for (int X = 0; X < NH; ++X) pf[X] = [&](int j) { os::prefetch({want[(size_t) j]}); };
                run_nodes((int) want.size(), pf);
            } else
            if (pf_all) os::prefetch(want);
            else os::prefetch_cold(want);
#else
            if (pf_all) os::prefetch(want);
            else os::prefetch_cold(want);
#endif
        }
        double tp1 = now_ms(); if (cpulog) t_pre += tp1 - tp0;
        // the activations in c_xh's bytes, E 4 apart: token t's (t < kWin) at row t - quantized once, whatever number of
        // entries take it - then a row a slot (kWin + slot): a token past the window's input (none on the decode or
        // chunk paths), then (x no longer needed) the slot's h
        uint8_t* aq = (uint8_t*) c_xh.data();
        auto x_act = [&](const Ent& en, int i) -> uint8_t* {
            const int t = en.tok[i];
            return aq + (size_t) (t < kWin ? t : kWin + en.slot0 + i) * E * 4;
        };
        {
            bool done[kWin] = {};
            for (const Ent& en : ents)
                for (int i = 0; i < en.n; ++i) {
                    const int t = en.tok[i];
                    if (t < kWin && done[t]) continue;
                    if (t < kWin) done[t] = true;
                    gg::iq_cpu_quant(fm.gu_act, x + (size_t) t * ldx, E, x_act(en, i));
                }
        }
        double tq1 = now_ms(); if (cpulog) t_q1 += tq1 - tp1;
        std::function<void(int)> f[4];
        const auto iq_gu = [&](int X, int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / GB] : j / GB)];
                const int r0 = X * FFh + (j % GB) * RB, r1 = std::min(X * FFh + FFh, r0 + RB);
                const void* ap[kEntMax];
                float* hp[kEntMax];
                for (int i = 0; i < en.n; ++i) {
                    ap[i] = x_act(en, i);
                    hp[i] = c_xhd.data() + (size_t) (en.slot0 + i) * FF + (size_t) X * FFh;   // (part X's rows of h)
                }
                // (part X's rows, from where they are: a copy's part on node X, or the file's - whole rows, so any
                // block size of the type)
                gg::iq_cpu_gate_up(fm, mx_part_ptr(l, en.e, 0, X), mx_part_ptr(l, en.e, 1, X), ap, en.n, hp,
                                   r0 - X * FFh, r1 - X * FFh, lim);
            };
        node_jobs(f, iq_gu);
        run_nodes(ne * GB, f);
        double tr1 = now_ms(); if (cpulog) t_r1 += tr1 - tq1;
        for (const Ent& en : ents)
            for (int i = 0; i < en.n; ++i)
                gg::iq_cpu_quant(fm.d_act, c_xhd.data() + (size_t) (en.slot0 + i) * FF, FF,
                                 aq + (size_t) (kWin + en.slot0 + i) * E * 4);
        double tq2 = now_ms(); if (cpulog) t_q2 += tq2 - tr1;
        const auto iq_down = [&](int X, int j) {
                const Ent& en = ents[(size_t) (ord != nullptr ? ord[j / DB] : j / DB)];
                const int r0 = X * Eh + (j % DB) * RB, r1 = std::min(X * Eh + Eh, r0 + RB);
                const void* hp[kEntMax];
                float* yp[kEntMax];
                for (int i = 0; i < en.n; ++i) {
                    hp[i] = aq + (size_t) (kWin + en.slot0 + i) * E * 4;
                    yp[i] = c_yd.data() + (size_t) (en.slot0 + i) * E + (size_t) X * Eh;   // (part X's rows of it)
                }
                gg::iq_cpu_down(fm, mx_part_ptr(l, en.e, 2, X), hp, en.n, yp, r0 - X * Eh, r1 - X * Eh);
            };
        node_jobs(f, iq_down);
        run_nodes(ne * DB, f);
        if (cpulog) t_r2 += now_ms() - tq2;
        {   // DS4_PROF: where the CPU lane's time goes (act prep + prefetch, gate/up, h quant, down), summed
            static const bool on = std::getenv("DS4_PROF") != nullptr;
            if (on) {
                static double acc[6] = {};
                const double te = now_ms();
                acc[0] += tq1 - tp0; acc[1] += tr1 - tq1; acc[2] += tq2 - tr1; acc[3] += te - tq2; acc[4] += 1; acc[5] += ne;
                if (((long long) acc[4]) % 1000 == 0)
                    std::fprintf(stderr, "ds4 prof CPU lane (IQ rows) per call: n %.0f, entries/call %.2f, prep %.3f ms, gate+up %.3f ms, h-quant %.3f ms, down %.3f ms\n", acc[4], acc[5] / acc[4], acc[0] / acc[4], acc[1] / acc[4], acc[2] / acc[4], acc[3] / acc[4]);
            }
        }
    }

    // the window's CPU-lane experts made ready (and pinned) in the store for the length of the call
    struct StoreHold {
        Impl* m = nullptr;
        int layer = 0;
        std::vector<int> es, sl;
        std::vector<char> ok;
        // lazy: the reads are started here and waited for by wait_all() / wait_expert(); the destructor releases
        StoreHold(Impl* m_, const Layer& l, const std::vector<Ent>& ents) {
            if (!m_->store) return;
            m = m_;
            layer = l.il;
            for (const Ent& en : ents)
                if ((l.ram.empty() || l.ram[(size_t) en.e] < 0) && std::find(es.begin(), es.end(), en.e) == es.end()) es.push_back(en.e);
            m->store->begin(layer, es.data(), (int) es.size(), ok, sl);
        }
        int idx(int e) const {
            for (size_t i = 0; i < es.size(); ++i)
                if (es[i] == e) return (int) i;
            return -1;
        }
        // expert e needs no waiting: not a store expert (RAM copy) or its reads are done
        bool ready(int e) const {
            if (!m) return true;
            const int i = idx(e);
            return i < 0 || m->store->loaded(sl[(size_t) i]);
        }
        // (no view of the files is left to fall back on: an expert without a slot is read again, one at a time, until it has one)
        void rescue(int a, int b) {
            if (!m || m->views) return;
            for (int i = a; i < b; ++i) {
                for (int tries = 0; !ok[(size_t) i]; ++tries) {
                    std::vector<char> o2;
                    m->store->ensure(layer, &es[(size_t) i], 1, o2);
                    if (!o2.empty() && o2[0]) {
                        ok[(size_t) i] = 1;
                        break;
                    }
                    if (tries > 2000) {
                        std::fprintf(stderr, "ds4: layer %d expert %d: no store slot and no view of the files\n", layer, es[(size_t) i]);
                        std::exit(3);
                    }
                    std::this_thread::sleep_for(std::chrono::milliseconds(1));
                }
            }
        }
        void wait_expert(int e) {
            if (!m) return;
            const int i = idx(e);
            if (i >= 0) {
                m->store->wait_slots(sl, ok, i, i + 1);
                rescue(i, i + 1);
            }
        }
        void wait_all() {
            if (m) {
                m->store->wait_slots(sl, ok, 0, (int) es.size());
                rescue(0, (int) es.size());
            }
        }
        ~StoreHold() {
            if (m) m->store->release(layer, es.data(), (int) es.size(), ok);
        }
    };
    // DS4_MISS_SPLIT=0: the old order (wait for every read, then compute); default: the entries whose reads are done
    // computed first, the others each as its read lands (the same bits: every entry's rows are independent)
    void cpu_experts(const Layer& l, const float* x, const std::vector<Ent>& ents, size_t ldx = 0,
                     const int* ord = nullptr) {
        if (ldx == 0) ldx = (size_t) g.dim;
        if (l.lay.fmt == gg::kFmtMXFP4) {
            StoreHold hold(this, l, ents);
            static const bool split = std::getenv("DS4_MISS_SPLIT") == nullptr || std::atoi(std::getenv("DS4_MISS_SPLIT")) != 0;
            if (!split || ord != nullptr || !hold.m || ents.size() < 2) {
                hold.wait_all();
                return cpu_experts_mx(l, x, ents, ldx, ord);
            }
            std::vector<Ent> hot, cold;
            for (const Ent& en : ents) (hold.ready(en.e) ? hot : cold).push_back(en);
            if (cold.empty()) {
                hold.wait_all();
                return cpu_experts_mx(l, x, ents, ldx, ord);
            }
            for (const Ent& en : hot) hold.wait_expert(en.e);   // (done reading: only the bookkeeping)
            if (!hot.empty()) cpu_experts_mx(l, x, hot, ldx, nullptr);
            // the ones that came in meanwhile first, then the rest in the order they land
            std::vector<char> done(cold.size(), 0);
            for (size_t left = cold.size(); left > 0;) {
                size_t pick = cold.size();
                for (size_t i = 0; i < cold.size(); ++i)
                    if (!done[i] && hold.ready(cold[i].e)) {
                        pick = i;
                        break;
                    }
                if (pick == cold.size())
                    for (size_t i = 0; i < cold.size(); ++i)
                        if (!done[i]) {
                            pick = i;
                            break;
                        }
                hold.wait_expert(cold[pick].e);
                std::vector<Ent> one(1, cold[pick]);
                cpu_experts_mx(l, x, one, ldx, nullptr);
                done[pick] = 1;
                --left;
            }
            return;
        }
        const int E = g.dim, FF = g.ff, FFh = FF / NH, Eh = E / NH, GQ = E / 256, DQ = FF / 128;
        const int GB = FFh / 128, DB = Eh / 128, EB = E / 128, FB = FF / 128;
        const int ne = (int) ents.size();
        const float lim = g.lim;
        auto part = [&](int e, int X, int r) {
            const uint8_t* b = l.hh[(size_t) e][(size_t) X];
            kc::Exl3Part p;
            p.trellis = (const uint32_t*) (b + l.hl.trellis[r]);
            p.suh = (const uint16_t*) (b + l.hl.suh[r]);
            p.svh = (const uint16_t*) (b + l.hl.svh[r]);
            p.k = l.hl.k[r];
            p.n = l.hl.n[r];
            p.K = l.lay.K[r];
            return p;
        };
        auto xh = [&](int X, int sl, int r) { return c_xh.data() + ((size_t) (X * kSlots + sl) * 2 + r) * E; };
        auto xsb = [&](int X, int sl, int r) { return c_xsb.data() + ((size_t) (X * kSlots + sl) * 2 + r) * EB; };
        auto acc = [&](int X, int sl, int r, int q) {
            return c_acc.data() + (((size_t) (X * kSlots + sl) * 2 + r) * GQ + q) * FFh;
        };
        auto xhd = [&](int sl) { return c_xhd.data() + (size_t) sl * FF; };
        auto xsd = [&](int sl) { return c_xsd.data() + (size_t) sl * FB; };
        auto accd = [&](int X, int sl, int q) { return c_accd.data() + ((size_t) (X * kSlots + sl) * DQ + q) * Eh; };
        std::function<void(int)> f[4];
        const auto x3job1 = [&](int X, int j) {
                const Ent& en = ents[(size_t) (j / (2 * GQ))];
                const int r = (j / GQ) % 2, q = j % GQ;
                const kc::Exl3Part p = part(en.e, X, r);
                const float* xp[kc::kExl3CpuMaxN];
                float* ap[kc::kExl3CpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    const int sl = en.slot0 + i;
                    const float* xt = x + (size_t) en.tok[i] * ldx;
                    for (int b = 2 * q; b < 2 * q + 2; ++b)
                        xsb(X, sl, r)[b] = kc::exl3_cpu_prepare_block(p.suh + b * 128, xt + b * 128, xh(X, sl, r) + b * 128);
                    xp[i] = xh(X, sl, r);
                    ap[i] = acc(X, sl, r, q);
                }
                if (en.n == 1) kc::exl3_cpu_rows_acc(p, xp[0], q * 16, (q + 1) * 16, ap[0]);
                else kc::exl3_cpu_rows_acc_n(p, xp, en.n, q * 16, (q + 1) * 16, ap);
            };
        node_jobs(f, x3job1);
        run_nodes(ne * 2 * GQ, f);
        const auto x3job2 = [&](int X, int j) {
                const Ent& en = ents[(size_t) (j / GB)];
                const int b = j % GB;
                const kc::Exl3Part pg = part(en.e, X, 0), pu = part(en.e, X, 1), pd = part(en.e, X, 2);
                for (int i = 0; i < en.n; ++i) {
                    const int sl = en.slot0 + i;
                    float y[2][128], a[128], hb[128];
                    for (int r = 0; r < 2; ++r) {
                        for (int c = 0; c < 128; ++c) a[c] = 0.0f;
                        for (int q = 0; q < GQ; ++q) {
                            const float* aq = acc(X, sl, r, q) + b * 128;
                            for (int c = 0; c < 128; ++c) a[c] += aq[c];
                        }
                        double xs = 0.0;
                        for (int k = 0; k < EB; ++k) xs += xsb(X, sl, r)[k];
                        kc::exl3_cpu_band_out(r == 0 ? pg : pu, a, (float) xs, b * 128, y[r]);
                    }
                    for (int c = 0; c < 128; ++c) {
                        float gv = y[0][c], uv = y[1][c];
                        if (lim > 0.0f) {
                            gv = std::min(gv, lim);
                            uv = std::min(std::max(uv, -lim), lim);
                        }
                        hb[c] = gv / (1.0f + std::exp(-gv)) * uv;
                    }
                    const int gb = X * GB + b;
                    xsd(sl)[gb] = kc::exl3_cpu_prepare_block(pd.suh + gb * 128, hb, xhd(sl) + gb * 128);
                }
            };
        node_jobs(f, x3job2);
        run_nodes(ne * GB, f);
        const auto x3job3 = [&](int X, int j) {
                const Ent& en = ents[(size_t) (j / DQ)];
                const int q = j % DQ;
                const kc::Exl3Part p = part(en.e, X, 2);
                const float* xp[kc::kExl3CpuMaxN];
                float* ap[kc::kExl3CpuMaxN];
                for (int i = 0; i < en.n; ++i) {
                    xp[i] = xhd(en.slot0 + i);
                    ap[i] = accd(X, en.slot0 + i, q);
                }
                if (en.n == 1) kc::exl3_cpu_rows_acc(p, xp[0], q * 8, (q + 1) * 8, ap[0]);
                else kc::exl3_cpu_rows_acc_n(p, xp, en.n, q * 8, (q + 1) * 8, ap);
            };
        node_jobs(f, x3job3);
        run_nodes(ne * DQ, f);
        const auto x3job4 = [&](int X, int j) {
                const Ent& en = ents[(size_t) (j / DB)];
                const int b = j % DB;
                const kc::Exl3Part pd = part(en.e, X, 2);
                for (int i = 0; i < en.n; ++i) {
                    const int sl = en.slot0 + i;
                    float a[128];
                    for (int c = 0; c < 128; ++c) a[c] = 0.0f;
                    for (int q = 0; q < DQ; ++q) {
                        const float* aq = accd(X, sl, q) + b * 128;
                        for (int c = 0; c < 128; ++c) a[c] += aq[c];
                    }
                    double xs = 0.0;
                    for (int k = 0; k < FB; ++k) xs += xsd(sl)[k];
                    kc::exl3_cpu_band_out(pd, a, (float) xs, b * 128, c_yd.data() + (size_t) sl * E + (size_t) X * Eh + b * 128);
                }
            };
        node_jobs(f, x3job4);
        run_nodes(ne * DB, f);
    }

    // ---- the expert cache.  A swap moves a CPU-lane expert (`in`) into the layer's spare VRAM slot and the VRAM expert it
    // replaces (`out`) into the spare host parts - both copies of weights that do not change, made while the model runs
    // (the copy stream, the host's repacking) - and cache_tick switches the tables between windows, so the device's
    // table and the host's view of a layer always agree within a window.  In place (file_experts) `out` needs no copy:
    // the CPU lane reads it from the file again.
    void ram_loop() {   // the RAM tier's moves in: an expert read from the file into a free slot
        for (;;) {
            RamSwap rs;
            {
                std::unique_lock<std::mutex> lk(sw_mu);
                ram_cv.wait(lk, [&] { return quit.load() || !ram_queue.empty(); });
                if (quit.load()) return;
                rs = ram_queue.front();
                ram_queue.pop_front();
            }
            os::malloc_pin_thread();   // this mover's arena pre-grown once the decode is pinned
            const Layer& l = L[(size_t) rs.layer];
            if (read_mx_file(l, rs.in, ram_slots[(size_t) rs.slot])) {
                for (int r = 0; r < 3; ++r)   // (one copy of it in RAM)
                    os::advise(pk.fds[(size_t) l.mx_file[r]], l.mx_off[r] + (uint64_t) rs.in * l.mx_stride[r],
                               mx_part_bytes(l, r), false);
            } else {
                rs.in = -1;   // (failed: the slot goes back)
            }
            std::lock_guard<std::mutex> lk(sw_mu);
            ram_ready.push_back(rs);
        }
    }

    void cache_loop(SwapBufs& B) {
        for (;;) {
            Swap sw;
            {
                std::unique_lock<std::mutex> lk(sw_mu);
                sw_cv.wait(lk, [&] { return quit.load() || !sw_queue.empty(); });
                if (quit.load()) return;
                sw = sw_queue.front();
                sw_queue.pop_front();
            }
            os::malloc_pin_thread();   // this mover's arena pre-grown once the decode is pinned
            Layer& l = L[(size_t) sw.layer];
            if (l.lay.fmt == gg::kFmtMXFP4) {   // in: from the file; out: nothing to keep (the file has it)
                swap_in_mx(l, sw, B);
                std::lock_guard<std::mutex> lk(sw_mu);
                sw_ready.push_back(sw);
                continue;
            }
            parts_to_blob(l, l.hh[(size_t) sw.in], B.a);
            if (l.nm == 1) {
                const Dev& d = devs[(size_t) l.dev];
                cudaSetDevice(d.id);
                cudaStream_t cs = B.st[(size_t) l.dev];
                cudaMemcpyAsync(l.vram_base + (size_t) l.spare_vram * l.blob, B.a, l.blob, cudaMemcpyHostToDevice, cs);
                if (!file_experts)
                    cudaMemcpyAsync(B.b, l.vram_base + (size_t) l.slot[(size_t) sw.out] * l.blob, l.blob,
                                    cudaMemcpyDeviceToHost, cs);
                cudaStreamSynchronize(cs);
            } else {   // a group: each member's part in, each member's part out
                for (int m = 0; m < l.nm; ++m) {
                    const Layer& x = member(l, m);
                    cudaSetDevice(devs[(size_t) x.dev].id);
                    cudaStream_t cs = B.st[(size_t) x.dev];
                    blob_to_half(l, B.a, m, B.h);
                    cudaMemcpyAsync(x.vram_base + (size_t) l.spare_vram * x.hblob, B.h, x.hblob, cudaMemcpyHostToDevice, cs);
                    cudaStreamSynchronize(cs);
                    if (file_experts) continue;
                    cudaMemcpyAsync(B.h, x.vram_base + (size_t) l.slot[(size_t) sw.out] * x.hblob, x.hblob,
                                    cudaMemcpyDeviceToHost, cs);
                    cudaStreamSynchronize(cs);
                    half_to_blob(l, B.h, m, B.b);
                }
            }
            if (!file_experts)
                for (int X = 0; X < NH; ++X) blob_to_part(l, B.b, X, l.spare_host[(size_t) X]);
            if (check_swaps) {   // DS4_CHECK_SWAPS: both moves against the model file, byte for byte
                std::vector<uint8_t> reg, blob(l.blob), part(l.hl.bytes);
                bool ok = true;
                for (int pass = 0; pass < (file_experts ? 1 : 2); ++pass) {   // (in place: no host copy of `out`)
                    const int e = pass == 0 ? sw.in : sw.out;
                    reg.resize(l.region_bytes[(size_t) e]);
                    pk.read_at(l.region_file[(size_t) e], l.region_off[(size_t) e], reg.size(), reg.data());
                    if (pass == 0) {
                        repack(l, reg.data(), blob.data());
                        std::vector<uint8_t> dev(l.blob);
                        if (l.nm == 1)
                            cudaMemcpy(dev.data(), l.vram_base + (size_t) l.spare_vram * l.blob, l.blob, cudaMemcpyDeviceToHost);
                        else
                            for (int m = 0; m < l.nm; ++m) {   // (the members' parts, put together again)
                                std::vector<uint8_t> h(member(l, m).hblob);
                                cudaSetDevice(devs[(size_t) member(l, m).dev].id);
                                cudaMemcpy(h.data(), member(l, m).vram_base + (size_t) l.spare_vram * member(l, m).hblob, member(l, m).hblob,
                                           cudaMemcpyDeviceToHost);
                                half_to_blob(l, h.data(), m, dev.data());
                            }
                        for (int r = 0; r < 3; ++r)
                            ok = ok && std::memcmp(dev.data() + l.lay.trellis[r], blob.data() + l.lay.trellis[r], l.piece_bytes[r][0]) == 0 &&
                                 std::memcmp(dev.data() + l.lay.suh[r], blob.data() + l.lay.suh[r], l.piece_bytes[r][1]) == 0 &&
                                 std::memcmp(dev.data() + l.lay.svh[r], blob.data() + l.lay.svh[r], l.piece_bytes[r][2]) == 0;
                    } else {
                        for (int X = 0; X < NH; ++X) {
                            repack_part(l, reg.data(), X, part.data());
                            for (int r = 0; r < 3; ++r) {
                                const size_t tb = (size_t) (l.hl.k[r] / 16) * (l.hl.n[r] / 16) * 32 * l.lay.K[r];
                                ok = ok && std::memcmp(part.data() + l.hl.trellis[r], l.spare_host[(size_t) X] + l.hl.trellis[r], tb) == 0 &&
                                     std::memcmp(part.data() + l.hl.suh[r], l.spare_host[(size_t) X] + l.hl.suh[r], (size_t) l.hl.k[r] * 2) == 0 &&
                                     std::memcmp(part.data() + l.hl.svh[r], l.spare_host[(size_t) X] + l.hl.svh[r], (size_t) l.hl.n[r] * 2) == 0;
                            }
                        }
                    }
                }
                std::fprintf(stderr, "ds4 cache: layer %d expert %d in, %d out: %s\n", l.il, sw.in, sw.out,
                             ok ? "both match the model file" : "MISMATCH");
            }
            std::lock_guard<std::mutex> lk(sw_mu);
            sw_ready.push_back(sw);
        }
    }

    // a GGUF's swap: expert sw.in from the file (copy_mode: its copy) into the spare VRAM slot (each member its part);
    // the expert it replaces goes back to the CPU lane, which reads it from the file's mapping - or (copy_mode, sw.ram)
    // from the layer's spare RAM slot, which it is copied into from VRAM here
    void swap_in_mx(Layer& l, Swap& sw, SwapBufs& B) {
        uint8_t *sw_a = B.a, *sw_b = B.b, *sw_h = B.h;   // (this thread's)
        const std::vector<cudaStream_t>& copy_st = B.st;
        bool ok = copy_mode ? read_mx(l, sw.in, sw_a) : read_mx_file(l, sw.in, sw_a);   // (a copy holds its slot till
                                                                                          // this swap's switch)
        for (int m = 0; m < l.nm && ok; ++m) {
            const Layer& x = member(l, m);
            cudaSetDevice(devs[(size_t) x.dev].id);
            cudaStream_t cs = copy_st[(size_t) x.dev];
            if (l.nm > 1) blob_to_half(l, sw_a, m, sw_h);
            // (tp4: each member's own slot size, unit(x) - unit(l) is member 0's)
            ok = cudaMemcpyAsync(x.vram_base + (size_t) l.spare_vram * unit(x), l.nm > 1 ? sw_h : sw_a, unit(x),
                                 cudaMemcpyHostToDevice, cs) == cudaSuccess &&
                 cudaStreamSynchronize(cs) == cudaSuccess;
        }
        if (sw.ram >= 0) {   // `out` from its VRAM slot (each member its part) into the spare RAM slot
            bool got = ok;
            for (int m = 0; m < l.nm && got; ++m) {
                const Layer& x = member(l, m);
                cudaSetDevice(devs[(size_t) x.dev].id);
                cudaStream_t cs = copy_st[(size_t) x.dev];
                got = cudaMemcpyAsync(l.nm > 1 ? sw_h : sw_b, x.vram_base + (size_t) l.slot[(size_t) sw.out] * unit(x),
                                      unit(x), cudaMemcpyDeviceToHost, cs) == cudaSuccess &&
                      cudaStreamSynchronize(cs) == cudaSuccess;
                if (got && l.nm > 1) half_to_blob(l, sw_h, m, sw_b);
            }
            if (got) blob_to_ram(l, sw_b, sw.ram);
            else sw.ram = -1;   // (back to the file's pages then)
        } else if (ok && store && l.nm == 1 && l.lay.fmt == gg::kFmtMXFP4 && strata::ds4::store_feature_default(env_tri("DS4_STORE_PUT"), defaults_026())) {
            // `out` goes back to the CPU lane: its blob is in VRAM, so it is copied into a store slot now - the lane would otherwise read it from
            // the SSD and wait for it (1-2 misses a token on the 251 GB R9700 box).  DS4_STORE_PUT=0: off.
            uint8_t* dst = store->put_begin(l.il, sw.out);
            if (dst != nullptr) {
                const Layer& x = member(l, 0);
                cudaSetDevice(devs[(size_t) x.dev].id);
                cudaStream_t cs = copy_st[(size_t) x.dev];
                const bool got = cudaMemcpyAsync(dst, x.vram_base + (size_t) l.slot[(size_t) sw.out] * unit(l), l.blob, cudaMemcpyDeviceToHost, cs) ==
                                     cudaSuccess &&
                                 cudaStreamSynchronize(cs) == cudaSuccess;
                store->put_done(l.il, sw.out, got);
            }
        }
        if (check_swaps) {   // DS4_CHECK_SWAPS: the slot (and `out`'s RAM copy) against the model file, byte for byte
            std::vector<uint8_t> dev(l.blob), h(l.blob), file(l.blob);   // (h: the widest member's part fits)
            for (int m = 0; m < l.nm && ok; ++m) {
                const Layer& x = member(l, m);
                cudaSetDevice(devs[(size_t) x.dev].id);
                cudaMemcpy(l.nm > 1 ? h.data() : dev.data(), x.vram_base + (size_t) l.spare_vram * unit(x), unit(x),
                           cudaMemcpyDeviceToHost);
                if (l.nm > 1) half_to_blob(l, h.data(), m, dev.data());
            }
            ok = ok && read_mx_file(l, sw.in, file.data());
            for (int r = 0; r < 3 && ok; ++r)
                ok = std::memcmp(dev.data() + l.lay.trellis[r], file.data() + l.lay.trellis[r], mx_part_bytes(l, r)) == 0;
            bool ok_out = true;
            if (sw.ram >= 0) {
                ok_out = read_mx_file(l, sw.out, file.data());
                ram_to_blob(l, sw.ram, dev.data());
                for (int r = 0; r < 3 && ok_out; ++r)
                    ok_out = std::memcmp(dev.data() + l.lay.trellis[r], file.data() + l.lay.trellis[r], mx_part_bytes(l, r)) == 0;
            }
            std::fprintf(stderr, "ds4 cache: layer %d expert %d in, %d out%s: %s\n", l.il, sw.in, sw.out,
                         sw.ram >= 0 ? " (into RAM)" : "", ok && ok_out ? "matches the model file" : "MISMATCH");
        } else if (!ok) {
            std::fprintf(stderr, "ds4 cache: layer %d expert %d: the move into VRAM failed\n", l.il, sw.in);
        }
    }

    // after a chunked prompt: the expert cache catches up with what the prompt picked at once - a window prompt gets
    // its swaps one tick at a time over its hundreds of windows, a chunked one has a single tick - so the decode that
    // follows finds the hot experts in VRAM.  Rounds of the ordinary swap rule (the hottest CPU-lane pick of each layer
    // in, its coldest VRAM expert out) until nothing is worth moving or DS4_SETTLE_MS is spent.
    // The budget was 6,000 ms, and it sits inside the prompt's own time ("prompt: N tokens in X ms"): measured on Strix Halo
    // 2026-10-28, the same p4k fixture took 26.6 s with it and 20.4 s without, +30.5% on the prompt (153.9 -> 200.8 tok/s).
    // What the swaps buy is decode: about 10% on a 256-token answer, i.e. 6.2 s of prompt against 1.6 s of decode on that
    // answer and nothing at all on a 50-300-token tool-call answer.  800 ms keeps the hottest of them and gives the prompt
    // back about 5 s (the plan's own table: prompt + 256 tokens, 27.2 s at 6,000 ms, 23.9 s at 800, 23.4 s at 0).
    void cache_settle() {
        if (!o.expert_cache || cache_ths.empty()) return;
        struct FreezeAtEnd {   // DS4_CACHE_FREEZE (test only): after the n-th read's settle, every queued move landed, then none
            Impl* p;
            ~FreezeAtEnd() {
                if (p->c_freeze <= 0 || p->c_frozen || ++p->c_reads < p->c_freeze) return;
                p->cache_drain();
                p->cache_tick_swaps(0);   // (lands them; queues the last round's picks too - then those)
                p->cache_drain();
                p->c_frozen = true;
                p->cache_tick_swaps(0);
                std::fprintf(stderr, "ds4: DS4_CACHE_FREEZE=%d: the expert placement fixed after prompt read %d (%lld swaps; %d VRAM / %d RAM "
                                     "moves still in flight)\n", p->c_freeze, p->c_reads, (long long) p->st.swaps, p->sw_inflight, p->ram_inflight);
            }
        } freeze_at_end{this};
        static const double budget = env_f("DS4_SETTLE_MS", 800.0f);
        if (budget <= 0.0 && !c_det) return;
        const double t0 = now_ms();
        const int64_t s0 = st.swaps;
        for (int round = 0; c_det ? round < 64 : now_ms() - t0 < budget; ++round) {   // (DS4_CACHE_DET: rounds, not ms)
            for (Layer& l : L) {
                if (l.mtp || l.spare_vram < 0 || l.swap_pending) continue;
                l.cpu_hits.clear();
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0 && l.heat[(size_t) e] >= 2.0f && !hlp.owns(l.il, e)) l.cpu_hits.push_back(e);   // (a helper's expert is not a CPU miss)
            }
            cache_tick_swaps(0);
            if (sw_inflight == 0) break;   // (nothing queued: every layer's best CPU-lane expert is not hotter than its coldest VRAM one)
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        // The RAM store's preload after a chunked prompt is off by default: measured on Strix Halo (code fixture, prompt +
        // 256 tokens, 3 runs a side) it costs the prompt 4.7 s and the decode that follows gains nothing (13.9/14.4 s with it
        // against 14.2 s without).  The swaps above are what the decode actually uses; DS4_SETTLE_STORE=1 restores it.
        if (store && env_f("DS4_SETTLE_STORE", strata::ds4::settle_store_default(defaults_026())) != 0.0f) {   // the RAM store too: a window prompt fills it through the CPU
            // lane's picks, a chunked one streams past it - the hottest CPU-lane experts of the prompt into its free slots
            // (copy_mode: an expert already in the CPU lane's RAM copy gains nothing from a second copy of the same bytes -
            // measured on the R9700 12 GB cell: 4152 such experts, 40 GB read at 6.4 GB/s, 6.2 s of an 8K prompt, 0.0 store
            // hits in the decode after it; the VRAM swaps above already read them from the copy)
            std::vector<std::pair<float, std::pair<int, int>>> hot;
            for (const Layer& l : L) {
                if (l.mtp) continue;
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0 && !(strata::ds4::settle_skips_copy_experts(defaults_026()) && copy_mode && !l.ram.empty() && l.ram[(size_t) e] >= 0) &&
                        l.heat[(size_t) e] >= 4.0f) hot.push_back({l.heat[(size_t) e], {l.il, e}});
            }
            std::sort(hot.begin(), hot.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
            std::vector<std::pair<int, int>> list;
            for (const auto& h : hot) {
                if (list.size() >= store->slots_max()) break;
                list.push_back(h.second);
            }
            const double ts = now_ms();
            const size_t n = store->preload(list, 0);
            if (o.verbose) std::fprintf(stderr, "ds4: RAM store: %zu hot experts read after the prompt (%.0f ms)\n", n, now_ms() - ts);
        }
        if (o.verbose && st.swaps > s0)
            std::fprintf(stderr, "ds4: expert cache: %lld swaps after the prompt (%.0f ms)\n", (long long) (st.swaps - s0),
                         now_ms() - t0);
    }
    // WP-8's option (1): the same swap rounds, run on a thread while the server has no request in flight, stopped by `cancel`.
    // The prompt path keeps its 800 ms (a run with no server has no idle to use), so this is pure addition: an agent's turn
    // ends, the swaps go in while it runs its tool, and the next turn's answer finds them.  Interrupting costs one round (a
    // swap of ~9 MB, a millisecond or two) because cancel is tested between rounds, and cache_tick_swaps is the same call the
    // prompt path makes, so the state it leaves is the state a decode window already handles.
    void cache_settle_idle(const std::atomic<bool>& cancel) {
        if (!o.expert_cache || cache_ths.empty() || c_det || c_frozen) return;   // (DS4_CACHE_DET / FREEZE: no timed rounds)
        static const double budget = env_f("DS4_SETTLE_IDLE_MS", 6000.0f);
        const double t0 = now_ms();
        const int64_t s0 = st.swaps;
        while (!cancel.load(std::memory_order_acquire) && now_ms() - t0 < budget) {
            for (Layer& l : L) {
                if (l.mtp || l.spare_vram < 0 || l.swap_pending) continue;
                l.cpu_hits.clear();
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] < 0 && l.heat[(size_t) e] >= 2.0f && !hlp.owns(l.il, e)) l.cpu_hits.push_back(e);   // (a helper's expert is not a CPU miss)
            }
            cache_tick_swaps(0);
            if (sw_inflight == 0) break;   // (nothing queued: no layer's best CPU-lane expert is hotter than its coldest VRAM one)
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        if (o.verbose)
            std::fprintf(stderr, "ds4: expert cache: %lld swaps in the idle (%.0f ms, cancelled %d)\n",
                         (long long) (st.swaps - s0), now_ms() - t0, cancel.load() ? 1 : 0);
    }
    void cache_tick(int T) {
        cache_tick_swaps(T);
        store_sync();
        store_watch();
    }
    // the store gives RAM back when the PC runs short (the owner opened something): below 4 GB free, a 0.7 GB chunk at a time
    // until 5 GB are free again (checked every 16 windows); it grows again by itself once 8 GB beside its chunk are free
    void store_watch() {
        if (!store) return;
        static int tick = 0;
        if (++tick % 16 != 0) return;
        const uint64_t avail = ram_avail();
        if (avail == ~uint64_t{0} || avail >= (4ull << 30)) return;
        const size_t chunks = 1 + (size_t) (((5ull << 30) - avail) / (700ull << 20));
        const size_t n = store->shrink_chunks(chunks);
        if (n > 0) std::fprintf(stderr, "ds4: RAM store: %.1f GB free: gave back %zu chunks (%zu slots left)\n", avail / 1e9, n, store->slots_allocated());
    }
    // the window's finished moves, taken out under the lock into these and left empty here, so the two buffers of each
    // kind trade places and keep their room (they were new vectors each window, and the movers' push_back reallocated)
    std::vector<Swap> sw_ready_tick;
    std::vector<RamSwap> ram_ready_tick;
    void cache_tick_swaps(int T) {
        if (!o.expert_cache || cache_ths.empty()) {   // no cache to read them: the lane's hit lists emptied (they grew
            for (Layer& l : L) l.cpu_hits.clear();     // without bound before, --no-expert-cache)
            return;
        }
        std::vector<Swap>& ready = sw_ready_tick;
        std::vector<RamSwap>& rready = ram_ready_tick;
        ready.clear();
        rready.clear();
        if (c_det && (sw_inflight > 0 || ram_inflight > 0)) cache_drain();   // DS4_CACHE_DET (test only)
        {
            std::lock_guard<std::mutex> lk(sw_mu);
            ready.swap(sw_ready);
            rready.swap(ram_ready);
        }
        for (const RamSwap& rs : rready) {   // (nothing reads the tier between windows)
            --ram_inflight;
            Layer& l = L[(size_t) rs.layer];
            if (rs.in < 0 || l.ram[(size_t) rs.in] >= 0 || l.slot[(size_t) rs.in] >= 0) {
                ram_free.push_back(rs.slot);
                continue;
            }
            l.ram[(size_t) rs.in] = rs.slot;
            if (rs.out >= 0 && l.ram[(size_t) rs.out] >= 0) {
                ram_free.push_back(l.ram[(size_t) rs.out]);
                l.ram[(size_t) rs.out] = -1;
            }
            ++st.ram_moves;
        }
        for (const Swap& sw : ready) {
            Layer& l = L[(size_t) sw.layer];
            const int old_slot = l.slot[(size_t) sw.out];
            const std::array<uint8_t*, 4> old_parts = l.hh[(size_t) sw.in];
            if (copy_mode && shared_store) {   // (the shared store holds every expert: `in` leaves the lane, `out` joins it at its own place)
                l.ram[(size_t) sw.in] = -1;
                if (shared_slot0[(size_t) l.il] >= 0) l.ram[(size_t) sw.out] = shared_slot0[(size_t) l.il] + sw.out;
            } else if (copy_mode) {   // (`out` takes the RAM place `in` leaves: through the spare, which `in`'s slot becomes)
                const int s_in = l.ram[(size_t) sw.in];
                l.ram[(size_t) sw.in] = -1;
                if (sw.ram >= 0) {
                    l.ram[(size_t) sw.out] = sw.ram;
                    copy_spare[(size_t) l.il] = s_in;
                } else if (s_in >= 0) {   // (the move into RAM failed: `out` back to the file, one copy fewer)
                    --ram_held;
                    if (copy_spare[(size_t) l.il] < 0) copy_spare[(size_t) l.il] = s_in;
                }
            } else if (!l.ram.empty() && l.ram[(size_t) sw.in] >= 0) {   // (in VRAM now: its RAM slot for the next hottest)
                ram_free.push_back(l.ram[(size_t) sw.in]);
                l.ram[(size_t) sw.in] = -1;
            }
            l.slot[(size_t) sw.in] = l.spare_vram;
            if (!l.zc.empty() && l.zc[(size_t) sw.in]) {   // (VRAM's now: not the store's to compute any more)
                l.zc[(size_t) sw.in] = 0;
                if (l.zc_tab != nullptr) {   // (the device's table too: its entry pointed into the slot the store now reuses - when `in` left VRAM later,
                                             // zc_stage copied whatever lay there, another expert's blob, into the plan)
                    cudaSetDevice(devs[0].id);
                    cudaMemsetAsync(l.zc_tab + sw.in, 0, 8, devs[0].st);
                }
                store->unmark(l.il, sw.in);
            }
            if (l.nm == 1) set_vm(l, sw.in, l.spare_vram);
            l.hh[(size_t) sw.in] = {nullptr, nullptr, nullptr, nullptr};
            l.host[(size_t) sw.in] = nullptr;
            l.slot[(size_t) sw.out] = -1;
            if (l.lay.fmt == gg::kFmtMXFP4) {   // (the file has it)
                l.host[(size_t) sw.out] = (uint8_t*) mx_mat(l, sw.out, 0);
            } else if (file_experts) {   // (back to its pages in the file)
                l.hh[(size_t) sw.out] = {file_part(l, sw.out), nullptr, nullptr, nullptr};
                l.host[(size_t) sw.out] = l.hh[(size_t) sw.out][0];
            } else {
                l.hh[(size_t) sw.out] = l.spare_host;
                l.host[(size_t) sw.out] = l.spare_host[0];
                l.spare_host = old_parts;
            }
            l.spare_vram = old_slot;
            for (int m = 0; m < l.nm; ++m) {
                Layer& x = member(l, m);
                const Dev& dm = devs[(size_t) x.dev];
                l.tab_pin[2 * m] = (unsigned long long) (x.vram_base + (size_t) l.slot[(size_t) sw.in] * unit(x));
                l.tab_pin[2 * m + 1] = 0ull;
                cudaSetDevice(dm.id);   // (stream order: before the next window)
                cudaMemcpyAsync(x.vram_tab + sw.in, &l.tab_pin[2 * m], 8, cudaMemcpyHostToDevice, dm.st);
                cudaMemcpyAsync(x.vram_tab + sw.out, &l.tab_pin[2 * m + 1], 8, cudaMemcpyHostToDevice, dm.st);
            }
            l.swap_pending = false;
            --sw_inflight;
            ++st.swaps;
        }
        decay_tokens += T;
        if (decay_tokens >= 256) {   // older use counts less: x0.9 every 256 tokens
            decay_tokens = 0;
            for (Layer& l : L)
                for (float& h : l.heat) h *= c_decay;
        }
        if (c_frozen) {   // DS4_CACHE_FREEZE (test only): nothing queued any more
            for (Layer& l : L) l.cpu_hits.clear();
            return;
        }
        bool queued = false, rqueued = false;
        for (Layer& l : L) {
            if (l.cpu_hits.empty()) continue;
            // read in place and emptied at the end of the layer (keeping its room): swapping it out into a local
            // freed the buffer every window, and the lane's next push_back allocated it again, a layer at a time
            const std::vector<int>& hits = l.cpu_hits;
            struct ClearAtEnd {
                std::vector<int>& v;
                ~ClearAtEnd() { v.clear(); }
            } clear_hits{l.cpu_hits};
            int best = -1, vin = -1;
            for (int e : hits) {
                if (l.slot[(size_t) e] >= 0) continue;
                if (ec_fix && hlp.owns(l.il, e)) {   // (DS4_EC_FIX: the helper computes it; never into VRAM)
                    ++ec_left;
                    continue;
                }
                if (best < 0 || l.heat[(size_t) e] > l.heat[(size_t) best]) best = e;
            }
            if (best >= 0 && l.spare_vram >= 0 && !l.swap_pending && sw_inflight < c_inflight) {   // VRAM: the hottest in
                int cold = -1;
                for (int e = 0; e < l.n_exp; ++e)
                    if (l.slot[(size_t) e] >= 0 && (cold < 0 || l.heat[(size_t) e] < l.heat[(size_t) cold])) cold = e;
                if (cold >= 0 && l.heat[(size_t) best] > l.heat[(size_t) cold] * c_margin + c_bonus) {
                    l.swap_pending = true;
                    ++sw_inflight;
                    vin = best;
                    Swap sw{l.il, best, cold};
                    if (copy_mode && l.ram[(size_t) best] >= 0) sw.ram = copy_spare[(size_t) l.il];   // (-1: none)
                    std::lock_guard<std::mutex> lk(sw_mu);
                    sw_queue.push_back(sw);
                    queued = true;
                }
            }
            if (l.ram.empty() || ram_free.empty() || ram_inflight >= kMaxSwaps) continue;
            int rb = -1;   // RAM: the hottest read from the file, in place of the layer's coldest held (or a free slot)
            for (int e : hits)
                if (e != vin && l.slot[(size_t) e] < 0 && l.ram[(size_t) e] < 0 && !(ec_fix && hlp.owns(l.il, e)) &&
                    (rb < 0 || l.heat[(size_t) e] > l.heat[(size_t) rb]))
                    rb = e;
            if (rb < 0) continue;
            int rc = -1;
            for (int e = 0; e < l.n_exp; ++e)
                if (l.ram[(size_t) e] >= 0 && (rc < 0 || l.heat[(size_t) e] < l.heat[(size_t) rc])) rc = e;
            const bool room = ram_free.size() > 1;   // (slots VRAM freed: filled at once)
            if (!room && !(rc >= 0 && l.heat[(size_t) rb] > l.heat[(size_t) rc] * 1.25f + 1.0f)) continue;
            RamSwap rs;
            rs.layer = l.il;
            rs.in = rb;
            rs.out = room ? -1 : rc;
            rs.slot = ram_free.back();
            ram_free.pop_back();
            ++ram_inflight;
            std::lock_guard<std::mutex> lk(sw_mu);
            ram_queue.push_back(rs);
            rqueued = true;
        }
        if (queued) sw_cv.notify_all();
        if (rqueued) ram_cv.notify_one();
    }

    // lookahead's thread: the ranges the CPU lane asked for, read in (os::prefetch) off the lane, which computes
    void prefetch_loop() {
        std::vector<std::pair<const void*, size_t>> b;
        for (;;) {
            {
                std::unique_lock<std::mutex> lk(pf_mu);
                pf_cv.wait(lk, [&] { return quit.load(std::memory_order_relaxed) || !pf_q.empty(); });
                if (quit.load(std::memory_order_relaxed)) return;
                b.swap(pf_q);
            }
            os::prefetch_cold(b);   // (the resident ones would only cost the page walk)
            b.clear();
        }
    }
    // an expert the CPU lane reads from the files (neither in VRAM nor in the RAM tier)
    static bool file_read(const Layer& l, int e) {
        return l.slot[(size_t) e] < 0 && (l.ram.empty() || l.ram[(size_t) e] < 0);
    }
    // the layer whose picks layer l0 guesses a layers ahead (1, 2): the next ones of its stack on its device, MXFP4
    // experts read in place, some of them from the files now (none: nothing to read early - null)
    const Layer* ahead_layer(const Layer& l0, int a) const {
        const int j = l0.il + a, end = l0.mtp ? g.nl + g.n_mtp : g.nl;
        if (j >= end || j >= (int) L.size()) return nullptr;
        const Layer& n = L[(size_t) j];
        if (n.mtp && draft_mod()) return nullptr;   // (DS4_DRAFT_*: no lookahead gate on the drafter's critical path)
        if (n.dev != l0.dev || n.mtp != l0.mtp || n.lay.fmt != gg::kFmtMXFP4 || n.gate_w == nullptr || n.n_exp > 1024 ||
            (int) n.slot.size() < n.n_exp)
            return nullptr;
        for (int e = 0; e < n.n_exp; ++e)
            if (file_read(n, e)) return &n;
        return nullptr;
    }
    // lookahead on the CPU lane: request r (layer li, seq) carries the device's guesses for the next layers - the
    // guessed experts read from the files asked for now (each once a window), the guesses kept for the hit counts
    std::vector<std::pair<const void*, size_t>> pf_want;
    void ahead_ask(int li, const Req& r, unsigned seq, int T) {
        pf_want.clear();
        for (int a = 1; a <= 2; ++a) {
            const int m = std::min(r.na[a - 1], a == 1 ? kAhead1 : kPicks), j = li + a;
            if (m <= 0 || j >= (int) L.size()) continue;
            const Layer& n = L[(size_t) j];
            uint8_t* fl = ahead_fl.data() + (size_t) j * 1024;
            uint8_t* rk = ahead_rank.data() + (size_t) j * 1024;
            if (ahead_for[(size_t) j] != seq + (unsigned) a) {
                std::memset(fl, 0, 1024);
                std::memset(rk, 0, 1024);
                ahead_for[(size_t) j] = seq + (unsigned) a;
            }
            for (int t = 0; t < T; ++t)
                for (int i = 0; i < m; ++i) {
                    const int e = r.ahead[t][(a - 1) * kAhead1 + i];
                    if (e < 0 || e >= n.n_exp || e >= (int) n.slot.size()) continue;
                    fl[e] |= a == 2 ? 4 : (i < n.k_exp ? 3 : 2);
                    if (a == 1 && (rk[e] == 0 || rk[e] > i + 1)) rk[e] = (uint8_t) (i + 1);
                    if ((fl[e] & 8) || !file_read(n, e) || hlp.owns(j, e)) continue;   // (the helper's never need the RAM tier)
                    fl[e] |= 8;
                    if (store) store->prefetch(j, e);
                    else
                        for (int q = 0; q < 3; ++q) pf_want.push_back({mx_mat(n, e, q), mx_part_bytes(n, q)});
                    ++st.ahead_pf;
                }
        }
        if (pf_want.empty()) return;
        {
            std::lock_guard<std::mutex> lk(pf_mu);
            pf_q.insert(pf_q.end(), pf_want.begin(), pf_want.end());
        }
        pf_cv.notify_one();
    }

    // the decode path's host side: each published routing in turn - its CPU lane experts (if any) into the answer's
    // part, then the answer's seq.  Spins while requests come (a token's 40 layers), naps after 2 ms without one.
    void serve_lane() {
        unsigned next = 1;
        auto last = std::chrono::steady_clock::now();
        std::vector<Ent> ents;
        // a request's lists, kept from request to request and sized for a whole window (kSlots picks) now: the lane
        // allocates nothing per layer (they were new vectors each request, ~5 a layer with a helper)
        std::vector<std::pair<int, int>> picks, fp;   // (expert, t * kPicks + i), CPU-lane only; (the helper's failed ones)
        std::vector<helper::Pick> hpicks, rej, hfail;  // the picks the helper expert cache owns; its rejected / failed ones
        std::vector<helper::Pick> himm, hdef, drej;    // DS4_HELPER_DEFER: kept in the layer / deferred / deferred for the CPU
        himm.reserve(kSlots);
        hdef.reserve(kSlots);
        drej.reserve(kSlots);
        ents.reserve(kSlots);
        picks.reserve(kSlots);
        fp.reserve(kSlots);
        hpicks.reserve(kSlots);
        rej.reserve(kSlots);
        hfail.reserve(kSlots);
        double tl_pub = 0.0;   // (DS4_HELPER_TIMELINE) the last answer's publish time
        if (helper_tl && htl.empty()) htl.resize((size_t) kWin + 1 + L.size());
        while (!quit.load(std::memory_order_relaxed)) {
            Req& r = reqs[next % kRing];
            if (*(volatile unsigned*) &r.seq != next) {
                cpu_relax();
                // (a decode layer takes ~2.8 ms on a Strix Halo, longer than the old 2 ms spin window, so the thread slept
                // before every request and Windows' sleep_for(20 us) wakes after ~1 ms or more: the lane's round trip.  Now it
                // spins for DS4_LANE_SPIN_MS (default 250) after its last answer, i.e. through a whole decode token.)
                static const long spin_ms = std::getenv("DS4_LANE_SPIN_MS") ? std::atol(std::getenv("DS4_LANE_SPIN_MS")) : 250;
                if (std::chrono::steady_clock::now() - last > std::chrono::milliseconds(spin_ms)) {
#if defined(_WIN32)
                    // DS4_LANE_NAP=sleep turns it off: a high-resolution waitable timer (Windows 10 1803+) instead of sleep_for's timer tick
                    static const bool hires = !(std::getenv("DS4_LANE_NAP") != nullptr && std::string(std::getenv("DS4_LANE_NAP")) == "sleep");
                    static HANDLE tmr = hires ? CreateWaitableTimerExW(nullptr, nullptr, 0x2 /* CREATE_WAITABLE_TIMER_HIGH_RESOLUTION */, TIMER_ALL_ACCESS) : nullptr;
                    if (tmr != nullptr) {
                        LARGE_INTEGER due;
                        due.QuadPart = -200;   // 20 us in 100 ns units
                        SetWaitableTimer(tmr, &due, 0, nullptr, nullptr, FALSE);
                        WaitForSingleObject(tmr, 5);
                    } else
#endif
                    hlp.arm_drop();   // (DS4_HELPER_ARMED: an armed window cancelled before a nap; a no-op when off)
                    std::this_thread::sleep_for(std::chrono::microseconds(20));
                }
                continue;
            }
            std::atomic_thread_fence(std::memory_order_acquire);
            const double tl_seen = helper_tl ? now_ms() : 0.0;   // (DS4_HELPER_TIMELINE)
            double tl_iss = 0.0, tl_mid = 0.0, tl_join = 0.0;
            size_t tl_hn = 0;   // (the request's picks the helpers took)
            os::malloc_pin_thread();   // this thread's arena pre-grown once the decode is pinned (ds4_os.hpp)
            const int li = layer_of[next % kRing].load(std::memory_order_acquire);
            Resp& rp = resps[next % kRing];
            const int T = std::max(1, std::min(kWin, r.T));
            for (int t = 0; t < T; ++t) rp.cpu[t] = 0;
            int arm_li = -1;   // DS4_HELPER_ARMED: the layer whose windows are armed after this answer (-1: none)
            if (li >= 0 && li < (int) L.size()) {
                Layer& l = L[(size_t) li];
                uint32_t* pr = prof.data() + (size_t) li * g.n_exp;
                ents.clear();
                if (store && li > 0 && li < g.nl) store->cancel_stale(li - 1);   // (guesses for layers the token has passed: dropped unread)
                // lookahead: the guesses made for this layer (when they are for this request), counted on decode
                const uint8_t* fl = T == 1 && !ahead_for.empty() && ahead_for[(size_t) li] == next
                                        ? ahead_fl.data() + (size_t) li * 1024 : nullptr;
                // the window's CPU-lane picks by expert (up to 8 tokens an entry), their weights by entry row
                float wv[kWin * kPicks];
                int tok_of[kWin * kPicks];
                int nslots = 0;
                picks.clear();
                hpicks.clear();
                const bool hon = hlp.enabled();
                const bool arm_ok = hon && hlp.armed_on();   // DS4_HELPER_ARMED
                // the helper's picks issued (its device computes while the CPU lane does); an issue failure hands them
                // to the CPU lane (the files still hold every expert).  Then (DS4_HELPER_ARMED) the helpers this request
                // gave nothing are told so (no-ops when off), and the next layer is armed after the answer.
                double th0 = 0.0;
                size_t hn_issued = 0;
                bool issued_early = false;
                // DS4_HELPER_DEFER: this request's helper picks split into the ones answered in the layer (route weight >=
                // DEFER_MAXW; none by default) and the deferred ones.  With nothing kept, the deferred ones are issued at once
                // (def_live); else after the in-layer answer (the helper takes one window at a time)
                const bool dfr = defer_at(li, T);
                bool def_live = false;
                size_t hd_issued = 0;
                himm.clear();
                hdef.clear();
                drej.clear();
                const bool ddr = hon && dd_at(li, T);   // DS4_HELPER_DD: this request's helper rows are joined on the device
                const auto issue_helpers = [&]() {
                    if (ddr) {   // (the helpers armed for it read it themselves; one that is not: the host answers it, its picks the CPU's)
                        if (dd_audit) {   // DS4_DD_AUDIT (before dd_check: the armed state the heads see; reads only)
                            long long np = 0, nd = 0, ns = 0, nu = 0, wq = 0;
                            if (ecown) {   // DS4_ECOWN: the lead's own marks (Req::vmask) decide, not the lane's l.slot
                                long long nh = 0, nx = 0, nz = 0;
                                for (int t = 0; t < T; ++t) {
                                    const unsigned vm = r.vmask[t];
                                    bool on_cpu = false;   // (route_publish's rule, from the marks: a pick not in VRAM)
                                    for (int i = 0; i < l.k_exp; ++i) on_cpu = on_cpu || ((vm >> i) & 1u) == 0u;
                                    int td = 0;
                                    for (int i = 0; i < l.k_exp; ++i) {
                                        const int e = r.ids[t][i];
                                        if (e < 0 || e >= l.n_exp) continue;
                                        ++np;
                                        const bool vb = ((vm >> i) & 1u) != 0u;
                                        if (vb != (l.slot[(size_t) e] >= 0)) ++nx;   // (the lane's table and the lead's marks differ)
                                        const int o = dd_aud_own[(size_t) li * (size_t) dd_aud_nexp + (size_t) e];
                                        if (o < 0) continue;
                                        if (!hlp.at((size_t) o).dd_armed(next, li, T)) {
                                            ++nu;
                                            continue;
                                        }
                                        if (vb) {   // (the lead's: the head leaves it out)
                                            ++nh;
                                            continue;
                                        }
                                        // (the helper's - and the lead's too only if its plan entry is not 0 after all: the store's
                                        //  zero-copy staging of a T = 1 request's off-VRAM pick)
                                        if (T == 1 && !l.zc.empty() && l.zc[(size_t) e]) {
                                            ++nz;
                                            ++td;
                                            wq += std::llround((double) r.w[t][i] * 1e6);
                                        }
                                    }
                                    nd += td;
                                    if (td > 0 && !on_cpu) ns += td;
                                }
                                if (nh > 0) ec_handed.fetch_add(nh, std::memory_order_relaxed);
                                if (nx > 0) ec_disagree.fetch_add(nx, std::memory_order_relaxed);
                                if (nz > 0) ec_zc.fetch_add(nz, std::memory_order_relaxed);
                            } else
                            for (int t = 0; t < T; ++t) {
                                bool on_cpu = false;   // (route_publish's rule: x written only for a token with a non-VRAM pick)
                                int td = 0;
                                for (int i = 0; i < l.k_exp; ++i) {
                                    const int e = r.ids[t][i];
                                    if (e < 0 || e >= l.n_exp) continue;
                                    ++np;
                                    if (l.slot[(size_t) e] < 0) {
                                        on_cpu = true;
                                        continue;
                                    }
                                    const int o = dd_aud_own[(size_t) li * (size_t) dd_aud_nexp + (size_t) e];
                                    if (o < 0) continue;
                                    if (!hlp.at((size_t) o).dd_armed(next, li, T)) {   // (its host answer has no rows: not joined twice)
                                        ++nu;
                                        continue;
                                    }
                                    ++td;
                                    wq += std::llround((double) r.w[t][i] * 1e6);
                                }
                                nd += td;
                                if (td > 0 && !on_cpu) ns += td;
                            }
                            dd_aud_req.fetch_add(1, std::memory_order_relaxed);
                            dd_aud_picks.fetch_add(np, std::memory_order_relaxed);
                            if (nd > 0) {
                                dd_aud_dreq.fetch_add(1, std::memory_order_relaxed);
                                dd_aud_dbl.fetch_add(nd, std::memory_order_relaxed);
                                dd_aud_stale.fetch_add(ns, std::memory_order_relaxed);
                                dd_aud_wq.fetch_add(wq, std::memory_order_relaxed);
                                dd_aud_layer[(size_t) li].fetch_add(nd, std::memory_order_relaxed);
                            }
                            if (nu > 0) dd_aud_unarmed.fetch_add(nu, std::memory_order_relaxed);
                        }
                        rej.clear();
                        if (hlp.dd_check(next, li, T, hpicks, rej) > 0) {
                            static std::atomic<int> said{0};
                            if (said.fetch_add(1) < 5)
                                std::fprintf(stderr, "ds4 helper: DS4_HELPER_DD: request %u (layer %d, T %d) found a helper not armed for it: %zu picks to the CPU lane\n",
                                             next, li, T, rej.size());
                        }
                        for (const helper::Pick& p : rej) picks.push_back({p.e, p.t * kPicks + p.i});
                        dd_cpu_n += (int64_t) rej.size();
                        ++dd_req_n;
                        st.helper_experts += (int64_t) hpicks.size() - (int64_t) rej.size();
                        if (helper_tl) tl_iss = now_ms();
                        return;
                    }
                    if (hon && dfr) {
                        for (const helper::Pick& p : hpicks) (r.w[p.t][p.i] < defer_maxw ? hdef : himm).push_back(p);
                        defer_kept += (int64_t) himm.size();
                        if (!defer_lanes && himm.empty() && !hdef.empty()) {   // (one lane, nothing kept: the deferred ones now)
                            th0 = now_ms();
                            rej.clear();
                            hlp.begin(li, r, T, hdef.data(), (int) hdef.size(), rej);
                            drej.insert(drej.end(), rej.begin(), rej.end());   // (computed on the CPU into the deferred rows)
                            hd_issued = hdef.size() - rej.size();
                            def_live = hd_issued > 0;
                            st.helper_ms += now_ms() - th0;
                        }
                    }
                    std::vector<helper::Pick>& now_p = hon && dfr ? himm : hpicks;
                    if (hon && !now_p.empty()) {
                        th0 = now_ms();
                        rej.clear();
                        hlp.begin(li, r, T, now_p.data(), (int) now_p.size(), rej);
                        for (const helper::Pick& p : rej) picks.push_back({p.e, p.t * kPicks + p.i});
                        hn_issued = now_p.size() - rej.size();
                        st.helper_ms += now_ms() - th0;
                    }
                    if (hon && dfr && defer_lanes && !hdef.empty()) {   // (two windows in flight: the deferred ones on the second
                        th0 = now_ms();                                  //  lanes, right after the kept ones - the critical path - went)
                        rej.clear();
                        hlp.begin_deferred(li, r, T, hdef.data(), (int) hdef.size(), rej);
                        drej.insert(drej.end(), rej.begin(), rej.end());
                        hd_issued = hdef.size() - rej.size();
                        def_live = hd_issued > 0;
                        st.helper_ms += now_ms() - th0;
                    }
                    if (hon) {
                        hlp.arm_drop();
                        if (arm_ok && !l.mtp && li + 1 < g.nl) arm_li = li + 1;
                    }
                    if (helper_tl) tl_iss = now_ms();
                };
                // DS4_HELPER_OVERLAP: the helper's picks found and issued first (the same list in the same (t, i)
                // order as the loop below makes it); the bookkeeping, the lookahead's requests and the trace record after
                if (hon && helper_overlap) {
                    for (int t = 0; t < T; ++t)
                        for (int i = 0; i < l.k_exp; ++i) {
                            const int e = r.ids[t][i];
                            if (e < 0 || e >= l.n_exp) continue;
                            if (l.slot[(size_t) e] < 0 && hlp.owns(li, e)) hpicks.push_back({t, i, e});
                        }
                    issue_helpers();
                    issued_early = true;
                }
                if (trace_f != nullptr && !l.mtp) {   // DS4_TRACE=file: one record a route request: u8 layer, u8 T, T x k int16 expert ids
                    // DS4_TRACE_AHEAD=1: T has bit 7 set and the guesses follow: u8 na1, u8 na2, T x (na1 + na2) int16 (the
                    // next layer's likely picks by rank, then the one after's), as the lookahead made them for THIS layer's
                    // predecessors (the request carries the guesses for the layers after it)
                    static const bool with_ahead = std::getenv("DS4_TRACE_AHEAD") != nullptr;
                    uint8_t hd[2] = {(uint8_t) li, (uint8_t) (T | (with_ahead ? 0x80 : 0))};
                    std::fwrite(hd, 1, 2, trace_f);
                    for (int t = 0; t < T; ++t)
                        for (int i = 0; i < l.k_exp; ++i) {
                            const int16_t v = (int16_t) r.ids[t][i];
                            std::fwrite(&v, 2, 1, trace_f);
                        }
                    if (with_ahead) {
                        const uint8_t na[2] = {(uint8_t) std::max(0, std::min(r.na[0], kAhead1)), (uint8_t) std::max(0, std::min(r.na[1], kPicks))};
                        std::fwrite(na, 1, 2, trace_f);
                        for (int t = 0; t < T; ++t) {
                            for (int i = 0; i < na[0]; ++i) {
                                const int16_t v = (int16_t) r.ahead[t][i];
                                std::fwrite(&v, 2, 1, trace_f);
                            }
                            for (int i = 0; i < na[1]; ++i) {
                                const int16_t v = (int16_t) r.ahead[t][kAhead1 + i];
                                std::fwrite(&v, 2, 1, trace_f);
                            }
                        }
                    }
                }
                const bool dsk = disk_skip_w > 0.0f && !l.mtp && li >= disk_skip_from && li < g.nl;
                uint64_t* dpk = l.mtp && !dpick.empty() ? dpick.data() + (size_t) (li - g.nl) * g.d_n_exp : nullptr;
                if (l.mtp && !dcal_gu.empty()) draft_cal(l, li, r, T);   // DS4_DRAFT_CAL
                for (int t = 0; t < T; ++t) {
                    float wsum = 0.0f;   // (DISK_SKIP_W: the token's route weights)
                    if (dsk)
                        for (int i = 0; i < l.k_exp; ++i)
                            if (r.ids[t][i] >= 0 && r.ids[t][i] < l.n_exp) wsum += r.w[t][i];
                    for (int i = 0; i < l.k_exp; ++i) {
                        const int e = r.ids[t][i];
                        if (e < 0 || e >= l.n_exp) continue;
                        ++pr[e];
                        if (dpk != nullptr) ++dpk[e];
                        l.heat[(size_t) e] += 1.0f;
                        if (fl != nullptr) {
                            ++st.ahead_picks;
                            st.ahead_hit_k += fl[e] & 1;
                            st.ahead_hit += (fl[e] & 6) != 0;
                            st.ahead_hit2 += (fl[e] >> 2) & 1;
                        }
                        if (hon && l.slot[(size_t) e] < 0 && hlp.owns(li, e)) {   // the helper's (counted in pr / heat above; not a CPU hit)
                            if (!issued_early) hpicks.push_back({t, i, e});   // (DS4_HELPER_OVERLAP: listed and issued above)
                            continue;
                        }
                        if (l.slot[(size_t) e] < 0) {
                            l.cpu_hits.push_back(e);
                            if (T == 1 && !l.zc.empty() && l.zc[(size_t) e]) {   // the device computed it from the store's slot
                                store->touch(li, e);
                                ++st.store_zc;
                                continue;
                            }
                            if (dsk && r.w[t][i] < disk_skip_w * wsum && !in_ram(l, e)) {
                                ++st.skipped;
                                continue;
                            }
                            if (!l.ram.empty() && l.ram[(size_t) e] >= 0) ++st.ram_experts;
                            else if (fl != nullptr) {
                                ++st.ahead_cold;
                                st.ahead_cold_hit += (fl[e] >> 3) & 1;
                            }
                            picks.push_back({e, t * kPicks + i});
                        }
                    }
                }
                if (fl != nullptr) {   // the guesses by rank: how many were picked
                    const uint8_t* rk = ahead_rank.data() + (size_t) li * 1024;
                    for (int e = 0; e < l.n_exp && e < 1024; ++e) {
                        if (rk[e] == 0 || rk[e] > 16) continue;
                        bool hit = false;
                        for (int i = 0; i < l.k_exp; ++i) hit = hit || r.ids[0][i] == e;
                        ++st.ahead_rank_n[rk[e] - 1];
                        st.ahead_rank_hit[rk[e] - 1] += hit;
                    }
                }
                if (ahead_mode > 0 && !ahead_for.empty()) ahead_ask(li, r, next, T);
                if (!issued_early) issue_helpers();   // (the place it always had)
                std::sort(picks.begin(), picks.end());
                for (size_t a = 0; a < picks.size();) {
                    Ent en;
                    en.e = picks[a].first;
                    en.slot0 = nslots;
                    en.n = 0;
                    while (a < picks.size() && picks[a].first == en.e && en.n < ent_cap(l)) {
                        const int t = picks[a].second / kPicks, i = picks[a].second % kPicks;
                        en.tok[en.n++] = t;
                        tok_of[nslots] = t;
                        wv[nslots] = r.w[t][i];
                        ++nslots;
                        ++a;
                    }
                    ents.push_back(en);
                }
                // lookahead: the entries asked for early (or in the RAM tier) computed first, so the ones asked for
                // only now get the others' time to come in from the SSD (their slots, so the sums, stay the same)
                int ord[kWin * kPicks];
                const int* po = nullptr;
                if (ahead_order && !ahead_for.empty() && ahead_for[(size_t) li] == next && ents.size() > 1 &&
                    ents.size() <= (size_t) (kWin * kPicks)) {
                    const uint8_t* fa = ahead_fl.data() + (size_t) li * 1024;
                    int n = 0;
                    for (int pass = 0; pass < 2; ++pass)
                        for (size_t q = 0; q < ents.size(); ++q) {
                            const int e = ents[q].e;
                            const bool early = !file_read(l, e) || (fa[e] & 8) != 0;
                            if (early == (pass == 0)) ord[n++] = (int) q;
                        }
                    po = ord;
                }
                static const bool lane_skip = std::getenv("DS4_LANE_SKIP") != nullptr;   // (timing oracle: the lane's compute left out; rp.cpu stays 0)
                if (!ents.empty() && lane_skip) { for (int t = 0; t < T; ++t) rp.cpu[t] = 0; }
                else if (!ents.empty()) {
                    const double tc = now_ms();
                    cpu_experts(l, &r.x[0][0], ents, (size_t) kMaxDim, po);
                    const int D = g.dim;
                    for (int t = 0; t < T; ++t) {
                        bool any = false;
                        for (int sl = 0; sl < nslots; ++sl) any = any || tok_of[sl] == t;
                        if (!any) continue;
                        float* o = rp.part[t];
                        for (int e = 0; e < D; ++e) o[e] = 0.0f;
                        for (int sl = 0; sl < nslots; ++sl) {
                            if (tok_of[sl] != t) continue;
                            const float* y = c_yd.data() + (size_t) sl * D;
                            for (int e = 0; e < D; ++e) o[e] += wv[sl] * y[e];
                        }
                        rp.cpu[t] = 1;
                    }
                    st.cpu_ms += now_ms() - tc;
                    st.cpu_experts += nslots;
                }
                if (helper_tl) {
                    tl_mid = now_ms();
                    tl_hn = hn_issued;
                }
                if (hon && hn_issued > 0) {   // the helpers' weighted parts joined into the same answer
                    const double tj = now_ms();
                    hfail.clear();
                    hlp.finish(rp, T, hfail);
                    if (helper_delay_ms > 0.0) {   // DS4_HELPER_DELAY_US (test only): the answer N us later
                        const double until = now_ms() + helper_delay_ms;
                        while (now_ms() < until) cpu_relax();
                        ++helper_delay_n;
                    }
                    st.helper_ms += now_ms() - tj;
                    st.helper_experts += (int64_t) hn_issued - (int64_t) hfail.size();
                    if (!hfail.empty()) {   // pool client: the serving engine did not answer; the CPU lane computes those picks now (the files hold every expert)
                        fp.clear();
                        for (const helper::Pick& p : hfail) fp.push_back({p.e, p.t * kPicks + p.i});
                        std::sort(fp.begin(), fp.end());
                        ents.clear();
                        nslots = 0;
                        for (size_t a = 0; a < fp.size();) {
                            Ent en;
                            en.e = fp[a].first;
                            en.slot0 = nslots;
                            en.n = 0;
                            while (a < fp.size() && fp[a].first == en.e && en.n < ent_cap(l)) {
                                const int t = fp[a].second / kPicks, i = fp[a].second % kPicks;
                                en.tok[en.n++] = t;
                                tok_of[nslots] = t;
                                wv[nslots] = r.w[t][i];
                                ++nslots;
                                ++a;
                            }
                            ents.push_back(en);
                        }
                        const double tc = now_ms();
                        cpu_experts(l, &r.x[0][0], ents, (size_t) kMaxDim, nullptr);
                        const int D = g.dim;
                        for (int t = 0; t < T; ++t) {
                            bool any = false;
                            for (int sl = 0; sl < nslots; ++sl) any = any || tok_of[sl] == t;
                            if (!any) continue;
                            float* o = rp.part[t];
                            if (!rp.cpu[t])
                                for (int e = 0; e < D; ++e) o[e] = 0.0f;
                            for (int sl = 0; sl < nslots; ++sl) {
                                if (tok_of[sl] != t) continue;
                                const float* y = c_yd.data() + (size_t) sl * D;
                                for (int e = 0; e < D; ++e) o[e] += wv[sl] * y[e];
                            }
                            rp.cpu[t] = 1;
                        }
                        st.cpu_ms += now_ms() - tc;
                        st.cpu_experts += nslots;
                    }
                }
                if (dfr) {   // DS4_HELPER_DEFER: the layer answered now (CPU-lane and kept rows), the deferred rows after it
                    if (helper_tl) tl_join = now_ms();
                    std::atomic_thread_fence(std::memory_order_release);
                    *(volatile unsigned*) &rp.seq = next;   // (stored again below: the same value)
                    Resp& dp = dresps[next % kRing];
                    for (int t = 0; t < T; ++t) dp.cpu[t] = 0;
                    if (!def_live && !hdef.empty() && !defer_lanes) {   // (one lane: the kept picks went first, the deferred ones now)
                        const double t0 = now_ms();
                        rej.clear();
                        hlp.begin(li, r, T, hdef.data(), (int) hdef.size(), rej);
                        drej.insert(drej.end(), rej.begin(), rej.end());
                        hd_issued = hdef.size() - rej.size();
                        def_live = hd_issued > 0;
                        st.helper_ms += now_ms() - t0;
                    }
                    if (def_live) {
                        const double tj = now_ms();
                        hfail.clear();
                        if (defer_lanes) hlp.finish_deferred(dp, T);
                        else hlp.finish(dp, T, hfail);
                        if (helper_delay_ms > 0.0) {   // (DS4_HELPER_DELAY_US: the deferred answer too)
                            const double until = now_ms() + helper_delay_ms;
                            while (now_ms() < until) cpu_relax();
                            ++helper_delay_n;
                        }
                        st.helper_ms += now_ms() - tj;
                        st.helper_experts += (int64_t) hd_issued - (int64_t) hfail.size();
                        drej.insert(drej.end(), hfail.begin(), hfail.end());
                    }
                    if (!drej.empty()) {   // (issue failures / a dead pool server: the CPU lane computes them into the deferred rows)
                        fp.clear();
                        for (const helper::Pick& p : drej) fp.push_back({p.e, p.t * kPicks + p.i});
                        std::sort(fp.begin(), fp.end());
                        ents.clear();
                        nslots = 0;
                        for (size_t a = 0; a < fp.size();) {
                            Ent en;
                            en.e = fp[a].first;
                            en.slot0 = nslots;
                            en.n = 0;
                            while (a < fp.size() && fp[a].first == en.e && en.n < ent_cap(l)) {
                                const int t = fp[a].second / kPicks, i = fp[a].second % kPicks;
                                en.tok[en.n++] = t;
                                tok_of[nslots] = t;
                                wv[nslots] = r.w[t][i];
                                ++nslots;
                                ++a;
                            }
                            ents.push_back(en);
                        }
                        cpu_experts(l, &r.x[0][0], ents, (size_t) kMaxDim, nullptr);
                        const int D = g.dim;
                        for (int t = 0; t < T; ++t) {
                            bool any = false;
                            for (int sl = 0; sl < nslots; ++sl) any = any || tok_of[sl] == t;
                            if (!any) continue;
                            float* o = dp.part[t];
                            if (!dp.cpu[t])
                                for (int e = 0; e < D; ++e) o[e] = 0.0f;
                            for (int sl = 0; sl < nslots; ++sl) {
                                if (tok_of[sl] != t) continue;
                                const float* y = c_yd.data() + (size_t) sl * D;
                                for (int e = 0; e < D; ++e) o[e] += wv[sl] * y[e];
                            }
                            dp.cpu[t] = 1;
                        }
                        st.cpu_experts += nslots;
                    }
                    ++defer_n;
                    defer_picks += (int64_t) hdef.size();
                    std::atomic_thread_fence(std::memory_order_release);
                    *(volatile unsigned*) &dp.seq = next;
                }
            }
            if (helper_tl && tl_join == 0.0) tl_join = now_ms();
            std::atomic_thread_fence(std::memory_order_release);
            *(volatile unsigned*) &rp.seq = next;
            if (helper_tl && li >= 0 && li < (int) L.size()) {   // (DS4_HELPER_TIMELINE) requests with helper picks only
                const double tp = now_ms();
                if (tl_hn > 0 && tl_iss > 0.0 && tl_join >= tl_mid && tl_mid >= tl_iss && !L[(size_t) li].mtp) {
                    {
                        const auto add = [&](HelperTl& a) {
                            ++a.n;
                            a.gap += tl_pub > 0.0 && tl_seen - tl_pub < 1000.0 ? tl_seen - tl_pub : 0.0;
                            a.issue += tl_iss - tl_seen;
                            a.mid += tl_mid - tl_iss;
                            a.join += tl_join - tl_mid;
                            a.pub += tp - tl_join;
                            a.total += tp - tl_seen;
                        };
                        const int Tn = std::max(1, std::min(kWin, r.T));
                        add(htl[(size_t) Tn]);
                        if (Tn == 1) add(htl[(size_t) kWin + 1 + (size_t) li]);
                    }
                }
                tl_pub = tp;
            }
            if (dd_live && li >= 0 && li < (int) L.size() && !L[(size_t) li].mtp && dd_at(li + 1, T)) {
                const double ta = now_ms();   // DS4_HELPER_DD: the next layer's windows armed (they wait for its request)
                hlp.dd_arm(li + 1, T, next + 1);
                st.helper_arm_ms += now_ms() - ta;
            }
            if (arm_li >= 0) {   // DS4_HELPER_ARMED: the lane is idle until the next request: its windows launched now
                const double ta = now_ms();
                hlp.arm(arm_li, T, next + 1);
                st.helper_arm_ms += now_ms() - ta;
            }
            ++next;
            last = std::chrono::steady_clock::now();
        }
    }

    // a GGUF's matrices (BF16 / MXFP4) to its own kernels, EXL3 ones to x3's (pre: the int8 input some of them read,
    // already rounded - gg::PreQ8; null: as before)
    static bool mv_any(const x3::MvJob* j, int n, cudaStream_t s, const gg::PreQ8* pre = nullptr) {
        bool g = false;
        for (int i = 0; i < n; ++i) g = g || j[i].m->fmt != 0;
        return g ? gg::mv(j, n, s, pre) : x3::mv(j, n, s);
    }
    bool mv(Dev& d, std::initializer_list<x3::MvJob> jobs, std::string& err) {
        x3::MvJob j[x3::kMaxMvJobs];
        int n = 0;
        for (const x3::MvJob& x : jobs) j[n++] = x;
        if (!mv_any(j, n, d.st)) {
            err = "exl3 mv failed";
            return false;
        }
        return true;
    }
    bool mv_n(Dev& d, x3::MvJob* j, int n, std::string& err, const gg::PreQ8* pre = nullptr) {
        for (int a = 0; a < n; a += x3::kMaxMvJobs)
            if (!mv_any(j + a, std::min(x3::kMaxMvJobs, n - a), d.st, pre)) {
                err = "exl3 mv failed";
                return false;
            }
        return true;
    }
    // y[c] = x[c] W for the T activations x + c * x_cs (floats), into y + c * y_cs
    static x3::MvJob job(const x3::Mat& m, const float* x, float* y, int T = 1, size_t x_cs = 0, size_t y_cs = 0,
                         float alpha = 1.0f) {
        x3::MvJob j;
        j.m = &m;
        j.xf = x;
        j.y = y;
        j.alpha = alpha;
        j.ncol = T;
        j.xf_cs = x_cs;
        j.y_cs = y_cs;
        return j;
    }
    // the attention's input GEMVs of layer l on x (T rows): q's low rank, the KV row, and the compressed KV and its gate
    // where the layer has them - layer()'s and attn_batch()'s list
    int attn_in_jobs(const Layer& l, const float* x, float* qr, float* kvr, float* ckr, float* cgr, int T, x3::MvJob* j) const {
        const int D = g.dim, HD = g.hd;
        int nj = 0;
        j[nj++] = job(l.wq_a, x, qr, T, D, g.q_lora);
        j[nj++] = job(l.wkv, x, kvr, T, D, HD);
        if (l.kv_src) j[nj++] = job(l.c_wkv, x, ckr, T, D, HD);
        if (l.kv_src && l.ratio > 1) j[nj++] = job(l.c_wgate, x, cgr, T, D, HD);
        return nj;
    }
    // ---- DS4_HC_FUSE (see hc_fuse): whether a window of T rows on layer l takes the fused launch
    bool hc_fuses(const Layer& l, int T) const { return hc_fuse > 0 && !l.mtp && T >= 1 && (T == 1 || (hc_fuse > 1 && T <= kWin)); }
    // hc_mix_split_norm's arguments for layer l's attention (ffn false) or FFN on these buffers (rows at the decode
    // buffers' strides): the mix of h, the split into pre / post / comb, the norm of h by the lagged mix into x, x's int8
    // rows into q / qd, the pre slots' copy into pre_copy (null: none)
    HcFuse hc_args(const Layer& l, bool ffn, const float* h, float* mixes, unsigned* cnt, float* pre, float* post, float* comb,
                   float* pre_copy, const float* lag, const float* w, float* x, int8_t* q, float* qd) const {
        HcFuse a;
        a.h = h;
        a.fn = ffn ? l.hcf_fn : l.hca_fn;
        a.n_mix = (2 + g.hc) * g.hc;
        a.eps = g.eps;
        a.mixes = mixes;
        a.cnt = cnt;
        a.scale = ffn ? l.hcf_scale : l.hca_scale;
        a.base = ffn ? l.hcf_base : l.hca_base;
        a.hc = g.hc;
        a.iters = g.sinkhorn;
        a.hc_eps = g.hc_eps;
        a.pre = pre;
        a.post = post;
        a.comb = comb;
        a.pre_copy = pre_copy;
        a.mix = lag;
        a.w = w;
        a.dim = g.dim;
        a.x = x;
        a.q = q;
        a.qd = qd;
        return a;
    }
    // the fused HC launch before layer l's attention (ffn false: the split into a_*, the norm by d.pre) or its FFN (the
    // split into f_*, its pre slots copied into d.pre - the layer's end copy then skipped -, the norm by a_pre), x rounded
    // into d.xq8 / d.xd8; pq set for the GEMVs that read x
    bool hc_fused(Dev& d, const Layer& l, bool ffn, int T, gg::PreQ8& pq, std::string& err) {
        const HcFuse a = ffn ? hc_args(l, true, d.h, d.mix, d.hccnt, d.f_pre, d.f_post, d.f_comb, d.pre, d.a_pre, l.ffn_norm,
                                       d.x, d.xq8, d.xd8)
                             : hc_args(l, false, d.h, d.mix, d.hccnt, d.a_pre, d.a_post, d.a_comb, nullptr, d.pre, l.attn_norm,
                                       d.x, d.xq8, d.xd8);
        if (d.xq8 == nullptr || !hc_mix_split_norm(a, T, d.st)) {
            err = "DS4_HC_FUSE: the fused HC launch refused (layer " + std::to_string(l.il) + ", " + std::to_string(T) + " rows)";
            return false;
        }
        pq = gg::PreQ8{};
        pq.x = d.x;
        pq.q = d.xq8;
        pq.d = d.xd8;
        pq.k = g.dim;
        pq.rows = T;
        return true;
    }
    // ---- DS4_ROUTE_FUSE (see route_fuse): whether a window of T rows on layer l may take the fused router stage, and
    // whether this layer and its next fit every refusal of gemv_f32_pair / route_pair (checked before anything is
    // enqueued: an unfit pair takes the old launches)
    bool route_fuses(const Layer& l, int T) const { return route_fuse > 0 && !l.mtp && T >= 1 && (T == 1 || (route_fuse > 1 && T <= kWin)); }
    bool route_fusable(const Layer& l, const Layer& nx, int m) const {
        const int D = g.dim;
        return l.gate_w != nullptr && nx.gate_w != nullptr && l.gate_bias != nullptr && nx.gate_bias != nullptr &&
               l.vram_tab != nullptr && l.n_exp >= 1 && l.n_exp <= 1024 && nx.n_exp >= 1 && nx.n_exp <= 1024 &&
               l.k_exp >= 1 && l.k_exp <= kPicks && m >= 1 && m <= kAhead1 && D >= 4 && D % 4 == 0 && D <= kMaxDim;
    }
    // ---- DS4_DECODE_TRIM (see decode_trim)
    // the shared expert's swiglu on d.sg / d.su (T rows of FF) into d.sh: bit 1 rounds its output to int8 there (q8 true,
    // pq set for s2's GEMV); else the old launch
    bool shared_swiglu(Dev& d, const Layer& l, int T, int FF, gg::PreQ8& pq, bool& q8, std::string& err) {
        q8 = (decode_trim & 1) && !l.mtp && FF % 32 == 0 && T >= 1 && T <= kWin && d.shq8 != nullptr;
        if (!q8) {
            swiglu(d.sg, d.su, T * FF, g.lim, d.sh, d.st);
            return true;
        }
        if (!swiglu_q8(d.sg, d.su, T * FF, g.lim, d.sh, d.shq8, d.shd8, d.st)) {
            err = "DS4_DECODE_TRIM: swiglu_q8 refused";
            return false;
        }
        pq = gg::PreQ8{};
        pq.x = d.sh;
        pq.q = d.shq8;
        pq.d = d.shd8;
        pq.k = FF;
        pq.rows = T;
        return true;
    }
    // bit 2: q's low-rank norm (f, on d.qr's T rows) also rounds its output to int8 for wq_b - true, f and pq set
    bool trim_q(Dev& d, const Layer& l, int T, Finish& f, gg::PreQ8& pq) const {
        if (!(decode_trim & 2) || l.mtp || T < 1 || T > kWin || d.qrq8 == nullptr || g.q_lora % 32 != 0) return false;
        f.q8 = d.qrq8;
        f.q8d = d.qrd8;
        pq = gg::PreQ8{};
        pq.x = d.qr;
        pq.q = d.qrq8;
        pq.d = d.qrd8;
        pq.k = g.q_lora;
        pq.rows = T;
        return true;
    }
    // bit 4: the latent / snapshot copies of layer l as one kernel
    bool trims_copy(const Layer& l) const { return (decode_trim & 4) && !l.mtp; }
    // the end of what a load-time check enqueued on s (its event if recorded, else the stream), 10 s at most; no clean end
    // ends the process at once (what the run may still touch is the model's): exit 3, no teardown
    static void fuse_end(const char* what, int dev, int il, cudaStream_t s, cudaEvent_t ev, bool recorded) {
        const auto t0 = std::chrono::steady_clock::now();
        cudaError_t q;
        while ((q = recorded ? cudaEventQuery(ev) : cudaStreamQuery(s)) == cudaErrorNotReady &&
               std::chrono::steady_clock::now() - t0 < std::chrono::seconds(10))
            std::this_thread::sleep_for(std::chrono::microseconds(100));
        if (q == cudaSuccess) return;
        std::fprintf(stderr, "ds4: %s: CUDA%d (layer %d): %s - the device's state unknown; the process ends without teardown "
                             "(exit 3)\n",
                     what, dev, il, q == cudaErrorNotReady ? "no end in time" : "an error at its end");
        std::fflush(stderr);
        std::fflush(stdout);
        std::_Exit(3);
    }
    // DS4_HC_FUSE (at load, before any request; Project Maya #511's hc_fuse_check, ported): on every device with layers,
    // for the first layer of each kind of attention input it holds (2 GEMVs; 3 with the compressed KV; 4 with its gate:
    // a kind held and not checked fails) and the last, its attention and its FFN, on three inputs - random; edges (h's
    // 32-blocks of zeros, negative zeros, tiny and large magnitudes and a lone maximum, a zero and a negative lagged
    // weight); ties (h +-8 / 7, the lagged mix 1 0 0 0, a synthetic norm of 127 or 254 and k + 0.5 a block: int8 rounding
    // at its halves) - the old launches (hc_mix_split, hc_pre_norm, the end copy of the pre slots, gguf mv's own int8
    // rounding of x and the GEMVs that read it: the attention's input list; the FFN's shared expert w1 / w3) against
    // hc_mix_split_norm with the GEMVs on its int8 rows (PreQ8).  Every output region starts 0xA5 between 64-byte guards,
    // the pre buffers' 8 slots as sentinels (4 .. 7: a NaN payload, -0, a denormal, -123.5): every byte of both sets
    // equal (each output, slot and guard), the guards untouched, the written values finite, the int8 scales >= 0.  T rows
    // (=2: kWin) at the decode buffers' strides.  A mismatch or a CUDA error after a clean end fails the load (everything
    // freed); no clean end ends the process (fuse_end)
    bool hc_fuse_check(std::string& err, int T) {
        const int D = g.dim, HD = g.hd, QL = g.q_lora, FF = g.ff, H = g.hc, NM = (2 + g.hc) * g.hc;
        constexpr size_t kGuard = 64;
        static constexpr uint32_t kSent[8] = {0x3e800000u, 0x3f000000u, 0x3f400000u, 0x3f800000u,
                                              0x7fc0beefu, 0x80000000u, 0x00000001u, 0xc2f70000u};
        enum { kMix, kPre, kPost, kComb, kCopy, kX, kQ, kQd, kQr, kKvr, kCkr, kCgr, kS1, kS3, kRegions };
        const size_t rb1[kRegions] = {128, 32, 32, 256, 32, (size_t) D * 4, (size_t) D, (size_t) D / 32 * 4, (size_t) QL * 4,
                                      (size_t) HD * 4, (size_t) HD * 4, (size_t) HD * 4, (size_t) FF * 4, (size_t) FF * 4};
        const char* rname[kRegions] = {"mixes", "pre", "post", "comb", "the pre copy", "x", "int8", "scale", "q's GEMV",
                                       "the KV GEMV", "the compressed KV GEMV", "its gate GEMV", "the shared w1 GEMV",
                                       "the shared w3 GEMV"};
        size_t rb[kRegions], at[kRegions], set_bytes = 0;
        for (int r = 0; r < kRegions; ++r) {
            rb[r] = rb1[r] * (size_t) T;
            at[r] = set_bytes + kGuard;
            set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
        }
        set_bytes += kGuard;
        const size_t n_in = (size_t) T * ((size_t) H * D + 8) + (size_t) D;   // h | the lagged mix | a synthetic norm
        const std::string rows = " (" + std::to_string(T) + (T > 1 ? " rows)" : " row)");
        uint32_t st = 0x2545f491u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;   // -4 .. 4
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            std::vector<const Layer*> ls;   // (the first of each kind, then the last)
            const Layer* last = nullptr;
            bool kind_held[5] = {}, kind_run[5] = {};
            for (const Layer& l0 : L)
                if (!l0.mtp)
                    for (int m = 0; m < l0.nm; ++m)
                        if (member(l0, m).dev == (int) di) {
                            const Layer& x = member(l0, m);
                            const int nk = 2 + (x.kv_src ? 1 : 0) + (x.kv_src && x.ratio > 1 ? 1 : 0);
                            if (!kind_held[nk]) ls.push_back(&x);
                            kind_held[nk] = true;
                            last = &x;
                        }
            if (ls.empty()) continue;
            if (std::find(ls.begin(), ls.end(), last) == ls.end()) ls.push_back(last);
            auto fail_at = [&](const std::string& why) {
                err = "HC fuse check" + rows + " on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d HC fuse check%s FAILED: %s\n", d.id, rows.c_str(), why.c_str());
                return false;
            };
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                return fail_at("cudaSetDevice failed");
            }
            const cudaStream_t s = d.st;
            float* in = nullptr;
            unsigned* cnt = nullptr;
            uint8_t *out = nullptr, *back = nullptr;
            cudaEvent_t ev = nullptr;
            if (cudaMalloc((void**) &in, n_in * 4) != cudaSuccess || cudaMalloc((void**) &cnt, 2 * kWin * 4) != cudaSuccess ||
                cudaMalloc((void**) &out, 2 * set_bytes) != cudaSuccess ||
                cudaMallocHost((void**) &back, 2 * set_bytes) != cudaSuccess ||
                cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) {
                (void) cudaGetLastError();
                if (in != nullptr) cudaFree(in);
                if (cnt != nullptr) cudaFree(cnt);
                if (out != nullptr) cudaFree(out);
                if (back != nullptr) cudaFreeHost(back);
                if (ev != nullptr) cudaEventDestroy(ev);
                return fail_at("its buffers");
            }
            float *h = in, *lag = in + (size_t) T * H * D, *wsyn = lag + 8 * T;
            std::vector<float> hin(n_in);   // (written again only after the run before has ended)
            int runs = 0;
            std::string bad;
            for (const Layer* lp : ls)
                for (int kind = 0; kind < 3 && bad.empty(); ++kind)
                    for (int ffn = 0; ffn < 2 && bad.empty(); ++ffn) {
                        const Layer& l = *lp;
                        float *hh = hin.data(), *hl = hh + (size_t) T * H * D, *hw = hl + 8 * T;
                        for (int t = 0; t < T; ++t)
                            for (int e = 0; e < D; ++e) {
                                const int blk = e / 32, lane = e % 32;
                                for (int k = 0; k < H; ++k) {
                                    float v = rnd() * (float) (1 + k);
                                    if (kind == 1)
                                        switch (blk % 8) {
                                            case 0: v = 0.0f; break;
                                            case 1: v = -0.0f; break;
                                            case 2: v = rnd() * 1e-20f; break;
                                            case 3: v = rnd() * 1e15f; break;
                                            case 4: v = lane == 5 ? 1000.0f : rnd(); break;
                                            default: break;
                                        }
                                    if (kind == 2) v = k == 0 ? (blk % 2 ? -8.0f : 8.0f) : 7.0f;
                                    hh[((size_t) t * H + k) * D + e] = v;
                                }
                                hw[e] = (lane == 0 ? 127.0f : (float) (lane - 16) + 0.5f) * (blk % 2 ? 2.0f : 1.0f);
                            }
                        const float lag_k[3][4] = {{0.4f, 0.9f, 0.6f, 1.2f}, {1.5f, 0.0f, -0.75f, 0.25f}, {1, 0, 0, 0}};
                        for (int t = 0; t < T; ++t)
                            for (int i = 0; i < 8; ++i) {
                                if (i < 4) hl[8 * t + i] = lag_k[kind][i];
                                else std::memcpy(&hl[8 * t + i], &kSent[i], 4);
                            }
                        const float* w = kind == 2 ? wsyn : ffn ? l.ffn_norm : l.attn_norm;
                        uint8_t* set[2] = {out, out + set_bytes};   // the old path's, the fused one's
                        auto F = [&](int b, int r) { return (float*) (set[b] + at[r]); };
                        auto Q = [&](int b) { return (int8_t*) (set[b] + at[kQ]); };
                        bool ok = cudaMemcpyAsync(in, hin.data(), n_in * 4, cudaMemcpyHostToDevice, s) == cudaSuccess &&
                                  cudaMemsetAsync(out, 0xA5, 2 * set_bytes, s) == cudaSuccess &&
                                  cudaMemsetAsync(cnt, 0, 2 * kWin * 4, s) == cudaSuccess;
                        for (int b = 0; b < 2; ++b)
                            for (int t = 0; ok && t < T; ++t)
                                ok = cudaMemcpyAsync(set[b] + at[kPre] + 32 * t, kSent, 32, cudaMemcpyHostToDevice, s) ==
                                     cudaSuccess;
                        x3::MvJob j[4];
                        int nj = 0;
                        auto jobs = [&](int b) {   // (the GEMVs that read x: the attention's input list, or w1 / w3)
                            if (!ffn) return attn_in_jobs(l, F(b, kX), F(b, kQr), F(b, kKvr), F(b, kCkr), F(b, kCgr), T, j);
                            j[0] = job(l.s1, F(b, kX), F(b, kS1), T, D, FF);
                            j[1] = job(l.s3, F(b, kX), F(b, kS3), T, D, FF);
                            return 2;
                        };
                        if (ok) {   // the old launches
                            hc_mix_split(h, ffn ? l.hcf_fn : l.hca_fn, H * D, NM, T, g.eps, F(0, kMix), cnt,
                                         ffn ? l.hcf_scale : l.hca_scale, ffn ? l.hcf_base : l.hca_base, H, g.sinkhorn,
                                         g.hc_eps, F(0, kPre), F(0, kPost), F(0, kComb), s);
                            hc_pre_norm(h, lag, w, D, H, T, g.eps, F(0, kX), s);
                            if (ffn)
                                ok = cudaMemcpyAsync(F(0, kCopy), F(0, kPre), (size_t) 32 * T, cudaMemcpyDeviceToDevice, s) ==
                                     cudaSuccess;
                            if (ok) {
                                gg::q8_round(F(0, kX), T, D, Q(0), F(0, kQd), s);   // (the rounding mv gives the old path)
                                nj = jobs(0);
                                ok = mv_any(j, nj, s);
                            }
                        }
                        if (ok) {   // the fused one
                            const HcFuse a = hc_args(l, ffn != 0, h, F(1, kMix), cnt + kWin, F(1, kPre), F(1, kPost),
                                                     F(1, kComb), ffn ? F(1, kCopy) : nullptr, lag, w, F(1, kX), Q(1),
                                                     F(1, kQd));
                            ok = hc_mix_split_norm(a, T, s);
                            if (ok) {
                                gg::PreQ8 pq;
                                pq.x = F(1, kX);
                                pq.q = Q(1);
                                pq.d = F(1, kQd);
                                pq.k = D;
                                pq.rows = T;
                                nj = jobs(1);
                                ok = mv_any(j, nj, s, &pq);
                                if (!ffn) kind_run[nj] = true;
                            }
                        }
                        ok = ok && cudaGetLastError() == cudaSuccess &&
                             cudaMemcpyAsync(back, out, 2 * set_bytes, cudaMemcpyDeviceToHost, s) == cudaSuccess;
                        const bool recorded = ok && cudaEventRecord(ev, s) == cudaSuccess;
                        fuse_end("HC fuse check", d.id, l.il, s, ev, recorded);
                        if (!recorded) {   // (a CUDA error or a refused launch before the end, which was clean)
                            (void) cudaGetLastError();
                            bad = "layer " + std::to_string(l.il) + ": a launch refused or a CUDA error";
                            break;
                        }
                        ++runs;
                        const char* what[3] = {"random", "edges", "ties"};
                        auto where = [&](const std::string& r, size_t o) {
                            return "layer " + std::to_string(l.il) + (ffn ? " FFN, " : " attention, ") + what[kind] + ": " +
                                   r + " byte " + std::to_string(o);
                        };
                        const uint8_t *A = back, *B = back + set_bytes;
                        for (size_t o = 0; o < set_bytes && bad.empty(); ++o)
                            if (A[o] != B[o]) bad = where("an output", o);
                        for (int r = 0; r < kRegions && bad.empty(); ++r) {   // (A == B now: A's guards and values)
                            const size_t lo = r == 0 ? 0 : at[r - 1] + rb[r - 1];
                            for (size_t o = lo; o < at[r] && bad.empty(); ++o)
                                if (A[o] != 0xA5) bad = where(std::string("a guard before ") + rname[r], o);
                            // (the floats written in a row: their count; 0 - not written, or not floats)
                            size_t n = 0;
                            if (r == kMix) n = (size_t) NM;
                            else if (r == kPre || r == kPost || (r == kCopy && ffn)) n = (size_t) H;
                            else if (r == kComb) n = (size_t) H * H;
                            else if (r == kX) n = (size_t) D;
                            else if (r == kQd) n = (size_t) D / 32;
                            else if (r >= kQr && r <= kCgr && !ffn && r - kQr < nj) n = (size_t) j[r - kQr].m->n;
                            else if (r >= kS1 && ffn) n = (size_t) j[r - kS1].m->n;
                            for (int t = 0; t < T; ++t)
                                for (size_t i = 0; i < n && bad.empty(); ++i) {
                                    const size_t o = rb1[r] * (size_t) t + 4 * i;
                                    float v;
                                    std::memcpy(&v, A + at[r] + o, 4);
                                    if (!std::isfinite(v) || (r == kQd && !(v >= 0.0f))) bad = where(rname[r], o);
                                }
                        }
                        for (size_t o = at[kRegions - 1] + rb[kRegions - 1]; o < set_bytes && bad.empty(); ++o)
                            if (A[o] != 0xA5) bad = where("the last guard", o);
                    }
            cudaFree(in);   // (every run ended cleanly)
            cudaFree(cnt);
            cudaFree(out);
            cudaFreeHost(back);
            cudaEventDestroy(ev);
            if (!bad.empty()) return fail_at(bad);
            std::string kinds;
            for (int k = 2; k <= 4; ++k) {
                if (kind_held[k] && !kind_run[k]) return fail_at("the attention's " + std::to_string(k) + "-GEMV input not checked");
                if (kind_run[k]) kinds += (kinds.empty() ? "" : ", ") + std::to_string(k);
            }
            std::string ids;
            for (const Layer* lp : ls) ids += (ids.empty() ? "" : " ") + std::to_string(lp->il);
            std::fprintf(stderr,
                         "ds4: CUDA%d HC fuse check%s: %d runs (layers %s; attention inputs of %s GEMVs; attention and FFN; "
                         "random / edges / ties): mixes, pre, post, comb, the pre copy, x, its int8 rounding, the attention's "
                         "input GEMVs and the shared expert's w1 / w3 the old launches' bit for bit, all finite, every guard "
                         "intact (DS4_HC_FUSE)\n",
                         d.id, rows.c_str(), runs, ids.c_str(), kinds.c_str());
        }
        return true;
    }
    // DS4_ROUTE_FUSE (at load, before any request; Project Maya #511's route_fuse_check, ported): on every device with
    // layers, gemv_f32_pair and route_pair (with its publish) against what they replace - two gemv_f32 launches; then
    // route_ahead, route_publish and its publish.  The GEMVs: the device's first and last pair of a layer and its next (and
    // the first with an image-token bias), their real gates on a random and an edge x (zeros, negative zeros, tiny and
    // large magnitudes), plus rows not a whole block (300 and 13 of the first gate's).  The routing: the real logits, the
    // real gates' biases and VRAM table; tied logits, logits past the softplus's 20 and negative, the request's x copied
    // (a pick on the CPU lane) and not (every pick in VRAM), no image bias / its bit on / its pointer given and its bit
    // off, n 257 (not a whole block), m 1, k and 16.  Every output (both logits, idx / w / plan_ptr, the whole request
    // record) starts 0xA5 between 64-byte guards; both paths' bytes must be equal - every value, untouched byte and guard
    // - and the values finite.  T rows (=2: 3 and kWin) at the decode buffers' strides, the image bit on row 0 or 1.  A
    // mismatch or an error after a clean end fails the load; no clean end ends the process (fuse_end)
    // leadpath (DS4_LP_ROUTE / DS4_LP_PUBFUSE, at load, before any request): route_publish_lp as the flags set it against
    // route_publish (its routing launch and publish_kernel) on every layer device, T rows: real logits (the first trunk
    // layer's gate on a random x), ties, past 20 and negative, all equal, a few NaN, fewer than k scores above -FLT_MAX (the
    // old rounds' path), scores at -FLT_MAX; the VRAM table the layer's / all / none / mixed; n the layer's, 257 and k; k the
    // layer's, 1 and 8; the image bias on and off.  The picks, weights, plan and the whole request record compared byte for
    // byte (both sets 0xA5 first); any difference fails the load.
    bool lp_route_check(std::string& err, int T) {
        const int D = g.dim;
        enum { kIdx, kW, kPlan, kReq, kRegions };
        const size_t rb[kRegions] = {(size_t) T * kPicks * 4, (size_t) T * kPicks * 4, (size_t) T * kPicks * 8, sizeof(Req)};
        size_t at[kRegions], set_bytes = 0;
        for (int r = 0; r < kRegions; ++r) {
            at[r] = set_bytes + 64;
            set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
        }
        set_bytes += 64;
        const size_t n_in = (size_t) T * ((size_t) D + 1024) + 1024 * 2 + 1024;   // x | logits | bias, bias_vl | vram (512 u64)
        const std::string rows = " (" + std::to_string(T) + (T > 1 ? " rows)" : " row)");
        uint32_t st = 0x2545f491u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            const Layer* lp = nullptr;
            for (const Layer& a0 : L) {
                if (a0.mtp || lp != nullptr) continue;
                for (int m = 0; m < a0.nm; ++m)
                    if (member(a0, m).dev == (int) di && member(a0, m).gate_w != nullptr && member(a0, m).n_exp <= 1024) {
                        lp = &member(a0, m);
                        break;
                    }
            }
            if (lp == nullptr) continue;
            const Layer& l = *lp;
            auto fail_at = [&](const std::string& why) {
                err = "leadpath route check" + rows + " on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d leadpath route check%s FAILED: %s\n", d.id, rows.c_str(), why.c_str());
                return false;
            };
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                return fail_at("cudaSetDevice failed");
            }
            const cudaStream_t s = d.st;
            float* in = nullptr;
            uint8_t *out = nullptr, *back = nullptr;
            if (cudaMalloc((void**) &in, n_in * 4) != cudaSuccess || cudaMalloc((void**) &out, 2 * set_bytes) != cudaSuccess ||
                cudaMallocHost((void**) &back, 2 * set_bytes) != cudaSuccess) {
                (void) cudaGetLastError();
                if (in != nullptr) cudaFree(in);
                if (out != nullptr) cudaFree(out);
                if (back != nullptr) cudaFreeHost(back);
                return fail_at("its buffers");
            }
            float *x = in, *lg = in + (size_t) D * T, *bias = lg + (size_t) 1024 * T, *bias_vl = bias + 1024;
            unsigned long long* vram = (unsigned long long*) (bias_vl + 1024);
            std::vector<float> hin(n_in);
            uint8_t* set[2] = {out, out + set_bytes};
            auto F = [&](int b, int r) { return (void*) (set[b] + at[r]); };
            int runs = 0;
            std::string bad;
            struct Case {
                int logits, vram, vl, n, k;
            };
            const int K = l.k_exp, N = l.n_exp;
            const Case cases[] = {{0, 0, 0, N, K}, {1, 1, 0, N, K}, {1, 2, 1, N, K}, {2, 3, 2, N, K}, {3, 3, 0, 257, K},
                                  {4, 3, 0, N, K}, {5, 3, 0, N, K}, {6, 3, 0, N, K}, {7, 3, 0, N, K}, {3, 1, 0, K, K},
                                  {3, 3, 0, N, 1}, {1, 3, 0, N, 8}, {0, 2, l.gate_bias_vl != nullptr ? 1 : 0, N, K}};
            for (const Case& c : cases) {
                if (!bad.empty()) break;
                const int n = std::min(c.n, N), k = std::min(c.k, kPicks);
                if (c.vram == 0 && l.vram_tab == nullptr) continue;
                if (c.vram != 0 && n > 512) continue;
                for (size_t e = 0; e < (size_t) D * T; ++e) hin[e] = rnd();
                float *hl = hin.data() + (size_t) D * T, *hb = hl + (size_t) 1024 * T, *hbv = hb + 1024;
                for (int t = 0; t < T; ++t)
                    for (int i = 0; i < 1024; ++i) {
                        float v = rnd();
                        if (c.logits == 1) v = (float) (i % 5) * 0.5f;                       // ties
                        if (c.logits == 2) v = i % 2 ? 20.0f + (float) (i % 7) : -v * 10.0f;  // past 20, negative
                        if (c.logits == 4) v = 1.0f;                                          // all equal
                        if (c.logits == 5 && i % 37 == 3) v = std::nanf("");                  // a few NaN
                        hl[1024 * t + i] = v;
                        if (t > 0) continue;
                        hb[i] = c.logits == 1 || c.logits == 4 ? 0.0f : 0.05f * rnd();
                        if (c.logits == 6) hb[i] = i % 97 == 5 ? 0.0f : -INFINITY;            // < k scores above -FLT_MAX
                        if (c.logits == 7) hb[i] = i % 3 ? -FLT_MAX : 0.0f;                   // scores at -FLT_MAX
                        hbv[i] = 0.05f * rnd();
                    }
                unsigned long long* hv = (unsigned long long*) (hbv + 1024);
                for (int i = 0; i < 512; ++i)
                    hv[i] = c.vram == 1   ? 0x1000ull + (unsigned long long) i * 64
                            : c.vram == 2 ? 0ull
                                          : (i % 3 ? 0x2000ull + (unsigned long long) i : 0ull);
                const unsigned vl = c.vl == 1 ? 1u : c.vl == 2 ? 2u : 0u;
                const float* bv = c.vl == 0 ? nullptr : c.logits == 0 && l.gate_bias_vl != nullptr ? l.gate_bias_vl : bias_vl;
                const float* rb0 = c.logits == 0 ? l.gate_bias : bias;
                const unsigned long long* vt = c.vram == 0 ? l.vram_tab : vram;
                const unsigned seq = 0x61u + (unsigned) runs;
                bool ok = cudaMemcpyAsync(in, hin.data(), n_in * 4, cudaMemcpyHostToDevice, s) == cudaSuccess &&
                          cudaMemsetAsync(out, 0xA5, 2 * set_bytes, s) == cudaSuccess;
                if (ok && c.logits == 0) gemv_f32(l.gate_w, x, n, D, T, lg, 1024, s);   // (the real gate's logits, both sets')
                for (int b = 0; b < 2 && ok; ++b) {
                    Req* rq = (Req*) F(b, kReq);
                    if (b == 0)
                        route_publish(lg, rb0, n, k, T, g.route_scale, vt, x, D, (int*) F(b, kIdx), (float*) F(b, kW),
                                      (unsigned long long*) F(b, kPlan), rq, seq, s, bv, vl, 3, 0);
                    else
                        route_publish_lp(lp_route, lp_pubfuse, lg, rb0, n, k, T, g.route_scale, vt, x, D, (int*) F(b, kIdx),
                                         (float*) F(b, kW), (unsigned long long*) F(b, kPlan), rq, seq, s, bv, vl, 3, 0,
                                         pub_cnt_of((int) di));   // (DS4_HW_PUBT: T > 1 published here too)
                }
                ok = ok && cudaGetLastError() == cudaSuccess &&
                     cudaMemcpyAsync(back, out, 2 * set_bytes, cudaMemcpyDeviceToHost, s) == cudaSuccess &&
                     cudaStreamSynchronize(s) == cudaSuccess;
                if (!ok) {
                    (void) cudaGetLastError();
                    bad = "case " + std::to_string(runs) + ": a launch refused or a CUDA error";
                    break;
                }
                for (size_t o = 0; o < set_bytes && bad.empty(); ++o)
                    if (back[o] != back[set_bytes + o])
                        bad = "case " + std::to_string(runs) + " (logits kind " + std::to_string(c.logits) + ", n " +
                              std::to_string(n) + ", k " + std::to_string(k) + "): an output byte " + std::to_string(o);
                ++runs;
            }
            cudaFree(in);
            cudaFree(out);
            cudaFreeHost(back);
            if (!bad.empty()) return fail_at(bad);
            std::fprintf(stderr, "ds4: CUDA%d leadpath route check%s: %d runs (real / tied / past 20 / equal / NaN / -inf / "
                                 "-FLT_MAX scores; n %d, 257, %d; k %d, 1, 8; VRAM table, all, none, mixed): picks, weights, "
                                 "plan and the request record route_publish's bit for bit (%s%s%s)\n",
                         d.id, rows.c_str(), runs, N, K, K, lp_route ? "DS4_LP_ROUTE" : "",
                         lp_pubfuse ? (lp_route ? " + DS4_LP_PUBFUSE" : "DS4_LP_PUBFUSE") : "",
                         T > 1 && pub_cnt_of((int) di) != nullptr ? " + DS4_HW_PUBT" : "");
        }
        return true;
    }
    bool route_fuse_check(std::string& err, int T) {
        const int D = g.dim;
        constexpr size_t kGuard = 64;
        enum { kLog, kLogA, kIdx, kW, kPlan, kReq, kRegions };
        const size_t rb[kRegions] = {(size_t) T * 1024 * 4,   (size_t) T * 1024 * 4,   (size_t) T * kPicks * 4,
                                     (size_t) T * kPicks * 4, (size_t) T * kPicks * 8, sizeof(Req)};
        size_t at[kRegions], set_bytes = 0;
        for (int r = 0; r < kRegions; ++r) {
            at[r] = set_bytes + kGuard;
            set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
        }
        set_bytes += kGuard;
        // inputs: x | synthetic logits, the guesses' logits (T rows each) | biases (routing, image) | a VRAM table (512)
        const size_t n_in = (size_t) T * ((size_t) D + 2 * 1024) + 1024 * 3;
        const std::string rows = " (" + std::to_string(T) + (T > 1 ? " rows)" : " row)");
        uint32_t st = 0x7f4a7c15u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;   // -4 .. 4
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            // (a layer, its next layer: both this device's member of the trunk's consecutive layers)
            std::vector<std::pair<const Layer*, const Layer*>> pairs, all;
            for (size_t j = 0; j + 1 < L.size(); ++j) {
                const Layer &a0 = L[j], &b0 = L[j + 1];
                if (a0.mtp || b0.mtp) continue;
                for (int m = 0; m < a0.nm && m < b0.nm; ++m)
                    if (member(a0, m).dev == (int) di && member(b0, m).dev == (int) di && member(a0, m).gate_w != nullptr &&
                        member(b0, m).gate_w != nullptr && member(a0, m).n_exp <= 1024 && member(b0, m).n_exp <= 1024)
                        all.push_back({&member(a0, m), &member(b0, m)});
            }
            if (all.empty()) continue;
            pairs.push_back(all.front());
            if (all.size() > 1) pairs.push_back(all.back());
            for (const auto& p : all)
                if (p.first->gate_bias_vl != nullptr) {
                    if (std::find(pairs.begin(), pairs.end(), p) == pairs.end()) pairs.push_back(p);
                    break;
                }
            auto fail_at = [&](const std::string& why) {
                err = "route fuse check" + rows + " on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d route fuse check%s FAILED: %s\n", d.id, rows.c_str(), why.c_str());
                return false;
            };
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                return fail_at("cudaSetDevice failed");
            }
            const cudaStream_t s = d.st;
            float* in = nullptr;
            uint8_t *out = nullptr, *back = nullptr;
            cudaEvent_t ev = nullptr;
            if (cudaMalloc((void**) &in, n_in * 4) != cudaSuccess || cudaMalloc((void**) &out, 2 * set_bytes) != cudaSuccess ||
                cudaMallocHost((void**) &back, 2 * set_bytes) != cudaSuccess ||
                cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) {
                (void) cudaGetLastError();
                if (in != nullptr) cudaFree(in);
                if (out != nullptr) cudaFree(out);
                if (back != nullptr) cudaFreeHost(back);
                if (ev != nullptr) cudaEventDestroy(ev);
                return fail_at("its buffers");
            }
            float *x = in, *lg = in + (size_t) D * T, *lga = lg + 1024 * T, *bias = lga + 1024 * T, *bias_vl = bias + 1024;
            unsigned long long* vram = (unsigned long long*) (bias_vl + 1024);   // (1024 floats: 512 entries)
            std::vector<float> hin(n_in);   // (written again only after the run before has ended)
            uint8_t* set[2] = {out, out + set_bytes};   // the old path's, the fused one's
            auto F = [&](int b, int r) { return (float*) (set[b] + at[r]); };
            int runs = 0;
            std::string bad;
            // one run: the inputs up, both sets 0xA5, the old path (set 0) then the fused one (set 1), the readback, its
            // end; then every byte compared
            auto run = [&](const char* what, int il, auto&& old_path, auto&& new_path, size_t n_log, size_t n_loga, int k) {
                bool ok = cudaMemcpyAsync(in, hin.data(), n_in * 4, cudaMemcpyHostToDevice, s) == cudaSuccess &&
                          cudaMemsetAsync(out, 0xA5, 2 * set_bytes, s) == cudaSuccess;
                ok = ok && old_path() && new_path();
                ok = ok && cudaGetLastError() == cudaSuccess &&
                     cudaMemcpyAsync(back, out, 2 * set_bytes, cudaMemcpyDeviceToHost, s) == cudaSuccess;
                const bool recorded = ok && cudaEventRecord(ev, s) == cudaSuccess;
                fuse_end("route fuse check", d.id, il, s, ev, recorded);
                if (!recorded) {   // (a CUDA error or a refused launch before the end, which was clean)
                    (void) cudaGetLastError();
                    bad = std::string(what) + ", layer " + std::to_string(il) + ": a launch refused or a CUDA error";
                    return;
                }
                ++runs;
                const uint8_t *A = back, *B = back + set_bytes;
                for (size_t o = 0; o < set_bytes && bad.empty(); ++o)
                    if (A[o] != B[o])
                        bad = std::string(what) + ", layer " + std::to_string(il) + ": an output byte " + std::to_string(o);
                size_t prev = 0;   // (A == B now: A's guards and values)
                for (int r = 0; r < kRegions && bad.empty(); ++r) {
                    for (size_t o = prev; o < at[r] && bad.empty(); ++o)
                        if (A[o] != 0xA5) bad = std::string(what) + ": a guard byte " + std::to_string(o);
                    prev = at[r] + rb[r];
                }
                for (size_t o = prev; o < set_bytes && bad.empty(); ++o)
                    if (A[o] != 0xA5) bad = std::string(what) + ": the last guard byte " + std::to_string(o);
                const size_t nf[3] = {n_log, n_loga, (size_t) k};   // (the logits written, then the weights: a row's)
                const int rf[3] = {kLog, kLogA, kW};
                const size_t rs[3] = {1024, 1024, kPicks};   // (rows apart)
                for (int q2 = 0; q2 < 3 && bad.empty(); ++q2)
                    for (int t = 0; t < T; ++t)
                        for (size_t i = 0; i < nf[q2] && bad.empty(); ++i) {
                            float v;
                            std::memcpy(&v, A + at[rf[q2]] + 4 * (rs[q2] * (size_t) t + i), 4);
                            if (!std::isfinite(v)) bad = std::string(what) + ": a value not finite";
                        }
            };
            for (const auto& pr : pairs) {
                const Layer &l = *pr.first, &nx = *pr.second;
                for (int kind = 0; kind < 2 && bad.empty(); ++kind) {   // the GEMVs: random, edges
                    for (size_t e = 0; e < (size_t) D * T; ++e) {
                        float v = rnd();
                        if (kind == 1)
                            switch ((e % (size_t) D / 32) % 6) {
                                case 0: v = 0.0f; break;
                                case 1: v = -0.0f; break;
                                case 2: v *= 1e-20f; break;
                                case 3: v *= 1e15f; break;
                                default: break;
                            }
                        hin[e] = v;
                    }
                    run(kind ? "the gates, edges" : "the gates, random", l.il,
                        [&] {
                            gemv_f32(l.gate_w, x, l.n_exp, D, T, F(0, kLog), 1024, s);
                            gemv_f32(nx.gate_w, x, nx.n_exp, D, T, F(0, kLogA), 1024, s);
                            return true;
                        },
                        [&] {
                            return gemv_f32_pair(l.gate_w, l.n_exp, F(1, kLog), nx.gate_w, nx.n_exp, F(1, kLogA), x, D, T,
                                                 1024, s);
                        },
                        (size_t) l.n_exp, (size_t) nx.n_exp, 0);
                }
            }
            const Layer &l = *pairs.front().first, &nx = *pairs.front().second;
            if (bad.empty())   // (rows not a whole block: 300 and 13 of the first gate's)
                run("the gates, 300 and 13 rows", l.il,
                    [&] {
                        gemv_f32(l.gate_w, x, std::min(300, l.n_exp), D, T, F(0, kLog), 1024, s);
                        gemv_f32(nx.gate_w, x, std::min(13, nx.n_exp), D, T, F(0, kLogA), 1024, s);
                        return true;
                    },
                    [&] {
                        return gemv_f32_pair(l.gate_w, std::min(300, l.n_exp), F(1, kLog), nx.gate_w, std::min(13, nx.n_exp),
                                             F(1, kLogA), x, D, T, 1024, s);
                    },
                    (size_t) std::min(300, l.n_exp), (size_t) std::min(13, nx.n_exp), 0);
            // the routing: logits (0 real - the first gates' on a random x, 1 ties, 2 past 20 and negative, 3 random), VRAM
            // (0 the layer's, 1 every pick in VRAM, 2 none, 3 mixed), image bias (0 none, 1 its bit on, 2 its pointer and
            // its bit off), n (0 the layer's, 1 257), m
            struct Case {
                int logits, vram, vl, n257, m;
            };
            const Case cases[] = {{0, 0, 0, 0, l.k_exp}, {1, 1, 0, 0, kAhead1}, {1, 2, 1, 0, 1}, {2, 3, 2, 0, l.k_exp},
                                  {3, 3, 0, 1, kAhead1}, {0, 2, l.gate_bias_vl != nullptr ? 1 : 0, 0, l.k_exp}};
            for (const Case& c : cases) {
                if (!bad.empty()) break;
                const int n = c.n257 ? std::min(257, l.n_exp) : l.n_exp;
                const int an = c.n257 ? std::min(257, nx.n_exp) : nx.n_exp;
                for (size_t e = 0; e < (size_t) D * T; ++e) hin[e] = rnd();
                float *hl = hin.data() + (size_t) D * T, *hla = hl + 1024 * T, *hb = hla + 1024 * T, *hbv = hb + 1024;
                for (int t = 0; t < T; ++t)
                    for (int i = 0; i < 1024; ++i) {
                        float v = rnd(), va = rnd();
                        if (c.logits == 1) v = (float) (i % 5) * 0.5f, va = (float) (i % 3);   // ties
                        if (c.logits == 2) v = i % 2 ? 20.0f + (float) (i % 7) : -v * 10.0f, va = -va * 5.0f;
                        hl[1024 * t + i] = v;
                        hla[1024 * t + i] = va;
                        if (t > 0) continue;   // (the biases: one set)
                        hb[i] = c.logits == 1 ? 0.0f : 0.05f * rnd();
                        hbv[i] = 0.05f * rnd();
                    }
                unsigned long long* hv = (unsigned long long*) (hbv + 1024);
                for (int i = 0; i < 512; ++i)   // (every pick in VRAM, none, or two in three)
                    hv[i] = c.vram == 1   ? 0x1000ull + (unsigned long long) i * 64
                            : c.vram == 2 ? 0ull
                                          : (i % 3 ? 0x2000ull + (unsigned long long) i : 0ull);
                const unsigned vl = c.vl == 1 ? 1u : c.vl == 2 ? 2u : 0u;
                const float* bv = c.vl == 0                                    ? nullptr
                                  : c.logits == 0 && l.gate_bias_vl != nullptr ? l.gate_bias_vl
                                                                               : bias_vl;
                const float* rb0 = c.logits == 0 ? l.gate_bias : bias;
                const float* rba = c.logits == 0 ? nx.gate_bias : bias;
                const unsigned long long* vt = c.vram == 0 ? l.vram_tab : vram;
                if (c.vram == 0 && vt == nullptr) continue;   // (no VRAM table on this member: nothing to compare)
                if (c.vram != 0 && n > 512) continue;
                const unsigned seq = 0x51u + (unsigned) runs;
                run("the routing", l.il,
                    [&] {
                        if (c.logits == 0) {   // (the logits: the first gates' on this x, the same in both sets)
                            gemv_f32(l.gate_w, x, n, D, T, F(0, kLog), 1024, s);
                            gemv_f32(nx.gate_w, x, an, D, T, F(0, kLogA), 1024, s);
                            gemv_f32(l.gate_w, x, n, D, T, F(1, kLog), 1024, s);
                            gemv_f32(nx.gate_w, x, an, D, T, F(1, kLogA), 1024, s);
                        } else {
                            for (int b = 0; b < 2; ++b)
                                if (cudaMemcpyAsync(F(b, kLog), lg, (size_t) T * 1024 * 4, cudaMemcpyDeviceToDevice, s) !=
                                        cudaSuccess ||
                                    cudaMemcpyAsync(F(b, kLogA), lga, (size_t) T * 1024 * 4, cudaMemcpyDeviceToDevice, s) !=
                                        cudaSuccess)
                                    return false;
                        }
                        Req* rq = (Req*) (set[0] + at[kReq]);
                        route_ahead(F(0, kLogA), rba, an, c.m, T, rq, 0, s);
                        route_publish(F(0, kLog), rb0, n, l.k_exp, T, g.route_scale, vt, x, D, (int*) F(0, kIdx), F(0, kW),
                                      (unsigned long long*) F(0, kPlan), rq, seq, s, bv, vl, c.m, 0);
                        return true;
                    },
                    [&] {
                        RoutePair a;
                        a.logits = F(1, kLog);
                        a.bias = rb0;
                        a.n = n;
                        a.k = l.k_exp;
                        a.route_scale = g.route_scale;
                        a.vram = vt;
                        a.x = x;
                        a.dim = D;
                        a.idx = (int*) F(1, kIdx);
                        a.w = F(1, kW);
                        a.plan_ptr = (unsigned long long*) F(1, kPlan);
                        a.req = (Req*) (set[1] + at[kReq]);
                        a.vl = vl;
                        a.bias_vl = vl != 0 ? bv : nullptr;
                        a.seq = seq;
                        a.na0 = c.m;
                        a.na1 = 0;
                        a.a_logits = F(1, kLogA);
                        a.a_bias = rba;
                        a.a_n = an;
                        a.m = c.m;
                        a.off = 0;
                        a.T = T;
                        return route_pair(a, s);
                    },
                    c.logits == 0 ? (size_t) n : 1024, c.logits == 0 ? (size_t) an : 1024, l.k_exp);
            }
            cudaFree(in);   // (every run ended cleanly)
            cudaFree(out);
            cudaFreeHost(back);
            cudaEventDestroy(ev);
            if (!bad.empty()) return fail_at(bad);
            std::string ids;
            for (const auto& p : pairs) ids += (ids.empty() ? "" : " ") + std::to_string(p.first->il);
            std::fprintf(stderr,
                         "ds4: CUDA%d route fuse check%s: %d runs (gates of layers %s and their next; the routing: real, "
                         "tied, past 20 and negative logits, the request's x copied and not, the image bias off / on / given "
                         "and off, n 257, m 1 .. 16): both logits, the picks, weights, plan and the whole request record the "
                         "old launches' bit for bit, all finite, every guard intact (DS4_ROUTE_FUSE)\n",
                         d.id, rows.c_str(), runs, ids.c_str());
        }
        return true;
    }
    // DS4_ROUTER_BF16 (at load, before any request; Project Maya #745's router_check, ported; on unless DS4_ROUTER_CHECK=0):
    // each BF16 router (gate()) through the kernel the decode, windows and chunks run it with, against the F32 copy it
    // replaces (its values widened on the host) through gemv_f32's old kernel, and against the host's replay of that
    // kernel's sums (a lane's fmaf chain over float4s c = lane + 32 j, then the warp's xor 16 .. 1 adds) - on 1, 3 and 40
    // rows of x (a token, a window, a chunk's rows), and DS4_ROUTE_FUSE's pair kernel on it and the router before it on the
    // device against the single launches; any bit off fails the load.  Identical logits are identical routing picks
    bool router_check(std::string& err) {
        constexpr int kRows = 40;
        const int D = g.dim;
        uint32_t st = 0x2545f491u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;   // -4 .. 4
        };
        int layers = 0;
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            const Layer* prev = nullptr;
            for (const Layer& l0 : L)
                for (int mi = 0; mi < std::max(1, l0.nm); ++mi) {
                    const Layer& l = member(l0, mi);
                    if (l.dev != (int) di || l.gate_w.h == nullptr) continue;
                    auto fail_at = [&](const std::string& why) {
                        err = "router check on CUDA" + std::to_string(d.id) + ", layer " + std::to_string(l.il) + ": " + why;
                        std::fprintf(stderr, "ds4: router check FAILED: %s\n", err.c_str());
                        return false;
                    };
                    const int n = l.n_exp;
                    const size_t nw = (size_t) n * D;
                    CK(cudaSetDevice(d.id));
                    std::vector<uint16_t> hw(nw);
                    std::vector<float> fw(nw), hx((size_t) kRows * D), y16((size_t) kRows * 1024), y32(y16.size());
                    CK(cudaMemcpy(hw.data(), l.gate_w.h, nw * 2, cudaMemcpyDeviceToHost));
                    for (size_t i = 0; i < nw; ++i) fw[i] = bf16_to_f32(hw[i]);
                    for (auto& v : hx) v = rnd();
                    float *dw = nullptr, *dx = nullptr, *dy = nullptr;
                    if (cudaMalloc((void**) &dw, nw * 4) != cudaSuccess || cudaMalloc((void**) &dx, hx.size() * 4) != cudaSuccess ||
                        cudaMalloc((void**) &dy, 2 * y16.size() * 4) != cudaSuccess) {
                        (void) cudaGetLastError();
                        if (dw != nullptr) cudaFree(dw);
                        if (dx != nullptr) cudaFree(dx);
                        return fail_at("its buffers");
                    }
                    CK(cudaMemcpy(dw, fw.data(), nw * 4, cudaMemcpyHostToDevice));
                    CK(cudaMemcpy(dx, hx.data(), hx.size() * 4, cudaMemcpyHostToDevice));
                    bool ok = true;
                    std::string why;
                    for (const int T : {1, 3, kRows}) {
                        if (!ok) break;
                        CK(cudaMemsetAsync(dy, 0xff, 2 * y16.size() * 4, d.st));
                        gemv_f32(l.gate_w, dx, n, D, T, dy, 1024, d.st);
                        gemv_f32((const float*) dw, dx, n, D, T, dy + y16.size(), 1024, d.st);
                        CK(cudaStreamSynchronize(d.st));
                        CK(cudaMemcpy(y16.data(), dy, y16.size() * 4, cudaMemcpyDeviceToHost));
                        CK(cudaMemcpy(y32.data(), dy + y16.size(), y32.size() * 4, cudaMemcpyDeviceToHost));
                        for (int t = 0; t < T && ok; ++t)
                            for (int r = 0; r < n && ok; ++r) {
                                const size_t o = (size_t) t * 1024 + r;
                                if (std::memcmp(&y16[o], &y32[o], 4) != 0) {
                                    ok = false;
                                    why = std::to_string(T) + " rows: row " + std::to_string(r) + " of token " + std::to_string(t) +
                                          " BF16 " + std::to_string(y16[o]) + ", F32 " + std::to_string(y32[o]);
                                }
                            }
                        if (T != 1) continue;
                        for (int r = 0; r < n && ok; ++r) {   // the old kernel's sums on the host: token 0, every row
                            float v[32];
                            for (int lane = 0; lane < 32; ++lane) {
                                float acc = 0.0f;
                                for (int c = lane; c < D / 4; c += 32)
                                    for (int e = 0; e < 4; ++e)
                                        acc = std::fmaf(fw[(size_t) r * D + 4 * c + e], hx[(size_t) 4 * c + e], acc);
                                v[lane] = acc;
                            }
                            for (int o = 16; o > 0; o >>= 1) {
                                float w2[32];
                                for (int lane = 0; lane < 32; ++lane) w2[lane] = v[lane] + v[lane ^ o];
                                std::memcpy(v, w2, sizeof v);
                            }
                            if (std::memcmp(&v[0], &y16[(size_t) r], 4) != 0) {
                                ok = false;
                                why = "row " + std::to_string(r) + " " + std::to_string(y16[(size_t) r]) +
                                      ", the old kernel's sums " + std::to_string(v[0]);
                            }
                        }
                    }
                    // the pair kernel (DS4_ROUTE_FUSE): the router before this one on the device and this one, against singles
                    if (ok && prev != nullptr && prev->gate_w.h != nullptr && prev->n_exp <= 1024 && n <= 1024)
                        for (const int T : {1, 3}) {
                            CK(cudaMemsetAsync(dy, 0xff, 2 * y16.size() * 4, d.st));
                            if (!gemv_f32_pair(prev->gate_w, prev->n_exp, dy, l.gate_w, n, dy + (size_t) T * 1024, dx, D, T,
                                               1024, d.st)) {
                                ok = false;
                                why = "the pair kernel's launch";
                                break;
                            }
                            gemv_f32(prev->gate_w, dx, prev->n_exp, D, T, dy + y16.size(), 1024, d.st);
                            gemv_f32(l.gate_w, dx, n, D, T, dy + y16.size() + (size_t) T * 1024, 1024, d.st);
                            CK(cudaStreamSynchronize(d.st));
                            CK(cudaMemcpy(y16.data(), dy, y16.size() * 4, cudaMemcpyDeviceToHost));
                            CK(cudaMemcpy(y32.data(), dy + y16.size(), y32.size() * 4, cudaMemcpyDeviceToHost));
                            for (int t = 0; t < 2 * T && ok; ++t)
                                for (int r = 0; r < (t < T ? prev->n_exp : n) && ok; ++r)
                                    if (std::memcmp(&y16[(size_t) t * 1024 + r], &y32[(size_t) t * 1024 + r], 4) != 0) {
                                        ok = false;
                                        why = "the pair kernel (" + std::to_string(T) + " rows) against the single one";
                                    }
                        }
                    cudaFree(dw);
                    cudaFree(dx);
                    cudaFree(dy);
                    if (!ok) return fail_at(why);
                    prev = &l;
                    ++layers;
                }
        }
        std::fprintf(stderr, "ds4: router check: %d BF16 routers (every member), the F32 copy's bits and the old kernel's sums "
                             "(1, 3 and %d rows; the pair kernel) (DS4_ROUTER_BF16)\n",
                     layers, kRows);
        return true;
    }
    // DS4_DECODE_TRIM's checks (at load, before any request; Project Maya #512's, ported).  trim_run: one run on device d's
    // stream - the inputs up, both output sets 0xA5, enqueue() (the old path into set 0, the new one into set 1), the
    // readback, its end (fuse_end) - then the two sets' bytes compared and every byte outside `regions` checked untouched.
    // false (why set): a difference, a guard touched, a launch refused or a CUDA error before a clean end
    template <class F>
    bool trim_run(Dev& d, const std::string& what, const std::vector<float>& hin, size_t set_bytes,
                  const std::vector<std::pair<size_t, size_t>>& regions, F&& enqueue, std::string& why) {
        float* in = nullptr;
        uint8_t *out = nullptr, *back = nullptr;
        cudaEvent_t ev = nullptr;
        if (cudaMalloc((void**) &in, std::max<size_t>(1, hin.size()) * 4) != cudaSuccess ||
            cudaMalloc((void**) &out, 2 * set_bytes) != cudaSuccess || cudaMallocHost((void**) &back, 2 * set_bytes) != cudaSuccess ||
            cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) {
            (void) cudaGetLastError();
            if (in != nullptr) cudaFree(in);
            if (out != nullptr) cudaFree(out);
            if (back != nullptr) cudaFreeHost(back);
            if (ev != nullptr) cudaEventDestroy(ev);
            why = what + ": its buffers";
            return false;
        }
        bool ok = cudaMemcpyAsync(in, hin.data(), hin.size() * 4, cudaMemcpyHostToDevice, d.st) == cudaSuccess &&
                  cudaMemsetAsync(out, 0xA5, 2 * set_bytes, d.st) == cudaSuccess;
        ok = ok && enqueue(in, out, out + set_bytes);
        ok = ok && cudaGetLastError() == cudaSuccess &&
             cudaMemcpyAsync(back, out, 2 * set_bytes, cudaMemcpyDeviceToHost, d.st) == cudaSuccess;
        const bool recorded = ok && cudaEventRecord(ev, d.st) == cudaSuccess;
        fuse_end("DS4_DECODE_TRIM check", d.id, -1, d.st, ev, recorded);
        if (!recorded) {
            (void) cudaGetLastError();
            why = what + ": a launch refused or a CUDA error";
        } else {
            const uint8_t *A = back, *B = back + set_bytes;
            for (size_t o = 0; o < set_bytes && why.empty(); ++o)
                if (A[o] != B[o]) why = what + ": byte " + std::to_string(o) + " differs";
            size_t prev = 0;   // (A == B now: A's bytes outside the regions)
            for (const auto& r : regions) {
                for (size_t o = prev; o < r.first && why.empty(); ++o)
                    if (A[o] != 0xA5) why = what + ": guard byte " + std::to_string(o);
                prev = r.first + r.second;
            }
            for (size_t o = prev; o < set_bytes && why.empty(); ++o)
                if (A[o] != 0xA5) why = what + ": the last guard byte " + std::to_string(o);
        }
        cudaFree(in);   // (the run ended cleanly)
        cudaFree(out);
        cudaFreeHost(back);
        cudaEventDestroy(ev);
        return recorded && why.empty();
    }
    // bits 1 / 2, on every device with layers: for its first and last trunk layer (its member), on 1 and kWin rows of
    // random inputs and of edges (zeros, negative zeros, tiny, and large past the swiglu's clamp, 32-blocks of each): 1
    // swiglu_q8 against swiglu, 2 q's norm finish with its int8 rounding against the finish, each then gguf mv's own
    // rounding (q8_round) and the layer's s2 / wq_b (a3: its decode prefix) - the old path rounding its own, the new one
    // given its int8 rows (PreQ8): the activations, the int8 rows and scales and the GEMV's rows equal byte for byte
    bool trim_q8_check(std::string& err) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x51ed2701u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;   // -4 .. 4
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            std::vector<const Layer*> ls;
            for (const Layer& l0 : L)
                if (!l0.mtp)
                    for (int mm = 0; mm < l0.nm; ++mm)
                        if (member(l0, mm).dev == (int) di) ls.push_back(&member(l0, mm));
            if (ls.empty()) continue;
            if (ls.size() > 2) ls = {ls.front(), ls.back()};
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                return false;
            }
            int runs = 0;
            for (const Layer* lp : ls)
                for (int part = 1; part <= 2; ++part) {
                    if (!(decode_trim & part)) continue;
                    const Layer& l = *lp;
                    const x3::Mat& m = part == 1 ? l.s2 : (l.a3 ? l.a3_qd : l.wq_b);
                    if (m.raw == nullptr || m.n <= 0 || m.k <= 0 || (part == 2 && l.ahn == 0)) continue;
                    const int K = m.k, N = m.n;   // (s2: the member's ff part in; wq_b: q_lora in, its heads out)
                    if (K % 32 != 0 || (part == 2 && K != g.q_lora)) {
                        err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": layer " + std::to_string(l.il) +
                              (part == 1 ? "'s s2" : "'s wq_b") + " takes " + std::to_string(K) + " values";
                        return false;
                    }
                    for (int T : {1, kWin})
                        for (int kind = 0; kind < 2; ++kind) {
                            const size_t n = (size_t) T * K;
                            const size_t rb[4] = {n * 4, n, n / 32 * 4, (size_t) T * N * 4};   // act | q | qd | y
                            size_t at[4], set_bytes = 0;
                            std::vector<std::pair<size_t, size_t>> regions;
                            for (int r = 0; r < 4; ++r) {
                                at[r] = set_bytes + kGuard;
                                set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
                                regions.push_back({at[r], rb[r]});
                            }
                            set_bytes += kGuard;
                            std::vector<float> hin(part == 1 ? 2 * n : n);
                            for (size_t i = 0; i < hin.size(); ++i) {
                                float v = rnd();
                                if (kind == 1)
                                    switch ((i / 32) % 6) {
                                        case 0: v = 0.0f; break;
                                        case 1: v = -0.0f; break;
                                        case 2: v *= 1e-20f; break;
                                        case 3: v *= 1e6f; break;   // (past swiglu's clamp)
                                        default: break;
                                    }
                                hin[i] = v;
                            }
                            auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                                uint8_t* set[2] = {s0, s1};
                                auto A = [&](int b) { return (float*) (set[b] + at[0]); };
                                auto Q = [&](int b) { return (int8_t*) (set[b] + at[1]); };
                                auto Qd = [&](int b) { return (float*) (set[b] + at[2]); };
                                auto Y = [&](int b) { return (float*) (set[b] + at[3]); };
                                bool ok = true;
                                if (part == 1) {
                                    swiglu(in, in + n, (int) n, g.lim, A(0), d.st);
                                    ok = swiglu_q8(in, in + n, (int) n, g.lim, A(1), Q(1), Qd(1), d.st);
                                } else {
                                    Finish f0;
                                    f0.w = l.q_norm;
                                    f0.eps = g.eps;
                                    Finish f1 = f0;
                                    f1.q8 = Q(1);
                                    f1.q8d = Qd(1);
                                    ok = cudaMemcpyAsync(A(0), in, n * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                         cudaMemcpyAsync(A(1), in, n * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess;
                                    finish(A(0), T, K, K, f0, d.st);
                                    finish(A(1), T, K, K, f1, d.st);
                                }
                                gg::q8_round(A(0), T, K, Q(0), Qd(0), d.st);   // (the old path's rounding, as mv gives it)
                                x3::MvJob j0 = job(m, A(0), Y(0), T, K, N), j1 = job(m, A(1), Y(1), T, K, N);
                                gg::PreQ8 pq;
                                pq.x = A(1);
                                pq.q = Q(1);
                                pq.d = Qd(1);
                                pq.k = K;
                                pq.rows = T;
                                return ok && mv_any(&j0, 1, d.st) && mv_any(&j1, 1, d.st, &pq);
                            };
                            std::string why;
                            const std::string what = std::string(part == 1 ? "s2's int8 from swiglu" : "wq_b's int8 from q's norm") +
                                                     ", layer " + std::to_string(l.il) + ", " + std::to_string(T) +
                                                     (kind ? " rows, edges" : " rows, random");
                            if (!trim_run(d, what, hin, set_bytes, regions, enqueue, why)) {
                                err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": " + why;
                                std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check FAILED: %s\n", d.id, why.c_str());
                                return false;
                            }
                            ++runs;
                        }
                }
            std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check: %d runs (the first and last layers; 1 and %d rows; random "
                                 "/ edges):%s%s the activations, int8 rows and scales and the GEMVs the old path's bit for bit, "
                                 "every guard intact\n",
                         d.id, runs, kWin, decode_trim & 1 ? " swiglu_q8 + s2;" : "", decode_trim & 2 ? " q's norm + wq_b;" : "");
        }
        return true;
    }
    // bit 4: copy_regions against four runtime copies (odd lengths), on every device
    bool trim_copy_check(std::string& err) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x2b7e1516u;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;
        };
        for (Dev& d : devs) {
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                return false;
            }
            const size_t nf[4] = {1, 37, 1024, 4099};   // (floats a region)
            size_t at[4], set_bytes = 0, src_at[4], n_in = 0;
            std::vector<std::pair<size_t, size_t>> regions;
            for (int r = 0; r < 4; ++r) {
                at[r] = set_bytes + kGuard;
                set_bytes = (at[r] + nf[r] * 4 + 255) / 256 * 256;
                regions.push_back({at[r], nf[r] * 4});
                src_at[r] = n_in;
                n_in += nf[r];
            }
            set_bytes += kGuard;
            std::vector<float> hin(n_in);
            for (float& v : hin) v = rnd();
            auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                CopyRegions cr;
                bool ok = true;
                for (int r = 0; r < 4; ++r) {
                    ok = ok && cudaMemcpyAsync(s0 + at[r], in + src_at[r], nf[r] * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess;
                    cr.dst[r] = s1 + at[r];
                    cr.src[r] = in + src_at[r];
                    cr.bytes[r] = nf[r] * 4;
                }
                cr.n = 4;
                return ok && copy_regions(cr, d.st);
            };
            std::string why;
            if (!trim_run(d, "copy_regions", hin, set_bytes, regions, enqueue, why)) {
                err = "DS4_DECODE_TRIM check on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check FAILED: %s\n", d.id, why.c_str());
                return false;
            }
            std::fprintf(stderr, "ds4: CUDA%d DS4_DECODE_TRIM check: copy_regions (4 regions, 1 .. 4099 floats) the runtime "
                                 "copies' bytes, every guard intact\n",
                         d.id);
        }
        return true;
    }

    // ---- FG-07: DS4_AR_POST / DS4_ATTN_MERGE (docs/dsv41/cards/FG-07.md)
    // the all-reduce of y (T rows of the model's dim) with hc_post into d.h2: allreduce_post where the flag takes the call,
    // else allreduce() then hc_post() as before.  The seq advances once either way
    void ar_then_post(Dev& d, float* y, int T, const ArGroup& ag, int mi, int nm, const float* post, const float* comb,
                      cudaStream_t s) {
        const int D = g.dim, H = g.hc;
        if (nm > 1 && ar_post > 0 && T >= 1 && T <= kWin) {
            HcPost hp;
            hp.res = d.h;
            hp.post = post;
            hp.comb = comb;
            hp.out = d.h2;
            hp.dim = D;
            hp.hc = H;
            if (allreduce_post(y, T * D, ag, mi, d.ar_seq + 1, d.xcnt, &hp, ar_post, s)) {
                ++d.ar_seq;
                if (!(ar_post & 1)) hc_post(y, d.h, post, comb, D, H, T, d.h2, s);   // (bit 2 alone: the put folded only)
                return;
            }
        }
        if (nm > 1) allreduce(y, T * D, ag, mi, ++d.ar_seq, d.xcnt, s);
        hc_post(y, d.h, post, comb, D, H, T, d.h2, s);
    }
    // whether layer l's window of T rows takes the merged attention launches
    bool attn_merges(const Layer& l, int T) const {
        return attn_merge > 0 && !l.mtp && T >= 1 && (T == 1 || (attn_merge > 1 && T <= kWin)) && dump_s == nullptr &&
               dump_l == nullptr;
    }
    // DS4_AR_POST's check, every device with layers, T rows: allreduce_post's kernels on the device alone (one member: x
    // its own sum) against hc_post's launch - the streams out, x and (bit 2) the put's row equal byte for byte, guards intact.
    // Random and edge inputs.  (The sums' chain is ar_sum_kernel's, unchanged; the cross-device run is the GPU identity test)
    bool ar_post_check(std::string& err, int T) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x7a3c19e5u ^ (uint32_t) T;
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;
        };
        const int D = g.dim, H = g.hc;
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            bool has = false;
            for (const Layer& l0 : L)
                for (int mm = 0; mm < l0.nm; ++mm) has = has || member(l0, mm).dev == (int) di;
            if (!has) continue;
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_AR_POST check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                return false;
            }
            const size_t ny = (size_t) T * D, nh = (size_t) T * H * D;
            // inputs: y | res | post (T x 8) | comb (T x 64); a set: out | x | rows | flags
            const size_t rb[4] = {nh * 4, ny * 4, ny * 4, (size_t) kArBlocks * 8 * 4};
            size_t at[4], set_bytes = 0;
            std::vector<std::pair<size_t, size_t>> regions;
            for (int r = 0; r < 4; ++r) {
                at[r] = set_bytes + kGuard;
                set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
            }
            set_bytes += kGuard;
            for (int mode = 1; mode <= 3; ++mode) {
                if ((mode & ~ar_post) != 0) continue;   // (the bit sets the flag can take)
                for (int kind = 0; kind < 2; ++kind) {
                    std::vector<float> hin(ny + nh + (size_t) T * 8 + (size_t) T * 64);
                    for (size_t i = 0; i < hin.size(); ++i) {
                        float v = rnd();
                        if (kind == 1) switch ((i / 7) % 5) {
                                case 0: v = 0.0f; break;
                                case 1: v = -0.0f; break;
                                case 2: v *= 1e-30f; break;
                                case 3: v *= 1e15f; break;
                                default: break;
                            }
                        hin[i] = v;
                    }
                    regions.clear();
                    regions.push_back({at[0], rb[0]});
                    regions.push_back({at[1], rb[1]});
                    if (mode & 2) {
                        regions.push_back({at[2], rb[2]});
                        regions.push_back({at[3], rb[3]});   // (the flags: only the blocks' slots change; compared whole)
                    }
                    auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                        uint8_t* set[2] = {s0, s1};
                        const float* y = in;
                        const float* res = in + ny;
                        const float* post = res + nh;
                        const float* comb = post + (size_t) T * 8;
                        bool ok = true;
                        for (int b = 0; b < 2; ++b)
                            ok = ok && cudaMemcpyAsync(set[b] + at[1], y, ny * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess;
                        // the old path: hc_post on y; bit 2: the put's row as xfer_put leaves it (a copy of y) and each
                        // block's flag word as the new kernel must leave it (seq 1 at its slot's first word)
                        hc_post(y, res, post, comb, D, H, T, (float*) (set[0] + at[0]), d.st);
                        if (mode & 2) {
                            ok = ok && cudaMemcpyAsync(set[0] + at[2], y, ny * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess;
                            // flags: block b's slot [b * 8] = seq 1, the rest of the slot untouched (0xA5)
                            constexpr int kTh = 256;   // (ds4_kernels.cu's kThreads: allreduce_post's block size)
                            const int blocks = std::max(1, std::min(64, (int) ((ny / 4 + kTh - 1) / kTh)));
                            for (int b = 0; b < blocks; ++b) {
                                static const unsigned one = 1u;
                                ok = ok && cudaMemcpyAsync(set[0] + at[3] + (size_t) b * 32, &one, 4, cudaMemcpyHostToDevice, d.st) ==
                                               cudaSuccess;
                            }
                        }
                        HcPost hp;
                        hp.res = res;
                        hp.post = post;
                        hp.comb = comb;
                        hp.out = (float*) (set[1] + at[0]);
                        hp.dim = D;
                        hp.hc = H;
                        float* rows = (float*) (set[1] + at[2]);
                        unsigned* flags = (unsigned*) (set[1] + at[3]);
                        // (bit 2 alone runs the put + sum kernel without the post: then set 1's out is hc_post's launch, as
                        //  ar_then_post does)
                        if (!(mode & 1)) hc_post((float*) (set[1] + at[1]), res, post, comb, D, H, T, hp.out, d.st);
                        return ok && allreduce_post_selftest((float*) (set[1] + at[1]), (int) ny, rows, flags, hp, mode, d.st);
                    };
                    std::string why;
                    const std::string what = std::string("mode ") + std::to_string(mode) + ", " + std::to_string(T) +
                                             (kind ? " rows, edges" : " rows, random");
                    if (!trim_run(d, what, hin, set_bytes, regions, enqueue, why)) {
                        err = "DS4_AR_POST check on CUDA" + std::to_string(d.id) + ": " + why;
                        std::fprintf(stderr, "ds4: CUDA%d DS4_AR_POST check FAILED: %s\n", d.id, why.c_str());
                        return false;
                    }
                }
            }
            std::fprintf(stderr, "ds4: CUDA%d DS4_AR_POST check (%d rows): the folded hc_post (and put) against the launches, "
                                 "random / edges, byte for byte, every guard intact\n",
                         d.id, T);
        }
        return true;
    }
    // (DS4_TOPK_MB) topk_mb against topk_kernel byte for byte on each layer device, its stream and its own d.tmb:
    // synthetic rows - ties (quantized scores, an all-equal row, -inf runs), a take-all row (k >= n), an empty row, k = n - 1,
    // candidate positions, full-range keys, row sizes from 8K to past kTopkMbMaxG x 2048 - each case run twice (the
    // scratch's histograms must come back zero).  Then one indicative timing line (synthetic scores, load-time clocks)
    bool topk_mb_check(std::string& err) {
        struct Case {
            int T, kind, blk;
            std::vector<int> n, k;
        };
        std::vector<Case> cs;
        auto one = [&](int kind, int n, int k, int blk = 1) { cs.push_back({1, kind, blk, {n}, {k}}); };
        one(0, 28190, 512);                                     // 110K tokens at ratio 4, quantized (ties)
        one(0, 16384, 512, g.cand_blk > 0 ? g.cand_blk : 8);    // the candidates' top-k shape, cand positions
        one(1, 140000, 2048);                                   // full-range keys, chunk > 2048 (G capped)
        one(2, 9000, 512);                                      // 10 finite, the rest -inf: ties among -inf
        one(0, 8192, 8191);                                     // k = n - 1
        {
            Case c{kWin, 0, 1, {}, {}};
            for (int t = 0; t < kWin; ++t) {
                int n = 8192 + 1237 * t, k = std::min(512, n);
                if (t == 3) n = 300;      // take-all (k >= n)
                if (t == 5) n = 0;        // empty
                if (t == 7) n = 10000;    // all equal (kind 3, below)
                if (t == 11) k = n - 1;   // (t 9: -inf runs, kind 2, below)
                c.n.push_back(n);
                c.k.push_back(t == 3 ? 512 : k);
            }
            cs.push_back(c);
        }
        cs.push_back({3, 1, 1, {20000, 19999, 12345}, {2048, 2048, 2048}});   // cand_blocks-like k, full-range keys
        size_t vmax = 0;
        int kmax = 1;
        for (const Case& c : cs) {
            int nm = 1;
            for (int t = 0; t < c.T; ++t) {
                nm = std::max(nm, c.n[(size_t) t]);
                kmax = std::max(kmax, c.k[(size_t) t]);
            }
            vmax = std::max(vmax, (size_t) c.T * (size_t) (nm + 64));
        }
        const int ostride = std::max(kmax, 1);
        const int cstride = 4096;
        auto fill = [&](std::vector<float>& h, int kind, int n, uint32_t& st) {
            auto u32 = [&]() {
                st = st * 1664525u + 1013904223u;
                return st;
            };
            for (int i = 0; i < n; ++i) {
                float v;
                if (kind == 1) {   // any bit pattern but NaN
                    uint32_t b;
                    do b = u32() ^ (u32() << 13);
                    while ((b & 0x7f800000u) == 0x7f800000u && (b & 0x007fffffu) != 0u);
                    std::memcpy(&v, &b, 4);
                } else if (kind == 2) {
                    v = (i % 900 == 7) ? (float) (int) (u32() % 64u) / 8.0f : -INFINITY;
                } else if (kind == 3) {
                    v = 1.25f;
                } else {   // ~ a sum of uniforms (bell-shaped), on a 1/64 grid: many ties, a few dense top bins
                    int a = 0;
                    for (int j = 0; j < 4; ++j) a += (int) (u32() % 1001u);
                    v = (float) (a - 2000) / 64.0f;
                }
                h[(size_t) i] = v;
            }
        };
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            if (d.tmb == nullptr) continue;
            auto fail_at = [&](const std::string& why) {
                err = "DS4_TOPK_MB check on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d DS4_TOPK_MB check FAILED: %s\n", d.id, why.c_str());
                return false;
            };
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                return fail_at("cudaSetDevice failed");
            }
            const cudaStream_t s = d.st;
            float* vals = nullptr;
            int *oa = nullptr, *ob = nullptr, *cand = nullptr;
            const size_t ob_n = (size_t) kWin * ostride;
            if (cudaMalloc((void**) &vals, vmax * 4) != cudaSuccess || cudaMalloc((void**) &oa, ob_n * 4) != cudaSuccess ||
                cudaMalloc((void**) &ob, ob_n * 4) != cudaSuccess ||
                cudaMalloc((void**) &cand, (size_t) kWin * cstride * 4) != cudaSuccess) {
                (void) cudaGetLastError();
                for (void* q : {(void*) vals, (void*) oa, (void*) ob, (void*) cand})
                    if (q != nullptr) cudaFree(q);
                return fail_at("its buffers");
            }
            auto release = [&]() {
                cudaStreamSynchronize(s);
                cudaFree(vals);
                cudaFree(oa);
                cudaFree(ob);
                cudaFree(cand);
                (void) cudaGetLastError();
            };
            uint32_t st = 0x6a09e667u ^ (uint32_t) (d.id * 7919);
            std::vector<int> ha(ob_n), hb(ob_n), hc((size_t) kWin * cstride);
            for (int& c : hc) {
                st = st * 1664525u + 1013904223u;
                c = (int) (st % 100000u);
            }
            if (cudaMemcpy(cand, hc.data(), hc.size() * 4, cudaMemcpyHostToDevice) != cudaSuccess) {
                release();
                return fail_at("cand upload");
            }
            int rows = 0;
            for (size_t ci = 0; ci < cs.size(); ++ci) {
                const Case& c = cs[ci];
                int nm = 1;
                for (int t = 0; t < c.T; ++t) nm = std::max(nm, c.n[(size_t) t]);
                const long long vs = nm + 64;
                std::vector<float> hv((size_t) c.T * (size_t) vs, -INFINITY);
                Rows r;
                for (int t = 0; t < c.T; ++t) {
                    std::vector<float> row((size_t) std::max(1, c.n[(size_t) t]));
                    int kind = c.kind;
                    if (c.T == kWin && t == 7) kind = 3;
                    if (c.T == kWin && t == 9) kind = 2;
                    fill(row, kind, c.n[(size_t) t], st);
                    std::copy(row.begin(), row.begin() + c.n[(size_t) t], hv.begin() + (size_t) t * vs);
                    r.n[t] = c.n[(size_t) t];
                    r.k[t] = c.k[(size_t) t];
                }
                const int* cd = c.blk > 1 ? cand : nullptr;
                if (cudaMemcpy(vals, hv.data(), hv.size() * 4, cudaMemcpyHostToDevice) != cudaSuccess) {
                    release();
                    return fail_at("vals upload");
                }
                for (int rep = 0; rep < 2; ++rep) {
                    if (cudaMemsetAsync(oa, 0xff, ob_n * 4, s) != cudaSuccess || cudaMemsetAsync(ob, 0xff, ob_n * 4, s) != cudaSuccess) {
                        release();
                        return fail_at("memset");
                    }
                    topk(vals, vs, c.T, r, cd, cstride, c.blk, oa, ostride, s);   // (mb nullptr: topk_kernel)
                    ::strata::ds4::topk_mb(vals, vs, c.T, r, cd, cstride, c.blk, ob, ostride, d.tmb, s);
                    if (cudaStreamSynchronize(s) != cudaSuccess || cudaGetLastError() != cudaSuccess ||
                        cudaMemcpy(ha.data(), oa, ob_n * 4, cudaMemcpyDeviceToHost) != cudaSuccess ||
                        cudaMemcpy(hb.data(), ob, ob_n * 4, cudaMemcpyDeviceToHost) != cudaSuccess) {
                        (void) cudaGetLastError();
                        release();
                        return fail_at("case " + std::to_string(ci) + ": a launch or copy failed");
                    }
                    for (size_t j = 0; j < (size_t) c.T * ostride; ++j)
                        if (ha[j] != hb[j]) {
                            const std::string why = "case " + std::to_string(ci) + " pass " + std::to_string(rep) + " row " +
                                                    std::to_string(j / ostride) + " slot " + std::to_string(j % ostride) +
                                                    ": topk_kernel " + std::to_string(ha[j]) + ", topk_mb " +
                                                    std::to_string(hb[j]);
                            release();
                            return fail_at(why);
                        }
                }
                rows += c.T;
            }
            // the histograms must be zero again (the next decode call relies on it)
            {
                std::vector<unsigned> hz((size_t) kWin * kTopkMbRow);
                if (cudaMemcpy(hz.data(), d.tmb, hz.size() * 4, cudaMemcpyDeviceToHost) != cudaSuccess) {
                    release();
                    return fail_at("scratch read-back");
                }
                for (int t = 0; t < kWin; ++t)
                    for (int j = 0; j < 8448; ++j)
                        if (hz[(size_t) t * kTopkMbRow + j] != 0u) {
                            release();
                            return fail_at("scratch row " + std::to_string(t) + " word " + std::to_string(j) + " not zero after use");
                        }
            }
            std::fprintf(stderr, "ds4: DS4_TOPK_MB check (CUDA%d): %d cases, %d rows, twice each: identical to topk_kernel\n",
                         d.id, (int) cs.size(), rows);
            // indicative timing: one row of quantized scores, old vs new, 20 launches each (synthetic, load-time clocks)
            {
                cudaEvent_t e0 = nullptr, e1 = nullptr;
                std::string line;
                if (cudaEventCreate(&e0) == cudaSuccess && cudaEventCreate(&e1) == cudaSuccess) {
                    for (int n : {8192, 16384, 28190}) {
                        std::vector<float> hv((size_t) n);
                        fill(hv, 0, n, st);
                        Rows r;
                        r.n[0] = n;
                        r.k[0] = std::min(g.ix_topk > 0 ? g.ix_topk : 512, n);
                        if (cudaMemcpy(vals, hv.data(), (size_t) n * 4, cudaMemcpyHostToDevice) != cudaSuccess) break;
                        float us[2] = {0.0f, 0.0f};
                        for (int m = 0; m < 2; ++m) {
                            for (int w = 0; w < 3; ++w)
                                m ? ::strata::ds4::topk_mb(vals, n + 64, 1, r, nullptr, 0, 1, ob, ostride, d.tmb, s)
                                  : topk(vals, n + 64, 1, r, nullptr, 0, 1, oa, ostride, s);
                            cudaEventRecord(e0, s);
                            for (int it = 0; it < 20; ++it)
                                m ? ::strata::ds4::topk_mb(vals, n + 64, 1, r, nullptr, 0, 1, ob, ostride, d.tmb, s)
                                  : topk(vals, n + 64, 1, r, nullptr, 0, 1, oa, ostride, s);
                            cudaEventRecord(e1, s);
                            float ms = 0.0f;
                            if (cudaEventSynchronize(e1) == cudaSuccess && cudaEventElapsedTime(&ms, e0, e1) == cudaSuccess)
                                us[m] = ms * 1000.0f / 20.0f;
                        }
                        char b[96];
                        std::snprintf(b, sizeof b, "%sn %d k %d: old %.1f us, mb %.1f us", line.empty() ? "" : " | ", n, r.k[0],
                                      us[0], us[1]);
                        line += b;
                    }
                }
                if (e0 != nullptr) cudaEventDestroy(e0);
                if (e1 != nullptr) cudaEventDestroy(e1);
                (void) cudaGetLastError();
                std::fprintf(stderr, "ds4: DS4_TOPK_MB timing (CUDA%d; synthetic, load-time, back-to-back launches): %s\n", d.id,
                             line.c_str());
            }
            release();
        }
        return true;
    }
    // DS4_ATTN_MERGE's check, every device with layers (its first and last trunk member layer with heads), T rows, random
    // inputs and a ring of valid FP8 rows: the old launches (q norm [+ int8], q RoPE, ring_to_ext, the KV finish,
    // ext_to_ring [+ backup]) into set 0, the two merged launches into set 1 - every byte equal, guards intact
    bool attn_merge_check(std::string& err, int T) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x3f84d5b5u ^ (uint32_t) (T * 977);
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;
        };
        auto rndu = [&]() {
            st = st * 1664525u + 1013904223u;
            return st >> 8;
        };
        const int HD = g.hd, QL = g.q_lora, W = g.win;
        const size_t rbr = kv_row_bytes(kKvFp8, HD);
        if (rbr % 4 != 0) {
            err = "DS4_ATTN_MERGE check: a ring row of " + std::to_string(rbr) + " bytes";
            return false;
        }
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            std::vector<const Layer*> ls;
            for (const Layer& l0 : L)
                if (!l0.mtp)
                    for (int mm = 0; mm < l0.nm; ++mm)
                        if (member(l0, mm).dev == (int) di && member(l0, mm).ahn > 0) ls.push_back(&member(l0, mm));
            if (ls.empty()) continue;
            if (ls.size() > 2) ls = {ls.front(), ls.back()};
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_ATTN_MERGE check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                return false;
            }
            int runs = 0;
            for (const Layer* lp : ls)
                for (int q8 = 0; q8 < 2; ++q8) {
                    const Layer& l = *lp;
                    const int NHL = l.ahn;
                    const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
                    const long long p0 = T == 1 ? 1000 + l.il : 5;   // (T kWin: rows before position 0 too)
                    const bool bak = T > 1;
                    // a set: qr | qr int8 | qr scales | q | ext | kvr | ring | backup
                    const size_t rb[8] = {(size_t) T * QL * 4, (size_t) T * QL, (size_t) T * QL / 32 * 4, (size_t) T * NHL * HD * 4,
                                          ((size_t) W + T) * HD * 2, (size_t) T * HD * 4, (size_t) W * rbr, (size_t) T * rbr};
                    size_t at[8], set_bytes = 0;
                    std::vector<std::pair<size_t, size_t>> regions;
                    for (int r = 0; r < 8; ++r) {
                        at[r] = set_bytes + kGuard;
                        set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
                        if ((r == 1 || r == 2) && !q8) continue;
                        if (r == 7 && !bak) continue;
                        regions.push_back({at[r], rb[r]});
                    }
                    set_bytes += kGuard;
                    // inputs (floats): qr | q | kvr | the ring's bytes
                    const size_t n_qr = (size_t) T * QL, n_q = (size_t) T * NHL * HD, n_kv = (size_t) T * HD, n_ring = (size_t) W * rbr / 4;
                    std::vector<float> hin(n_qr + n_q + n_kv + n_ring);
                    for (size_t i = 0; i < n_qr + n_q + n_kv; ++i) hin[i] = rnd();
                    {
                        std::vector<uint8_t> ring((size_t) W * rbr);
                        for (int r = 0; r < W; ++r) {
                            uint8_t* row = ring.data() + (size_t) r * rbr;
                            for (int e = 0; e < HD; ++e) row[e] = (uint8_t) ((rndu() % 0x7e) | ((rndu() & 1u) << 7));   // (no NaN code)
                            for (int b = 0; b < HD / 32; ++b) row[HD + b] = (uint8_t) (120 + rndu() % 15);
                        }
                        std::memcpy(hin.data() + n_qr + n_q + n_kv, ring.data(), ring.size());
                    }
                    auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                        uint8_t* set[2] = {s0, s1};
                        bool ok = true;
                        for (int b = 0; b < 2; ++b) {
                            ok = ok && cudaMemcpyAsync(set[b] + at[0], in, n_qr * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[3], in + n_qr, n_q * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[5], in + n_qr + n_q, n_kv * 4, cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[6], in + n_qr + n_q + n_kv, (size_t) W * rbr, cudaMemcpyDeviceToDevice,
                                                 d.st) == cudaSuccess;
                        }
                        Finish fq[2], fr, fk[2];
                        for (int b = 0; b < 2; ++b) {
                            fq[b].w = l.q_norm;
                            fq[b].eps = g.eps;
                            if (q8) {
                                fq[b].q8 = (int8_t*) (set[b] + at[1]);
                                fq[b].q8d = (float*) (set[b] + at[2]);
                            }
                            fk[b].w = l.kv_norm;
                            fk[b].eps = g.eps;
                            fk[b].rd = g.rd;
                            fk[b].pos = (int) p0;
                            fk[b].freqs = freqs;
                            fk[b].quant = 1;
                            fk[b].dst = (uint16_t*) (set[b] + at[4]) + (size_t) W * HD;
                            fk[b].dst_stride = HD;
                        }
                        fr.rd = g.rd;
                        fr.pos = (int) p0;
                        fr.vpp = NHL;
                        fr.freqs = freqs;
                        auto F = [&](int b, int r) { return (float*) (set[b] + at[r]); };
                        uint8_t* bk[2] = {bak ? set[0] + at[7] : nullptr, bak ? set[1] + at[7] : nullptr};
                        // set 0: the old launches, in layer()'s order
                        finish(F(0, 0), T, QL, QL, fq[0], d.st);
                        finish(F(0, 3), T * NHL, HD, HD, fr, d.st);
                        ring_to_ext(set[0] + at[6], (uint16_t*) (set[0] + at[4]), p0, W, HD, d.st);
                        finish(F(0, 5), T, HD, HD, fk[0], d.st);
                        ext_to_ring((const uint16_t*) (set[0] + at[4]), set[0] + at[6], p0, W, T, HD, d.st, bk[0]);
                        // set 1: the merged ones
                        FinOp a[3], b2[2];
                        a[0].kind = 0;
                        a[0].x = F(1, 0);
                        a[0].n_vec = T;
                        a[0].len = QL;
                        a[0].stride = QL;
                        a[0].f = fq[1];
                        a[1].kind = 1;
                        a[1].ring_r = set[1] + at[6];
                        a[1].ext_w = (uint16_t*) (set[1] + at[4]);
                        a[1].p0 = p0;
                        a[1].n = W;
                        a[1].d = HD;
                        a[2].kind = 0;
                        a[2].x = F(1, 5);
                        a[2].n_vec = T;
                        a[2].len = HD;
                        a[2].stride = HD;
                        a[2].f = fk[1];
                        b2[0].kind = 0;
                        b2[0].x = F(1, 3);
                        b2[0].n_vec = T * NHL;
                        b2[0].len = HD;
                        b2[0].stride = HD;
                        b2[0].f = fr;
                        b2[1].kind = 2;
                        b2[1].ext_r = (const uint16_t*) (set[1] + at[4]);
                        b2[1].ring_w = set[1] + at[6];
                        b2[1].backup = bk[1];
                        b2[1].p0 = p0;
                        b2[1].n = W;
                        b2[1].T = T;
                        b2[1].d = HD;
                        return ok && finish_multi(a, 3, d.st) && finish_multi(b2, 2, d.st);
                    };
                    std::string why;
                    const std::string what = "layer " + std::to_string(l.il) + ", " + std::to_string(T) + " rows" +
                                             (q8 ? ", q's int8" : "") + (bak ? ", the ring's backup" : "");
                    if (!trim_run(d, what, hin, set_bytes, regions, enqueue, why)) {
                        err = "DS4_ATTN_MERGE check on CUDA" + std::to_string(d.id) + ": " + why;
                        std::fprintf(stderr, "ds4: CUDA%d DS4_ATTN_MERGE check FAILED: %s\n", d.id, why.c_str());
                        return false;
                    }
                    ++runs;
                }
            std::fprintf(stderr, "ds4: CUDA%d DS4_ATTN_MERGE check (%d rows): %d runs (first / last layers; q's norm with and without "
                                 "its int8 rows): q, ext, the ring, the int8 rows byte for byte, every guard intact\n",
                         d.id, T, runs);
        }
        return true;
    }
    // DS4_ATTN_MERGE=3's check, every device with layers (its first trunk member layer with heads), T rows (1 and
    // kAttnScratchT): random q / ext / ring rows, random packed compressed rows (kKvFp4, finite scales) and selections (some
    // queries with none, one with every slot): set 0 the =2 second launch (q's RoPE + the KV row into the ring, the backup at
    // T > 1) then unpack_sel_kernel as sparse_attn launches it, set 1 finish_multi_sel's one launch - q, ext, the ring, the
    // backup and the scratch rows byte for byte, every guard intact.  Refused fold on a device: a failure (=3 asked for it)
    bool attn_merge3_check(std::string& err, int T) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x9e3779b9u ^ (uint32_t) (T * 7919);
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;
        };
        auto rndu = [&]() {
            st = st * 1664525u + 1013904223u;
            return st >> 8;
        };
        const int HD = g.hd, W = g.win, S = (int) topk_stride(), NR = 4096;
        const size_t rbr = kv_row_bytes(kKvFp8, HD), rb4 = kv_row_bytes(kKvFp4, 512);
        if (HD != 512 || rbr % 4 != 0 || rb4 % 4 != 0 || T < 1 || T > kAttnScratchT) {
            err = "DS4_ATTN_MERGE=3 check: head dim " + std::to_string(HD) + " / rows " + std::to_string(T) + " not covered";
            return false;
        }
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            const Layer* lp = nullptr;
            for (const Layer& l0 : L)
                if (!l0.mtp && lp == nullptr)
                    for (int mm = 0; mm < l0.nm; ++mm)
                        if (member(l0, mm).dev == (int) di && member(l0, mm).ahn > 0) lp = &member(l0, mm);
            if (lp == nullptr) continue;
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_ATTN_MERGE=3 check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                return false;
            }
            const Layer& l = *lp;
            const int NHL = l.ahn;
            const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
            const long long p0 = T == 1 ? 1000 + l.il : 5;
            const bool bak = T > 1;
            // a set: q | ext | ring | backup | ckv | sel | scratch rows
            const size_t rb[7] = {(size_t) T * NHL * HD * 4, ((size_t) W + T) * HD * 2, (size_t) W * rbr, (size_t) T * rbr,
                                  (size_t) NR * rb4, (size_t) T * S * 4, (size_t) T * S * 512 * 2};
            size_t at[7], set_bytes = 0;
            std::vector<std::pair<size_t, size_t>> regions;
            for (int r = 0; r < 7; ++r) {
                at[r] = set_bytes + kGuard;
                set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
                if (r == 3 && !bak) continue;
                regions.push_back({at[r], rb[r]});
            }
            set_bytes += kGuard;
            // inputs, as floats / bytes: q | ext | ring | ckv | sel
            const size_t iq = 0, ie = iq + rb[0] / 4, ir = ie + rb[1] / 4, ic = ir + rb[2] / 4, is = ic + rb[4] / 4, in_n = is + rb[5] / 4;
            std::vector<float> hin(in_n);
            for (size_t i = 0; i < rb[0] / 4; ++i) hin[iq + i] = rnd();
            {
                std::vector<uint16_t> ext(rb[1] / 2);
                for (auto& v : ext) v = (uint16_t) ((rndu() & 0x807fu) | ((120u + rndu() % 15u) << 7));   // (finite BF16)
                std::memcpy(hin.data() + ie, ext.data(), rb[1]);
                std::vector<uint8_t> ring(rb[2]);
                for (int r = 0; r < W; ++r) {
                    uint8_t* row = ring.data() + (size_t) r * rbr;
                    for (int e = 0; e < HD; ++e) row[e] = (uint8_t) ((rndu() % 0x7e) | ((rndu() & 1u) << 7));
                    for (int b = 0; b < HD / 32; ++b) row[HD + b] = (uint8_t) (120 + rndu() % 15);
                }
                std::memcpy(hin.data() + ir, ring.data(), rb[2]);
                std::vector<uint8_t> ckv(rb[4]);
                for (int r = 0; r < NR; ++r) {
                    uint8_t* row = ckv.data() + (size_t) r * rb4;
                    for (int e = 0; e < 256; ++e) row[e] = (uint8_t) rndu();                                    // (E2M1 codes)
                    for (int b = 0; b < 32; ++b) row[256 + b] = (uint8_t) ((rndu() % 0x7e) | ((rndu() & 1u) << 7));   // (E4M3)
                }
                std::memcpy(hin.data() + ic, ckv.data(), rb[4]);
                std::vector<int> sel((size_t) T * S);
                for (auto& v : sel) v = (int) (rndu() % (uint32_t) NR);
                std::memcpy(hin.data() + is, sel.data(), rb[5]);
            }
            AttnRows ar;
            for (int t = 0; t < T; ++t) {
                ar.win0[t] = 1;
                ar.nwin[t] = W;
                ar.nsel[t] = t == 0 ? S : (T > 1 && t == 1 ? 0 : (int) (rndu() % (uint32_t) (S + 1)));
            }
            auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                uint8_t* set[2] = {s0, s1};
                const uint8_t* ib = (const uint8_t*) in;
                bool ok = true;
                for (int b = 0; b < 2; ++b) {
                    ok = ok && cudaMemcpyAsync(set[b] + at[0], ib + iq * 4, rb[0], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                         cudaMemcpyAsync(set[b] + at[1], ib + ie * 4, rb[1], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                         cudaMemcpyAsync(set[b] + at[2], ib + ir * 4, rb[2], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                         cudaMemcpyAsync(set[b] + at[4], ib + ic * 4, rb[4], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                         cudaMemcpyAsync(set[b] + at[5], ib + is * 4, rb[5], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess;
                }
                Finish fr;
                fr.rd = g.rd;
                fr.pos = (int) p0;
                fr.vpp = NHL;
                fr.freqs = freqs;
                FinOp b2[2][2];
                SelOp u[2];
                AttnScratch sc[2];
                for (int b = 0; b < 2; ++b) {
                    b2[b][0].kind = 0;
                    b2[b][0].x = (float*) (set[b] + at[0]);
                    b2[b][0].n_vec = T * NHL;
                    b2[b][0].len = HD;
                    b2[b][0].stride = HD;
                    b2[b][0].f = fr;
                    b2[b][1].kind = 2;
                    b2[b][1].ext_r = (const uint16_t*) (set[b] + at[1]);
                    b2[b][1].ring_w = set[b] + at[2];
                    b2[b][1].backup = bak ? set[b] + at[3] : nullptr;
                    b2[b][1].p0 = p0;
                    b2[b][1].n = W;
                    b2[b][1].T = T;
                    b2[b][1].d = HD;
                    sc[b].rows = (uint16_t*) (set[b] + at[6]);
                    sc[b].max_t = kAttnScratchT;
                    sc[b].cap = S;
                    ok = ok && sparse_attn_sel_op(set[b] + at[4], (const int*) (set[b] + at[5]), S, ar, HD, T, kKvFp4, 0, &sc[b], u[b]);
                }
                // set 0: the =2 launch, then sparse_attn's unpack; set 1: the =3 launch
                return ok && finish_multi(b2[0], 2, d.st) && unpack_sel_ref(u[0], d.st) && finish_multi_sel(b2[1], 2, u[1], d.st);
            };
            std::string why;
            const std::string what = "layer " + std::to_string(l.il) + ", " + std::to_string(T) + " rows, " + std::to_string(S) +
                                     " selection slots" + (bak ? ", the ring's backup" : "");
            if (!trim_run(d, what, hin, set_bytes, regions, enqueue, why)) {
                err = "DS4_ATTN_MERGE=3 check on CUDA" + std::to_string(d.id) + ": " + why;
                std::fprintf(stderr, "ds4: CUDA%d DS4_ATTN_MERGE=3 check FAILED: %s\n", d.id, why.c_str());
                return false;
            }
            std::fprintf(stderr, "ds4: CUDA%d DS4_ATTN_MERGE=3 check (%d rows): the folded unpack (%s): q, ext, the ring, the "
                                 "scratch rows byte for byte, every guard intact\n", d.id, T, what.c_str());
        }
        return true;
    }
    // DS4_BT_FUSE's check (fusion plan F2), every device with layers (its first and last trunk member layer with heads -
    // their norms, wo_a and head counts), a batch window of T rows (2: two sequences of one row; kWin: eight sequences of 1 to
    // 4 rows) laid out by ma_plan as attn_batch_multi's runs, at positions from 2 to past the window (rows before position 0
    // too); random q low-rank / q / KV / o rows, rings of valid FP8 rows, random packed compressed rows (two caches) and
    // selections (one query with every slot, one with none).  Set 0: attn_batch's unfused launches, in its order - q's norm
    // [+ int8], q's RoPE (finish_rows), the rings into the shared buffer, the KV rows' finish, the new rows into the rings
    // [+ backups], sparse_attn_rows' unpack (=3), the o finish (finish_rows) and gguf mv's own rounding of each wo_a group's
    // T rows (q8_round), then wo_a's GEMVs rounding their own (XK_QO).  Set 1: bt_fin's launches as attn_batch makes them, and
    // wo_a's GEMVs reading the finish's int8 rows (PreQ8 rows T).  Every byte equal (q, q's int8, the shared buffer, the
    // rings, the backups, the scratch rows, o, its int8 rows and scales, wo_a's outputs), every guard intact.  The parts the
    // flags apply: DS4_ATTN_MERGE the two merged launches (=3 with the unpack), DS4_XK_QO the o finish and wo_a.  A refused
    // launch is a failure (the flag asked for it)
    bool bt_fuse_check(std::string& err, int T) {
        constexpr size_t kGuard = 64;
        uint32_t st = 0x2545f491u ^ (uint32_t) (T * 6271);
        auto rnd = [&]() {
            st = st * 1664525u + 1013904223u;
            return (float) (int) (st % 2001u - 1000u) / 250.0f;
        };
        auto rndu = [&]() {
            st = st * 1664525u + 1013904223u;
            return st >> 8;
        };
        const int HD = g.hd, QL = g.q_lora, W = g.win, S = (int) topk_stride(), NR = 4096;
        const size_t rbr = kv_row_bytes(kKvFp8, HD), rb4 = kv_row_bytes(kKvFp4, 512);
        const bool mrg = attn_merge > 0, unp = attn_merge > 2, oq = xk_qo != 0;
        static const int kLen16[8] = {1, 3, 1, 4, 2, 1, 3, 1};   // (kWin rows: runs of 1 .. 4, each <= kAttnScratchT)
        static const int kLen2[2] = {1, 1};
        const int* lens = T == 2 ? kLen2 : kLen16;
        const int nrun = T == 2 ? 2 : 8;
        {
            int sum = 0;
            for (int k = 0; k < nrun; ++k) sum += lens[k];
            if (HD != 512 || rbr % 4 != 0 || rb4 % 4 != 0 || sum != T || T > kWin || W < 1) {
                err = "DS4_BT_FUSE check: head dim " + std::to_string(HD) + " / rows " + std::to_string(T) + " not covered";
                return false;
            }
        }
        for (size_t di = 0; di < devs.size(); ++di) {
            Dev& d = devs[di];
            std::vector<const Layer*> ls;
            for (const Layer& l0 : L)
                if (!l0.mtp)
                    for (int mm = 0; mm < l0.nm; ++mm)
                        if (member(l0, mm).dev == (int) di && member(l0, mm).ahn > 0) ls.push_back(&member(l0, mm));
            if (ls.empty()) continue;
            if (ls.size() > 2) ls = {ls.front(), ls.back()};
            if (cudaSetDevice(d.id) != cudaSuccess) {
                (void) cudaGetLastError();
                err = "DS4_BT_FUSE check on CUDA" + std::to_string(d.id) + ": cudaSetDevice failed";
                return false;
            }
            int runs = 0;
            for (const Layer* lp : ls)
                for (int v = 0; v < 2; ++v) {   // (v 1: q's int8 rows and the rings' backups too)
                    const Layer& l = *lp;
                    const int NHL = l.ahn, HQ = NHL * HD, OG = l.ogn;
                    const bool q8 = v == 1, bak = v == 1;
                    const bool ofit = oq && OG > 0 && HQ % OG == 0 && (HQ / OG) % 32 == 0;
                    const int per = ofit ? HQ / OG : 0;
                    const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
                    // the window: run k sequence k, its rows, its position
                    int rseq[kWin];
                    int64_t rpos[kWin];
                    const long long p0s[8] = {5, 1000 + l.il, 37, 2, 300, (long long) W + 1, 64, 7};
                    for (int k = 0, t = 0; k < nrun; ++k)
                        for (int i = 0; i < lens[k]; ++i, ++t) {
                            rseq[t] = k;
                            rpos[t] = p0s[k] + i;
                        }
                    MaPlan mp;
                    if (!ma_plan(rseq, rpos, T, W, false, mp) || mp.nrun != nrun) {
                        err = "DS4_BT_FUSE check: the window's plan";
                        return false;
                    }
                    // a set: 0 qr | 1 qr int8 | 2 qr scales | 3 q | 4 the shared buffer | 5 kvr | 6 rings | 7 backups | 8 ckv |
                    // 9 sel | 10 scratch rows | 11 o | 12 o int8 | 13 o scales | 14 wo_a's outputs
                    const size_t rb[15] = {(size_t) T * QL * 4, (size_t) T * QL, (size_t) T * QL / 32 * 4, (size_t) T * HQ * 4,
                                           (size_t) mp.rows * HD * 2, (size_t) T * HD * 4, (size_t) nrun * W * rbr, (size_t) T * rbr,
                                           (size_t) NR * rb4, (size_t) T * S * 4, (size_t) T * S * 512 * 2, (size_t) T * HQ * 4,
                                           (size_t) T * HQ, (size_t) T * HQ / 32 * 4, (size_t) T * OG * g.o_lora * 4};
                    size_t at[15], set_bytes = 0;
                    std::vector<std::pair<size_t, size_t>> regions;
                    for (int r = 0; r < 15; ++r) {
                        at[r] = set_bytes + kGuard;
                        set_bytes = (at[r] + rb[r] + 255) / 256 * 256;
                        regions.push_back({at[r], rb[r]});
                    }
                    set_bytes += kGuard;
                    // inputs, as floats / bytes: qr | q | kvr | o | rings | ckv | sel
                    const size_t iqr = 0, iq = iqr + rb[0] / 4, ikv = iq + rb[3] / 4, io = ikv + rb[5] / 4, iring = io + rb[11] / 4,
                                 ickv = iring + rb[6] / 4, isel = ickv + rb[8] / 4, in_n = isel + rb[9] / 4;
                    std::vector<float> hin(in_n);
                    for (size_t i = 0; i < iring; ++i) hin[i] = rnd();
                    {
                        std::vector<uint8_t> ring(rb[6]);
                        for (size_t r = 0; r < (size_t) nrun * W; ++r) {
                            uint8_t* row = ring.data() + r * rbr;
                            for (int e = 0; e < HD; ++e) row[e] = (uint8_t) ((rndu() % 0x7e) | ((rndu() & 1u) << 7));   // (no NaN code)
                            for (int b = 0; b < HD / 32; ++b) row[HD + b] = (uint8_t) (120 + rndu() % 15);
                        }
                        std::memcpy(hin.data() + iring, ring.data(), rb[6]);
                        std::vector<uint8_t> ckv(rb[8]);
                        for (int r = 0; r < NR; ++r) {
                            uint8_t* row = ckv.data() + (size_t) r * rb4;
                            for (int e = 0; e < 256; ++e) row[e] = (uint8_t) rndu();                                    // (E2M1 codes)
                            for (int b = 0; b < 32; ++b) row[256 + b] = (uint8_t) ((rndu() % 0x7e) | ((rndu() & 1u) << 7));   // (E4M3)
                        }
                        std::memcpy(hin.data() + ickv, ckv.data(), rb[8]);
                        std::vector<int> sel((size_t) T * S);
                        for (auto& x : sel) x = (int) (rndu() % (uint32_t) (NR / 2));   // (each of the two caches' rows)
                        std::memcpy(hin.data() + isel, sel.data(), rb[9]);
                    }
                    AttnRows ua;   // (the unpack's rows: attn_batch_multi's window rows, random selection counts)
                    for (int t = 0; t < T; ++t) {
                        ua.win0[t] = mp.win0[t];
                        ua.nwin[t] = mp.nwin[t];
                        ua.nsel[t] = t == 0 ? S : (t == 1 ? 0 : (int) (rndu() % (uint32_t) (S + 1)));
                    }
                    auto enqueue = [&](float* in, uint8_t* s0, uint8_t* s1) {
                        uint8_t* set[2] = {s0, s1};
                        const uint8_t* ib = (const uint8_t*) in;
                        bool ok = true;
                        for (int b = 0; b < 2; ++b)
                            ok = ok && cudaMemcpyAsync(set[b] + at[0], ib + iqr * 4, rb[0], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[3], ib + iq * 4, rb[3], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[5], ib + ikv * 4, rb[5], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[11], ib + io * 4, rb[11], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[6], ib + iring * 4, rb[6], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[8], ib + ickv * 4, rb[8], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess &&
                                 cudaMemcpyAsync(set[b] + at[9], ib + isel * 4, rb[9], cudaMemcpyDeviceToDevice, d.st) == cudaSuccess;
                        auto F = [&](int b, int r) { return (float*) (set[b] + at[r]); };
                        auto E = [&](int b) { return (uint16_t*) (set[b] + at[4]); };
                        Finish fq[2], fk[2], fr, fo;
                        RingRuns rr[2];
                        AttnCkv ck[2];
                        AttnScratch sc[2];
                        for (int b = 0; b < 2; ++b) {
                            fq[b].w = l.q_norm;
                            fq[b].eps = g.eps;
                            if (q8) {
                                fq[b].q8 = (int8_t*) (set[b] + at[1]);
                                fq[b].q8d = F(b, 2);
                            }
                            fk[b].w = l.kv_norm;
                            fk[b].eps = g.eps;
                            fk[b].rd = g.rd;
                            fk[b].freqs = freqs;
                            fk[b].quant = 1;
                            fk[b].dst = E(b);
                            fk[b].dst_stride = HD;
                            rr[b].runs = mp.nrun;
                            for (int k = 0; k < mp.nrun; ++k) {
                                const MaRun& u = mp.run[k];
                                rr[b].ring[k] = set[b] + at[6] + (size_t) k * W * rbr;
                                rr[b].bak[k] = bak ? set[b] + at[7] + (size_t) u.r0 * rbr : nullptr;
                                rr[b].p0[k] = (long long) u.p0;
                                rr[b].e0[k] = u.e0;
                                rr[b].T[k] = u.n;
                                for (int i = 0; i < u.n; ++i) ck[b].ckv[u.r0 + i] = set[b] + at[8] + (size_t) (k % 2) * (NR / 2) * rb4;
                            }
                            sc[b].rows = (uint16_t*) (set[b] + at[10]);
                            sc[b].max_t = kWin;
                            sc[b].cap = S;
                        }
                        fr.rd = g.rd;
                        fr.vpp = NHL;
                        fr.freqs = freqs;
                        fo.rd = g.rd;
                        fo.vpp = NHL;
                        fo.freqs = freqs;
                        fo.inverse = 1;
                        fo.quant = 1;
                        FinishRows fp, fkr;
                        for (int t = 0; t < T; ++t) {
                            fp.pos[t] = mp.pos[t];
                            fkr.pos[t] = mp.pos[t];
                            fkr.dst[t] = mp.dst[t];
                        }
                        std::string e2;
                        x3::MvJob j[2][16];
                        for (int b = 0; b < 2 && ofit; ++b)
                            for (int gi = 0; gi < OG; ++gi)
                                j[b][gi] = job(l.wo_a[gi], F(b, 11) + (size_t) gi * per, F(b, 14) + (size_t) gi * g.o_lora, T, HQ,
                                               (size_t) OG * g.o_lora);
                        // set 0: attn_batch's unfused launches, in its order
                        if (mrg) {
                            finish(F(0, 0), T, QL, QL, fq[0], d.st);
                            ok = ok && finish_rows(F(0, 3), T * NHL, HD, HD, fr, fp, d.st);
                            ring_to_ext_runs(rr[0], E(0), W, HD, d.st);
                            ok = ok && finish_rows(F(0, 5), T, HD, HD, fk[0], fkr, d.st);
                            ext_to_ring_runs(rr[0], E(0), W, HD, d.st);
                        }
                        if (unp) ok = ok && unpack_sel_rows_ref(ck[0], (const int*) (set[0] + at[9]), S, ua, T, &sc[0], d.st);
                        if (ofit) {
                            ok = ok && finish_rows(F(0, 11), T * NHL, HD, HD, fo, fp, d.st);
                            for (int gi = 0; gi < OG; ++gi)
                                for (int t = 0; t < T; ++t)
                                    gg::q8_round(F(0, 11) + (size_t) t * HQ + (size_t) gi * per, 1, per,
                                                 (int8_t*) (set[0] + at[12]) + ((size_t) gi * T + t) * per,
                                                 F(0, 13) + ((size_t) gi * T + t) * (per / 32), d.st);
                            ok = ok && mv_n(d, j[0], OG, e2);
                        }
                        // set 1: bt_fin's launches, as attn_batch makes them
                        if (mrg) {
                            BtFin m1, m2;
                            m1.seg[0].kind = 0;
                            m1.seg[0].x = F(1, 0);
                            m1.seg[0].n_vec = T;
                            m1.seg[0].len = QL;
                            m1.seg[0].stride = QL;
                            m1.seg[0].f = fq[1];
                            m1.seg[1].kind = 1;
                            m1.seg[1].x = F(1, 5);
                            m1.seg[1].n_vec = T;
                            m1.seg[1].len = HD;
                            m1.seg[1].stride = HD;
                            m1.seg[1].f = fk[1];
                            m1.nseg = 2;
                            m1.fr = fkr;
                            m1.ring = 2;
                            m1.rr = rr[1];
                            m1.ext = E(1);
                            m1.n = W;
                            m1.d = HD;
                            m2.seg[0].kind = 1;
                            m2.seg[0].x = F(1, 3);
                            m2.seg[0].n_vec = T * NHL;
                            m2.seg[0].len = HD;
                            m2.seg[0].stride = HD;
                            m2.seg[0].f = fr;
                            m2.nseg = 1;
                            m2.fr = fp;
                            m2.ring = 3;
                            m2.rr = rr[1];
                            m2.ext = E(1);
                            m2.n = W;
                            m2.d = HD;
                            if (unp) {
                                m2.unpack = true;
                                m2.uc = ck[1];
                                m2.sel = (const int*) (set[1] + at[9]);
                                m2.sel_stride = S;
                                m2.cap = S;
                                m2.out = sc[1].rows;
                                m2.ut = T;
                                m2.ua = ua;
                            }
                            ok = ok && bt_fin(m1, d.st) && bt_fin(m2, d.st);
                        }
                        if (ofit) {
                            BtFin mo;
                            mo.seg[0].kind = 1;
                            mo.seg[0].x = F(1, 11);
                            mo.seg[0].n_vec = T * NHL;
                            mo.seg[0].len = HD;
                            mo.seg[0].stride = HD;
                            mo.seg[0].f = fo;
                            mo.seg[0].f.q8 = (int8_t*) (set[1] + at[12]);
                            mo.seg[0].f.q8d = F(1, 13);
                            mo.seg[0].q8_per = per;
                            mo.seg[0].q8_rows = T;
                            mo.nseg = 1;
                            mo.fr = fp;
                            gg::PreQ8 po;
                            po.x = F(1, 11);
                            po.q = (const int8_t*) (set[1] + at[12]);
                            po.d = F(1, 13);
                            po.k = per;
                            po.rows = T;
                            po.nslice = OG;
                            po.slice = (size_t) per;
                            po.xcs = (size_t) HQ;
                            ok = ok && bt_fin(mo, d.st) && mv_n(d, j[1], OG, e2, &po);
                        }
                        return ok;
                    };
                    std::string why;
                    const std::string what = "layer " + std::to_string(l.il) + ", " + std::to_string(T) + " rows in " +
                                             std::to_string(nrun) + " runs" + (q8 ? ", q's int8, the rings' backups" : "") +
                                             (mrg ? ", the merged launches" : "") + (unp ? " with the unpack" : "") +
                                             (ofit ? ", the o finish's int8 rows and wo_a (" + std::to_string(OG) + " groups)" : "");
                    if (!mrg && !ofit) continue;   // (XK_QO on a layer whose heads do not split into 32-blocks of groups: never fused)
                    if (!trim_run(d, what, hin, set_bytes, regions, enqueue, why)) {
                        err = "DS4_BT_FUSE check on CUDA" + std::to_string(d.id) + ": " + why;
                        std::fprintf(stderr, "ds4: CUDA%d DS4_BT_FUSE check FAILED: %s\n", d.id, why.c_str());
                        return false;
                    }
                    ++runs;
                    if (v == 1)
                        std::fprintf(stderr, "ds4: CUDA%d DS4_BT_FUSE check (%d rows): %s - byte for byte, every guard intact\n",
                                     d.id, T, what.c_str());
                }
            std::fprintf(stderr, "ds4: CUDA%d DS4_BT_FUSE check (%d rows): %d runs passed\n", d.id, T, runs);
        }
        return true;
    }

    // ---- the DSpark drafter (DeepSeek's DSparkBlock / forward_spec).  Its blocks' rings hold the trunk's main KV:
    // seed() turns a window's taps (the streams' mean entering layers 37..39) into it, through main_proj / main_norm
    // and each block's wkv / kv_norm / rope / FP8, for the positions the trunk kept.  draft() runs the block [y, noise x
    // (block - 1)] at positions pos .. through the blocks (each query attending to the ring and to the whole block),
    // the trunk's head, the markov bias token by token (greedy) and the confidence head.
    bool seed_drafter(int64_t p0, int n, int row0, std::string& err) {
        if (g.n_mtp == 0 || n <= 0 || o.dspark_noseed) return true;   // (DS4_DSPARK_NOSEED: never drafts)
        if (n > kWin * kPicks) {
            err = "seeding the drafter with " + std::to_string(n) + " rows";
            return false;
        }
        Dev& d = devs[(size_t) d_dev];
        cudaSetDevice(d.id);
        const int nt = (int) g.d_targets.size(), D = g.dim, HD = g.hd;
        if (dump_d != nullptr) {   // DS4_DSPARK_DUMP: 'S', the first position, the rows, then the taps
            for (Dev& e : devs) {
                cudaSetDevice(e.id);
                CK(cudaStreamSynchronize(e.st));
            }
            cudaSetDevice(d.id);
            const int64_t hdr[4] = {'S', p0, n, (int64_t) nt * D};
            std::fwrite(hdr, 8, 4, dump_d);
            std::fwrite(h_taps + (size_t) row0 * nt * D, 4, (size_t) n * nt * D, dump_d);
            std::fflush(dump_d);
        }
        for (int a = 0; a < n; a += kWin) {   // (a chunk's last 128 rows: 16 a GEMV)
            const int na = std::min(kWin, n - a);
            CK(cudaMemcpyAsync(d.xe, h_taps + (size_t) (row0 + a) * nt * D, (size_t) na * nt * D * 4,
                               cudaMemcpyHostToDevice, d.st));
            if (!mv(d, {job(d_main_proj, d.xe, d.ed + (size_t) a * D, na, (size_t) nt * D, D)}, err)) return false;
        }
        CK(cudaEventRecord(ev_seed, d.st));
        Finish fm;
        fm.w = d_main_norm;
        fm.eps = g.eps;
        finish(d.ed, n, D, D, fm, d.st);
        for (int i = 0; i < g.n_mtp; ++i) {
            Layer& l = L[(size_t) (g.nl + i)];
            if (l.dev != d_dev) {
                err = "the DSpark blocks are split across devices";
                return false;
            }
            for (int a = 0; a < n; a += kWin) {
                const int na = std::min(kWin, n - a);
                if (!mv(d, {job(l.wkv, d.ed + (size_t) a * D, d.kvr, na, D, HD)}, err)) return false;
                Finish fk;
                fk.w = l.kv_norm;
                fk.eps = g.eps;
                fk.rd = g.rd;
                fk.pos = (int) (p0 + a);
                fk.freqs = d.freqs_win;
                fk.quant = 1;
                fk.dst = d.ext + (size_t) g.win * HD;
                fk.dst_stride = HD;
                finish(d.kvr, na, HD, HD, fk, d.st);
                ext_to_ring(d.ext, l.win, p0 + a, g.win, na, HD, d.st);
            }
        }
        if (draft_tp) {   // DS4_DRAFT_TP: every block's whole ring, the lead's, to each member's (through h_dring)
            const Layer& l0 = L[(size_t) g.nl];
            const size_t rb = (size_t) g.win * win_rb();
            for (int m = 1; m < l0.nm; ++m)   // (the members' copies of the last seeding read h_dring first)
                CK(cudaStreamWaitEvent(d.st, ev_dring_in[(size_t) m], 0));
            for (int i = 0; i < g.n_mtp; ++i)
                CK(cudaMemcpyAsync(h_dring + (size_t) i * rb, L[(size_t) (g.nl + i)].win, rb, cudaMemcpyDeviceToHost, d.st));
            CK(cudaEventRecord(ev_dring, d.st));
            for (int m = 1; m < l0.nm; ++m) {
                Dev& e = devs[(size_t) member(l0, m).dev];
                cudaSetDevice(e.id);
                CK(cudaStreamWaitEvent(e.st, ev_dring, 0));
                for (int i = 0; i < g.n_mtp; ++i)
                    CK(cudaMemcpyAsync(member(L[(size_t) (g.nl + i)], m).win, h_dring + (size_t) i * rb, rb,
                                       cudaMemcpyHostToDevice, e.st));
                CK(cudaEventRecord(ev_dring_in[(size_t) m], e.st));
            }
            cudaSetDevice(d.id);
        }
        return true;
    }

    bool draft(int y, std::vector<int>& out, std::vector<float>& conf, std::string& err, float temperature, float top_p,
               int top_k, float min_p, uint64_t seed, uint64_t counter) {
        const double t0 = now_ms();
        drafts_q = temperature > 0.0f && sample_drafts;
        dq_temp = temperature;
        dq_top_p = top_p;
        dq_top_k = top_k;
        dq_min_p = min_p;
        dq_seed = seed;
        dq_counter = counter;
        const bool ok = draft_(y, out, conf, err);
        if (!ok) drafts_q = false;
        if (max_drafts > 0 && (int) out.size() > max_drafts) {
            out.resize((size_t) max_drafts);
            conf.resize((size_t) max_drafts);
        }
        st.draft_ms += now_ms() - t0;
        ++st.drafts_rounds;
        return ok;
    }
    // the drafter's blocks for the window, as member m of their group (m 0: the lead, whose input draft_ embedded; a
    // member, DS4_DRAFT_TP: its own copy of the input first - the same rows - then its share of each block)
    bool draft_blocks(int m, int64_t p0, int T, const WinPlan& dp, std::string& err) {
        const int D = g.dim, H = g.hc;
        const Layer& l0 = L[(size_t) g.nl];
        Dev& d = devs[(size_t) member(l0, m).dev];
        cudaSetDevice(d.id);
        if (m > 0) {
            CK(emb_upload(d.emb_rows, h_emb, (size_t) T * D * 2, d.st));
            embed(d.emb_rows, T, d.h, D, H, d.st);
            init_pre(d.pre, T, d.st);
        }
        const size_t hs = (size_t) T * H * D, rs = (size_t) g.win * g.hd;
        for (int i = 0; i < g.n_mtp; ++i) {
            Layer& l = L[(size_t) (g.nl + i)];
            if (m == 0 && dump_d != nullptr) {   // (stream order: the ring the block reads - as BF16 rows - the stream it leaves)
                ring_to_ext(l.win, d.ext, g.win, g.win, g.hd, d.st);
                CK(cudaMemcpyAsync(h_dump_ring + (size_t) i * rs, d.ext, rs * 2, cudaMemcpyDeviceToHost, d.st));
            }
            if (!layer(l, m, p0, T, dp, err)) return false;
            if (m == 0 && dump_d != nullptr) {
                cudaSetDevice(d.id);
                CK(cudaMemcpyAsync(h_dump + (size_t) i * hs, d.h, hs * 4, cudaMemcpyDeviceToHost, d.st));
            }
        }
        return true;
    }
    bool draft_(int y, std::vector<int>& out, std::vector<float>& conf, std::string& err) {
        out.clear();
        conf.clear();
        const int T = g.d_block, D = g.dim, H = g.hc, V = g.vocab, R = g.d_rank;
        const int64_t p0 = pos;
        if (g.n_mtp == 0 || o.dspark_noseed || T < 1 || T > kWin || p0 + T > o.max_context) return true;   // (DS4_DSPARK_NOSEED: no drafts)
        int tk[kWin];
        tk[0] = y;
        for (int t = 1; t < T; ++t) tk[t] = g.d_noise;
        Dev& d = devs[(size_t) d_dev];
        cudaSetDevice(d.id);
        for (int t = 0; t < T; ++t) std::memcpy(h_emb + (size_t) t * D, embed_pinned + (size_t) tk[t] * D, (size_t) D * 2);
        CK(emb_upload(d.emb_rows, h_emb, (size_t) T * D * 2, d.st));
        embed(d.emb_rows, T, d.h, D, H, d.st);
        if (ds4_dbg("DS4_DBG_EMB")) {
            ds4_metal_flush();
            float *hp = d.h;
            float hh[4] = {0,0,0,0};
            cudaMemcpy(hh, hp, sizeof(hh), cudaMemcpyDeviceToHost);
            std::fprintf(stderr, "DBG at embed site %d: h[0..3] = %g %g %g %g\n", __LINE__, hh[0], hh[1], hh[2], hh[3]);
        }
        if (ds4_dbg("DS4_DBG_EMB")) {
            ds4_metal_flush();
            float hh[4] = {0, 0, 0, 0};
            cudaMemcpy(hh, d.h, sizeof(hh), cudaMemcpyDeviceToHost);
            std::fprintf(stderr, "DBG after embed: h[0..3] = %g %g %g %g\n", hh[0], hh[1], hh[2], hh[3]);
        }
        init_pre(d.pre, T, d.st);
        WinPlan dp;   // (window attention alone: the mailbox seqs)
        dp.async = draft_tp || (!sync_decode && T <= async_max_t);   // (a tensor-parallel block: the device-routed path)
        for (int i = 0; i < g.n_mtp && dp.async; ++i) {
            const int il = g.nl + i;
            dp.seq[il] = ++seq_issued;
            layer_of[dp.seq[il] % kRing].store(il, std::memory_order_release);
        }
        const size_t hs = (size_t) T * H * D, rs = (size_t) g.win * g.hd;
        if (dump_d != nullptr && h_dump == nullptr &&
            (!halloc(h_dump, (size_t) g.n_mtp * kWin * H * D, err) || !halloc(h_dump_ring, (size_t) g.n_mtp * rs, err)))
            return false;
        if (!draft_tp) {
            if (!draft_blocks(0, p0, T, dp, err)) return false;
        } else {   // DS4_DRAFT_TP: each member's share of the blocks on its own thread, as forward_par runs the trunk's
            if (dr_jobs.empty()) {
                const int nm = L[(size_t) g.nl].nm;
                dr_errs.assign((size_t) nm, std::string());
                dr_bad.assign((size_t) nm, 0);
                for (int m = 0; m < nm; ++m) {
                    dr_errs[(size_t) m].reserve(256);
                    dr_jobs.push_back([this, m] {
                        std::string& e = dr_errs[(size_t) m];
                        e.clear();
                        if (!draft_blocks(m, dr_p0, dr_T, *dr_wp, e)) {
                            dr_bad[(size_t) m] = 1;
                            if (e.empty()) e = "a drafter member's thread failed";
                        }
                    });
                }
            }
            if (workers.size() != devs.size()) {
                err = "the drafter's tensor-parallel blocks without the decode's threads";
                return false;
            }
            dr_p0 = p0;
            dr_T = T;
            dr_wp = &dp;
            const Layer& l0 = L[(size_t) g.nl];
            std::fill(dr_bad.begin(), dr_bad.end(), (char) 0);
            for (int m = 0; m < l0.nm; ++m) workers[(size_t) member(l0, m).dev]->submit(std::ref(dr_jobs[(size_t) m]));
            for (int m = 0; m < l0.nm; ++m) workers[(size_t) member(l0, m).dev]->wait();
            dr_wp = nullptr;
            for (int m = 0; m < l0.nm; ++m)
                if (dr_bad[(size_t) m]) {
                    err = dr_errs[(size_t) m];
                    return false;
                }
        }
        cudaSetDevice(d.id);
        hc_pre_norm(d.h, d.pre, nullptr, D, H, T, g.eps, d.x, d.st);   // (the confidence head reads it before the norm)
        Dev& hd = devs[(size_t) head_dev];
        // (through the host to the head's device, and to the head group's other members - the drafter's device can be
        // the head group's lead itself, a group of every GPU)
        if (d_dev != head_dev || groups[(size_t) hd.grp].mem.size() > 1) {
            CK(cudaMemcpyAsync(d.bounce, d.x, (size_t) T * D * 4, cudaMemcpyDeviceToHost, d.st));
            CK(cudaEventRecord(d.ev_out, d.st));
        }
        if (d_dev != head_dev) {
            cudaSetDevice(hd.id);
            CK(cudaStreamWaitEvent(hd.st, d.ev_out, 0));
            CK(cudaMemcpyAsync(hd.x, d.bounce, (size_t) T * D * 4, cudaMemcpyHostToDevice, hd.st));
        }
        // the drafter's final norm and the trunk's head, on every member of the head group (the others' shares first)
        const std::vector<int>& hg = groups[(size_t) hd.grp].mem;
        const bool mk = mk_split && !drafts_q;   // (sampled drafts: the lead's whole rows, gathered)
        for (int m = (int) hg.size() - 1; m >= 0; --m) {
            Dev& e = devs[(size_t) hg[(size_t) m]];
            cudaSetDevice(e.id);
            if (m > 0) {
                CK(cudaStreamWaitEvent(e.st, d.ev_out, 0));
                CK(cudaMemcpyAsync(e.ao, d.bounce, (size_t) T * D * 4, cudaMemcpyHostToDevice, e.st));
            } else
                CK(cudaMemcpyAsync(e.ao, e.x, (size_t) T * D * 4, cudaMemcpyDeviceToDevice, e.st));
            Finish fn;
            fn.w = e.d_norm;
            fn.eps = g.eps;
            finish(e.ao, T, D, D, fn, e.st);
            if (!head_share(e, m, e.ao, T, err, !mk)) return false;
        }
        h_idx[0] = y;
        if (mk) {
            // the markov steps over the group: each member its rows of the bias and its share's argmax, every member
            // then the global one (the sampler's tie rule) and its E row - the same drafts as the lead's whole rows,
            // each step ~1/nm of their 66 MB and no gather of the shares
            const int nm = (int) hg.size();
            const unsigned seq = ++mk_seq;
            for (int m = 0; m < nm; ++m) {
                Dev& e = devs[(size_t) hg[(size_t) m]];
                cudaSetDevice(e.id);
                CK(cudaMemcpyAsync(e.mk_ints, h_idx, 4, cudaMemcpyHostToDevice, e.st));
                CK(cudaMemcpyAsync(e.mk_erow, h_mk_embed + (size_t) y * R, (size_t) R * 2, cudaMemcpyHostToDevice, e.st));
            }
            for (int i = 0; i < T; ++i)
                for (int m = 0; m < nm; ++m) {
                    Dev& e = devs[(size_t) hg[(size_t) m]];
                    cudaSetDevice(e.id);
                    float* row = m == 0 ? hd.logits + (size_t) i * V : e.logits_part + (size_t) i * e.mk_vn;
                    markov_share(row, e.mk_share, e.mk_erow, e.mk_vn, R, e.st);
                    argmax_share(row, e.mk_vn, e.mk_v0, mk_slots + ((size_t) i * nm + m) * 4, seq, e.st);
                    markov_pick(mk_slots + (size_t) i * nm * 4, nm, seq, e.mk_ints + i + 1, h_mk_embed, e.mk_erow, R,
                                e.st);
                }
            cudaSetDevice(hd.id);
        } else {
            CK(cudaMemcpyAsync(d_ints, h_idx, 4, cudaMemcpyHostToDevice, hd.st));
            strata::dsv41k::SamplerParams sp;
            sp.greedy = true;
            sp.temperature = 0.0f;
            if (drafts_q) {   // the request's own chain: draft i drawn as the model's token i would be (verify's counter + i)
                sp.greedy = false;
                sp.temperature = dq_temp * (q_temp_scale > 0.0f ? q_temp_scale : 1.0f);
                sp.top_p = dq_top_p;
                sp.top_k = dq_top_k;
                sp.min_p = dq_min_p;
                sp.seed = dq_seed;
            }
            for (int i = 0; i < T; ++i) {   // the markov bias of the token before, then that position's draft
                if (d_mk_head_q8 != nullptr) markov_add_q8(hd.logits + (size_t) i * V, d_mk_embed, d_mk_head_q8, d_ints + i, V, R, hd.st);
                else markov_add(hd.logits + (size_t) i * V, d_mk_embed, d_mk_head, d_ints + i, V, R, hd.st);
                if (drafts_q) {
                    sp.counter = dq_counter + (uint64_t) i;
                    strata::dsv41k::sample_draft(hd.logits + (size_t) i * V, 1, V, sp, d_specq + i, d_ints + i + 1, hd.st);
                } else
                    strata::dsv41k::sample_tokens(hd.logits + (size_t) i * V, 1, V, nullptr, 0, sp, d_ints + i + 1, hd.st);
            }
        }
        confidence(hd.x, d_mk_embed, d_ints, d_conf, T, D, R, d_confv, hd.st);
        int tok[kWin + 1];
        float cf[kWin];
#if defined(STRATA_METAL)
        ds4_metal_flush();   // (a host read of a device result: commit the batched dispatches first)
#endif
        CK(cudaMemcpyAsync(h_idx, d_ints, (size_t) (T + 1) * 4, cudaMemcpyDeviceToHost, hd.st));
        CK(cudaMemcpyAsync(h_w, d_confv, (size_t) T * 4, cudaMemcpyDeviceToHost, hd.st));
        CK(cudaStreamSynchronize(hd.st));
        for (int i = 0; i <= T; ++i) tok[i] = h_idx[i];
        for (int i = 0; i < T; ++i) cf[i] = h_w[i];
        if (dump_d != nullptr) {   // 'D', the block's position, y, T, then the drafts, their confidences, the hidden
            std::vector<float> xs((size_t) T * D);   // rows before the final norm; then each block's ring and stream
            CK(cudaMemcpy(xs.data(), hd.x, xs.size() * 4, cudaMemcpyDeviceToHost));
            cudaSetDevice(d.id);
            CK(cudaStreamSynchronize(d.st));
            const int64_t hdr[4] = {'D', p0, y, T};
            std::fwrite(hdr, 8, 4, dump_d);
            std::fwrite(tok + 1, 4, (size_t) T, dump_d);
            std::fwrite(cf, 4, (size_t) T, dump_d);
            std::fwrite(xs.data(), 4, xs.size(), dump_d);
            for (int i = 0; i < g.n_mtp; ++i) {
                std::fwrite(h_dump_ring + (size_t) i * rs, 2, rs, dump_d);
                std::fwrite(h_dump + (size_t) i * hs, 4, hs, dump_d);
            }
            std::fflush(dump_d);
            cudaSetDevice(hd.id);
        }
        for (int i = 0; i < T; ++i) {
            out.push_back(tok[i + 1]);
            conf.push_back(cf[i]);
        }
        return true;
    }

    // the token sample_tokens left in d.tok; -1 on a CUDA error, printed here (the callers reject a -1).
    // (Project Maya 2040174, #619: the copy's and the sync's errors were unchecked, so a token -1 could reach the client)
    int tok_back(Dev& d) {
        int t = -1;
#if defined(STRATA_METAL)
        ds4_metal_flush();   // (a host read of a device result: commit the batched dispatches first)
#endif
        cudaError_t e = cudaMemcpyAsync(&t, d.tok, 4, cudaMemcpyDeviceToHost, d.st);
        if (e == cudaSuccess) e = cudaStreamSynchronize(d.st);
        if (e == cudaSuccess) return t;
        std::fprintf(stderr, "ds4 sample: %s\n", cudaGetErrorString(e));
        return -1;
    }

    int sample_row(int row, float temperature, float top_p, int top_k, float min_p, uint64_t seed, uint64_t counter,
                   const float* bias) {
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        strata::dsv41k::SamplerParams sp;
        sp.temperature = temperature;
        sp.greedy = temperature <= 0.0f;
        sp.top_p = top_p;
        sp.top_k = top_k;
        sp.min_p = min_p;
        sp.seed = seed;
        sp.counter = counter;
        sp.logit_bias = bias;
        strata::dsv41k::sample_tokens(d.logits + (size_t) row * g.vocab, 1, g.vocab, nullptr, 0, sp, d.tok, d.st);
        return tok_back(d);
    }

    // [y, drafts] at positions pos ..: the trunk's verdict, its next token, and the state back to what it kept.
    // Greedy: the drafts the trunk's argmax agrees with.  Sampled: the speculative-sampling rule over the request's own
    // chain (top_k, top_p, min_p, temperature): draft d stands with probability min(1, p(d) / q(d)), q the distribution
    // it was drawn from (the drafter's argmax: a point at d, so p(d)), a rejected one is replaced by a draw from the
    // residual max(0, p - q) - so each kept token is distributed as the trunk's own draw.
    bool verify(int y, const std::vector<int>& drafts, float temperature, float top_p, int top_k, float min_p,
                uint64_t seed, uint64_t counter, int& accepted, int& next, std::string& err) {
        const int n = (int) std::min<size_t>(drafts.size(), (size_t) kWin - 1);
        const int T = n + 1, V = g.vocab;
        const int64_t p0 = pos;
        int tk[kWin];
        tk[0] = y;
        for (int i = 0; i < n; ++i) tk[i + 1] = drafts[(size_t) i];
        spec_win = true;
        const double tv = now_ms();
        const bool ok = forward(tk, T, T, err, 0);
        st.verify_ms += now_ms() - tv;
        spec_win = false;
        if (!ok) return false;
        Dev& hd = devs[(size_t) head_dev];
        cudaSetDevice(hd.id);
        int m = 0;
        if (temperature <= 0.0f) {
            strata::dsv41k::SamplerParams sp;
            sp.greedy = true;
            sp.temperature = 0.0f;
            strata::dsv41k::sample_tokens(hd.logits, T, V, nullptr, 0, sp, d_ints + 16, hd.st);   // (the T rows at once)
#if defined(STRATA_METAL)
        ds4_metal_flush();   // (a host read of a device result: commit the batched dispatches first)
#endif
            CK(cudaMemcpyAsync(h_idx, d_ints + 16, (size_t) T * 4, cudaMemcpyDeviceToHost, hd.st));
            CK(cudaStreamSynchronize(hd.st));
            while (m < n && h_idx[m] == drafts[(size_t) m]) ++m;
            next = h_idx[m];
        } else {
            // row i keeps draft i with probability min(1, p(d) / q(d)), else draws from the residual max(0, p - q)
            // (never d itself): each row a token distributed as the model's own draw at that position, p through the
            // request's chain - the top_k / top_p / min_p cut included (the drafter's argmax can lie outside it: p(d) 0,
            // never kept); past the first rejection the rows do not count
            const bool own = drafts_q && dq_temp == temperature && dq_top_p == top_p && dq_top_k == top_k &&
                             dq_min_p == min_p && dq_seed == seed && dq_counter == counter;
            if (!own) {   // the drafter's argmax: q a point at each draft
                for (int i = 0; i < n; ++i) {
                    h_specq[(size_t) i].n = 1;
                    h_specq[(size_t) i].ids[0] = drafts[(size_t) i];
                    h_specq[(size_t) i].p[0] = 1.0;
                }
                CK(cudaMemcpyAsync(d_specq, h_specq.data(), (size_t) n * sizeof(strata::dsv41k::SpecList),
                                   cudaMemcpyHostToDevice, hd.st));
            }
            for (int i = 0; i < n; ++i) h_idx[i] = drafts[(size_t) i];
            CK(cudaMemcpyAsync(d_ints + 32, h_idx, (size_t) n * 4, cudaMemcpyHostToDevice, hd.st));
            strata::dsv41k::SamplerParams sp;
            sp.greedy = false;
            sp.temperature = temperature;
            sp.top_p = top_p;
            sp.top_k = top_k;
            sp.min_p = min_p;
            sp.seed = seed;
            sp.counter = counter;
            strata::dsv41k::sample_verify(hd.logits, n, V, sp, d_specq, d_ints + 32, d_ints + 16, hd.st);
#if defined(STRATA_METAL)
        ds4_metal_flush();   // (a host read of a device result: commit the batched dispatches first)
#endif
            CK(cudaMemcpyAsync(h_idx, d_ints + 16, (size_t) n * 4, cudaMemcpyDeviceToHost, hd.st));
            CK(cudaStreamSynchronize(hd.st));
            while (m < n && h_idx[m] == drafts[(size_t) m]) ++m;
            next = m < n ? h_idx[m] : sample_row(n, temperature, top_p, top_k, min_p, seed, counter + (uint64_t) n, nullptr);
        }
        drafts_q = false;
        rollback(p0, T, m + 1);
        if (!seed_drafter(p0, m + 1, 0, err)) return false;
        accepted = m;
        st.drafts_offered += n;
        st.drafts_accepted += m;
        for (int i = 0; i < n && i <= m && i < 8; ++i) {
            ++st.draft_reached[i];
            if (i < m) ++st.draft_kept[i];
        }
        return true;
    }

    // a verified window keeps its first `keep` positions: the ring rows and the compressors' state of the rest undone
    // (the compressed KV and the index keys past them are written again when those positions come)
    std::vector<RingBatch> rb_scratch;   // rollback's batches, kept (a verify round's: no allocation in it)
    void rollback(int64_t p0, int T, int keep) {
        if (keep >= T) return;
        // the ring rows: one launch a device for all its layers (a launch a layer and member was ~300 on 8-way tensor
        // parallel, a millisecond of the host's before the next draft)
        std::vector<RingBatch>& rb = rb_scratch;
        rb.assign(devs.size(), RingBatch{});
        for (int il = 0; il < g.nl; ++il)
            for (int m = 0; m < L[(size_t) il].nm; ++m) {
                Layer& l = member(L[(size_t) il], m);
                RingBatch& b = rb[(size_t) l.dev];
                if (b.n == kMaxRingBatch) {   // (more layers on a device than a batch takes: this one alone)
                    cudaSetDevice(devs[(size_t) l.dev].id);
                    ring_restore(l.win, l.ring_bak, p0, g.win, keep, T, g.hd, devs[(size_t) l.dev].st);
                    continue;
                }
                b.ring[b.n] = l.win;
                b.bak[b.n++] = l.ring_bak;
            }
        for (size_t di = 0; di < devs.size(); ++di)
            if (rb[di].n > 0) {
                cudaSetDevice(devs[di].id);
                ring_restore_batch(rb[di], p0, g.win, keep, T, g.hd, devs[di].st);
            }
        for (int il = 0; il < g.nl; ++il)
            for (int m = 0; m < L[(size_t) il].nm; ++m) {
                Layer& l = member(L[(size_t) il], m);
                Dev& d = devs[(size_t) l.dev];
                if (l.c_snap != nullptr) {
                    cudaSetDevice(d.id);
                    const size_t ns = (size_t) l.ratio * g.hd * 4;
                    cudaMemcpyAsync(l.c_kv, l.c_snap, ns, cudaMemcpyDeviceToDevice, d.st);
                    cudaMemcpyAsync(l.c_score, l.c_snap + (size_t) l.ratio * g.hd, ns, cudaMemcpyDeviceToDevice, d.st);
                    compress_win(l.c_rows, l.c_rows + (size_t) kWin * g.hd, l.c_kv, l.c_score, l.ratio, (int) p0, keep,
                                 g.hd, l.c_norm, g.eps, d.latent, d.st);
                }
            }
        pos = p0 + keep;
        toks.resize((size_t) pos);
        ctoks.resize((size_t) pos);
        slot_held = false;
    }

    // ---- a window: T tokens at positions pos .. pos + T - 1 through every layer; the logits of its last `logits` rows
    bool step(int token, bool want_logits, std::string& err) { return forward(&token, 1, want_logits ? 1 : 0, err); }


    // layer L0 for a chunk of T tokens at p0 as group member mi: layer()'s arithmetic over the chunk's rows (the
    // projections as GEMMs, the attention and the indexer in slabs, the routed experts as sorted rows: the VRAM ones in
    // place, the CPU lane's streamed in batches).  kv_only (a long prompt's first pass, Run::stop): only what the layers
    // after it read of these rows - its compressed KV and index keys - and nothing of its own attention or experts
    bool layer_chunk(Layer& L0, int mi, int64_t p0, int T, const WinPlan& wp, Streamer& S, std::string& err,
                     bool kv_only = false) {
        Layer& l = member(L0, mi);
        Dev& d = devs[(size_t) l.dev];
        Chunk& c = *chunks[(size_t) l.dev];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        prof_mark(d, 0);
        const int nm = L0.nm;
        const int D = g.dim, H = g.hc, HD = g.hd, NHL = l.ahn, HQ = NHL * HD, OG = l.ogn, FF = l.ffn;
        const ArGroup& ab = groups[(size_t) L0.grp].arb;
        const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
        // Engram, in slabs of 256 tokens
        if (l.eg >= 0) {
            const int cols = (pk.eg_ngram - 1) * pk.eg_heads, ehd = pk.eg_hd;
            const size_t per = (size_t) cols * (ehd + ehd / 32);
            const int slot = wp.eg_slot >= 0 ? wp.eg_slot : wp.k % 2;   // (read ahead by the run: two in flight)
            uint8_t* host = c.eg_host[slot] + (size_t) l.eg * c.C * per;
            CK(cudaMemcpyAsync(c.eg_rows, host, (size_t) T * per, cudaMemcpyHostToDevice, s));
            CK(cudaEventRecord(c.eg_ev[slot], s));
            for (int s0 = 0; s0 < T; s0 += 256) {
                const int ns = std::min(256, T - s0);
                engram_dequant_tok(c.eg_rows + (size_t) s0 * per, per, cols, ns, ehd, c.eg_x, s, (int) eg_fmt[(size_t) l.eg]);
                x3::rows_f16(c.eg_x, cols * ehd, nullptr, ns, cols * ehd, c.eg_x16, s);
                if (!gemm(d, c, l.eg_wkv, c.eg_x16, cols * ehd, ns, c.eg_kv, (H + 1) * D, 0.0f, err)) return false;
                engram_gate(c.h + (size_t) s0 * H * D, c.eg_kv, l.eg_w, H, D, ns, g.eps, s);
            }
        }
        prof_mark(d, 4);
        // attention
#if defined(STRATA_METAL)
        // the mix and the split in one dispatch (hc_mix + hc_split were two, back to back on the same token)
        hc_mix_split(c.h, l.hca_fn, g.hc * g.dim, (2 + g.hc) * g.hc, T, g.eps, c.mix, l.hca_scale, l.hca_base, H,
                     g.sinkhorn, g.hc_eps, c.a_pre, c.a_post, c.a_comb, s);
#else
        if (!hc_mix_chunk(d, c, c.h, l.hca_fn, T, c.mix, err)) return false;
        hc_split(c.mix, l.hca_scale, l.hca_base, H, g.sinkhorn, g.hc_eps, T, c.a_pre, c.a_post, c.a_comb, s);
#endif
        dump_sub(d, "mix0", l.il, p0, T, c.mix, (size_t) T * 32 * 4);
        hc_pre_norm(c.h, c.pre, l.attn_norm, D, H, T, g.eps, c.x, s);
        dump_sub(d, "a_mix", l.il, p0, T, c.mix, (size_t) T * 32 * 4);
        dump_sub(d, "a_pre", l.il, p0, T, c.a_pre, (size_t) T * 8 * 4);
        dump_sub(d, "a_post", l.il, p0, T, c.a_post, (size_t) T * 8 * 4);
        dump_sub(d, "a_comb", l.il, p0, T, c.a_comb, (size_t) T * 64 * 4);
        dump_sub(d, "attn_x", l.il, p0, T, c.x, (size_t) T * D * 4);
        x3::rows_f16(c.x, D, nullptr, T, D, c.x16, s);
        prof_mark(d, 5);
        if (!kv_only && (!gemm(d, c, l.wq_a, c.x16, D, T, c.qr, g.q_lora, 0.0f, err) ||
                         !gemm(d, c, l.wkv, c.x16, D, T, c.kvr, HD, 0.0f, err)))
            return false;
        if (l.kv_src && !gemm(d, c, l.c_wkv, c.x16, D, T, c.ckr, HD, 0.0f, err)) return false;
        if (l.kv_src && l.ratio > 1 && !gemm(d, c, l.c_wgate, c.x16, D, T, c.cgr, HD, 0.0f, err)) return false;
        prof_mark(d, 6);
        const bool snap = !kv_only && wp.snap_t >= 0 && mi == 0 && L0.snap_win != nullptr;
        if (!kv_only) {
            dump_sub(d, "qr_raw", l.il, p0, T, c.qr, (size_t) T * g.q_lora * 4);
            dump_sub(d, "kvr_raw", l.il, p0, T, c.kvr, (size_t) T * HD * 4);
            Finish fq;
            fq.w = l.q_norm;
            fq.eps = g.eps;
            finish(c.qr, T, g.q_lora, g.q_lora, fq, s);
            x3::rows_f16(c.qr, g.q_lora, nullptr, T, g.q_lora, c.qr16, s);
            // the window rows: the ring's (positions p0 - win ..) then the chunk's
            ring_to_ext(l.win, c.ext, p0, g.win, HD, s);
            Finish fk;
            fk.w = l.kv_norm;
            fk.eps = g.eps;
            fk.rd = g.rd;
            fk.pos = (int) p0;
            fk.freqs = freqs;
            fk.quant = 1;
            fk.dst = c.ext + (size_t) g.win * HD;
            fk.dst_stride = HD;
            finish(c.kvr, T, HD, HD, fk, s);
            // feed_mark's checkpoint: the ring as it was before row snap_t - the old ring, then the chunk's rows before it
            if (snap) {
                CK(cudaMemcpyAsync(L0.snap_win, l.win, (size_t) g.win * win_rb(), cudaMemcpyDeviceToDevice, s));
                if (wp.snap_t > 0) ext_to_ring(c.ext, L0.snap_win, p0, g.win, wp.snap_t, HD, s, nullptr);
            }
            ext_to_ring(c.ext, l.win, p0, g.win, T, HD, s, nullptr);
        }
        const uint8_t* ckv = nullptr;
        const long long ss = (long long) o.max_context + 64;
        if (l.ratio > 0) {
            Src& sr = srcs[(size_t) l.src];
            const int R = l.ratio;
            const int64_t g_first = p0 / R, g_end = (p0 + T) / R;
            const int ng = (int) std::max<int64_t>(0, g_end - g_first);
            const float* latent = c.latent;
            if (l.kv_src) {
                if (R == 1) {
                    Finish fc;
                    fc.w = l.c_norm;
                    fc.eps = g.eps;
                    finish(c.ckr, T, HD, HD, fc, s);
                    latent = c.ckr;
                } else {
                    if (snap && L0.snap_kv != nullptr) {   // (each slot: the latest row before snap_t that holds it)
                        const int64_t ps = p0 + wp.snap_t;
                        for (int sl = 0; sl < R; ++sl) {
                            const int64_t q = ps - 1 - (((ps - 1 - sl) % R) + R) % R;
                            const float* kv = q >= p0 ? c.ckr + (size_t) (q - p0) * HD : l.c_kv + (size_t) sl * HD;
                            const float* sc = q >= p0 ? c.cgr + (size_t) (q - p0) * HD : l.c_score + (size_t) sl * HD;
                            CK(cudaMemcpyAsync(L0.snap_kv + (size_t) sl * HD, kv, (size_t) HD * 4, cudaMemcpyDeviceToDevice, s));
                            CK(cudaMemcpyAsync(L0.snap_sc + (size_t) sl * HD, sc, (size_t) HD * 4, cudaMemcpyDeviceToDevice, s));
                        }
                    }
                    compress_win(c.ckr, c.cgr, l.c_kv, l.c_score, R, (int) p0, T, HD, l.c_norm, g.eps, c.latent, s);
                }
            }
            const int clen_max = (int) ((p0 + T) / R);
            if (l.ix_src) {
                Src& ks = srcs[(size_t) l.ik_src];
                if (l.owns_k && ng > 0) {
                    x3::rows_f16(latent, HD, nullptr, ng, HD, c.lat16, s);
                    if (!gemm(d, c, l.i_wk, c.lat16, HD, ng, c.ikr, g.ix_hd, 0.0f, err)) return false;
                    Finish fi;
                    fi.w = l.ik_norm;
                    fi.eps = g.eps;
                    fi.rd = g.rd;
                    fi.pos = (int) (g_first * R);
                    fi.pos_step = R;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    fi.pdst = ks.ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                    fi.pdst_stride = (long long) ik_rb();
                    finish(c.ikr, ng, g.ix_hd, g.ix_hd, fi, s);
                }
                if (clen_max > 0 && !kv_only) {
                    if (!gemm_f16w(c, l.i_wproj, g.ix_heads, D, c.x16, D, T,
                                   1.0f / std::sqrt((float) g.ix_hd) / std::sqrt((float) g.ix_heads), c.iw, 64, err))
                        return false;
                    for (int a0 = 0; a0 < T; a0 += c.AI) {
                        const int na = std::min(c.AI, T - a0);
                        const int64_t pa = p0 + a0;
                        if (!gemm(d, c, l.i_wq_b, c.qr16 + (size_t) a0 * g.q_lora, g.q_lora, na, c.iq,
                                  g.ix_heads * g.ix_hd, 0.0f, err))
                            return false;
                        Finish fi;
                        fi.rd = g.rd;
                        fi.pos = (int) pa;
                        fi.vpp = g.ix_heads;
                        fi.freqs = freqs;
                        fi.quant = 3;
                        finish(c.iq, na * g.ix_heads, g.ix_hd, g.ix_hd, fi, s);
                        Rows lim;
                        lim.gen = 1;
                        lim.p0 = pa;
                        lim.R = R;
                        lim.kcap = g.ix_topk;
                        lim.ccap = g.cand_topk;
                        lim.blk = std::max(1, g.cand_blk);
                        const int nlast = (int) ((pa + na) / R);   // the slab's widest query
                        int* tk = c.topk + (size_t) a0 * topk_stride();
                        int* cd = c.cand + (size_t) a0 * cand_stride();
                        const float* iw = c.iw + (size_t) a0 * 64;
                        if (nlast <= 0) continue;
                        if (l.uses_cand && (nlast + g.cand_blk - 1) / g.cand_blk > g.cand_topk) {
                            Rows cl = lim;
                            cl.gen = 2;
                            index_score(c.iq, iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, na, g.cand_topk * g.cand_blk,
                                        cd, (int) cand_stride(), g.cand_blk, cl, c.scores, ss, s);
                            Rows tr = lim;
                            tr.gen = 3;
                            topk(c.scores, ss, na, tr, cd, (int) cand_stride(), g.cand_blk, tk, (int) topk_stride(), s);
                        } else {
                            index_score(c.iq, iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, na, nlast, nullptr, 0, 1,
                                        lim, c.scores, ss, s);
                            if (l.cand_src) {
                                Rows cr = lim;
                                cr.kcap = g.cand_topk;
                                cand_blocks(c.scores, ss, na, cr, g.cand_blk, c.bm, (long long) bm_stride(), cd,
                                            (int) cand_stride(), s);
                            }
                            topk(c.scores, ss, na, lim, nullptr, 0, 1, tk, (int) topk_stride(), s);
                        }
                    }
                }
            }
            if (l.kv_src && ng > 0) {
                Finish fc;
                fc.rd = g.rd;
                fc.pos = (int) (g_first * R);
                fc.pos_step = R;
                fc.freqs = freqs;
                fc.quant = 2;
                fc.pdst = sr.ckv[(size_t) l.dev] + (size_t) g_first * ckv_rb();
                fc.pdst_stride = (long long) ckv_rb();
                finish(const_cast<float*>(latent), ng, HD, HD, fc, s);
                if (mi == 0 && sr.remote) {   // the new rows for the other groups' readers (slot k % 2, once
                    const int slot = wp.k % 2;  // they took the chunk before last's)
                    if (wp.k >= 2)
                        for (int r : sr.readers) {
                            host_wait_at_least(sr.x_ack + ((size_t) slot * devs.size() + r) * 32, wp.win - 2);
                            wait_flags(sr.x_ack + ((size_t) slot * devs.size() + r) * 32, 1, 32, wp.win - 2, s);
                        }
                    Xfer x;
                    x.src[0] = fc.pdst;
                    x.dst[0] = sr.stage(slot);
                    x.bytes[0] = (size_t) ng * ckv_rb();
                    x.n = 1;
                    if (l.owns_k && srcs[(size_t) l.ik_src].ik[(size_t) l.dev] != nullptr) {
                        x.src[1] = srcs[(size_t) l.ik_src].ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                        x.dst[1] = sr.stage(slot) + x_cap() * ckv_rb();
                        x.bytes[1] = (size_t) ng * ik_rb();
                        x.n = 2;
                    }
                    xfer_put(x, sr.flag(slot), wp.win, d.xcnt, s);
                }
            }
            ckv = sr.ckv[(size_t) l.dev];
        }
        if (kv_only) return true;
        prof_mark(d, 7);
        // the attention in slabs: q, the sparse attention, wo_a, wo_b (this member's share) into acc
        if (NHL == 0 && !l.a3) CK(cudaMemsetAsync(c.acc, 0, (size_t) T * D * sizeof(*c.acc), s));   // (no heads)
        if (l.a3) {
            // DS4_ATTN_SPLIT3 (Layer::a3): the own groups' heads for every row of a slab, the shared groups' for the
            // slab's rows in this member's nm-th of the chunk [r0, r1); the products are the ones of the single-card path
            // (the same weights' rows, a whole wo_a group a GEMM), only wo_b's sum taken in parts in another order
            const int hpg = g.heads / g.o_groups, HO = l.a3_own * HD, HS = l.a3_sh * HD, OGO = l.a3_own / hpg,
                      OGS = l.a3_sh / hpg, ldo = (OGO + OGS) * g.o_lora, per = hpg * HD;
            const int r0 = (int) ((long long) T * mi / nm), r1 = (int) ((long long) T * (mi + 1) / nm);
            float* const qs = c.q + (size_t) c.A * HO;
            float* const os = c.o + (size_t) c.A * HO;
            uint16_t* const os16 = c.o16 + (size_t) c.A * HO;
            for (int a0 = 0; a0 < T; a0 += c.A) {
                const int na = std::min(c.A, T - a0);
                const int b0 = std::max(a0, r0), b1 = std::min(a0 + na, r1), nb = std::max(0, b1 - b0);
                if (!gemm(d, c, l.a3_qo, c.qr16 + (size_t) a0 * g.q_lora, g.q_lora, na, c.q, HO, 0.0f, err)) return false;
                Finish fr;
                fr.rd = g.rd;
                fr.pos = (int) (p0 + a0);
                fr.vpp = l.a3_own;
                fr.freqs = freqs;
                finish(c.q, na * l.a3_own, HD, HD, fr, s);
                if (nb > 0) {
                    if (!gemm(d, c, l.a3_qs, c.qr16 + (size_t) b0 * g.q_lora, g.q_lora, nb, qs, HS, 0.0f, err)) return false;
                    Finish fs = fr;
                    fs.pos = (int) (p0 + b0);
                    fs.vpp = l.a3_sh;
                    finish(qs, nb * l.a3_sh, HD, HD, fs, s);
                }
                prof_mark(d, 8);
                AttnRows ar;
                ar.gen = 1;
                ar.p0 = p0;
                ar.t0 = a0;
                ar.win = g.win;
                ar.R = l.ratio;
                ar.kcap = g.ix_topk;
                sparse_attn(c.q, c.ext, ckv, c.topk + (size_t) a0 * topk_stride(), (int) topk_stride(), ar, l.sink, l.a3_own, HD,
                            na, 1.0f / std::sqrt((float) HD), c.o, s, kKvFp4, 0, &d.attn_scr, l.il);   // (the layer: DS4_FAST_ATTN_LAYERS)
                if (nb > 0) {
                    AttnRows as = ar;
                    as.t0 = b0;
                    sparse_attn(qs, c.ext, ckv, c.topk + (size_t) b0 * topk_stride(), (int) topk_stride(), as, l.sink + l.a3_own,
                                l.a3_sh, HD, nb, 1.0f / std::sqrt((float) HD), os, s, kKvFp4, 0, &d.attn_scr, l.il);
                }
                prof_mark(d, 9);
                Finish fo;
                fo.rd = g.rd;
                fo.pos = (int) (p0 + a0);
                fo.vpp = l.a3_own;
                fo.freqs = freqs;
                fo.inverse = 1;
                fo.quant = 1;
                finish(c.o, na * l.a3_own, HD, HD, fo, s);
                x3::rows_f16(c.o, HO, nullptr, na, HO, c.o16, s);
                for (int gi = 0; gi < OGO; ++gi)
                    if (!gemm(d, c, l.wo_a[gi], c.o16 + (size_t) gi * per, HO, na, c.oa + (size_t) gi * g.o_lora, ldo, 0.0f, err))
                        return false;
                if (nb > 0) {
                    Finish fx = fo;
                    fx.pos = (int) (p0 + b0);
                    fx.vpp = l.a3_sh;
                    finish(os, nb * l.a3_sh, HD, HD, fx, s);
                    x3::rows_f16(os, HS, nullptr, nb, HS, os16, s);
                    float* const oas = c.oa + (size_t) (b0 - a0) * ldo + (size_t) OGO * g.o_lora;
                    for (int j = 0; j < OGS; ++j)
                        if (!gemm(d, c, l.wo_a[OGO + j], os16 + (size_t) j * per, HS, nb, oas + (size_t) j * g.o_lora, ldo, 0.0f, err))
                            return false;
                }
                // (the whole width: the shared columns of the rows outside [r0, r1) are converted but never read)
                x3::rows_f16(c.oa, ldo, nullptr, na, ldo, c.oa16, s);
                if (!gemm(d, c, l.a3_bo, c.oa16, ldo, na, c.acc + (size_t) a0 * D, D, 0.0f, err)) return false;
                if (nb > 0 && !gemm(d, c, l.a3_bs, c.oa16 + (size_t) (b0 - a0) * ldo + (size_t) OGO * g.o_lora, ldo, nb,
                                    c.acc + (size_t) b0 * D, D, 1.0f, err))
                    return false;
            }
        }
        for (int a0 = 0; a0 < T && NHL > 0 && !l.a3; a0 += c.A) {
            const int na = std::min(c.A, T - a0);
            if (!gemm(d, c, l.wq_b, c.qr16 + (size_t) a0 * g.q_lora, g.q_lora, na, c.q, HQ, 0.0f, err)) return false;
            Finish fr;
            fr.rd = g.rd;
            fr.pos = (int) (p0 + a0);
            fr.vpp = NHL;
            fr.freqs = freqs;
            finish(c.q, na * NHL, HD, HD, fr, s);
            prof_mark(d, 8);
            if (a0 == 0 && na == T) dump_sub(d, "q", l.il, p0, T, c.q, (size_t) T * HQ * 4);
            AttnRows ar;
            ar.gen = 1;
            ar.p0 = p0;
            ar.t0 = a0;
            ar.win = g.win;
            ar.R = l.ratio;
            ar.kcap = g.ix_topk;
            sparse_attn(c.q, c.ext, ckv, c.topk + (size_t) a0 * topk_stride(), (int) topk_stride(), ar, l.sink, NHL, HD,
                        na, 1.0f / std::sqrt((float) HD), c.o, s, kKvFp4, 0, &d.attn_scr, l.il);   // (a short last slab; the layer: DS4_FAST_ATTN_LAYERS)
            prof_mark(d, 9);
            if (a0 == 0 && na == T) dump_sub(d, "o", l.il, p0, T, c.o, (size_t) T * HQ * 4);
            Finish fo;
            fo.rd = g.rd;
            fo.pos = (int) (p0 + a0);
            fo.vpp = NHL;
            fo.freqs = freqs;
            fo.inverse = 1;
            fo.quant = 1;
            finish(c.o, na * NHL, HD, HD, fo, s);
            if (a0 == 0 && na == T) dump_sub(d, "o_fin", l.il, p0, T, c.o, (size_t) T * HQ * 4);
            x3::rows_f16(c.o, HQ, nullptr, na, HQ, c.o16, s);
            const int per = HQ / OG;
            for (int gi = 0; gi < OG; ++gi)
                if (!gemm(d, c, l.wo_a[gi], c.o16 + (size_t) gi * per, HQ, na, c.oa + (size_t) gi * g.o_lora,
                          OG * g.o_lora, 0.0f, err))
                    return false;
            x3::rows_f16(c.oa, OG * g.o_lora, nullptr, na, OG * g.o_lora, c.oa16, s);
            if (!gemm(d, c, l.wo_b, c.oa16, OG * g.o_lora, na, c.acc + (size_t) a0 * D, D, 0.0f, err)) return false;
            if (a0 == 0 && na == T) dump_sub(d, "ao", l.il, p0, T, c.acc, (size_t) T * D * 4);
        }
        // DS4_AR_OVERLAP=N (2..4; 1 = 2; unset / 0 off): the attention's all-reduce in N row parts on a second stream, each
        // part's hc_post, FFN mHC and router GEMV on the compute stream as soon as its part is summed - the all-reduce of part
        // i + 1 runs beside the work of part i.  Every op here is row-wise, so a row's arithmetic is its own (the mHC mixes'
        // F32 GEMM is the one call whose blocking can change with its row count); routing's sort waits for all the rows.
        static const int ar_ov = [] {
            const char* e = std::getenv("DS4_AR_OVERLAP");
            const int v = e != nullptr ? std::atoi(e) : 0;
            return v <= 0 ? 0 : std::min(4, std::max(2, v));
        }();
#if defined(STRATA_METAL)
        const int n_ov = 0;
#else
        const int n_ov = nm > 1 && ar_ov > 0 && T >= 256 * ar_ov && dump_l == nullptr && !dump_s_on(l.il) ? ar_ov : 0;
#endif
        // rows [r0, r0 + nr): hc_post of the attention, then the FFN's mHC, pre-norm, F16 copy, router logits and picks
        auto ffn_pre = [&](int r0, int nr) -> bool {
            hc_post_inplace(c.acc + (size_t) r0 * D, c.h + (size_t) r0 * H * D, c.a_post + (size_t) r0 * 8,
                            c.a_comb + (size_t) r0 * 64, D, H, nr, s);
#if !defined(STRATA_METAL)
            if (!hc_mix_chunk(d, c, c.h + (size_t) r0 * H * D, l.hcf_fn, nr, c.mix + (size_t) r0 * 32, err)) return false;
            hc_split(c.mix + (size_t) r0 * 32, l.hcf_scale, l.hcf_base, H, g.sinkhorn, g.hc_eps, nr, c.f_pre + (size_t) r0 * 8,
                     c.f_post + (size_t) r0 * 8, c.f_comb + (size_t) r0 * 64, s);
#endif
            hc_pre_norm(c.h + (size_t) r0 * H * D, c.a_pre + (size_t) r0 * 8, l.ffn_norm, D, H, nr, g.eps, c.x + (size_t) r0 * D, s);
            x3::rows_f16(c.x + (size_t) r0 * D, D, nullptr, nr, D, c.x16 + (size_t) r0 * D, s);
            gemv_f32(l.gate_w, c.x + (size_t) r0 * D, l.n_exp, D, nr, c.glog + (size_t) r0 * 1024, 1024, s);
            for (int q0 = r0; q0 < r0 + nr; q0 += kVlRows) {
                const int nq = std::min(kVlRows, r0 + nr - q0);
                VlBits vb;
                const bool vl = l.gate_bias_vl != nullptr && vl_bits(p0 + q0, nq, vb);
                route(c.glog + (size_t) q0 * 1024, l.gate_bias, l.n_exp, l.k_exp, nq, g.route_scale,
                      c.ridx + (size_t) q0 * kPicks, c.rw + (size_t) q0 * kPicks, s, l.gate_bias_vl, vl ? &vb : nullptr);
            }
            return true;
        };
        if (n_ov > 0) {
            if (c.ars == nullptr) {
                CK(cudaStreamCreateWithFlags(&c.ars, cudaStreamNonBlocking));
                for (cudaEvent_t& e : c.ar_ev) CK(cudaEventCreateWithFlags(&e, cudaEventDisableTiming));
            }
            prof_mark(d, 1);
            int rb[5];
            for (int i = 0; i <= n_ov; ++i) rb[i] = i == n_ov ? T : (int) ((int64_t) T * i / n_ov / 16 * 16);
            CK(cudaEventRecord(c.ar_ev[4], s));   // (the attention's partial in acc)
            CK(cudaStreamWaitEvent(c.ars, c.ar_ev[4], 0));
            for (int i = 0; i < n_ov; ++i) {
                allreduce(c.acc + (size_t) rb[i] * D, (rb[i + 1] - rb[i]) * D, ab, mi, ++c.arb_seq, d.xcnt, c.ars);
                CK(cudaEventRecord(c.ar_ev[i], c.ars));
            }
            for (int i = 0; i < n_ov; ++i) {
                CK(cudaStreamWaitEvent(s, c.ar_ev[i], 0));
                if (!ffn_pre(rb[i], rb[i + 1] - rb[i])) return false;
            }
            prof_mark(d, 11);   // (overlapped: the all-reduce and the FFN's head together)
        } else {
            if (nm > 1) {   // (DS4_PROF: the all-reduce its own stage, 11; it includes the wait for the slowest member)
                prof_mark(d, 1);
                allreduce(c.acc, T * D, ab, mi, ++c.arb_seq, d.xcnt, s);
                prof_mark(d, 11);
            }
            dump_sub(d, "h_in", l.il, p0, T, c.h, (size_t) T * H * D * 4);
            hc_post_inplace(c.acc, c.h, c.a_post, c.a_comb, D, H, T, s);
            if (dump_l != nullptr && mi == 0) dump_layer(d, c.h, 1000 + l.il, p0, T);   // (after the attention, as the window path)
            prof_mark(d, 1);
            // the MoE
#if defined(STRATA_METAL)
            // the FFN half of the same fusion: mix and split in one dispatch
            hc_mix_split(c.h, l.hcf_fn, g.hc * g.dim, (2 + g.hc) * g.hc, T, g.eps, c.mix, l.hcf_scale, l.hcf_base, H,
                         g.sinkhorn, g.hc_eps, c.f_pre, c.f_post, c.f_comb, s);
#else
            if (!hc_mix_chunk(d, c, c.h, l.hcf_fn, T, c.mix, err)) return false;
            hc_split(c.mix, l.hcf_scale, l.hcf_base, H, g.sinkhorn, g.hc_eps, T, c.f_pre, c.f_post, c.f_comb, s);
#endif
            hc_pre_norm(c.h, c.a_pre, l.ffn_norm, D, H, T, g.eps, c.x, s);
            x3::rows_f16(c.x, D, nullptr, T, D, c.x16, s);
            gemv_f32(l.gate_w, c.x, l.n_exp, D, T, c.glog, 1024, s);   // (F32 x: the token path's bits)
            for (int r0 = 0; r0 < T; r0 += kVlRows) {   // (route()'s image bits cover kVlRows rows a call)
                const int nr = std::min(kVlRows, T - r0);
                VlBits vb;
                const bool vl = l.gate_bias_vl != nullptr && vl_bits(p0 + r0, nr, vb);
                route(c.glog + (size_t) r0 * 1024, l.gate_bias, l.n_exp, l.k_exp, nr, g.route_scale,
                      c.ridx + (size_t) r0 * kPicks, c.rw + (size_t) r0 * kPicks, s, l.gate_bias_vl, vl ? &vb : nullptr);
            }
        }
        // DS4_PF_HELPER: this layer's CPU-lane experts on the helpers (pfh_chunk / pfh_layer_ok: the planner left it no
        // batches).  The lead reads the routing back on the compute stream (it is small; the bounds wait below covers it) and
        // the FFN input on its own stream, beside the sort and the shared expert.
        const bool pfh = wp.pfh && !c.flow && !kv_only && pfh_layer_ok(L0);
        if (pfh && mi == 0) {
            const size_t ldi = (size_t) l.dev;
            CK(cudaMemcpyAsync(pfh_ids, c.ridx, (size_t) T * kPicks * 4, cudaMemcpyDeviceToHost, s));
            CK(cudaMemcpyAsync(pfh_w, c.rw, (size_t) T * kPicks * 4, cudaMemcpyDeviceToHost, s));
            CK(cudaEventRecord(pfh_ev_r[ldi], s));
            CK(cudaStreamWaitEvent(pfh_cs[ldi], pfh_ev_r[ldi], 0));
            CK(cudaMemcpyAsync(hlp.pf_x(), c.x, (size_t) T * D * 4, cudaMemcpyDeviceToHost, pfh_cs[ldi]));
            CK(cudaEventRecord(pfh_ev_x[ldi], pfh_cs[ldi]));
        }
        const int n_vs = L0.n_slots + (int) L0.host_list.size();
        CK(cudaMemcpyAsync(l.vs_dev, l.vs_pin, (size_t) l.n_exp * 4, cudaMemcpyHostToDevice, s));   // (this member's)
        moe_sort(c.ridx, T, l.k_exp, l.vs_dev, n_vs, c.bounds, c.row_tok, c.pos, s);
        CK(cudaMemcpyAsync(c.bounds_pin, c.bounds, (size_t) (n_vs + 1) * 4, cudaMemcpyDeviceToHost, s));
        prof_mark(d, 10);
        // the shared expert into acc while the host waits for the bounds
        if (!gemm(d, c, l.s1, c.x16, D, T, c.sg, FF, 0.0f, err) || !gemm(d, c, l.s3, c.x16, D, T, c.su, FF, 0.0f, err))
            return false;
        swiglu(c.sg, c.su, T * FF, g.lim, c.sg, s);
        x3::rows_f16(c.sg, FF, nullptr, T, FF, c.sh16, s);
        if (!gemm(d, c, l.s2, c.sh16, FF, T, c.acc, D, 0.0f, err)) return false;
        prof_mark(d, 2);
        // the expert stream's copies keep going while the device runs this layer's attention, routing and shared expert:
        // the next items (this layer's likely experts, queued when the layer before routed) go out as they are ready and
        // ring slots free, not only once the bounds are back (Project Maya #360; DS4_FLOW_PUMP_WAIT=0: wait as before)
        static const bool pump_wait = std::getenv("DS4_FLOW_PUMP_WAIT") == nullptr ||
                                      std::atoi(std::getenv("DS4_FLOW_PUMP_WAIT")) != 0;
        if (c.flow && pump_wait)
            while (cudaStreamQuery(s) == cudaErrorNotReady) {
                if (!flow_pump(c, err)) return false;
                std::this_thread::yield();
            }
        CK(cudaStreamSynchronize(s));
        std::vector<int> b(c.bounds_pin, c.bounds_pin + n_vs + 1);
        if (dump_r != nullptr && mi == 0) {
            const size_t nk = (size_t) T * l.k_exp, np = (size_t) T * kPicks;
            std::vector<int> ri(np), rt(nk);
            std::vector<float> gl((size_t) T * l.n_exp), gb((size_t) l.n_exp);
            CK(cudaMemcpy(ri.data(), c.ridx, np * 4, cudaMemcpyDeviceToHost));
            CK(cudaMemcpy(rt.data(), c.row_tok, nk * 4, cudaMemcpyDeviceToHost));
            CK(cudaMemcpy2D(gl.data(), (size_t) l.n_exp * 4, c.glog, 1024 * 4, (size_t) l.n_exp * 4, (size_t) T,
                            cudaMemcpyDeviceToHost));
            CK(cudaMemcpy(gb.data(), l.gate_bias, gb.size() * 4, cudaMemcpyDeviceToHost));
            std::lock_guard<std::mutex> lk(dump_mu);
            const int64_t hdr[8] = {l.il, p0, T, l.k_exp, l.n_exp, n_vs, L0.n_slots, kPicks};
            std::fwrite(hdr, 8, 8, dump_r);
            std::fwrite(ri.data(), 4, np, dump_r);
            std::fwrite(L0.vs_pin, 4, (size_t) l.n_exp, dump_r);
            std::fwrite(b.data(), 4, b.size(), dump_r);
            std::fwrite(rt.data(), 4, nk, dump_r);
            std::fwrite(gl.data(), 4, gl.size(), dump_r);
            std::fwrite(gb.data(), 4, gb.size(), dump_r);
            std::fflush(dump_r);
        }
        if (mi == 0 && !l.mtp && (pred_f != nullptr || xin_f != nullptr)) {
            std::lock_guard<std::mutex> lk(dump_mu);
            if (pred_f != nullptr) {
                float* dp = nullptr;
                CK(cudaMalloc(&dp, (size_t) T * 256 * 4));
                strata_ds4_launch(pred_proj_k, T, 256, 0, s, c.x, (int) D, dp);
                std::vector<float> hp((size_t) T * 256), hl((size_t) T * l.n_exp);
                CK(cudaMemcpyAsync(hp.data(), dp, hp.size() * 4, cudaMemcpyDeviceToHost, s));
                CK(cudaMemcpy2DAsync(hl.data(), (size_t) l.n_exp * 4, c.glog, 1024 * 4, (size_t) l.n_exp * 4, (size_t) T,
                                     cudaMemcpyDeviceToHost, s));
                CK(cudaStreamSynchronize(s));
                CK(cudaFree(dp));
                std::vector<uint16_t> o(hp.size() + hl.size());
                for (size_t i = 0; i < hl.size(); ++i) o[i] = strata::kernels::f16_from_f32(hl[i]);
                for (size_t i = 0; i < hp.size(); ++i) o[hl.size() + i] = strata::kernels::f16_from_f32(hp[i]);
                const uint8_t hd[3] = {(uint8_t) l.il, (uint8_t) (T & 255), (uint8_t) (T >> 8)};
                std::fwrite(hd, 1, 3, pred_f);
                std::fwrite(o.data(), 2, o.size(), pred_f);
            }
            if (xin_f != nullptr && xin_got[(size_t) l.il] < xin_n) {   // up to 32 evenly spaced tokens of the chunk
                const int tk = std::min(std::min(T, 32), xin_n - xin_got[(size_t) l.il]);
                const int stride = std::max(1, T / tk);
                std::vector<float> hx((size_t) T * D);
                CK(cudaMemcpyAsync(hx.data(), c.x, hx.size() * 4, cudaMemcpyDeviceToHost, s));
                CK(cudaStreamSynchronize(s));
                const uint8_t hd[3] = {(uint8_t) l.il, (uint8_t) (tk & 255), (uint8_t) (tk >> 8)};
                std::fwrite(hd, 1, 3, xin_f);
                for (int i = 0; i < tk; ++i) std::fwrite(hx.data() + (size_t) std::min(T - 1, i * stride) * D, 4, (size_t) D, xin_f);
                xin_got[(size_t) l.il] += tk;
            }
        }
        if (mi == 0 && trace_f != nullptr && !l.mtp) {   // DS4_TRACE: a chunk's picks, u8 (layer | 0x80), u16 T, T x k int16 ids
            std::vector<int> ri((size_t) T * kPicks);
            CK(cudaMemcpy(ri.data(), c.ridx, ri.size() * 4, cudaMemcpyDeviceToHost));
            std::lock_guard<std::mutex> lk(dump_mu);
            const uint8_t hd[3] = {(uint8_t) (l.il | 0x80), (uint8_t) (T & 255), (uint8_t) (T >> 8)};
            std::fwrite(hd, 1, 3, trace_f);
            for (int t = 0; t < T; ++t)
                for (int i = 0; i < l.k_exp; ++i) {
                    const int16_t v = (int16_t) ri[(size_t) t * kPicks + i];
                    std::fwrite(&v, 2, 1, trace_f);
                }
        }
        if (mi == 0) {   // the profile (the CPU lane's experts: by the plan's order)
            uint32_t* pr = prof.data() + (size_t) l.il * g.n_exp;
            for (int e = 0; e < l.n_exp; ++e) {
                const int v = L0.vs_pin[e];
                const int cnt = b[(size_t) v + 1] - b[(size_t) v];
                pr[e] += (uint32_t) cnt;
                if (cnt > 0) {   // (the expert cache learns from a chunked prompt as from windows: heat, and the CPU lane's hits)
                    l.heat[(size_t) e] += (float) cnt;
                    if (l.slot[(size_t) e] < 0) l.cpu_hits.push_back(e);
                }
            }
            st.experts += (int64_t) T * l.k_exp;
        }
        if (c.flow) {
            if (!flow_layer(d, c, L0, mi, wp.k, T, b, err)) return false;
            if (nm > 1) allreduce(c.acc, T * D, ab, mi, ++c.arb_seq, d.xcnt, s);
            hc_post_inplace(c.acc, c.h, c.f_post, c.f_comb, D, H, T, s);
            CK(cudaMemcpyAsync(c.pre, c.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));
            prof_mark(d, 3);
            return true;
        }
        // the streamed experts as their batches arrive (each batch's slots freed for the copies at once), the VRAM ones
        // in shares between them (the device works while the copies run)
        const int di = l.dev, P = Chunk::kParts;
        prof_mark(d, 14);   // (DS4_PROF: the GPU idle while the host waited for the bounds and read them)
        int nb = 0;
        for (size_t q = S.kp; q < S.b.size() && S.b[q].il == L0.il && S.b[q].k == wp.k; ++q) ++nb;
        int v_done = 0;
        if (pfh) {   // DS4_PF_HELPER: every VRAM expert queued, then the helpers' share issued (lead) and joined (each member its own)
            if (!run_set(d, c, l, l.vram_base, 0, unit(l), c.bounds, b.data(), 0, L0.n_slots, T, err)) return false;
            prof_mark(d, 3);
            v_done = L0.n_slots;
            const uint64_t key = ((uint64_t) wp.win << 8) | (uint64_t) (l.il & 255);
            if (mi == 0) {
                const double txw = now_ms();
                CK(cudaEventSynchronize(pfh_ev_x[(size_t) di]));   // (the FFN input in the shared staging)
                pfh_xwait_ms += now_ms() - txw;   // (pf3: the lead's host wait for the x read-back)
                std::string e2;
                if (!hlp.pf_issue(l.il, T, l.k_exp, pfh_ids, pfh_w, [&](int e) { return L0.slot[(size_t) e] < 0 && pfh_held(L0, e); }, e2)) {
                    err = "DS4_PF_HELPER: layer " + std::to_string(l.il) + ": " + e2;
                    return false;
                }
                ++pfh_layers_run;
                if (nb > 0) {
                    ++pfh_layers_mixed;
                    for (size_t q = S.kp; q < S.kp + (size_t) nb; ++q) pfh_exp_streamed += S.b[q].n;
                }
                pfh_key.store(key, std::memory_order_release);
            } else {
                while (pfh_key.load(std::memory_order_acquire) < key) {
                    if (g_pipeline_abort.load(std::memory_order_relaxed)) {
                        err = "DS4_PF_HELPER: the lead stopped before issuing layer " + std::to_string(l.il);
                        return false;
                    }
                    std::this_thread::yield();
                }
            }
        } else if (wp.pfh && mi == 0 && !kv_only && !c.flow && !L0.host_list.empty()) {
            ++pfh_layers_streamed;   // (a PF chunk's layer with a CPU-lane expert no helper takes: streamed as before)
        }
        for (int bi = 0; bi < nb; ++bi) {
            const Batch& bt = S.b[S.kp];
            const int half = (int) (S.kp % P);
            CK(cudaStreamWaitEvent(s, c.filled[half], 0));
            const int v0 = L0.n_slots + bt.j0;
            if (!run_set(d, c, l, c.ring + (size_t) half * (c.ring_n / P) * c.ring_stride, v0, c.ring_stride, c.bounds,
                         b.data(), v0, v0 + bt.n, T, err))
                return false;
            prof_mark(d, 13);   // (DS4_PROF: the streamed batch, with the wait for its copies)
            CK(cudaEventRecord(c.freed[half], s));
            ++S.kp;
            if (!copy_ahead(d, c, S, di, err)) return false;
            const int v_to = std::max(v_done, (int) ((int64_t) L0.n_slots * (bi + 1) / nb));   // (pfh: every VRAM one done)
            if (v_to > v_done || !pfh) {   // (unset / not a helper layer: every share run as before)
                if (!run_set(d, c, l, l.vram_base, 0, unit(l), c.bounds, b.data(), v_done, v_to, T, err)) return false;
                prof_mark(d, 3);
            }
            v_done = v_to;
        }
        if (!run_set(d, c, l, l.vram_base, 0, unit(l), c.bounds, b.data(), v_done, L0.n_slots, T, err)) return false;
        if (pfh) {   // DS4_PF_HELPER: the helpers' sums joined after this member's streamed runs (none: as pf1)
            const double tw = now_ms();
            for (size_t h = (size_t) mi; h < hlp.size(); h += (size_t) nm) {   // (helper h's sums on member h % nm, in helper order)
                if (hlp.pf_tokens(h) <= 0) continue;
                if (!hlp.pf_wait(h)) {
                    err = "DS4_PF_HELPER: layer " + std::to_string(l.il) + ": helper " + std::to_string(h) + " failed";
                    return false;
                }
                strata_ds4_launch(pfh_add_k, dim3((unsigned) ((D / 4 + 255) / 256), (unsigned) T), 256, 0, s, c.acc,
                                  pfh_map_dev[(size_t) di][h], pfh_out_dev[(size_t) di][h], D);
            }
            pfh_wait_ms[(size_t) di] += now_ms() - tw;
            prof_mark(d, 13);   // (DS4_PROF: the helpers' wait in the streamed experts' stage)
        }
        if (nm > 1) {   // (DS4_PROF: stage 12, the MoE's all-reduce)
            prof_mark(d, 3);
            allreduce(c.acc, T * D, ab, mi, ++c.arb_seq, d.xcnt, s);
            prof_mark(d, 12);
        }
        hc_post_inplace(c.acc, c.h, c.f_post, c.f_comb, D, H, T, s);
        CK(cudaMemcpyAsync(c.pre, c.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));
        prof_mark(d, 3);
        return true;
    }

    // the CPU lane's experts of every layer, in index order, and each expert's virtual slot (before a chunk)
    void plan_streams() {
        for (Layer& l : L) {
            if (l.mtp || l.vs_pin == nullptr) continue;
            l.host_list.clear();
            for (int e = 0; e < l.n_exp; ++e)
                if (l.slot[(size_t) e] < 0) l.host_list.push_back(e);
            for (int m = 0; m < l.nm; ++m) {   // (a group's members: each its own copy)
                Layer& x = member(l, m);
                int j = 0;
                for (int e = 0; e < l.n_exp; ++e) x.vs_pin[e] = l.slot[(size_t) e] >= 0 ? l.slot[(size_t) e] : l.n_slots + j++;
            }
        }
    }

    // a chunk's hand-off between groups: h | pre | topk | cand of a chunk of T rows
    Xfer chunk_xfer(uint8_t* host, Chunk& c, int T, bool put) const {
        const size_t nh = (size_t) T * g.hc * g.dim * 4, np = (size_t) T * 8 * 4, nk = (size_t) T * topk_stride() * 4,
                     nc = (size_t) T * cand_stride() * 4;
        void* dv[4] = {c.h, c.pre, c.topk, c.cand};
        uint8_t* hv[4] = {host, host + nh, host + nh + np, host + nh + np + nk};
        const size_t nb[4] = {nh, np, nk, nc};
        Xfer x;
        x.n = 4;
        for (int i = 0; i < 4; ++i) {
            x.src[i] = put ? (const void*) dv[i] : (const void*) hv[i];
            x.dst[i] = put ? (void*) hv[i] : dv[i];
            x.bytes[i] = nb[i];
        }
        return x;
    }

    // a run of chunks (start positions p0[k], sizes T[k], seqs seq[k]) on device di: its layers chunk after chunk, the
    // groups pipelined (a group takes chunk k + 1 while the next takes chunk k: the hand-offs and the sources' rows
    // two deep, each slot reused once its readers acknowledged it), the streamed experts' copies running ahead across
    // layers and chunks
    struct Run {
        std::vector<int64_t> p0;
        std::vector<int> T;
        std::vector<unsigned> seq;
        int64_t snap_pos = -1;   // feed_mark: the position whose state before it the layers keep (-1: none)
        // a long prompt's skip (forward_chunks): the cut at row cut_r of chunk cut_k - the chunks before it go through
        // the layers before `yoco`, that layer as layer_chunk's kv_only and none after it; chunk cut_k's rows before
        // cut_r the same, its rows from cut_r on and the chunks after it through every layer (yoco -1: no skip)
        int yoco = -1, cut_k = 0, cut_r = 0;
        bool runs(int k, int il) const { return yoco < 0 || k >= cut_k || il <= yoco; }
        bool kv_only(int k, int il) const { return yoco >= 0 && k < cut_k && il == yoco; }
        int r0(int k, int il) const { return yoco >= 0 && k == cut_k && il >= yoco ? cut_r : 0; }   // the first row
    };
    // layer L0 over chunk k per a long prompt's skip (Run): its kv_only, or its rows from Run::r0 on - the chunk's
    // buffers seen from that row (the yoco layer: its kv_only over the rows before it first)
    bool run_layer(Layer& L0, int mi, int64_t p0, int T, const WinPlan& wp, Streamer& S, std::string& err,
                   const Run& run, int k, int il) {
        if (run.kv_only(k, il)) return layer_chunk(L0, mi, p0, T, wp, S, err, true);
        const int r0 = run.r0(k, il);
        if (r0 <= 0) return layer_chunk(L0, mi, p0, T, wp, S, err);
        if (il == run.yoco) {
            WinPlan w0 = wp;
            w0.snap_t = -1;
            if (!layer_chunk(L0, mi, p0, r0, w0, S, err, true)) return false;
        }
        Chunk& c = *chunks[(size_t) member(L0, mi).dev];
        float* const h0 = c.h;
        float* const pre0 = c.pre;
        c.h += (size_t) r0 * g.hc * g.dim;
        c.pre += (size_t) r0 * 8;
        WinPlan w1 = wp;
        w1.snap_t = wp.snap_t >= r0 ? wp.snap_t - r0 : -1;
        const bool ok = layer_chunk(L0, mi, p0 + r0, T - r0, w1, S, err);
        c.h = h0;
        c.pre = pre0;
        return ok;
    }

    // layer-major (c.lm: a run of several chunks, device di every trunk layer, the flow set up by run_dev_chunks):
    // layer after layer, each through all the chunks in order - a chunk's state to host memory after each of its
    // layers and back before the next - so a layer's experts are read from the files once for the whole run (the
    // layer cache keeps what a chunk read for the chunks after it), where chunk after chunk reads them once a chunk
    bool run_dev_layers(int di, const Run& run, std::string& err) {
        Dev& d = devs[(size_t) di];
        Chunk& c = *chunks[(size_t) di];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int D = g.dim, H = g.hc, nk = (int) run.T.size();
        Streamer S;   // (none: the flow streams)
        const size_t hb = chunk_hand_bytes();
        // the Engram rows: (layer, chunk) after (layer, chunk) in the run's order, each read on a helper thread while
        // the one before runs (slot u % 2, once unit u - 2's copy of it is done)
        std::vector<std::pair<int, int>> egu;   // (Engram layer, chunk)
        for (int il : c.fl_layers)
            if (L[(size_t) il].eg >= 0)
                for (int k = 0; k < nk; ++k)
                    if (run.runs(k, il)) egu.push_back({L[(size_t) il].eg, k});
        const size_t eg_per = (size_t) (pk.eg_ngram - 1) * pk.eg_heads * (pk.eg_hd + pk.eg_hd / 32);
        auto read_eg = [this, &c, &run, &egu, eg_per](size_t u) {
            if (u >= 2) cudaEventSynchronize(c.eg_ev[u % 2]);
            const int li = egu[u].first, k = egu[u].second;
            engram_rows(run.p0[(size_t) k], run.T[(size_t) k], li, c.eg_host[u % 2] + (size_t) li * c.C * eg_per);
        };
        size_t eg_u = 0;
        std::future<void> eg_next;
        if (!egu.empty()) eg_next = std::async(std::launch::async, read_eg, (size_t) 0);
        for (size_t li = 0; li < c.fl_layers.size(); ++li) {
            const int il = c.fl_layers[li];
            Layer& L0 = L[(size_t) il];
            const bool last_l = li + 1 == c.fl_layers.size();
            for (int k = 0; k < nk; ++k) {
                if (!run.runs(k, il)) continue;   // (a skipped early chunk: nothing after the yoco layer)
                if (halt_now()) return halt_end(di, err);   // (a Stop: one GPU, this one)
                const int64_t p0 = run.p0[(size_t) k];
                const int T = run.T[(size_t) k], slot = k % 2;
                const bool last_k = k + 1 == nk;
                WinPlan wp;
                wp.par = true;
                wp.async = true;
                wp.win = run.seq[(size_t) k];
                wp.k = k;
                wp.snap_t = run.snap_pos >= p0 && run.snap_pos < p0 + T ? (int) (run.snap_pos - p0) : -1;
                if (L0.eg >= 0) {   // this unit's rows ready, the next one's on their way
                    const double te = now_ms();
                    eg_next.get();
                    st.engram_ms += now_ms() - te;
                    wp.eg_slot = (int) (eg_u % 2);
                    if (++eg_u < egu.size()) eg_next = std::async(std::launch::async, read_eg, eg_u);
                }
                if (li == 0) {   // the chunk's input: its embedding rows
                    if (k >= 2) CK(cudaEventSynchronize(c.emb_ev[slot]));
                    for (int t = 0; t < T; ++t)
                        std::memcpy(c.emb_host[slot] + (size_t) t * D, emb_row(p0 + t, toks[(size_t) (p0 + t)]),
                                    (size_t) D * 2);
                    CK(cudaMemcpyAsync(c.emb, c.emb_host[slot], (size_t) T * D * 2, cudaMemcpyHostToDevice, s));
                    CK(cudaEventRecord(c.emb_ev[slot], s));
                    embed(c.emb, T, c.h, D, H, s);
                    if (ds4_dbg("DS4_DBG_EMB")) {
                        ds4_metal_flush();
                        float *hp = c.h;
                        float hh[4] = {0,0,0,0};
                        cudaMemcpy(hh, hp, sizeof(hh), cudaMemcpyDeviceToHost);
                        std::fprintf(stderr, "DBG at embed site %d: h[0..3] = %g %g %g %g\n", __LINE__, hh[0], hh[1], hh[2], hh[3]);
                    }
                    init_pre(c.pre, T, s);
                } else {   // or its state after the layer before
                    const Xfer x = chunk_xfer(c.lm_state + (size_t) k * hb, c, T, false);
                    for (int i = 0; i < x.n; ++i)
                        CK(cudaMemcpyAsync(x.dst[i], x.src[i], x.bytes[i], cudaMemcpyHostToDevice, s));
                }
                if (last_k && g.n_mtp > 0 && !o.dspark_noseed) {   // the drafter's taps: the last chunk's last rows
                    const auto it = std::find(g.d_targets.begin(), g.d_targets.end(), il);
                    if (it != g.d_targets.end()) {
                        const size_t j = (size_t) (it - g.d_targets.begin()), nt = g.d_targets.size();
                        const int nr = std::min(T, tap_cap);
                        hc_mean(c.h + (size_t) (T - nr) * H * D, nr, H, D, d.tap, D, s);
                        CK(cudaStreamWaitEvent(s, ev_seed, 0));
                        CK(cudaMemcpy2DAsync(h_taps + j * D, nt * D * 4, d.tap, (size_t) D * 4, (size_t) D * 4,
                                             (size_t) nr, cudaMemcpyDeviceToHost, s));
                    }
                }
                const bool kvo = run.kv_only(k, il);
                if (!run_layer(L0, 0, p0, T, wp, S, err, run, k, il)) return false;
                if (dump_l != nullptr) dump_layer(d, c.h, il, p0, T);
                if (kvo) continue;   // (no layer after it reads this chunk's state)
                if (!last_l) {   // the chunk's state kept for the next layer
                    const Xfer x = chunk_xfer(c.lm_state + (size_t) k * hb, c, T, true);
                    for (int i = 0; i < x.n; ++i)
                        CK(cudaMemcpyAsync(x.dst[i], x.src[i], x.bytes[i], cudaMemcpyDeviceToHost, s));
                    continue;
                }
                // through every layer: the chunk's end, and the logits
                if ((size_t) k < chunk_done.size()) {
                    CK(cudaEventRecord(chunk_done[(size_t) k], s));
                    chunk_rec[(size_t) k].store(1, std::memory_order_release);
                }
                if (logits_all) {   // every row's logits (tests): the head over the chunk's rows, 16 at a time
                    const size_t base = (size_t) (p0 - run.p0[0]) * g.vocab;
                    for (int r0 = 0; r0 < T; r0 += kWin) {
                        const int nr = std::min(kWin, T - r0);
                        hc_pre_norm(c.h + (size_t) r0 * H * D, c.pre + (size_t) r0 * 8, d.norm_w, D, H, nr, g.eps, d.x, s);
                        if (!head_share(d, d.mi, d.x, nr, err)) return false;
                        CK(cudaMemcpyAsync(chunk_logits.data() + base + (size_t) r0 * g.vocab, d.logits,
                                           (size_t) nr * g.vocab * 4, cudaMemcpyDeviceToHost, s));
                        CK(cudaStreamSynchronize(s));
                    }
                } else if (last_k && n_logits > 0) {   // (the last rows' logits, into the window path's buffers)
                    const int t0 = T - n_logits;
                    hc_pre_norm(c.h + (size_t) t0 * H * D, c.pre + (size_t) t0 * 8, d.norm_w, D, H, n_logits, g.eps, d.x, s);
                    if (!head_share(d, d.mi, d.x, n_logits, err)) return false;
                }
            }
            lm_layers.store((int) li + 1, std::memory_order_release);
        }
        return true;
    }
    bool run_dev_chunks(int di, const Run& run, std::string& err) {
        Dev& d = devs[(size_t) di];
        Chunk& c = *chunks[(size_t) di];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int D = g.dim, H = g.hc, nk = (int) run.T.size();
        Streamer S;
        const int B = std::max(1, c.ring_n / Chunk::kParts);
        c.dbg_stage_ms = c.dbg_dma_ms = c.dbg_evt_ms = 0;   // (the run's own, not the process's)
        c.run_bytes = 0;
        c.run_direct = c.run_staged = 0;
        struct RunClock {   // (the device thread's time in the run, whichever way it ends)
            Chunk& c;
            double t0;
            ~RunClock() { c.run_ms = now_ms() - t0; }
        } run_clock{c, now_ms()};
        if (c.flow) {   // (the flow decides its streams as the layers route; nothing planned here)
            CK(cudaStreamSynchronize(s));
            CK(cudaStreamSynchronize(c.cs));
            c.items.clear();
            c.base = c.n_read = c.n_dma = c.n_comp = 0;
            c.n_file = 0;
            std::fill(c.stage_item.begin(), c.stage_item.end(), -1);
            c.fl_layers.clear();
            for (int il = 0; il < g.nl; ++il)   // (a group's layers: on each member)
                for (int m = 0; m < L[(size_t) il].nm; ++m)
                    if (member(L[(size_t) il], m).dev == di) c.fl_layers.push_back(il);
            c.fl_T = run.T;
            c.fl_yoco = run.yoco;
            c.fl_cut_k = run.cut_k;
            c.fl_cut_r = run.cut_r;
            c.spec_k = c.spec_il = -1;
            c.wait_ms = 0;
            c.it_file = c.it_ram = c.it_spec = c.it_spec_unused = c.it_lc = 0;
            c.lc_il = -1;
            c.lc_used = 0;
            c.lc_first = c.lc_chk = 0;
            c.io_d0 = c.io->direct_bytes();
            c.io_b0 = c.io->buffered_bytes();
            c.io_busy0 = c.io->busy_ms();
            if (!c.fl_layers.empty()) {
                flow_spec(c, 0, c.fl_layers[0], run.T[0]);
                if (!flow_pump(c, err)) return false;
            }
            if (c.lm) return run_dev_layers(di, run, err);
        }
        for (int k = 0; k < nk && !c.flow; ++k)
            for (int il = 0; il < g.nl; ++il) {
                if (!run.runs(k, il) || run.kv_only(k, il)) continue;   // (a long prompt's skip: no experts there)
                const Layer& L0 = L[(size_t) il];
                bool here = false;
                for (int m = 0; m < L0.nm; ++m) here = here || member(L0, m).dev == di;
                if (!here) continue;
                if (pfh_chunk(run.T[(size_t) k]) && pfh_layer_ok(L0)) {   // (DS4_PF_HELPER: the helpers take the held ones;
                    const int nh = (int) L0.host_list.size();             //  the runs of unheld ones stream, at most B a batch)
                    for (int j = 0; j < nh;) {
                        if (pfh_held(L0, L0.host_list[(size_t) j])) { ++j; continue; }
                        int j1 = j;
                        while (j1 < nh && j1 - j < B && !pfh_held(L0, L0.host_list[(size_t) j1])) ++j1;
                        S.b.push_back({k, il, j, j1 - j});
                        j = j1;
                    }
                    continue;
                }
                for (int j0 = 0; j0 < (int) L0.host_list.size(); j0 += B)
                    S.b.push_back({k, il, j0, std::min(B, (int) L0.host_list.size() - j0)});
            }
        if (!S.b.empty() && c.ring == nullptr) {
            err = "no slots to stream experts into on CUDA" + std::to_string(d.id);
            return false;
        }
        std::atomic<bool> ra_stop{false};
        std::thread ra;
        if (file_experts && !S.b.empty()) ra = std::thread([this, &S, di, &ra_stop] { read_ahead(S, di, ra_stop); });
        struct Join {   // (every way out of the run: the read-ahead ends before S does)
            std::atomic<bool>& stop;
            std::thread& th;
            ~Join() {
                stop.store(true);
                if (th.joinable()) th.join();
            }
        } ra_join{ra_stop, ra};
        if (!copy_ahead(d, c, S, di, err)) return false;
        // this device's Engram layers: chunk k's rows read on a helper thread while chunk k - 1 runs (slot k % 2, once
        // chunk k - 2's copy of it is done)
        std::vector<int> egs;
        for (const Layer& l0 : L)
            for (int m = 0; m < l0.nm; ++m)
                if (member(l0, m).dev == di && !l0.mtp && l0.eg >= 0) egs.push_back(l0.eg);
        const size_t eg_per = (size_t) (pk.eg_ngram - 1) * pk.eg_heads * (pk.eg_hd + pk.eg_hd / 32);
        auto read_eg = [this, &c, &run, &egs, eg_per](int k) {
            if (k >= 2) cudaEventSynchronize(c.eg_ev[k % 2]);
            for (int li : egs)
                engram_rows(run.p0[(size_t) k], run.T[(size_t) k], li, c.eg_host[k % 2] + (size_t) li * c.C * eg_per);
        };
        std::future<void> eg_next;
        if (!egs.empty()) eg_next = std::async(std::launch::async, read_eg, 0);
        for (int k = 0; k < nk; ++k) {
            if (!chunk_go(k)) return halt_end(di, err);   // (a Stop: the chunks every device reaches are done)
            const int64_t p0 = run.p0[(size_t) k];
            const int T = run.T[(size_t) k], slot = k % 2;
            const bool last_k = k + 1 == nk;
            if (!egs.empty()) {   // chunk k's rows ready, chunk k + 1's on their way
                const double te = now_ms();
                eg_next.get();
                if (d.mi == 0) st.engram_ms += now_ms() - te;
                if (k + 1 < nk) eg_next = std::async(std::launch::async, read_eg, k + 1);
            }
            WinPlan wp;
            wp.par = true;
            wp.async = true;
            wp.win = run.seq[(size_t) k];
            wp.k = k;
            wp.snap_t = run.snap_pos >= p0 && run.snap_pos < p0 + T ? (int) (run.snap_pos - p0) : -1;
            wp.pfh = !c.flow && pfh_chunk(T);   // (DS4_PF_HELPER: the planner's rule above, on the chunk's whole T)
            bool started = false;
            std::vector<char> got(srcs.size(), 0);
            for (int il = 0; il < g.nl && run.runs(k, il); ++il) {
                if (halt_now()) return halt_end(di, err);   // (one GPU: after the layer it is on)
                Layer& L0 = L[(size_t) il];
                int mi = -1;
                for (int m = 0; m < L0.nm; ++m)
                    if (member(L0, m).dev == di) mi = m;
                if (mi < 0) continue;
                if (!started) {   // the chunk's input: its embedding rows, or the previous group's hand-off
                    started = true;
                    if (il == 0) {
                        if (k >= 2) CK(cudaEventSynchronize(c.emb_ev[slot]));
                        for (int t = 0; t < T; ++t)
                            std::memcpy(c.emb_host[slot] + (size_t) t * D, emb_row(p0 + t, toks[(size_t) (p0 + t)]),
                                        (size_t) D * 2);
                        CK(cudaMemcpyAsync(c.emb, c.emb_host[slot], (size_t) T * D * 2, cudaMemcpyHostToDevice, s));
                        CK(cudaEventRecord(c.emb_ev[slot], s));
                        embed(c.emb, T, c.h, D, H, s);
                        if (ds4_dbg("DS4_DBG_EMB")) {
                            ds4_metal_flush();
                            float *hp = c.h;
                            float hh[4] = {0,0,0,0};
                            cudaMemcpy(hh, hp, sizeof(hh), cudaMemcpyDeviceToHost);
                            std::fprintf(stderr, "DBG at embed site %d: h[0..3] = %g %g %g %g\n", __LINE__, hh[0], hh[1], hh[2], hh[3]);
                        }
                        init_pre(c.pre, T, s);
                    } else {
                        Chunk& a = *chunks[(size_t) L[(size_t) il - 1].dev];
                        host_wait_at_least(a.hand_flag[slot], wp.win);
                        xfer_get(chunk_xfer(a.hand[slot], c, T, false), a.hand_flag[slot], wp.win, s);
                        set_flag(a.hand_ack + ((size_t) slot * 8 + mi) * 32, wp.win, s);
                    }
                }
                for (int sidx : {L0.src, L0.ix_src ? L0.ik_src : -1}) {
                    if (sidx < 0 || got[(size_t) sidx]) continue;
                    got[(size_t) sidx] = 1;
                    Src& sr = srcs[(size_t) sidx];
                    if (L[(size_t) sr.layer].grp == L0.grp) continue;
                    const int64_t g_first = p0 / sr.ratio;
                    const int ng = (int) std::max<int64_t>(0, (p0 + T) / sr.ratio - g_first);
                    Xfer x;
                    if (ng > 0 && sr.ckv[(size_t) di] != nullptr) {
                        x.src[x.n] = sr.stage(slot);
                        x.dst[x.n] = sr.ckv[(size_t) di] + (size_t) g_first * ckv_rb();
                        x.bytes[x.n++] = (size_t) ng * ckv_rb();
                    }
                    if (ng > 0 && sr.ik[(size_t) di] != nullptr) {
                        x.src[x.n] = sr.stage(slot) + x_cap() * ckv_rb();
                        x.dst[x.n] = sr.ik[(size_t) di] + (size_t) g_first * ik_rb();
                        x.bytes[x.n++] = (size_t) ng * ik_rb();
                    }
                    if (x.n > 0) {
                        host_wait_at_least(sr.flag(slot), wp.win);
                        xfer_get(x, sr.flag(slot), wp.win, s);
                    }
                    set_flag(sr.x_ack + ((size_t) slot * devs.size() + di) * 32, wp.win, s);   // (taken, or none)
                }
                if (last_k && mi == 0 && g.n_mtp > 0 && !o.dspark_noseed) {   // the drafter's taps: the last chunk's last rows
                    const auto it = std::find(g.d_targets.begin(), g.d_targets.end(), il);
                    if (it != g.d_targets.end()) {
                        const size_t j = (size_t) (it - g.d_targets.begin()), nt = g.d_targets.size();
                        const int nr = std::min(T, tap_cap);
                        hc_mean(c.h + (size_t) (T - nr) * H * D, nr, H, D, d.tap, D, s);
                        CK(cudaStreamWaitEvent(s, ev_seed, 0));
                        CK(cudaMemcpy2DAsync(h_taps + j * D, nt * D * 4, d.tap, (size_t) D * 4, (size_t) D * 4,
                                             (size_t) nr, cudaMemcpyDeviceToHost, s));
                    }
                }
                if (!run_layer(L0, mi, p0, T, wp, S, err, run, k, il)) return false;
                if (dump_l != nullptr && mi == 0) dump_layer(d, c.h, il, p0, T);
                const bool last = il + 1 == g.nl || L[(size_t) il + 1].grp != L0.grp;
                if (last && mi == 0 && il + 1 < g.nl) {   // the hand-off, once the next group took the chunk before last
                    const int nnext = L[(size_t) il + 1].nm;
                    if (k >= 2) {
                        for (int m = 0; m < nnext; ++m)
                            host_wait_at_least(c.hand_ack + ((size_t) slot * 8 + m) * 32, wp.win - 2);
                        wait_flags(c.hand_ack + (size_t) slot * 8 * 32, nnext, 32, wp.win - 2, s);
                    }
                    xfer_put(chunk_xfer(c.hand[slot], c, T, true), c.hand_flag[slot], wp.win, d.xcnt, s);
                }
            }
            if (di == head_dev && (size_t) k < chunk_done.size()) {
                CK(cudaEventRecord(chunk_done[(size_t) k], s));
                chunk_rec[(size_t) k].store(1, std::memory_order_release);
            }
            if (d.grp == devs[(size_t) head_dev].grp) {   // the head group: each member its share of the logits
                if (logits_all) {   // every row's logits (tests): the head over the chunk's rows, 16 at a time
                    const size_t base = (size_t) (p0 - run.p0[0]) * g.vocab;
                    for (int r0 = 0; r0 < T; r0 += kWin) {
                        const int nr = std::min(kWin, T - r0);
                        hc_pre_norm(c.h + (size_t) r0 * H * D, c.pre + (size_t) r0 * 8, d.norm_w, D, H, nr, g.eps, d.x, s);
                        if (!head_share(d, d.mi, d.x, nr, err)) return false;
                        if (di != head_dev) continue;
                        CK(cudaMemcpyAsync(chunk_logits.data() + base + (size_t) r0 * g.vocab, d.logits,
                                           (size_t) nr * g.vocab * 4, cudaMemcpyDeviceToHost, s));
                        CK(cudaStreamSynchronize(s));
                    }
                } else if (last_k && n_logits > 0) {   // (the last rows' logits, into the window path's buffers)
                    const int t0 = T - n_logits;
                    hc_pre_norm(c.h + (size_t) t0 * H * D, c.pre + (size_t) t0 * 8, d.norm_w, D, H, n_logits, g.eps, d.x, s);
                    if (!head_share(d, d.mi, d.x, n_logits, err)) return false;
                }
            }
        }
        return true;
    }

    // ---- a prompt's path: the flow or windows of 16
    // this PC's speeds for pick_path (every device on the flow, the experts in place): the DMA from pinned staging to a
    // GPU; the readers copying RAM into staging; the disk read by them (experts not in RAM); the CPU lane on experts in
    // RAM and on ones it reads from the disk first - each timed once, a few experts' worth (DS4_PATH_PICK=0: always the
    // flow, as before)
    void calibrate_paths() {
        if (chunk <= 0 || chunk_min != kFlowChunkMin || std::getenv("DS4_CHUNK_MIN") != nullptr) return;
        if (const char* v = std::getenv("DS4_PATH_PICK"))
            if (std::atoi(v) == 0) return;
        int di = -1;
        for (size_t i = 0; i < chunks.size() && di < 0; ++i)
            if (chunks[i] != nullptr && chunks[i]->flow && chunks[i]->S >= 2) di = (int) i;
        if (di < 0) return;
        Chunk& c = *chunks[(size_t) di];
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        const double t0 = now_ms();
        // the DMA: staging -> the ring (once to warm up, once timed)
        const size_t nb = std::min({(size_t) 256 << 20, (size_t) c.S * c.stage_stride, (size_t) c.ring_n * c.ring_stride});
        double ms = 0;
        for (int rep = 0; rep < 2; ++rep) {
            const double a = now_ms();
            if (cudaMemcpyAsync(c.ring, c.stage, nb, cudaMemcpyHostToDevice, c.cs) != cudaSuccess ||
                cudaStreamSynchronize(c.cs) != cudaSuccess) {
                cudaGetLastError();
                return;
            }
            ms = now_ms() - a;
        }
        pm.dma = (double) nb / std::max(1e-3, ms / 1000.0);
        // the readers: RAM -> staging (a buffer of its own, touched first), in as many jobs as they are
        auto run_jobs = [&](std::vector<IoQueue::Job>& jobs, std::atomic<int>& left) {
            const double a = now_ms();
            left.store((int) jobs.size());
            c.io->push(jobs.data(), (int) jobs.size());
            while (left.load(std::memory_order_acquire) != 0) c.io->wait_any(500);
            return now_ms() - a;
        };
        {
            const size_t part = std::min(nb, (size_t) 64 << 20) / 8 / 4096 * 4096;
            std::vector<uint8_t> src(part * 8, 1);
            std::vector<IoQueue::Job> jobs(8);
            std::atomic<int> left{0};
            std::atomic<bool> bad{false};
            for (int i = 0; i < 8; ++i) {
                jobs[(size_t) i].mem = src.data() + (size_t) i * part;
                jobs[(size_t) i].dst = c.stage + (size_t) i * part;
                jobs[(size_t) i].len = part;
                jobs[(size_t) i].left = &left;
                jobs[(size_t) i].bad = &bad;
            }
            run_jobs(jobs, left);
            const double t1 = run_jobs(jobs, left), t2 = run_jobs(jobs, left);
            pm.copy = (double) (part * 8) / std::max(1e-3, std::min(t1, t2) / 1000.0);
        }
        // experts not in RAM (none of their sampled pages resident), of the trunk layer with the most CPU-lane ones:
        // up to min(8, staging slots) read by the readers as the flow reads them, then 8 others through the CPU lane
        // three times (from the disk, then in RAM: the faster of two)
        int best = -1, most = 0;
        for (int il = 0; il < g.nl; ++il) {
            int n = 0;
            for (int e = 0; e < L[(size_t) il].n_exp; ++e) n += L[(size_t) il].slot[(size_t) e] < 0;
            if (n > most) most = n, best = il;
        }
        if (best < 0) return;
        const Layer& l = L[(size_t) best];
        std::vector<int> cold;
        const int n_read = std::min(8, c.S), n_cpu = 8;
        for (int e = 0; e < l.n_exp && (int) cold.size() < n_read + n_cpu; ++e) {
            if (l.slot[(size_t) e] >= 0 || (!l.ram.empty() && l.ram[(size_t) e] >= 0)) continue;
            bool res = false;
            for (int r = 0; r < 3; ++r) res = res || os::resident_sampled(mx_mat(l, e, r), mx_part_bytes(l, r), 4);
            if (!res) cold.push_back(e);
        }
        if ((int) cold.size() >= n_read + n_cpu) {
            std::vector<IoQueue::Job> jobs;
            std::atomic<int> left{0};
            std::atomic<bool> bad{false};
            for (int i = 0; i < n_read; ++i) {
                uint8_t* sb = c.stage + (size_t) i * c.stage_stride;
                for (int r = 0; r < 3; ++r) {
                    IoQueue::Job j;
                    const os::fd_t pf = pk.pfds.empty() ? os::kBadFd : pk.pfds[(size_t) l.mx_file[r]];
                    j.fd = pf != os::kBadFd ? pf : pk.fds[(size_t) l.mx_file[r]];
                    j.dfd = pk.dfds.empty() ? os::kBadFd : pk.dfds[(size_t) l.mx_file[r]];
                    j.off = l.mx_off[r] + (uint64_t) cold[(size_t) i] * l.mx_stride[r];
                    j.len = mx_part_bytes(l, r);
                    j.dst = sb;
                    j.left = &left;
                    j.bad = &bad;
                    j.map = pk.at(l.mx_file[r], j.off);
                    jobs.push_back(j);
                    sb += flow_region(r);
                }
            }
            const double rd = run_jobs(jobs, left);
            if (!bad.load()) pm.disk = (double) n_read * (double) l.blob / std::max(1e-3, rd / 1000.0);
        }
        {   // the CPU lane: entries of one token (as most of a window's are), from the disk (if any were cold), then RAM
            const size_t first = (int) cold.size() >= n_read + n_cpu ? (size_t) n_read : 0;
            std::vector<Ent> ents;
            for (int i = 0; i < n_cpu; ++i) {
                Ent en;
                en.e = first + (size_t) i < cold.size() ? cold[first + (size_t) i] : -1;
                if (en.e < 0)   // (no cold ones: the first CPU-lane experts, wherever they are)
                    for (int e = 0, k = 0; e < l.n_exp && en.e < 0; ++e)
                        if (l.slot[(size_t) e] < 0 && k++ == i) en.e = e;
                if (en.e < 0) break;
                en.n = 1;
                en.slot0 = i;
                en.tok[0] = 0;
                ents.push_back(en);
            }
            if (ents.empty()) return;
            std::vector<float> x((size_t) g.dim);
            for (size_t i = 0; i < x.size(); ++i) x[i] = 0.02f * std::sin(0.37f * (float) i);
            const double bytes = (double) ents.size() * (double) l.blob;
            double a = now_ms();
            cpu_experts(l, x.data(), ents, (size_t) g.dim);
            const double t_first = now_ms() - a;
            double t_warm = 1e30;
            for (int rep = 0; rep < 2; ++rep) {
                a = now_ms();
                cpu_experts(l, x.data(), ents, (size_t) g.dim);
                t_warm = std::min(t_warm, now_ms() - a);
            }
            pm.cpu = bytes / std::max(1e-3, t_warm / 1000.0);
            if (first > 0 || (int) cold.size() >= n_cpu) pm.cpu_cold = bytes / std::max(1e-3, t_first / 1000.0);
        }
        pm.on = pm.dma > 0 && pm.copy > 0 && pm.cpu > 0;
        if (o.verbose) {
            char dk[32] = "not measured", cc[32] = "not measured";
            if (pm.disk > 0) std::snprintf(dk, sizeof dk, "%.2f GB/s", pm.disk / 1e9);
            if (pm.cpu_cold > 0) std::snprintf(cc, sizeof cc, "%.2f GB/s", pm.cpu_cold / 1e9);
            std::fprintf(stderr,
                         "ds4: prompts through the flow or windows by this PC's speeds: DMA %.1f GB/s, RAM to staging "
                         "%.1f GB/s, the disk %s; the CPU lane %.1f GB/s in RAM, %s from the disk (%.0f ms)\n",
                         pm.dma / 1e9, pm.copy / 1e9, dk, pm.cpu / 1e9, cc, now_ms() - t0);
        }
    }
    // layer l's CPU-lane experts (VRAM holds the rest) and the chance a token picks a given one of them: the profile's
    // share of the layer's picks they took, spread evenly over them, times pm.m (what the flow's runs found)
    double pm_rate(const Layer& l, int& n_cold) const {
        const uint32_t* pr = prof.data() + (size_t) l.il * g.n_exp;
        double sum = 0, cold = 0;
        n_cold = 0;
        for (int e = 0; e < l.n_exp; ++e) {
            sum += pr[e];
            if (l.slot[(size_t) e] < 0) cold += pr[e], ++n_cold;
        }
        if (n_cold == 0) return 0.0;
        const double share = sum > 0 && cold > 0 ? cold / sum : (double) n_cold / l.n_exp;
        return pm.m * (double) l.k_exp * share / n_cold;
    }
    // the CPU-lane experts n tokens pick in the trunk's layers, expected (each layer's n_cold (1 - e^(-rate n)))
    double pm_picks(int n) const {
        double d = 0;
        for (int il = 0; il < g.nl; ++il) {
            int nc = 0;
            const double a = pm_rate(L[(size_t) il], nc);
            d += nc * (1.0 - std::exp(-a * n));
        }
        return d;
    }
    // a run of one chunk of n tokens on the flow picked `picked` CPU-lane experts: pm.m to what makes the expectation
    // that (bisection over its log; a running mean of the log)
    void pm_learn(int n, double picked) {
        if (!pm.on || n < 2 || picked < 1) return;
        const double m0 = pm.m;
        double lo = std::log(1e-3), hi = std::log(1e3);
        for (int it = 0; it < 40; ++it) {
            pm.m = std::exp(0.5 * (lo + hi));
            (pm_picks(n) < picked ? lo : hi) = 0.5 * (lo + hi);
        }
        const double obs = 0.5 * (lo + hi);
        pm.m = std::exp(pm.n_m == 0 ? obs : 0.7 * std::log(m0) + 0.3 * obs);
        ++pm.n_m;
    }
    // a prompt of n tokens that the flow could take (n >= chunk_min): true the flow, false windows of 16 - each path's
    // time predicted from the bytes of CPU-lane experts it would move (the flow: each picked one once, n_cold (1 -
    // e^(-rate n)) a layer, pm_rate) or compute (windows: each window's own picks), those in RAM (each layer's share:
    // sampled pages of up to 32 of its CPU-lane experts, mincore / QueryWorkingSetEx; the RAM tier's) and those not at
    // this PC's speeds - the flow's times what it really took against its predictions so far for prompts of that size
    // (pm_k), windows' once some ran what a window took times the windows; the flow unless windows are predicted
    // faster (by half, with less than kPickRes in RAM); said with --verbose
    // The choice is made from the prompt's length alone (pick_flow_min): the same prompt takes the same path - and so
    // gives the same bits, the two paths round differently - in every session and on every restart.  The timing prediction below
    // (DS4_PICK=adaptive) used measured speeds and sampled page residency, so it flipped between runs: r9700, one 16-token feed
    // through the flow in one run, another feed in the next, three different logits checksums in six runs.  Measured on 4 and 1 R9700
    // (first prompt of a run, windows against the flow, ms): 28 tokens 594 / 4966 (4 cards), 1094 / 5588 (1 card); 100: 1164 / 5375,
    // 3279 / 7299; 300: 2831 / 5874, 9018 / 9803; 600: 5304 / 6808, 16969 / 11327; 1500: 13325 / 8012, 41547 / 18187 - the flow pays a
    // fixed ~5 s the first time (its buffers and GEMM libraries), then wins from about 400 tokens up.
    // The length from which the flow is taken: one number for every box (ds4_pick_rule.hpp says why 96), DS4_PICK_MIN=N overrides.
    int pick_flow_min() {
        if (pick_min_ > 0) return pick_min_;
        pick_min_ = prompt_flow_min(std::getenv("DS4_PICK_MIN"));
        std::fprintf(stderr, "ds4: prompt path: the chunked pass from %d tokens, windows of 16 below\n", pick_min_);
        return pick_min_;
    }
    int pick_min_ = 0;
    bool pick_path(int n) {
        static const bool adaptive = [] {
            const char* e = std::getenv("DS4_PICK");
            return e != nullptr && std::strcmp(e, "adaptive") == 0;
        }();
        pm.last = -1;
        if (!adaptive) return n >= pick_flow_min();
        if (!pm.on || n >= kPickMax) return true;
        double f_res = 0, f_cold = 0, w = 0;
        const int nw = n / kWin, rem = n % kWin;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            int nc = 0;
            const double a = pm_rate(l, nc);
            if (nc == 0) continue;
            int sampled = 0, res = 0, seen = 0;
            const int step = std::max(1, nc / 32);
            for (int e = 0; e < l.n_exp; ++e) {
                if (l.slot[(size_t) e] >= 0 || seen++ % step != 0) continue;
                bool r = !l.ram.empty() && l.ram[(size_t) e] >= 0;
                if (!r) {
                    r = true;
                    for (int p = 0; p < 3 && r; ++p) r = os::resident_sampled(mx_mat(l, e, p), mx_part_bytes(l, p), 2);
                }
                ++sampled;
                res += r;
            }
            const double share = sampled > 0 ? (double) res / sampled : 0.0, b = (double) l.blob;
            auto u = [&](int t) { return nc * (1.0 - std::exp(-a * t)); };
            f_res += share * u(n) * b;
            f_cold += (1.0 - share) * u(n) * b;
            w += ((double) nw * u(kWin) + (rem > 0 ? u(rem) : 0.0)) * b;
        }
        const double r_fr = std::min(pm.copy, pm.dma), r_fc = pm.disk > 0 ? std::min(pm.disk, pm.dma) : r_fr;
        const double r_wc = pm.cpu_cold > 0 ? pm.cpu_cold : 1.0 / (1.0 / r_fc + 1.0 / pm.cpu);
        const double t_flow = f_res / r_fr + f_cold / r_fc;
        const double t_win = std::max(0.0, w - f_cold) / pm.cpu + f_cold / r_wc;
        const int cls = pm_cls(n), n_win = (n + kWin - 1) / kWin;
        // (windows: once some ran, what a window took on average times the windows the prompt needs - each pays the
        // fixed costs of every layer on every GPU again, which a pass of the flow pays once)
        const double pf = pm_k(cls) * t_flow, pw = pm.win_n > 0 ? pm.win_s * n_win : t_win;
        // (the flow unless windows are predicted faster - in half its time at least, unless kPickRes of the CPU-lane
        // experts' bytes are in RAM: the flow wins on every PC whose experts come from an SSD, where a wrong pick would
        // cost the most; windows win where they are all in RAM)
        const double res_share = f_res / std::max(1.0, f_res + f_cold);
        const bool flow = !(pw < pf && (res_share >= kPickRes || 2.0 * pw <= pf));
        pm.last = flow ? 1 : 0;
        pm.last_cls = cls;
        pm.last_nw = n_win;
        pm.last_pred = flow ? t_flow : t_win;
        if (o.verbose)
            std::fprintf(stderr,
                         "ds4: a prompt of %d tokens through %s: predicted %.2f s, %s %.2f s (%.0f%% of its CPU-lane "
                         "experts' %.1f GB in RAM)\n",
                         n, flow ? "the flow" : "windows", flow ? pf : pw, flow ? "windows" : "the flow", flow ? pw : pf,
                         100.0 * res_share, (f_res + f_cold) / 1e9);
        return flow;
    }
    // a prompt's size class for pm.k: 2-31, 32-127, 128-511, 512 tokens and more
    static int pm_cls(int n) { return n < 32 ? 0 : n < 128 ? 1 : n < 512 ? 2 : 3; }
    // the flow's time factor for size class c: its own, else its nearest class's, else 1 (never the windows': theirs
    // is mostly the fixed costs a window pays again and again)
    double pm_k(int c) const {
        for (int dc = 0; dc < 4; ++dc)
            for (int cc : {c - dc, c + dc})
                if (cc >= 0 && cc < 4 && pm.kn[0][cc] > 0) return pm.k[0][cc];
        return 1.0;
    }
    // n tokens through windows of 16, the last one's logits_rows rows of logits
    bool feed_windows(const int* tokens, int n, int logits_rows, std::string& err) {
        logits_all = false;
        for (int a = 0; a < n; a += kWin) {
            const int T = std::min(kWin, n - a);
            if (!forward(tokens + a, T, a + T == n ? logits_rows : 0, err)) return false;
        }
        return true;
    }
    // the picked path took ms: the flow's predictions for the prompt's size class scaled by what it really takes (taken
    // / predicted), windows' time a window - running means
    void path_done(double ms) {
        if (pm.last < 0 || pm.last_pred <= 0) return;
        if (pm.last == 0) {
            const double w = ms / 1000.0 / std::max(1, pm.last_nw);
            pm.win_s = pm.win_n == 0 ? w : 0.7 * pm.win_s + 0.3 * w;
            ++pm.win_n;
        } else {
            const double ratio = std::min(8.0, std::max(0.25, ms / 1000.0 / pm.last_pred));
            double& k = pm.k[0][pm.last_cls];
            int64_t& n = pm.kn[0][pm.last_cls];
            k = n == 0 ? ratio : 0.7 * k + 0.3 * ratio;
            ++n;
        }
        pm.last = -1;
    }
    // a run layer-major? - one device holding every layer on the flow, several chunks, and what the chunks after the
    // first would read from the files again more than the chunks' states moved to host memory and back at every layer
    // (DS4_LAYER_MAJOR=0: never); then its host memory: the chunks' states (pinned, else pageable) and the layer cache,
    // the largest layer's experts read from the files if RAM allows (ram_avail() less kRamMargin; DS4_LAYER_CACHE_MB
    // sets it) - at least one expert, or not layer-major
    bool lm_begin(const Run& run) {
        static const char* env = std::getenv("DS4_LAYER_MAJOR");
        if (devs.size() != 1 || run.T.size() < 2 || (env != nullptr && std::atoi(env) == 0)) return false;
        Chunk& c = *chunks[0];
        if (!c.flow) return false;
        size_t need = 0, n_exp = 0, blob_max = 0;
        double file_b = 0;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            size_t ne = 0;
            for (int e : l.host_list)
                if (l.ram.empty() || l.ram[(size_t) e] < 0) ++ne;
            const size_t stride = (l.blob + 63) & ~(size_t) 63;
            need = std::max(need, ne * stride);
            n_exp = std::max(n_exp, (size_t) l.n_exp);
            blob_max = std::max(blob_max, stride);
            file_b += (double) ne * (double) l.blob;
        }
        int64_t rows = 0;
        for (int T : run.T) rows += T;
        const size_t hb = chunk_hand_bytes(), state_b = run.T.size() * hb;
        const double moved = 2.0 * (double) rows * ((double) hb / (double) chunk) * (double) g.nl;
        if (need == 0 || (double) (run.T.size() - 1) * file_b <= moved) return false;
        size_t lc_bytes = need;
        if (const char* mb = std::getenv("DS4_LAYER_CACHE_MB")) lc_bytes = std::min(need, (size_t) std::atoll(mb) << 20);
        else {
            const uint64_t avail = ram_avail();
            if (avail != ~uint64_t{0})
                lc_bytes = std::min<uint64_t>(need, avail > kRamMargin + state_b ? avail - kRamMargin - state_b : 0);
        }
        if (lc_bytes < blob_max) return false;
        void* st_p = nullptr;
        c.lm_pinned = cudaHostAlloc(&st_p, state_b, cudaHostAllocPortable) == cudaSuccess;
        if (!c.lm_pinned) {
            cudaGetLastError();
            st_p = os::anon_alloc(state_b, -1, 1);
            if (st_p == nullptr) return false;
        }
        c.lc = (uint8_t*) os::anon_alloc(lc_bytes, -1, 1);
        if (c.lc == nullptr) {
            if (c.lm_pinned) cudaFreeHost(st_p);
            else os::anon_free(st_p, state_b);
            return false;
        }
        c.lm_state = (uint8_t*) st_p;
        c.lm_state_bytes = state_b;
        c.lc_bytes = lc_bytes;
        c.lc_of.assign(n_exp, -1);
        c.lc_writer.assign(n_exp, -1);
        c.lm = true;
        lm_layers.store(0);
        return true;
    }
    void lm_end() {
        for (size_t di = 0; di < chunks.size(); ++di) {
            Chunk& c = *chunks[di];
            if (!c.lm) continue;
            cudaSetDevice(devs[di].id);
            cudaStreamSynchronize(devs[di].st);   // (nothing of the run's still reads or writes them: the device's
            cudaStreamSynchronize(c.cs);          // copies done, every read the run issued done - a failed run's too)
            for (size_t i = c.base; i < c.n_read; ++i)
                while (fit(c, i).left.load(std::memory_order_acquire) != 0) c.io->wait_any(500);
            if (c.lm_pinned) cudaFreeHost(c.lm_state);
            else os::anon_free(c.lm_state, c.lm_state_bytes);
            os::anon_free(c.lc, c.lc_bytes);
            c.lm_state = c.lc = nullptr;
            c.lm_state_bytes = c.lc_bytes = 0;
            c.lm = c.lm_pinned = false;
        }
    }

    // the first layer of a long prompt's second half (forward_chunks' two passes), or -1: the first with compress ratio 1
    // (V4.1: 20), every one after it ratio 1 too and owning no compressed KV or index keys of its own (they read its),
    // every trunk layer on one GPU.  The settings' MAYA_DS4_PROMPT_SKIP (STRATA_DS4_PROMPT_SKIP; DS4_YOCO for tests):
    // 1 (the default) the skip, 2 DeepSeek's own serving's (the last 128 rows only: faster, the answers shift a
    // little), 0 off
    static int yoco_mode() {
        static const int m = [] {
            const char* v = std::getenv("DS4_YOCO");
            if (v == nullptr) v = std::getenv("STRATA_DS4_PROMPT_SKIP");
            return v != nullptr ? std::atoi(v) : 1;
        }();
        return m;
    }
    // STRATA_DS4_PROMPT_SKIP_TP (DS4_YOCO_TP; default 1, =0 off): the skip on a tensor-parallel group too, where
    // one group of members holds every trunk layer (tp3 on 3 GPUs).  What it needs is already per member: run_layer and
    // layer_chunk run on each member with the same Run (the same kv_only calls and r0 views, so the same all-reduces in
    // the same order, each of n = (T - r0) x dim floats on c.acc, which no view moves); the compressor / indexer are
    // replicated, so each member's kv_only fills its own copy of layer yoco's compressed KV and index keys and leaves its
    // own rings as the one-GPU path does; the stream plans (the flow's flow_next / fl_rows, the staged / DS4_TP_DIRECT
    // S.b) leave out the same (chunk, layer)s on every member; DS4_ATTN_SPLIT3's row thirds are of the cut view's rows;
    // the drafter's taps and the logits are the last chunk's last rows, which the skip keeps.  Not with groups after
    // one another (a layer split: the hand-offs and the remote sources carry every row of every chunk, which the skip
    // does not run - those stay on the full work).  The skip is not bitwise: a chunk's rows
    // through layers yoco.. change count, so the experts' sorted batches, the hc mix GEMM's blocking (and DS4_AR_OVERLAP's
    // parts) change too - the one-GPU gate is a teacher-forced KL (tools/dsv41/test_prompt_skip.py); the tp gate is the
    // same at tp3 (docs/dsv41/cards/PF-05.md).  On by default since the test machine's tp3 gate: KL 0.000175 vs the full work, 16K TTFT
    // 25.35 -> 15.61 s, decode ms a round unchanged (section 6)
    static bool yoco_tp() {
        static const bool on = [] {
            const char* v = std::getenv("DS4_YOCO_TP");
            if (v == nullptr) v = std::getenv("STRATA_DS4_PROMPT_SKIP_TP");
            return v == nullptr || std::atoi(v) != 0;
        }();
        return on;
    }
    int yoco_layer() const {
        if (yoco_mode() == 0 || chunk <= 0 || g.nl < 2 || (int) g.ratios.size() < g.nl) return -1;
        int yl = -1;
        for (int il = 0; il < g.nl && yl < 0; ++il)
            if (g.ratios[(size_t) il] == 1) yl = il;
        if (yl <= 0 || !L[(size_t) yl].kv_src) return -1;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            if (l.dev != L[0].dev || l.grp != L[0].grp || l.nm != L[0].nm) return -1;   // (one GPU, or one tp group)
            if (l.nm != 1) {
                if (!yoco_tp()) return -1;
                for (int m = 0; m < l.nm; ++m)   // (the same members, in the same order, on every layer)
                    if (member(l, m).dev != member(L[0], m).dev) return -1;
            }
            if (il > yl && (g.ratios[(size_t) il] != 1 || l.kv_src)) return -1;
        }
        return yl;
    }

    // n tokens at positions pos .. in chunks of equal size (at most `chunk`), pipelined over the groups; the logits of
    // the last min(logits_rows, 16) rows (logits_rows > 16: a run of one chunk, every row's into chunk_logits)
    bool forward_chunks(const int* tk, int n, int logits_rows, std::string& err, int snap_slot = -1) {
        if (n < 1) return true;
        flow_used.store(true);
        std::lock_guard<std::mutex> warm_lk(warm_mu);   // (the warm-up, if it is running, finishes first)
        if (pos + n > o.max_context) {
            err = "the context is full";
            return false;
        }
        for (int t = 0; t < n; ++t)
            if (tk[t] < 0 || tk[t] >= g.vocab) {
                err = "token " + std::to_string(tk[t]) + " out of range";
                return false;
            }
        // a long prompt's skip: the layers from yoco_layer() on (V4.1: 20-39) read the earlier positions only through
        // that layer's compressed KV and index keys, and each looks back one window (win - 1 positions) more than the
        // layer before - so they need their own work only on the last keep = (nl - yoco) (win - 1) + win rows for the
        // run's last rows and the rings the decode reads to be what the full work gives (up to the experts' summing
        // order).  The chunks stay as they are: the ones before the cut go through the layers before yoco and its
        // kv_only, the cut's chunk through those over all its rows and through the rest from the cut on (Run::r0, a
        // view of its buffers), the chunks after it through every layer - each layer's experts read as without the
        // skip.  One GPU (DS4_YOCO=1; 0: off), or one tp group (yoco_tp: STRATA_DS4_PROMPT_SKIP_TP, =0 off); not with
        // every row's logits (tests)
        const int yl = logits_rows > kWin ? -1 : yoco_layer();
        // (DS4_YOCO_KEEP=<rows>: fewer - DeepSeek's own serving replays the last 128 tokens through those layers
        //  (DeepInfer's "SWA bounded replay"), which shifts the answers a little; at least one window)
        static const int keep_env = std::getenv("DS4_YOCO_KEEP") ? std::atoi(std::getenv("DS4_YOCO_KEEP")) : 0;
        const int keep = yl <= 0 ? 0
                         : keep_env > 0 ? std::max(keep_env, g.win)
                         : yoco_mode() == 2 ? g.win : (g.nl - yl) * (g.win - 1) + g.win;
        const int a = yl > 0 && n - keep >= kYocoMin ? n - keep : 0;
        const int nc = (n + chunk - 1) / chunk, per = (n + nc - 1) / nc;
        if (ds4_dbg("DS4_DBG_CHUNK")) std::fprintf(stderr, "forward_chunks n %d nc %d per %d\n", n, nc, per);
        Run run;
        for (int x = 0; x < n; x += per) {
            run.p0.push_back(pos + x);
            run.T.push_back(std::min(per, n - x));
            run.seq.push_back(++win_seq);
        }
        if (a > 0) {
            run.yoco = yl;
            run.cut_k = a / per;
            run.cut_r = a - run.cut_k * per;
        }
        if (ds4_dbg("DS4_DBG_CHUNK"))
            std::fprintf(stderr, "forward_chunks skip: yoco %d keep %d cut chunk %d row %d (nm %d)\n", run.yoco, keep,
                         run.cut_k, run.cut_r, L[0].nm);
        if (run.yoco >= 0 && L[0].nm > 1) {   // (the tp skip's first use, once - a run can be seen to have taken it)
            static std::atomic<bool> said{false};
            if (!said.exchange(true))
                std::fprintf(stderr, "ds4: long-prompt skip on the tp%d group (STRATA_DS4_PROMPT_SKIP_TP, =0 off): layers %d-%d on "
                                     "the last %d of %d rows\n", L[0].nm, yl, g.nl - 1, n - a, n);
        }
        logits_all = logits_rows > kWin;
        if (logits_all) chunk_logits.resize((size_t) n * g.vocab);
        for (int t = 0; t < n; ++t) {
            toks.push_back(tk[t]);
            ctoks.push_back(ctok(pos + t, tk[t]));
        }
        plan_streams();
        if (snap_slot >= 0) {   // feed_mark: the state before the run's last row, kept by its layers on the way
            run.snap_pos = pos + n - 1;
            for (int il = 0; il < g.nl; ++il) {
                Layer& l = L[(size_t) il];
                Dev& d = devs[(size_t) l.dev];
                if (l.snap_win == nullptr && !dalloc(d, l.snap_win, (size_t) g.win * win_rb(), err)) return false;
                if (l.c_kv != nullptr && l.snap_kv == nullptr &&
                    (!dalloc(d, l.snap_kv, (size_t) l.ratio * g.hd, err) || !dalloc(d, l.snap_sc, (size_t) l.ratio * g.hd, err)))
                    return false;
            }
        }
        const int T_last = run.T.back();
        n_logits = logits_all ? 0 : std::min(logits_rows, T_last);
        const double tl = now_ms();
        {   // each chunk's end on the head device, for the progress reports
            cudaSetDevice(devs[(size_t) head_dev].id);
            while (chunk_done.size() < run.T.size()) {
                cudaEvent_t e = nullptr;
                CK(cudaEventCreateWithFlags(&e, cudaEventDisableTiming));
                chunk_done.push_back(e);
            }
            chunk_rec.reset(new std::atomic<int>[chunk_done.size()]);
            for (size_t i = 0; i < chunk_done.size(); ++i) chunk_rec[i].store(0);
        }
        prof_chunk = prof_on && !prof_sync_on;   // (DS4_PROF_SYNC: the decode profile only; the prompt events hang the driver)
        const bool lm = lm_begin(run);
        struct LmEnd {   // (every way out: its host memory freed once the device is done with it)
            Impl* p;
            bool on;
            ~LmEnd() {
                if (on) p->lm_end();
            }
        } lm_end_{this, lm};
        std::vector<std::string> errs(devs.size());
        halted = false;
        halt.store(false);
        {
            std::lock_guard<std::mutex> lk(halt_mu);
            halt_k = INT_MAX;
            halt_seen = -1;
        }
        bool halting = false;
        g_pipeline_abort.store(false);
        if (pfh_live) {   // (DS4_PF_HELPER: the run's counters)
            std::fill(pfh_wait_ms.begin(), pfh_wait_ms.end(), 0.0);
            pfh_layers_run = pfh_layers_streamed = pfh_layers_mixed = pfh_exp_streamed = 0;
            pfh_xwait_ms = 0;
        }
        const int launch_err0 = x3::launch_errors() + gg::launch_errors();
        for (size_t di = 0; di < devs.size(); ++di)
            workers[di]->submit([this, di, &run, &errs] {
                std::string e;
                if (!run_dev_chunks((int) di, run, e)) {
                    errs[di] = e.empty() ? "a device's thread failed" : e;
                    if (errs[di] != kHalted) g_pipeline_abort.store(true);   // (the others stop waiting for its flags)
                }
            });
        size_t reported = 0;
        double abort_at = 0;
        for (;;) {
            bool all = true;
            for (auto& w : workers) all = all && w->idle();
            // a kernel that fails to launch leaves its flags unraised and the other devices waiting for them: stop
            // them waiting, give the device-side waits a few seconds to drain, then end the process with the error
            if (!all && x3::launch_errors() + gg::launch_errors() != launch_err0) g_pipeline_abort.store(true);
            if (!all && g_pipeline_abort.load()) {
                if (abort_at == 0) abort_at = now_ms();
                else if (now_ms() - abort_at > 15000.0) {
                    std::fprintf(stderr, "ds4: the prompt path failed (%d kernel launch errors, see above) and its workers do not "
                                         "end: exiting\n", x3::launch_errors() + gg::launch_errors() - launch_err0);
#if defined(STRATA_USE_HIP)
                    if (diag_enabled()) ds4_diag_errs().summary();
#endif
                    std::fflush(stderr);
                    std::_Exit(3);
                }
            }
            if (!all && !halting && cancel && cancel()) {   // a Stop: the devices end the run early
                halting = true;
                std::lock_guard<std::mutex> lk(halt_mu);
                halt_k = halt_seen + 1;
                halt.store(true, std::memory_order_release);
            }
            if (progress && lm) {   // (layer-major: the share of the layers every chunk went through)
                const int nd = lm_layers.load(std::memory_order_acquire);
                if (nd > 0 && nd < g.nl) progress((int64_t) n * nd / g.nl);
            } else if (progress) {   // chunks through every layer (the last layer's device past their event)
                while (reported < run.T.size() && chunk_rec[reported].load(std::memory_order_acquire) &&
                       cudaEventQuery(chunk_done[reported]) == cudaSuccess)
                    ++reported;
                if (reported > 0 && reported < run.T.size())
                    progress(run.p0[reported - 1] + run.T[reported - 1] - run.p0[0]);
            }
            if (all) break;
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
        for (const std::string& e : errs)   // (a device's failure first: a Stop's early end is not one)
            if (!e.empty() && e != kHalted) {
                err = e;
                return false;
            }
        if (const int nle = x3::launch_errors() + gg::launch_errors() - launch_err0; nle > 0) {
            err = std::to_string(nle) + " kernel launches failed in the prompt path (the lines above name them)";
            return false;
        }
        for (const std::string& e : errs)
            if (e == kHalted) {
                halted = true;
                err = "stopped while reading the prompt";
                return false;
            }
        st.layer_ms += now_ms() - tl;
        eg_stats();
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        const double th = now_ms();
        CK(cudaStreamSynchronize(d.st));
        st.head_ms += now_ms() - th;
        if (prof_chunk) {   // DS4_PROF: the run's GPU time by stage, every device's summed
            for (Dev& dv : devs) {
                cudaSetDevice(dv.id);
                CK(cudaStreamSynchronize(dv.st));
            }
            cudaSetDevice(d.id);
            prof_collect();
            std::fprintf(stderr,
                         "ds4 prompt GPU time, %d tokens: attention %.0f ms, routing + shared expert %.0f ms, experts %.0f ms "
                         "(with the waits for streamed ones), between layers %.0f ms\n",
                         n, cprof_ms[1], cprof_ms[2], cprof_ms[3], cprof_ms[0]);
            {   // the finer table (ms, % of the sum)
                static const char* nm_[16] = {"between layers", "attn rest (q_b, wo_a/b, hc_post)", "shared expert", "experts (incl waits)",
                                              "engram", "attn mHC (mix/split/norm)", "attn projections", "compressor + indexer",
                                              "q_b + rope", "sparse attention", "ffn mHC + router + sort", "attn all-reduce (tp)",
                                              "moe all-reduce (tp)", "streamed experts (incl waits)", "bounds readback gap", ""};
                double sum = 0;
                for (double v : cprof_ms) sum += v;
                for (int i = 0; i < 15; ++i)
                    std::fprintf(stderr, "ds4 prof  %-34s %9.1f ms %5.1f%%\n", nm_[i], cprof_ms[i], sum > 0 ? 100.0 * cprof_ms[i] / sum : 0.0);
                for (const Dev& dv : devs) {   // (by device - the members' shares are not the same work)
                    if (dv.id < 0 || dv.id >= 16) continue;
                    std::string row;
                    double ds = 0;
                    for (int i = 0; i < 15; ++i) {
                        char b2[32];
                        std::snprintf(b2, sizeof b2, " %d:%.0f", i, cprof_dev[dv.id][i]);
                        row += b2;
                        ds += cprof_dev[dv.id][i];
                    }
                    std::fprintf(stderr, "ds4 prof  CUDA%d stage ms (sum %.0f):%s\n", dv.id, ds, row.c_str());
                    for (double& v : cprof_dev[dv.id]) v = 0;
                }
                struct Agg {
                    double ms = 0, flops = 0;
                    long calls = 0, rows = 0, experts = 0;
                };
                std::map<std::pair<int, int>, Agg> agg;   // (type, role 0 gate+up, 1 down)
                {
                    std::lock_guard<std::mutex> lk(prof_mu);
                    for (const EkMark& m : ek_marks) {
                        float a = 0, b = 0;
                        cudaSetDevice(m.dev);
                        cudaEventElapsedTime(&a, m.e0, m.e1);
                        cudaEventElapsedTime(&b, m.e1, m.e2);
                        Agg& x = agg[{m.tg, 0}];
                        x.ms += a;
                        x.flops += 2.0 * 2.0 * m.nrows * (double) g.dim * (double) m.ff;
                        x.calls++, x.rows += m.nrows, x.experts += m.nexp;
                        Agg& y = agg[{m.td, 1}];
                        y.ms += b;
                        y.flops += 2.0 * m.nrows * (double) g.dim * (double) m.ff;
                        y.calls++, y.rows += m.nrows, y.experts += m.nexp;
                        ek_pool[m.dev].push_back(m.e0);
                        ek_pool[m.dev].push_back(m.e1);
                        ek_pool[m.dev].push_back(m.e2);
                    }
                    ek_marks.clear();
                }
                double tot = 0;
                for (auto& kv : agg) tot += kv.second.ms;
                for (auto& kv : agg)
                    std::fprintf(stderr,
                                 "ds4 prof  expert kernels type %-8s %-7s %9.1f ms  calls %5ld  experts %6ld (%.1f us each, %.1f a call)  rows/expert %6.1f  ~%5.1f TFLOPS\n",
                                 gg::iq::name(kv.first.first), kv.first.second ? "down" : "gate+up", kv.second.ms, kv.second.calls,
                                 kv.second.experts, kv.second.experts > 0 ? 1e3 * kv.second.ms / (double) kv.second.experts : 0.0,
                                 kv.second.calls > 0 ? (double) kv.second.experts / (double) kv.second.calls : 0.0,
                                 kv.second.experts > 0 ? (double) kv.second.rows / (double) kv.second.experts : 0.0,
                                 kv.second.ms > 0 ? kv.second.flops / kv.second.ms / 1e9 : 0.0);
                std::fprintf(stderr, "ds4 prof  expert kernels total %.1f ms\n", tot);
            }
            for (double& v : cprof_ms) v = 0;
            prof_chunk = false;
        }
        if (o.verbose || std::getenv("DS4_FLOW_STATS") != nullptr) {
            const double ms = now_ms() - tl;
            for (size_t di = 0; di < chunks.size(); ++di) {
                const Chunk& c = *chunks[di];
                if (!c.flow) continue;
                const double db = (double) (c.io->direct_bytes() - c.io_d0) / 1e9;
                const double bb = (double) (c.io->buffered_bytes() - c.io_b0) / 1e9;
                const double fb = db + bb, rb = (double) c.it_ram * (double) L[0].blob / 1e9;   // (a member: its parts)
                char lcs[160] = "";
                if (c.lm)
                    std::snprintf(lcs, sizeof lcs, ", %llu again from the layer cache (layer-major, %d chunks, %.1f GB "
                                  "of RAM)", (unsigned long long) c.it_lc, (int) run.T.size(), (double) c.lc_bytes / 1e9);
                char dbgs[200] = "";
                if (pm.on)
                    std::snprintf(dbgs, sizeof dbgs,
                                  "; io threads busy %.0f ms, copy_ahead staging %.0f ms, DMA issues %.0f ms, slot waits %.0f ms",
                                  c.io->busy_ms() - c.io_busy0, c.dbg_stage_ms, c.dbg_dma_ms, c.dbg_evt_ms);
                std::fprintf(stderr,
                             "ds4 prompt stream, CUDA%d: %d tokens in %.0f ms; %llu experts streamed: %llu from the files "
                             "(%.1f GB, %.2f GB/s: %.1f GB from the disk unbuffered, %.1f GB through the page cache), %llu "
                             "from RAM (%.1f GB)%s; %llu likely ones queued early, %llu of them unpicked; the compute waited "
                             "%.0f ms for reads%s\n",
                             devs[di].id, n, ms, (unsigned long long) (c.it_file + c.it_ram + c.it_lc),
                             (unsigned long long) c.it_file, fb, fb / std::max(1e-3, ms / 1000.0), db, bb,
                             (unsigned long long) c.it_ram, rb, lcs, (unsigned long long) c.it_spec,
                             (unsigned long long) c.it_spec_unused, c.wait_ms, dbgs);
            }
        }
        if (o.verbose || prof_on || std::getenv("DS4_FLOW_STATS") != nullptr) {   // the batches' path (tensor parallel)
            const double ms = now_ms() - tl;
            for (size_t di = 0; di < chunks.size(); ++di) {
                const Chunk& c = *chunks[di];
                if (c.flow || c.ring == nullptr || c.run_bytes <= 0) continue;
                std::fprintf(stderr,
                             "ds4 prompt stream (batches), CUDA%d: %d tokens in %.0f ms (this device's thread %.0f ms); %.1f GB "
                             "streamed (%.2f GB/s over the run), %llu experts DMA'd from the pinned RAM copy, %llu through the "
                             "staging; host: staging copies %.0f ms, DMA issues %.0f ms, waits for a staging part %.0f ms\n",
                             devs[di].id, n, ms, c.run_ms, c.run_bytes / 1e9, c.run_bytes / 1e9 / std::max(1e-3, ms / 1000.0),
                             (unsigned long long) c.run_direct, (unsigned long long) c.run_staged, c.dbg_stage_ms,
                             c.dbg_dma_ms, c.dbg_evt_ms);
            }
            if (pfh_live && (pfh_layers_run > 0 || pfh_layers_streamed > 0)) {   // DS4_PF_HELPER
                std::string wt;
                for (size_t di = 0; di < devs.size(); ++di) {
                    char b2[48];
                    std::snprintf(b2, sizeof b2, "%sCUDA%d %.0f", di ? ", " : "", devs[di].id, pfh_wait_ms[di]);
                    wt += b2;
                }
                std::fprintf(stderr, "ds4 prompt helpers (DS4_PF_HELPER=%d), %d tokens in %.0f ms: %lld layers on the helpers (%lld of them also streamed %lld "
                                     "unheld experts), %lld streamed; "
                                     "members' host waits for their helpers (ms): %s; the lead's x read-back waits %.0f ms; helpers so far: %s\n",
                             pfh_rows, n, ms, (long long) pfh_layers_run, (long long) pfh_layers_mixed, (long long) pfh_exp_streamed,
                             (long long) pfh_layers_streamed, wt.c_str(), pfh_xwait_ms, hlp.pf_describe().c_str());
            }
            if (ec_fix && o.expert_cache)   // DS4_EC_FIX (before this read's own tick: "so far")
                std::fprintf(stderr, "ds4: DS4_EC_FIX=1: so far %lld helper-held cache hits left out of the swaps, %lld swaps\n",
                             (long long) ec_left, (long long) st.swaps);
        }
        if (dd_audit)   // DS4_DD_AUDIT (before this read's own tick: "so far"; every prompt read, whatever the stats flags)
            std::fprintf(stderr, "ds4: DS4_DD_AUDIT=1: so far %s\n", dd_audit_line().c_str());
        if (dd_audit && ecown) {   // DS4_ECOWN: a pick computed twice, a member's plan off the lead's marks or a check timed out
            unsigned long long bad = 0, tmo = 0;
            for (size_t di = 0; ec_chk != nullptr && di < ec_tmo.size(); ++di) {
                bad += ((const volatile unsigned long long*) ec_chk)[di * 4 + 1];
                tmo += ((const volatile unsigned long long*) ec_chk)[di * 4 + 2];
            }
            if (dd_aud_dbl.load() > 0 || bad > 0 || tmo > 0)
                std::fprintf(stderr, "ds4: DS4_ECOWN check FAILED: %lld picks computed twice, %llu mismatched picks, %llu timeouts so far\n",
                             dd_aud_dbl.load(), bad, tmo);
        }
        if (pm.on && run.T.size() == 1) {   // (the picks' spread for pick_path: the CPU-lane experts this run picked)
            bool tp = false;
            for (const Layer& l : L) tp = tp || l.nm > 1;
            double picked = 0;
            for (const auto& cp : chunks)
                if (cp != nullptr && cp->flow) picked += (double) (cp->it_file + cp->it_ram) - (double) cp->it_spec_unused;
            if (!tp) pm_learn(n, picked);
        }
        if (logits_all) n_logits = (T_last - 1) % kWin + 1;   // (sample() takes the last row of d.logits)
        pos += n;
        st.tokens += n;
        cache_tick(n);
        if (lm_end_.on) {   // (the layer cache's RAM back before the store and the swaps want it)
            lm_end();
            lm_end_.on = false;
        }
        cache_settle();
        const int nr = std::min(T_last, tap_cap);
        if (!seed_drafter(pos - nr, nr, 0, err)) return false;
        if (snap_slot >= 0) {   // checkpoint `snap_slot` from what the layers kept (the drafter's blocks: as they are -
            // the next feed seeds them again from its own rows, past this position)
            Check& ckp = ck[snap_slot & 1];
            ckp.pos = run.snap_pos;
            ckp.win.resize(L.size());
            ckp.comp.resize(L.size() * 2);
            for (size_t i = 0; i < L.size(); ++i) {
                Layer& l = L[i];
                Dev& dv = devs[(size_t) l.dev];
                cudaSetDevice(dv.id);
                const bool kept = !l.mtp && l.snap_win != nullptr;
                ckp.win[i].resize((size_t) g.win * win_rb());
                CK(cudaMemcpyAsync(ckp.win[i].data(), kept ? l.snap_win : l.win, ckp.win[i].size(),
                                   cudaMemcpyDeviceToHost, dv.st));
                if (l.c_kv) {
                    ckp.comp[2 * i].resize((size_t) l.ratio * g.hd);
                    ckp.comp[2 * i + 1].resize((size_t) l.ratio * g.hd);
                    CK(cudaMemcpyAsync(ckp.comp[2 * i].data(), kept && l.snap_kv ? l.snap_kv : l.c_kv,
                                       ckp.comp[2 * i].size() * 4, cudaMemcpyDeviceToHost, dv.st));
                    CK(cudaMemcpyAsync(ckp.comp[2 * i + 1].data(), kept && l.snap_sc ? l.snap_sc : l.c_score,
                                       ckp.comp[2 * i + 1].size() * 4, cudaMemcpyDeviceToHost, dv.st));
                }
            }
            for (Dev& dv : devs) {
                cudaSetDevice(dv.id);
                CK(cudaStreamSynchronize(dv.st));
            }
        }
        return true;
    }

    // the window's plan, in window order (the indexer's and the candidate source's sizes carry from window to window)
    // (DS4_BATCH_DECODE: rpos gives each row its own position, and cur_topk / cur_cand each row's indexer state -
    // a batch row carries its own sequence's, as that sequence's windows of one would; null: p0 .., this state's)
    void plan_window(int64_t p0, int T, WinPlan& wp, const int64_t* rpos = nullptr, int* cur_topk = nullptr,
                     int* cur_cand = nullptr) {
        int* cur_topk_n = cur_topk != nullptr ? cur_topk : this->cur_topk_n;
        int* cur_cand_n = cur_cand != nullptr ? cur_cand : this->cur_cand_n;
        wp.par = par;
        wp.async = par || (!sync_decode && T <= async_max_t);
        wp.vl = 0;
        for (int t = 0; t < T && !imgs.empty() && rpos == nullptr; ++t)
            if (in_image(p0 + t)) wp.vl |= 1u << t;
        for (int il = 0; il < g.nl; ++il) {
            const Layer& l = L[(size_t) il];
            if (l.ratio > 0) {
                const int R = l.ratio;
                int n[kWin], k[kWin], clen_max = 0;
                for (int t = 0; t < T; ++t) {
                    n[t] = (int) (((rpos != nullptr ? rpos[t] : p0 + t) + 1) / R);
                    k[t] = std::min(g.ix_topk, n[t]);
                    clen_max = std::max(clen_max, n[t]);
                }
                if (l.ix_src) {
                    for (int t = 0; t < T; ++t) wp.cand[il][t] = cur_cand_n[t];
                    if (clen_max > 0 && l.cand_src)
                        for (int t = 0; t < T; ++t) cur_cand_n[t] = std::min(g.cand_topk, (n[t] + g.cand_blk - 1) / g.cand_blk);
                    for (int t = 0; t < T; ++t) cur_topk_n[t] = k[t];
                }
                for (int t = 0; t < T; ++t) wp.topk[il][t] = cur_topk_n[t];
            }
            if (wp.async) {
                wp.seq[il] = ++seq_issued;
                layer_of[wp.seq[il] % kRing].store(il, std::memory_order_release);
            }
        }
    }

    int head_nm() const { return (int) groups[(size_t) devs[(size_t) head_dev].grp].mem.size(); }
    // the head's columns on member mi of its group of nm: an EXL3 head's split128 of the vocabulary (mat's), a GGUF's
    // BF16 / Q8_0 head's even shares (mat_bf16's) - head_share's, its gather's and the markov steps' rows
    void head_cols(int nm, int mi, int& v0, int& vn) const {
        const Tensor* tw = pk.get("head.weight");
        if (tw != nullptr && (tw->dtype == "BF16" || tw->dtype == "Q8_0")) {
            vn = g.vocab / nm;
            v0 = mi * vn;
        } else
            split128(g.vocab, nm, mi, v0, vn);
    }
    // the head over `rows` (<= 16) normed rows xn on member mi of the head group (device d): its share of each row's
    // logits (columns [v0, v0 + vn), head_cols); the lead gathers the others' into d.logits (rows V apart) - two
    // slots by seq (Vmax apart, the widest share's), a member reusing one once the lead acknowledged it.  gather
    // false: each member keeps its share (the drafter's markov steps over the group, mk_split)
    bool head_share(Dev& d, int mi, const float* xn, int rows, std::string& err, bool gather = true) {
        const int V = g.vocab, D = g.dim, nm = head_nm();
        int v0 = 0, vn = 0, Vmax = 0, z = 0;
        head_cols(nm, mi, v0, vn);
        head_cols(nm, 0, z, Vmax);
        Group& G = groups[(size_t) d.grp];
        float* out = mi == 0 ? d.logits : d.logits_part;
        const size_t ld = mi == 0 ? (size_t) V : (size_t) vn;
        cudaSetDevice(d.id);
        // (an EXL3 head: as many activations at a time as its split-K partials fit the scratch - 8 for a shared head, 4
        // for a whole one, each pass reading the whole share; a GGUF's: 8, so that every window the engine can build (rows
        // <= kWin = 8) walks the head once instead of twice - measured on the drafter's fixed T=5: 4.55 -> 2.83 ms, its
        // round 14.49 -> 13.46; the verify window's head 3.48 -> 2.68 ms, the same logits.  DS4_HEAD_PER overrides.)
        const int per = d.head.fmt != 0 ? (std::getenv("DS4_HEAD_PER") ? std::atoi(std::getenv("DS4_HEAD_PER")) :
#if defined(STRATA_METAL)
                                                                                   4   // (8 columns a pass on Metal moved the KL by +0.002: the mvn8 kernel sums in another order)
#else
                                                                                   strata::ds4::head_per_default(defaults_026())
#endif
                                                                                   )
                                        : std::max(1, x3::mv_cols(d.head));
        for (int c = 0; c < rows; c += per)
            if (!mv(d, {job(d.head, xn + (size_t) c * D, out + (size_t) c * ld, std::min(per, rows - c), D, ld)}, err))
                return false;
        if (nm == 1 || !gather) return true;
        const unsigned seq = ++d.head_seq;
        const int slot = (int) (seq % 2);
        auto stage = [&](int m) { return G.lg_stage + ((size_t) slot * (nm - 1) + (m - 1)) * kWin * Vmax; };
        auto flag = [&](int m) { return G.lg_flag + ((size_t) slot * (nm - 1) + (m - 1)) * 32; };
        if (mi > 0) {
            if (seq > 2) wait_flags(G.lg_ack + (size_t) slot * 32, 1, 32, seq - 2, d.st);
            Xfer x;
            x.n = 1;
            x.src[0] = d.logits_part;
            x.dst[0] = stage(mi);
            x.bytes[0] = (size_t) rows * vn * 4;
            xfer_put(x, flag(mi), seq, d.xcnt, d.st);
            return true;
        }
        for (int m = 1; m < nm; ++m) {
            int m0 = 0, mn = 0;
            head_cols(nm, m, m0, mn);
            Xfer x;
            x.n = 1;
            x.src[0] = stage(m);
            x.dst[0] = d.logits_part;
            x.bytes[0] = (size_t) rows * mn * 4;
            xfer_get(x, flag(m), seq, d.st);
            CK(cudaMemcpy2DAsync(d.logits + (size_t) m0, (size_t) V * 4, d.logits_part, (size_t) mn * 4,
                                 (size_t) mn * 4, (size_t) rows, cudaMemcpyDeviceToDevice, d.st));
        }
        set_flag(G.lg_ack + (size_t) slot * 32, seq, d.st);
        return true;
    }

    // the head's rows (the last n_logits of the window) on head group member di (its h / pre: the group's)
    bool head_rows_dev(int di, int T, std::string& err) {
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        const int D = g.dim, H = g.hc;
        if (n_logits <= 0) return true;
        const int t0 = T - n_logits;
        hc_pre_norm(d.h + (size_t) t0 * H * D, d.pre + (size_t) t0 * 8, d.norm_w, D, H, n_logits, g.eps, d.x, d.st);
        return head_share(d, d.mi, d.x, n_logits, err);
    }

    // the DSpark drafter's taps: the streams' mean entering target layer il, on device d (after the last seeding read
    // h_taps)
    bool tap(Dev& d, int il, int T, std::string& err) {
        const auto it = std::find(g.d_targets.begin(), g.d_targets.end(), il);
        if (g.n_mtp == 0 || o.dspark_noseed || it == g.d_targets.end()) return true;   // (DS4_DSPARK_NOSEED)
        const size_t j = (size_t) (it - g.d_targets.begin()), nt = g.d_targets.size();
        const int D = g.dim;
        cudaSetDevice(d.id);
        hc_mean(d.h, T, g.hc, D, d.tap, D, d.st);
        CK(cudaStreamWaitEvent(d.st, ev_seed, 0));
        CK(cudaMemcpy2DAsync(h_taps + j * D, nt * D * 4, d.tap, (size_t) D * 4, (size_t) D * 4, (size_t) T,
                             cudaMemcpyDeviceToHost, d.st));
        return true;
    }

    bool forward(const int* tk, int T, int logits_rows, std::string& err, int seed_rows = -1) {
#if defined(STRATA_METAL)
        struct BusyAll {   // DS4_BUSY_ALL: the GPU is held busy for the whole step (the host gaps between its bursts too)
            bool on;
            BusyAll() : on(std::getenv("DS4_BUSY_ALL") != nullptr) { if (on) ds4_busy_begin(); }
            ~BusyAll() { if (on) ds4_busy_end(); }
        } busy_all;
#endif
        if (T < 1 || T > kWin) {
            err = "a window of " + std::to_string(T) + " tokens";
            return false;
        }
        if (pos + T > o.max_context) {
            err = "the context is full";
            return false;
        }
        for (int t = 0; t < T; ++t)
            if (tk[t] < 0 || tk[t] >= g.vocab) {
                err = "token " + std::to_string(tk[t]) + " out of range";
                return false;
            }
        const int64_t p0 = pos;
        slot_held = false;   // (the state grows now: what slot_save took is no longer the conversation)
        for (int t = 0; t < T; ++t) {
            toks.push_back(tk[t]);
            ctoks.push_back(ctok(pos + t, tk[t]));
        }
        // the Engram rows asked for now (the first Engram layer's first), collected right before their layer: what is
        // left of their reads by then is the window's Engram time
        const double te = now_ms();
        const int64_t eg_w0 = eg_wait_ns.load();
        for (int li = 0; li < pk.eg_layers; ++li) {
            EgBatch& b = *eg_win[(size_t) li];
            if (b.live) eg_finish(b);   // (a window that failed midway: its reads end before h_eg is reused)
            eg_issue(p0, T, li, nullptr, b);
        }
        st.engram_ms += now_ms() - te;
        const int D = g.dim;
        for (int t = 0; t < T; ++t)   // (h_emb is written again by the next window, after this one's last sync)
            std::memcpy(h_emb + (size_t) t * D, emb_row(p0 + t, tk[t]), (size_t) D * 2);
        plan_window(p0, T, wplan);
        prof_window = prof_on && T == 1;
        n_logits = std::min(logits_rows, T);
        const double tl = now_ms();
        if (par) {
            if (!forward_par(p0, T, err)) return false;
        } else if (!forward_serial(p0, T, err)) return false;
        st.layer_ms += now_ms() - tl;
        for (auto& b : eg_win)
            if (b->live) eg_finish(*b);
        st.engram_ms += (double) (eg_wait_ns.load() - eg_w0) / 1e6;
        eg_stats();
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        const double th = now_ms();
        CK(cudaStreamSynchronize(d.st));
        st.head_ms += now_ms() - th;
        prof_collect();
        pos += T;
        st.tokens += T;
        cache_tick(T);
        if (seed_rows != 0 && !seed_drafter(p0, seed_rows < 0 ? T : seed_rows, 0, err)) return false;
        return true;
    }

    // one thread: the layers device after device, the hand-offs through pinned memory and events
    void dbg_nf(const char* tag, int il, const float* dev, size_t n) {   // DBG: non-finite count of a device buffer
        ds4_metal_flush();
        const float* hp = (const float*) strata::gpu::host_view(dev);
        size_t nf = 0, first = 0; float mx = 0.0f;
        for (size_t i = 0; i < n; ++i) { const float v = hp[i]; if (!(v == v)) { if (!nf) first = i; ++nf; } else if (std::fabs(v) > mx) mx = std::fabs(v); }
        std::fprintf(stderr, "DBG nf il=%d %s n=%zu nonfinite=%zu first=%zu max=%.4g\n", il, tag, n, nf, first, mx);
    }
    void dbg_h(const char* tag, Dev& d, int T) {   // DBG: max |h| of the window's residual stream, after the queue drains
        ds4_metal_flush();
        const float* hp = (const float*) strata::gpu::host_view(d.h);
        float mx = 0.0f; size_t nf = 0;
        const size_t n = (size_t) T * g.hc * g.dim;
        for (size_t i = 0; i < n; ++i) { const float v = hp[i]; if (!(v == v)) ++nf; else if (std::fabs(v) > mx) mx = std::fabs(v); }
        std::fprintf(stderr, "DBG hmax %s T=%d max=%.4g nonfinite=%zu h0=%g\n", tag, T, mx, nf, hp[0]);
    }
    bool forward_serial(int64_t p0, int T, std::string& err) {
        const int D = g.dim, H = g.hc;
        if (eg_ahead > 0) ++eg_ah_win;   // (DS4_EG_AHEAD: this window's prefetches)
        int cur = L[0].dev;
        if (ds4_dbg("DS4_SYNC_WIN")) cudaDeviceSynchronize();
        {
            Dev& d = devs[(size_t) cur];
            cudaSetDevice(d.id);
            CK(emb_upload(d.emb_rows, h_emb, (size_t) T * D * 2, d.st));
            embed(d.emb_rows, T, d.h, D, H, d.st);
            if (ds4_dbg("DS4_DBG_EMB")) {
                ds4_metal_flush();
                float *hp = d.h;
                float hh[4] = {0,0,0,0};
                cudaMemcpy(hh, hp, sizeof(hh), cudaMemcpyDeviceToHost);
                std::fprintf(stderr, "DBG at embed site %d: h[0..3] = %g %g %g %g\n", __LINE__, hh[0], hh[1], hh[2], hh[3]);
            }
            init_pre(d.pre, T, d.st);
            if (ds4_dbg("DS4_DBG_EMB")) dbg_h("after init_pre", d, T);
        }
        std::vector<float> dump;
        if (dump_h != nullptr) dump.resize((size_t) T * g.nl * H * D);
        for (int il = 0; il < g.nl; ++il) {
            Layer& l = L[(size_t) il];
            if (l.dev != cur) {
                Dev& a = devs[(size_t) cur];
                Dev& b = devs[(size_t) l.dev];
                cudaSetDevice(a.id);
                const size_t nh = (size_t) T * H * D * 4, np = (size_t) T * 8 * 4, nk = (size_t) T * topk_stride() * 4,
                             nc = (size_t) T * cand_stride() * 4;
                uint8_t* bb = a.bounce;
                CK(cudaMemcpyAsync(bb, a.h, nh, cudaMemcpyDeviceToHost, a.st));
                CK(cudaMemcpyAsync(bb + nh, a.pre, np, cudaMemcpyDeviceToHost, a.st));
                CK(cudaMemcpyAsync(bb + nh + np, a.topk, nk, cudaMemcpyDeviceToHost, a.st));
                CK(cudaMemcpyAsync(bb + nh + np + nk, a.cand, nc, cudaMemcpyDeviceToHost, a.st));
                CK(cudaEventRecord(a.ev_out, a.st));
                cudaSetDevice(b.id);
                CK(cudaStreamWaitEvent(b.st, a.ev_out, 0));
                CK(cudaMemcpyAsync(b.h, bb, nh, cudaMemcpyHostToDevice, b.st));
                CK(cudaMemcpyAsync(b.pre, bb + nh, np, cudaMemcpyHostToDevice, b.st));
                CK(cudaMemcpyAsync(b.topk, bb + nh + np, nk, cudaMemcpyHostToDevice, b.st));
                CK(cudaMemcpyAsync(b.cand, bb + nh + np + nk, nc, cudaMemcpyHostToDevice, b.st));
                cur = l.dev;
            }
            if (!tap(devs[(size_t) l.dev], il, T, err)) return false;
            if (il == 0 && ds4_dbg("DS4_DBG_EMB")) dbg_h("after tap", devs[(size_t) l.dev], T);
            if (!layer(l, 0, p0, T, wplan, err)) return false;
            if (dump_h != nullptr) {   // DS4_DUMP_H: every layer's residual stream, for tools/ds4/compare.py --layers
                Dev& dd = devs[(size_t) l.dev];
                std::vector<float> hv((size_t) T * H * D);
                cudaSetDevice(dd.id);
                CK(cudaMemcpyAsync(hv.data(), dd.h, hv.size() * 4, cudaMemcpyDeviceToHost, dd.st));
                CK(cudaStreamSynchronize(dd.st));
                for (int t = 0; t < T; ++t)
                    std::memcpy(dump.data() + ((size_t) t * g.nl + l.il) * H * D, hv.data() + (size_t) t * H * D,
                                (size_t) H * D * 4);
            }
        }
        if (dump_h != nullptr) std::fwrite(dump.data(), 4, dump.size(), dump_h);
        if (cur != head_dev) {
            err = "the head is not on the last layer's GPU";
            return false;
        }
        return head_rows_dev(head_dev, T, err);
    }

    // threads: each device's thread enqueues its layers (a group's members each their share) at once, the
    // devices waiting on each other through host-mapped flags (the window's seq)
    // each device thread's job made once (par_jobs, handed over by reference: a std::function holding a
    // reference_wrapper stores it in place) and its window passed in par_p0 / par_T - a window allocates nothing
    std::vector<std::function<void()>> par_jobs;
    std::vector<std::string> par_errs;
    std::vector<char> par_bad;
    int64_t par_p0 = 0;
    int par_T = 0;
    bool forward_par(int64_t p0, int T, std::string& err) {
        wplan.win = ++win_seq;
        if (eg_ahead > 0) ++eg_ah_win;   // (DS4_EG_AHEAD: this window's prefetches; before the device threads start)
        if (par_jobs.size() != devs.size()) {
            par_jobs.clear();
            par_errs.assign(devs.size(), std::string());
            par_bad.assign(devs.size(), 0);
            for (size_t di = 0; di < devs.size(); ++di) {
                par_errs[di].reserve(256);
                par_jobs.push_back([this, di] {
                    std::string& e = par_errs[di];
                    e.clear();
                    if (!run_dev((int) di, par_p0, par_T, wplan, e)) {
                        par_bad[di] = 1;
                        if (e.empty()) e = "a device's thread failed";
                    }
                });
            }
        }
        par_p0 = p0;
        par_T = T;
        std::fill(par_bad.begin(), par_bad.end(), (char) 0);
        for (size_t di = 0; di < devs.size(); ++di) workers[di]->submit(std::ref(par_jobs[di]));
        for (auto& w : workers) w->wait();
        for (size_t di = 0; di < devs.size(); ++di)
            if (par_bad[di]) {
                err = par_errs[di];
                return false;
            }
        return true;
    }

    // the hand-off between groups: h | pre | topk | cand of device d <-> the host-mapped buffer
    Xfer hand_xfer(uint8_t* host, Dev& d, int T, bool put) const {
        const size_t nh = (size_t) T * g.hc * g.dim * 4, np = (size_t) T * 8 * 4, nk = (size_t) T * topk_stride() * 4,
                     nc = (size_t) T * cand_stride() * 4;
        void* dv[4] = {d.h, d.pre, d.topk, d.cand};
        uint8_t* hv[4] = {host, host + nh, host + nh + np, host + nh + np + nk};
        const size_t nb[4] = {nh, np, nk, nc};
        Xfer x;
        x.n = 4;
        for (int i = 0; i < 4; ++i) {
            x.src[i] = put ? (const void*) dv[i] : (const void*) hv[i];
            x.dst[i] = put ? (void*) hv[i] : dv[i];
            x.bytes[i] = nb[i];
        }
        return x;
    }

    bool run_dev(int di, int64_t p0, int T, const WinPlan& wp, std::string& err) {
        Dev& d = devs[(size_t) di];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int D = g.dim, H = g.hc;
        bool started = false;
        thread_local std::vector<char> got;   // this device thread's, kept (assign: no allocation once it has the size)
        got.assign(srcs.size(), 0);
        for (int il = 0; il < g.nl; ++il) {
            Layer& L0 = L[(size_t) il];
            int mi = -1;
            for (int m = 0; m < L0.nm; ++m)
                if (member(L0, m).dev == di) mi = m;
            if (mi < 0) continue;
            if (!started) {   // the window's input: the embedding rows, or the previous group's hand-off
                started = true;
                if (il == 0) {
                    CK(emb_upload(d.emb_rows, h_emb, (size_t) T * D * 2, s));
                    embed(d.emb_rows, T, d.h, D, H, s);
                    if (ds4_dbg("DS4_DBG_EMB")) {
                        ds4_metal_flush();
                        float *hp = d.h;
                        float hh[4] = {0,0,0,0};
                        cudaMemcpy(hh, hp, sizeof(hh), cudaMemcpyDeviceToHost);
                        std::fprintf(stderr, "DBG at embed site %d: h[0..3] = %g %g %g %g\n", __LINE__, hh[0], hh[1], hh[2], hh[3]);
                    }
                    init_pre(d.pre, T, s);
                } else {
                    const Dev& a = devs[(size_t) L[(size_t) il - 1].dev];
                    xfer_get(hand_xfer(a.hand, d, T, false), a.hand_flag, wp.win, s);
                }
            }
            // the compressed KV / index keys another group's source layer wrote this window
            for (int sidx : {L0.src, L0.ix_src ? L0.ik_src : -1}) {
                if (sidx < 0 || got[(size_t) sidx]) continue;
                got[(size_t) sidx] = 1;
                Src& sr = srcs[(size_t) sidx];
                if (L[(size_t) sr.layer].grp == L0.grp) continue;
                const int64_t g_first = p0 / sr.ratio;
                const int ng = (int) std::max<int64_t>(0, (p0 + T) / sr.ratio - g_first);
                if (ng == 0) continue;
                Xfer x;
                if (sr.ckv[(size_t) di] != nullptr) {
                    x.src[x.n] = sr.x_stage;
                    x.dst[x.n] = sr.ckv[(size_t) di] + (size_t) g_first * ckv_rb();
                    x.bytes[x.n++] = (size_t) ng * ckv_rb();
                }
                if (sr.ik[(size_t) di] != nullptr) {
                    x.src[x.n] = sr.x_stage + x_cap() * ckv_rb();
                    x.dst[x.n] = sr.ik[(size_t) di] + (size_t) g_first * ik_rb();
                    x.bytes[x.n++] = (size_t) ng * ik_rb();
                }
                if (x.n > 0) xfer_get(x, sr.x_flag, wp.win, s);
            }
            if (mi == 0 && (!bt_on || bt_spec) && !tap(d, il, T, err)) return false;   // (a plain batch window seeds no drafter)
            if (!layer(L0, mi, p0, T, wp, err)) return false;
            if (dump_l != nullptr && mi == 0) dump_layer(d, d.h, il, p0, T);
            const bool last = il + 1 == g.nl || L[(size_t) il + 1].grp != L0.grp;
            if (last && mi == 0 && il + 1 < g.nl) xfer_put(hand_xfer(d.hand, d, T, true), d.hand_flag, wp.win, d.xcnt, s);
        }
        if (d.grp == devs[(size_t) head_dev].grp) return head_rows_dev(di, T, err);
        return true;
    }

    // a source's new cache rows (src on device `from`, bytes of them) to the same place of its other devices' copies,
    // through pinned memory: the copy out on the source's stream, each copy in on its device's stream after it
    bool replicate(std::vector<uint8_t*>& copies, uint8_t* stage, cudaEvent_t ev, const uint8_t* src, size_t at,
                   size_t bytes, int from, std::string& err) {
        bool any = false;
        for (size_t od = 0; od < devs.size(); ++od) any = any || (copies[od] != nullptr && (int) od != from);
        if (!any) return true;
        Dev& d = devs[(size_t) from];
        CK(cudaMemcpyAsync(stage, src, bytes, cudaMemcpyDeviceToHost, d.st));
        CK(cudaEventRecord(ev, d.st));
        for (size_t od = 0; od < devs.size(); ++od) {
            if (copies[od] == nullptr || (int) od == from) continue;
            Dev& o2 = devs[od];
            cudaSetDevice(o2.id);
            CK(cudaStreamWaitEvent(o2.st, ev, 0));
            CK(cudaMemcpyAsync(copies[od] + at, stage, bytes, cudaMemcpyHostToDevice, o2.st));
        }
        cudaSetDevice(d.id);
        return true;
    }

    // DS4_EG_AHEAD (see eg_ahead): at layer il's FFN start on device di (its attention enqueued), the Engram layers il
    // triggers - each one's chain on the side stream, after the main stream's work so far (so the buffers' last readers,
    // the previous window's gate / all-gather, are done), into that layer's own buffers; layer() takes it if the window,
    // p0 and T match.  The kernels and their inputs are layer()'s own (the DS4_EG_SPLIT slice where it applies)
    bool eg_ahead_issue(int di, int il, int64_t p0, int T, std::string& err) {
        if (eg_ahead <= 0 || eg_ah_win == 0 || il < 0 || il >= g.nl || T < 1 || T > kWin) return true;
        Dev& d = devs[(size_t) di];
        for (size_t e = 0; e < eg_ah_trig.size() && e < (size_t) Dev::kEgAh; ++e) {
            if (eg_ah_trig[e] != il) continue;
            const int le = g.eg_layers[e];
            if (le < 0 || le >= g.nl || d.eg_st == nullptr || d.eg_ah_kv[e] == nullptr) continue;
            Layer& L1 = L[(size_t) le];
            int mi = -1;
            for (int m = 0; m < L1.nm; ++m)
                if (member(L1, m).dev == di) mi = m;
            if (mi < 0) continue;   // (this device does not hold that layer)
            Layer& l = member(L1, mi);
            if (l.eg != (int) e || l.eg_wkv.fmt == 0) continue;   // (fmt 0, EXL3: no scratch made for the side stream)
            const int nm = L1.nm, D = g.dim, H = g.hc;
            const int cols = (pk.eg_ngram - 1) * pk.eg_heads, ehd = pk.eg_hd;
            const size_t per = (size_t) cols * (ehd + ehd / 32);
            cudaSetDevice(d.id);
            cudaStream_t s2 = d.eg_st;
            CK(cudaEventRecord(d.eg_ev_main, d.st));
            CK(cudaStreamWaitEvent(s2, d.eg_ev_main, 0));
            eg_finish(*eg_win[e]);   // (asked for when the window began)
            uint8_t* src = h_eg + e * eg_cap * per;
            uint8_t* rows = d.eg_ah_rows[e];
            float* x = d.eg_ah_x[e];
            float* kv = d.eg_ah_kv[e];
            for (int t = 0; t < T; ++t)   // [token][rows | scales] -> [all rows][all scales]
                CK(cudaMemcpyAsync(rows + (size_t) t * cols * ehd, src + (size_t) t * per, (size_t) cols * ehd,
                                   cudaMemcpyHostToDevice, s2));
            uint8_t* sc = rows + (size_t) T * cols * ehd;
            for (int t = 0; t < T; ++t)
                CK(cudaMemcpyAsync(sc + (size_t) t * cols * (ehd / 32), src + (size_t) t * per + (size_t) cols * ehd,
                                   (size_t) cols * (ehd / 32), cudaMemcpyHostToDevice, s2));
            engram_dequant(rows, sc, T * cols, ehd, x, s2, (int) eg_fmt[e]);
            const bool split = eg_split > 0 && nm > 1 && T == 1 && d.eg_nz != nullptr;   // (layer()'s DS4_EG_SPLIT test)
            if (split) {
                const int N = (H + 1) * D, r0 = (int) ((long long) mi * N / nm), r1 = (int) ((long long) (mi + 1) * N / nm);
                CK(cudaMemcpyAsync(kv, d.eg_nz, (size_t) N * 4, cudaMemcpyDeviceToDevice, s2));
                const x3::Mat part = gg::view(l.eg_wkv, r0, r1 - r0);
                const x3::MvJob j = job(part, x, kv + r0, 1, (size_t) cols * ehd, (size_t) N);
                if (!mv_any(&j, 1, s2)) {
                    err = "DS4_EG_AHEAD: the Engram GEMV slice failed";
                    return false;
                }
            } else {
                const x3::MvJob j = job(l.eg_wkv, x, kv, T, (size_t) cols * ehd, (size_t) (H + 1) * D);
                if (!mv_any(&j, 1, s2)) {
                    err = "DS4_EG_AHEAD: the Engram GEMV failed";
                    return false;
                }
            }
            CK(cudaEventRecord(d.eg_ev[e], s2));
            Dev::EgAhPend& pd = d.eg_pend[e];
            pd.win = eg_ah_win;
            pd.p0 = p0;
            pd.T = T;
            pd.split = split;
        }
        return true;
    }

    // layer L0 for the window, as group member mi (its share of the heads, of the output projection and of the FFNs;
    // the partial sums all-reduced across the group)
    bool layer(Layer& L0, int mi, int64_t p0, int T, const WinPlan& wp, std::string& err) {
        Layer& l = member(L0, mi);
        Dev& d = devs[(size_t) l.dev];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int nm = L0.nm;
        const int D = g.dim, H = g.hc, HD = g.hd, NHL = l.ahn, HQ = NHL * HD, OG = l.ogn, FF = l.ffn;
        const ArGroup& ag = groups[(size_t) L0.grp].ar;
        const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
        if (ds4_dbg("DS4_DBG_SLOTS") && l.il < 2 && l.lay.fmt == gg::kFmtMXFP4) {   // DBG: a resident expert's bytes against its file's
            ds4_metal_flush();
            int shown = 0;
            for (int e = 0; e < l.n_exp && shown < 3; ++e) {
                if (l.slot[(size_t) e] < 0) continue;
                std::vector<uint8_t> want(l.blob, 0);
                read_mx_file(l, e, want.data());
                const uint8_t* have = (const uint8_t*) strata::gpu::host_view(l.vram_base + (size_t) l.slot[(size_t) e] * unit(l));
                size_t bad = 0, first = 0;
                for (size_t i = 0; i < l.blob; ++i)
                    if (want[i] != have[i]) { if (!bad) first = i; ++bad; }
                std::fprintf(stderr, "DBG slot il=%d e=%d slot=%d blob=%zu mismatching bytes=%zu first=%zu\n", l.il, e, l.slot[(size_t) e], l.blob, bad, first);
                ++shown;
            }
        }
        if (ds4_dbg("DS4_TRACE_DISP")) std::fprintf(stderr, "TRACE layer %d p0=%lld T=%d\n", l.il, (long long) p0, T);
        if (ds4_dbg("DS4_DBG_H") && mi == 0 && (l.il < 2 || ds4_dbg("DS4_DBG_ALL"))) {   // DBG
            std::vector<float> hv((size_t) T * H * D);
            cudaSetDevice(d.id);
            ds4_metal_flush();
            {
                const float* hvp = (const float*) strata::gpu::host_view(d.h);
                if (hvp) std::memcpy(hv.data(), hvp, hv.size() * 4);
            }
            int nf = 0, nzv = 0;
            float mx = 0.0f;
            size_t firstnan = 0, lastnan = 0;
            for (size_t i = 0; i < hv.size(); ++i) {
                const float v = hv[i];
                if (!(v == v)) { if (nf == 0) firstnan = i; lastnan = i; ++nf; continue; }
                if (v != 0.0f) ++nzv;
                if (std::fabs(v) > mx) mx = std::fabs(v);
            }
            std::fprintf(stderr, "DBG h: il=%d dev=%d h=%p p0=%lld T=%d p0tok=%d zeros=%zu ninf=%d max=%.4g first=%.5g %.5g nan_range=%zu..%zu\n",
                         l.il, (int) l.dev, (void*) d.h, (long long) p0, T, toks.empty() ? -1 : toks[(size_t) p0],
                         hv.size() - (size_t) nzv - (size_t) nf, nf, mx, hv[0], hv.size() > 1 ? hv[1] : 0.0f, firstnan, lastnan);
        }
        prof_mark(d, 0);
        // Engram
        Dev::EgAhPend* eap = nullptr;   // (DS4_EG_AHEAD: this window's prefetch of this layer on this device, if any)
        if (eg_ahead > 0 && l.eg >= 0 && l.eg < Dev::kEgAh) {
            Dev::EgAhPend& pd = d.eg_pend[l.eg];
            if (pd.win != 0 && pd.win == eg_ah_win && pd.p0 == p0 && pd.T == T) eap = &pd;
        }
        if (eap != nullptr) {   // DS4_EG_AHEAD: the chain ran on the side stream; the gate waits for it
            const int e = l.eg;
            const bool split = eap->split;
            eap->win = 0;
            CK(cudaStreamWaitEvent(s, d.eg_ev[e], 0));
            if (split) allreduce(d.eg_ah_kv[e], (H + 1) * D, ag, mi, ++d.ar_seq, d.xcnt, s);   // (DS4_EG_SPLIT's all-gather, in place)
            if (ds4_dbg("DS4_DBG_EG")) dbg_nf("eg_kv", l.il, d.eg_ah_kv[e], (size_t) T * (H + 1) * D);
            dump_sub(d, "eg_kv", l.il, p0, T, d.eg_ah_kv[e], (size_t) T * (H + 1) * D * 4);
            dump_sub(d, "eg_h0", l.il, p0, T, d.h, (size_t) T * H * D * 4);
            dump_sub(d, "eg_w", l.il, p0, 1, l.eg_w, (size_t) H * D * 4);
            engram_gate(d.h, d.eg_ah_kv[e], l.eg_w, H, D, T, g.eps, s);
            dump_sub(d, "eg_h", l.il, p0, T, d.h, (size_t) T * H * D * 4);
            if (ds4_dbg("DS4_DBG_EG")) dbg_nf("h_after_gate", l.il, d.h, (size_t) T * H * D);
            ++eg_ah_used;
            if (eg_ah_said.exchange(1) == 0)
                std::fprintf(stderr, "ds4: DS4_EG_AHEAD engaged: layer %d's Engram chain taken from the side stream (T=%d, %s)\n",
                             l.il, T, split ? "the DS4_EG_SPLIT slice, all-gathered in place" : "the whole GEMV");
        } else if (l.eg >= 0) {
            if (eg_ahead > 0) ++eg_ah_old;   // (DS4_EG_AHEAD: not prefetched - the old path)
            const int cols = (pk.eg_ngram - 1) * pk.eg_heads, ehd = pk.eg_hd;
            const size_t per = (size_t) cols * (ehd + ehd / 32);
            eg_finish(*eg_win[(size_t) l.eg]);   // (asked for when the window began)
            uint8_t* src = h_eg + (size_t) l.eg * eg_cap * per;
            for (int t = 0; t < T; ++t)   // [token][rows | scales] -> [all rows][all scales]
                CK(cudaMemcpyAsync(d.eg_rows + (size_t) t * cols * ehd, src + (size_t) t * per, (size_t) cols * ehd,
                                   cudaMemcpyHostToDevice, s));
            uint8_t* sc = d.eg_rows + (size_t) T * cols * ehd;
            for (int t = 0; t < T; ++t)
                CK(cudaMemcpyAsync(sc + (size_t) t * cols * (ehd / 32), src + (size_t) t * per + (size_t) cols * ehd,
                                   (size_t) cols * (ehd / 32), cudaMemcpyHostToDevice, s));
            engram_dequant(d.eg_rows, sc, T * cols, ehd, d.eg_x, s, (int) eg_fmt[(size_t) l.eg]);
            dump_sub(d, "eg_rows", l.il, p0, T, d.eg_rows, (size_t) T * cols * ehd);
            dump_sub(d, "eg_x", l.il, p0, T, d.eg_x, (size_t) T * cols * ehd * 4);
            if (ds4_dbg("DS4_DBG_EG")) {
                dbg_nf("eg_x", l.il, d.eg_x, (size_t) T * cols * ehd);
                const float* xv = (const float*) strata::gpu::host_view(d.eg_x);
                for (size_t i = 0; i < (size_t) T * cols * ehd; ++i)
                    if (!std::isfinite(xv[i])) {
                        const size_t t = i / ((size_t) cols * ehd), c = (i / ehd) % cols;
                        const uint8_t* dv = (const uint8_t*) strata::gpu::host_view(d.eg_rows) + (t * cols + c) * ehd;
                        const uint8_t* hv = src + t * per + c * ehd;
                        std::fprintf(stderr, "DBG eg bad x: t=%zu c=%zu e=%zu | dev/host row bytes:", t, c, i % ehd);
                        for (int b = 0; b < 80; ++b) std::fprintf(stderr, "%s%02x/%02x", b % 18 == 0 ? " |" : " ", dv[b], hv[b]);
                        std::fprintf(stderr, "\n");
                        break;
                    }
            }
            if (eg_split > 0 && nm > 1 && T == 1 && d.eg_nz != nullptr) {   // DS4_EG_SPLIT (see eg_split)
                const int N = (H + 1) * D, r0 = (int) ((long long) mi * N / nm), r1 = (int) ((long long) (mi + 1) * N / nm);
                CK(cudaMemcpyAsync(d.eg_kv, d.eg_nz, (size_t) N * 4, cudaMemcpyDeviceToDevice, s));
                const x3::Mat part = gg::view(l.eg_wkv, r0, r1 - r0);
                if (!mv(d, {job(part, d.eg_x, d.eg_kv + r0, 1, (size_t) cols * ehd, (size_t) N)}, err)) return false;
                allreduce(d.eg_kv, N, ag, mi, ++d.ar_seq, d.xcnt, s);
            } else if (!mv(d, {job(l.eg_wkv, d.eg_x, d.eg_kv, T, (size_t) cols * ehd, (size_t) (H + 1) * D)}, err))
                return false;
            if (ds4_dbg("DS4_DBG_EG")) dbg_nf("eg_kv", l.il, d.eg_kv, (size_t) T * (H + 1) * D);
            dump_sub(d, "eg_kv", l.il, p0, T, d.eg_kv, (size_t) T * (H + 1) * D * 4);
            dump_sub(d, "eg_h0", l.il, p0, T, d.h, (size_t) T * H * D * 4);
            dump_sub(d, "eg_w", l.il, p0, 1, l.eg_w, (size_t) H * D * 4);
            engram_gate(d.h, d.eg_kv, l.eg_w, H, D, T, g.eps, s);
            dump_sub(d, "eg_h", l.il, p0, T, d.h, (size_t) T * H * D * 4);
            if (ds4_dbg("DS4_DBG_EG")) dbg_nf("h_after_gate", l.il, d.h, (size_t) T * H * D);
        }
        if (bt_on) {   // DS4_BATCH_DECODE: a batch window's rows are B sequences (attn_batch), then the MoE as for any window
            if (!attn_batch(L0, mi, T, wp, err)) return false;
            return ffn(L0, mi, p0, T, wp, err);
        }
        dump_sub(d, "h_in", l.il, p0, T, d.h, (size_t) T * H * D * 4);
        dump_sub(d, "ring_in", l.il, p0, T, l.win, (size_t) g.win * kv_row_bytes(kKvFp8, HD));
        // attention
        const bool hcf = hc_fuses(l, T);   // (DS4_HC_FUSE: the mix, split, norm and x's int8 rounding in one launch)
        gg::PreQ8 xq8;
        if (hcf) {
            if (!hc_fused(d, l, false, T, xq8, err)) return false;
        } else {
#if defined(STRATA_METAL)
        hc_mix_split(d.h, l.hca_fn, H * D, (2 + H) * H, T, g.eps, d.mix, l.hca_scale, l.hca_base, H,
                     g.sinkhorn, g.hc_eps, d.a_pre, d.a_post, d.a_comb, s);
#else
        hc_mix_split(d.h, l.hca_fn, H * D, (2 + H) * H, T, g.eps, d.mix, d.hccnt, l.hca_scale, l.hca_base, H, g.sinkhorn, g.hc_eps,
                     d.a_pre, d.a_post, d.a_comb, s);
#endif
        }
        dump_sub(d, "a_mix", l.il, p0, T, d.mix, (size_t) T * 32 * 4);
        dump_sub(d, "a_pre", l.il, p0, T, d.a_pre, (size_t) T * 8 * 4);
        dump_sub(d, "a_post", l.il, p0, T, d.a_post, (size_t) T * 8 * 4);
        dump_sub(d, "a_comb", l.il, p0, T, d.a_comb, (size_t) T * 64 * 4);
        if (!hcf) hc_pre_norm(d.h, d.pre, l.attn_norm, D, H, T, g.eps, d.x, s);
        dump_sub(d, "pre_in", l.il, p0, T, d.pre, (size_t) T * 8 * 4);
        dump_sub(d, "attn_x", l.il, p0, T, d.x, (size_t) T * D * 4);
        {
            x3::MvJob j[4];
            const int nj = attn_in_jobs(l, d.x, d.qr, d.kvr, d.ckr, d.cgr, T, j);
            if (!mv_n(d, j, nj, err, hcf ? &xq8 : nullptr)) return false;
        }
        dump_sub(d, "qr_raw", l.il, p0, T, d.qr, (size_t) T * g.q_lora * 4);
        dump_sub(d, "kvr_raw", l.il, p0, T, d.kvr, (size_t) T * HD * 4);
        Finish fq;
        fq.w = l.q_norm;
        fq.eps = g.eps;
        gg::PreQ8 qrp;   // (DS4_DECODE_TRIM bit 2: q's norm rounds wq_b's int8 input where it makes it)
        const bool qr8 = NHL > 0 && trim_q(d, l, T, fq, qrp);
        Finish fk;   // (DS4_ATTN_MERGE: made here, before q's launches - it reads only the window's position)
        fk.w = l.kv_norm;
        fk.eps = g.eps;
        fk.rd = g.rd;
        fk.pos = (int) p0;
        fk.freqs = freqs;
        fk.quant = 1;
        fk.dst = d.ext + (size_t) g.win * HD;
        fk.dst_stride = HD;
        // DS4_ATTN_MERGE: q's norm, the ring's rows into ext and the KV row's finish read only the input GEMVs' rows
        // and the ring (each writes its own buffer: qr / its int8, ext rows 0 .. win - 1, ext rows win ..): one launch.
        // Then q's RoPE and the KV row into the ring (which reads the finish's ext rows, and writes the slot ring_to_ext
        // read in the launch before): another.  Unmerged, the old order below
        bool merged = false;
        if (attn_merges(l, T)) {
            FinOp a[3];
            a[0].kind = 0;
            a[0].x = d.qr;
            a[0].n_vec = T;
            a[0].len = g.q_lora;
            a[0].stride = g.q_lora;
            a[0].f = fq;
            a[1].kind = 1;
            a[1].ring_r = l.win;
            a[1].ext_w = d.ext;
            a[1].p0 = p0;
            a[1].n = g.win;
            a[1].d = HD;
            a[2].kind = 0;
            a[2].x = d.kvr;
            a[2].n_vec = T;
            a[2].len = HD;
            a[2].stride = HD;
            a[2].f = fk;
            merged = finish_multi(a, 3, s);
        }
        if (!merged) finish(d.qr, T, g.q_lora, g.q_lora, fq, s);
        dump_sub(d, "qr", l.il, p0, T, d.qr, (size_t) T * g.q_lora * 4);
        Finish fr;
        fr.rd = g.rd;
        fr.pos = (int) p0;
        fr.vpp = NHL;
        fr.freqs = freqs;
        if (NHL > 0) {
            x3::MvJob jb = job(l.a3 ? l.a3_qd : l.wq_b, d.qr, d.q, T, g.q_lora, HQ);   // (a3: its decode prefix)
            if (!mv_n(d, &jb, 1, err, qr8 ? &qrp : nullptr)) return false;
            if (!merged) finish(d.q, T * NHL, HD, HD, fr, s);
        }
        // DS4_ATTN_MERGE=3: the arguments sparse_attn gets below (ar3 / ckv3, made the same way as ar / ckv there - and
        // compared with them there), when its unpack's inputs are final now: no indexer of this layer's own (ix_src: the
        // top-k comes later in this layer) and no compressed row of this layer's own written by this window (kv_src, a
        // group completed: finish() writes it into ckv later in this layer).  The KV of other layers / groups is in place
        // (earlier layers, xfer_get before the layer)
        SelOp sel3;
        AttnRows ar3;
        const void* ckv3 = nullptr;
        bool fold3 = false;
        if (merged && attn_merge > 2 && NHL > 0 && !l.ix_src) {
            bool ok3 = true;
            for (int t = 0; t < T; ++t) {
                const int first = (int) std::max<int64_t>(g.win - p0, t + 1);
                ar3.win0[t] = first;
                ar3.nwin[t] = g.win + t - first + 1;
                ar3.nsel[t] = 0;
            }
            if (l.ratio > 0) {
                const int R = l.ratio;
                const int ng = (int) std::max<int64_t>(0, (p0 + T) / R - p0 / R);
                if (l.kv_src && ng > 0) ok3 = false;
                for (int t = 0; t < T && ok3; ++t) ar3.nsel[t] = (int) ((p0 + t + 1) / R) > 0 ? wp.topk[l.il][t] : 0;
                ckv3 = srcs[(size_t) l.src].ckv[(size_t) l.dev];
            }
            fold3 = ok3 && sparse_attn_sel_op(ckv3, d.topk, (int) topk_stride(), ar3, HD, T, kKvFp4, 0, &d.attn_scr, sel3);
        }
        if (merged) {
            FinOp b[2];
            int nb = 0;
            if (NHL > 0) {
                b[nb].kind = 0;
                b[nb].x = d.q;
                b[nb].n_vec = T * NHL;
                b[nb].len = HD;
                b[nb].stride = HD;
                b[nb].f = fr;
                ++nb;
            }
            b[nb].kind = 2;
            b[nb].ext_r = d.ext;
            b[nb].ring_w = l.win;
            b[nb].backup = spec_win ? l.ring_bak : nullptr;
            b[nb].p0 = p0;
            b[nb].n = g.win;
            b[nb].T = T;
            b[nb].d = HD;
            ++nb;
            if (fold3) fold3 = finish_multi_sel(b, nb, sel3, s);   // (DS4_ATTN_MERGE=3; refused: the =2 launch below)
            if (!fold3 && !finish_multi(b, nb, s)) {   // (each op as its own launch then: independent, so any order)
                if (NHL > 0) finish(d.q, T * NHL, HD, HD, fr, s);
                ext_to_ring(d.ext, l.win, p0, g.win, T, HD, s, spec_win ? l.ring_bak : nullptr);
            }
        }
        if (NHL > 0) dump_sub(d, "q", l.il, p0, T, d.q, (size_t) T * HQ * 4);
        // the window rows: the ring's (positions p0 - win ..) then this window's, each query its own 128.  A DSpark
        // block's ring holds the trunk's main KV (positions <= p0 - 1, seeded); its block of drafts attends to all of
        // that ring and to the whole block, and leaves the ring as it was
        if (!merged) {
        ring_to_ext(l.win, d.ext, l.mtp ? (int64_t) g.win : p0, g.win, HD, s);   // (a block's ring: its rows as they lie)
        finish(d.kvr, T, HD, HD, fk, s);
        if (!l.mtp) ext_to_ring(d.ext, l.win, p0, g.win, T, HD, s, spec_win ? l.ring_bak : nullptr);
        }
        dump_sub(d, "kv_win", l.il, p0, T, d.ext + (size_t) g.win * HD, (size_t) T * HD * 4);
        dump_sub(d, "ext", l.il, p0, T, d.ext, ((size_t) g.win + T) * HD * 2);   // (BF16 rows: the ring's, then this window's)
        AttnRows ar;
        for (int t = 0; t < T; ++t) {
            if (l.mtp) {
                ar.win0[t] = 0;
                ar.nwin[t] = (int) std::min<int64_t>(g.win, p0);
                ar.nsel[t] = T;
                continue;
            }
            const int first = (int) std::max<int64_t>(g.win - p0, t + 1);   // ext row of position max(0, p - win + 1)
            ar.win0[t] = first;
            ar.nwin[t] = g.win + t - first + 1;
            ar.nsel[t] = 0;
        }
        const void* ckv = nullptr;
        int ckv_fmt = kKvFp4;
        if (l.ratio > 0) {
            Src& sr = srcs[(size_t) l.src];
            const int R = l.ratio;
            // the groups this window completes: g_first .. g_first + ng - 1
            const int64_t g_first = p0 / R;              // the first group whose last position is >= p0
            const int64_t g_end = (p0 + T) / R;          // groups completed by p0 + T - 1
            const int ng = (int) std::max<int64_t>(0, g_end - g_first);
            if (l.kv_src) {
                if (R == 1) {
                    Finish fc;
                    fc.w = l.c_norm;
                    fc.eps = g.eps;
                    finish(d.ckr, T, HD, HD, fc, s);
                    if (trims_copy(l)) {   // (DS4_DECODE_TRIM bit 4: one kernel, no runtime copy)
                        CopyRegions cr;
                        cr.dst[0] = d.latent;
                        cr.src[0] = d.ckr;
                        cr.bytes[0] = (size_t) T * HD * 4;
                        cr.n = 1;
                        if (!copy_regions(cr, s)) {
                            err = "DS4_DECODE_TRIM: the latent copy refused";
                            return false;
                        }
                    } else
                    CK(cudaMemcpyAsync(d.latent, d.ckr, (size_t) T * HD * 4, cudaMemcpyDeviceToDevice, s));
                } else {
                    if (spec_win && l.c_snap != nullptr) {   // to replay the accepted rows if drafts are rejected
                        const size_t ns = (size_t) R * HD * 4, nr = (size_t) T * HD * 4;
                        if (trims_copy(l)) {   // (DS4_DECODE_TRIM bit 4: the four in one kernel)
                            CopyRegions cr;
                            cr.dst[0] = l.c_snap;
                            cr.src[0] = l.c_kv;
                            cr.bytes[0] = ns;
                            cr.dst[1] = l.c_snap + (size_t) R * HD;
                            cr.src[1] = l.c_score;
                            cr.bytes[1] = ns;
                            cr.dst[2] = l.c_rows;
                            cr.src[2] = d.ckr;
                            cr.bytes[2] = nr;
                            cr.dst[3] = l.c_rows + (size_t) kWin * HD;
                            cr.src[3] = d.cgr;
                            cr.bytes[3] = nr;
                            cr.n = 4;
                            if (!copy_regions(cr, s)) {
                                err = "DS4_DECODE_TRIM: the snapshot copies refused";
                                return false;
                            }
                        } else {
                        CK(cudaMemcpyAsync(l.c_snap, l.c_kv, ns, cudaMemcpyDeviceToDevice, s));
                        CK(cudaMemcpyAsync(l.c_snap + (size_t) R * HD, l.c_score, ns, cudaMemcpyDeviceToDevice, s));
                        CK(cudaMemcpyAsync(l.c_rows, d.ckr, nr, cudaMemcpyDeviceToDevice, s));
                        CK(cudaMemcpyAsync(l.c_rows + (size_t) kWin * HD, d.cgr, nr, cudaMemcpyDeviceToDevice, s));
                        }
                    }
                    compress_win(d.ckr, d.cgr, l.c_kv, l.c_score, R, (int) p0, T, HD, l.c_norm, g.eps, d.latent, s);
                    dump_sub(d, "ckr", l.il, p0, T, d.ckr, (size_t) T * HD * 4);
                    dump_sub(d, "cgr", l.il, p0, T, d.cgr, (size_t) T * HD * 4);
                }
            }
            Rows lim;
            int clen_max = 0;
            for (int t = 0; t < T; ++t) {
                lim.n[t] = (int) ((p0 + t + 1) / R);
                lim.k[t] = std::min(g.ix_topk, lim.n[t]);
                clen_max = std::max(clen_max, lim.n[t]);
            }
            if (l.ix_src) {
                Src& ks = srcs[(size_t) l.ik_src];
                if (l.owns_k && ng > 0) {
                    if (!mv(d, {job(l.i_wk, d.latent, d.ikr, ng, HD, g.ix_hd)}, err)) return false;
                    Finish fi;
                    fi.w = l.ik_norm;
                    fi.eps = g.eps;
                    fi.rd = g.rd;
                    fi.pos = (int) (g_first * R);
                    fi.pos_step = R;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    fi.pdst = ks.ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                    fi.pdst_stride = (long long) ik_rb();
                    finish(d.ikr, ng, g.ix_hd, g.ix_hd, fi, s);
                    if (!wp.par && !replicate(ks.ik, ks.h_ik, ks.ev_ik, fi.pdst, (size_t) g_first * ik_rb(),
                                              (size_t) ng * ik_rb(), l.dev, err))
                        return false;
                }
                if (clen_max > 0) {
                    if (!mv(d, {job(l.i_wq_b, d.qr, d.iq, T, g.q_lora, (size_t) g.ix_heads * g.ix_hd)}, err)) return false;
                    Finish fi;
                    fi.rd = g.rd;
                    fi.pos = (int) p0;
                    fi.vpp = g.ix_heads;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    finish(d.iq, T * g.ix_heads, g.ix_hd, g.ix_hd, fi, s);
                    // (iw rows are 64 apart)
                    gemv_f16_rows(l.i_wproj, d.x, (size_t) D, g.ix_heads, D, T,
                                  1.0f / std::sqrt((float) g.ix_hd) / std::sqrt((float) g.ix_heads), d.iw, 64, s);
                    const long long ss = (long long) o.max_context + 64;
                    bool restrict_ = false;
                    for (int t = 0; t < T; ++t)
                        restrict_ = restrict_ || (lim.n[t] + g.cand_blk - 1) / g.cand_blk > g.cand_topk;
                    if (l.uses_cand && restrict_) {
                        Rows cl;   // the candidate positions of each query: its blocks x blk
                        int nmax = 0;
                        for (int t = 0; t < T; ++t) {
                            cl.n[t] = lim.n[t];
                            cl.k[t] = wp.cand[l.il][t];
                            nmax = std::max(nmax, wp.cand[l.il][t] * g.cand_blk);
                        }
                        index_score(d.iq, d.iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, T, nmax, d.cand,
                                    (int) cand_stride(), g.cand_blk, cl, d.scores, ss, s);
                        Rows tr;
                        for (int t = 0; t < T; ++t) {
                            tr.n[t] = wp.cand[l.il][t] * g.cand_blk;
                            tr.k[t] = lim.k[t];
                        }
                        topk(d.scores, ss, T, tr, d.cand, (int) cand_stride(), g.cand_blk, d.topk, (int) topk_stride(), s,
                             tmb_of(d), kWin, topk_mb_min);
                    } else {
                        index_score(d.iq, d.iw, ks.ik[(size_t) l.dev], g.ix_heads, g.ix_hd, T, clen_max, nullptr, 0, 1,
                                    lim, d.scores, ss, s);
                        if (l.cand_src) {
                            Rows cr;
                            for (int t = 0; t < T; ++t) {
                                cr.n[t] = lim.n[t];
                                cr.k[t] = g.cand_topk;
                            }
                            cand_blocks(d.scores, ss, T, cr, g.cand_blk, d.bm, (long long) bm_stride(), d.cand,
                                        (int) cand_stride(), s, tmb_of(d), kWin, topk_mb_min);
                        }
                        topk(d.scores, ss, T, lim, nullptr, 0, 1, d.topk, (int) topk_stride(), s, tmb_of(d), kWin,
                             topk_mb_min);
                    }
                }
            }
            if (l.kv_src && ng > 0) {
                Finish fc;
                fc.rd = g.rd;
                fc.pos = (int) (g_first * R);
                fc.pos_step = R;
                fc.freqs = freqs;
                fc.quant = 2;
                fc.pdst = sr.ckv[(size_t) l.dev] + (size_t) g_first * ckv_rb();
                fc.pdst_stride = (long long) ckv_rb();
                finish(d.latent, ng, HD, HD, fc, s);
                if (!wp.par && !replicate(sr.ckv, sr.h_ckv, sr.ev_ckv, fc.pdst, (size_t) g_first * ckv_rb(),
                                          (size_t) ng * ckv_rb(), l.dev, err))
                    return false;
                if (wp.par && mi == 0 && sr.remote) {   // the new rows for the other groups' readers
                    Xfer x;
                    x.src[0] = fc.pdst;
                    x.dst[0] = sr.x_stage;
                    x.bytes[0] = (size_t) ng * ckv_rb();
                    x.n = 1;
                    if (l.owns_k && srcs[(size_t) l.ik_src].ik[(size_t) l.dev] != nullptr) {
                        x.src[1] = srcs[(size_t) l.ik_src].ik[(size_t) l.dev] + (size_t) g_first * ik_rb();
                        x.dst[1] = sr.x_stage + x_cap() * ckv_rb();
                        x.bytes[1] = (size_t) ng * ik_rb();
                        x.n = 2;
                    }
                    xfer_put(x, sr.x_flag, wp.win, d.xcnt, s);
                }
            }
            if (ng > 0) dump_sub(d, "latent", l.il, p0, ng, d.latent, (size_t) ng * HD * 4);
            dump_sub(d, "topk", l.il, p0, T, d.topk, (size_t) T * topk_stride() * 4);
            for (int t = 0; t < T; ++t) ar.nsel[t] = lim.n[t] > 0 ? wp.topk[l.il][t] : 0;
            ckv = sr.ckv[(size_t) l.dev];
        }
        if (l.mtp) {   // the block's rows (BF16), after the ring's in ext, as every query's selection
            ckv = d.ext + (size_t) g.win * HD;
            ckv_fmt = kKvBf16;
            iota_rows(d.topk, T, T, (int) topk_stride(), s);
        }
        if (NHL > 0) {
            bool seld = false;   // (DS4_ATTN_MERGE=3: the folded unpack had exactly these arguments, else it runs again here)
            if (fold3) {
                seld = ckv == ckv3 && ckv_fmt == kKvFp4 && ar.gen == ar3.gen;
                for (int t = 0; t < T && seld; ++t)
                    seld = ar.win0[t] == ar3.win0[t] && ar.nwin[t] == ar3.nwin[t] && ar.nsel[t] == ar3.nsel[t];
                if (!seld && !am3_warned.exchange(true))
                    std::fprintf(stderr, "ds4: DS4_ATTN_MERGE=3: layer %d: the folded unpack's arguments differ from sparse_attn's - "
                                         "unpacked again (correct, slower; please report)\n", l.il);
            }
            sparse_attn(d.q, d.ext, ckv, d.topk, (int) topk_stride(), ar, l.sink, NHL, HD, T,
                        1.0f / std::sqrt((float) HD), d.o, s, ckv_fmt, 0, &d.attn_scr, -1, seld);
            dump_sub(d, "o", l.il, p0, T, d.o, (size_t) T * HQ * 4);
            Finish fo;
            fo.rd = g.rd;
            fo.pos = (int) p0;
            fo.vpp = NHL;
            fo.freqs = freqs;
            fo.inverse = 1;
            fo.quant = 1;
            const int per = HQ / OG;
            // (xtxkern DS4_XK_QO / DS4_XK_QA: the roundings in HC_FUSE's int8 rows past row 0 - o's at row 1, oa's after)
            const bool xfit = T == 1 && !l.mtp && d.xq8 != nullptr && d.xd8 != nullptr && HD % 32 == 0 && per % 32 == 0 &&
                              g.o_lora % 32 == 0 && OG <= 4 && (size_t) D + HQ + (size_t) OG * g.o_lora <= (size_t) kWin * D;
            const bool xo = xk_qo && xfit, xa = xk_qa && xfit;
            int8_t* oq = xfit ? d.xq8 + D : nullptr;
            float* od = xfit ? d.xd8 + D / 32 : nullptr;
            if (xo) {   // (finish_kernel<false, true>: q8_quant's ops on the stored values; the heads' 32-blocks are the groups')
                fo.q8 = oq;
                fo.q8d = od;
            }
            finish(d.o, T * NHL, HD, HD, fo, s);
            dump_sub(d, "o_fin", l.il, p0, T, d.o, (size_t) T * HQ * 4);
            x3::MvJob j[16];
            for (int gi = 0; gi < OG; ++gi)
                j[gi] = job(l.wo_a[gi], d.o + (size_t) gi * per, d.oa + (size_t) gi * g.o_lora, T, HQ, (size_t) OG * g.o_lora);
            bool qa_done = false;
            if (xa) {   // (FG-16 DS4_XK_QA) wo_a's groups with their outputs rounded (Q5_K only; anything else: the old launches)
                XkQaJob qj[4];
                bool ok = true;
                for (int gi = 0; gi < OG && ok; ++gi) {
                    ok = gg::q5k_rows(l.wo_a[gi], &qj[gi].w, &qj[gi].ld) && l.wo_a[gi].k == per && j[gi].bias == nullptr;
                    qj[gi].xq = oq + (size_t) gi * per;
                    qj[gi].xd = od + (size_t) gi * per / 32;
                    qj[gi].k = per;
                    qj[gi].n = l.wo_a[gi].n;
                    qj[gi].y = d.oa + (size_t) gi * g.o_lora;
                    qj[gi].alpha = j[gi].alpha;
                    qj[gi].q = oq + HQ + (size_t) gi * g.o_lora;
                    qj[gi].qd = od + HQ / 32 + (size_t) gi * g.o_lora / 32;
                    ok = ok && qj[gi].n == g.o_lora;
                }
                if (ok) {
                    if (!xo) gg::q8_rows(d.o, (size_t) HQ, 1, HQ, oq, od, s);   // (the groups' rounding, one launch as before)
                    qa_done = xk_mv_q5k_q8(qj, OG, s);
                }
            }
            if (!qa_done) {
            gg::PreQ8 po;   // (DS4_XK_QO: the groups read the finish's rounding, slice gi of the heads' vector)
            po.x = d.o;
            po.q = oq;
            po.d = od;
            po.k = per;
            po.rows = 1;
            po.nslice = OG;
            po.slice = (size_t) per;
            if (!mv_n(d, j, OG, err, xo ? &po : nullptr)) return false;
            if (!mv(d, {job(l.a3 ? l.a3_bd : l.wo_b, d.oa, d.ao, T, (size_t) OG * g.o_lora, D)}, err)) return false;
            } else {   // (DS4_XK_QA: wo_b reads wo_a's rounding of oa)
                x3::MvJob jb = job(l.a3 ? l.a3_bd : l.wo_b, d.oa, d.ao, T, (size_t) OG * g.o_lora, D);
                gg::PreQ8 pb;
                pb.x = d.oa;
                pb.q = oq + HQ;
                pb.d = od + HQ / 32;
                pb.k = OG * g.o_lora;
                pb.rows = 1;
                if (!mv_n(d, &jb, 1, err, &pb)) return false;
            }
        } else CK(cudaMemsetAsync(d.ao, 0, (size_t) T * D * sizeof(*d.ao), s));   // (no heads: nothing to add)
        dump_sub(d, "ao", l.il, p0, T, d.ao, (size_t) T * D * 4);
        if (!l.mtp) ar_then_post(d, d.ao, T, ag, mi, nm, d.a_post, d.a_comb, s);   // (DS4_AR_POST; unset: the two below)
        else {
        if (nm > 1) allreduce(d.ao, T * D, ag, mi, ++d.ar_seq, d.xcnt, s);
        hc_post(d.ao, d.h, d.a_post, d.a_comb, D, H, T, d.h2, s);
        }
        std::swap(d.h, d.h2);
        if (dump_l != nullptr && mi == 0) dump_layer(d, d.h, 1000 + l.il, p0, T);   // (DS4_DUMP_L: after the attention)
        dump_sub(d, "h_attn", l.il, p0, T, d.h, (size_t) T * H * D * 4);
        prof_mark(d, 1);
        return ffn(L0, mi, p0, T, wp, err);
    }

    // the second half of layer(): the MoE of the window's rows (each row's routing, the shared expert, the routed
    // experts on the GPUs, the helpers and the CPU lane), the partial sums all-reduced across the group.  (split
    // out of layer() as it was, so a batch window - DS4_BATCH_DECODE - runs it unchanged after attn_batch.)
    bool ffn(Layer& L0, int mi, int64_t p0, int T, const WinPlan& wp, std::string& err) {
        Layer& l = member(L0, mi);
        Dev& d = devs[(size_t) l.dev];
        if (eg_ahead > 0 && !eg_ahead_issue(l.dev, l.il, p0, T, err)) return false;   // (DS4_EG_AHEAD)
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int nm = L0.nm;
        const int D = g.dim, H = g.hc, FF = l.ffn;
        const ArGroup& ag = groups[(size_t) L0.grp].ar;
        // the MoE
        // (DS4_HC_FUSE: the mix, split, norm and x's int8 rounding in one launch, the split writing d.pre's copy of the
        //  pre slots - nothing here reads d.pre before the layer's end, whose copy is then skipped; xq8 for w1 / w3)
        const bool hcf = hc_fuses(l, T);
        gg::PreQ8 xq8;
        if (hcf) {
            if (!hc_fused(d, l, true, T, xq8, err)) return false;
        } else {
#if defined(STRATA_METAL)
        hc_mix_split(d.h, l.hcf_fn, H * D, (2 + H) * H, T, g.eps, d.mix, l.hcf_scale, l.hcf_base, H,
                     g.sinkhorn, g.hc_eps, d.f_pre, d.f_post, d.f_comb, s);
#else
        hc_mix_split(d.h, l.hcf_fn, H * D, (2 + H) * H, T, g.eps, d.mix, d.hccnt, l.hcf_scale, l.hcf_base, H, g.sinkhorn, g.hc_eps,
                     d.f_pre, d.f_post, d.f_comb, s);
#endif
        hc_pre_norm(d.h, d.a_pre, l.ffn_norm, D, H, T, g.eps, d.x, s);
        }
        const gg::PreQ8* sx8 = hcf ? &xq8 : nullptr;   // (the shared expert's w1 / w3 input)
        dump_sub(d, "f_pre", l.il, p0, T, d.f_pre, (size_t) T * 8 * 4);
        dump_sub(d, "f_post", l.il, p0, T, d.f_post, (size_t) T * 8 * 4);
        dump_sub(d, "f_comb", l.il, p0, T, d.f_comb, (size_t) T * 64 * 4);
        dump_sub(d, "ffn_x", l.il, p0, T, d.x, (size_t) T * D * 4);
        if (wp.async) {
            // the routing goes to the service thread through the mailbox (a group's lead publishes it, the members
            // make the same plan) while the device runs the shared expert and the VRAM experts (from the plan the
            // router made), and waits for the answer only before the experts' sum
            const unsigned sq = wp.seq[l.il];
            const int slot = (int) (sq % kRing);
            const bool lead = mi == 0;
            // (DS4_ROUTE_FUSE: the lead's router stage with one layer of guesses in two launches - the two gates, then
            //  the routing and the guesses, the publish as before; every other case the launches below)
            const Layer* nx1 = lead && ahead_mode == 1 && route_fuses(l, T) ? ahead_layer(L0, 1) : nullptr;
            const int m1 = nx1 != nullptr ? std::max(1, std::min(kAhead1, nx1->k_exp + ahead_extra)) : 0;
            if (nx1 != nullptr && route_fusable(l, *nx1, m1)) {
                RoutePair rp;
                rp.logits = d.glog;
                rp.bias = l.gate_bias;
                rp.n = l.n_exp;
                rp.k = l.k_exp;
                rp.route_scale = g.route_scale;
                rp.vram = l.vram_tab;
                rp.x = d.x;
                rp.dim = D;
                rp.idx = d.ridx;
                rp.w = d.rw;
                rp.plan_ptr = d.plan_ptr;
                rp.req = reqs + slot;
                rp.vl = wp.vl;   // (a trunk layer: route_fuses)
                rp.bias_vl = rp.vl != 0 ? l.gate_bias_vl : nullptr;
                rp.seq = sq;
                rp.na0 = m1;
                rp.na1 = 0;
                rp.a_logits = d.glog_a;
                rp.a_bias = nx1->gate_bias;
                rp.a_n = nx1->n_exp;
                rp.m = m1;
                rp.off = 0;
                rp.T = T;
                if (!gemv_f32_pair(l.gate_w, l.n_exp, d.glog, nx1->gate_w, nx1->n_exp, d.glog_a, d.x, D, T, 1024, s) ||
                    !route_pair(rp, s)) {   // (a GEMV not gone in reaches no routing; a routing, no publish)
                    err = "DS4_ROUTE_FUSE: a fused router launch did not go in (layer " + std::to_string(l.il) + ")";
                    return false;
                }
            } else {
            gemv_f32(l.gate_w, d.x, l.n_exp, D, T, d.glog, 1024, s);
            int na[2] = {0, 0};   // lookahead: the next layers' guesses (their gate on this FFN input), published below
            for (int a = 1; lead && a <= std::min(2, ahead_mode); ++a) {
                const Layer* nx = ahead_layer(L0, a);
                if (nx == nullptr) break;
                const int m = a == 1 ? std::max(1, std::min(kAhead1, nx->k_exp + ahead_extra)) : std::min(kPicks, nx->k_exp);
                float* gl = d.glog_a + (size_t) (a - 1) * kWin * 1024;
                gemv_f32(nx->gate_w, d.x, nx->n_exp, D, T, gl, 1024, s);   // (normed with the next layer's FFN
                                                                         // weights instead: the same hit rate)
                route_ahead(gl, nx->gate_bias, nx->n_exp, m, T, reqs + slot, (a - 1) * kAhead1, s);
                na[a - 1] = m;
            }
            if (lp_route || lp_pubfuse)   // leadpath (the same bytes; checked at load)
                route_publish_lp(lp_route, lp_pubfuse, d.glog, l.gate_bias, l.n_exp, l.k_exp, T, g.route_scale, l.vram_tab, d.x, D,
                                 d.ridx, d.rw, d.plan_ptr, lead ? reqs + slot : nullptr, sq, s, l.gate_bias_vl,
                                 l.mtp ? 0u : wp.vl, na[0], na[1], pub_cnt_of(l.dev));   // (DS4_HW_PUBT)
            else
            route_publish(d.glog, l.gate_bias, l.n_exp, l.k_exp, T, g.route_scale, l.vram_tab, d.x, D, d.ridx, d.rw,
                          d.plan_ptr, lead ? reqs + slot : nullptr, sq, s, l.gate_bias_vl, l.mtp ? 0u : wp.vl, na[0],
                          na[1]);
            }
#if defined(STRATA_USE_HIP)
            if (ec_chk != nullptr && dd_at(l.il, T))   // DS4_ECOWN + DS4_DD_AUDIT: this device's plan against the lead's marks
                strata_ds4_launch(ecown_chk_k, 1, 64, 0, s, (const Req*) (reqs + slot), sq, (const unsigned long long*) d.plan_ptr, T,
                                  l.k_exp, ec_chk + (size_t) l.dev * 4, ec_tmo[(size_t) l.dev]);
#endif
            {
                x3::MvJob js[2] = {job(l.s1, d.x, d.sg, T, D, FF), job(l.s3, d.x, d.su, T, D, FF)};
                if (!mv_n(d, js, 2, err, sx8)) return false;
            }
            {   // (DS4_DECODE_TRIM bit 1: the swiglu rounds s2's int8 input where it makes it)
                gg::PreQ8 s2q;
                bool s2f = false;
                if (!shared_swiglu(d, l, T, FF, s2q, s2f, err)) return false;
                x3::MvJob j2 = job(l.s2, d.sh, d.sh_out, T, FF, D);
                if (!mv_n(d, &j2, 1, err, s2f ? &s2q : nullptr)) return false;
            }
            prof_mark(d, 2);
            const x3::ExpertLayout& lay = nm > 1 ? l.hlay : l.lay;
            if (T == 1 && moe_token_path) {
                x3::MoeArgs ma;
                ma.plan_ptr = d.plan_ptr;
                ma.plan_w = d.rw;
                ma.cpu_part = lead ? resps[slot].part[0] : nullptr;
                ma.cpu_flag = lead ? &resps[slot].cpu[0] : nullptr;
                ma.lay = lay;
                ma.k = l.k_exp;
                ma.n_embd = D;
                ma.n_ff = FF;
                ma.limit = g.lim;
                const bool mx = lay.fmt == gg::kFmtMXFP4;
                if (zc_stage_buf != nullptr && l.zc_tab != nullptr)   // (the store's experts copied to VRAM at the PCIe rate first)
                    zc_stage(d.plan_ptr, d.ridx, l.zc_tab, l.k_exp, zc_stage_buf, zc_stride, l.blob, s);
                // DS4_TLOG2: the expert stage's three host spans (gate/up issue, the CPU-lane wait, down issue)
                static const bool tlog2 = ds4_dbg("DS4_TLOG2");
                static double t_moe_gu = 0, t_moe_wait = 0, t_moe_dn = 0; static long t_moe_n = 0; static bool t_moe_reg = false;
                if (tlog2 && !t_moe_reg) {
                    t_moe_reg = true;
                    std::atexit([] {
                        std::fprintf(stderr, "tlog2: %ld stages | host ms a stage: gate_up %.2f  cpu_wait %.2f  down %.2f\n",
                                     t_moe_n, t_moe_n ? t_moe_gu / (double) t_moe_n : 0.0,
                                     t_moe_n ? t_moe_wait / (double) t_moe_n : 0.0,
                                     t_moe_n ? t_moe_dn / (double) t_moe_n : 0.0);
                    });
                }
                const double m0 = tlog2 ? now_ms() : 0.0;
                if (mx) gg::moe_gate_up(ma, d.x, d.xg, s);
                else x3::moe_gate_up(ma, d.x, d.xg, s);
                const double m1 = tlog2 ? now_ms() : 0.0;
                prof_mark(d, 3);
                // (DS4_HELPER_OVERLAP: the down rows before the wait, the combine after it - the same launches, so the
                //  same bits; a member without the wait runs them back to back as before)
                // (DS4_HELPER_DD: the down rows, the lane's answer, the helpers' seq words, the join on this device, the
                //  combine on the joined part - the combine's launch and inputs as before, so the same bits)
                const bool ddl = lead && mx && dd_at(l.il, T);
                const bool ov = (helper_overlap && mx && lead) || ddl;
                if (ov) gg::moe_down_part(ma, d.xg, s);
                if (lead && !ddl) wait_seq(&resps[slot].seq, sq, s);
                bool lpj = false;   // DS4_LP_JOINCOMB: the join and the combine in one launch
                if (ddl && lp_joincomb) {
                    const gg::DdJoinArgs ja = lp_join_args(l, slot, sq, T);
                    lpj = gg::moe_join_combine(ma, ja, d.sh_out, d.moe_out, s);
                }
                if (ddl && !lpj) {   // (the lane's answer, the helpers' seq words and the join: one launch)
                    DdJoin dj = dd_j[(size_t) l.dev];
                    dj.vmask = ecown ? (const unsigned*) reqs[slot].vmask : nullptr;   // DS4_ECOWN
                    strata_ds4_launch(dd_join_k, dim3((unsigned) ((D / 4 + 255) / 256), 1u), 256, 0, s, dj, (const unsigned*) &resps[slot].seq, sq,
                                      (const float*) &resps[slot].part[0][0], (const int*) resps[slot].cpu, dd_part[(size_t) l.dev], dd_flag[(size_t) l.dev], D,
                                      (const int*) d.ridx, l.il, l.k_exp);
                    ma.cpu_part = dd_part[(size_t) l.dev];
                    ma.cpu_flag = dd_flag[(size_t) l.dev];
                }
                const double m2 = tlog2 ? now_ms() : 0.0;
                prof_mark(d, 4);
                if (lpj) {
                } else if (ov) gg::moe_combine(ma, d.sh_out, d.moe_out, s);
                else if (mx) gg::moe_down(ma, d.xg, d.sh_out, d.moe_out, s);
                else x3::moe_down(ma, d.xg, d.sh_out, d.moe_out, s);
                if (tlog2) { t_moe_gu += m1 - m0; t_moe_wait += m2 - m1; t_moe_dn += now_ms() - m2; ++t_moe_n; }
            } else {   // each distinct expert read once for the window's tokens
                gf::MoeWin mw;
                mw.plan_ptr = d.plan_ptr;
                mw.T = T;
                mw.k = l.k_exp;
                mw.grp_ptr = d.grp_ptr;
                mw.grp_start = d.grp_start;
                mw.grp_ent = d.grp_ent;
                mw.n_groups = d.n_groups;
                gf::moe_win_group(mw, s);
                x3::WinArgs wa;
                wa.grp_ptr = d.grp_ptr;
                wa.grp_start = d.grp_start;
                wa.grp_ent = d.grp_ent;
                wa.n_groups = d.n_groups;
                wa.plan_ptr = d.plan_ptr;
                wa.plan_w = d.rw;
                wa.cpu_part = lead ? &resps[slot].part[0][0] : nullptr;
                wa.cpu_stride = kMaxDim;
                wa.cpu_flag = lead ? resps[slot].cpu : nullptr;
                wa.wait_ptr = lead ? &resps[slot].seq : nullptr;
                wa.wait_val = sq;
                wa.x = d.x;
                wa.x_stride = (size_t) D;
                wa.h = d.xg;
                wa.part = d.ed;
                wa.sh_out = d.sh_out;
                wa.out = d.moe_out;
                wa.out_stride = (size_t) D;
                wa.lay = lay;
                wa.T = T;
                wa.k = l.k_exp;
                wa.n_embd = D;
                wa.n_ff = FF;
                wa.limit = g.lim;
                const bool ddl = lead && lay.fmt == gg::kFmtMXFP4 && dd_at(l.il, T);   // DS4_HELPER_DD (see the T = 1 path)
                wa.no_combine = ddl;
                if (!(lay.fmt == gg::kFmtMXFP4 ? gg::win_experts(wa, s) : x3::win_experts(wa, s))) {
                    err = "exl3 win_experts failed";
                    return false;
                }
                bool lpj = false;   // DS4_LP_JOINCOMB (win_combine's arguments, the join's part)
                if (ddl && lp_joincomb) lpj = gg::win_join_combine(wa, lp_join_args(l, slot, sq, T), s);
                if (ddl && !lpj) {
                    DdJoin dj = dd_j[(size_t) l.dev];
                    dj.vmask = ecown ? (const unsigned*) reqs[slot].vmask : nullptr;   // DS4_ECOWN
                    strata_ds4_launch(dd_join_k, dim3((unsigned) ((D / 4 + 255) / 256), (unsigned) T), 256, 0, s, dj, (const unsigned*) &resps[slot].seq, sq,
                                      (const float*) &resps[slot].part[0][0], (const int*) resps[slot].cpu, dd_part[(size_t) l.dev], dd_flag[(size_t) l.dev], D,
                                      (const int*) d.ridx, l.il, l.k_exp);
                    wa.cpu_part = dd_part[(size_t) l.dev];
                    wa.cpu_stride = (size_t) D;
                    wa.cpu_flag = dd_flag[(size_t) l.dev];
                    gg::win_combine(wa, s);
                }
            }
            if (lead) st.experts += (int64_t) T * l.k_exp;
            // DS4_HELPER_DEFER: the previous trunk layer's deferred helper rows, added once (the lead) before the all-reduce
            if (lead && l.il >= 1 && defer_at(l.il - 1, T)) {
                const unsigned pq = wp.seq[l.il - 1];
                Resp& dp = dresps[pq % kRing];
                wait_seq(&dp.seq, pq, s);
                strata_ds4_launch(defer_add_k, dim3((unsigned) ((D + 255) / 256), (unsigned) T), 256, 0, s, d.moe_out, &dp.part[0][0],
                                  dp.cpu, D);
            }
            if (!l.mtp) ar_then_post(d, d.moe_out, T, ag, mi, nm, d.f_post, d.f_comb, s);   // (DS4_AR_POST)
            else {
            if (nm > 1) allreduce(d.moe_out, T * D, ag, mi, ++d.ar_seq, d.xcnt, s);
            hc_post(d.moe_out, d.h, d.f_post, d.f_comb, D, H, T, d.h2, s);
            }
            std::swap(d.h, d.h2);
            if (!hcf) CK(cudaMemcpyAsync(d.pre, d.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));   // (fused: done)
            prof_mark(d, 5);
            return true;
        }
        if (nm > 1) {
            err = "a tensor-parallel layer on the host-routed path";
            return false;
        }
        // (glog rows are 1024 apart: route reads them so)
        static const bool phases = ds4_dbg("DS4_PHASES");   // debugging: where a decode layer's host time goes
        static double ph[8] = {0}, ph_prev = 0; static long ph_n = 0;
        const double ph0 = phases ? now_ms() : 0.0;
        gemv_f32(l.gate_w, d.x, l.n_exp, D, T, d.glog, 1024, s);
        VlBits vb = {};
        vb.w[0] = l.mtp ? 0u : wp.vl;
        route(d.glog, l.gate_bias, l.n_exp, l.k_exp, T, g.route_scale, d.ridx, d.rw, s, l.gate_bias_vl,
              vb.w[0] != 0 ? &vb : nullptr);
        CK(cudaMemcpyAsync(h_idx, d.ridx, (size_t) T * kPicks * 4, cudaMemcpyDeviceToHost, s));
        CK(cudaMemcpyAsync(h_w, d.rw, (size_t) T * kPicks * 4, cudaMemcpyDeviceToHost, s));
        CK(cudaMemcpyAsync(h_x, d.x, (size_t) T * D * 4, cudaMemcpyDeviceToHost, s));
        CK(cudaEventRecord(d.ev, s));
        // the shared expert while the host looks at the picks
        {
            x3::MvJob js[2] = {job(l.s1, d.x, d.sg, T, D, g.ff), job(l.s3, d.x, d.su, T, D, g.ff)};
            if (!mv_n(d, js, 2, err, sx8)) return false;
        }
#if defined(STRATA_METAL)
        int la_n = 0;   // the next layers' guessed picks (their gate on this FFN input), on the GPU: a gemv and a route a layer
        if (T == 1 && la_enabled()) {
            for (int a = 1; a <= la_depth(); ++a) {
                const int il = l.il + a;
                if (il >= g.nl) break;
                const Layer& nx = L[(size_t) il];
                if (nx.nm != 1 || nx.lay.fmt != gg::kFmtMXFP4 || nx.gate_bias == nullptr || nx.gate_w == nullptr) break;
                gemv_f32(nx.gate_w, d.x, nx.n_exp, D, 1, d.glog_a + (size_t) (a - 1) * kWin * 1024, 1024, s);
                route(d.glog_a + (size_t) (a - 1) * kWin * 1024, nx.gate_bias, nx.n_exp, nx.k_exp, 1, g.route_scale, d.ridx_a + (a - 1) * kPicks,
                      d.rw_a + (a - 1) * kPicks, s, nullptr, nullptr);
                CK(cudaMemcpyAsync(h_idx_a + (a - 1) * kPicks, d.ridx_a + (a - 1) * kPicks, (size_t) kPicks * 4, cudaMemcpyDeviceToHost, s));
                la_n = a;
            }
            if (la_n > 0) CK(cudaEventRecord(d.ev2, s));
        }
#endif
        if (ds4_dbg("DS4_DBG_MOE")) { dbg_nf("x", l.il, d.x, (size_t) T * D); dbg_nf("sg", l.il, d.sg, (size_t) T * g.ff); dbg_nf("su", l.il, d.su, (size_t) T * g.ff);
            std::fprintf(stderr, "DBG s1 fmt=%d K=%d k=%d n=%d ld=%d raw=%p\n", l.s1.fmt, l.s1.K, l.s1.k, l.s1.n, l.s1.ld, (void*) l.s1.raw); }
        gg::PreQ8 s2q;   // (DS4_DECODE_TRIM bit 1: the swiglu rounds s2's int8 input where it makes it)
        bool s2f = false;
        if (!shared_swiglu(d, l, T, g.ff, s2q, s2f, err)) return false;
        if (ds4_dbg("DS4_DBG_MOE")) dbg_nf("sh", l.il, d.sh, (size_t) T * g.ff);
        {
            x3::MvJob j2 = job(l.s2, d.sh, d.sh_out, T, g.ff, D);
            if (!mv_n(d, &j2, 1, err, s2f ? &s2q : nullptr)) return false;
        }
        const double tw = now_ms();
        CK(cudaEventSynchronize(d.ev));
        st.gpu_wait_ms += now_ms() - tw;
        const double ph2 = phases ? now_ms() : 0.0;
        dump_sub(d, "glog", l.il, p0, T, d.glog, (size_t) T * 1024 * 4);
        dump_sub_host("ridx", l.il, p0, T, h_idx, (size_t) T * kPicks * 4);
        dump_sub_host("rw", l.il, p0, T, h_w, (size_t) T * kPicks * 4);
        dump_sub(d, "sh_out", l.il, p0, T, d.sh_out, (size_t) T * D * 4);
        // the picks by expert: the VRAM ones' rows (gathered inputs, one GEMV per matrix for all their tokens), the
        // CPU lane's entries
        Combine cm;
        Gather ga;
        uint32_t* pr = prof.data() + (size_t) l.il * g.n_exp;
        int vex[kWin * kPicks], vrow0[kWin * kPicks], vn[kWin * kPicks];
        int nvex = 0, nrows = 0;
        std::vector<Ent> ents;
        std::vector<std::pair<int, float>> cpu_rows;   // slot -> (token, weight)
        std::vector<std::vector<std::pair<int, int>>> per((size_t) l.n_exp);   // expert -> (token, pick)
        for (int t = 0; t < T; ++t) {
            cm.n[t] = 0;
            cm.cpu[t] = 0;
            for (int i = 0; i < l.k_exp; ++i) {
                const int e = h_idx[t * kPicks + i];
                if (e < 0 || e >= l.n_exp) {
                    err = "router picked expert " + std::to_string(e) + " (layer " + std::to_string(l.il) + ", token " + std::to_string(t) + ", pick " + std::to_string(i) + ", of " + std::to_string(l.k_exp) + ")";
                    return false;
                }
                // (upstream fix C1, upstream f6eed469: a non-finite gate input - the router then gave a valid stand-in pick
                //  but a NaN weight; said here, where the picks are on the host anyway, instead of answering nonsense)
                if (!std::isfinite(h_w[t * kPicks + i])) {
                    err = "the router's weight is not finite (layer " + std::to_string(l.il) + ", token " + std::to_string(t) + ", pick " + std::to_string(i) + "): the gate's input went NaN or infinite";
                    return false;
                }
                ++pr[e];
                if (l.mtp && !dpick.empty()) ++dpick[(size_t) (l.il - g.nl) * g.d_n_exp + e];
                l.heat[(size_t) e] += 1.0f;
                if (l.slot[(size_t) e] < 0) l.cpu_hits.push_back(e);
                per[(size_t) e].push_back({t, i});
            }
        }
        int nslots = 0;
        for (int e = 0; e < l.n_exp; ++e) {
            const auto& pe = per[(size_t) e];
            if (pe.empty()) continue;
#if defined(STRATA_METAL)
            const bool on_gpu = l.slot[(size_t) e] >= 0 || (T == 1 && zc_try(l, e));
#else
            const bool on_gpu = l.slot[(size_t) e] >= 0;
#endif
            if (on_gpu) {
                vex[nvex] = e;
                vrow0[nvex] = nrows;
                vn[nvex] = (int) pe.size();
                for (const auto& tp : pe) {
                    ga.src[nrows] = tp.first;
                    const int t = tp.first;
                    cm.row[t][cm.n[t]] = nrows;
                    cm.w[t][cm.n[t]] = h_w[t * kPicks + tp.second];
                    ++cm.n[t];
                    ++nrows;
                }
                ++nvex;
            } else {
                for (size_t a = 0; a < pe.size(); a += (size_t) ent_cap(l)) {
                    Ent en;
                    en.e = e;
                    en.slot0 = nslots;
                    en.n = (int) std::min<size_t>((size_t) ent_cap(l), pe.size() - a);
                    for (int i = 0; i < en.n; ++i) {
                        en.tok[i] = pe[a + (size_t) i].first;
                        cpu_rows.push_back({pe[a + (size_t) i].first, h_w[pe[a + (size_t) i].first * kPicks + pe[a + (size_t) i].second]});
                        cm.cpu[en.tok[i]] = 1;
                    }
                    nslots += en.n;
                    ents.push_back(en);
                }
            }
        }
        st.experts += (int64_t) T * l.k_exp;
        st.cpu_experts += nslots;
#if defined(STRATA_METAL)
        if (T == 1) lookahead_prefetch(l, d.ev2, la_n, ents);
#endif
        if (nrows > 0) {
            gather_rows(d.x, ga, nrows, D, d.xe, s);
            dump_sub(d, "xe", l.il, p0, nrows, d.xe, (size_t) nrows * D * 4);
            if (dump_s != nullptr) { std::vector<int> vmap; for (int i = 0; i < nvex; ++i) { vmap.push_back(vex[i]); vmap.push_back(vrow0[i]); vmap.push_back(vn[i]); }
              dump_sub_host("vmap", l.il, p0, nvex, vmap.data(), vmap.size() * 4); }
            x3::MvJob j[2 * kWin * kPicks];
            int nj = 0;
            for (int i = 0; i < nvex; ++i) {
                const auto& vm = l.vm[(size_t) vex[i]];
                j[nj++] = job(vm[0], d.xe + (size_t) vrow0[i] * D, d.xg + (size_t) vrow0[i] * g.ff, vn[i], D, g.ff);
                j[nj++] = job(vm[1], d.xe + (size_t) vrow0[i] * D, d.xu + (size_t) vrow0[i] * g.ff, vn[i], D, g.ff);
            }
            if (!mv_n(d, j, nj, err)) return false;
            dump_sub(d, "xg", l.il, p0, nrows, d.xg, (size_t) nrows * g.ff * 4);
            dump_sub(d, "xu", l.il, p0, nrows, d.xu, (size_t) nrows * g.ff * 4);
            swiglu(d.xg, d.xu, nrows * g.ff, g.lim, d.xhh, s);
            dump_sub(d, "xhh", l.il, p0, nrows, d.xhh, (size_t) nrows * g.ff * 4);
            nj = 0;
            for (int i = 0; i < nvex; ++i)
                j[nj++] = job(l.vm[(size_t) vex[i]][2], d.xhh + (size_t) vrow0[i] * g.ff, d.ed + (size_t) vrow0[i] * D,
                              vn[i], g.ff, D);
            if (!mv_n(d, j, nj, err)) return false;
            dump_sub(d, "ed", l.il, p0, nrows, d.ed, (size_t) nrows * D * 4);
        }
        const double ph3 = phases ? now_ms() : 0.0;
        if (!ents.empty()) {
            const double tc = now_ms();
#if defined(STRATA_METAL)
            ds4_metal_kick();   // (the VRAM experts run on the GPU while the CPU lane works)
            ds4_busy_begin();   // (and the GPU is kept out of its idle clocks until the lane is done)
#endif
            static const bool skip_cpu = ds4_dbg("DS4_SKIP_CPU");   // (timing only: the CPU lane's experts left out)
            if (!skip_cpu) cpu_experts(l, h_x, ents);
            else if (ds4_dbg("DS4_FAKE_CPU_US")) std::this_thread::sleep_for(std::chrono::microseconds(std::atoi(std::getenv("DS4_FAKE_CPU_US"))));   // (timing only)
#if defined(STRATA_METAL)
            ds4_busy_end();
#endif
            std::fill(h_part, h_part + (size_t) T * D, 0.0f);
            for (int sl = 0; sl < nslots; ++sl) {
                float* o = h_part + (size_t) cpu_rows[(size_t) sl].first * D;
                const float wv = cpu_rows[(size_t) sl].second;
                const float* y = c_yd.data() + (size_t) sl * D;
                for (int e = 0; e < D; ++e) o[e] += wv * y[e];
            }
            if (ds4_dbg("DS4_CPU_LOG")) { static double ms = 0; static long calls = 0, exps = 0; static bool reg = false;
              ms += now_ms() - tc; ++calls; exps += (long) ents.size();
              if (ds4_dbg("DS4_CPU_LOG") && !reg) { reg = true; std::atexit([] { std::fprintf(stderr, "cpu lane calls: %ld, experts %ld, %.1f ms (%.3f ms a call, %.3f ms an expert)%c", calls, exps, ms, ms / (double) calls, ms / (double) exps, 10); }); }
              (void) 0; (void) ms; }
            st.cpu_ms += now_ms() - tc;
            dump_sub_host("cpu_part", l.il, p0, T, h_part, (size_t) T * D * 4);
            CK(cudaMemcpyAsync(d.cpu_part, h_part, (size_t) T * D * 4, cudaMemcpyHostToDevice, s));
        }
        combine(d.ed, ents.empty() ? nullptr : d.cpu_part, d.sh_out, cm, T, D, d.moe_out, s);
        dump_sub(d, "moe_out", l.il, p0, T, d.moe_out, (size_t) T * D * 4);
        if (ds4_dbg("DS4_DBG_MOE")) {
            float hp = 0.0f;
            for (size_t i = 0; i < (size_t) T * D; ++i) hp = std::max(hp, std::fabs(h_part[i]));
            std::fprintf(stderr, "DBG moe il=%d T=%d vram_rows=%d cpu_slots=%d max|h_part|=%.4g", l.il, T, nrows, nslots, (double) hp);
            dbg_nf("moe_out", l.il, d.moe_out, (size_t) T * D);
            dbg_nf("sh_out", l.il, d.sh_out, (size_t) T * D);
        }
        hc_post(d.moe_out, d.h, d.f_post, d.f_comb, D, H, T, d.h2, s);
        std::swap(d.h, d.h2);
        dump_sub(d, "h_out", l.il, p0, T, d.h, (size_t) T * H * D * 4);
        if (dump_l != nullptr && mi == 0) dump_layer(d, d.h, l.il, p0, T);   // (post-layer residual, as the chunk path writes it)
        if (!hcf) CK(cudaMemcpyAsync(d.pre, d.f_pre, (size_t) T * 8 * 4, cudaMemcpyDeviceToDevice, s));   // (fused: done)
        if (phases && T == 1) {
            const double ph4 = now_ms();
            ph[0] += ph2 - ph0; ph[1] += ph3 - ph2; ph[2] += ph4 - ph3; if (ph_prev > 0 && ph0 - ph_prev < 5.0) ph[3] += ph0 - ph_prev; ph_prev = ph4; ++ph_n;
            static bool reg = false;
            if (!reg) { reg = true; std::atexit([] { std::fprintf(stderr, "phases per layer call (%ld): route enqueue + shared expert + wait %.3f ms, routing analysis + GPU experts enqueue %.3f ms, CPU lane + combine + hc_post %.3f ms, attention enqueue %.3f ms%s", ph_n, ph[0] / ph_n, ph[1] / ph_n, ph[2] / ph_n, ph[3] / ph_n, "\n"); }); }
        }
        // (h_part / h_x are written again only after the next layer's route has synchronized, which follows these)
        return true;
    }

    // ---- DS4_BATCH_DECODE=N (docs/dsv41/cards/SV-03.md): batched decode over N sequence banks, default off.
    // A bank is a whole sequence state beside the conversation in the model: its position, tokens and Engram ids, every
    // window ring and compressor partial group (each member's), each KV source's compressed KV and index keys (each
    // device's), its checkpoints and its indexer plan state.  A bank's prompt is read by swapping its pointers into
    // the model (bank_swap, its own inverse) and running the normal prompt path; a batch step (forward_batch) is one
    // window of B rows, row b bank b's next token: the row-wise work (mHC, the projections, the MoE, the all-reduces,
    // the head) runs once over the B rows - the dense weights and the experts read once a step - and the work that
    // reads or writes a sequence's state (the window ring, the compressor, the indexer, the sparse attention, RoPE at
    // the row's own position) runs per row against its bank (attn_batch).  Greedy only, no drafter, no pictures,
    // one tensor-parallel group holding every trunk layer (tp3 on 3 cards).  Each row's arithmetic is the window path's
    // for that row alone (the token and window MoE paths give the same bits: DS4_MOE_TOKEN), so a sequence's greedy
    // tokens are those of its own windows of one on the same placement - the GPU plan checks it per sequence.
    struct Bank {
        int64_t pos = 0;
        std::vector<int32_t> toks, ctoks;
        Check ck[kChecks];
        bool slot_held = false;
        int cur_topk[kWin] = {}, cur_cand[kWin] = {};
        std::vector<std::vector<uint8_t*>> win;            // [layer (L's order, the drafter's blocks too)][member]
        std::vector<std::vector<float*>> c_kv, c_score;    // (null where the layer has no partial group)
        std::vector<std::vector<uint8_t*>> ckv, ik;        // [source][device] (null where no layer on it reads it)
        // DS4_BATCH_DSPARK: the compressor's partial group as it was before a verify window (kv then score; where
        // the member layer has a c_snap: a trunk kv source of ratio > 1), for the rollback of rejected drafts
        std::vector<std::vector<float*>> c_snap;
    };
    std::vector<Bank> banks;
    int bt_n = 0;                     // banks (0: DS4_BATCH_DECODE off)
    bool bt_on = false;               // the window running is a batch window (layer() takes attn_batch)
    int64_t bt_pos[kWin] = {};        // row b's position (its bank's, before the step)
    int bt_bank[kWin] = {};           // row b's bank
    int* d_bt = nullptr;              // (head device) the rows' greedy picks
    int h_bt[kWin] = {};
    // DS4_BATCH_DSPARK (build 9: on by default with DS4_BATCH_DECODE and the drafter loaded; 0 = off): DSpark drafts inside batch steps - each sequence drafts from its own bank,
    // and one batch window verifies every sequence's [y, drafts] rows (a sequence's rows contiguous, at consecutive
    // positions); each then keeps its own accepted rows (bank_rollback) and seeds its drafter with them
    bool bt_spec_ok = false;          // the flag, a loaded drafter and the banks' snapshots
    int bt_spec_max = 2;              // DS4_BATCH_DSPARK_MAX: the scheduler drafts while at most this many sequences are active
    bool bt_spec = false;             // the window running is a batch verify window (ring backups, compressor snapshots, taps)
    bool bt_first[kWin] = {};         // row r is its bank's first row of the window
    // DS4_MULTI_ATTN (docs/dsv41/cards/FG-05.md, docs/dsv41/cards/FG-05.md; Project Maya #639): a batch window's attention
    // for all its sequences' rows in one launch a member layer (attn_batch_multi) instead of one a sequence.  build 10: on
    // by default whenever DS4_BATCH_DECODE allocates the banks (unset or 1).  0: off - the buffers are still allocated
    // (the same VRAM, so the same expert placement as on) and the per-run path runs: the A/B control.  Without
    // DS4_BATCH_DECODE nothing is allocated and nothing changes.
    bool mattn_buf = false, mattn_on = false;
    MaPlan bt_mplan;                  // (forward_batch, before the layers) the window's runs in the shared buffer
    bool bt_mplan_ok = false;
    static_assert(kMaRows == kWin, "DS4_MULTI_ATTN: a batch window's rows (kWin) in one plan");
    std::atomic<long long> mattn_shared{0}, mattn_per_run{0};   // (the device threads' count; into st after the window)

    // load(), before place_experts: the banks' VRAM comes out of what the experts would have had
    bool bank_alloc(std::string& err) {
        const char* v = std::getenv("DS4_BATCH_DECODE");
        const int want = v != nullptr ? std::atoi(v) : 0;
        if (want <= 0) return true;
        const int n = std::min(want, kWin);
        bool one = par && !L.empty();
        for (int il = 0; il < g.nl && one; ++il) one = L[(size_t) il].grp == L[0].grp;
        for (const Src& s : srcs) one = one && !s.remote;
        if (!one) {   // (recommend, never force: the engine runs as without it)
            std::fprintf(stderr, "ds4: DS4_BATCH_DECODE=%d needs threads mode and one tensor-parallel group holding every "
                                 "trunk layer (--tp = the GPU count, e.g. --gpus 0,1,2 --tp 3): batched decode off\n", want);
            return true;
        }
        size_t bytes = 0;
        banks.resize((size_t) n);
        for (Bank& k : banks) {
            k.toks.reserve((size_t) o.max_context);
            k.ctoks.reserve((size_t) o.max_context);
            k.win.assign(L.size(), {});
            k.c_kv.assign(L.size(), {});
            k.c_score.assign(L.size(), {});
            for (size_t i = 0; i < L.size(); ++i) {
                const int nm = L[i].nm;
                k.win[i].assign((size_t) nm, nullptr);
                k.c_kv[i].assign((size_t) nm, nullptr);
                k.c_score[i].assign((size_t) nm, nullptr);
                for (int m = 0; m < nm; ++m) {
                    const Layer& l = member(L[i], m);
                    Dev& d = devs[(size_t) l.dev];
                    if (l.win != nullptr && !dalloc(d, k.win[i][(size_t) m], (size_t) g.win * win_rb(), err, &d.caches))
                        return false;
                    bytes += (size_t) g.win * win_rb();
                    if (l.c_kv != nullptr) {
                        if (!dalloc(d, k.c_kv[i][(size_t) m], (size_t) l.ratio * g.hd, err, &d.caches) ||
                            !dalloc(d, k.c_score[i][(size_t) m], (size_t) l.ratio * g.hd, err, &d.caches))
                            return false;
                        bytes += 2 * (size_t) l.ratio * g.hd * 4;
                    }
                }
            }
            k.ckv.assign(srcs.size(), std::vector<uint8_t*>(devs.size(), nullptr));
            k.ik.assign(srcs.size(), std::vector<uint8_t*>(devs.size(), nullptr));
            for (size_t si = 0; si < srcs.size(); ++si)
                for (size_t di = 0; di < devs.size(); ++di) {
                    const Src& s = srcs[si];
                    Dev& d = devs[di];
                    if (s.ckv[di] != nullptr && !dalloc(d, k.ckv[si][di], (size_t) s.cap * ckv_rb(), err, &d.caches))
                        return false;
                    if (s.ik[di] != nullptr && !dalloc(d, k.ik[si][di], (size_t) s.cap * ik_rb(), err, &d.caches))
                        return false;
                    bytes += (s.ckv[di] != nullptr ? (size_t) s.cap * ckv_rb() : 0) +
                             (s.ik[di] != nullptr ? (size_t) s.cap * ik_rb() : 0);
                }
        }
        if (!dalloc(devs[(size_t) head_dev], d_bt, (size_t) kWin, err)) return false;
        bt_n = n;
        // DS4_MULTI_ATTN (build 10: on by default with the banks; =0 off): the shared buffers on every device holding a
        // member's window ring, out of the expert room like the banks - allocated with =0 too, so 0 and 1 place the
        // experts the same way (the A/B control)
        {
            const char* ma_env = std::getenv("DS4_MULTI_ATTN");
            const bool ma_set = ma_env != nullptr && *ma_env != '\0';
            if (ma_set && std::strcmp(ma_env, "0") != 0 && std::strcmp(ma_env, "1") != 0)
                std::fprintf(stderr, "ds4: DS4_MULTI_ATTN=%s: 1 or 0 - on (the default)\n", ma_env);
            const char* ma = ma_set && std::strcmp(ma_env, "0") == 0 ? "0" : ma_set && std::strcmp(ma_env, "1") == 0 ? "1"
                                                                                                                   : "1 (the default)";
            {
#if defined(STRATA_METAL)
                std::fprintf(stderr, "ds4: DS4_MULTI_ATTN=%s: not on Metal builds - the per-run batch attention\n", ma);
#else
                std::vector<char> want_dev(devs.size(), 0);
                for (size_t i = 0; i < L.size(); ++i)
                    for (int m = 0; m < L[i].nm; ++m) {
                        const Layer& l = member(L[i], m);
                        if (l.win != nullptr) want_dev[(size_t) l.dev] = 1;
                    }
                size_t mb = 0;
                for (size_t di = 0; di < devs.size(); ++di) {
                    if (!want_dev[di]) continue;
                    Dev& d = devs[di];
                    const size_t er = (size_t) ma_rows_max(g.win) * g.hd, sr = (size_t) kWin * topk_stride() * g.hd;
                    if (!dalloc(d, d.mext, er, err, &d.caches) || !dalloc(d, d.mscr.rows, sr, err, &d.caches)) return false;
                    d.mscr.max_t = kWin;
                    d.mscr.cap = (int) topk_stride();
                    mb += (er + sr) * 2;
                }
                mattn_buf = true;
                mattn_on = ma[0] == '1';   // ("1 (the default)" too)
                std::fprintf(stderr, "ds4: DS4_MULTI_ATTN=%s: %s; %.1f MB of shared window buffers and selections, before the "
                                     "experts' placement\n", ma,
                             mattn_on ? "a batch window's attention for all its sequences in one launch a layer"
                                      : "off - the buffers only, the per-run batch attention (the A/B control)",
                             (double) mb / 1e6);
#endif
            }
        }
        // build 9: batch drafts are on by default once the batch path is (DS4_BATCH_DECODE, above) and the drafter is
        // loaded; DS4_BATCH_DSPARK=0 turns them off
        const char* sv_env = std::getenv("DS4_BATCH_DSPARK");
        const bool sv_set = sv_env != nullptr && *sv_env != '\0';
        const char* sv = sv_set ? sv_env : "1 (the default)";
        if (!sv_set || std::atoi(sv_env) != 0) {
            if (g.n_mtp == 0) {
                if (sv_set)
                    std::fprintf(stderr, "ds4: DS4_BATCH_DSPARK=%s needs the DSpark drafter loaded (--dspark on / off): batch "
                                         "steps do not draft\n", sv);
            } else {
                size_t sb = 0;
                for (Bank& k : banks) {
                    k.c_snap.assign(L.size(), {});
                    for (size_t i = 0; i < L.size(); ++i) {
                        k.c_snap[i].assign((size_t) L[i].nm, nullptr);
                        for (int m = 0; m < L[i].nm; ++m) {
                            const Layer& l = member(L[i], m);
                            if (l.c_snap == nullptr) continue;
                            Dev& d = devs[(size_t) l.dev];
                            if (!dalloc(d, k.c_snap[i][(size_t) m], (size_t) 2 * l.ratio * g.hd, err, &d.caches)) return false;
                            sb += 2 * (size_t) l.ratio * g.hd * 4;
                        }
                    }
                }
                bt_spec_ok = true;
                if (const char* mv_ = std::getenv("DS4_BATCH_DSPARK_MAX"); mv_ != nullptr && *mv_ != '\0')
                    bt_spec_max = std::max(0, std::min(kWin, std::atoi(mv_)));
                std::fprintf(stderr, "ds4: batched decode drafts (DS4_BATCH_DSPARK=%s): each sequence its own drafts, one batch "
                                     "window verifies them all; %.1f MB of compressor snapshots; drafted steps while at most %d "
                                     "sequences are active (DS4_BATCH_DSPARK_MAX), plain batch steps above\n", sv,
                             (double) sb / 1e6, bt_spec_max);
            }
        }
        std::fprintf(stderr, "ds4: batched decode: %d sequence banks (DS4_BATCH_DECODE=%d), %.1f MB of VRAM in all at context "
                             "%lld, before the experts' placement; greedy, no drafter in a batch step\n",
                     n, want, (double) bytes / 1e6, (long long) o.max_context);
        return true;
    }

    // bank b's state into the model and the model's into bank b (its own inverse): the prompt path then reads into
    // the bank; between windows only (every device's queue drained first)
    void bank_swap(int b) {
        for (Dev& d : devs) {
            cudaSetDevice(d.id);
            cudaStreamSynchronize(d.st);
        }
        Bank& k = banks[(size_t) b];
        std::swap(pos, k.pos);
        toks.swap(k.toks);
        ctoks.swap(k.ctoks);
        for (int i = 0; i < kChecks; ++i) std::swap(ck[i], k.ck[i]);
        std::swap(slot_held, k.slot_held);
        std::swap_ranges(cur_topk_n, cur_topk_n + kWin, k.cur_topk);
        std::swap_ranges(cur_cand_n, cur_cand_n + kWin, k.cur_cand);
        for (size_t i = 0; i < L.size(); ++i)
            for (int m = 0; m < L[i].nm; ++m) {
                Layer& l = member(L[i], m);
                std::swap(l.win, k.win[i][(size_t) m]);
                std::swap(l.c_kv, k.c_kv[i][(size_t) m]);
                std::swap(l.c_score, k.c_score[i][(size_t) m]);
            }
        for (size_t si = 0; si < srcs.size(); ++si)
            for (size_t di = 0; di < devs.size(); ++di) {
                std::swap(srcs[si].ckv[di], k.ckv[si][di]);
                std::swap(srcs[si].ik[di], k.ik[si][di]);
            }
    }

    // (attn_batch) a run's selection work - the compressor, the indexer and the compressed KV rows - for bank bk's
    // n rows r0 .. at positions p0 ..: nsel[t] (t < n) its rows' selected compressed rows, ckv its compressed cache
    // (null: a layer without one).  layer()'s calls for a window of n at p0, moved out of attn_batch unchanged (
    // DS4_MULTI_ATTN: both of attn_batch's paths run it a run at a time)
    bool bt_run_sel(Layer& l, Dev& d, Bank& bk, size_t li, int mi, int r0, int n, int64_t p0, const WinPlan& wp,
                    int* nsel, const void*& ckv, std::string& err) {
        cudaStream_t s = d.st;
        const int D = g.dim, HD = g.hd;
        const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
        const int ts = (int) topk_stride(), cs = (int) cand_stride();
        for (int t = 0; t < n; ++t) nsel[t] = 0;
        ckv = nullptr;
        if (l.ratio > 0) {
            const int R = l.ratio;
            const int64_t g_first = p0 / R;
            const int ng = (int) std::max<int64_t>(0, (p0 + n) / R - g_first);
            if (l.kv_src) {
                if (R == 1) {
                    Finish fc;
                    fc.w = l.c_norm;
                    fc.eps = g.eps;
                    finish(d.ckr + (size_t) r0 * HD, n, HD, HD, fc, s);
                    if (trims_copy(l)) {   // (DS4_DECODE_TRIM bit 4: one kernel, no runtime copy - build 10: fuse's, in bt_run_sel)
                        CopyRegions cr;
                        cr.dst[0] = d.latent;
                        cr.src[0] = d.ckr + (size_t) r0 * HD;
                        cr.bytes[0] = (size_t) n * HD * 4;
                        cr.n = 1;
                        if (!copy_regions(cr, s)) {
                            err = "DS4_DECODE_TRIM: the latent copy refused";
                            return false;
                        }
                    } else
                    CK(cudaMemcpyAsync(d.latent, d.ckr + (size_t) r0 * HD, (size_t) n * HD * 4, cudaMemcpyDeviceToDevice, s));
                } else {
                    if (bt_spec && l.c_snap != nullptr) {   // the bank's partial group before the run; the run's raw rows
                        float* snap = bk.c_snap[li][(size_t) mi];
                        const size_t ns = (size_t) R * HD * 4, nr = (size_t) n * HD * 4;
                        if (snap != nullptr) {
                            CK(cudaMemcpyAsync(snap, bk.c_kv[li][(size_t) mi], ns, cudaMemcpyDeviceToDevice, s));
                            CK(cudaMemcpyAsync(snap + (size_t) R * HD, bk.c_score[li][(size_t) mi], ns, cudaMemcpyDeviceToDevice, s));
                        }
                        CK(cudaMemcpyAsync(l.c_rows + (size_t) r0 * HD, d.ckr + (size_t) r0 * HD, nr, cudaMemcpyDeviceToDevice, s));
                        CK(cudaMemcpyAsync(l.c_rows + (size_t) (kWin + r0) * HD, d.cgr + (size_t) r0 * HD, nr,
                                           cudaMemcpyDeviceToDevice, s));
                    }
                    compress_win(d.ckr + (size_t) r0 * HD, d.cgr + (size_t) r0 * HD, bk.c_kv[li][(size_t) mi],
                                 bk.c_score[li][(size_t) mi], R, (int) p0, n, HD, l.c_norm, g.eps, d.latent, s);
                }
            }
            Rows lim;
            int clen_max = 0;
            for (int t = 0; t < n; ++t) {
                lim.n[t] = (int) ((p0 + t + 1) / R);
                lim.k[t] = std::min(g.ix_topk, lim.n[t]);
                clen_max = std::max(clen_max, lim.n[t]);
            }
            if (l.ix_src) {
                uint8_t* ik = bk.ik[(size_t) l.ik_src][(size_t) l.dev];
                if (l.owns_k && ng > 0) {
                    if (!mv(d, {job(l.i_wk, d.latent, d.ikr, ng, HD, g.ix_hd)}, err)) return false;
                    Finish fi;
                    fi.w = l.ik_norm;
                    fi.eps = g.eps;
                    fi.rd = g.rd;
                    fi.pos = (int) (g_first * R);
                    fi.pos_step = R;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    fi.pdst = ik + (size_t) g_first * ik_rb();
                    fi.pdst_stride = (long long) ik_rb();
                    finish(d.ikr, ng, g.ix_hd, g.ix_hd, fi, s);
                }
                if (clen_max > 0) {
                    if (!mv(d, {job(l.i_wq_b, d.qr + (size_t) r0 * g.q_lora, d.iq, n, g.q_lora,
                                    (size_t) g.ix_heads * g.ix_hd)}, err))
                        return false;
                    Finish fi;
                    fi.rd = g.rd;
                    fi.pos = (int) p0;
                    fi.vpp = g.ix_heads;
                    fi.freqs = freqs;
                    fi.quant = 3;
                    finish(d.iq, n * g.ix_heads, g.ix_hd, g.ix_hd, fi, s);
                    gemv_f16_rows(l.i_wproj, d.x + (size_t) r0 * D, (size_t) D, g.ix_heads, D, n,
                                  1.0f / std::sqrt((float) g.ix_hd) / std::sqrt((float) g.ix_heads), d.iw, 64, s);
                    const long long ss = (long long) o.max_context + 64;
                    bool restrict_ = false;
                    for (int t = 0; t < n; ++t)
                        restrict_ = restrict_ || (lim.n[t] + g.cand_blk - 1) / g.cand_blk > g.cand_topk;
                    int* cand_b = d.cand + (size_t) r0 * cs;
                    int* topk_b = d.topk + (size_t) r0 * ts;
                    if (l.uses_cand && restrict_) {
                        Rows cl;
                        int nmax = 0;
                        for (int t = 0; t < n; ++t) {
                            cl.n[t] = lim.n[t];
                            cl.k[t] = wp.cand[l.il][r0 + t];
                            nmax = std::max(nmax, wp.cand[l.il][r0 + t] * g.cand_blk);
                        }
                        index_score(d.iq, d.iw, ik, g.ix_heads, g.ix_hd, n, nmax, cand_b, cs, g.cand_blk, cl,
                                    d.scores, ss, s);
                        Rows tr;
                        for (int t = 0; t < n; ++t) {
                            tr.n[t] = wp.cand[l.il][r0 + t] * g.cand_blk;
                            tr.k[t] = lim.k[t];
                        }
                        tmb_bt_note(d, tr, n);
                        ::strata::ds4::topk(d.scores, ss, n, tr, cand_b, cs, g.cand_blk, topk_b, ts, s, tmb_bt(d), kWin,
                                            topk_mb_min);   // (DS4_TOPK_MB_BATCH: null = the old kernel)
                    } else {
                        index_score(d.iq, d.iw, ik, g.ix_heads, g.ix_hd, n, clen_max, nullptr, 0, 1, lim, d.scores,
                                    ss, s);
                        if (l.cand_src) {
                            Rows cr;
                            for (int t = 0; t < n; ++t) {
                                cr.n[t] = lim.n[t];
                                cr.k[t] = g.cand_topk;
                            }
                            ::strata::ds4::cand_blocks(d.scores, ss, n, cr, g.cand_blk, d.bm, (long long) bm_stride(), cand_b, cs,
                                                       s, tmb_bt(d), kWin, topk_mb_min);   // (DS4_TOPK_MB_BATCH)
                        }
                        tmb_bt_note(d, lim, n);
                        ::strata::ds4::topk(d.scores, ss, n, lim, nullptr, 0, 1, topk_b, ts, s, tmb_bt(d), kWin,
                                            topk_mb_min);   // (DS4_TOPK_MB_BATCH: null = the old kernel)
                    }
                }
            }
            uint8_t* ckv_b = bk.ckv[(size_t) l.src][(size_t) l.dev];
            if (l.kv_src && ng > 0) {
                Finish fc;
                fc.rd = g.rd;
                fc.pos = (int) (g_first * R);
                fc.pos_step = R;
                fc.freqs = freqs;
                fc.quant = 2;
                fc.pdst = ckv_b + (size_t) g_first * ckv_rb();
                fc.pdst_stride = (long long) ckv_rb();
                finish(d.latent, ng, HD, HD, fc, s);
            }
            for (int t = 0; t < n; ++t) nsel[t] = lim.n[t] > 0 ? wp.topk[l.il][r0 + t] : 0;
            ckv = ckv_b;
        }
        return true;
    }

    // DS4_MULTI_ATTN=1 (docs/dsv41/cards/FG-05.md; Project Maya #639's attn_multi, MIT - third_party/project-maya): the
    // per-run work of attn_batch for all T rows, in one launch a step where the rows read only their own state - the
    // runs' window buffers side by side in d.mext (bt_mplan's blocks), the rings into them, the KV rows' finish and the
    // rings' new rows (and their backups); then each run's selection (bt_run_sel, a run at a time as before); then one
    // sparse attention over all the rows and one inverse RoPE.  Each row's kernels and values are the per-run path's;
    // only which launch computes it, and where in VRAM its window rows sit, differ
    // (the runs' rings, their blocks of d.mext and their backups, for member mi of trunk layer li - attn_batch_multi's, and
    // DS4_BT_FUSE's merged launches')
    void bt_runs(const Layer& l, size_t li, int mi, RingRuns& rr) {
        const MaPlan& mp = bt_mplan;
        rr.runs = mp.nrun;
        for (int k = 0; k < mp.nrun; ++k) {
            const MaRun& u = mp.run[k];
            rr.ring[k] = banks[(size_t) u.seq].win[li][(size_t) mi];
            rr.bak[k] = bt_spec && l.ring_bak != nullptr ? l.ring_bak + (size_t) u.r0 * win_rb() : nullptr;
            rr.p0[k] = (long long) u.p0;
            rr.e0[k] = u.e0;
            rr.T[k] = u.n;
        }
    }
    // DS4_BT_FUSE: what attn_batch's merged launches did already, for attn_batch_multi (null there: the unfused path)
    struct BtPre {
        bool kv = false;           // the rings into d.mext, the KV rows' finish, the new rows into the rings (and backups)
        bool sel = false;          // the rows' unpack (sel d.topk, the scratch d.mscr) with exactly nsel / ck
        int nsel[kWin] = {};
        AttnCkv ck;
        int8_t* oq = nullptr;      // non-null: the o finish to round wo_a's int8 input too (T rows a group, groups apart)
        float* od = nullptr;
        int per = 0;               // (wo_a's group: its input values a row)
        bool oq_done = false;      // (attn_batch_multi: the o finish made them)
    };
    // (DS4_BT_FUSE with DS4_ATTN_MERGE=3) whether the selections and compressed rows layer l's sparse attention reads in
    // this batch window are final before bt_run_sel - no indexer of its own (ix_src: bt_run_sel makes the top-k), no run
    // completing a compressed row of its own (kv_src with a group done: bt_run_sel writes it) - and then each row's nsel and
    // cache as bt_run_sel gives them (attn_batch_multi compares)
    bool bt_sel_final(const Layer& l, const WinPlan& wp, BtPre& bp) {
        if (l.ix_src) return false;
        const MaPlan& mp = bt_mplan;
        for (int k = 0; k < mp.nrun; ++k) {
            const MaRun& u = mp.run[k];
            const void* c = nullptr;
            int R = 0;
            if (l.ratio > 0) {
                R = l.ratio;
                const int ng = (int) std::max<int64_t>(0, (u.p0 + u.n) / R - u.p0 / R);
                if (l.kv_src && ng > 0) return false;
                c = banks[(size_t) u.seq].ckv[(size_t) l.src][(size_t) l.dev];
            }
            for (int i = 0; i < u.n; ++i) {
                bp.nsel[u.r0 + i] = R > 0 && (int) ((u.p0 + i + 1) / R) > 0 ? wp.topk[l.il][u.r0 + i] : 0;
                bp.ck.ckv[u.r0 + i] = c;
            }
        }
        return true;
    }
    bool attn_batch_multi(Layer& l, Dev& d, size_t li, int mi, int T, const WinPlan& wp, std::string& err,
                          BtPre* bp = nullptr) {
        cudaStream_t s = d.st;
        const int HD = g.hd, NHL = l.ahn, ts = (int) topk_stride();
        const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
        const MaPlan& mp = bt_mplan;
        RingRuns rr;
        bt_runs(l, li, mi, rr);
        if (bp == nullptr || !bp->kv) {   // (DS4_BT_FUSE: else attn_batch's merged launches did these three)
        ring_to_ext_runs(rr, d.mext, g.win, HD, s);
        Finish fk;
        fk.w = l.kv_norm;
        fk.eps = g.eps;
        fk.rd = g.rd;
        fk.freqs = freqs;
        fk.quant = 1;
        fk.dst = d.mext;
        fk.dst_stride = HD;
        FinishRows fr;
        for (int t = 0; t < T; ++t) {
            fr.pos[t] = mp.pos[t];
            fr.dst[t] = mp.dst[t];
        }
        if (!finish_rows(d.kvr, T, HD, HD, fk, fr, s)) {
            err = "DS4_MULTI_ATTN: the KV rows' finish refused";
            return false;
        }
        // (a verify window: each run's replaced ring rows to l.ring_bak at its rows, as the per-run path puts them)
        ext_to_ring_runs(rr, d.mext, g.win, HD, s);
        }
        AttnRows ar;
        AttnCkv ck;
        bool one = true;
        for (int t = 0; t < T; ++t) {
            ar.win0[t] = mp.win0[t];
            ar.nwin[t] = mp.nwin[t];
            ar.nsel[t] = 0;
        }
        for (int k = 0; k < mp.nrun; ++k) {
            const MaRun& u = mp.run[k];
            const void* c = nullptr;
            if (!bt_run_sel(l, d, banks[(size_t) u.seq], li, mi, u.r0, u.n, u.p0, wp, ar.nsel + u.r0, c, err)) return false;
            for (int i = 0; i < u.n; ++i) ck.ckv[u.r0 + i] = c;
            one = one && u.n == 1;
        }
        if (NHL == 0) return true;
        bool seld = false;   // (DS4_BT_FUSE: the folded unpack had exactly these arguments, else it runs again here)
        if (bp != nullptr && bp->sel) {
            seld = true;
            for (int t = 0; t < T && seld; ++t) seld = ar.nsel[t] == bp->nsel[t] && ck.ckv[t] == bp->ck.ckv[t];
            if (!seld && !btf_warned.exchange(true))
                std::fprintf(stderr, "ds4: DS4_BT_FUSE: layer %d: the folded unpack's arguments differ from sparse_attn_rows' - "
                                     "unpacked again (correct, slower; please report)\n", l.il);
        }
        sparse_attn_rows(d.q, d.mext, ck, d.topk, ts, ar, l.sink, NHL, HD, T, 1.0f / std::sqrt((float) HD), d.o, s, one,
                         &d.mscr, seld);
        Finish fo;
        fo.rd = g.rd;
        fo.vpp = NHL;
        fo.freqs = freqs;
        fo.inverse = 1;
        fo.quant = 1;
        FinishRows fp;
        for (int t = 0; t < T; ++t) fp.pos[t] = mp.pos[t];
        if (bp != nullptr && bp->oq != nullptr) {   // (DS4_BT_FUSE + DS4_XK_QO: finish_rows' launch, its int8 rows too)
            BtFin m;
            m.seg[0].kind = 1;
            m.seg[0].x = d.o;
            m.seg[0].n_vec = T * NHL;
            m.seg[0].len = HD;
            m.seg[0].stride = HD;
            m.seg[0].f = fo;
            m.seg[0].f.q8 = bp->oq;
            m.seg[0].f.q8d = bp->od;
            m.seg[0].q8_per = bp->per;
            m.seg[0].q8_rows = T;
            m.nseg = 1;
            m.fr = fp;
            bp->oq_done = bt_fin(m, s);
        }
        if (!(bp != nullptr && bp->oq_done) && !finish_rows(d.o, T * NHL, HD, HD, fo, fp, s)) {
            err = "DS4_MULTI_ATTN: the output's finish refused";
            return false;
        }
        return true;
    }

    // the attention half of layer() for a batch window: T rows, row b at bt_pos[b] of bank bt_bank[b].  The row-wise
    // steps run once over the T rows as layer() runs them; the steps that touch a sequence's state, or take a position,
    // run a row at a time - each exactly layer()'s call for a window of one at that position, on the bank's buffers
    // (d.ext, the indexer's and the compressor's scratch reused row after row, in stream order)
    bool attn_batch(Layer& L0, int mi, int T, const WinPlan& wp, std::string& err) {
        Layer& l = member(L0, mi);
        Dev& d = devs[(size_t) l.dev];
        cudaSetDevice(d.id);
        cudaStream_t s = d.st;
        const int nm = L0.nm;
        const int D = g.dim, H = g.hc, HD = g.hd, NHL = l.ahn, HQ = NHL * HD, OG = l.ogn;
        const ArGroup& ag = groups[(size_t) L0.grp].ar;
        const float* freqs = l.ratio ? d.freqs_comp : d.freqs_win;
        const size_t li = (size_t) L0.il;   // (a trunk layer: its index in L)
        const int ts = (int) topk_stride();
        // DS4_MULTI_ATTN=1: the shared launches (attn_batch_multi) where every run takes sparse_attn's few-queries
        // path the per-run path would take (sparse_attn_rows_ok), else the per-run path; each row's bits the same
        bool multi = false;
        if (mattn_on && bt_mplan_ok && d.mext != nullptr && bt_mplan.T == T) {
            int max_run = 0;
            bool any1 = false, anyn = false;
            for (int k = 0; k < bt_mplan.nrun; ++k) {
                max_run = std::max(max_run, bt_mplan.run[k].n);
                (bt_mplan.run[k].n == 1 ? any1 : anyn) = true;
            }
            multi = sparse_attn_rows_ok(T, max_run, ts, &d.mscr, any1 && anyn);
        }
        if (mattn_buf) (multi ? mattn_shared : mattn_per_run).fetch_add(1, std::memory_order_relaxed);
        const bool hcf = hc_fuses(l, T);   // (DS4_HC_FUSE=2: the batch window's rows in the fused launch)
        gg::PreQ8 xq8;
        if (hcf) {
            if (!hc_fused(d, l, false, T, xq8, err)) return false;
        } else {
#if defined(STRATA_METAL)
        hc_mix_split(d.h, l.hca_fn, H * D, (2 + H) * H, T, g.eps, d.mix, l.hca_scale, l.hca_base, H,
                     g.sinkhorn, g.hc_eps, d.a_pre, d.a_post, d.a_comb, s);
#else
        hc_mix_split(d.h, l.hca_fn, H * D, (2 + H) * H, T, g.eps, d.mix, d.hccnt, l.hca_scale, l.hca_base, H, g.sinkhorn, g.hc_eps,
                     d.a_pre, d.a_post, d.a_comb, s);
#endif
        hc_pre_norm(d.h, d.pre, l.attn_norm, D, H, T, g.eps, d.x, s);
        }
        {
            x3::MvJob j[4];
            const int nj = attn_in_jobs(l, d.x, d.qr, d.kvr, d.ckr, d.cgr, T, j);
            if (!mv_n(d, j, nj, err, hcf ? &xq8 : nullptr)) return false;
        }
        Finish fq;
        fq.w = l.q_norm;
        fq.eps = g.eps;
        gg::PreQ8 qrp;   // (DS4_DECODE_TRIM bit 2: q's norm rounds wq_b's int8 input where it makes it)
        const bool qr8 = NHL > 0 && trim_q(d, l, T, fq, qrp);
        // DS4_BT_FUSE (fusion plan F2) with DS4_ATTN_MERGE: over DS4_MULTI_ATTN's runs, {q's norm [+ int8], the runs'
        // rings into d.mext, the KV rows' finish} in one launch here - each writes its own buffer (qr / its int8, each run's
        // ring rows of its block, each run's own rows of its block) and reads only the input GEMVs' rows and the rings - then
        // {q's RoPE, the runs' new rows into their rings [+ backups]} (=3: and the rows' unpack) after wq_b below.  The order
        // the unfused path runs these in is q's norm, q's RoPE, then attn_batch_multi's three; none of them reads what another
        // writes except e2r after the KV finish (second launch after the first)
        BtPre bp;
        RingRuns brr;
        const bool btm = bt_fuse > 0 && multi && attn_merge > 0 && !l.mtp && dump_s == nullptr && dump_l == nullptr;
        if (btm) {
            const MaPlan& mp = bt_mplan;
            bt_runs(l, li, mi, brr);
            BtFin m1;
            m1.seg[0].kind = 0;
            m1.seg[0].x = d.qr;
            m1.seg[0].n_vec = T;
            m1.seg[0].len = g.q_lora;
            m1.seg[0].stride = g.q_lora;
            m1.seg[0].f = fq;
            Finish fk;   // (attn_batch_multi's)
            fk.w = l.kv_norm;
            fk.eps = g.eps;
            fk.rd = g.rd;
            fk.freqs = freqs;
            fk.quant = 1;
            fk.dst = d.mext;
            fk.dst_stride = HD;
            m1.seg[1].kind = 1;
            m1.seg[1].x = d.kvr;
            m1.seg[1].n_vec = T;
            m1.seg[1].len = HD;
            m1.seg[1].stride = HD;
            m1.seg[1].f = fk;
            m1.nseg = 2;
            for (int t = 0; t < T; ++t) {
                m1.fr.pos[t] = mp.pos[t];
                m1.fr.dst[t] = mp.dst[t];
            }
            m1.ring = 2;
            m1.rr = brr;
            m1.ext = d.mext;
            m1.n = g.win;
            m1.d = HD;
            bp.kv = bt_fin(m1, s);
        }
        if (!bp.kv) finish(d.qr, T, g.q_lora, g.q_lora, fq, s);
        if (NHL > 0) {
            x3::MvJob jb = job(l.a3 ? l.a3_qd : l.wq_b, d.qr, d.q, T, g.q_lora, HQ);
            if (!mv_n(d, &jb, 1, err, qr8 ? &qrp : nullptr)) return false;
            if (bp.kv) {   // (DS4_BT_FUSE: q's RoPE in the second merged launch below)
            } else if (multi) {   // (DS4_MULTI_ATTN: every row at its own position, one launch)
                Finish fr;
                fr.rd = g.rd;
                fr.vpp = NHL;
                fr.freqs = freqs;
                FinishRows fp;
                for (int b = 0; b < T; ++b) fp.pos[b] = (int) bt_pos[b];
                if (!finish_rows(d.q, T * NHL, HD, HD, fr, fp, s)) {
                    err = "DS4_MULTI_ATTN: q's rotation refused";
                    return false;
                }
            } else
            for (int b = 0; b < T; ++b) {   // (RoPE at each row's own position)
                Finish fr;
                fr.rd = g.rd;
                fr.pos = (int) bt_pos[b];
                fr.vpp = NHL;
                fr.freqs = freqs;
                finish(d.q + (size_t) b * HQ, NHL, HD, HD, fr, s);
            }
        }
        // the per-sequence state work: a bank's rows (a run: one row, or DS4_BATCH_DSPARK's [y, drafts]) go through it
        // together, as layer() takes a window of them at the run's first position - its ring, compressor, indexer and
        // sparse attention calls over the run's n rows, on the bank's buffers (d.ext and the indexer's scratch reused
        // run after run, in stream order).  A run of one is a window of one.  (DS4_MULTI_ATTN=1: attn_batch_multi,
        // the same calls for all the runs at once where they read only their own state)
        if (bp.kv) {   // (DS4_BT_FUSE: the second merged launch - q's RoPE at each row's position, the new rows into the rings)
            const MaPlan& mp = bt_mplan;
            BtFin m2;
            Finish fr;   // (the unfused multi path's q rotation)
            fr.rd = g.rd;
            fr.vpp = NHL;
            fr.freqs = freqs;
            if (NHL > 0) {
                m2.seg[0].kind = 1;
                m2.seg[0].x = d.q;
                m2.seg[0].n_vec = T * NHL;
                m2.seg[0].len = HD;
                m2.seg[0].stride = HD;
                m2.seg[0].f = fr;
                m2.nseg = 1;
            }
            for (int b = 0; b < T; ++b) m2.fr.pos[b] = (int) bt_pos[b];
            m2.ring = 3;
            m2.rr = brr;
            m2.ext = d.mext;
            m2.n = g.win;
            m2.d = HD;
            // (=3: sparse_attn_rows' unpack too, where the rows' selections and compressed rows are final here)
            if (attn_merge > 2 && NHL > 0 && HD == 512 && bt_sel_final(l, wp, bp)) {
                m2.unpack = true;
                m2.uc = bp.ck;
                m2.sel = d.topk;
                m2.sel_stride = ts;
                m2.cap = d.mscr.cap;
                m2.out = d.mscr.rows;
                m2.ut = T;
                for (int t = 0; t < T; ++t) {
                    m2.ua.win0[t] = mp.win0[t];
                    m2.ua.nwin[t] = mp.nwin[t];
                    m2.ua.nsel[t] = bp.nsel[t];
                }
            }
            bool ok2 = bt_fin(m2, s);
            if (!ok2 && m2.unpack) {
                m2.unpack = false;
                ok2 = bt_fin(m2, s);
            }
            bp.sel = ok2 && m2.unpack;
            if (!ok2) {   // (refused: the unfused launches)
                if (NHL > 0 && !finish_rows(d.q, T * NHL, HD, HD, fr, m2.fr, s)) {
                    err = "DS4_BT_FUSE: q's rotation refused";
                    return false;
                }
                ext_to_ring_runs(brr, d.mext, g.win, HD, s);
            }
            if (!(btf_seen.fetch_or(1u) & 1u))
                std::fprintf(stderr, "ds4: DS4_BT_FUSE: the merged attention launches engaged (first: layer %d, %d rows)\n", l.il, T);
            if (bp.sel && !(btf_seen.fetch_or(2u) & 2u))
                std::fprintf(stderr, "ds4: DS4_BT_FUSE: the unpack folded into the second merged launch (first: layer %d, %d rows)\n",
                             l.il, T);
        }
        // (DS4_BT_FUSE + DS4_XK_QO: the o finish rounds wo_a's int8 input, T rows a group, into HC_FUSE's x int8 rows - free
        //  here: only the input GEMVs above read them, and the MoE's hc_fused writes them anew)
        if (bt_fuse > 0 && xk_qo && multi && NHL > 0 && OG > 0 && HQ % OG == 0 && (HQ / OG) % 32 == 0 && HD % 32 == 0 &&
            d.xq8 != nullptr && d.xd8 != nullptr && (size_t) T * HQ <= (size_t) kWin * D) {
            bp.oq = d.xq8;
            bp.od = d.xd8;
            bp.per = HQ / OG;
        }
        if (multi && !attn_batch_multi(l, d, li, mi, T, wp, err, bp.kv || bp.oq != nullptr ? &bp : nullptr)) return false;
        for (int r0 = 0; !multi && r0 < T;) {
            int n = 1;
            while (r0 + n < T && bt_bank[r0 + n] == bt_bank[r0]) ++n;
            const int64_t p0 = bt_pos[r0];
            Bank& bk = banks[(size_t) bt_bank[r0]];
            uint8_t* win = bk.win[li][(size_t) mi];
            ring_to_ext(win, d.ext, p0, g.win, HD, s);
            Finish fk;
            fk.w = l.kv_norm;
            fk.eps = g.eps;
            fk.rd = g.rd;
            fk.pos = (int) p0;
            fk.freqs = freqs;
            fk.quant = 1;
            fk.dst = d.ext + (size_t) g.win * HD;
            fk.dst_stride = HD;
            finish(d.kvr + (size_t) r0 * HD, n, HD, HD, fk, s);
            // (a verify window: the ring rows these replace, at their window rows, for the rollback of rejected drafts)
            ext_to_ring(d.ext, win, p0, g.win, n, HD, s,
                        bt_spec && l.ring_bak != nullptr ? l.ring_bak + (size_t) r0 * win_rb() : nullptr);
            AttnRows ar;
            for (int t = 0; t < n; ++t) {
                const int first = (int) std::max<int64_t>(g.win - p0, t + 1);   // ext row of position max(0, p - win + 1)
                ar.win0[t] = first;
                ar.nwin[t] = g.win + t - first + 1;
                ar.nsel[t] = 0;
            }
            const void* ckv = nullptr;
            if (!bt_run_sel(l, d, bk, li, mi, r0, n, p0, wp, ar.nsel, ckv, err)) return false;
            if (NHL > 0) {
                sparse_attn(d.q + (size_t) r0 * HQ, d.ext, ckv, d.topk + (size_t) r0 * ts, ts, ar, l.sink, NHL, HD, n,
                            1.0f / std::sqrt((float) HD), d.o + (size_t) r0 * HQ, s, kKvFp4, 0, &d.attn_scr);
                Finish fo;
                fo.rd = g.rd;
                fo.pos = (int) p0;
                fo.vpp = NHL;
                fo.freqs = freqs;
                fo.inverse = 1;
                fo.quant = 1;
                finish(d.o + (size_t) r0 * HQ, n * NHL, HD, HD, fo, s);
            }
            r0 += n;
        }
        if (NHL > 0) {
            x3::MvJob j[16];
            const int per = HQ / OG;
            for (int gi = 0; gi < OG; ++gi)
                j[gi] = job(l.wo_a[gi], d.o + (size_t) gi * per, d.oa + (size_t) gi * g.o_lora, T, HQ, (size_t) OG * g.o_lora);
            gg::PreQ8 po;   // (DS4_BT_FUSE + DS4_XK_QO: the groups read the o finish's int8 rows, T rows each)
            if (bp.oq_done) {
                po.x = d.o;
                po.q = bp.oq;
                po.d = bp.od;
                po.k = per;
                po.rows = T;
                po.nslice = OG;
                po.slice = (size_t) per;
                po.xcs = (size_t) HQ;
                if (!(btf_seen.fetch_or(4u) & 4u))
                    std::fprintf(stderr, "ds4: DS4_BT_FUSE: the o finish rounds wo_a's input (first: layer %d, %d rows)\n", l.il, T);
            }
            if (!mv_n(d, j, OG, err, bp.oq_done ? &po : nullptr)) return false;
            if (!mv(d, {job(l.a3 ? l.a3_bd : l.wo_b, d.oa, d.ao, T, (size_t) OG * g.o_lora, D)}, err)) return false;
        } else CK(cudaMemsetAsync(d.ao, 0, (size_t) T * D * sizeof(*d.ao), s));
        if (bt_fuse > 0) {   // (DS4_BT_FUSE: DS4_AR_POST's fold as layer() takes it; DS4_AR_POST unset: the two below)
            ar_then_post(d, d.ao, T, ag, mi, nm, d.a_post, d.a_comb, s);
            if (ar_post > 0 && nm > 1 && !(btf_seen.fetch_or(8u) & 8u))
                std::fprintf(stderr, "ds4: DS4_BT_FUSE: the attention's all-reduce through DS4_AR_POST (first: layer %d, %d rows)\n",
                             l.il, T);
        } else {
        if (nm > 1) allreduce(d.ao, T * D, ag, mi, ++d.ar_seq, d.xcnt, s);
        hc_post(d.ao, d.h, d.a_post, d.a_comb, D, H, T, d.h2, s);
        }
        std::swap(d.h, d.h2);
        prof_mark(d, 1);
        return true;
    }

    // one batch step: row b feeds tk[b] to bank bk[b]; the B rows' logits are left on the head device.  A bank may
    // have several rows (DS4_BATCH_DSPARK: its [y, drafts], or a teacher-forced run of its tokens), contiguous and
    // in order: they take its next positions, each row seeing the ones before it as a window of one at its position
    // would.  Each bank's position moves on by its rows.  B <= kWin rows; a bank's rows never span a gap.
    bool forward_batch(const int* tk, const int* bk, int B, std::string& err) {
        if (bt_n <= 0) {
            err = "batched decode is off (DS4_BATCH_DECODE)";
            return false;
        }
        if (B < 1 || B > kWin) {
            err = "a batch of " + std::to_string(B) + " rows (at most " + std::to_string(kWin) + ")";
            return false;
        }
        if (!imgs.empty()) {
            err = "a batch step with pictures in the model";
            return false;
        }
        const std::vector<int32_t>* rt[kWin];
        for (int b = 0; b < B; ++b) {
            if (bk[b] < 0 || bk[b] >= bt_n) {
                err = "bank " + std::to_string(bk[b]);
                return false;
            }
            int run = 0;   // (this row's place in its bank's run)
            for (int c = b - 1; c >= 0 && bk[c] == bk[b]; --c) ++run;
            for (int c = 0; c < b - run; ++c)
                if (bk[c] == bk[b]) {
                    err = "bank " + std::to_string(bk[b]) + "'s rows are not contiguous in one step";
                    return false;
                }
            const Bank& k = banks[(size_t) bk[b]];
            if (k.pos <= 0) {
                err = "bank " + std::to_string(bk[b]) + " holds no prompt";
                return false;
            }
            if (k.pos + run + 1 > o.max_context) {
                err = "bank " + std::to_string(bk[b]) + ": the context is full";
                return false;
            }
            if (tk[b] < 0 || tk[b] >= g.vocab) {
                err = "token " + std::to_string(tk[b]) + " out of range";
                return false;
            }
        }
        for (int b = 0; b < B; ++b) {
            Bank& k = banks[(size_t) bk[b]];
            bt_bank[b] = bk[b];
            bt_first[b] = b == 0 || bk[b - 1] != bk[b];
            bt_pos[b] = bt_first[b] ? k.pos : bt_pos[b - 1] + 1;
            k.slot_held = false;
            k.toks.push_back(tk[b]);
            k.ctoks.push_back(ctok(bt_pos[b], tk[b]));
            rt[b] = &k.ctoks;
        }
        const double te = now_ms();
        const int64_t eg_w0 = eg_wait_ns.load();
        for (int li = 0; li < pk.eg_layers; ++li) {
            EgBatch& eb = *eg_win[(size_t) li];
            if (eb.live) eg_finish(eb);
            eg_issue(0, B, li, nullptr, eb, bt_pos, rt);
        }
        st.engram_ms += now_ms() - te;
        const int D = g.dim;
        for (int b = 0; b < B; ++b) std::memcpy(h_emb + (size_t) b * D, emb_row(bt_pos[b], tk[b]), (size_t) D * 2);
        int ct[kWin], cc[kWin];
        for (int b = 0; b < B; ++b) {   // (each sequence's indexer state, as its own windows of one leave it: entry 0)
            ct[b] = banks[(size_t) bk[b]].cur_topk[0];
            cc[b] = banks[(size_t) bk[b]].cur_cand[0];
        }
        plan_window(0, B, wplan, bt_pos, ct, cc);
        for (int b = 0; b < B; ++b) {
            banks[(size_t) bk[b]].cur_topk[0] = ct[b];
            banks[(size_t) bk[b]].cur_cand[0] = cc[b];
        }
        prof_window = false;
        n_logits = B;
        // DS4_MULTI_ATTN: the window's runs (a bank's contiguous rows each) in the shared buffer - the same for every
        // layer, made here before the device threads read it
        bt_mplan_ok = false;
        if (mattn_on) {
            int rseq[kWin];
            for (int b = 0; b < B; ++b) rseq[b] = bt_bank[b];
            bt_mplan_ok = ma_plan(rseq, bt_pos, B, g.win, false, bt_mplan);
        }
        const double tl = now_ms();
        bt_on = true;
        const bool ok = forward_par(bt_pos[0], B, err);
        bt_on = false;
        st.layer_ms += now_ms() - tl;
        st.mattn_shared = mattn_shared.load();
        st.mattn_per_run = mattn_per_run.load();
        for (auto& eb : eg_win)
            if (eb->live) eg_finish(*eb);
        if (!ok) return false;
        st.engram_ms += (double) (eg_wait_ns.load() - eg_w0) / 1e6;
        eg_stats();
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        const double th = now_ms();
        CK(cudaStreamSynchronize(d.st));
        st.head_ms += now_ms() - th;
        prof_collect();
        for (int b = 0; b < B; ++b) banks[(size_t) bk[b]].pos += 1;
        st.tokens += B;
        cache_tick(B);
        return true;
    }

    // DS4_BATCH_DSPARK: bank b's verify rows [row0, row0 + T) at positions p0 .. keep their first `keep`: the ring
    // rows the rest replaced back (their backups, at their window rows), the compressor's partial group back to its
    // snapshot and the kept rows' raw rows replayed into it (the solo rollback's steps, on the bank's buffers); the
    // compressed KV and index keys past them are written again when those positions come
    void bank_rollback(int b, int64_t p0, int row0, int T, int keep) {
        Bank& bk = banks[(size_t) b];
        if (keep < T) {
            std::vector<RingBatch>& rbs = rb_scratch;
            rbs.assign(devs.size(), RingBatch{});
            for (int il = 0; il < g.nl; ++il)
                for (int m = 0; m < L[(size_t) il].nm; ++m) {
                    Layer& l = member(L[(size_t) il], m);
                    uint8_t* ring = bk.win[(size_t) il][(size_t) m];
                    const uint8_t* bak = l.ring_bak + (size_t) row0 * win_rb();
                    RingBatch& rb = rbs[(size_t) l.dev];
                    if (rb.n == kMaxRingBatch) {
                        cudaSetDevice(devs[(size_t) l.dev].id);
                        ring_restore(ring, bak, p0, g.win, keep, T, g.hd, devs[(size_t) l.dev].st);
                        continue;
                    }
                    rb.ring[rb.n] = ring;
                    rb.bak[rb.n++] = bak;
                }
            for (size_t di = 0; di < devs.size(); ++di)
                if (rbs[di].n > 0) {
                    cudaSetDevice(devs[di].id);
                    ring_restore_batch(rbs[di], p0, g.win, keep, T, g.hd, devs[di].st);
                }
            for (int il = 0; il < g.nl; ++il)
                for (int m = 0; m < L[(size_t) il].nm; ++m) {
                    Layer& l = member(L[(size_t) il], m);
                    float* snap = bk.c_snap.empty() ? nullptr : bk.c_snap[(size_t) il][(size_t) m];
                    if (l.c_snap == nullptr || snap == nullptr) continue;
                    Dev& d = devs[(size_t) l.dev];
                    cudaSetDevice(d.id);
                    float* ckv = bk.c_kv[(size_t) il][(size_t) m];
                    float* csc = bk.c_score[(size_t) il][(size_t) m];
                    const size_t ns = (size_t) l.ratio * g.hd * 4;
                    cudaMemcpyAsync(ckv, snap, ns, cudaMemcpyDeviceToDevice, d.st);
                    cudaMemcpyAsync(csc, snap + (size_t) l.ratio * g.hd, ns, cudaMemcpyDeviceToDevice, d.st);
                    compress_win(l.c_rows + (size_t) row0 * g.hd, l.c_rows + (size_t) (kWin + row0) * g.hd, ckv, csc, l.ratio,
                                 (int) p0, keep, g.hd, l.c_norm, g.eps, d.latent, d.st);
                }
        }
        bk.pos = p0 + keep;
        bk.toks.resize((size_t) bk.pos);
        bk.ctoks.resize((size_t) bk.pos);
    }

    // DS4_BATCH_DSPARK: one verify window over S sequences - sequence s is bank bk[s] with nr[s] rows rows[...]
    // ([y, its drafts], contiguous; at most kWin rows in all).  Greedy: each keeps its drafts while the trunk's argmax
    // agrees, acc[s] of them, and next[s] is the argmax after them; then each bank keeps acc + 1 rows and its drafter is
    // seeded with them (the solo verify's rollback and seed_drafter, a bank at a time)
    bool batch_verify(const int* bk, const int* nr, const int* rows, int S, int* acc, int* next, std::string& err,
                      const Model::BatchSampling* bs = nullptr) {   // (DS4_BATCH_DSPARK_SAMPLED: bs, else greedy)
        if (!bt_spec_ok) {
            err = "batch drafts are off (DS4_BATCH_DSPARK=1 with the drafter loaded)";
            return false;
        }
        int rb[kWin], R = 0, row0[kWin];
        for (int s = 0; s < S; ++s) {
            if (nr[s] < 1 || R + nr[s] > kWin) {
                err = "a verify window of more than " + std::to_string(kWin) + " rows";
                return false;
            }
            row0[s] = R;
            for (int t = 0; t < nr[s]; ++t) rb[R++] = bk[s];
        }
        int64_t p0[kWin];
        for (int s = 0; s < S; ++s) p0[s] = banks[(size_t) bk[s]].pos;
        const double tv = now_ms();
        bt_spec = true;
        const bool ok = forward_batch(rows, rb, R, err);
        bt_spec = false;
        st.verify_ms += now_ms() - tv;
        if (!ok) return false;
        int pick[kWin];
        if (!batch_pick(R, pick, err)) return false;
        for (int s = 0; s < S; ++s) {
            const int n = nr[s] - 1;
            int m = 0;
            if (bs != nullptr && bs[s].temperature > 0.0f) {   // DS4_BATCH_DSPARK_SAMPLED: the solo verify()'s sampled rule
                if (!bt_spec_rows(row0[s], rows + row0[s] + 1, n, bs[s], m, next[s], err)) return false;
            } else {
                while (m < n && pick[row0[s] + m] == rows[row0[s] + m + 1]) ++m;
                next[s] = pick[row0[s] + m];
            }
            acc[s] = m;
            bank_rollback(bk[s], p0[s], row0[s], nr[s], m + 1);
            st.drafts_offered += n;
            st.drafts_accepted += m;
            for (int i = 0; i < n && i <= m && i < 8; ++i) {
                ++st.draft_reached[i];
                if (i < m) ++st.draft_kept[i];
            }
        }
        for (int s = 0; s < S; ++s) {   // (the drafter of each: its kept rows' taps, at their window rows)
            bank_swap(bk[s]);
            const bool sd = seed_drafter(p0[s], acc[s] + 1, row0[s], err);
            bank_swap(bk[s]);
            if (!sd) return false;
        }
        return true;
    }

    // DS4_BATCH_DSPARK_SAMPLED: a sequence's rows [r0, r0 + n] of the verify window (y, then its n drafts - the
    // drafter's argmax: batch_draft drafts greedy) under the speculative-sampling rule over the request's chain - the
    // solo verify()'s sampled branch with q a point at each draft, on these rows: row i keeps draft i with probability
    // p(d), else draws from the residual (never d itself), past the first rejection the rows do not count; all n kept:
    // row n is drawn as sample() at counter + n.  m: the drafts that stand; next: the token after them.
    bool bt_spec_rows(int r0, const int* drafts, int n, const Model::BatchSampling& q, int& m, int& next, std::string& err) {
        const int V = g.vocab;
        Dev& hd = devs[(size_t) head_dev];
        cudaSetDevice(hd.id);
        m = 0;
        if (n < 0 || n > kWin - 1) {
            err = "a sampled verify run of " + std::to_string(n) + " drafts";
            return false;
        }
        if (n > 0) {
            for (int i = 0; i < n; ++i) {
                h_specq[(size_t) i].n = 1;
                h_specq[(size_t) i].ids[0] = drafts[i];
                h_specq[(size_t) i].p[0] = 1.0;
                h_idx[i] = drafts[i];
            }
            CK(cudaMemcpyAsync(d_specq, h_specq.data(), (size_t) n * sizeof(strata::dsv41k::SpecList), cudaMemcpyHostToDevice,
                               hd.st));
            CK(cudaMemcpyAsync(d_ints + 32, h_idx, (size_t) n * 4, cudaMemcpyHostToDevice, hd.st));
            strata::dsv41k::SamplerParams sp;
            sp.greedy = false;
            sp.temperature = q.temperature;
            sp.top_p = q.top_p;
            sp.top_k = q.top_k;
            sp.min_p = q.min_p;
            sp.seed = q.seed;
            sp.counter = q.counter;
            strata::dsv41k::sample_verify(hd.logits + (size_t) r0 * V, n, V, sp, d_specq, d_ints + 32, d_ints + 16, hd.st);
#if defined(STRATA_METAL)
            ds4_metal_flush();
#endif
            CK(cudaMemcpyAsync(h_idx, d_ints + 16, (size_t) n * 4, cudaMemcpyDeviceToHost, hd.st));
            CK(cudaStreamSynchronize(hd.st));
            while (m < n && h_idx[m] == drafts[m]) ++m;
        }
        next = m < n ? h_idx[m]
                     : sample_row(r0 + n, q.temperature, q.top_p, q.top_k, q.min_p, q.seed, q.counter + (uint64_t) n, nullptr);
        if (next < 0) {
            err = "a sampled verify row's draw failed";
            return false;
        }
        return true;
    }

    // srvbatch: row `row` of the batch window's logits (batch_pick's rows, on the head device) sampled as sample() does
    // its one row - a temperature > 0 request in a plain batch step
    int batch_sample_row(int row, float temperature, float top_p, int top_k, float min_p, uint64_t seed, uint64_t counter) {
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        strata::dsv41k::SamplerParams sp;
        sp.temperature = temperature;
        sp.greedy = temperature <= 0.0f;
        sp.top_p = top_p;
        sp.top_k = top_k;
        sp.min_p = min_p;
        sp.seed = seed;
        sp.counter = counter;
        strata::dsv41k::sample_tokens(d.logits + (size_t) std::max(0, row) * g.vocab, 1, g.vocab, nullptr, 0, sp, d.tok, d.st);
        int t = -1;
#if defined(STRATA_METAL)
        ds4_metal_flush();
#endif
        cudaMemcpyAsync(&t, d.tok, 4, cudaMemcpyDeviceToHost, d.st);
        cudaStreamSynchronize(d.st);
        return t;
    }

    // the B rows' greedy picks (the verify path's sample_tokens over all rows at once)
    bool batch_pick(int B, int* next, std::string& err) {
        Dev& hd = devs[(size_t) head_dev];
        cudaSetDevice(hd.id);
        strata::dsv41k::SamplerParams sp;
        sp.greedy = true;
        sp.temperature = 0.0f;
        strata::dsv41k::sample_tokens(hd.logits, B, g.vocab, nullptr, 0, sp, d_bt, hd.st);
        CK(cudaMemcpyAsync(h_bt, d_bt, (size_t) B * 4, cudaMemcpyDeviceToHost, hd.st));
        CK(cudaStreamSynchronize(hd.st));
        for (int b = 0; b < B; ++b) next[b] = h_bt[b];
        return true;
    }

    int sample(float temperature, float top_p, int top_k, float min_p, uint64_t seed, uint64_t counter) {
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        strata::dsv41k::SamplerParams sp;
        sp.temperature = temperature;
        sp.greedy = temperature <= 0.0f;
        sp.top_p = top_p;
        sp.top_k = top_k;
        sp.min_p = min_p;
        sp.seed = seed;
        sp.counter = counter;
        strata::dsv41k::sample_tokens(d.logits + (size_t) std::max(0, n_logits - 1) * g.vocab, 1, g.vocab, nullptr, 0,
                                       sp, d.tok, d.st);
        return tok_back(d);
    }

    bool logits(std::vector<float>& out) {
        if (logits_all) {
            out = chunk_logits;
            return true;
        }
        Dev& d = devs[(size_t) head_dev];
        cudaSetDevice(d.id);
        out.resize((size_t) std::max(1, n_logits) * g.vocab);
#if defined(STRATA_METAL)
        ds4_metal_flush();   // (a host read of a device result: commit the batched dispatches first)
#endif
        // (on d.st: the legacy stream is not ordered after the non-blocking d.st that wrote the head.  Project Maya
        // 2040174, #619.  Today forward() and forward_chunks() end with a sync of the head's d.st, so the old copy read
        // finished logits; this keeps logits() correct without relying on that)
        return cudaMemcpyAsync(out.data(), d.logits, out.size() * 4, cudaMemcpyDeviceToHost, d.st) == cudaSuccess &&
               cudaStreamSynchronize(d.st) == cudaSuccess;
    }

    // ---- the drafter's footprint (docs/dsv41/cards/DR-05.md): DS4_DRAFT_KEEP / _COUNTS / _EXPERTS / _CAL / _HIST ----
    // the experts a drafter block may hold on a primary GPU (the trunk's layers: all)
    int dcap(const Layer& l) const {
        if (!l.mtp) return l.n_exp;
        if (dhelper) return 0;
        return dkeep_n > 0 && !l.dkeep.empty() ? std::min(dkeep_n, l.n_exp) : l.n_exp;
    }
    // a counts file: "dims <blocks> <experts>", then "c <block> <expert> <picks>" lines (summed when repeated)
    bool read_dcounts(const std::string& p, std::vector<uint64_t>& v, std::string& err) const {
        std::FILE* f = std::fopen(p.c_str(), "r");
        if (f == nullptr) {
            err = p + ": cannot open";
            return false;
        }
        const int N = g.d_n_exp;
        v.assign((size_t) g.n_mtp * N, 0);
        int nb = -1, ne = -1;
        char ln[256];
        while (std::fgets(ln, sizeof ln, f) != nullptr) {
            int b = 0, e = 0;
            unsigned long long c = 0;
            if (std::sscanf(ln, "dims %d %d", &b, &e) == 2) {
                nb = b;
                ne = e;
            } else if (std::sscanf(ln, "c %d %d %llu", &b, &e, &c) == 3 && b >= 0 && b < g.n_mtp && e >= 0 && e < N) {
                v[(size_t) b * N + e] += c;
            }
        }
        std::fclose(f);
        if (nb != g.n_mtp || ne != N) {
            err = p + ": not a drafter counts file of " + std::to_string(g.n_mtp) + " blocks x " + std::to_string(N) +
                  " experts (its dims line: " + std::to_string(nb) + " x " + std::to_string(ne) + ")";
            return false;
        }
        return true;
    }
    // after the layers are made (L has the drafter's blocks), before the members are copied from them
    bool draft_small_setup(std::string& err) {
        auto set = [](const char* v) { return v != nullptr && *v != '\0'; };
        const char* kv = std::getenv("DS4_DRAFT_KEEP");
        const char* cv = std::getenv("DS4_DRAFT_COUNTS");
        const char* ev = std::getenv("DS4_DRAFT_EXPERTS");
        const char* calv = std::getenv("DS4_DRAFT_CAL");
        const char* hv = std::getenv("DS4_DRAFT_HIST");
        dreport = set(kv) || set(cv) || set(ev) || set(calv) || (set(hv) && std::atoi(hv) != 0);
        if (g.n_mtp == 0) {
            if (set(kv) || set(ev) || set(calv)) std::fprintf(stderr, "ds4: DS4_DRAFT_*: no drafter loaded, ignored\n");
            dreport = false;
            return true;
        }
        const int N = g.d_n_exp;
        dpick.assign((size_t) g.n_mtp * N, 0);
        if (set(cv)) dcount_path = cv;
        if (set(ev)) {
            if (std::strcmp(ev, "helper") == 0) dhelper = true;
            else if (std::strcmp(ev, "gpu") != 0) {
                err = std::string("DS4_DRAFT_EXPERTS=") + ev + ": helper or gpu";
                return false;
            }
        }
        if (dhelper && o.helper_devices.empty()) {
            err = "DS4_DRAFT_EXPERTS=helper: no helper (--helper-device)";
            return false;
        }
        if (set(kv)) {
            char* end = nullptr;
            const double x = std::strtod(kv, &end);
            const bool pct = end != nullptr && *end == '%' && end[1] == '\0';
            const bool frac = pct || std::strchr(kv, '.') != nullptr;
            if (end == kv || !(x > 0.0) || (!pct && *end != '\0') || (frac && !pct && x > 1.0) || (pct && x > 100.0)) {
                err = std::string("DS4_DRAFT_KEEP=") + kv + ": a count of experts (1 .. " + std::to_string(N) +
                      "), a fraction (0.75) or a percentage (75%)";
                return false;
            }
            int n = pct ? (int) std::lround(x / 100.0 * N) : frac ? (int) std::lround(x * N) : (int) x;
            if (n < g.d_k) {
                std::fprintf(stderr, "ds4: DS4_DRAFT_KEEP=%s: %d is fewer than the %d a token picks; keeping %d\n", kv, n,
                             g.d_k, g.d_k);
                n = g.d_k;
            }
            n = std::min(n, N);
            if (n == N) {
                std::fprintf(stderr, "ds4: DS4_DRAFT_KEEP=%s: every drafter expert kept (as without it)\n", kv);
            } else {
                if (dcount_path.empty()) {
                    err = "DS4_DRAFT_KEEP needs DS4_DRAFT_COUNTS=<the counts file of a profiling run>";
                    return false;
                }
                std::vector<uint64_t> c;
                if (!read_dcounts(dcount_path, c, err)) {
                    err = "DS4_DRAFT_KEEP: " + err;
                    return false;
                }
                dkeep_n = n;
                std::string cov;
                for (int b = 0; b < g.n_mtp; ++b) {
                    Layer& l = L[(size_t) (g.nl + b)];
                    l.dcnt.assign(c.begin() + (long) b * N, c.begin() + (long) (b + 1) * N);
                    std::vector<int> ord((size_t) N);
                    std::iota(ord.begin(), ord.end(), 0);
                    std::stable_sort(ord.begin(), ord.end(), [&](int a2, int b2) { return l.dcnt[(size_t) a2] > l.dcnt[(size_t) b2]; });
                    l.dkeep.assign((size_t) N, 0);
                    double all = 0, kept = 0;
                    for (int i = 0; i < N; ++i) {
                        all += (double) l.dcnt[(size_t) ord[(size_t) i]];
                        if (i < n) {
                            l.dkeep[(size_t) ord[(size_t) i]] = 1;
                            kept += (double) l.dcnt[(size_t) ord[(size_t) i]];
                        }
                    }
                    if (all <= 0) {
                        err = "DS4_DRAFT_KEEP: " + dcount_path + " has no picks of drafter block " + std::to_string(b);
                        return false;
                    }
                    char s[48];
                    std::snprintf(s, sizeof s, "%s%.1f %%", b ? " / " : "", 100.0 * kept / all);
                    cov += s;
                }
                std::fprintf(stderr, "ds4: DS4_DRAFT_KEEP=%s: each drafter block keeps its %d most picked of %d experts on "
                                     "the GPU (%s); the kept hold %s of the profile's picks (blocks 0 .. %d); a dropped one is "
                                     "never picked (its router bias masked: the top %d over the kept, renormalised)\n",
                             kv, n, N, dcount_path.c_str(), cov.c_str(), g.n_mtp - 1, g.d_k);
            }
        }
        if (dhelper)
            std::fprintf(stderr, "ds4: DS4_DRAFT_EXPERTS=helper: the drafter's routed experts on the helpers (ranked first), "
                                 "none on the GPUs; its dense part stays on them\n");
        if (set(calv)) {
            dcal_dir = calv;
            dcal_gu.assign((size_t) g.n_mtp * N * g.dim, 0.0);
            dcal_cnt.assign((size_t) g.n_mtp * N, 0);
            if (!dhelper)
                std::fprintf(stderr, "ds4: DS4_DRAFT_CAL: the host sees a drafter expert's input only when the expert is off "
                                     "the GPUs - use it with DS4_DRAFT_EXPERTS=helper\n");
        }
        return true;
    }
    // a drafter block's router bias (one member's copy) with the dropped experts masked: they never reach the top k, and
    // the kept picks' weights are normalised among themselves (route_kernel's weights are the scores, not the bias)
    bool draft_mask_bias(Dev& d, float* bias, const Layer& l0, std::string& err) {
        const int n = l0.n_exp;
        std::vector<float> b((size_t) n);
        cudaSetDevice(d.id);
        if (cudaMemcpy(b.data(), bias, (size_t) n * 4, cudaMemcpyDeviceToHost) != cudaSuccess) {
            err = "DS4_DRAFT_KEEP: reading " + l0.name + "ffn.gate.bias back";
            return false;
        }
        for (int e = 0; e < n; ++e)
            if (!l0.dkeep[(size_t) e]) b[(size_t) e] = -1e30f;
        if (cudaMemcpy(bias, b.data(), (size_t) n * 4, cudaMemcpyHostToDevice) != cudaSuccess) {
            err = "DS4_DRAFT_KEEP: writing " + l0.name + "ffn.gate.bias";
            return false;
        }
        return true;
    }
    // DS4_DRAFT_CAL, on the lane: row t's FFN input is on the host when one of its picks is off the GPU
    void draft_cal(const Layer& l, int li, const Req& r, int T) {
        const int N = g.d_n_exp, D = g.dim, b = li - g.nl;
        for (int t = 0; t < T; ++t) {
            bool xok = false;
            for (int i = 0; i < l.k_exp; ++i) {
                const int e = r.ids[t][i];
                xok = xok || (e >= 0 && e < l.n_exp && l.slot[(size_t) e] < 0);
            }
            if (!xok) continue;
            for (int i = 0; i < l.k_exp; ++i) {
                const int e = r.ids[t][i];
                if (e < 0 || e >= N) continue;
                double* s = dcal_gu.data() + ((size_t) b * N + e) * D;
                const float* x = r.x[t];
                for (int c = 0; c < D; ++c) s[c] += (double) x[c] * x[c];
                ++dcal_cnt[(size_t) b * N + e];
            }
        }
    }
    // at exit: each block's picks sorted (the histogram), the counts file (a profiling run), the calibration sums
    void draft_report() {
        if (!dreport || dpick.empty()) return;
        dreport = false;
        const int N = g.d_n_exp;
        for (int b = 0; b < g.n_mtp; ++b) {
            const Layer& l = L[(size_t) (g.nl + b)];
            const uint64_t* c = dpick.data() + (size_t) b * N;
            std::vector<int> ord((size_t) N);
            std::iota(ord.begin(), ord.end(), 0);
            std::stable_sort(ord.begin(), ord.end(), [&](int a2, int b2) { return c[a2] > c[b2]; });
            double all = 0;
            int unused = 0;
            uint64_t dropped = 0;
            for (int e = 0; e < N; ++e) {
                all += (double) c[e];
                unused += c[e] == 0;
                if (!l.dkeep.empty() && !l.dkeep[(size_t) e]) dropped += c[e];
            }
            std::string cov;
            double run = 0;
            int q = 1;
            for (int i = 0; i < N; ++i) {
                run += (double) c[ord[(size_t) i]];
                if (i + 1 == (q * N + 3) / 4 && q <= 4) {
                    char s[64];
                    std::snprintf(s, sizeof s, "%s%d (%d %%): %.1f %%", q > 1 ? ", " : "", i + 1, 25 * q,
                                  all > 0 ? 100.0 * run / all : 0.0);
                    cov += s;
                    ++q;
                }
            }
            std::fprintf(stderr, "dspark experts: block %d: %.0f picks over %d experts; the most picked %s; never picked %d; "
                                 "picks of dropped experts %llu\n",
                         b, all, N, cov.c_str(), unused, (unsigned long long) dropped);
            std::string row;
            for (int i = 0; i < N; ++i) {
                char s[32];
                std::snprintf(s, sizeof s, " %d:%llu", ord[(size_t) i], (unsigned long long) c[ord[(size_t) i]]);
                row += s;
                if ((i + 1) % 16 == 0 || i + 1 == N) {
                    std::fprintf(stderr, "dspark experts: block %d sorted (expert:picks)%s\n", b, row.c_str());
                    row.clear();
                }
            }
        }
        if (!dcount_path.empty() && dkeep_n == 0) {   // a profiling run: its picks added into the file
            std::vector<uint64_t> v = dpick, old;
            std::string e2;
            bool ok = true;
            if (std::FILE* f = std::fopen(dcount_path.c_str(), "r")) {
                std::fclose(f);
                if (read_dcounts(dcount_path, old, e2))
                    for (size_t i = 0; i < v.size(); ++i) v[i] += old[i];
                else {
                    std::fprintf(stderr, "dspark experts: %s left as it is: %s\n", dcount_path.c_str(), e2.c_str());
                    ok = false;
                }
            }
            if (ok) {
                const std::string tmp = dcount_path + ".tmp";
                if (std::FILE* f = std::fopen(tmp.c_str(), "w")) {
                    std::fprintf(f, "# strata-dsv41 drafter expert picks (DS4_DRAFT_COUNTS), summed over runs\ndims %d %d\n",
                                 g.n_mtp, N);
                    for (int b = 0; b < g.n_mtp; ++b)
                        for (int e = 0; e < N; ++e)
                            std::fprintf(f, "c %d %d %llu\n", b, e, (unsigned long long) v[(size_t) b * N + e]);
                    const bool w = std::fclose(f) == 0;
                    if (w && os::replace_file(tmp, dcount_path))
                        std::fprintf(stderr, "dspark experts: picks added into %s\n", dcount_path.c_str());
                    else std::remove(tmp.c_str());
                }
            }
        }
        if (!dcal_dir.empty()) {
            std::error_code ec;
            std::filesystem::create_directories(dcal_dir, ec);
            int wrote = 0;
            for (int b = 0; b < g.n_mtp; ++b) {
                const std::string p = dcal_dir + "/L" + std::to_string(b);
                std::FILE* f = std::fopen((p + "_gu.f64").c_str(), "wb");
                std::FILE* h = std::fopen((p + "_cnt.u64").c_str(), "wb");
                if (f != nullptr && h != nullptr) {
                    std::fwrite(dcal_gu.data() + (size_t) b * N * g.dim, 8, (size_t) N * g.dim, f);
                    std::fwrite(dcal_cnt.data() + (size_t) b * N, 8, (size_t) N, h);
                    ++wrote;
                }
                if (f != nullptr) std::fclose(f);
                if (h != nullptr) std::fclose(h);
            }
            std::fprintf(stderr, "dspark experts: DS4_DRAFT_CAL: %d blocks' gate / up input sums in %s\n", wrote, dcal_dir.c_str());
        }
    }

    void save_profile() const {
        if (o.profile.empty() || o.profile_readonly) return;   // (--profile-readonly: a test keeps the file it read)
        const std::string tmp = o.profile + ".tmp";
        std::FILE* f = std::fopen(tmp.c_str(), "wb");
        if (f == nullptr) return;
        const bool ok = std::fwrite(prof.data(), 4, prof.size(), f) == prof.size();
        std::fclose(f);
        // (the old profile replaced: std::rename does not replace an existing file on Windows, so there the profile
        // never moved on and only .tmp files were left)
        if (!ok || !os::replace_file(tmp, o.profile)) std::remove(tmp.c_str());
    }

    std::vector<std::string> info_lines() const {
        std::vector<std::string> v;
        int nh = 0;
        for (const Layer& l : L) nh += l.n_exp - l.n_vram;
        char b[512];
        // kv=fp4: DeepSeek's own cache layout (the compressed KV and the index keys FP4, the window FP8)
        std::snprintf(b, sizeof b, "INFO context=%lld kv=fp4 kv_resident=%lld expert_slots=%d engine_kind=ds4 "
                                   "cpu_experts=%d ram_experts=%d engine=ds4-0.1",
                      (long long) o.max_context, (long long) o.max_context, g.nl * g.n_exp - nh, nh, ram_held);
        v.push_back(b);
        if (commit_kept > 0) {   // (Windows, an integrated GPU: the commit kept experts off the GPU - the server says so)
            std::snprintf(b, sizeof b,
                          "NOTE experts: %.0f GB stay off the GPU - Windows' page file is too small to hold them there; "
                          "a page file of %.0f GB keeps them on the GPU (System > About > Advanced system settings > "
                          "Performance > Advanced > Virtual memory), then restart Maya", commit_kept / 1e9, pagefile_hint);
            v.push_back(b);
            std::snprintf(b, sizeof b, "INFO gpu_commit_capped_gb=%.0f pagefile_hint_gb=%.0f", std::ceil(commit_kept / 1e9),
                          pagefile_hint);
            v.push_back(b);
        }
        if (pk.eg_layers > 0) {   // the n-gram memory's (Engram's) table rows a token reads, for the Monitor
            std::snprintf(b, sizeof b, "INFO engram_layers=%d engram_lookups=%d", pk.eg_layers,
                          pk.eg_layers * (pk.eg_ngram - 1) * pk.eg_heads);
            v.push_back(b);
        }
        if (img_tok >= 0) {   // the server's image resize (DeepSeek's image_processor.py)
            std::snprintf(b, sizeof b,
                          "INFO vision=ds4 vision_patch=%d vision_merge=%d vision_min_pixels=%lld vision_max_tokens=%d "
                          "vision_max_wh_ratio=%lld image_token=%d vision_gpu=%d vision_mib=%lld",
                          vg.patch, vg.merge, (long long) pk.num("vision.min_pixels", 0), vg.max_tokens,
                          (long long) pk.num("vision.max_wh_ratio", 0), img_tok, vt.device(),
                          (long long) (vt.device_bytes() >> 20));
            v.push_back(b);
        } else if (!vision_err.empty()) {   // (the server offers no pictures and says why)
            std::string why = vision_err;
            for (char& ch : why)
                if (ch == '\n' || ch == '\r') ch = ' ';
            v.push_back("NOTE images: OFF - the model's vision tower did not load (" + why + ")");
            v.push_back("INFO vision=off");
        }
        return v;
    }
};

Model::Model() : p_(new Impl) {}
